#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// ADS1115 configuration values
#define ADS1115_MODE_SINGLE 0x8000
#define ADS1115_MUX_SINGLE_0 0x4000
#define ADS1115PGA_4_096V 0x0080
#define ADS1115_DR_128SPS 0x0008

// MLX91219 sensitivity (40mV/A)
#define MLX91219_SENSITIVITY 0.040 // 40mV/A

// Zero-current offset (2.5V)
#define ZERO_CURRENT_OFFSET 0.5 // 2.5V - 2V = 0.5V

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Function to write a 16-bit value to an ADS1115 register
int write_ads1115_register(int handle, uint16_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;       // LSB

    int result = i2cWriteI2CBlockData(handle, reg, buf + 1, 2); // Write the value
    if (result != 2) {
        fprintf(stderr, "Error writing to ADS1115 register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from an ADS1115 register
int read_ads1115_register(int handle, uint16_t reg, uint16_t *value) {
    char buf[1];
    buf[0] = reg;

    int result = i2cWriteI2CBlockData(handle, reg, NULL, 0); // Set register to read
    if (result != 0) {
        fprintf(stderr, "Error setting ADS1115 register 0x%02X for read: %d\n", reg, result);
        return -1;
    }

    result = i2cReadI2CBlockData(handle, reg, buf, 2); // Read the value
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 register 0x%02X: %d\n", reg, result);
        return -1;
    }

    *value = (buf[0] << 8) | buf[1]; // Combine MSB and LSB
    return 0;
}

// Function to read the current from the MLX91219 sensor
float read_current() {
    uint16_t config;
    uint16_t convert;
    int16_t raw_value;
    float current;

    // Read the configuration register (optional, but good practice)
    if (read_ads1115_register(i2c_handle, ADS1115_REG_CONFIG, &config) != 0) {
        fprintf(stderr, "Error reading config register\n");
        return -1.0;
    }

    // Read the conversion register
    if (read_ads1115_register(i2c_handle, ADS1115_REG_CONVERT, &convert) != 0) {
        fprintf(stderr, "Error reading conversion register\n");
        return -1.0;
    }

    // Convert the raw value to a signed 16-bit integer
    raw_value = (int16_t)((convert >> 4) & 0x0FFF); // Extract 12-bit value

    // Convert the raw value to a voltage
    float voltage = (float)raw_value * (4.096 / 2048.0); // 4.096V / 2^11

    // Convert the voltage to a current
    current = (voltage - ZERO_CURRENT_OFFSET) / MLX91219_SENSITIVITY;

    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float current = read_current();

        if (current >= 0) {
            printf("Current: %.2f A\n", current);
        } else {
            fprintf(stderr, "Error reading current\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

