#define HEAT_SENSOR_I2C_ADDR 0x48
#define HEAT_SENSOR_I2C_BUS 1
#define HEAT_SENSOR_CHANNEL 0
#define HEAT_SENSOR_THRESHOLD 60.0
#define BUZZER_GPIO 27
#define DEBOUNCE_TIME_MS 50
#define BUZZER_DURATION_S 2
#define LOG_FILE "fire_log.txt"

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;
static time_t last_flame_event = 0;

// Function prototypes
int initialize();
void cleanup();
void signal_handler(int signal);
int read_flame_sensor();
float read_temperature();
void log_event(const char *message);
void activate_buzzer();
void deactivate_buzzer();
void flame_isr(int gpio, int level, uint32_t tick, void *user);

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    i2c_handle = i2cOpen(HEAT_SENSOR_I2C_BUS, HEAT_SENSOR_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for single-shot mode, gain ±4.096V, 128 SPS
    char config[3];
    config[0] = 0x01; // Configuration register address
    config[1] = 0x44; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    config[2] = 0x83; // Start single conversion

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to cleanup resources
void cleanup() {
    running = 0;
    deactivate_buzzer();
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_isr, NULL); // Disable ISR
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to read the temperature from the ADS1115
float read_temperature() {
    char buf[2];
    int16_t raw_value;
    float voltage, temperature;

    // Read the conversion register (0x00)
    if (i2cWriteDevice(i2c_handle, (char[1]){0x00}, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device for temperature read\n");
        return -1.0;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1.0;
    }

    raw_value = (buf[0] << 8) | buf[1];

    // Convert raw value to voltage (assuming +/- 4.096V range)
    voltage = (float)raw_value * 4.096 / 32768.0;

    // Convert voltage to temperature (20°C - 80°C)
    temperature = 20.0 + (voltage - 1.65) * 60.0;

    return temperature;
}

// Function to log events to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    printf("%s: %s\n", timestamp, message);
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1);
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0);
}

// Flame sensor interrupt service routine
void flame_isr(int gpio, int level, uint32_t tick, void *user) {
    time_t now = time(NULL);
    if (difftime(now, last_flame_event) >= DEBOUNCE_TIME_MS / 1000.0) {
        last_flame_event = now;
        log_event("Flame detected!");
        activate_buzzer();
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_detected = read_flame_sensor();
        float temperature = read_temperature();

        if (flame_detected == 0) {
            log_event("Flame detected!");
            activate_buzzer();
        } else {
            log_event("No flame detected.");
        }

        if (temperature > HEAT_SENSOR_THRESHOLD) {
            log_event("Temperature above threshold!");
        } else {
            log_event("Temperature below threshold.");
        }

        if (flame_detected == 0 && temperature > HEAT_SENSOR_THRESHOLD) {
            log_event("Fire condition triggered!");
            activate_buzzer();
            gpioDelay(BUZZER_DURATION_S * 1000000); // Delay for 2 seconds
            deactivate_buzzer();
        }

        gpioDelay(100000); // Poll every 100ms
    }

    cleanup();
    return 0;
}

