#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

// Configuration parameters
#define DEFAULT_SENSITIVITY 0.1  // 100 mV/A
#define DEFAULT_THRESHOLD 5.0    // Amperes
#define DEFAULT_FAN_GPIO 18
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_SPI_SPEED 1000000 // 1 MHz
#define DEFAULT_SPI_MODE 0

// GPIO chip names to try (for Raspberry Pi 5)
const char *gpio_chips[] = { "gpiochip4", "gpiochip0" };
#define NUM_GPIO_CHIPS (sizeof(gpio_chips) / sizeof(gpio_chips[0]))

// Global variables
static int spi_fd = -1;
static int fan_gpio = DEFAULT_FAN_GPIO;
static float sensitivity = DEFAULT_SENSITIVITY;
static float threshold = DEFAULT_THRESHOLD;
static char *spi_device = DEFAULT_SPI_DEVICE;
static int spi_speed = DEFAULT_SPI_SPEED;
static int spi_mode = DEFAULT_SPI_MODE;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
} gpio_t;

// Function prototypes
int spi_init(const char *device, int speed, int mode);
int spi_read_adc(int fd, int channel);
float adc_to_current(int adc_value, float sensitivity);
int gpio_export(int gpio);
int gpio_unexport(int gpio);
int gpio_set_direction(int gpio, const char *direction);
int gpio_write(int gpio, int value);
int gpio_read(int gpio);
int gpio_get_line(gpio_t *gpio);
int gpio_release_line(gpio_t *gpio);
int gpio_set_value(gpio_t *gpio, int value);
void log_current(float current);
void signal_handler(int sig);
int load_configuration(const char *filename);

// Function to load configuration from file
int load_configuration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "sensitivity") == 0) {
            sensitivity = atof(value);
        } else if (strcmp(key, "threshold") == 0) {
            threshold = atof(value);
        } else if (strcmp(key, "fan_gpio") == 0) {
            fan_gpio = atoi(value);
        } else if (strcmp(key, "spi_device") == 0) {
            spi_device = strdup(value); // Duplicate the string to avoid modifying the original
        } else if (strcmp(key, "spi_speed") == 0) {
            spi_speed = atoi(value);
        } else if (strcmp(key, "spi_mode") == 0) {
            spi_mode = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

// SPI initialization function
int spi_init(const char *device, int speed, int mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int ret = ioctl(fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x80 | (channel << 4)) & 0xFF; // Single-ended, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = spi_speed;
    tr.bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value, float sensitivity) {
    float voltage = (adc_value / 1023.0) * 3.3;
    float current = voltage / sensitivity;
    return current;
}

// GPIO export function
int gpio_export(int gpio) {
    int ret = gpiod_chip_open_by_name(gpio_chips[0]);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chips[0], strerror(errno));
        return -1;
    }

    ret = gpiod_chip_get_line(gpio_chips[0], gpio);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio, strerror(errno));
        gpiod_chip_close(gpio_chips[0]);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_chips[0], gpio, "current_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", gpio, strerror(errno));
        gpiod_chip_close(gpio_chips[0]);
        return -1;
    }

    gpiod_chip_close(gpio_chips[0]);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int gpio) {
    int ret = gpiod_chip_open_by_name(gpio_chips[0]);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chips[0], strerror(errno));
        return -1;
    }

    ret = gpiod_chip_get_line(gpio_chips[0], gpio);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio, strerror(errno));
        gpiod_chip_close(gpio_chips[0]);
        return -1;
    }

    ret = gpiod_line_release(gpio_chips[0], gpio);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %s\n", gpio, strerror(errno));
        gpiod_chip_close(gpio_chips[0]);
        return -1;
    }

    gpiod_chip_close(gpio_chips[0]);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int gpio, const char *direction) {
    int ret = gpiod_chip_open_by_name(gpio_chips[0]);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chips[0], strerror(errno));
        return -1;
    }

    ret = gpiod_chip_get_line(gpio_chips[0], gpio);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio, strerror(errno));
        gpiod_chip_close(gpio_chips[0]);
        return -1;
    }

    ret = gpiod_line_set_direction(gpio_chips[0], gpio, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d direction to %s: %s\n", gpio, direction, strerror(errno));
        gpiod_chip_close(gpio_chips[0]);
        return -1;
    }

    gpiod_chip_close(gpio_chips[0]);
    return 0;
}

// GPIO write function
int gpio_write(int gpio, int value) {
    gpio_t gpio_t = {0};
    gpio_t.chip = gpiod_chip_open_by_name(gpio_chips[0]);
    if (gpio_t.chip < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chips[0], strerror(errno));
        return -1;
    }

    gpio_t.line = gpiod_chip_get_line(gpio_t.chip, gpio);
    if (gpio_t.line < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio, strerror(errno));
        gpiod_chip_close(gpio_t.chip);
        return -1;
    }

    int ret = gpiod_line_set_value(gpio_t.chip, gpio_t.line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value to %d: %s\n", gpio, value, strerror(errno));
        gpiod_chip_close(gpio_t.chip);
        return -1;
    }

    gpiod_chip_close(gpio_t.chip);
    return 0;
}

// GPIO read function
int gpio_read(int gpio) {
    gpio_t gpio_t = {0};
    gpio_t.chip = gpiod_chip_open_by_name(gpio_chips[0]);
    if (gpio_t.chip < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chips[0], strerror(errno));
        return -1;
    }

    gpio_t.line = gpiod_chip_get_line(gpio_t.chip, gpio);
    if (gpio_t.line < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio, strerror(errno));
        gpiod_chip_close(gpio_t.chip);
        return -1;
    }

    int ret = gpiod_line_get_value(gpio_t.chip, gpio_t.line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d value: %s\n", gpio, strerror(errno));
        gpiod_chip_close(gpio_t.chip);
        return -1;
    }

    gpiod_chip_close(gpio_t.chip);
    return ret;
}

// GPIO get line function
int gpio_get_line(gpio_t *gpio) {
    *gpio = (gpio_t)malloc(sizeof(struct gpiod_line));
    if (*gpio == NULL) {
        perror("Error allocating GPIO line");
        return -1;
    }

    *gpio->chip = gpiod_chip_open_by_name(gpio_chips[0]);
    if (*gpio->chip < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chips[0], strerror(errno));
        free(*gpio);
        return -1;
    }

    *gpio->line = gpiod_chip_get_line(*gpio->chip, gpio);
    if (*gpio->line < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio, strerror(errno));
        gpiod_chip_close(*gpio->chip);
        free(*gpio);
        return -1;
    }

    return 0;
}

// GPIO release line function
int gpio_release_line(gpio_t *gpio) {
    gpiod_line_release(gpio->chip, gpio->line);
    free(gpio);
    return 0;
}

// GPIO set value function
int gpio_set_value(gpio_t *gpio, int value) {
    int ret = gpiod_line_set_value(gpio->chip, gpio->line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", gpio->line, strerror(errno));
        return -1;
    }
    return 0;
}

// Logging function
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int adc_value;
    float current;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:f:d:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            case 'f':
                fan_gpio = atoi(optarg);
                break;
            case 'd':
                spi_device = strdup(optarg); // Duplicate the string to avoid modifying the original
                break;
            default:
