// Configuration parameters
#define DEFAULT_SENSITIVITY 0.1  // 100 mV/A
#define DEFAULT_THRESHOLD 5.0    // Amperes
#define DEFAULT_FAN_GPIO 18
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_SPI_SPEED 1000000 // 1 MHz
#define DEFAULT_SPI_MODE 0

// GPIO chip names to try (for Raspberry Pi 5)
const char *gpio_chips[] = { "gpiochip4", "gpiochip0" };
#define NUM_GPIO_CHIPS (sizeof(gpio_chips) / sizeof(gpio_chips[0]))

// Global variables
static int spi_fd = -1;
static int fan_gpio = DEFAULT_FAN_GPIO;
