static float threshold = DEFAULT_THRESHOLD;
static char *spi_device = DEFAULT_SPI_DEVICE;
static int spi_speed = DEFAULT_SPI_SPEED;
static int spi_mode = DEFAULT_SPI_MODE;
static FILE *log_file = NULL;
