#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define CO_LOG_FILE "co_log.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_ads1115();
int16_t read_ads1115();
float convert_to_ppm(int16_t raw_value);
int log_ppm(float ppm_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115 for single-ended channel 0, 4.096V range, continuous conversion
int configure_ads1115() {
    // Configuration register value: 0b1000000000000000 (Single-ended AIN0, 4.096V, Continuous)
    uint16_t config_value = 0x4003; // Single-ended AIN0, 4.096V, Continuous conversion
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read 16-bit value from ADS1115 conversion register
int16_t read_ads1115() {
    char buf[1];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device for conversion read: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    return (int16_t)((read_buf[0] << 8) | read_buf[1]);
}

// Convert raw ADC value to CO concentration in PPM using a logarithmic curve
float convert_to_ppm(int16_t raw_value) {
    // Example calibration curve (replace with your sensor's calibration data)
    // This is a placeholder and needs to be calibrated with known CO concentrations
    float ppm = 100.0 * (float)raw_value / 32767.0; // Assuming 16-bit ADC
    return ppm;
}

// Log timestamped CO concentration to file
int log_ppm(float ppm_value) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm_value);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw ADC value
        int16_t raw_value = read_ads1115();
        if (raw_value == -1) {
            fprintf(stderr, "Failed to read ADC value, retrying in %d seconds...\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Convert to PPM
        float ppm_value = convert_to_ppm(raw_value);

        // Log PPM value
        if (log_ppm(ppm_value) != 0) {
            fprintf(stderr, "Failed to log PPM value\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("CO sensor monitoring stopped.\n");
    return 0;
}

