    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set flame sensor pin as input
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);

    printf("Flame sensor and temperature logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to temperature
        float temperature = convert_adc_to_temperature(adc_value);

        // Log data
        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

