#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define SAMPLE_RATE_MS 100
#define REFERENCE_PRESSURE 20e-6 // Pa
#define SENSITIVITY -38.0        // dBV/Pa
#define MAX_RAW_VALUE 32767.0

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mic_data(int i2c_handle, int address);
float convert_to_db(int raw_value);
void log_data(FILE *fp, float avg_db1, float avg_db2);
void signal_handler(int signal);

// Function to read data from the microphone
int read_mic_data(int i2c_handle, int address) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device at address 0x%02X: %d\n", address, result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_value = (int16_t)((buf[0] << 8) | buf[1]);

    // Handle two's complement conversion if necessary
    if (raw_value > 32767) {
        raw_value -= 65536;
    }

    return raw_value;
}

// Function to convert raw data to dB
float convert_to_db(int raw_value) {
    float pressure = (float)raw_value * REFERENCE_PRESSURE / (MAX_RAW_VALUE / 32768.0);
    float db = 20.0 * log10(pressure / (10e-6));
    return db;
}

// Function to log data to a file
void log_data(FILE *fp, float avg_db1, float avg_db2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, avg_db1, avg_db2);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both microphones
    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for microphone 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for microphone 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

