#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1
#define LED_PIN 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 0.7

// Define sampling window duration (ms)
#define WINDOW_DURATION 100

// Define LED on duration (ms)
#define LED_ON_DURATION 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int mic1_rms;
    int mic2_rms;
} MicrophoneData;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    if (spiXfer(spi_handle, spi_data, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on RMS values
void control_led(double mic1_rms, double mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(LED_ON_DURATION * 1000); // Delay for 500ms
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    int mic1_samples[WINDOW_DURATION];
    int mic2_samples[WINDOW_DURATION];
    int mic1_index = 0;
    int mic2_index = 0;

    printf("Sampling audio... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read microphone 1
        int adc_value = read_mcp3008(MIC1_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading mic1, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }
        mic1_samples[mic1_index] = adc_value;
        mic1_index++;

        // Read microphone 2
        adc_value = read_mcp3008(MIC2_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading mic2, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }
        mic2_samples[mic2_index] = adc_value;
        mic2_index++;

        if (mic1_index == WINDOW_DURATION || mic2_index == WINDOW_DURATION) {
            // Calculate RMS values
            double mic1_rms = calculate_rms(mic1_samples, WINDOW_DURATION);
            double mic2_rms = calculate_rms(mic2_samples, WINDOW_DURATION);

            // Log data
            log_data(mic1_rms, mic2_rms);

            // Control LED
            control_led(mic1_rms, mic2_rms);

            // Reset sample buffers
            mic1_index = 0;
            mic2_index = 0;
        }

        gpioDelay(1); // Sample every 1 ms
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

