float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void check_overcurrent(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure the ADS1115
int config_ads1115() {
    // Single-shot mode, A0, +/-4.096V, 128 SPS, disable comparator
    uint16_t config = 0x4003; //0b0100000000000011
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }
    return 0;
}

// Function to read from the ADS1115
int16_t read_ads1115() {
    char buf[1];
    buf[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device for conversion read\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Function to convert raw value to current
float convert_to_current(int16_t raw_value) {
    // Assuming Vref = 4.096V
    float voltage = (float)raw_value * 4.096 / 32768.0;
    float current = voltage / 0.5 * 100.0; // 0.5V to 4.5V for 0-100A
    return current;
}

// Function to check for overcurrent and trigger LED
void check_overcurrent(float average_current) {
    if (average_current > ALERT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
        gpioDelay(1000);       // Wait 1 second
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (config_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize circular buffer
    CircularBuffer current_buffer;
    init_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        int16_t raw_value = read_ads1115();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(raw_value);

        // Add to circular buffer
        add_to_buffer(&current_buffer, current);

        // Calculate average current
        float average_current = calculate_average(&current_buffer);

        // Check for overcurrent
        check_overcurrent(average_current);

        // Print current reading
        printf("Current: %.2f A\n", average_current);

        // Delay for sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

