// TCS34725 I2C address
#define TCS34725_ADDR 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init();
int tcs34725_read_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue);
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the TCS34725 sensor
int tcs34725_init() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }
    if (sensor_id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure the sensor
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) { // Power on and enable ADC
        fprintf(stderr, "Failed to write to ENABLE register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }
    gpioDelay(3); // Wait for power-on

    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01) < 0) { // Set gain to 4x
        fprintf(stderr, "Failed to write to CONTROL register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xFF) < 0) { // Set integration time to 2.4ms
        fprintf(stderr, "Failed to write to ATIME register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read color data from the sensor
int tcs34725_read_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    int retries = 0;
    int status;

    while (retries < 3) {
        status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
        if (status >= 0) {
            *clear = (unsigned int)status;
        } else {
            fprintf(stderr, "I2C read error (clear): %d, retry %d\n", status, retries + 1);
            retries++;
            gpioDelay(1); // Small delay before retrying
        }

        status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
        if (status >= 0) {
            *red = (unsigned int)status;
        } else {
            fprintf(stderr, "I2C read error (red): %d, retry %d\n", status, retries + 1);
            retries++;
            gpioDelay(1);
        }

        status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
        if (status >= 0) {
            *green = (unsigned int)status;
        } else {
            fprintf(stderr, "I2C read error (green): %d, retry %d\n", status, retries + 1);
            retries++;
            gpioDelay(1);
        }

        status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
        if (status >= 0) {
            *blue = (unsigned int)status;
        } else {
            fprintf(stderr, "I2C read error (blue): %d, retry %d\n", status, retries + 1);
            retries++;
            gpioDelay(1);
        }
    }

    if (retries == 3) {
        fprintf(stderr, "Failed to read color data after 3 retries\n");
        return -1;
    }

    return 0;
}

// Log data to CSV file
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensor
    if (tcs34725_init() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        unsigned int clear, red, green, blue;

        if (tcs34725_read_data(&clear, &red, &green, &blue) == 0) {
            if (log_data(clear, red, green, blue) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

