#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define VREF 3.3 // Reference voltage for MCP3008
#define SENSITIVITY 0.1 // Sensor sensitivity in V/A
#define OFFSET 0.05 // Sensor offset in V

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *motor_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
int log_current(float current);
int control_motor_shutdown(int enable);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Function to log current reading to file
int log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("current_log.csv", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "Timestamp,Current (A)\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to control motor shutdown
int control_motor_shutdown(int enable) {
    int ret = 0;
    if (enable) {
        ret = gpiod_line_set_value(motor_line, 1); // HIGH
    } else {
        ret = gpiod_line_set_value(motor_line, 0); // LOW
    }
    if (ret < 0) {
        perror("Error setting motor shutdown pin");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (motor_line != NULL) {
        gpiod_line_release(motor_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    motor_line = gpiod_chip_get_line(gpio_chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_line) {
        perror("Error getting motor shutdown line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(motor_line, "motor_shutdown", 0) < 0) {
        perror("Error requesting motor shutdown line as output");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log current reading
        if (log_current(current) < 0) {
            fprintf(stderr, "Error logging current reading\n");
        }

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            fprintf(stderr, "Overcurrent detected: %.2fA\n", current);
            if (control_motor_shutdown(0) < 0) { // Disable motor
                fprintf(stderr, "Error disabling motor shutdown\n");
            }
            sleep(1); // Wait for 1 second
            if (control_motor_shutdown(1) < 0) { // Re-enable motor
                fprintf(stderr, "Error re-enabling motor shutdown\n");
            }
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

