    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from the sensor
int read_pressure(int handle, int *raw_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure data from register 0x%02X: %d\n", PRESSURE_REG, result);
        return -1;
    }

    *raw_value = (buf[0] << 7) | (buf[1] >> 0); // Combine the two bytes into a 16-bit value
    return 0;
}

// Convert raw value to kPa
float convert_to_kPa(int raw_value) {
    return (float)raw_value / 65535.0 * 500.0;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(const char *timestamp, float pressure_kPa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int raw_value;
        if (read_pressure(i2c_handle, &raw_value) == 0) {
            float pressure_kPa = convert_to_kPa(raw_value);
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (log_data(timestamp, pressure_kPa) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
        } else {
            fprintf(stderr, "Error reading pressure, skipping log.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

