#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// Constants
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_FIFO 0x02
#define ADS1115_REG_DEVICE_ID 0x03

#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_ads1115();
int16_t read_ads1115(int16_t channel);
float adc_to_voltage(int16_t adc_value);
float voltage_to_pressure(float voltage);
float voltage_to_temperature(float voltage);
void display_data(float pressure, float temperature);
void control_led(float pressure);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int16_t pressure_channel;
    int16_t temperature_channel;
    int16_t gain;
    int16_t data_rate;
} ads1115_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the ADS1115
int config_ads1115() {
    // Single-shot mode, AIN0 and AIN1, +/-6.144V, 128 SPS, Gain 2/3
    uint16_t config_value = 0x4083; //0b0100000010000011
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read data from the ADS1115
int16_t read_ads1115(int16_t channel) {
    char buf[1];
    char read_buf[2];
    int result;

    // Set the channel to read
    buf[0] = ADS1115_REG_CONVERT;
    if (channel == 0) {
        buf[1] = 0x4003; // AIN0 single-ended
    } else if (channel == 1) {
        buf[1] = 0x4013; // AIN1 single-ended
    } else {
        fprintf(stderr, "Invalid channel number: %d\n", channel);
        return -1;
    }

    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write conversion register: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read conversion register: %d\n", result);
        return -1;
    }

    return (read_buf[0] << 8) | read_buf[1];
}

// Convert ADC value to voltage
float adc_to_voltage(int16_t adc_value) {
    // ADS1115 is a 16-bit ADC with a 6.144V full-scale range
    // and a gain of 2/3.
    float voltage = (adc_value / 32767.0) * 6.144 * 2.0 / 3.0;
    return voltage;
}

// Convert voltage to pressure using linear transfer function
float voltage_to_pressure(float voltage) {
    return (voltage / 5.0) * 400.0;
}

// Convert voltage to temperature using simplified linear NTC approximation
float voltage_to_temperature(float voltage) {
    return (voltage - 1.0) * 100.0;
}

// Display pressure and temperature data
void display_data(float pressure, float temperature) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
}

// Control the warning LED based on pressure
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure ADS1115
    if (config_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int16_t adc_pressure = read_ads1115(0); // AIN0
        int16_t adc_temperature = read_ads1115(1); // AIN1

        if (adc_pressure == -1 || adc_temperature == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltage
        float voltage_pressure = adc_to_voltage(adc_pressure);
        float voltage_temperature = adc_to_voltage(adc_temperature);

        // Convert voltage to pressure and temperature
        float pressure = voltage_to_pressure(voltage_pressure);
        float temperature = voltage_to_temperature(voltage_temperature);

        // Display data
        display_data(pressure, temperature);

        // Control LED
        control_led(pressure);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

