#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define VREF 3.3 // Reference voltage for MCP3008
#define MLX91209_SENSITIVITY 66.0 // mV/A
#define MLX91209_VCC 3.3 // Sensor supply voltage
#define MLX91209_VCC_DIV 2.0 // Zero-current midpoint voltage
#define OVERCURRENT_GPIO 27
#define OVERCURRENT_THRESHOLD 10.0 // Amperes

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void handle_overcurrent(float current);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Dummy byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - MLX91209_VCC_DIV) / (MLX91209_SENSITIVITY / 1000.0);
}

// Function to log current to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.3f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle overcurrent condition
void handle_overcurrent(float current) {
    printf("OVERCURRENT DETECTED: %.3f A\n", current);
    gpioWrite(OVERCURRENT_GPIO, 1); // Set GPIO HIGH
    fprintf(log_file, "OVERCURRENT EVENT\n");
    fflush(log_file);
    program_running = 0; // Stop the program
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0; // Stop the main loop

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(OVERCURRENT_GPIO, 0); // Reset GPIO to LOW
    gpioTerminate(); // Terminate pigpio

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(OVERCURRENT_GPIO, PI_OUTPUT);
    gpioWrite(OVERCURRENT_GPIO, 0); // Initialize to LOW

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log current
        log_current(current);

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            handle_overcurrent(current);
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(OVERCURRENT_GPIO, 0);
    gpioTerminate();

    return 0;
}

