#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define FULL_SCALE_RANGE 4.096 // +/- 4.096V
#define OFFSET 0.5 // Offset voltage at 0 kPa
#define SENSITIVITY 0.1 // Sensitivity in V/kPa
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int16_t read_adc();
float adc_to_voltage(int16_t adc_value);
float voltage_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    char log_file[64];
} config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, 128 SPS
    // OS = 0x01, MUX = 0x00, PGA = 0x00, MODE = 0x00, DR = 0x00, COMP_MODE = 0x00, COMP_POL = 0x00, COMP_LAT = 0x00
    uint16_t config = 0x4083; //0b0100000010000011
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc() {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADC value: %d\n", i2c_handle);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Convert ADC value to voltage
float adc_to_voltage(int16_t adc_value) {
    return ((float)adc_value / 32767.0) * FULL_SCALE_RANGE;
}

// Convert voltage to pressure
float voltage_to_pressure(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Log pressure reading to file
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Pressure sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t adc_value = read_adc();
        if (adc_value >= 0) {
            float voltage = adc_to_voltage(adc_value);
            float pressure = voltage_to_pressure(voltage);

            if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure reading.\n");
                }
            } else {
                fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        gpioDelay(1000); // 1 Hz sampling rate
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

