    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Humidity Alert\n\nTimestamp: %s\nHumidity: %.2f%%\" | ssmtp -s \"Humidity Alert\" %s", timestamp, humidity, EMAIL_RECIPIENT);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error sending email\n");
    } else {
        printf("Email alert sent\n");
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    printf("Humidity and Temperature Monitoring Started...\n");

    while (!terminate) {
        int humidity_adc = read_mcp3208(MCP3208_CHANNEL);
        int thermistor_adc = read_mcp3208(MCP3208_CHANNEL_1);

        if (humidity_adc == -1 || thermistor_adc == -1) {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(thermistor_adc);

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        log_data(humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        sleep(5);
    }

    cleanup();
    printf("Humidity and Temperature Monitoring Stopped.\n");
    return 0;
}

