#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CS_PIN 8 // GPIO8 (gpiochip4)
#define VREF 3.3
#define TMP36_MIN_VOLTAGE 0.1
#define TMP36_MAX_VOLTAGE 1.7
#define TMP36_MIN_TEMPERATURE -40.0
#define TMP36_MAX_TEMPERATURE 125.0

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_temperature(float voltage);
int log_temperature(float temperature);
void signal_handler(int sig);
int gpio_init(void);
int gpio_set_cs_low(void);
int gpio_set_cs_high(void);
int gpio_set_cs_active_high(void);
int gpio_set_cs_inactive_low(void);
void cleanup(void);

// Function to initialize GPIO
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, MCP3208_CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "temperature_sensor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to set CS line low
int gpio_set_cs_low(void) {
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS line low");
        return -1;
    }
    return 0;
}

// Function to set CS line high
int gpio_set_cs_high(void) {
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS line high");
        return -1;
    }
    return 0;
}

// Function to set CS line active high
int gpio_set_cs_active_high(void) {
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS line active high");
        return -1;
    }
    return 0;
}

// Function to set CS line inactive low
int gpio_set_cs_inactive_low(void) {
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS line inactive low");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to transfer data via SPI
int spi_transfer(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct the SPI message to send to the MCP3208
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (write(spi_fd, tx_buf, 3) != 3) {
        perror("Error writing to SPI device");
        return -1;
    }

    if (read(spi_fd, rx_buf, 3) != 3) {
        perror("Error reading from SPI device");
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 4095.0) * VREF;
}

// Function to convert voltage to temperature (Celsius)
float voltage_to_temperature(float voltage) {
    return (voltage - 0.5) / 0.01;
}

// Function to log temperature to a file
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("temperature_log.csv", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "Timestamp,Temperature_Celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Set CS line active high
        if (gpio_set_cs_active_high() < 0) {
            fprintf(stderr, "Failed to set CS line active high. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Read ADC value from channel 0
        int adc_value = spi_transfer(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate ADC reading
        if (adc_value < 0 || adc_value > 4095) {
            fprintf(stderr, "Invalid ADC value: %d. Skipping.\n", adc_value);
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Validate voltage
        if (voltage < TMP36_MIN_VOLTAGE || voltage > TMP36_MAX_VOLTAGE) {
            fprintf(stderr, "Voltage out of range: %.2f V. Skipping.\n", voltage);
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert voltage to temperature
        float temperature = voltage_to_temperature(voltage);

        // Log temperature
        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Failed to log temperature.\n");
        }

        // Set CS line inactive low
        if (gpio_set_cs_inactive_low() < 0) {
            fprintf(stderr, "Failed to set CS line inactive low. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

