#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define LOG_FILE "impact_log.txt"
#define SAMPLE_RATE 100 // Hz
#define NUM_SAMPLES 10 // Number of samples for magnitude calculation

// ADXL335 Calibration
#define SUPPLY_VOLTAGE 3.3
#define ZERO_G_VOLTAGE 1.65
#define SENSITIVITY 300.0 // mV/g

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
accelerometer_data_t read_accelerometer();
double calculate_magnitude(accelerometer_data_t data);
void log_data(accelerometer_data_t data, double magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Read accelerometer data from MCP3008 channels 0, 1, and 2
accelerometer_data_t read_accelerometer() {
    accelerometer_data_t data;
    data.x = read_mcp3008(0);
    data.y = read_mcp3008(1);
    data.z = read_mcp3008(2);
    return data;
}

// Calculate acceleration magnitude in g
double calculate_magnitude(accelerometer_data_t data) {
    double x_g = (double)data.x / 1023.0 * SUPPLY_VOLTAGE / ZERO_G_VOLTAGE * 1000.0 / SENSITIVITY;
    double y_g = (double)data.y / 1023.0 * SUPPLY_VOLTAGE / ZERO_G_VOLTAGE * 1000.0 / SENSITIVITY;
    double z_g = (double)data.z / 1023.0 * SUPPLY_VOLTAGE / ZERO_G_VOLTAGE * 1000.0 / SENSITIVITY;

    double magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
    return magnitude;
}

// Log data to file
void log_data(accelerometer_data_t data, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.4f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Accelerometer data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        accelerometer_data_t data = read_accelerometer();
        double magnitude = calculate_magnitude(data);

        log_data(data, magnitude);

        // Impact detection
        if (magnitude > 2.0) {
            printf("IMPACT DETECTED: Magnitude = %.4f g\n", magnitude);
            fprintf(log_file, "IMPACT DETECTED: Magnitude = %.4f g\n", magnitude);
            fflush(log_file);
        }

        gpioDelay(1000000 / SAMPLE_RATE); // Delay to achieve desired sample rate
    }

    cleanup();
    return 0;
}

