#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel connected to the sensor
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
float convert_to_flow_rate(int adc_value);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    float flow_min;
    float flow_max;
    char *log_file;
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_BAUD,
    MCP3008_CHANNEL,
    FLOW_MIN,
    FLOW_MAX,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_adc(config.mcp3008_channel);
        if (adc_value >= 0) {
            float flow_rate = convert_to_flow_rate(adc_value);
            if (flow_rate >= config.flow_min && flow_rate <= config.flow_max) {
                log_data(flow_rate);
            } else {
                fprintf(stderr, "Error: Flow rate out of range: %.2f L/min\n", flow_rate);
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended + channel
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
