#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASURE_CMD 0x6845
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration parameters (example values, replace with actual sensor calibration data)
const float T0 = 25.0; // Temperature offset
const float P0 = 101325.0; // Pressure offset
const float T1 = 0.01; // Temperature sensitivity
const float P1 = 0.01; // Pressure sensitivity
const float T2 = 0.0001; // Temperature quadratic term
const float P2 = 0.0001; // Pressure quadratic term

// Function prototypes
int i2c_setup(int bus, int address);
int i2c_write(int fd, uint16_t command);
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len);
int read_sensor_data(int fd, float *temperature, float *pressure);
void convert_data(uint16_t raw_pressure, uint16_t raw_temperature, float *temperature, float *pressure);
void log_data(float temperature, float pressure);
void signal_handler(int signal);
void cleanup();

// I2C setup function
int i2c_setup(int bus, int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address to I2C device");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    uint16_t raw_pressure, raw_temperature;

    if (i2c_write(fd, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error sending measurement command.\n");
        return -1;
    }

    gpioDelay(20); // Wait for conversion (adjust as needed)

    if (i2c_read(fd, 0x00, data, 6) < 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return -1;
    }

    raw_pressure = (data[0] << 8) | data[1];
    raw_temperature = (data[3] << 8) | data[4];

    convert_data(raw_pressure, raw_temperature, temperature, pressure);

    return 0;
}

// Convert raw data to temperature and pressure
void convert_data(uint16_t raw_pressure, uint16_t raw_temperature, float *temperature, float *pressure) {
    float temp = T0 + T1 * raw_temperature + T2 * (raw_temperature * raw_temperature);
    float pres = P0 + P1 * raw_pressure + P2 * (raw_pressure * raw_pressure);

    *temperature = temp;
    *pressure = pres;
}

// Log data to CSV file
void log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(csv_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Temperature(C),Pressure(Pa)\n");
    }

    // I2C setup
    i2c_fd = i2c_setup(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    float temperature, pressure;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &temperature, &pressure) == 0) {
            log_data(temperature, pressure);
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

