#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1

// Define GPIO pins for MCP3008
#define MCP3008_CS 8

// Define command-line argument for gain
#define GAIN_ARG "gain"

// Global variables
int spi_handle;
int gain = 1; // Default gain
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int16_t adc_to_audio(int adc_value);
int16_t noise_cancellation(int16_t mic1_audio, int16_t mic2_audio);
void signal_handler(int signal);

// Signal handler for clean exit
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to audio data (simulated)
int16_t adc_to_audio(int adc_value) {
    // Simulate audio data based on ADC value
    // This is a placeholder; replace with actual audio processing
    // For example, you could use a lookup table or a more complex algorithm
    return (int16_t)(adc_value * gain); // Scale ADC value by gain
}

// Function to perform noise cancellation
int16_t noise_cancellation(int16_t mic1_audio, int16_t mic2_audio) {
    return mic1_audio - mic2_audio;
}

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Parse command-line argument for gain
    if (argc > 1) {
        char *endptr;
        long gain_value = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || gain_value <= 0) {
            fprintf(stderr, "Error: Invalid gain value. Using default gain of 1.\n");
            gain = 1;
        } else {
            gain = (int)gain_value;
            printf("Using gain: %d\n", gain);
        }
    }

    // Configure SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set MCP3008 CS pin as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from microphones
        int adc_value_0 = read_mcp3008(MCP3008_CHANNEL_0);
        int adc_value_1 = read_mcp3008(MCP3008_CHANNEL_1);

        if (adc_value_0 == -1 || adc_value_1 == -1) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to audio data
        int16_t mic1_audio = adc_to_audio(adc_value_0);
        int16_t mic2_audio = adc_to_audio(adc_value_1);

        // Perform noise cancellation
        int16_t noise_canceled_audio = noise_cancellation(mic1_audio, mic2_audio);

        // Output data to terminal in CSV format
        printf("%d,%d,%d\n", mic1_audio, mic2_audio, noise_canceled_audio);

        // Delay for a short period
        gpioDelay(10); // 10 ms delay
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

