#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 1.0
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_temperature(float voltage, float temperature);
int read_ambient_temperature(float *temperature);
int log_data(FILE *fp, int raw_adc, float voltage, float temperature, int flame_detected);
int control_buzzer(int flame_detected);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

// Function to convert voltage to temperature (Celsius)
float voltage_to_temperature(float voltage, float temperature) {
    return voltage + (temperature - 25.0) * 0.001;
}

// Function to read ambient temperature from file
int read_ambient_temperature(float *temperature) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening ambient temperature file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading ambient temperature from file");
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "%f", temperature) != 1) {
        fprintf(stderr, "Invalid ambient temperature format in file. Using default value.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to log data to file
int log_data(FILE *fp, int raw_adc, float voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%.3f,%.3f,%.3f,%d\n", timestamp, raw_adc, voltage, temperature, flame_detected);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Function to control the buzzer
int control_buzzer(int flame_detected) {
    if (flame_detected) {
        if (gpiod_line_set_value(buzzer_line, 1) < 0) {
            perror("Error setting buzzer ON");
            return -1;
        }
    } else {
        if (gpiod_line_set_value(buzzer_line, 0) < 0) {
            perror("Error setting buzzer OFF");
            return -1;
        }
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0); // Ensure buzzer is off
        gpiod_line_release(buzzer_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        cleanup();
        return 1;
    }

    // Request buzzer line for output
    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        perror("Error requesting buzzer line for output");
        cleanup();
        return 1;
    }

    float ambient_temperature;
    int raw_adc, voltage, compensated_voltage;
    int flame_detected;

    // Main loop
    while (!terminate) {
        // Read ADC value
        raw_adc = read_mcp3008(MCP3008_CHANNEL);
        if (raw_adc < 0) {
            fprintf(stderr, "Error reading ADC value. Skipping iteration.\n");
            continue; // Skip to the next iteration
        }

        // Check for invalid ADC value
        int retries = 0;
        while (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Invalid ADC value: %d. Retrying...\n", raw_adc);
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            raw_adc = read_mcp3008(MCP3008_CHANNEL);
            if (raw_adc < 0) {
                fprintf(stderr, "Error reading ADC value during retry. Skipping iteration.\n");
                break; // Exit retry loop if error persists
            }
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Skipping iteration.\n");
                break;
            }
        }

        // Read ambient temperature
        if (read_ambient_temperature(&ambient_temperature) < 0) {
            ambient_temperature = 25.0; // Use default temperature
        }

        // Convert ADC value to voltage
        voltage = adc_to_voltage(raw_adc);

        // Convert voltage to temperature
        temperature = voltage_to_temperature(voltage, ambient_temperature);

        // Calculate compensated voltage
        compensated_voltage = voltage + (temperature - 25.0) * 0.001;

        // Flame detection
        flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

        // Log data
        if (log_data(log_file, raw_adc, voltage, temperature, flame_detected) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Control buzzer
        if (control_buzzer(flame_detected) < 0) {
            fprintf(stderr, "Error controlling buzzer.\n");
        }

        // Wait for 500ms
        usleep(500000); // 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

