            return -1;
        }
    } else {
        if (gpiod_line_set_value(buzzer_line, 0) < 0) {
            perror("Error setting buzzer OFF");
            return -1;
        }
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0); // Ensure buzzer is off
        gpiod_line_release(buzzer_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        cleanup();
        return 1;
    }

    // Request buzzer line for output
    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        perror("Error requesting buzzer line for output");
        cleanup();
        return 1;
    }

    float ambient_temperature;
    int raw_adc, voltage, compensated_voltage;
    int flame_detected;

    // Main loop
    while (!terminate) {
        // Read ADC value
        raw_adc = read_mcp3008(MCP3008_CHANNEL);
        if (raw_adc < 0) {
            fprintf(stderr, "Error reading ADC value. Skipping iteration.\n");
            continue; // Skip to the next iteration
        }

        // Check for invalid ADC value
        int retries = 0;
        while (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Invalid ADC value: %d. Retrying...\n", raw_adc);
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            raw_adc = read_mcp3008(MCP3008_CHANNEL);
            if (raw_adc < 0) {
                fprintf(stderr, "Error reading ADC value during retry. Skipping iteration.\n");
                break; // Exit retry loop if error persists
            }
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Skipping iteration.\n");
                break;
            }
        }

        // Read ambient temperature
        if (read_ambient_temperature(&ambient_temperature) < 0) {
            ambient_temperature = 25.0; // Use default temperature
        }

        // Convert ADC value to voltage
        voltage = adc_to_voltage(raw_adc);

        // Convert voltage to temperature
        temperature = voltage_to_temperature(voltage, ambient_temperature);

        // Calculate compensated voltage
        compensated_voltage = voltage + (temperature - 25.0) * 0.001;

        // Flame detection
        flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

        // Log data
        if (log_data(log_file, raw_adc, voltage, temperature, flame_detected) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Control buzzer
        if (control_buzzer(flame_detected) < 0) {
            fprintf(stderr, "Error controlling buzzer.\n");
        }

        // Wait for 500ms
        usleep(500000); // 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

