    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read water level from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(100); // Small delay to prevent flooding the console with errors
            continue; // Skip to the next iteration
        }

        // Convert ADC value to percentage
        float water_level = convert_to_percentage(adc_value);
        if (water_level < 0.0) {
            fprintf(stderr, "Error: Failed to convert ADC value to percentage\n");
            gpioDelay(100);
            continue;
        }

        // Control the LED
        control_led(water_level);

        // Log the data
        log_data(water_level);

        // Wait for 5 seconds
        gpioDelay(5000); // 5000 milliseconds = 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

