        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created (empty) and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlowRate (LPM)\n");
    }
    rewind(log_file);

    return 0;
}

