#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define SPI device and chip select pin
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_CHIP_SELECT 8 // CE0

// Define GPIO chip and line for chip select
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8

// Define dry and wet calibration ADC values
#define DRY_ADC_VALUE 700
#define WET_ADC_VALUE 300

// Define SPI clock frequency
#define SPI_CLOCK_FREQUENCY 1000000 // 1 MHz

// Global variable to store the SPI file descriptor
int spi_fd = -1;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void signal_handler(int signal);

// Structure to hold GPIO configuration
struct gpiod_line_config {
    struct gpiod_line_config chip_config;
    struct gpiod_line_config line_config;
};

// Function to initialize the SPI interface
int spi_init(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_config chip_config, line_config;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Configure the chip
    chip_config.chip_config.name = "gpiochip" + (chip->number - 1);
    chip_config.chip_config.line_count = 0;
    chip_config.chip_config.requested_chip_flags = 0;

    // Configure the chip
    if (gpiod_chip_request(chip, &chip_config, 0) < 0) {
        perror("Error requesting GPIO chip");
        gpiod_chip_close(chip);
        return -1;
    }

    // Open the GPIO line for the chip select pin
    line = gpiod_chip_get_line(chip, SPI_CHIP_SELECT);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure the GPIO line as output
    line_config.line_config.consumer = "soil_moisture_sensor";
    line_config.line_config.consumer_data = NULL;
    line_config.line_config.requested_line_flags = 0;

    if (gpiod_line_request(line, &line_config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure the GPIO line as output
    if (gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Error setting GPIO line direction");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    // Set the initial state of the GPIO line (low)
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    // Open the SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct gpiod_line_config chip_config, line_config;
    struct gpiod_line *line;
    int adc_value;

    // Configure the chip and line
    chip_config.chip_config.name = "gpiochip" + (chip->number - 1);
    chip_config.chip_config.line_count = 0;
    chip_config.chip_config.requested_chip_flags = 0;

    line = gpiod_chip_get_line(chip, SPI_CHIP_SELECT);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    line_config.line_config.consumer = "soil_moisture_sensor";
    line_config.line_config.consumer_data = NULL;
    line_config.line_config.requested_line_flags = 0;

    if (gpiod_line_request(line, &line_config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        return -1;
    }

    // Configure the GPIO line as output
    if (gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Error setting GPIO line direction");
        gpiod_line_release(line);
        return -1;
    }

    // Set the initial state of the GPIO line (low)
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    // Build the SPI command (single-ended conversion)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Transfer the data
    if (write(spi_fd, tx_buf, 3) != 3) {
        perror("Error writing to SPI device");
        gpiod_line_release(line);
        return -1;
    }

    // Read the response
    if (read(spi_fd, rx_buf, 3) != 3) {
        perror("Error reading from SPI device");
        gpiod_line_release(line);
        return -1;
    }

    // Extract the ADC value
    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Configure the chip and line
    chip_config.chip_config.name = "gpiochip" + (chip->number - 1);
    chip_config.chip_config.line_count = 0;
    chip_config.chip_config.requested_chip_flags = 0;

    line = gpiod_chip_get_line(chip, SPI_CHIP_SELECT);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    line_config.line_config.consumer = "soil_moisture_sensor";
    line_config.line_config.consumer_data = NULL;
    line_config.line_config.requested_line_flags = 0;

    if (gpiod_line_request(line, &line_config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        return -1;
    }

    // Configure the GPIO line as output
    if (gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Error setting GPIO line direction");
        gpiod_line_release(line);
        return -1;
    }

    // Set the initial state of the GPIO line (low)
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    return adc_value;
}

// Function to calculate the moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float moisture_percentage = 100.0 * (adc_value - WET_ADC_VALUE) / (DRY_ADC_VALUE - WET_ADC_VALUE);

    // Clamp the percentage between 0 and 100
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }

    return moisture_percentage;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open_by_name(GPIO_CHIP), SPI_CHIP_SELECT));
    gpiod_chip_close(gpiod_chip_open_by_name(GPIO_CHIP));
    exit(0);
}

int main(void) {
    int adc_value;
    float moisture_percentage;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the SPI interface
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ADC value from channel 0
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate the moisture percentage
        moisture_percentage = calculate_moisture_percentage(adc_value);

        // Print the raw ADC value and moisture percentage
        printf("Raw ADC Value: %d, Moisture Percentage: %.2f%%\n", adc_value, moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

