#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define READ_INTERVAL_SEC 5
#define SPI_RETRY_COUNT 3
#define SPI_RETRY_DELAY_MS 10

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_ce0_line = NULL;
static struct gpiod_line *gpio_sclk_line = NULL;
static struct gpiod_line *gpio_mosi_line = NULL;
static struct gpiod_line *gpio_miso_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float adc_to_moisture_percentage(int adc_value);
void log_moisture_reading(float moisture_percentage);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure chip select line as output
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    gpio_ce0_line = gpiod_chip_get_line(gpio_chip, "ce0");
    if (!gpio_ce0_line) {
        fprintf(stderr, "Error getting CE0 line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    gpio_ce0_line->direction = GPIOD_LINE_DIRECTION_OUTPUT;
    if (gpiod_line_set_value(gpio_ce0_line, 0) == -1) {
        fprintf(stderr, "Error setting CE0 low: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    gpio_sclk_line = gpiod_chip_get_line(gpio_chip, "sclk");
    if (!gpio_sclk_line) {
        fprintf(stderr, "Error getting SCLK line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    gpio_mosi_line = gpiod_chip_get_line(gpio_chip, "mosi");
    if (!gpio_mosi_line) {
        fprintf(stderr, "Error getting MOSI line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    gpio_miso_line = gpiod_chip_get_line(gpio_chip, "miso");
    if (!gpio_miso_line) {
        fprintf(stderr, "Error getting MISO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    gpio_mosi_line->direction = GPIOD_LINE_DIRECTION_OUTPUT;
    gpio_miso_line->direction = GPIOD_LINE_DIRECTION_INPUT;

    return 0;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct gpiod_line *ce_line = NULL;
    struct gpiod_line *sclk_line = NULL;
    struct gpiod_line *mosi_line = NULL;
    struct gpiod_line *miso_line = NULL;

    ce_line = gpiod_chip_get_line(gpio_chip, "ce0");
    sclk_line = gpiod_chip_get_line(gpio_chip, "sclk");
    mosi_line = gpiod_chip_get_line(gpio_chip, "mosi");
    miso_line = gpiod_chip_get_line(gpio_chip, "miso");

    if (!ce_line || !sclk_line || !mosi_line || !miso_line) {
        fprintf(stderr, "Error getting GPIO lines for SPI communication.\n");
        cleanup();
        return -1;
    }

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    for (int i = 0; i < SPI_RETRY_COUNT; ++i) {
        if (gpiod_line_set_value(ce_line, 1) == -1) {
            fprintf(stderr, "Error setting CE high: %s\n", strerror(errno));
            goto retry;
        }

        for (int j = 0; j < 3; ++j) {
            if (gpiod_line_set_value(sclk_line, 1) == -1) {
                fprintf(stderr, "Error setting SCLK high: %s\n", strerror(errno));
                goto retry;
            }
            if (gpiod_line_set_value(mosi_line, tx_buf[j] & 0x01) == -1) {
                fprintf(stderr, "Error setting MOSI high: %s\n", strerror(errno));
                goto retry;
            }
            if (gpiod_line_set_value(miso_line, 0) == -1) {
                fprintf(stderr, "Error setting MISO low: %s\n", strerror(errno));
                goto retry;
            }
            if (gpiod_line_set_value(sclk_line, 0) == -1) {
                fprintf(stderr, "Error setting SCLK low: %s\n", strerror(errno));
                goto retry;
            }
        }

        if (gpiod_line_set_value(ce_line, 0) == -1) {
            fprintf(stderr, "Error setting CE low: %s\n", strerror(errno));
            goto retry;
        }

        // Read the received data
        for (int j = 0; j < 3; ++j) {
            if (gpiod_line_set_value(sclk_line, 1) == -1) {
                fprintf(stderr, "Error setting SCLK high: %s\n", strerror(errno));
                goto retry;
            }
            if (gpiod_line_get_value(miso_line) & (1 << (2 - j))) {
                rx_buf[j] |= (1 << (2 - j));
            }
            if (gpiod_line_set_value(sclk_line, 0) == -1) {
                fprintf(stderr, "Error setting SCLK low: %s\n", strerror(errno));
                goto retry;
            }
        }

        // Combine the received bytes into a 10-bit value
        int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

        goto cleanup;
        break;
    }

    retry:
        usleep(SPI_RETRY_DELAY_MS * 1000); // Exponential backoff
    }

cleanup:
    if (gpiod_line_set_value(ce_line, 0) == -1) {
        fprintf(stderr, "Error setting CE low: %s\n", strerror(errno));
    }
    if (gpiod_line_set_value(sclk_line, 0) == -1) {
        fprintf(stderr, "Error setting SCLK low: %s\n", strerror(errno));
    }
    if (gpiod_line_set_value(mosi_line, 0) == -1) {
        fprintf(stderr, "Error setting MOSI low: %s\n", strerror(errno));
    }
    if (gpiod_line_set_value(miso_line, 0) == -1) {
        fprintf(stderr, "Error setting MISO low: %s\n", strerror(errno));
    }

    return adc_value;
}

// Convert ADC value to moisture percentage
float adc_to_moisture_percentage(int adc_value) {
    if (adc_value < 0) return 0.0;
    if (adc_value > 1023) return 100.0;
    return 100.0 - ((float)(adc_value - MIN_ADC_VALUE) / (float)(MAX_ADC_VALUE - MIN_ADC_VALUE)) * 100.0;
}

// Log moisture reading with timestamp
void log_moisture_reading(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Moisture: %.2f%%\n", timestamp, moisture_percentage);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (gpio_ce0_line) {
        gpiod_line_release(gpio_ce0_line);
    }
    if (gpio_sclk_line) {
        gpiod_line_release(gpio_sclk_line);
    }
    if (gpio_mosi_line) {
        gpiod_line_release(gpio_mosi_line);
    }
    if (gpio_miso_line) {
        gpiod_line_release(gpio_miso_line);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            float moisture_percentage = adc_to_moisture_percentage(adc_value);
            log_moisture_reading(moisture_percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", READ_INTERVAL_SEC);
        }

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

