    miso_line = gpiod_chip_get_line(gpio_chip, "miso");

    if (!ce_line || !sclk_line || !mosi_line || !miso_line) {
        fprintf(stderr, "Error getting GPIO lines for SPI communication.\n");
        cleanup();
        return -1;
    }

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    for (int i = 0; i < SPI_RETRY_COUNT; ++i) {
        if (gpiod_line_set_value(ce_line, 1) == -1) {
            fprintf(stderr, "Error setting CE high: %s\n", strerror(errno));
            goto retry;
        }

        for (int j = 0; j < 3; ++j) {
            if (gpiod_line_set_value(sclk_line, 1) == -1) {
                fprintf(stderr, "Error setting SCLK high: %s\n", strerror(errno));
                goto retry;
            }
            if (gpiod_line_set_value(mosi_line, tx_buf[j] & 0x01) == -1) {
                fprintf(stderr, "Error setting MOSI high: %s\n", strerror(errno));
                goto retry;
            }
            if (gpiod_line_set_value(miso_line, 0) == -1) {
                fprintf(stderr, "Error setting MISO low: %s\n", strerror(errno));
                goto retry;
            }
            if (gpiod_line_set_value(sclk_line, 0) == -1) {
                fprintf(stderr, "Error setting SCLK low: %s\n", strerror(errno));
                goto retry;
            }
        }

        if (gpiod_line_set_value(ce_line, 0) == -1) {
            fprintf(stderr, "Error setting CE low: %s\n", strerror(errno));
            goto retry;
        }

        // Read the received data
        for (int j = 0; j < 3; ++j) {
            if (gpiod_line_set_value(sclk_line, 1) == -1) {
                fprintf(stderr, "Error setting SCLK high: %s\n", strerror(errno));
                goto retry;
            }
            if (gpiod_line_get_value(miso_line) & (1 << (2 - j))) {
                rx_buf[j] |= (1 << (2 - j));
            }
            if (gpiod_line_set_value(sclk_line, 0) == -1) {
                fprintf(stderr, "Error setting SCLK low: %s\n", strerror(errno));
                goto retry;
            }
        }

        // Combine the received bytes into a 10-bit value
        int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

        goto cleanup;
        break;
    }

    retry:
        usleep(SPI_RETRY_DELAY_MS * 1000); // Exponential backoff
    }

cleanup:
    if (gpiod_line_set_value(ce_line, 0) == -1) {
        fprintf(stderr, "Error setting CE low: %s\n", strerror(errno));
    }
    if (gpiod_line_set_value(sclk_line, 0) == -1) {
        fprintf(stderr, "Error setting SCLK low: %s\n", strerror(errno));
    }
    if (gpiod_line_set_value(mosi_line, 0) == -1) {
        fprintf(stderr, "Error setting MOSI low: %s\n", strerror(errno));
    }
    if (gpiod_line_set_value(miso_line, 0) == -1) {
        fprintf(stderr, "Error setting MISO low: %s\n", strerror(errno));
    }

    return adc_value;
}

// Convert ADC value to moisture percentage
float adc_to_moisture_percentage(int adc_value) {
    if (adc_value < 0) return 0.0;
    if (adc_value > 1023) return 100.0;
    return 100.0 - ((float)(adc_value - MIN_ADC_VALUE) / (float)(MAX_ADC_VALUE - MIN_ADC_VALUE)) * 100.0;
}

// Log moisture reading with timestamp
void log_moisture_reading(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Moisture: %.2f%%\n", timestamp, moisture_percentage);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (gpio_ce0_line) {
        gpiod_line_release(gpio_ce0_line);
    }
    if (gpio_sclk_line) {
        gpiod_line_release(gpio_sclk_line);
    }
    if (gpio_mosi_line) {
        gpiod_line_release(gpio_mosi_line);
    }
    if (gpio_miso_line) {
        gpiod_line_release(gpio_miso_line);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            float moisture_percentage = adc_to_moisture_percentage(adc_value);
            log_moisture_reading(moisture_percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", READ_INTERVAL_SEC);
        }

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

