#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_SENSORS 4
#define CSV_FILE "environmental_data.csv"

// Global variables
static int spi_fd = -1;
static struct gpiod_line *chip = NULL;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value, float vref);
int log_data(float voltages[NUM_SENSORS]);
void signal_handler(int sig);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// SPI initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    // Chip select line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return -1;
    }

    struct gpiod_line *lines = gpiod_chip_get_lines(chip);
    if (!lines) {
        perror("Error getting GPIO lines");
        gpiod_chip_close(chip);
        close(spi_fd);
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        struct gpiod_line *line = lines[i];
        if (!line) {
            perror("Error getting GPIO line");
            gpiod_chip_close(chip);
            close(spi_fd);
            return -1;
        }

        if (gpiod_line_request_output(line, "sensor_cs", 0) < 0) {
            perror("Error requesting GPIO line as output");
            gpiod_chip_close(chip);
            close(spi_fd);
            return -1;
        }
    }

    return 0;
}

// Read ADC value from MCP3008
int spi_read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return (adc_value / 1023.0) * vref;
}

// Log data to CSV file
int log_data(float voltages[NUM_SENSORS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(fp, ",%.3f", voltages[i]);
    }
    fprintf(fp, "\n");
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (fp) {
        fclose(fp);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Sensor0,Sensor1,Sensor2,Sensor3\n");
    }

    // Main loop
    while (!terminate) {
        float voltages[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = spi_read_adc(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC value from channel %d\n", i);
                voltages[i] = -1.0; // Indicate error
            } else {
                voltages[i] = adc_to_voltage(adc_value, VREF);
            }
        }

        if (log_data(voltages) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

