    printf("\n--- Log Buffer ---\n");
    int start_index = buffer_index;
    if (buffer_count == 0) {
        start_index = 0;
    } else {
        start_index = (buffer_index - buffer_count + CIRCULAR_BUFFER_SIZE) % CIRCULAR_BUFFER_SIZE;
