// MAX30102 I2C address
#define MAX30102_ADDR 0x57

// MAX30102 register addresses
#define REG_PART_ID 0xFF
#define REG_MODE_CONFIG 0x06
#define REG_FIFO_DATA 0x07
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A

// SpO2 and HR thresholds
#define SPO2_THRESHOLD 95
#define HR_THRESHOLD 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

// Function prototypes
int init_max30102();
int read_fifo(sensor_data_t *data);
float calculate_spo2(uint16_t ir);
float calculate_hr(uint16_t ir);
void log_health_event(float spo2, int hr);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the MAX30102 sensor
int init_max30102() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Clear interrupts
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to clear interrupts.\n");
        return -1;
    }

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, REG_MODE_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to configure SpO2 mode.\n");
        return -1;
    }

    // Configure SPO2_CONFIG
    if (i2cWriteByteData(i2c_handle, REG_SPO2_CONFIG, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to configure SPO2_CONFIG.\n");
        return -1;
    }

    // Configure LED pulse amplitudes
    if (i2cWriteByteData(i2c_handle, REG_LED1_PA, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to configure LED1_PA.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_LED2_PA, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to configure LED2_PA.\n");
        return -1;
    }

    return 0;
}

// Read FIFO data from the sensor
int read_fifo(sensor_data_t *data) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, REG_FIFO_DATA, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read FIFO data.\n");
        return -1;
    }

    data->red = (buf[0] << 8) | buf[1];
    data->ir = (buf[3] << 8) | buf[4];

    return 0;
}

// Calculate SpO2 using the ratio-of-ratios method
float calculate_spo2(uint16_t ir) {
    // Implement ratio-of-ratios algorithm here
    // This is a placeholder; replace with actual implementation
    // based on the MAX30102 datasheet and your specific application.
    // The following is a simplified example and may not be accurate.
    float ratio = (float)ir / 1000.0; // Example ratio
    float spo2 = 100.0 - (ratio * 2.0); // Example SpO2 calculation

    return spo2;
}

// Calculate heart rate using peak detection on the IR signal
float calculate_hr(uint16_t ir) {
    // Implement peak detection algorithm here
    // This is a placeholder; replace with actual implementation
    // based on the MAX30102 datasheet and your specific application.
    // The following is a simplified example and may not be accurate.
    float peaks = 0.0;
    for (int i = 1; i < 100; i++) { // Example window size
        if (ir[i] > ir[i - 1] && ir[i] > ir[i + 1]) {
            peaks++;
        }
    }
    float hr = peaks * 60.0; // Example heart rate calculation

    return hr;
}

// Log health event to file
void log_health_event(float spo2, int hr) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    FILE *fp = fopen("health_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open health_log.txt for writing.\n");
        return;
    }

    fprintf(fp, "%s - SpO2: %.2f%%, HR: %d BPM\n", timestamp, spo2, hr);
    fclose(fp);
}

