    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus 1.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_max30102() < 0) {
        fprintf(stderr, "Error: MAX30102 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    float spo2, hr;

    // Main loop
    while (!terminate) {
        // Read FIFO data
        if (read_fifo(&sensor_data) == 0) {
            // Calculate SpO2 and HR
            spo2 = calculate_spo2(sensor_data.ir);
            hr = calculate_hr(sensor_data.ir);

            // Log health event
            if (spo2 < SPO2_THRESHOLD || hr > HR_THRESHOLD) {
                log_health_event(spo2, hr);
            }

            printf("SpO2: %.2f%%, HR: %d BPM\n", spo2, hr);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

