#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_CONFIG_DEFAULT 0x4003 // Single-shot mode, +/-4.096V, 128 SPS, AIN0
#define ADS1115_REG_CONVERT_DEFAULT 0x8000 // Start single conversion
#define GPIO_DOOR_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define NUM_BASLINE_SAMPLES 10
#define SAMPLE_INTERVAL_MS 200
#define RELAY_ON_TIME_S 3
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *door_sensor_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int ads1115_setup(int fd, int addr);
int read_ads1115(int fd, int addr);
float calibrate_sensor(int fd, int addr);
int gpio_setup(int gpio);
int gpio_write(int gpio, int value);
int gpio_read(int gpio);
void log_event(const char *event);
void signal_handler(int sig);
void cleanup();

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// ADS1115 setup function
int ads1115_setup(int fd, int addr) {
    // Configure ADS1115 for single-shot mode, +/-4.096V, 128 SPS, AIN0
    uint16_t config = ADS1115_REG_CONFIG_DEFAULT | (0x8000 << 12); // Start single conversion
    uint8_t write_buf[3];
    write_buf[0] = ADS1115_REG_CONFIG;
    write_buf[1] = (config >> 8) & 0xFF; // MSB
    write_buf[2] = config & 0xFF;        // LSB

    if (write(fd, write_buf, 3) != 3) {
        perror("Error writing to ADS1115");
        return -1;
    }

    return 0;
}

// Read ADS1115 data function
int read_ads1115(int fd, int addr) {
    uint8_t read_buf[2];
    uint16_t raw_value;

    // Request a single conversion
    uint8_t write_buf[3];
    write_buf[0] = ADS1115_REG_CONVERT;
    write_buf[1] = 0x80; // Conversion start bit
    write_buf[2] = 0x00; // Dummy byte

    if (write(fd, write_buf, 3) != 3) {
        perror("Error writing to ADS1115 for conversion");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    if (read(fd, read_buf, 2) != 2) {
        perror("Error reading from ADS1115");
        return -1;
    }

    raw_value = (read_buf[0] << 8) | read_buf[1];

    return raw_value;
}

// Calibrate sensor function
float calibrate_sensor(int fd, int addr) {
    int sum = 0;
    for (int i = 0; i < NUM_BASLINE_SAMPLES; i++) {
        int raw_value = read_ads1115(fd, addr);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading sensor during calibration\n");
            return -1.0; // Indicate calibration failure
        }
        sum += raw_value;
        usleep(SAMPLE_INTERVAL_MS * 1000); // Sample every 200ms
    }

    float average = (float)sum / NUM_BASLINE_SAMPLES;
    return average * 0.8; // Set threshold to 80% of average
}

// GPIO setup function
int gpio_setup(int gpio) {
    struct gpiod_chip *chip = gpiod_chip_open_by_number(0); // Assuming chip 0
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "door_control", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return line;
}

// GPIO write function
int gpio_write(int gpio, int value) {
    if (gpio == GPIO_DOOR_RELAY) {
        if (gpiod_line_set_value(relay_line, value) < 0) {
            perror("Error setting GPIO value");
            return -1;
        }
    } else if (gpio == GPIO_DOOR_SENSOR) {
        if (gpiod_line_set_value(door_sensor_line, value) < 0) {
            perror("Error setting GPIO value");
            return -1;
        }
    }
    return 0;
}

// GPIO read function
int gpio_read(int gpio) {
    if (gpio == GPIO_DOOR_SENSOR) {
        return gpiod_line_get_value(door_sensor_line);
    }
    return -1; // Invalid GPIO
}

// Log event function
void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0); // De-energize relay
        gpiod_line_release(relay_line);
    }
    if (door_sensor_line) {
        gpiod_line_release(door_sensor_line);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (relay_line != NULL) {
        gpiod_chip_close(relay_line->chip);
    }
    if (door_sensor_line != NULL) {
        gpiod_chip_close(door_sensor_line->chip);
    }
}

int main() {
    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, ADS1115_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_setup(i2c_fd, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        cleanup();
        return 1;
    }

    // Calibrate the sensor
    float threshold = calibrate_sensor(i2c_fd, ADS1115_ADDR);
    if (threshold < 0) {
        fprintf(stderr, "Sensor calibration failed\n");
        cleanup();
        return 1;
    }
    printf("Threshold: %.2f\n", threshold);

    // Setup GPIO
    relay_line = gpio_setup(GPIO_DOOR_RELAY);
    if (relay_line == NULL) {
        fprintf(stderr, "GPIO setup failed\n");
        cleanup();
        return 1;
    }

    door_sensor_line = gpio_setup(GPIO_DOOR_SENSOR);
    if (door_sensor_line == NULL) {
        fprintf(stderr, "GPIO setup failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor value
        int raw_value = read_ads1115(i2c_fd, ADS1115_ADDR);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading sensor\n");
            continue; // Continue to the next iteration
        }

        // Check if value is below threshold
        if (raw_value < threshold) {
            printf("Distance below threshold, opening door...\n");
            log_event("door opened (sensor)");
            gpio_write(GPIO_DOOR_RELAY, 1); // Energize relay
            sleep(RELAY_ON_TIME_S);
            gpio_write(GPIO_DOOR_RELAY, 0); // De-energize relay
            usleep(100000); // Small delay after relay de-energization

            // Read door sensor
            int door_state = gpio_read(GPIO_DOOR_SENSOR);
            if (door_state == 0) {
                log_event("door opened (sensor)");
            } else {
                log_event("door not opened (sensor)");
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sample every 200ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

