#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS0 8
#define CS1 7
#define CS2 25
#define NUM_SENSORS 3
#define LOG_INTERVAL_SEC 5

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs0_line = NULL;
static struct gpiod_line *cs1_line = NULL;
static struct gpiod_line *cs2_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int bus, int chip, int speed);
int read_mcp3008(int spi_fd, int channel);
int gpio_request(int line_num, const char *chip_name);
int gpio_set_value(int line_num, int value);
int gpio_unrequest(int line_num);
int open_log_file(const char *filename);
void close_log_file(FILE *file);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(int bus, int chip, int speed) {
    char spi_device[20];
    sprintf(spi_device, "/dev/spidev%d.%d", bus, chip);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// GPIO initialization function
int gpio_request(int line_num, const char *chip_name) {
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "soil_moisture_logger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT; // Assuming CS is output
    config.flags = 0;

    if (gpiod_line_request(gpio_chip, line_num, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        return -1;
    }

    return 0;
}

// GPIO set function
int gpio_set_value(int line_num, int value) {
    struct gpiod_line_set_value_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "soil_moisture_logger";
    config.offset = 0;
    config.value = value;

    if (gpiod_line_set_value(cs0_line, &config, 0) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    return 0;
}

// GPIO unrequest function
int gpio_unrequest(int line_num) {
    if (gpiod_line_release(cs0_line, 0) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    if (gpiod_line_release(cs1_line, 0) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    if (gpiod_line_release(cs2_line, 0) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }

    if (gpiod_chip_close(gpio_chip) < 0) {
        perror("Error closing GPIO chip");
        return -1;
    }

    return 0;
}

// Open log file function
int open_log_file(const char *filename) {
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Check if the file is newly created (empty)
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sensor1,Sensor2,Sensor3\n");
    }
    rewind(log_file);

    return 0;
}

// Close log file function
void close_log_file(FILE *file) {
    if (file != NULL) {
        fclose(file);
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Unrequest GPIO lines
    gpio_unrequest(CS0);
    gpio_unrequest(CS1);
    gpio_unrequest(CS2);

    // Close log file
    if (log_file != NULL) {
        close_log_file(log_file);
    }

    // Free GPIO chip
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines
    if (gpio_request(CS0, "gpiochip0") < 0 ||
        gpio_request(CS1, "gpiochip0") < 0 ||
        gpio_request(CS2, "gpiochip0") < 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (spi_init(SPI_BUS, SPI_CHIP, SPI_SPEED) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    if (open_log_file("soil_moisture_log.csv") < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];
        int sensor1_value, sensor2_value, sensor3_value;

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read sensor values
        sensor1_value = read_mcp3008(spi_fd, 0);
        sensor2_value = read_mcp3008(spi_fd, 0);
        sensor3_value = read_mcp3008(spi_fd, 0);

        // Log data to file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value);
        fflush(log_file); // Ensure data is written to disk

        // Wait for the next interval
        sleep(LOG_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

