#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CE 8
#define VH400_DRY_ADC 200
#define VH400_WET_ADC 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60

// Global variables
static int spi_handle;
static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int interval = DEFAULT_INTERVAL;
static volatile int running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void control_pump(int activate);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            log_message("Error: SPI transfer failed. Retrying...");
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    log_message("Error: SPI transfer failed after multiple retries.");
    return -1; // Indicate error
}

// Function to convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    float moisture = (float)(adc_value - VH400_DRY_ADC) / (float)(VH400_WET_ADC - VH400_DRY_ADC) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

// Function to control the water pump
void control_pump(int activate) {
    gpioWrite(PUMP_GPIO, activate);
    char message[100];
    sprintf(message, "Pump %s", activate ? "activated" : "deactivated");
    log_message(message);
}

// Function to log messages to a file
void log_message(const char *message) {
    FILE *fp = fopen("irrigation.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    log_message("pigpio terminated");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (initialize()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Irrigation system started.");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_message("Error reading ADC value, skipping irrigation cycle.");
        } else {
            float moisture = adc_to_moisture(adc_value);
            char message[100];
            sprintf(message, "Moisture: %.2f%%", moisture);
            log_message(message);

            if (moisture < threshold) {
                log_message("Moisture below threshold, activating pump.");
                control_pump(1);
                gpioDelay(duration * 1000); // Convert seconds to milliseconds
                control_pump(0);
                log_message("Pump deactivated.");
            }

            gpioDelay(interval * 1000); // Convert seconds to milliseconds
        }
    }

    cleanup();
    return 0;
}

