#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define EMA_WINDOW_SIZE 10
#define THRESHOLD_MULTIPLIER 1.2
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
double ema_values[EMA_WINDOW_SIZE];
int ema_index = 0;
double ema_sum = 0.0;
int running = 1;

// Function prototypes
int read_mcp3008(int channel);
double calculate_ema(double new_value, double *ema_values, int window_size, double *ema_sum, int *ema_index);
double calculate_threshold(double ema_value);
int detect_peak(double raw_value, double threshold);
int log_event(double raw_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate Exponential Moving Average (EMA)
double calculate_ema(double new_value, double *ema_values, int window_size, double *ema_sum, int *ema_index) {
    // Update EMA sum
    *ema_sum -= ema_values[*ema_index];
    *ema_sum += new_value;

    // Update EMA value
    double weighted_sum = 0.0;
    for (int i = 0; i < window_size; i++) {
        weighted_sum += ema_values[i] * (1.0 - pow(0.95, abs(i - *ema_index)));
    }
    ema_values[*ema_index] = weighted_sum + new_value;

    // Update EMA index
    *ema_index = (*ema_index + 1) % window_size;

    return weighted_sum;
}

// Function to calculate the dynamic threshold
double calculate_threshold(double ema_value) {
    return ema_value * THRESHOLD_MULTIPLIER;
}

// Function to detect a peak
int detect_peak(double raw_value, double threshold) {
    return (raw_value > threshold);
}

// Function to log the event
int log_event(double raw_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, raw_value);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize EMA values
    for (int i = 0; i < EMA_WINDOW_SIZE; i++) {
        ema_values[i] = 0.0;
    }
    ema_sum = 0.0;
    ema_index = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate EMA
        double ema_value = calculate_ema(adc_value, ema_values, EMA_WINDOW_SIZE, &ema_sum, &ema_index);

        // Calculate threshold
        double threshold = calculate_threshold(ema_value);

        // Detect peak
        if (detect_peak(adc_value, threshold)) {
            // Log event
            if (log_event(adc_value) != 0) {
                fprintf(stderr, "Error: Failed to log event\n");
            }
            printf("Peak detected: %.2f\n", adc_value);
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Sound level monitoring stopped.\n");

    return 0;
}

