#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define CONTROL_BYTE 0x40 // Single-ended mode, AIN0, disable analog output
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(int bus, int addr);
int read_adc(int fd);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// I2C setup function
int i2c_setup(int bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read ADC function
int read_adc(int fd) {
    unsigned char buf[1];
    unsigned char result[1];
    int value;

    // Send control byte
    buf[0] = CONTROL_BYTE;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Read two bytes (dummy read + actual read)
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Extract the ADC value (right-aligned)
    value = ((unsigned int)buf[1] << 8) | (unsigned int)buf[0];

    return value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, PCF8591_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    printf("PCF8591 ADC monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(i2c_fd);
        if (adc_value >= 0) {
            printf("ADC Value: %d\n", adc_value);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    close(i2c_fd);
    gpioTerminate();

    printf("PCF8591 ADC monitoring stopped.\n");
    return 0;
}

