#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_SHUTDOWN 27
#define BUFFER_SIZE 10
#define THRESHOLD 500.0 // Gauss
#define VCC 3.3 // Volts
#define SENSITIVITY 1.4 // mV/Gauss
#define ZERO_FIELD_VOLTAGE 2.5 // Volts

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize();
int read_adc();
float voltage_to_gauss(float voltage);
void buffer_init(CircularBuffer *cb);
void buffer_add(CircularBuffer *cb, float value);
float buffer_get_average(CircularBuffer *cb);
void shutdown_gpio();
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the average of the values in the circular buffer
float buffer_get_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, 128 SPS
    uint16_t config = 0x4083; // 0b0100000010000011
    if (i2cWriteWordData(i2c_handle, ADS1115_REG_CONFIG, config) < 0) {
        syslog(LOG_ERR, "Failed to write to ADS1115 config register");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, PI_LOW);

    syslog(LOG_INFO, "Initialization complete");
    return 0;
}

// Read ADC value from ADS1115
int read_adc() {
    char buf[2];
    int16_t raw_value;

    if (i2cWriteByte(i2c_handle, ADS1115_REG_CONVERT) < 0) {
        syslog(LOG_ERR, "Failed to trigger ADC conversion");
        return -1;
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADC data");
        return -1;
    }

    raw_value = (buf[0] << 8) | buf[1];
    return raw_value;
}

// Convert voltage to Gauss
float voltage_to_gauss(float voltage) {
    if (voltage < 0.0 || voltage > VCC) {
        syslog(LOG_ERR, "Invalid voltage reading: %f", voltage);
        return -1.0;
    }
    float gauss = (voltage - ZERO_FIELD_VOLTAGE) / (SENSITIVITY / VCC);
    return gauss;
}

// Shutdown GPIO
void shutdown_gpio() {
    gpioWrite(GPIO_SHUTDOWN, PI_HIGH);
    syslog(LOG_INFO, "Motor shutdown triggered");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(GPIO_SHUTDOWN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("hall_effect_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        syslog(LOG_ERR, "Initialization failed, exiting");
        closelog();
        return 1;
    }

    CircularBuffer gauss_buffer;
    buffer_init(&gauss_buffer);

    // Main loop
    while (!terminate) {
        int raw_value = read_adc();
        if (raw_value < 0) {
            syslog(LOG_WARNING, "Failed to read ADC, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float voltage = (float)raw_value * VCC / 32768.0; // Convert to voltage
        float gauss = voltage_to_gauss(voltage);

        if (gauss < 0.0) {
            syslog(LOG_WARNING, "Invalid Gauss reading, skipping...");
            gpioDelay(100);
            continue;
        }

        buffer_add(&gauss_buffer, gauss);
        float avg_gauss = buffer_get_average(&gauss_buffer);

        syslog(LOG_INFO, "Voltage: %f V, Gauss: %f, Average Gauss: %f", voltage, gauss, avg_gauss);

        if (avg_gauss > THRESHOLD) {
            shutdown_gpio();
        }

        gpioDelay(1000); // Sample at 1 Hz
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

