#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define READ_INTERVAL 60 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_event(int moisture_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Validate ADC value
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1; // Indicate error
    }

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log watering events
void log_event(int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture Level: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0 CE0, 1 MHz, SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("watering_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_level == -1) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            // Attempt to recover by re-initializing SPI
            spiClose(spi_handle);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "Error: SPI re-initialization failed\n");
                terminate = 1; // Exit loop if recovery fails
            }
            continue; // Skip to the next iteration
        }

        // Control water pump
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating pump.\n");
            control_pump(1); // Turn pump on
            log_event(moisture_level);
            time_t start_time = time(NULL);
            while (time(NULL) - start_time < WATERING_DURATION && !terminate) {
                gpioDelay(1000); // Check every 1 second
            }
            control_pump(0); // Turn pump off
            printf("Pump deactivated.\n");
        } else {
            printf("Moisture level above threshold. Not watering.\n");
        }

        // Wait before next reading
        gpioDelay(READ_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Watering system stopped.\n");
    return 0;
}

