// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MOTOR_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1024

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_speed(int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set motor speed using PWM
void set_motor_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid duty cycle: %d\n", duty_cycle);
        return;
    }

    gpioPWM(MOTOR_GPIO, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0, CE0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure PWM on GPIO18
    gpioSetMode(MOTOR_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR_GPIO, PWM_RANGE);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008 channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate duty cycle (0-1023)
        int duty_cycle = adc_value;

        // Set motor speed
        set_motor_speed(duty_cycle);

        // Print ADC value and duty cycle
        printf("ADC Value: %d, Duty Cycle: %d\n", adc_value, duty_cycle);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Stop PWM and terminate pigpio library
    gpioPWM(MOTOR_GPIO, 0); // Stop PWM
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated gracefully.\n");

    return 0;
}

