#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <errno.h>

// Constants
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_POWER_CTL 0x2D
#define ADS1115_REG_GAIN 0x40
#define ADS1115_REG_PGA 0x41
#define ADS1115_REG_MODE_SINGLE 0x0100
#define ADS1115_REG_MODE_SINGLE_ENA 0x0200
#define ADS1115_REG_MODE_SINGLE_START 0x0003
#define ADS1115_REG_MODE_SINGLE_RDY 0x0004
#define ADS1115_REG_MODE_SINGLE_CONVERT 0x0002

#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0

// Global variables
static int i2c_handle;
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_ads1115();
int16_t read_ads1115();
double calculate_gauss(int16_t adc_value);
void blink_led(double threshold);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure ADS1115 for single-ended AIN0, gain 4.096V, continuous conversion
int configure_ads1115() {
    // Configure register 0x01 (Configuration Register)
    uint16_t config = 0x4003; // Single-ended AIN0, 4.096V gain, continuous conversion
    uint8_t write_buf[3];
    write_buf[0] = ADS1115_REG_CONFIG;
    write_buf[1] = (config >> 8) & 0xFF; // MSB
    write_buf[2] = config & 0xFF;      // LSB

    if (i2cWriteDevice(i2c_handle, (char *)write_buf, 3) != 3) {
        fprintf(stderr, "Failed to write to configuration register: %s\n", strerror(errno));
        return -1;
    }

    // Set the configuration register
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Failed to set configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int16_t read_ads1115() {
    uint8_t read_buf[2];
    int16_t adc_value;

    // Start a single conversion
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_POWER_CTL, ADS1115_REG_MODE_SINGLE_START) != 0) {
        fprintf(stderr, "Failed to start single conversion: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // Wait 10ms

    // Read the conversion result
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, (char *)read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read conversion result: %s\n", strerror(errno));
        return -1;
    }

    adc_value = (read_buf[0] << 8) | read_buf[1];

    // Clear the conversion complete interrupt
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_POWER_CTL, ADS1115_REG_MODE_SINGLE_RDY) != 0) {
        fprintf(stderr, "Failed to clear conversion complete interrupt: %s\n", strerror(errno));
        return -1;
    }

    return adc_value;
}

// Calculate magnetic field strength in Gauss
double calculate_gauss(int16_t adc_value) {
    double voltage = (adc_value / 32768.0) * 4.096; // 16-bit ADC, 4.096V gain
    double gauss = voltage * 1000.0; // 0.001 V/Gauss
    return gauss;
}

// Blink LED rapidly for 1 second if magnetic field exceeds threshold
void blink_led(double threshold) {
    int on_time = 50; // 50 ms on
    int off_time = 50; // 50 ms off
    int num_cycles = (int)(1.0 / (on_time + off_time) * 1000.0); // Calculate number of cycles for 1 second

    if (threshold > 0) {
        for (int i = 0; i < num_cycles; i++) {
            gpioWrite(LED_GPIO, 1); // Turn LED on
            gpioDelay(on_time * 1000); // Delay in microseconds
            gpioWrite(LED_GPIO, 0); // Turn LED off
            gpioDelay(off_time * 1000); // Delay in microseconds
        }
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int16_t adc_value = read_ads1115();
        if (adc_value >= 0) {
            double gauss = calculate_gauss(adc_value);
            printf("Magnetic Field: %.2f Gauss\n", gauss);

            if (gauss > threshold) {
                blink_led(threshold);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    return 0;
}

