    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, (char *)read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read conversion result: %s\n", strerror(errno));
        return -1;
    }

    adc_value = (read_buf[0] << 8) | read_buf[1];

    // Clear the conversion complete interrupt
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_POWER_CTL, ADS1115_REG_MODE_SINGLE_RDY) != 0) {
        fprintf(stderr, "Failed to clear conversion complete interrupt: %s\n", strerror(errno));
        return -1;
    }

    return adc_value;
}

// Calculate magnetic field strength in Gauss
double calculate_gauss(int16_t adc_value) {
    double voltage = (adc_value / 32768.0) * 4.096; // 16-bit ADC, 4.096V gain
    double gauss = voltage * 1000.0; // 0.001 V/Gauss
    return gauss;
}

// Blink LED rapidly for 1 second if magnetic field exceeds threshold
void blink_led(double threshold) {
    int on_time = 50; // 50 ms on
    int off_time = 50; // 50 ms off
    int num_cycles = (int)(1.0 / (on_time + off_time) * 1000.0); // Calculate number of cycles for 1 second

    if (threshold > 0) {
        for (int i = 0; i < num_cycles; i++) {
            gpioWrite(LED_GPIO, 1); // Turn LED on
            gpioDelay(on_time * 1000); // Delay in microseconds
            gpioWrite(LED_GPIO, 0); // Turn LED off
            gpioDelay(off_time * 1000); // Delay in microseconds
        }
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int16_t adc_value = read_ads1115();
        if (adc_value >= 0) {
            double gauss = calculate_gauss(adc_value);
            printf("Magnetic Field: %.2f Gauss\n", gauss);

            if (gauss > threshold) {
                blink_led(threshold);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    return 0;
}

