#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_KEEPALIVE 60

// Global variables
int spi_handle;
struct mosquitto *mqtt_client = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_relay(float moisture);
void publish_mqtt(float moisture);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signum);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        syslog(LOG_ERR, "SPI transfer failed: %d", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "Invalid ADC value: %d", adc_value);
        return -1.0; // Indicate sensor-absent condition
    }

    // Map ADC value (0-1023) to moisture percentage (0-100)
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to control the relay
void control_relay(float moisture) {
    if (moisture < MOISTURE_THRESHOLD_LOW && !gpioRead(RELAY_GPIO) == 0) {
        gpioWrite(RELAY_GPIO, 1); // Activate relay
        syslog(LOG_INFO, "Moisture below threshold. Activating relay.");
    } else if (moisture > MOISTURE_THRESHOLD_HIGH && gpioRead(RELAY_GPIO) == 1) {
        gpioWrite(RELAY_GPIO, 0); // Deactivate relay
        syslog(LOG_INFO, "Moisture above threshold. Deactivating relay.");
    }
}

// Function to publish moisture data to MQTT
void publish_mqtt(float moisture) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
    }
}

// MQTT connect callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_CONTROL_TOPIC, 0); // Subscribe to control topic
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(result));
    }
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        if (strcmp(message->topic, MQTT_CONTROL_TOPIC) == 0) {
            if (strcmp(message->payload, "pump_on") == 0) {
                syslog(LOG_INFO, "Received pump_on command. Activating relay.");
                control_relay(-1.0); // Activate relay even if moisture is unknown
            } else if (strcmp(message->payload, "pump_off") == 0) {
                syslog(LOG_INFO, "Received pump_off command. Deactivating relay.");
                control_relay(-1.0); // Deactivate relay even if moisture is unknown
            } else {
                syslog(LOG_WARNING, "Received unknown command: %s", message->payload);
            }
        }
    }
}

// Signal handler for clean shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received: %d. Terminating...", signum);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    if (mqtt_client) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
    closelog();
}

