            control_relay(moisture);
        } else {
            syslog(LOG_WARNING, "Sensor absent. Moisture = %.2f", moisture);
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

