#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x11
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_db(int adc_value);
int read_bh1750();
void log_data(time_t timestamp, float sound_level_db, float light_level_lux, int error_code);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    if (spiXfer(spi_fd, tx_buf, rx_buf, 3) != 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to dB
float adc_to_db(int adc_value) {
    // Simple linear conversion for demonstration purposes.
    // A more accurate calibration would involve a lookup table or polynomial fit.
    float db = (float)adc_value * 0.1; // Example: 0-1023 -> 0-10 dB
    return db;
}

// Function to read from BH1750 sensor
int read_bh1750() {
    unsigned char buf[2];
    int lux = -1;

    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    usleep(180000); // Wait 180 ms

    if (read(i2c_fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }

    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Function to log data to CSV file
void log_data(time_t timestamp, float sound_level_db, float light_level_lux, int error_code) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp_str, sound_level_db, light_level_lux, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI device
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        spiClose(spi_fd);
        gpioTerminate();
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    printf("Tamper detection system started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (!terminate) {
        time_t now = time(NULL);
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        float sound_level_db = adc_to_db(adc_value);
        int light_level_lux = read_bh1750();

        if (adc_value == -1 || light_level_lux == -1) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            // Basic data validation
            if (sound_level_db < -100 || sound_level_db > 100) {
                fprintf(stderr, "Warning: Sound level out of range: %.2f dB\n", sound_level_db);
            }
            if (light_level_lux < 0 || light_level_lux > 100000) {
                fprintf(stderr, "Warning: Light level out of range: %.2f lux\n", light_level_lux);
            }

            log_data(now, sound_level_db, light_level_lux, 0); // No error code for now
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    printf("Tamper detection system stopped.\n");
    return 0;
}

