#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define NUM_SENSORS 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int pump_state);
void log_data(int sensor_values[]);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming 3.3V reference voltage
    float voltage = (float)adc_value / 1023.0 * 3.3;
    float moisture = 100.0 - (voltage / 3.3) * 100.0; // Inverted for VH400
    return moisture;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
}

// Function to log sensor data
void log_data(int sensor_values[]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        printf("Sensor %d: %d, %.2f%%\t", i + 1, sensor_values[i], calculate_moisture(sensor_values[i]));
        if (i < NUM_SENSORS - 1) {
            printf(", ");
        }
    }
    printf("\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_values[NUM_SENSORS];

    // Main loop
    while (!terminate) {
        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i + 1);
                sensor_values[i] = -1; // Indicate error
            } else {
                sensor_values[i] = adc_value;
            }
        }

        // Calculate moisture percentages
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (sensor_values[i] >= 0) {
                sensor_values[i] = calculate_moisture(sensor_values[i]);
            }
        }

        // Control the pump
        int any_below_threshold = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (sensor_values[i] >= 0 && sensor_values[i] < MOISTURE_THRESHOLD) {
                any_below_threshold = 1;
                break;
            }
        }
        control_pump(any_below_threshold);

        // Log the data
        log_data(sensor_values);

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

