    // You'll need to calibrate the sensor and create a lookup table or polynomial
    // to accurately map ADC values to distances.
    // For this example, we'll use a simple linear approximation.
    // You'll need to adjust the slope and intercept based on your sensor's characteristics.
    float distance = 27.0 - (float)adc_value / 64.0; // Example linear approximation
    if (distance < 0) distance = 0; // Ensure distance is not negative
    return distance;
}

