        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int relay_state = 0; // 0 = off, 1 = on
    time_t last_trigger_time = 0;

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        float distance = calculate_distance(adc_value);

        // Check for proximity
        if (distance < PROXIMITY_THRESHOLD) {
            // Check debounce delay
            time_t current_time = time(NULL);
            if (difftime(current_time, last_trigger_time) >= DEBOUNCE_DELAY) {
                // Activate relay
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Door opened");
                    last_trigger_time = current_time;
                }
            }
        } else {
            // Deactivate relay
            if (relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_event("Door closed");
            }
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

