#include <string.h>

// Constants
#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 100 // 100 Hz
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_adc(int sensor1, int sensor2, int sensor3);
int map_to_duty_cycle(float average);
void set_valve_position(int duty_cycle);
void log_data(int sensor1, int sensor2, int sensor3, float average, int duty_cycle);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 single-ended read)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to average ADC readings
float average_adc(int sensor1, int sensor2, int sensor3) {
    float sum = 0.0;
    int valid_count = 0;

    if (sensor1 >= 0) {
        sum += sensor1;
        valid_count++;
    }
    if (sensor2 >= 0) {
        sum += sensor2;
        valid_count++;
    }
    if (sensor3 >= 0) {
        sum += sensor3;
        valid_count++;
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return -1.0; // Indicate error
    }
}

// Function to map ADC average to duty cycle
int map_to_duty_cycle(float average) {
    // Inverse mapping: higher average (wetter soil) -> lower duty cycle
    // Ensure average is within the valid range (0-1023)
    if (average < 0) average = 0;
    if (average > 1023) average = 1023;

    return 100 - (int)(average / 1023.0 * 100.0); // Scale to 0-100
}

// Function to set valve position using PWM
void set_valve_position(int duty_cycle) {
    gpioPWM(VALVE_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(int sensor1, int sensor2, int sensor3, float average, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d, Sensor3: %d, Average: %.2f, Duty Cycle: %d\n",
            timestamp, sensor1, sensor2, sensor3, average, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;

    // Close valve
    set_valve_position(0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
