        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture irrigation system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1 = read_mcp3008(0);
        int sensor2 = read_mcp3008(1);
        int sensor3 = read_mcp3008(2);

        // Check for sensor read errors
        if (sensor1 < 0 || sensor2 < 0 || sensor3 < 0) {
            fprintf(stderr, "Error: Failed to read one or more sensors. Skipping this iteration.\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Calculate average ADC value
        float average = average_adc(sensor1, sensor2, sensor3);

        // Check for average read error
        if (average < 0) {
            fprintf(stderr, "Error: Failed to calculate average ADC value. Skipping this iteration.\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

