        while (retry_count < RETRY_ATTEMPTS) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", retry_count + 1, RETRY_ATTEMPTS);
                gpioDelay(BACKOFF_DELAY_MS * (1 << retry_count)); // Exponential backoff
                retry_count++;
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries. Skipping this reading.\n", RETRY_ATTEMPTS);
            gpioDelay(5000); // Wait 5 seconds before next attempt
            continue;
        }

        float moisture_percentage = adc_to_moisture(adc_value);
        if (moisture_percentage >= 0) {
            log_data(moisture_percentage);
            printf("Moisture: %.2f%%\n", moisture_percentage);
        } else {
            fprintf(stderr, "Failed to convert ADC value to moisture percentage.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

