#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FAN_GPIO 18
#define NUM_SENSORS 2
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_aqi(int adc_value);
void control_fan(int aqi);
void log_data(int sensor_id, int adc_value, float aqi);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    int count, i;
    unsigned char spi_data[3];
    int adc_value = -1; // Initialize to an invalid value

    // Construct SPI message
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    spi_data[2] = 0x00; // Dummy byte

    for (count = 0; count < RETRY_COUNT; count++) {
        if (spiXfer(spi_handle, spi_data, spi_data, 3) == 0) {
            // Extract ADC value from response bytes
            adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d/%d). Retrying...\n", count + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "SPI read failed after %d retries. Re-initializing SPI.\n", RETRY_COUNT);
    spiClose(spi_handle);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Re-initialize SPI
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
        return -1; // Indicate failure
    }

    return -1; // Return failure if re-initialization fails
}

// Function to convert ADC value to AQI (linear mapping)
float adc_to_aqi(int adc_value) {
    // Linear mapping: AQI = (ADC_Value / 1023) * 500
    return (adc_value / 1023.0) * 500.0;
}

// Function to control the ventilation fan
void control_fan(int aqi) {
    if (aqi > 100) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to log data to file
void log_data(int sensor_id, int adc_value, float aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d, ADC: %d, AQI: %.2f\n", timestamp, sensor_id, adc_value, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;

    // Turn off the fan
    gpioWrite(FAN_GPIO, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    int i, adc_value, aqi;
    int fan_state = 0; // 0 = off, 1 = on

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (i = 0; i < NUM_SENSORS; i++) {
            adc_value = read_mcp3008(i);
            if (adc_value != -1) {
                aqi = adc_to_aqi(adc_value);
                control_fan(aqi);
                log_data(i, adc_value, aqi);
                printf("Sensor %d: ADC = %d, AQI = %.2f\n", i, adc_value, aqi);
            } else {
                fprintf(stderr, "Failed to read sensor %d\n", i);
            }
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

