#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define LOG_FILE "alcohol_log.txt"
#define ALCOHOL_THRESHOLD 50.0
#define SOBRIETY_THRESHOLD 20.0
#define SENSOR_ABSENT_THRESHOLD 5.0

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(int channel);
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
char* classify_reading(float ppm);
int log_reading(float ppm, char* classification);
void signal_handler(int sig);
int gpio_init(void);
int gpio_cleanup(void);

// SPI transfer function
int spi_transfer(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command: start bit, single-ended mode, channel number, dummy bit
    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x80; // Single-ended, channel select
    tx[2] = 0x00;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    int adc_value = -1;
    int retries = 3;

    while (retries > 0) {
        adc_value = spi_transfer(channel);
        if (adc_value >= 0) {
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed, retrying...\n");
            retries--;
            usleep(100000); // 100 ms delay
        }
    }

    fprintf(stderr, "SPI read failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Convert ADC value to approximate PPM
float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Classify the reading
char* classify_reading(float ppm) {
    if (ppm > ALCOHOL_THRESHOLD) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < SOBRIETY_THRESHOLD) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

// Log the reading to a file
int log_reading(float ppm, char* classification) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, %.2f, %s\n", timestamp, ppm, classification);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "alcohol_sensor", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
int gpio_cleanup(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        return 1;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpio_cleanup();
        return 1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpio_cleanup();
        return 1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpio_cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        float ppm = adc_to_ppm(adc_value);
        char* classification = classify_reading(ppm);

        if (log_reading(ppm, classification) < 0) {
            fprintf(stderr, "Failed to log reading.\n");
        }

        printf("ADC Value: %d, PPM: %.2f, Classification: %s\n", adc_value, ppm, classification);

        sleep(1);
    }

    // Cleanup
    close(spi_fd);
    gpio_cleanup();

    return 0;
}

