        return "Alcohol level within acceptable range.";
    }
}

// Log the reading to a file
int log_reading(float ppm, char* classification) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, %.2f, %s\n", timestamp, ppm, classification);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "alcohol_sensor", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
int gpio_cleanup(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        return 1;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpio_cleanup();
        return 1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpio_cleanup();
        return 1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpio_cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        float ppm = adc_to_ppm(adc_value);
        char* classification = classify_reading(ppm);

        if (log_reading(ppm, classification) < 0) {
            fprintf(stderr, "Failed to log reading.\n");
        }

        printf("ADC Value: %d, PPM: %.2f, Classification: %s\n", adc_value, ppm, classification);

        sleep(1);
    }

    // Cleanup
    close(spi_fd);
    gpio_cleanup();

    return 0;
}

