#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor 1 GPIOs
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIOs
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 Channel Assignments
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Global Variables
int spi_handle;
int min_speed = 50;
int max_speed = 255;
int current_speed = min_speed;
int current_direction = 0; // 0: forward, 1: backward
int motor1_speed = 0;
int motor2_speed = 0;
int pot1_value, pot2_value;
int running = 1;

// Function Prototypes
int read_mcp3008(int channel);
float map_pot_to_speed(int pot_value);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void motion_profile(int motor1_speed, int motor2_speed);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map potentiometer value to speed factor
float map_pot_to_speed(int pot_value) {
    // Logarithmic mapping
    float speed_factor = log10((float)pot_value + 1) / log10(1024.0 + 1); // Ensure denominator is not zero
    speed_factor = fmin(1.0, speed_factor); // Clamp to 1.0
    return (int)(speed_factor * (max_speed - min_speed) + min_speed);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    if (motor == 1) {
        gpioWrite(MOTOR1_DIRECTION, direction);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_DIRECTION, direction);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }
}

// Function to execute the motion profile
void motion_profile(int motor1_speed, int motor2_speed) {
    // Accelerate
    for (int i = min_speed; i <= motor1_speed; i += 5) {
        set_motor_speed(1, i);
        set_motor_speed(2, motor2_speed);
        gpioDelay(20); // 20ms delay
    }

    // Hold constant speed
    set_motor_speed(1, motor1_speed);
    set_motor_speed(2, motor2_speed);
    gpioDelay(2000); // 2 seconds

    // Decelerate
    for (int i = motor1_speed; i >= min_speed; i -= 5) {
        set_motor_speed(1, i);
        set_motor_speed(2, motor2_speed);
        gpioDelay(20); // 20ms delay
    }

    // Hold constant speed
    set_motor_speed(1, min_speed);
    set_motor_speed(2, min_speed);
    gpioDelay(2000); // 2 seconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion control system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read potentiometer values
        pot1_value = read_mcp3008(POT1_CHANNEL);
        pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values. Continuing...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Map potentiometer values to speed factors
        motor1_speed = map_pot_to_speed(pot1_value);
        motor2_speed = map_pot_to_speed(pot2_value);

        // Apply motion profile
        motion_profile(motor1_speed, motor2_speed);

        // Small delay to avoid overwhelming the system
        gpioDelay(50);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

