int spi_init(const char *device, int mode, int bits, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int gpio_request_output(struct gpiod_chip *chip, int line, const char *consumer);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_unrequest(struct gpiod_line *line);
int read_mcp3008(int fd, int channel);
void log_audio_data(long long timestamp_ns, int adc_value);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO request output function
int gpio_request_output(struct gpiod_chip *chip, int line, const char *consumer) {
    struct gpiod_line_request_config config = {
        .consumer = consumer,
        .requested_flags = 0,
    };

    int ret = gpiod_chip_request_line(chip, line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %d\n", line, ret);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// GPIO unrequest function
int gpio_unrequest(struct gpiod_line *line) {
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line: %d\n", ret);
        return -1;
    }
    return 0;
}

// Read MCP3008 function
int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message to read from the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error during SPI transfer for MCP3008\n");
        return -1;
    }

    // Parse the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Log audio data function
void log_audio_data(long long timestamp_ns, int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%lld|%d\n", timestamp_ns, adc_value);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (cs_line) {
        gpio_unrequest(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    if (gpio_request_output(gpio_chip, CS_PIN, "audio_adc") < 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = SAMPLE_PERIOD; // Sample every 1 ms
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CH0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Get timestamp
        long long timestamp_ns = clock_gettime(CLOCK_MONOTONIC_RAW, &ts);

        // Log data
        log_audio_data(timestamp_ns, adc_value);

        // Sleep until the next sample deadline
        nanosleep(&ts, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

