#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8

// Define ADXL335 parameters
#define SENSITIVITY 0.300 // 300 mV/g
#define ZERO_G_VOLTAGE 1.5 // 1.5 V
#define REFERENCE_VOLTAGE 3.3 // 3.3 V

// Define Kalman filter parameters
#define ALPHA 0.98 // Kalman filter gain

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold Kalman filter state
typedef struct {
    float x;
    float y;
    float z;
} KalmanState;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
void kalman_filter(KalmanState *state, float measurement);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transaction failed (channel %d): %d\n", channel, result);
        return -1;
    }

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * REFERENCE_VOLTAGE;
}

// Function to convert voltage to acceleration (g)
float voltage_to_acceleration(float voltage) {
    return (voltage - ZERO_G_VOLTAGE) / (SENSITIVITY / 1000.0);
}

// Kalman filter function
void kalman_filter(KalmanState *state, float measurement) {
    // Prediction step
    state->x = ALPHA * state->x + (1 - ALPHA) * state->x; // No process noise
    state->y = ALPHA * state->y + (1 - ALPHA) * state->y; // No process noise
    state->z = ALPHA * state->z + (1 - ALPHA) * state->z; // No process noise

    // Update step
    float kalman_gain_x = 1 - ALPHA * (measurement - state->x);
    float kalman_gain_y = 1 - ALPHA * (measurement - state->y);
    float kalman_gain_z = 1 - ALPHA * (measurement - state->z);

    state->x = kalman_gain_x * measurement;
    state->y = kalman_gain_y * measurement;
    state->z = kalman_gain_z * measurement;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    KalmanState kalman_state = {0.0, 0.0, 0.0}; // Initialize Kalman state

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        // Convert voltages to accelerations
        float x_acceleration = voltage_to_acceleration(x_voltage);
        float y_acceleration = voltage_to_acceleration(y_voltage);
        float z_acceleration = voltage_to_acceleration(z_voltage);

        // Apply Kalman filter
        kalman_filter(&kalman_state, x_acceleration);
        kalman_filter(&kalman_state, y_acceleration);
        kalman_filter(&kalman_state, z_acceleration);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", kalman_state.x, kalman_state.y, kalman_state.z);

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

