#define SENSOR3_GPIO 27

// Define the quiescent voltage of the DRV5055VA sensor
#define V_QUIESCENT 1.65

// Define the sensitivity of the DRV5055VA sensor (25 mV/mT = 0.025 V/mT)
#define SENSITIVITY 0.025

// Define the ADC resolution (simulated digital read)
#define ADC_RESOLUTION 2 // Assuming a simple HIGH/LOW read

// Global variable to indicate program termination
