    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        // Calculate magnetic field strengths
        float sensor1_mT = calculate_magnetic_field(sensor1_value);
        float sensor2_mT = calculate_magnetic_field(sensor2_value);
        float sensor3_mT = calculate_magnetic_field(sensor3_value);

        // Log the data
        log_data(sensor1_mT, sensor2_mT, sensor3_mT);

        // Check for out-of-range values and print warnings
        if (fabs(sensor1_mT) > 100.0 || fabs(sensor2_mT) > 100.0 || fabs(sensor3_mT) > 100.0) {
            fprintf(stderr, "Warning: Magnetic field value out of range!\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

