#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 command
#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED_MODE 0x80
#define MCP3008_DUMMY_BYTE 0x00

// Define CSV file name
#define CSV_FILE "sensor_data.csv"

// Global variables for cleanup
static int spi_fd = -1;
static FILE *csv_file = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int read_mcp3008_channel(int spi_fd, int channel);
int log_data(FILE *fp, int channel, int adc_value);
void cleanup(int spi_fd, FILE *fp);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    char device[20];
    uint8_t mode;
    uint8_t bits;
    uint32_t speed;
} spi_config_t;

// Function to initialize SPI
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd;
    uint8_t mode_flags[3];

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    mode_flags[0] = SPI_MODE;
    mode_flags[1] = mode;
    mode_flags[2] = 0; // Padding

    if (ioctl(fd, SPI_IOC_WR_MODE, mode_flags) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    mode_flags[0] = SPI_BITS_PER_WORD;
    mode_flags[1] = bits;
    mode_flags[2] = 0; // Padding

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, mode_flags) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    mode_flags[0] = SPI_SPEED;
    mode_flags[1] = 0; // No argument for max speed
    mode_flags[2] = 0; // Padding

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, mode_flags) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008 channel
int read_mcp3008_channel(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message
    tx_buf[0] = MCP3008_START_BIT;
    tx_buf[1] = MCP3008_SINGLE_ENDED_MODE | (channel << 4);
    tx_buf[2] = MCP3008_DUMMY_BYTE;

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value
    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

// Function to log data to CSV file
int log_data(FILE *fp, int channel, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, adc_value) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }
    return 0;
}

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup(spi_fd, csv_file);
    exit(0);
}

// Function to cleanup resources
void cleanup(int spi_fd, FILE *fp) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
}

int main() {
    int adc_value;
    int channel;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC values from channels 0, 1, and 2
        adc_value = read_mcp3008_channel(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading channel 0. Continuing.\n");
            continue;
        }
        channel = 0;
        if (log_data(csv_file, channel, adc_value) < 0) {
            fprintf(stderr, "Error logging data for channel 0. Continuing.\n");
        }

        adc_value = read_mcp3008_channel(spi_fd, 1);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading channel 1. Continuing.\n");
            continue;
        }
        channel = 1;
        if (log_data(csv_file, channel, adc_value) < 0) {
            fprintf(stderr, "Error logging data for channel 1. Continuing.\n");
        }

        adc_value = read_mcp3008_channel(spi_fd, 2);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading channel 2. Continuing.\n");
            continue;
        }
        channel = 2;
        if (log_data(csv_file, channel, adc_value) < 0) {
            fprintf(stderr, "Error logging data for channel 2. Continuing.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

