#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>
#include <pigpio.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds

// Global variables for signal handling and MQTT
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
void signal_handler(int signum);
int mqtt_connect_and_subscribe(struct mosquitto **mosq, const char *client_id, const char *host, int port, const char *topic, int qos);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_led_state(const char *payload);
int set_led_state(int state);
void log_error(const char *message);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        running = 0;
        if (mosq) {
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
        }
        mosquitto_lib_cleanup();
        gpioWrite(GPIO_PIN, 0); // Turn off LED
        gpioTerminate();
        exit(0);
    }
}

// MQTT connection and subscription function
int mqtt_connect_and_subscribe(struct mosquitto **mosq, const char *client_id, const char *host, int port, const char *topic, int qos) {
    int rc;

    *mosq = mosquitto_new(client_id, true, NULL);
    if (!*mosq) {
        log_error("Failed to create mosquitto instance");
        return 1;
    }

    mosquitto_connect_callback_set(*mosq, NULL);
    mosquitto_message_callback_set(*mosq, mqtt_message_callback);
    mosquitto_subscribe_callback_set(*mosq, NULL);

    rc = mosquitto_connect(*mosq, host, port, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(*mosq);
        *mosq = NULL;
        return 1;
    }

    rc = mosquitto_subscribe(*mosq, NULL, topic, qos);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to subscribe to MQTT topic");
        mosquitto_destroy(*mosq);
        *mosq = NULL;
        return 1;
    }

    return 0;
}

// MQTT message callback function
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        printf("Received message on topic '%s': %s\n", message->topic, (char *)message->payload);
        if (parse_led_state((char *)message->payload) != 0) {
            log_error("Invalid LED state received");
        }
    } else {
        log_error("Received empty message");
    }
}

// JSON parsing function
int parse_led_state(const char *payload) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error before: %s\n", error_ptr);
        }
        log_error("Failed to parse JSON payload");
        return 1;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBoolean(led_state)) {
        log_error("Invalid 'led_state' type");
        cJSON_Delete(json);
        return 1;
    }

    int led_state = cJSON_GetBooleanValue(led_state);
    if (led_state != 0 && led_state != 1) {
        log_error("Invalid 'led_state' value");
        cJSON_Delete(json);
        return 1;
    }

    cJSON_Delete(json);
    return 0;
}

// GPIO control function
int set_led_state(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        log_error("Failed to write to GPIO pin");
        return 1;
    }
    return 0;
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker with exponential backoff
    int reconnect_delay = 1;
    int max_reconnect_delay = MAX_RECONNECT_DELAY;
    int attempts = 0;
    while (running && attempts < 5) {
        if (mqtt_connect_and_subscribe(&mosq, MQTT_CLIENT_ID, MQTT_BROKER, MQTT_PORT, MQTT_TOPIC, 0) == 0) {
            printf("Connected to MQTT broker\n");
            break; // Exit reconnection loop on success
        } else {
            attempts++;
            log_error("MQTT connection failed, retrying...");
            sleep(reconnect_delay);
            reconnect_delay *= 2; // Exponential backoff
            if (reconnect_delay > max_reconnect_delay) {
                reconnect_delay = max_reconnect_delay;
            }
        }
    }

    if (!running) {
        printf("Exiting due to signal or connection failure\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int rc = mosquitto_loop(mosq, -1, 1); // -1 means loop forever
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop error");
            sleep(5); // Wait before retrying
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

