#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *sound_sensor_line;
struct gpiod_line *alarm_led_line;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
int request_gpio_line(struct gpiod_chip *chip, int pin);
int set_gpio_value(struct gpiod_line *line, int value);
int read_sound_sensor(void);
int trigger_alarm_led(void);
void cleanup_gpio(void);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signum);
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO chip
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", "gpiochip0");
        return -1;
    }

    return 0;
}

// Request GPIO line
int request_gpio_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, "sound_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %d\n", pin, ret);
        return -1;
    }

    return line;
}

// Set GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d value: %d\n", line->line_number, ret);
        return -1;
    }
    return 0;
}

// Read sound sensor
int read_sound_sensor(void) {
    int value = gpiod_line_get_value(sound_sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not read sound sensor value\n");
        return -1;
    }
    return value;
}

// Trigger alarm LED
int trigger_alarm_led(void) {
    for (int i = 0; i < 5; i++) {
        if (set_gpio_value(alarm_led_line, 1) < 0) {
            return -1;
        }
        usleep(1000000); // 1 second
        if (set_gpio_value(alarm_led_line, 0) < 0) {
            return -1;
        }
        usleep(1000000); // 1 second
    }
    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Request GPIO lines
    sound_sensor_line = request_gpio_line(chip, SOUND_SENSOR_PIN);
    alarm_led_line = request_gpio_line(chip, ALARM_LED_PIN);

    if (!sound_sensor_line || !alarm_led_line) {
        cleanup_gpio();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound sensor, exiting.\n");
            break;
        }

        printf("Sound Level: %d\n", sound_level);

        if (sound_level == 0) {
            printf("Sound detected! Triggering alarm.\n");
            if (trigger_alarm_led() < 0) {
                fprintf(stderr, "Error triggering alarm, exiting.\n");
                break;
            }
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

