    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Request GPIO lines
    sound_sensor_line = request_gpio_line(chip, SOUND_SENSOR_PIN);
    alarm_led_line = request_gpio_line(chip, ALARM_LED_PIN);

    if (!sound_sensor_line || !alarm_led_line) {
        cleanup_gpio();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound sensor, exiting.\n");
            break;
        }

        printf("Sound Level: %d\n", sound_level);

        if (sound_level == 0) {
            printf("Sound detected! Triggering alarm.\n");
            if (trigger_alarm_led() < 0) {
                fprintf(stderr, "Error triggering alarm, exiting.\n");
                break;
            }
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

