#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nSignal received (%d). Exiting gracefully.\n", signum);
}

// Function to log messages to a file
int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Function to read the vibration sensor value
int read_vibration_sensor(struct gpiod_chip *chip, struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Function to log the vibration event
int log_vibration_event(struct gpiod_chip *chip, struct gpiod_line *line) {
    char message[256];
    snprintf(message, sizeof(message), "Vibration detected!");
    if (log_message(message) != 0) {
        fprintf(stderr, "Error logging vibration event.\n");
        return -1;
    }
    return 0;
}

// Function to initiate system shutdown
int shutdown_system(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (system("sudo shutdown -h now") != 0) {
        perror("Error shutting down system");
        return -1;
    }
    return 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for falling-edge events
    ret = gpiod_line_request(line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE, "vibration-monitor");
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Wait for a falling-edge event
        ret = gpiod_line_event_wait(line, 0);
        if (ret < 0) {
            if (program_running) {
                perror("Error waiting for GPIO event");
            }
            break; // Exit loop on error
        }

        // Read the sensor value
        int sensor_value = read_vibration_sensor(chip, line);
        if (sensor_value < 0) {
            if (program_running) {
                fprintf(stderr, "Error reading sensor, exiting.\n");
                break;
            }
        }

        // Log the vibration event
        if (log_vibration_event(chip, line) != 0) {
            fprintf(stderr, "Error logging vibration event, exiting.\n");
            break;
        }

        // Initiate system shutdown
        if (shutdown_system(chip, line) != 0) {
            fprintf(stderr, "Error shutting down system, exiting.\n");
            break;
        }

        // Release the line and close the chip
        gpiod_line_release(line);
        gpiod_chip_close(chip);

        // Exit the program
        break;
    }

    // Clean up resources before exiting
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

