#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CALIB_E1 0xE1
#define BMP280_REG_DATA_PRESS_MSB 0xF7
#define BMP280_REG_DATA_PRESS_LSB 0xF8
#define BMP280_REG_DATA_PRESS_XLSB 0xF9
#define BMP280_REG_DATA_TEMP_MSB 0xFA
#define BMP280_REG_DATA_TEMP_LSB 0xFB
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
bmp280_calib_data calib;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bmp280();
int read_calibration_data(bmp280_calib_data *calib);
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, double t_fine, bmp280_calib_data calib);
double calculate_altitude(double pressure);
void log_data(double altitude);
void signal_handler(int signal);
int safe_i2c_read(int handle, uint8_t reg, uint8_t *data, int len);
int safe_i2c_write(int handle, uint8_t reg, uint8_t *data, int len);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the BMP280 sensor
int init_bmp280() {
    // Check if pigpio is initialized
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check BMP280 ID register
    uint8_t chip_id;
    if (safe_i2c_read(i2c_handle, BMP280_REG_RESET, &chip_id, 1) != 0) {
        fprintf(stderr, "Failed to read chip ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02x\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set control register (temperature oversampling x1, pressure oversampling x1, normal mode)
    uint8_t ctrl_meas = (0x03 << 5) | (0x03 << 2) | 0x03; //0b00100111
    if (safe_i2c_write(i2c_handle, BMP280_REG_CTRL_MEAS, &ctrl_meas, 1) != 0) {
        fprintf(stderr, "Failed to write to control register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(bmp280_calib_data *calib) {
    uint8_t data[26];
    if (safe_i2c_read(i2c_handle, BMP280_REG_CALIB_00, data, 26) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from the BMP280
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (safe_i2c_read(i2c_handle, BMP280_REG_DATA_PRESS_MSB, data, 6) != 0) {
        fprintf(stderr, "Failed to read raw data\n");
        return -1;
    }

    *pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    *temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    return 0;
}

// Function to compensate temperature using the BMP280 datasheet formulas
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, T;
    double adc_T = (double)raw_temperature;

    var1 = (adc_T / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    var2 = ((adc_T / 131072.0 - calib.dig_T1 / 8192.0) * (adc_T / 131072.0 - calib.dig_T1 / 8192.0)) * calib.dig_T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure using the BMP280 datasheet formulas
double compensate_pressure(int32_t raw_pressure, double t_fine, bmp280_calib_data calib) {
    double var1, var2, p;
    double adc_P = (double)raw_pressure;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (calib.dig_P4 * 65536.0);
    var1 = (calib.dig_P3 * var1 * var1 / 524288.0 + calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * calib.dig_P1;

    if (var1 == 0)
    {
        return 0; // avoid exception caused by division by zero
    }

    p = 1048576.0 - adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + calib.dig_P7) / 16.0;

    return p;
}

// Function to calculate altitude using the barometric formula
double calculate_altitude(double pressure) {
    double altitude = 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
    return altitude;
}

// Function to log data to a file
void log_data(double altitude) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("altitude_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, altitude);
    fclose(fp);
}

// Safe I2C read function with error handling
int safe_i2c_read(int handle, uint8_t reg, uint8_t *data, int len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }
    return 0;
}

// Safe I2C write function with error handling
int safe_i2c_write(int handle, uint8_t reg, uint8_t *data, int len) {
    int result = i2cWriteI2CBlockData(handle, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize BMP280 sensor
    if (init_bmp280() != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        return 1;
    }

    printf("BMP280 sensor initialized successfully\n");

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure, altitude;

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read raw data, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, calib);
        pressure = compensate_pressure(raw_pressure, temperature, calib);

        // Calculate altitude
        altitude = calculate_altitude(pressure);

        // Log data
        log_data(altitude);

        printf("Altitude: %.2f meters\n", altitude);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated\n");
    return 0;
}

