#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define VREF 3.3
#define LM35_SENSITIVITY 0.01 // 10 mV/°C
#define CIRCULAR_BUFFER_SIZE 120

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
void circular_buffer_init(CircularBuffer *cb);
void circular_buffer_add(CircularBuffer *cb, float value);
void circular_buffer_get(CircularBuffer *cb, float *values, int num_values);
void signal_handler(int signal);
void log_temperature(float temperature);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode + channel number
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature (°C)
float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float temperature = voltage / LM35_SENSITIVITY;
    return temperature;
}

// Function to initialize the circular buffer
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to add a value to the circular buffer
void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (cb->count < CIRCULAR_BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to get values from the circular buffer
void circular_buffer_get(CircularBuffer *cb, float *values, int num_values) {
    int start_index = cb->head;
    if (cb->count < num_values) {
        start_index = (start_index + cb->count) % CIRCULAR_BUFFER_SIZE;
    }
    for (int i = 0; i < num_values; i++) {
        values[i] = cb->buffer[(start_index + i) % CIRCULAR_BUFFER_SIZE];
    }
}

// Function to log temperature to the console
void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temp_log.dat", "wb+");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
    }

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    circular_buffer_init(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Log temperature
        log_temperature(temperature);

        // Add temperature to circular buffer
        circular_buffer_add(&temp_buffer, temperature);

        // Overwrite circular buffer to file
        if (log_file != NULL) {
            float temp_buffer_values[CIRCULAR_BUFFER_SIZE];
            circular_buffer_get(&temp_buffer, temp_buffer_values, CIRCULAR_BUFFER_SIZE);
            fwrite(temp_buffer_values, sizeof(float), CIRCULAR_BUFFER_SIZE, log_file);
            fflush(log_file); // Ensure data is written to file immediately
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    spiClose(spi_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

