#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Sensor Addresses
#define BH1750_ADDR 0x23
#define MAX4466_CHANNEL 0

// Global Variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
int spi_fd = -1;
FILE *log_file = NULL;

// Function Prototypes
int init_i2c(const char *bus, int addr);
int init_spi(const char *device, int mode, int bits_per_word);
int read_bh1750(int fd);
int read_max4466(int fd);
void log_data(FILE *fp, int lux, int adc_value);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize SPI
int init_spi(const char *device, int mode, int bits_per_word) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_local = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_local) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits_local = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_local) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    int speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read ambient light from BH1750
int read_bh1750(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting BH1750 address");
        return -1;
    }

    // Send start measurement command (High Resolution Mode)
    unsigned char start_cmd = 0x10;
    if (write(fd, &start_cmd, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    unsigned char data[2];
    if (read(fd, data, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    // Convert data to lux
    unsigned int raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2;

    return (int)lux;
}

// Function to read sound level from MAX4466
int read_max4466(int fd) {
    // MCP3008 configuration
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Start bit (1)
    tx_buf[0] = 0x01;

    // Single-ended mode (1), channel selection (0-7), don't care (0)
    tx_buf[1] = (0x08 | MAX4466_CHANNEL) << 4;

    // MSB first (0)
    tx_buf[2] = 0x00;

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to log data to file
void log_data(FILE *fp, int lux, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Light: [%d lux], Sound: [%d]\n", timestamp, lux, adc_value);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE, SPI_MODE_0, 8);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Starting data logging...\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        int lux = read_bh1750(i2c_fd);
        int adc_value = read_max4466(spi_fd);

        // Log data
        if (lux >= 0 && adc_value >= 0) {
            log_data(log_file, lux, adc_value);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, ERROR: Could not read sensor data\n", timestamp);
            fflush(log_file);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Data logging stopped.\n");
    return 0;
}

