#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nSignal received, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int initialize_gpio(struct gpiod_chip *chip, struct gpiod_line **line, int pin) {
    int ret;

    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", pin);
        return -1;
    }

    ret = gpiod_line_request(*line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %s\n", pin, strerror(-ret));
        gpiod_line_release(*line);
        return -1;
    }

    // Enable pull-down resistor
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.pull_config = GPIOD_LINE_REQUEST_PULL_DOWN;

    ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d with pull-down: %s\n", pin, strerror(-ret));
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not read GPIO line value: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

// Function to log the event to a file
int log_event(FILE *log_file, struct gpiod_line *line, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, line->line_number, state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to handle flame detection
void handle_flame_detection(struct gpiod_line *line, int state) {
    if (state == 1) {
        printf("ALARM: Flame detected!\n");
    }
}

// Function to cleanup GPIO resources
void cleanup(struct gpiod_line *line, struct gpiod_chip *chip, FILE *log_file) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Initialize the GPIO line
    if (initialize_gpio(chip, &line, GPIO_PIN) != 0) {
        cleanup(chip, NULL, NULL);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup(line, chip, NULL);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor(line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (sensor_value == 1) {
            handle_flame_detection(line, sensor_value);
        }

        log_event(log_file, line, sensor_value);

        sleep(1);
    }

    // Cleanup and exit
    cleanup(line, chip, log_file);
    return 0;
}

