#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and lines
#define GPIO_CHIP "gpiochip0"
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
int set_relay_state(int relay_pin, int state);
int cleanup_gpio(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
        program_running = 0; // Set flag to exit main loop
        cleanup_gpio();       // Release GPIO lines
        exit(0);             // Exit the program
    }
}

// Function to initialize the GPIO chip
int initialize_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line handles for each relay pin
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request output lines
    if (gpiod_line_request_output(relay1_line, "relay", 0) < 0 ||
        gpiod_line_request_output(relay2_line, "relay", 0) < 0 ||
        gpiod_line_request_output(relay3_line, "relay", 0) < 0 ||
        gpiod_line_request_output(relay4_line, "relay", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0; // Success
}

// Function to set the state of a relay
int set_relay_state(int relay_pin, int state) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(gpiod_chip_get_chip(gpiod_line_get_chip(relay1_line)), relay_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    return 0;
}

