#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 16
#define SOUND_THRESHOLD 500
#define DEBOUNCE_DELAY 200 // ms
#define LOG_FILE "sound_events.log"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void log_event(const char *timestamp);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1; // Indicate an error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log event to file
void log_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1; // Indicate failure
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    return 0; // Indicate success
}

// Cleanup function
void cleanup() {
    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    // Turn off LED
    gpioWrite(LED_GPIO, 0);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1; // Exit if initialization fails
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sound level
        int sound_level = read_mcp3008(0);

        if (sound_level < 0) {
            fprintf(stderr, "Error: Failed to read sound level\n");
            continue; // Skip to the next iteration
        }

        // Check if sound level exceeds threshold
        if (sound_level > SOUND_THRESHOLD) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log event
            log_event(timestamp);

            // Turn on LED
            gpioWrite(LED_GPIO, 1);

            // Wait for 500 ms
            gpioDelay(500000); // 500 ms = 500000 us

            // Turn off LED
            gpioWrite(LED_GPIO, 0);

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to us
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    printf("Sound sensor monitoring stopped.\n");
    return 0;
}

