#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for motor control
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain sensor calibration parameters
#define RAIN_THRESHOLD 5
#define RAIN_LEVEL_MIN 0
#define RAIN_LEVEL_MAX 10

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_SPEED 150

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_handle;
FILE *log_file;

// Function prototypes
int read_rain_sensor();
int map_adc_to_rain_level(int adc_value);
void control_motor(int rain_level);
void log_rain_data(int rain_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the rain sensor value from MCP3008
int read_rain_sensor() {
    int handle;
    char tx[3];
    char rx[3];

    handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return -1; // Indicate error
    }

    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | SPI_CHANNEL) << 4; // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    if (spiXfer(handle, tx, rx, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        spiClose(handle);
        return -1; // Indicate error
    }

    spiClose(handle);

    // Parse the ADC value from the received data
    int adc_value = ((rx[1] & 0x03) << 8) + rx[2];

    return adc_value;
}

// Function to map the ADC value to a rain level (0-10)
int map_adc_to_rain_level(int adc_value) {
    // Ensure ADC value is within the valid range
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    // Linearly map the ADC value to the rain level
    return RAIN_LEVEL_MIN + (int)(((float)(adc_value - RAIN_LEVEL_MIN) / (1023 - RAIN_LEVEL_MIN)) * (RAIN_LEVEL_MAX - RAIN_LEVEL_MIN));
}

// Function to control the motor based on the rain level
void control_motor(int rain_level) {
    if (rain_level >= RAIN_THRESHOLD) {
        // Close the window
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, MOTOR_SPEED);
        gpioDelay(3000); // Wait for 3 seconds
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, MOTOR_SPEED);
        gpioDelay(3000); // Wait for 3 seconds
    } else {
        // Open the window
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, MOTOR_SPEED);
        gpioDelay(3000); // Wait for 3 seconds
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, MOTOR_SPEED);
        gpioDelay(3000); // Wait for 3 seconds
    }
}

// Function to log the rain data to a file
void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to the file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(MOTOR_ENA, 255);
    gpioSetPWMfrequency(MOTOR_ENA, 1000); // 1 kHz

    // Open the log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int rain_level = map_adc_to_rain_level(read_rain_sensor());
        printf("Rain Level: %d\n", rain_level);
        log_rain_data(rain_level);
        control_motor(rain_level);
        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, 0); // Stop the motor
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

