#define DEBOUNCE_TIME 50 // milliseconds
#define LED_ON_TIME 500 // milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_adc();
void control_led(int state);
void log_detection();
void signal_handler(int signal);

