void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        program_running = 0;
        control_led(0); // Turn off LED
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO26 as input for microphone
    gpioSetMode(MIC_PIN, PI_INPUT);

    // Set GPIO16 as output for LED
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    for (int i = 0; i < 10; i++) {
        // Set the pin as output
        gpioSetMode(MIC_PIN, PI_OUTPUT);
        gpioWrite(MIC_PIN, 0); // Discharge capacitor

        // Set the pin as input
        gpioSetMode(MIC_PIN, PI_INPUT);

        // Measure the time it takes for the pin to go high
        int start_time = gpioTick();
        while (gpioRead(MIC_PIN) == 0 && (gpioTick() - start_time) < 10000) {
            // Wait for the pin to go high or timeout
        }

        if (gpioRead(MIC_PIN) == 1) {
            // Pin went high, measure the time it takes to go low
            start_time = gpioTick();
            while (gpioRead(MIC_PIN) == 1 && (gpioTick() - start_time) < 10000) {
                // Wait for the pin to go low or timeout
            }
            if (gpioRead(MIC_PIN) == 0) {
                // Pin went low, calculate ADC value based on time difference
                adc_value |= (1 << (9 - (gpioTick() - start_time) / 10000));
            }
        } else {
            // Pin didn't go high, return 0
            return 0;
        }
    }
    return adc_value;
}

// Function to control the LED
