            control_led(1); // Turn on LED
            log_detection();  // Log the detection
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            control_led(0); // Turn off LED after debounce
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

