#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to export the GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open(GPIO_PATH "/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        perror("gpio/export");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open(GPIO_PATH "/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        perror("gpio/unexport");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("gpio/direction");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the GPIO value
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("gpio/value");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        perror("gpio/value");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

