int log_distance(int distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

