int calculate_distance(int gpio_value) {
    float voltage = (float)gpio_value * 3.3; // Placeholder voltage conversion
    float distance = 26.0 / voltage - 6.0; // Distance calculation
    return (int)distance;
}

// Function to control the pet feeder based on the distance
void control_feeder(int distance) {
    if (distance < 200) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    int gpio_value;
    int distance;
    int retries = 3; // Number of retries for GPIO operations

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    while (retries > 0) {
        if (gpio_export(GPIO_PIN) == 0) {
            break;
        } else {
            fprintf(stderr, "Error exporting GPIO %d, retrying...\n", GPIO_PIN);
            sleep(1);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to export GPIO %d after multiple retries.\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    while (retries > 0) {
        if (gpio_set_direction(GPIO_PIN, "in") == 0) {
            break;
        } else {
            fprintf(stderr, "Error setting GPIO %d direction to input, retrying...\n", GPIO_PIN);
            sleep(1);
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input after multiple retries.\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read GPIO value
        retries = 3;
        while (retries > 0) {
            gpio_value = gpio_read(GPIO_PIN);
            if (gpio_value == -1) {
                fprintf(stderr, "Error reading GPIO %d value, retrying...\n", GPIO_PIN);
                sleep(1);
                retries--;
            } else {
                break;
            }
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to read GPIO %d value after multiple retries.\n", GPIO_PIN);
            sleep(1);
            continue; // Skip to the next iteration
        }

        // Calculate distance
        distance = calculate_distance(gpio_value);

        // Log distance
        if (log_distance(distance) == -1) {
            fprintf(stderr, "Error logging distance.\n");
        }

        // Control feeder
        control_feeder(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pin before exiting
    if (gpio_unexport(GPIO_PIN) == -1) {
        fprintf(stderr, "Error unexporting GPIO %d.\n", GPIO_PIN);
    }

    return 0;
}

