int control_pump(int gpio_pin, int state) {
    if (gpio_pin < 0) return -1; // Invalid GPIO pin

    if (gpio_pin != PUMP_GPIO) {
        fprintf(stderr, "Error: Pump GPIO pin mismatch. Expected %d, got %d\n", PUMP_GPIO, gpio_pin);
        return -1;
    }

    int ret = gpiod_line_set_value(pump_line, state);
    if (ret < 0) {
        perror("Error setting pump state");
        return -1;
    }
    return 0;
}

