#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CS_PIN 8
#define MCP3008_DIN_PIN 9
#define MCP3008_DOUT_PIN 10
#define MCP3008_CLK_PIN 11
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8

#define VREF 3300.0 // mV
#define ADC_RESOLUTION 1023.0
#define DRV5055_SENSITIVITY 100.0 // mV/mT
#define DRV5055_VCC 3300.0 // mV

#define LOG_FILE "magnetic_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int gpio_init(const char *chip_name, int line_num);
int gpio_set_value(int fd, int value);
int gpio_get_value(int fd, int *value);
int gpio_set_direction(int fd, const char *direction);
int gpio_get_direction(int fd, const char *direction);
int open_log_file(const char *filename);
int write_log_entry(FILE *fp, long epoch_ms, double magnetic_field);
void signal_handler(int sig);
int cleanup();

// SPI Initialization
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    int ret = ioctl(fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO Initialization
int gpio_init(const char *chip_name, int line_num) {
    int fd = gpiod_chip_open_by_name(chip_name);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chip_name, strerror(errno));
        return -1;
    }

    gpio_chip = gpiod_chip_get_fd(fd);
    if (!gpio_chip) {
        fprintf(stderr, "Error getting GPIO chip file descriptor: %s\n", strerror(errno));
        gpiod_chip_close(fd);
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, line_num);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", line_num, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    int ret = gpiod_line_request_output(gpio_line, "mcp3008_cs", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", line_num, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(int fd, int value) {
    int ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", value, strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO Get Value
int gpio_get_value(int fd, int *value) {
    int ret = gpiod_line_get_value(gpio_line, value);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d value: %s\n", value, strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO Set Direction
int gpio_set_direction(int fd, const char *direction) {
    int ret = gpiod_line_set_direction(gpio_line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d direction: %s\n", direction, strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO Get Direction
int gpio_get_direction(int fd, const char *direction) {
    int ret = gpiod_line_get_direction(gpio_line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d direction: %s\n", direction, strerror(errno));
        return -1;
    }
    return 0;
}

// Open Log File
int open_log_file(const char *filename) {
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

// Write Log Entry
int write_log_entry(FILE *fp, long epoch_ms, double magnetic_field) {
    if (fprintf(fp, "%ld,%.2f\n", epoch_ms, magnetic_field) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
int cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_chip != NULL) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_LINE) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    if (open_log_file(LOG_FILE) < 0) {
        fprintf(stderr, "Failed to open log file. Continuing without logging.\n");
    }

    // Main loop
    while (!terminate) {
        uint8_t tx_buf[3];
        uint8_t rx_buf[3];
        int adc_value;
        long epoch_ms;
        double magnetic_field;

        // MCP3008 configuration: single-ended, channel 0
        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
        tx_buf[2] = 0x00; // Don't care

        // Chip Select low
        if (gpio_set_value(gpio_line, 0) < 0) {
            fprintf(stderr, "Failed to set CS low. Continuing.\n");
            continue;
        }

        // SPI transfer
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed. Continuing.\n");
            continue;
        }

        // Chip Select high
        if (gpio_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Failed to set CS high. Continuing.\n");
            continue;
        }

        // Extract ADC value (10 bits)
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Calculate Vout_mV
        double vout_mV = (adc_value / ADC_RESOLUTION) * VREF * 1000.0;

        // Calculate magnetic field (mT)
        magnetic_field = ((vout_mV - 1650.0) / 100.0) * 1000.0;

        // Get epoch time
        epoch_ms = (long)time(NULL) * 1000;

        // Write to log file
        if (write_log_entry(log_file, epoch_ms, magnetic_field) < 0) {
            fprintf(stderr, "Failed to write to log file. Continuing.\n");
        }

        // Wait 500 ms
        usleep(500000); // 500 ms
    }

    // Cleanup
    cleanup();

    return 0;
}

