#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

static volatile int keep_running = 1;

void sigint_handler(int sig)
{
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

int main()
{
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int sensor1_value, sensor2_value;
    int debounce_samples[5] = {0, 0, 0, 0, 0};
    int debounce_count[2] = {0, 0};
    int i, majority;

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines as input
    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        perror("Error getting GPIO line 1");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        perror("Error getting GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as input
    if (gpiod_line_request_input(line1, "sensor1") < 0) {
        perror("Error requesting GPIO line 1 as input");
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line2, "sensor2") < 0) {
        perror("Error requesting GPIO line 2 as input");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read sensor values
        for (i = 0; i < 5; i++) {
            sensor1_value = gpiod_line_get_value(line1);
            if (sensor1_value < 0) {
                perror("Error reading sensor 1 value");
                break;
            }
            sensor2_value = gpiod_line_get_value(line2);
            if (sensor2_value < 0) {
                perror("Error reading sensor 2 value");
                break;
            }

            debounce_samples[i] = sensor1_value;
            debounce_samples[i] = (debounce_samples[i] == 0) ? 1 : 0; // Convert to 0/1
            debounce_samples[i] = sensor2_value;
            debounce_samples[i] = (debounce_samples[i] == 0) ? 1 : 0; // Convert to 0/1

            gpioDelay(2); // 2ms delay
        }

        // Determine majority value for each sensor
        majority = 0;
        for (i = 0; i < 5; i++) {
            if (debounce_samples[i] == 0) {
                majority = 1;
                break;
            }
        }

        // Log sensor states
