#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_COMMAND "libcamera-still -n -o /home/pi/security_cam/%Y%m%d_%H%M%S.jpg --width 1280 --height 720 --encoding jpeg"
#define IMAGE_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/motion_detector.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
}

int main() {
    int gpio_status;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];
    char log_message[256];
    pid_t child_pid;

    // Initialize syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully");

    // Configure GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    syslog(LOG_INFO, "GPIO %d configured as input with pull-down resistor", GPIO_PIN);

    // Main loop
    while (program_running) {
        gpio_status = gpioRead(GPIO_PIN);
        if (gpio_status == 1) {
            syslog(LOG_INFO, "Motion detected!");

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read GPIO to confirm motion
            if (gpioRead(GPIO_PIN) == 1) {
                // Construct filename
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(filename, sizeof(filename), IMAGE_DIR "%Y%m%d_%H%M%S.jpg", timeinfo);

                // Create image directory if it doesn't exist
                struct stat st = {0};
                if (stat(IMAGE_DIR, &st) == -1) {
                    if (mkdir(IMAGE_DIR, 0777) != 0) {
                        syslog(LOG_ERR, "Failed to create image directory");
                        continue; // Continue to next iteration
                    }
                    syslog(LOG_INFO, "Image directory created: %s", IMAGE_DIR);
                }

                // Execute libcamera-still in a child process
                child_pid = fork();
                if (child_pid == 0) {
                    // Child process
                    execlp("libcamera-still", "libcamera-still", "-n", "-o", IMAGE_DIR, filename, (char *)NULL);
                    perror("execlp failed");
                    exit(EXIT_FAILURE);
                } else if (child_pid < 0) {
                    syslog(LOG_ERR, "Fork failed");
                } else {
                    // Parent process
                    // Wait for child process to finish
                    int status = 0;
                    if (waitpid(child_pid, &status, 0) == -1) {
                        syslog(LOG_ERR, "Waitpid failed");
                    } else {
                        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
                            syslog(LOG_ERR, "libcamera-still failed with exit status %d", WEXITSTATUS(status));
                        } else {
                            syslog(LOG_INFO, "Image captured successfully: %s", filename);
                        }
                    }
                }
            }
        }
        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // Cleanup
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");
    closelog();

    return 0;
}

