#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEVICE_DEFAULT "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define TIMEOUT_SEC 2

// Structure to hold image data and file name
typedef struct {
    unsigned char *data;
    char filename[10];
} image_buffer_t;

// Global variables for signal handling
volatile sig_atomic_t stop_flag = 0;
int device_fd = -1;
image_buffer_t buffers[NUM_BUFFERS];

// Function prototypes
int open_device(const char *device_name);
int configure_device(int fd);
int capture_frame(int fd, unsigned char **buffer, size_t *buffer_size);
int save_image(unsigned char *buffer, size_t buffer_size, const char *filename);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, stopping...\n", sig);
        stop_flag = 1;
    }
}

// Function to open the V4L2 device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to configure the V4L2 device
int configure_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_DEFAULT);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    // Queue buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    return 0;
}

// Function to capture a frame
int capture_frame(int fd, unsigned char **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        if (errno == EAGAIN) {
            // EAGAIN means no buffer is available, wait for one
            select(NULL, NULL, NULL, NULL, NULL); // Wait for up to 0 seconds
            if (errno == EAGAIN) {
                fprintf(stderr, "Error: No buffer available after select\n");
                return -1;
            }
        } else {
            perror("Error dequeuing buffer");
            return -1;
        }
    }

    *buffer = (unsigned char *)buf.m.offset;
    *buffer_size = buf.m.bytesused;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to save the image to a PGM file
int save_image(unsigned char *buffer, size_t buffer_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
