        if (ret == -1) {
            perror("Error unmapping buffer");
        }
    }

    // Close file descriptors
    for (i = 0; i < frame_count; i++) {
        close(frame_fds[i]);
    }

    close(video_fd);

    printf("Cleanup complete.\n");
}

int main() {
    struct timeval tv;
    struct timeval start_time, current_time;
    long elapsed_time;
    unsigned char *frame_buffer;
    size_t frame_size;
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize V4L2
    if (init_v4l2(&video_fd, &FRAME_WIDTH, &FRAME_HEIGHT) < 0) {
        fprintf(stderr, "V4L2 initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(FRAME_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "0\n"); // Initial timestamp: 0 seconds
    fclose(log_file);

    // Main loop
    while (running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(video_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = 1; // Timeout after 1 second
        timeout.tv_usec = 0;

        ret = select(video_fd + 1, &readfds, NULL, NULL, &timeout);

        if (ret == -1) {
            perror("Error in select");
            break;
        } else if (ret == 0) {
            // Timeout occurred
            printf("Timeout waiting for frame.\n");
            continue;
        } else {
            // Frame is available
            if (capture_frame(video_fd, &frame_buffer, &frame_size) == 0) {
                // Get timestamp
                gettimeofday(&tv, NULL);
                elapsed_time = (tv.tv_sec - start_time.tv_sec) * 1000000L + (tv.tv_usec - start_time.tv_usec);

                // Log timestamp
                if (log_timestamp(FRAME_LOG_FILE, elapsed_time) != 0) {
                    fprintf(stderr, "Error logging timestamp.\n");
                }

                // Update start time for next frame
                gettimeofday(&start_time, NULL);
            } else {
                fprintf(stderr, "Error capturing frame.\n");
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

