#include <sys/types.h>

#define SERVER_IP "127.0.0.1" // Default server IP
#define SERVER_PORT 5000       // Default server port

#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_RATE 30
#define BUFFER_COUNT 4

// Structure to hold frame header information
typedef struct {
    uint32_t frame_index;
    uint32_t fragment_index;
    uint32_t total_fragments;
    uint32_t payload_size;
} FrameHeader;

// Structure to hold buffer information
typedef struct {
    void *start;
    size_t length;
} Buffer;

// Global variables
static int camera_fd = -1;
static int udp_socket = -1;
static int running = 1;

// Function prototypes
int init_camera(const char *device_name);
int mmap_camera_buffers(int fd, void **buffers, size_t *buffer_lengths);
int unmap_camera_buffers(void **buffers, size_t *buffer_lengths);
int capture_frame(Buffer *buffers, size_t *buffer_lengths, uint8_t **frame_data);
int send_udp_packet(void *data, size_t data_len, uint32_t frame_index, uint32_t fragment_index, uint32_t total_fragments, uint32_t payload_size);
void signal_handler(int signum);
void cleanup();

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        running = 0;
    }
}

// Initialize the camera
int init_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening camera device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying camera capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", device_name);
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting camera format");
        close(fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    struct v4l2_mmap_params mmap_params;
    memset(&mmap_params, 0, sizeof(mmap_params));
    mmap_params.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    mmap_params.memory = V4L2_MEMORY_MMAP;
    mmap_params.fmt.pix.width = FRAME_WIDTH;
    mmap_params.fmt.pix.height = FRAME_HEIGHT;
    mmap_params.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;

    if (ioctl(fd, VIDIOC_MMAP, &mmap_params) < 0) {
        perror("Error mapping camera buffers");
        close(fd);
        return -1;
    }

    return fd;
}

// Map the camera buffers
int mmap_camera_buffers(int fd, void **buffers, size_t *buffer_lengths) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
        buffer_lengths[i] = buf.length;
    }

    return 0;
}

// Unmap the camera buffers
int unmap_camera_buffers(void **buffers, size_t *buffer_lengths) {
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        if (munmap(buffers[i], buffer_lengths[i]) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    return 0;
}

// Capture a single frame
int capture_frame(Buffer *buffers, size_t *buffer_lengths, uint8_t **frame_data) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *frame_data = (uint8_t *)buffers[buf.index];
    return buf.bytesused;
}

// Send a UDP packet
int send_udp_packet(void *data, size_t data_len, uint32_t frame_index, uint32_t fragment_index, uint32_t total_fragments, uint32_t payload_size) {
    int sockfd;
    struct sockaddr_in servaddr;
    char header[256]; // Adjust size as needed
    size_t header_len = sizeof(uint32_t) * 4; // Frame index, fragment index, total fragments, payload size

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Create the header
    memcpy(header, &frame_index, sizeof(uint32_t));
    memcpy(header + sizeof(uint32_t), &fragment_index, sizeof(uint32_t));
    memcpy(header + sizeof(uint32_t) + sizeof(uint32_t), &total_fragments, sizeof(uint32_t));
    memcpy(header + sizeof(uint32_t) + sizeof(uint32_t) + sizeof(uint32_t), &payload_size, sizeof(uint32_t));

    // Calculate the number of fragments to send
    size_t fragment_size = (data_len + sizeof(uint32_t) * 3) / 65000;
    size_t num_fragments = (data_len + sizeof(uint32_t) * 3) / 65000 + 1; // +1 for the last fragment

    // Send the fragments
    for (size_t i = 0; i < num_fragments; ++i) {
        size_t fragment_len = fragment_size;
        if (i == num_fragments - 1) {
            fragment_len = data_len - (i * fragment_size);
        }

        size_t offset = i * fragment_size;
        size_t payload_len = fragment_len - sizeof(uint32_t) * 3;

        memcpy(header, &frame_index, sizeof(uint32_t));
        memcpy(header + sizeof(uint32_t), &fragment_index + i, sizeof(uint32_t));
        memcpy(header + sizeof(uint32_t) + sizeof(uint32_t), &total_fragments, sizeof(uint32_t));
        memcpy(header + sizeof(uint32_t) + sizeof(uint32_t) + sizeof(uint32_t), &payload_len, sizeof(uint32_t));

        if (sendto(sockfd, data + offset, payload_len, 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
            perror("Error sending UDP packet");
            close(sockfd);
            return -1;
        }
    }

    close(sockfd);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (camera_fd != -1) {
        if (unmap_camera_buffers(buffers, buffer_lengths) < 0) {
            perror("Error unmapping buffers during cleanup");
        }
        close(camera_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    camera_fd = init_camera("/dev/video0");
    if (camera_fd < 0) {
        fprintf(stderr, "Failed to initialize camera. Exiting.\n");
        return 1;
    }

    // Allocate memory for buffers
    void *buffers[BUFFER_COUNT];
    size_t buffer_lengths[BUFFER_COUNT];
    if (mmap_camera_buffers(camera_fd, buffers, buffer_lengths) < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        uint8_t *frame_data = NULL;
        size_t frame_size = 0;

        if (capture_frame(buffers, buffer_lengths, &frame_data) < 0) {
            fprintf(stderr, "Failed to capture frame. Continuing.\n");
            continue;
        }

        frame_size = frame_data ? frame_data[0] : 0; // Check if frame data is valid

        if (frame_size > 0) {
            for (int i = 0; i < BUFFER_COUNT; ++i) {
                if (send_udp_packet(frame_data + i * frame_size, frame_size, i, i, 1, frame_size) < 0) {
                    fprintf(stderr, "Failed to send UDP packet. Continuing.\n");
                }
            }
        }

        free(frame_data);
        frame_data = NULL; // Reset frame_data after freeing
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

