#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define PAN_LEFT_BUTTON 6
#define PAN_RIGHT_BUTTON 7
#define TILT_UP_BUTTON 8
#define TILT_DOWN_BUTTON 9

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define PWM period (Hz)
#define PWM_PERIOD 50

// Define PWM range (duty cycle)
#define PWM_RANGE 1000

// Define servo mid-position value
#define SERVO_MID_POSITION 75

// Define button polling interval (ms)
#define BUTTON_POLLING_INTERVAL 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pan_servo_line;
static struct gpiod_line *tilt_servo_line;
static struct gpiod_line *pan_left_button_line;
static struct gpiod_line *pan_right_button_line;
static struct gpiod_line *tilt_up_button_line;
static struct gpiod_line *tilt_down_button_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int gpio_set_direction(int pin, const char *direction);
int gpio_get_value(int pin);
int gpio_set_value(int pin, int value);
int gpio_request_line(struct gpiod_chip *chip, int pin, const char *direction);
int gpio_release_line(struct gpiod_line *line);
int gpio_set_edge(struct gpiod_line *line, const char *edge);
int generate_pwm(int pin, int duty_cycle);
int set_servo_position(int pin, int position);
void button_poll(void);
void signal_handler(int sig);

// Function to initialize GPIO lines
int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return -1;
    }

    pan_servo_line = gpio_request_line(chip, PAN_SERVO_PIN, "out");
    tilt_servo_line = gpio_request_line(chip, TILT_SERVO_PIN, "out");
    pan_left_button_line = gpio_request_line(chip, PAN_LEFT_BUTTON, "in");
    pan_right_button_line = gpio_request_line(chip, PAN_RIGHT_BUTTON, "in");
    tilt_up_button_line = gpio_request_line(chip, TILT_UP_BUTTON, "in");
    tilt_down_button_line = gpio_request_line(chip, TILT_DOWN_BUTTON, "in");

    if (!pan_servo_line || !tilt_servo_line || !pan_left_button_line ||
        !pan_right_button_line || !tilt_up_button_line || !tilt_down_button_line) {
        fprintf(stderr, "Error requesting GPIO line\n");
        goto cleanup;
    }

    if (gpio_set_direction(PAN_SERVO_PIN, "out") < 0 ||
        gpio_set_direction(TILT_SERVO_PIN, "out") < 0 ||
        gpio_set_direction(PAN_LEFT_BUTTON, "in") < 0 ||
        gpio_set_direction(PAN_RIGHT_BUTTON, "in") < 0 ||
        gpio_set_direction(TILT_UP_BUTTON, "in") < 0 ||
        gpio_set_direction(TILT_DOWN_BUTTON, "in") < 0) {
        fprintf(stderr, "Error setting GPIO direction\n");
        goto cleanup;
    }

    if (gpio_set_edge(pan_servo_line, "rising") < 0 ||
        gpio_set_edge(tilt_servo_line, "rising") < 0 ||
        gpio_set_edge(pan_left_button_line, "rising") < 0 ||
        gpio_set_edge(pan_right_button_line, "rising") < 0 ||
        gpio_set_edge(tilt_up_button_line, "rising") < 0 ||
        gpio_set_edge(tilt_down_button_line, "rising") < 0) {
        fprintf(stderr, "Error setting GPIO edge\n");
        goto cleanup;
    }

    return 0;

cleanup:
    if (pan_servo_line) gpio_release_line(pan_servo_line);
    if (tilt_servo_line) gpio_release_line(tilt_servo_line);
    if (pan_left_button_line) gpio_release_line(pan_left_button_line);
    if (pan_right_button_line) gpio_release_line(pan_right_button_line);
    if (tilt_up_button_line) gpio_release_line(tilt_up_button_line);
    if (tilt_down_button_line) gpio_release_line(tilt_down_button_line);
    if (chip) gpiod_chip_close(chip);
    return -1;
}

// Function to set the direction of a GPIO pin
int gpio_set_direction(int pin, const char *direction) {
    int ret = gpiod_line_set_direction(pin, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO direction for pin %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    return gpiod_line_get_value(pin);
}

// Function to set the value of a GPIO pin
int gpio_set_value(int pin, int value) {
    return gpiod_line_set_value(pin, value);
}

// Function to request a GPIO line
int gpio_request_line(struct gpiod_chip *chip, int pin, const char *direction) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line for pin %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for pin %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return line;
}

// Function to release a GPIO line
int gpio_release_line(struct gpiod_line *line) {
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to generate PWM signal
int generate_pwm(int pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle out of range (0-%d)\n", PWM_RANGE);
        return -1;
    }

    int period_ns = (PWM_PERIOD * 1000000) / PWM_RANGE;
    int on_time_ns = (duty_cycle * period_ns) / PWM_RANGE;
    int off_time_ns = period_ns - on_time_ns;

    if (gpio_set_value(pin, 1) < 0) return -1;
    if (gpio_set_value(pin, 0) < 0) return -1;

    struct timespec on_time = {0, on_time_ns};
    nanosleep(&on_time, NULL);

    struct timespec off_time = {0, off_time_ns};
    nanosleep(&off_time, NULL);

    return 0;
}

// Function to set the servo position
int set_servo_position(int pin, int position) {
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Error: Position out of range (0-%d)\n", PWM_RANGE);
        return -1;
    }

    return generate_pwm(pin, position);
}

// Function to poll buttons and adjust servo positions
void button_poll(void) {
    int pan_left = gpio_get_value(PAN_LEFT_BUTTON);
    int pan_right = gpio_get_value(PAN_RIGHT_BUTTON);
    int tilt_up = gpio_get_value(TILT_UP_BUTTON);
    int tilt_down = gpio_get_value(TILT_DOWN_BUTTON);

    int pan_position = SERVO_MID_POSITION;
    int tilt_position = SERVO_MID_POSITION;

    if (pan_left) {
        pan_position -= 5;
        if (pan_position < 25) pan_position = 25;
        if (pan_position > 125) pan_position = 125;
    } else if (pan_right) {
        pan_position += 5;
        if (pan_position < 25) pan_position = 25;
        if (pan_position > 125) pan_position = 125;
    }

    if (tilt_up) {
        tilt_position -= 5;
        if (tilt_position < 25) tilt_position = 25;
        if (tilt_position > 125) tilt_position = 125;
    } else if (tilt_down) {
        tilt_position += 5;
        if (tilt_position < 25) tilt_position = 25;
        if (tilt_position > 125) tilt_position = 125;
    }

    if (set_servo_position(PAN_SERVO_PIN, pan_position) < 0) {
        fprintf(stderr, "Error setting pan servo position\n");
    }
    if (set_servo_position(TILT_SERVO_PIN, tilt_position) < 0) {
        fprintf(stderr, "Error setting tilt servo position\n");
    }
}

// Signal handler for SIGINT
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        button_poll();
        usleep(BUTTON_POLLING_INTERVAL * 1000); // Poll every BUTTON_POLLING_INTERVAL ms
    }

    // Cleanup GPIO resources
    gpio_release_line(pan_servo_line);
    gpio_release_line(tilt_servo_line);
    gpio_release_line(pan_left_button_line);
    gpio_release_line(pan_right_button_line);
    gpio_release_line(tilt_up_button_line);
    gpio_release_line(tilt_down_button_line);
    gpiod_chip_close(chip);

    fprintf(stderr, "Program terminated gracefully\n");
    return 0;
}

