#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <sys/select.h>
#include <jpeglib.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75
#define TIMEOUT_SEC 2

// Structure to hold image data
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
static int fd = -1;
static buffer *buffers = NULL;
static unsigned int n_buffers = 0;
static unsigned int timeout = TIMEOUT_SEC * 1000; // Convert seconds to milliseconds
static volatile sig_atomic_t keep_running = 1;

// Signal handler for SIGINT
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

// Function to initialize the V4L2 device
int init_v4l2(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    // Map the buffers
    buffers = calloc(req.count, sizeof(buffer));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    for (unsigned int i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }

    return 0;
}

// Function to uninitialize the V4L2 device
void uninit_v4l2(int fd) {
    if (fd != -1) {
        if (buffers != NULL) {
            for (unsigned int i = 0; i < n_buffers; ++i) {
                if (munmap(buffers[i].start, buffers[i].length) < 0) {
                    perror("munmap");
                }
            }
            free(buffers);
        }
        close(fd);
    }
}

// Function to capture a single frame
int capture_frame(int fd, buffer *buffers, unsigned int n_buffers, unsigned char **frame_data, size_t *frame_size) {
    fd_set fds;
    struct timeval tv;
    int ret;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = timeout / 1000; // Convert seconds to milliseconds
    tv.tv_usec = (timeout % 1000) * 1000; // Convert milliseconds to microseconds

    ret = select(fd + 1, &fds, NULL, NULL, &tv);

    if (ret == -1) {
        perror("select");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout occurred\n");
        return -1;
    } else {
        // Dequeue a buffer
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("VIDIOC_DQBUF");
            return -1;
        }

        *frame_data = buffers[buf.index].start;
        *frame_size = buf.bytesused;

        // Requeue the buffer
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = buf.index; // Keep the same index

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }

        return 0;
    }
}

// Function to apply a 5x5 box blur filter with edge clamping
void apply_box_blur(unsigned char *input, unsigned char *output, size_t input_size) {
    for (int y = 0; y < IMAGE_HEIGHT; y++) {
        for (int x = 0; x < IMAGE_WIDTH; x++) {
            int sum = 0;
            for (int i = -2; i <= 2; i++) {
                for (int j = -2; j <= 2; j++) {
                    int index = y + i + (x + j) * IMAGE_WIDTH;
                    if (index >= 0 && index < input_size) {
                        sum += input[index];
                    }
                }
            }
            output[y * IMAGE_WIDTH + x] = sum / 25; // Average the sum
        }
    }
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb(unsigned char *yuyv, unsigned char *rgb, size_t input_size) {
    int i, j;
    unsigned char *y, *u, *v, *r, *g, *b;

    y = (unsigned char *)yuyv;
    r = (unsigned char *)rgb;
    for (i = 0; i < input_size; i += 6) {
        u = y + 1;
        v = y + 3;
        r[i] = (unsigned char)((y[i] * 1.333333f) + (u[i] * 0.333333f));
        g[i] = (unsigned char)((y[i + 1] * 1.333333f) + (v[i + 1] * 0.333333f));
        b[i] = (unsigned char)((y[i + 2] * 1.333333f) + (u[i + 2] * 0.333333f));
    }
}

// Function to save the image as JPEG
int save_jpeg(unsigned char *image_data, size_t image_size, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        perror("Error opening output JPEG file");
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = IMAGE_WIDTH;
    cinfo.image_height = IMAGE_HEIGHT;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = IMAGE_WIDTH * 3; // RGB

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image_data[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);

    return 0;
}

int main() {
    unsigned char *frame_data = NULL;
    size_t frame_size = 0;
    unsigned char *blurred_frame = NULL;
    size_t blurred_size = 0;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize V4L2 device
    if (init_v4l2(fd) < 0) {
        fprintf(stderr, "V4L2 initialization failed\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        if (capture_frame(fd, buffers, n_buffers, &frame_data, &frame_size) == 0) {
            // Convert YUYV to RGB
            yuyv_to_rgb(frame_data, blurred_frame, frame_size);

            // Apply box blur
            apply_box_blur(blurred_frame, blurred_frame, blurred_size);

            // Save as JPEG
            if (save_jpeg(blurred_frame, blurred_size, filename) != 0) {
                fprintf(stderr, "JPEG save failed\n");
            } else {
                printf("Saved image: %s\n", filename);
            }

            free(frame_data);
            free(blurred_frame);
        } else {
            fprintf(stderr, "Frame capture failed\n");
        }
    }

    // Uninitialize V4L2 device
    uninit_v4l2(fd);

    return EXIT_SUCCESS;
}

