#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <unistd.h>

#define DEVICE_PATH "/dev/video0"
#define MAX_RESOLUTIONS 10
#define MAX_FRAME_INTERVALS 10

// Structure to hold camera capabilities
typedef struct {
    int index;
    struct v4l2_frmsizeenum *framesizes;
    int count;
} frame_sizes_t;

typedef struct {
    int index;
    struct v4l2_frmintrvlenum *intervals;
    int count;
} frame_intervals_t;

// Function to handle errors
void error_exit(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

// Function to initialize the camera device
int init_camera(int fd) {
    struct v4l2_capability cap;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, frame_sizes_t *frame_sizes) {
    struct v4l2_frmsizeenum *enum_framesizes;
    struct v4l2_frmsizeenum *frame;

    enum_framesizes = (struct v4l2_frmsizeenum *)malloc(sizeof(struct v4l2_frmsizeenum));
    if (enum_framesizes == NULL) {
        perror("malloc");
        return -1;
    }

    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, enum_framesizes) == -1) {
        perror("VIDIOC_ENUM_FRAMESIZES");
        free(enum_framesizes);
        return -1;
    }

    frame_sizes->count = 0;
    frame_sizes->framesizes = (struct v4l2_frmsizeenum *)malloc(sizeof(struct v4l2_frmsizeenum) * MAX_RESOLUTIONS);
    if (frame_sizes->framesizes == NULL) {
        perror("malloc");
        free(enum_framesizes);
        return -1;
    }

    frame_sizes->framesizes[0].index = 0;
    frame_sizes->framesizes[0].pad = 0;

    for (int i = 1; i < MAX_RESOLUTIONS; i++) {
        frame = &enum_framesizes[i];
        if (ioctl(fd, VIDIOC_G_FRAMESIZE, &frame->value) == -1) {
            perror("VIDIOC_G_FRAMESIZE");
            free(enum_framesizes);
            free(frame_sizes->framesizes);
            return -1;
        }
        frame_sizes->framesizes[i].index = i;
        frame_sizes->framesizes[i].pad = 0;
    }

    free(enum_framesizes);
    return 0;
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(int fd, frame_intervals_t *frame_intervals) {
    struct v4l2_frmintrvlenum *enum_frameintervals;
    struct v4l2_frmintrvlenum *interval;

    enum_frameintervals = (struct v4l2_frmintrvlenum *)malloc(sizeof(struct v4l2_frmintrvlenum));
    if (enum_frameintervals == NULL) {
        perror("malloc");
        return -1;
    }

    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, enum_frameintervals) == -1) {
        perror("VIDIOC_ENUM_FRAMEINTERVALS");
        free(enum_frameintervals);
        return -1;
    }

    frame_intervals->count = 0;
    frame_intervals->intervals = (struct v4l2_frmintrvlenum *)malloc(sizeof(struct v4l2_frmintrvlenum) * MAX_FRAME_INTERVALS);
    if (frame_intervals->intervals == NULL) {
        perror("malloc");
        free(enum_frameintervals);
        return -1;
    }

    interval = &enum_frameintervals[0];
    frame_intervals->intervals[0].index = 0;
    frame_intervals->intervals[0].pad = 0;

    for (int i = 1; i < MAX_FRAME_INTERVALS; i++) {
        if (ioctl(fd, VIDIOC_G_FRAME_INTERVAL, &interval->value) == -1) {
            perror("VIDIOC_G_FRAME_INTERVAL");
            free(enum_frameintervals);
            free(frame_intervals->intervals);
            return -1;
        }
        frame_intervals->intervals[i].index = i;
        frame_intervals->intervals[i].pad = 0;
    }

    free(enum_frameintervals);
    return 0;
}

// Function to check autofocus support
int check_autofocus_support(int fd) {
    struct v4l2_control ctrl;
    struct v4l2_ctrl *focus_auto;

    focus_auto = (struct v4l2_ctrl *)malloc(sizeof(struct v4l2_ctrl));
    if (focus_auto == NULL) {
        perror("malloc");
        return -1;
    }

    focus_auto->id = V4L2_CID_FOCUS_AUTO;
    focus_auto->type = V4L2_CTRL_TYPE_INTEGER;
    focus_auto->min = 0;
    focus_auto->max = 1;
    focus_auto->step = 1;

    if (ioctl(fd, VIDIOC_QUERYCTRL, focus_auto) == -1) {
        perror("VIDIOC_QUERYCTRL");
        free(focus_auto);
        return -1;
    }

    if (focus_auto->flags & V4L2_CTRL_FLAG_READWRITE) {
        return 1; // Autofocus supported
    } else {
        return 0; // Autofocus not supported
    }

    free(focus_auto);
    return 0;
}

// Function to print camera capabilities
void print_capabilities(int fd, const char *caption) {
    struct v4l2_capability cap;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return;
    }

    printf("%s", caption);
    printf("  Vendor: %s\n", cap.vendor);
    printf("  Device: %s\n", cap.device);
    printf("  Card: %s\n", cap.card);
    printf("  Bus Info: %s\n", cap.bus_info);
    printf("  Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("  Capabilities: %x\n", cap.capabilities);
}

// Function to print frame sizes
void print_frame_sizes(int fd, const char *caption) {
    frame_sizes_t frame_sizes;
    if (enumerate_frame_sizes(fd, &frame_sizes) == -1) {
        fprintf(stderr, "Failed to enumerate frame sizes\n");
        return;
    }

    printf("%s", caption);
    for (int i = 0; i < frame_sizes.count; i++) {
        printf("  %d: %dx%d\n", i, frame_sizes.framesizes[i].width, frame_sizes.framesizes[i].height);
    }
}

// Function to print frame intervals
void print_frame_intervals(int fd, const char *caption) {
    frame_intervals_t frame_intervals;
    if (enumerate_frame_intervals(fd, &frame_intervals) == -1) {
        fprintf(stderr, "Failed to enumerate frame intervals\n");
        return;
    }

    printf("%s", caption);
    for (int i = 0; i < frame_intervals.count; i++) {
        printf("  %d: %d\n", i, frame_intervals.intervals[i].value);
    }
}

int main() {
    int fd;
    const char *autofocus_support;

    fd = open(DEVICE_PATH, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        error_exit("Failed to open device");
    }

    if (init_camera(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Camera Capabilities:\n");
    print_capabilities(fd, "Camera Capabilities");

    printf("\nFrame Sizes:\n");
    print_frame_sizes(fd, "Frame Sizes");

    printf("\nFrame Intervals:\n");
    print_frame_intervals(fd, "Frame Intervals");

    autofocus_support = check_autofocus_support(fd) ? "Supported" : "Not Supported";
    printf("\nAutofocus Support: %s\n", autofocus_support);

    close(fd);
    return EXIT_SUCCESS;
}

