#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define servo center position
#define CENTER_PULSE_WIDTH 1500

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to set servo position
void set_servo_position(int gpio, int pulse_width) {
    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error setting servo position on GPIO %d\n", gpio);
    }
}

// Function to move servo in a given direction
void move_servo(int gpio, int direction, int steps, int delay_ms) {
    int pulse_width = CENTER_PULSE_WIDTH;
    int current_pulse_width = CENTER_PULSE_WIDTH;
    int increment = 10; // 10 microseconds

    if (direction == 1) { // Increment
        while (current_pulse_width <= MAX_PULSE_WIDTH && program_running) {
            current_pulse_width += increment;
            if (current_pulse_width > MAX_PULSE_WIDTH) {
                current_pulse_width = MAX_PULSE_WIDTH;
            }
            set_servo_position(gpio, current_pulse_width);
            gpioDelay(delay_ms * 1000); // Delay in microseconds
        }
    } else if (direction == -1) { // Decrement
        while (current_pulse_width >= MIN_PULSE_WIDTH && program_running) {
            current_pulse_width -= increment;
            if (current_pulse_width < MIN_PULSE_WIDTH) {
                current_pulse_width = MIN_PULSE_WIDTH;
            }
            set_servo_position(gpio, current_pulse_width);
            gpioDelay(delay_ms * 1000); // Delay in microseconds
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Startup message
    printf("Pan-Tilt Camera Control System\n");
    printf("GPIO Pin Assignments:\n");
    printf("  Pan Servo: GPIO %d\n", PAN_SERVO_PIN);
    printf("  Tilt Servo: GPIO %d\n", TILT_SERVO_PIN);
    printf("  UP Button: GPIO %d\n", UP_BUTTON_PIN);
    printf("  DOWN Button: GPIO %d\n", DOWN_BUTTON_PIN);
    printf("  LEFT Button: GPIO %d\n", LEFT_BUTTON_PIN);
    printf("  RIGHT Button: GPIO %d\n", RIGHT_BUTTON_PIN);
    printf("Center Position: 1500 microseconds\n");

    // Main loop
    while (program_running) {
        // Check button states
        if (gpioRead(UP_BUTTON_PIN) == 0) {
            move_servo(PAN_SERVO_PIN, 1, 50, 50); // Move pan up
        } else if (gpioRead(DOWN_BUTTON_PIN) == 0) {
            move_servo(PAN_SERVO_PIN, -1, 50, 50); // Move pan down
        } else if (gpioRead(LEFT_BUTTON_PIN) == 0) {
            move_servo(TILT_SERVO_PIN, 1, 50, 50); // Move tilt left
        } else if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
            move_servo(TILT_SERVO_PIN, -1, 50, 50); // Move tilt right
        }

        gpioDelay(50); // Delay for 50 ms
    }

    // Cleanup
    gpioServo(PAN_SERVO_PIN, 0); // Stop pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop tilt servo
    gpioTerminate(); // Terminate pigpio

    return 0;
}

