#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>
#include <curl/curl.h>

#define MOTION_CAPTURE_DIR "motion_captures"
#define DEBOUNCE_TIME 2 // seconds
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 8080 // Replace with your server port

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Structure to hold the JSON payload
typedef struct {
    char filename[256];
    char timestamp[32];
    char motion_status[8];
    char gpio_pin[8];
} json_payload_t;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to create the motion capture directory
int create_motion_capture_directory() {
    struct stat st = {0};
    if (stat(MOTION_CAPTURE_DIR, &st) == -1) {
        if (mkdir(MOTION_CAPTURE_DIR, 0777) == -1) {
            fprintf(stderr, "Error creating motion capture directory: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to capture a JPEG image using libcamera-still
int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 --quality 85", filename);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing libcamera-still command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to format the ISO 8601 timestamp with microseconds
void format_iso8601_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), 32 - strlen(timestamp), ".%06ldZ", ts.tv_nsec / 1000);
}

// Function to create the JSON payload
int create_json_payload(const char *filename, const char *timestamp, const char *motion_status, const char *gpio_pin, json_payload_t *payload) {
    strncpy(payload->filename, filename, sizeof(payload->filename) - 1);
    payload->filename[sizeof(payload->filename) - 1] = '\0'; // Ensure null termination
    format_iso8601_timestamp(payload->timestamp);
    strncpy(payload->motion_status, motion_status, sizeof(payload->motion_status) - 1);
    payload->motion_status[sizeof(payload->motion_status) - 1] = '\0';
    strncpy(payload->gpio_pin, gpio_pin, sizeof(payload->gpio_pin) - 1);
    payload->gpio_pin[sizeof(payload->gpio_pin) - 1] = '\0';
    return 0;
}

// Function to send the JSON payload using libcurl
int send_json_payload(const json_payload_t *payload) {
    CURL *curl;
    CURLcode res;
    char json_payload[512];

    // Create the JSON payload string
    snprintf(json_payload, sizeof(json_payload), "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":\"%s\",\"gpio_pin\":\"%s\"}",
             payload->filename, payload->timestamp, payload->motion_status, payload->gpio_pin);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_IP ":" SERVER_PORT);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "Error initializing libcurl\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <server_ip>:<server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip_port = argv[1];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-down resistor
    gpioSetMode(17, PI_INPUT);
    gpioSetPullUpDown(17, PI_PUD_DOWN);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create the motion capture directory
    if (create_motion_capture_directory() != 0) {
        gpioTerminate();
        return 1;
    }

    int last_motion_state = 0; // 0 = no motion, 1 = motion
    time_t last_motion_time = 0;

    printf("Motion detection started.  Monitoring GPIO %d...\n", 17);

    while (!terminate) {
        int motion_state = gpioRead(17);

        if (motion_state == 1 && last_motion_state == 0) {
            // Motion detected
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= DEBOUNCE_TIME) {
                printf("Motion detected!\n");

                // Capture image
                if (capture_image("motion_capture.jpg") == 0) {
                    printf("Image captured successfully.\n");
                } else {
                    fprintf(stderr, "Failed to capture image.\n");
                }

                // Create JSON payload
                json_payload_t json_payload;
                create_json_payload("motion_capture.jpg", "", "motion", "17", &json_payload);

                // Send JSON payload
                if (send_json_payload(&json_payload) != 0) {
                    fprintf(stderr, "Failed to send JSON payload.\n");
                }
            }
            last_motion_time = now;
        }

        last_motion_state = motion_state;
        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    gpioTerminate();
    printf("Motion detection stopped.\n");
    return 0;
}

