#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define MOTION_LOG_FILE "/home/pi/motion_capture.log"
#define IMAGES_DIR "/home/pi/images"
#define DEBOUNCE_MS 50
#define CAPTURE_COMMAND "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int generate_filename(char *filename, size_t filename_size);
int capture_image(const char *filename);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup(void);

// GPIO Initialization
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(gpio_line, "motion_capture", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Direction Setting
int gpio_set_direction(int pin, const char *direction) {
    if (gpiod_line_set_direction(gpio_line, direction) < 0) {
        perror("Error setting GPIO direction");
        return -1;
    }
    return 0;
}

// GPIO Reading
int gpio_read(int pin) {
    int value = gpiod_line_get_value(gpio_line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Filename Generation
int generate_filename(char *filename, size_t filename_size) {
    time_t timer;
    struct tm *tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(filename, filename_size, "%Y%m%d_%H%M%S", tm_info);
    return 0;
}

// Image Capture
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), CAPTURE_COMMAND, filename);

    int status = system(command);
    if (status == -1) {
        perror("Error executing capture command");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still command failed with exit code %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Logging
int log_event(const char *message) {
    time_t timer;
    struct tm *tm_info;
    char timestamp[20];

    time(&timer);
    tm_info = localtime(&timer);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Cleanup
void cleanup(void) {
    printf("Cleaning up...\n");
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(MOTION_LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_event("Motion capture system started.");

    // Main loop
    while (!terminate) {
        int motion_detected = gpio_read(GPIO_PIN);
        if (motion_detected < 0) {
            fprintf(stderr, "Error reading GPIO. Exiting.\n");
            break;
        }

        if (motion_detected == 1) {
            char filename[64];
            if (generate_filename(filename, sizeof(filename)) == 0) {
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Motion detected. Capturing image: %s", filename);
                log_event(log_message);

                if (capture_image(filename) == 0) {
                    log_event("Image captured successfully.");
                } else {
                    log_event("Image capture failed.");
                }
            } else {
                log_event("Error generating filename.");
            }
        }

        usleep(100000); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

