        perror("Error executing capture command");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still command failed with exit code %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Logging
int log_event(const char *message) {
    time_t timer;
    struct tm *tm_info;
    char timestamp[20];

    time(&timer);
    tm_info = localtime(&timer);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Cleanup
void cleanup(void) {
    printf("Cleaning up...\n");
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(MOTION_LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_event("Motion capture system started.");

    // Main loop
    while (!terminate) {
        int motion_detected = gpio_read(GPIO_PIN);
        if (motion_detected < 0) {
            fprintf(stderr, "Error reading GPIO. Exiting.\n");
            break;
        }

        if (motion_detected == 1) {
            char filename[64];
            if (generate_filename(filename, sizeof(filename)) == 0) {
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Motion detected. Capturing image: %s", filename);
                log_event(log_message);

                if (capture_image(filename) == 0) {
                    log_event("Image captured successfully.");
                } else {
                    log_event("Image capture failed.");
                }
            } else {
                log_event("Error generating filename.");
            }
        }

        usleep(100000); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

