// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables
static int fd = -1; // File descriptor
static buffer_t *buffers = NULL; // Array of buffers
static unsigned int n_buffers = 0; // Number of buffers
static int running = 1; // Flag to control the main loop

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

// Function to initialize the V4L2 device
int init_v4l2() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(buffers);
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fd_set fds;
    struct timeval tv;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Streaming interrupted by signal, retrying...\n");
            return -1; // Retry
        }
        perror("Error in select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    } else {
        return 0;
    }
}

// Function to stop streaming
void stop_streaming() {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
        }
    }
    if (close(fd) < 0) {
        perror("Error closing device");
    }
    if (buffers) {
        free(buffers);
    }
}

// Function to crop the frame
int crop_frame(const void *src, void *dest, size_t dest_size) {
    size_t src_size = WIDTH * HEIGHT * 2 / 4; // YUYV is 2 bytes per pixel
    size_t dest_offset = CROP_X_OFFSET * 2 + CROP_Y_OFFSET * 2;

    if (src_size != dest_size) {
        fprintf(stderr, "Error: Source and destination sizes do not match.\n");
        return -1;
    }

    size_t bytes_to_copy = src_size;
    size_t bytes_copied = 0;

    while (bytes_to_copy > 0 && bytes_copied < dest_size) {
        // Copy a macroblock (Y0, U, Y1, V)
        memcpy(dest + dest_offset + bytes_copied, src + bytes_to_copy - 4, 4); // Copy 4 bytes (Y0, U, Y1, V)
        bytes_copied += 4;
        bytes_to_copy -= 4;
        dest_offset += 4;
    }

    return 0;
}

// Function to save the cropped frame to a file
int save_frame(const void *data, size_t size) {
    FILE *fp = fopen("cropped.yuv", "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(data, 1, size, fp);
    if (bytes_written != size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
