            for (unsigned int i = 0; i < n_buffers; ++i) {
                if (munmap(buffers[i].start, buffers[i].length) < 0) {
                    perror("Error unmapping buffer");
                    break; // Exit loop on error
                }
            }

            if (buffers) {
                free(buffers);
            }

            // Process the captured frame
            void *cropped_frame = NULL;
            size_t cropped_frame_size = WIDTH * HEIGHT * 2 / 4; // YUYV is 2 bytes per pixel
            void *dest = NULL;
            size_t dest_size = CROP_WIDTH * CROP_HEIGHT * 2; // 200 * 150 * 2 bytes

            // Allocate memory for the cropped frame
            cropped_frame = malloc(cropped_frame_size);
            if (!cropped_frame) {
                perror("Error allocating memory for cropped frame");
                break; // Exit loop on error
            }

            // Allocate memory for the destination buffer
            dest = malloc(dest_size);
            if (!dest) {
                perror("Error allocating memory for destination buffer");
                free(cropped_frame);
                break; // Exit loop on error
            }

            // Copy the captured frame to the cropped frame
            if (crop_frame(buffers[0].start, cropped_frame, cropped_frame_size) < 0) {
                free(cropped_frame);
                free(dest);
                break; // Exit loop on error
            }

            // Save the cropped frame to a file
            if (save_frame(cropped_frame, cropped_frame_size) < 0) {
                free(cropped_frame);
                free(dest);
                break; // Exit loop on error
            }

            printf("Cropped frame saved to cropped.yuv\n");
        }
    }

    stop_streaming();
    printf("Streaming stopped.\n");

    return EXIT_SUCCESS;
}

