#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define neutral angle (90 degrees)
#define NEUTRAL_ANGLE 90

// Define angle increment (5 degrees)
#define ANGLE_INCREMENT 5

// Define angle limits (0 to 180 degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Global variables for pan and tilt angles
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
int initialize_gpio();
void set_pan_angle(int angle);
void set_tilt_angle(int angle);
void handle_user_input();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes for pan and tilt servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency for both servos
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Function to set the pan angle using hardware PWM
void set_pan_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Pan angle out of range (0-180)\n");
        return;
    }

    // Calculate pulse width based on angle (linear mapping)
    int pulse_width = (int)(NEUTRAL_ANGLE + (angle - NEUTRAL_ANGLE) * (2500.0 / 180.0));

    // Set the PWM duty cycle
    gpioPWM(PAN_GPIO, pulse_width);
}

// Function to set the tilt angle using hardware PWM
void set_tilt_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Tilt angle out of range (0-180)\n");
        return;
    }

    // Calculate pulse width based on angle (linear mapping)
    int pulse_width = (int)(NEUTRAL_ANGLE + (angle - NEUTRAL_ANGLE) * (2500.0 / 180.0));

    // Set the PWM duty cycle
    gpioPWM(TILT_GPIO, pulse_width);
}

// Function to handle user input and update pan and tilt angles
void handle_user_input() {
    int input;

    while ((input = getchar()) != EOF) {
        switch (input) {
            case 'p':
                pan_angle += ANGLE_INCREMENT;
                if (pan_angle > MAX_ANGLE) {
                    pan_angle = MAX_ANGLE;
                }
                set_pan_angle(pan_angle);
                break;
            case 'm':
                pan_angle -= ANGLE_INCREMENT;
                if (pan_angle < MIN_ANGLE) {
                    pan_angle = MIN_ANGLE;
                }
                set_pan_angle(pan_angle);
                break;
            case 't':
                tilt_angle += ANGLE_INCREMENT;
                if (tilt_angle > MAX_ANGLE) {
                    tilt_angle = MAX_ANGLE;
                }
                set_tilt_angle(tilt_angle);
                break;
            case 'b':
                tilt_angle -= ANGLE_INCREMENT;
                if (tilt_angle < MIN_ANGLE) {
                    tilt_angle = MIN_ANGLE;
                }
                set_tilt_angle(tilt_angle);
                break;
            case 'q':
                set_pan_angle(NEUTRAL_ANGLE);
                set_tilt_angle(NEUTRAL_ANGLE);
                break;
            default:
                // Ignore other inputs
                break;
        }
        gpioDelay(100); // Delay to prevent excessive CPU usage
    }
}

// Function to cleanup GPIO and terminate pigpio
void cleanup_gpio() {
    gpioPWM(PAN_GPIO, 0); // Stop PWM on pan servo
    gpioPWM(TILT_GPIO, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Pan-Tilt Camera Control\n");
    printf("Enter 'p'/'m'/'t'/'b' to adjust pan/tilt angles, 'q' to quit.\n");

    // Main loop to handle user input
    while (1) {
        handle_user_input();
    }

    return 0;
}

