// Function to read CPU usage from /proc/stat
float read_cpu_usage()
{
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long total_cpu_time;
    float cpu_usage = -1.0; // Default value in case of error

    fp = fopen("/proc/stat", "r");
    if (fp == NULL)
    {
        fprintf(stderr, "Error opening CPU stats file: %s\n", strerror(errno));
        return -1.0;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10)
    {
        fprintf(stderr, "Error reading CPU stats file: %s\n", strerror(errno));
        fclose(fp);
        return -1.0;
    }

    fclose(fp);

    total_cpu_time = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;

    // Calculate CPU usage as a percentage
    cpu_usage = ((float)(total_cpu_time - idle - iowait)) / (total_cpu_time - idle - iowait) * 100.0;
