#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for the water flow sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define SENSOR3_GPIO 19

// Define I2C bus and address for the LCD
#define I2C_BUS 1
#define LCD_ADDR 0x27

// Define LCD constants
#define LCD_CHR 1
#define LCD_CMD 0

#define LCD_LINE_1 0x80 // LCD RAM address for the 1st line
#define LCD_LINE_2 0xC0 // LCD RAM address for the 2nd line

#define LCD_BACKLIGHT 0x08  // On
// LCD_BACKLIGHT = 0x00  # Off

#define ENABLE 0b00000100 // Enable bit

// Global variables
volatile int pulse_count1 = 0;
volatile int pulse_count2 = 0;
volatile int pulse_count3 = 0;
float flow_rate1 = 0.0;
float flow_rate2 = 0.0;
float flow_rate3 = 0.0;
float total_volume = 0.0;
int i2c_handle;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);
void lcd_init();
void lcd_clear();
void lcd_print(int row, const char *text);
void lcd_set_cursor(int row);
void lcd_send_command(unsigned char cmd);
void lcd_send_data(unsigned char data);
void lcd_print_float(float value);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    i2cClose(i2c_handle);
    exit(0);
}

// Interrupt handler for water flow sensors
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        int pulse_count;
        if (gpio == SENSOR1_GPIO) {
            pulse_count = pulse_count1;
        } else if (gpio == SENSOR2_GPIO) {
            pulse_count = pulse_count2;
        } else if (gpio == SENSOR3_GPIO) {
            pulse_count = pulse_count3;
        } else {
            fprintf(stderr, "Error: Invalid GPIO pin in pulse_counter\n");
            return;
        }
        pulse_count++;
    }
}

// LCD initialization function
void lcd_init() {
    // Initialise display
    gpioDelay(15); // Wait for more than 15 ms after VCC rises to 4.5V
    gpioDelay(5);  // Wait for more than 4.1 ms
    gpioSetMode(25, PI_OUTPUT); // RS
    gpioSetMode(24, PI_OUTPUT); // EN
    gpioSetMode(23, PI_OUTPUT); // D4
    gpioSetMode(17, PI_OUTPUT); // D5
    gpioSetMode(18, PI_OUTPUT); // D6
    gpioSetMode(12, PI_OUTPUT); // D3

    // Initialise display - 4 bit mode
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, 0); // D4 = 0
    gpioWrite(17, 0); // D5 = 0
    gpioWrite(18, 0); // D6 = 0
    gpioWrite(12, 0); // D3 = 0

    gpioDelay(500); // Wait for more than 400 us

    gpioWrite(24, 0); // EN = 0
}

// LCD clear function
void lcd_clear() {
    gpioWrite(25, 1); // RS = 1
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, 1); // D4 = 1
    gpioWrite(17, 1); // D5 = 1
    gpioWrite(18, 1); // D6 = 1
    gpioWrite(12, 1); // D3 = 1

    gpioDelay(2000); // Wait for more than 1.64 ms
    gpioWrite(24, 0); // EN = 0
}

// LCD print function
void lcd_print(int row, const char *text) {
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, (row == LCD_LINE_1) ? 0 : 1); // D4 = (row == LCD_LINE_1)
    gpioWrite(17, (row == LCD_LINE_1) ? 0 : 1); // D5 = (row == LCD_LINE_1)
    gpioWrite(18, (row == LCD_LINE_1) ? 0 : 1); // D6 = (row == LCD_LINE_1)
    gpioWrite(12, (row == LCD_LINE_1) ? 0 : 1); // D3 = (row == LCD_LINE_1)

    for (int i = 0; text[i] != 0; i++) {
        gpioWrite(24, 1); // EN = 1
        gpioWrite(23, (text[i] & 0x01) ? 1 : 0); // D4 = (text[i] & 0x01)
        gpioWrite(17, (text[i] & 0x02) ? 1 : 0); // D5 = (text[i] & 0x02)
        gpioWrite(18, (text[i] & 0x04) ? 1 : 0); // D6 = (text[i] & 0x04)
        gpioWrite(12, (text[i] & 0x08) ? 1 : 0); // D3 = (text[i] & 0x08)
        gpioDelay(1); // Wait for more than 500 us
        gpioWrite(24, 0); // EN = 0
    }
}

// LCD set cursor function
void lcd_set_cursor(int row) {
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, (row == LCD_LINE_1) ? 0 : 1); // D4 = (row == LCD_LINE_1)
    gpioWrite(17, (row == LCD_LINE_1) ? 0 : 1); // D5 = (row == LCD_LINE_1)
    gpioWrite(18, (row == LCD_LINE_1) ? 0 : 1); // D6 = (row == LCD_LINE_1)
    gpioWrite(12, (row == LCD_LINE_1) ? 0 : 1); // D3 = (row == LCD_LINE_1)

    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 0); // EN = 0
}

// LCD send command function
void lcd_send_command(unsigned char cmd) {
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, 0); // D4 = 0
    gpioWrite(17, 0); // D5 = 0
    gpioWrite(18, 0); // D6 = 0
    gpioWrite(12, 0); // D3 = 0

    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 1, 0); // EN = 1, then 0
    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 0); // EN = 0
}

// LCD send data function
void lcd_send_data(unsigned char data) {
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, 0); // D4 = 0
    gpioWrite(17, 0); // D5 = 0
    gpioWrite(18, 0); // D6 = 0
    gpioWrite(12, 0); // D3 = 0

    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 1, 0); // EN = 1, then 0
    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 0); // EN = 0
}

// LCD print float function
void lcd_print_float(float value) {
    char buffer[17];
    snprintf(buffer, sizeof(buffer), "%.2f", value);
    lcd_clear();
    lcd_set_cursor(LCD_LINE_1);
    lcd_print(buffer);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();
    lcd_clear();
    lcd_print_float(0.0); // Initialize LCD with 0.0

    // Set GPIO modes for water flow sensors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Set pull-up/down resistor for water flow sensors
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP);

    // Set interrupt handlers for water flow sensors
    gpioSetISRFuncEx(SENSOR1_GPIO, RISING_EDGE, 0, pulse_counter, NULL);
    gpioSetISRFuncEx(SENSOR2_GPIO, RISING_EDGE, 0, pulse_counter, NULL);
    gpioSetISRFuncEx(SENSOR3_GPIO, RISING_EDGE, 0, pulse_counter, NULL);

    // Main loop
    while (1) {
        // Calculate flow rates
        float flow_rate1 = (float)pulse_count1 / 450.0 * 60.0; // pulses per liter * 60 seconds
        float flow_rate2 = (float)pulse_count2 / 450.0 * 60.0;
        float flow_rate3 = (float)pulse_count3 / 450.0 * 60.0;

        // Update total volume
        total_volume += (flow_rate1 + flow_rate2 + flow_rate3) / 3.0; // Average flow rates

        // Print flow rates and total volume to console
        printf("Sensor 1: %.2f LPM, Sensor 2: %.2f LPM, Sensor 3: %.2f LPM, Total: %.2f L\n",
               flow_rate1, flow_rate2, flow_rate3, total_volume);

        // Update LCD display
        lcd_clear();
        lcd_set_cursor(LCD_LINE_1);
        lcd_print_float(flow_rate1);
        lcd_set_cursor(LCD_LINE_2);
        lcd_print_float(total_volume);

        // Reset pulse counts
        pulse_count1 = 0;
        pulse_count2 = 0;
        pulse_count3 = 0;

        // Wait for 1 second
        gpioDelay(1000);
    }

    return 0;
}

