    gpioDelay(15); // Wait for more than 15 ms after VCC rises to 4.5V
    gpioDelay(5);  // Wait for more than 4.1 ms
    gpioSetMode(25, PI_OUTPUT); // RS
    gpioSetMode(24, PI_OUTPUT); // EN
    gpioSetMode(23, PI_OUTPUT); // D4
    gpioSetMode(17, PI_OUTPUT); // D5
    gpioSetMode(18, PI_OUTPUT); // D6
    gpioSetMode(12, PI_OUTPUT); // D3

    // Initialise display - 4 bit mode
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, 0); // D4 = 0
    gpioWrite(17, 0); // D5 = 0
    gpioWrite(18, 0); // D6 = 0
    gpioWrite(12, 0); // D3 = 0

    gpioDelay(500); // Wait for more than 400 us

    gpioWrite(24, 0); // EN = 0
}

// LCD clear function
void lcd_clear() {
    gpioWrite(25, 1); // RS = 1
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, 1); // D4 = 1
    gpioWrite(17, 1); // D5 = 1
    gpioWrite(18, 1); // D6 = 1
    gpioWrite(12, 1); // D3 = 1

    gpioDelay(2000); // Wait for more than 1.64 ms
    gpioWrite(24, 0); // EN = 0
}

// LCD print function
void lcd_print(int row, const char *text) {
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, (row == LCD_LINE_1) ? 0 : 1); // D4 = (row == LCD_LINE_1)
    gpioWrite(17, (row == LCD_LINE_1) ? 0 : 1); // D5 = (row == LCD_LINE_1)
    gpioWrite(18, (row == LCD_LINE_1) ? 0 : 1); // D6 = (row == LCD_LINE_1)
    gpioWrite(12, (row == LCD_LINE_1) ? 0 : 1); // D3 = (row == LCD_LINE_1)

    for (int i = 0; text[i] != 0; i++) {
        gpioWrite(24, 1); // EN = 1
        gpioWrite(23, (text[i] & 0x01) ? 1 : 0); // D4 = (text[i] & 0x01)
        gpioWrite(17, (text[i] & 0x02) ? 1 : 0); // D5 = (text[i] & 0x02)
        gpioWrite(18, (text[i] & 0x04) ? 1 : 0); // D6 = (text[i] & 0x04)
        gpioWrite(12, (text[i] & 0x08) ? 1 : 0); // D3 = (text[i] & 0x08)
        gpioDelay(1); // Wait for more than 500 us
        gpioWrite(24, 0); // EN = 0
    }
}

// LCD set cursor function
void lcd_set_cursor(int row) {
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, (row == LCD_LINE_1) ? 0 : 1); // D4 = (row == LCD_LINE_1)
    gpioWrite(17, (row == LCD_LINE_1) ? 0 : 1); // D5 = (row == LCD_LINE_1)
    gpioWrite(18, (row == LCD_LINE_1) ? 0 : 1); // D6 = (row == LCD_LINE_1)
    gpioWrite(12, (row == LCD_LINE_1) ? 0 : 1); // D3 = (row == LCD_LINE_1)

    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 0); // EN = 0
}

// LCD send command function
void lcd_send_command(unsigned char cmd) {
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, 0); // D4 = 0
    gpioWrite(17, 0); // D5 = 0
    gpioWrite(18, 0); // D6 = 0
    gpioWrite(12, 0); // D3 = 0

    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 1, 0); // EN = 1, then 0
    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 0); // EN = 0
}

// LCD send data function
void lcd_send_data(unsigned char data) {
    gpioWrite(25, 0); // RS = 0
    gpioWrite(24, 1); // EN = 1
    gpioWrite(23, 0); // D4 = 0
    gpioWrite(17, 0); // D5 = 0
    gpioWrite(18, 0); // D6 = 0
    gpioWrite(12, 0); // D3 = 0

    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 1, 0); // EN = 1, then 0
    gpioDelay(1); // Wait for more than 500 us
    gpioWrite(24, 0); // EN = 0
}

// LCD print float function
void lcd_print_float(float value) {
    char buffer[17];
    snprintf(buffer, sizeof(buffer), "%.2f", value);
    lcd_clear();
    lcd_set_cursor(LCD_LINE_1);
    lcd_print(buffer);
}

