// Define GPIO pins for rows and columns
const struct gpiod_line *row_lines[] = {
    gpiod_line_get_by_number(17),
    gpiod_line_get_by_number(18),
    gpiod_line_get_by_number(27),
    gpiod_line_get_by_number(22),
    gpiod_line_get_by_number(23),
    gpiod_line_get_by_number(24),
    gpiod_line_get_by_number(25),
    gpiod_line_get_by_number(4)
};

const struct gpiod_line *column_lines[] = {
    gpiod_line_get_by_number(5),
    gpiod_line_get_by_number(6),
    gpiod_line_get_by_number(12),
    gpiod_line_get_by_number(13),
    gpiod_line_get_by_number(19),
    gpiod_line_get_by_number(16),
    gpiod_line_get_by_number(26),
    gpiod_line_get_by_number(20)
};

const int num_rows = 8;
const int num_columns = 8;
const int num_lines = num_rows + num_columns;

// Global variable to store the GPIO chip handle
struct gpiod_chip *chip = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to initialize the GPIO lines
int initialize_gpio() {
    int i, ret;
    for (i = 0; i < num_lines; i++) {
        ret = gpiod_line_request_output(row_lines[i], "wave_animation", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting row line %d as output: %s\n", row_lines[i]->number, strerror(-ret));
            return -1;
        }

        ret = gpiod_line_request_output(column_lines[i], "wave_animation", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting column line %d as output: %s\n", column_lines[i]->number, strerror(-ret));
            return -1;
        }
    }
    return 0;
}

// Function to display a single frame of the wave animation
void display_frame(int wave_direction) {
    int i, j;
    int row_index = 0;
    int col_index = 0;

    for (i = 0; i < num_rows; i++) {
        if (wave_direction == 1) { // Left-to-right
            row_index = i;
        } else { // Right-to-left
            row_index = num_rows - 1 - i;
        }

        for (j = 0; j < num_columns; j++) {
            if (wave_direction == 1) { // Left-to-right
                col_index = j;
            } else { // Right-to-left
                col_index = num_columns - 1 - j;
            }

            // Set row HIGH and column LOW to light the LED
            if (gpiod_line_set_value(row_lines[row_index], 1) < 0) {
                fprintf(stderr, "Error setting row line %d value: %s\n", row_lines[row_index]->number, strerror(-gpiod_line_set_value(row_lines[row_index], 1)));
            }
            if (gpiod_line_set_value(column_lines[col_index], 0) < 0) {
                fprintf(stderr, "Error setting column line %d value: %s\n", column_lines[col_index]->number, strerror(-gpiod_line_set_value(column_lines[col_index], 0)));
            }
        }
    }
}

int main() {
    int i, ret;
    struct gpiod_line *row_line, *col_line;
    int wave_direction = 1; // 1 for left-to-right, 0 for right-to-left

