// Define GPIO pins for row anodes and column cathodes
const struct gpiod_line *row_lines[8] = {NULL};
const struct gpiod_line *col_lines[8] = {NULL};

// Define chip and line attributes
struct gpiod_chip *chip;
struct gpiod_line_request_config config;

// Function prototypes
int initialize_gpio(void);
void clear_matrix(void);
void set_column(int col);
void scan_column(int col);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request row line pins as output
    for (int i = 0; i < 8; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, 2 + i);
        if (!row_lines[i]) {
            perror("Error getting row line");
            cleanup_gpio();
            return -1;
        }

        config.consumer = "row";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0;

        ret = gpiod_line_request(row_lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting row line");
            cleanup_gpio();
            return -1;
        }
    }

    // Request column line pins as output
    for (int i = 0; i < 8; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, 14 + i);
        if (!col_lines[i]) {
            perror("Error getting column line");
            cleanup_gpio();
            return -1;
        }

        config.consumer = "col";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0;

        ret = gpiod_line_request(col_lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting column line");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Clear the LED matrix (turn off all LEDs)
void clear_matrix(void) {
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(row_lines[i], 0);
        gpiod_line_set_value(col_lines[i], 1);
    }
}

// Set a single column
void set_column(int col) {
    gpiod_line_set_value(col_lines[col], 0);
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(row_lines[i], 1);
    }
}

// Scan a single column with a delay
void scan_column(int col) {
    set_column(col);
    usleep(150000); // 150 ms delay
    clear_matrix();
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    for (int i = 0; i < 8; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handlers for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop: scan columns indefinitely
    while (1) {
        for (int col = 0; col < 8; col++) {
            scan_column(col);
        }
    }

    return 0;
}

