    terminate = 1;
}

// Function to initialize the Si1145 sensor
int si1145_init() {
    int status;

    // Reset the sensor
    status = i2cWriteByteData(i2c_handle, SI1145_COMMAND, SI1145_RESET);
    if (status < 0) {
        fprintf(stderr, "Error resetting Si1145: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure measurement rates
    status = i2cWriteByteData(i2c_handle, SI1145_COMMAND, SI1145_ALS_RATE);
    if (status < 0) {
        fprintf(stderr, "Error writing ALS_RATE: %s\n", strerror(errno));
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, SI1145_COMMAND, SI1145_PS_RATE);
    if (status < 0) {
        fprintf(stderr, "Error writing PS_RATE: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int si1145_read_data(int *proximity, int *ambient_light) {
    int status;
    int proximity_low, proximity_high, ambient_low, ambient_high;

    // Read proximity data
    proximity_low = i2cReadByteData(i2c_handle, SI1145_PS1_DATA0);
    if (proximity_low < 0) {
        fprintf(stderr, "Error reading PS1_DATA0: %s\n", strerror(errno));
        return -1;
    }
    proximity_high = i2cReadByteData(i2c_handle, SI1145_PS1_DATA1);
    if (proximity_high < 0) {
        fprintf(stderr, "Error reading PS1_DATA1: %s\n", strerror(errno));
        return -1;
    }

    // Read ambient light data
    ambient_low = i2cReadByteData(i2c_handle, SI1145_ALS_VIS_DATA0);
    if (ambient_low < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0: %s\n", strerror(errno));
        return -1;
    }
    ambient_high = i2cReadByteData(i2c_handle, SI1145_ALS_VIS_DATA1);
    if (ambient_high < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA1: %s\n", strerror(errno));
        return -1;
    }

    *proximity = (proximity_high << 8) | proximity_low;
    *ambient_light = (ambient_high << 8) | ambient_low;

    return 0;
}

// Function to log data to a file with ISO-8601 timestamp
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

