#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "proximity.log"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 UTC format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
void log_event(const char* timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s Object detected\n", timestamp);
    fclose(fp);
}

// Callback function for falling edge detection on the sensor pin
void sensor_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge (LOW signal)
        char* timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            log_event(timestamp);
            free(timestamp); // Free the allocated memory
            gpioWrite(LED_PIN, 1); // Turn LED on
            gpioDelay(100);         // Wait 100ms
            gpioWrite(LED_PIN, 0); // Turn LED off
        }
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up resistor on the sensor pin (optional, depending on sensor)
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    // Register callback function for falling edge detection
    gpioSetAlertFuncEx(SENSOR_PIN, sensor_callback, NULL);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (runs until a signal is caught)
    while (program_running) {
        gpioDelay(100); // Check every 100ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

