#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define COMMAND_REG 0x30
#define PS1_REG 0x18
#define ALS_VIS_REG 0x22

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Initialize the Si1145 sensor
int init_si1145() {
    int status;

    // Verify PART_ID
    status = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (status != 0x45) {
        fprintf(stderr, "Error: Incorrect PART_ID (0x%02x). Expected 0x45.\n", status);
        return -1;
    }

    // Enable HW_KEY
    status = i2cWriteByteData(i2c_handle, HW_KEY_REG, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing to HW_KEY: %s\n", strerror(errno));
        return -1;
    }

