#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_MS 30
#define MIN_DISTANCE 2.0    // cm
#define MAX_DISTANCE 400.0  // cm
#define WATERING_THRESHOLD 15.0 // cm

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio(void);
int trigger_sensor(void);
int read_echo_pulse(void);
float calculate_distance(long pulse_width_ns);
void log_data(float distance);
void signal_handler(int sig);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO pins
int init_gpio(void) {
    struct gpiod_line_request_config trigger_config, echo_config;
    struct gpiod_line_request *trigger_req, *echo_req;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        goto cleanup;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        goto cleanup;
    }

    // Request trigger line as output
    memset(&trigger_config, 0, sizeof(trigger_config));
    trigger_config.consumer = "plant_watering";
    trigger_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    trigger_config.flags = 0;
    trigger_req = gpiod_line_request(trigger_line, &trigger_config);
    if (!trigger_req) {
        perror("Error requesting trigger line as output");
        goto cleanup;
    }

    // Request echo line as input
    memset(&echo_config, 0, sizeof(echo_config));
    echo_config.consumer = "plant_watering";
    echo_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    echo_config.flags = 0;
    echo_req = gpiod_line_request(echo_line, &echo_config);
    if (!echo_req) {
        perror("Error requesting echo line as input");
        goto cleanup;
    }

    // Dequeue the request
    if (gpiod_line_request_dequeue(echo_req) < 0) {
        perror("Error dequeuing echo line request");
        goto cleanup;
    }

    if (gpiod_line_request_dequeue(trigger_req) < 0) {
        perror("Error dequeuing trigger line request");
        goto cleanup;
    }

    return 0;

cleanup:
    if (trigger_req) gpiod_line_request_free(trigger_req);
    if (echo_req) gpiod_line_request_free(echo_req);
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    return -1;
}

// Trigger the ultrasonic sensor
int trigger_sensor(void) {
    struct gpiod_line_request_config trigger_config;
    struct gpiod_line_request *trigger_req;

    memset(&trigger_config, 0, sizeof(trigger_config));
    trigger_config.consumer = "plant_watering";
    trigger_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    trigger_config.flags = 0;

    trigger_req = gpiod_line_request(trigger_line, &trigger_config);
    if (!trigger_req) {
        perror("Error requesting trigger line as output for triggering");
        return -1;
    }

    if (gpiod_line_request_send(trigger_req, 1) < 0) {
        perror("Error sending trigger pulse");
        gpiod_line_request_free(trigger_req);
        return -1;
    }

    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 10 * 1000000; // 10 microseconds
    nanosleep(&delay, NULL);

    if (gpiod_line_request_release(trigger_req) < 0) {
        perror("Error releasing trigger line request");
        return -1;
    }

    return 0;
}

// Read the echo pulse width
int read_echo_pulse(void) {
    struct timespec start, end;
    long pulse_width_ns = 0;
    struct gpiod_line_event event;

    // Wait for the echo line to go high
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        if (gpiod_line_event_wait(echo_line, &event, TIMEOUT_MS * 1000) < 0) {
            perror("Timeout waiting for echo to go high");
            return -1;
        }

        if (event.value) {
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > (TIMEOUT_MS * 1000000)) {
            fprintf(stderr, "Timeout waiting for echo to go high\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo line to go low
    while (1) {
        if (gpiod_line_event_wait(echo_line, &event, TIMEOUT_MS * 1000) < 0) {
            perror("Timeout waiting for echo to go low");
            return -1;
        }

        if (!event.value) {
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > (TIMEOUT_MS * 1000000)) {
            fprintf(stderr, "Timeout waiting for echo to go low\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
    return pulse_width_ns;
}

// Calculate distance in centimeters
float calculate_distance(long pulse_width_ns) {
    if (pulse_width_ns <= 0) return -1.0; // Indicate error
    return (float)(pulse_width_ns * SPEED_OF_SOUND) / 2000000.0 / 2.0; // cm
}

// Log data to file
void log_data(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, distance);
    fclose(fp);

    if (distance < WATERING_THRESHOLD) {
        printf("Time to water the plant!\n");
    }
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
}

int main(void) {
    struct timespec sleep_time;
    sleep_time.tv_sec = 60;
    sleep_time.tv_nsec = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger sensor
        if (trigger_sensor() < 0) {
            fprintf(stderr, "Error triggering sensor. Retrying in 60 seconds.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Read echo pulse
        long pulse_width_ns = read_echo_pulse();
        if (pulse_width_ns < 0) {
            fprintf(stderr, "Error reading echo pulse. Retrying in 60 seconds.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Calculate distance
        float distance = calculate_distance(pulse_width_ns);

        // Log data
        if (distance >= 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error calculating distance. Logging error.\n");
            FILE *fp = fopen("distance_log.txt", "a");
            if (fp != NULL) {
                time_t t = time(NULL);
                struct tm tm = *localtime(&t);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);
                fprintf(fp, "%s,ERROR\n", timestamp);
                fclose(fp);
            }
        }

        // Sleep for 60 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

