#define APDS9960_REG_ATIME 0x81
#define APDS9960_REG_WTIME 0x83
#define APDS9960_REG_PPULSE 0x8E
#define APDS9960_REG_CONTROL 0xF1
#define APDS9960_REG_CONFIG2 0x90

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int apds9960_read_register(int reg);
int apds9960_write_register(int reg, int value);
int apds9960_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity);
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the APDS9960 sensor
int apds9960_init() {
    // Verify sensor ID
    int sensor_id = apds9960_read_register(APDS9960_REG_ID);
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%X\n", sensor_id);
        return -1;
    }

    // Configure the sensor
    if (apds9960_write_register(APDS9960_REG_ENABLE, 0x03) < 0) return -1; // Enable power and ALS
    if (apds9960_write_register(APDS9960_REG_ATIME, 0xDB) < 0) return -1; // ALS integration time
    if (apds9960_write_register(APDS9960_REG_WTIME, 0xF6) < 0) return -1; // ALS wait time
    if (apds9960_write_register(APDS9960_REG_PPULSE, 0x87) < 0) return -1; // Pulse width
    if (apds9960_write_register(APDS9960_REG_CONTROL, 0x03) < 0) return -1; // Enable color sensing
    if (apds9960_write_register(APDS9960_REG_CONFIG2, 0x01) < 0) return -1; // Enable proximity

    return 0;
}

