    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read color and proximity data from the APDS9960
int apds9960_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    *red = apds9960_read_register(0x96);
    *green = apds9960_read_register(0x98);
    *blue = apds9960_read_register(0x9A);
    *proximity = apds9960_read_register(0x9C);

    return 0;
}

