    i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (apds9960_init() < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue;
    uint8_t proximity;

    // Main loop
    while (!terminate) {
        if (apds9960_read_data(&red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (apds9960_init() < 0) {
                    fprintf(stderr, "APDS9960 re-initialization failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

