#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define PART_ID_REG 0x00
#define MEAS_RATE0_REG 0x08
#define COMMAND_REG 0x47
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25
#define PS_DATA_LEN 2
#define CSV_FILE "heartrate.csv"

// Global variables
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile int running = 1;

// Function prototypes
int i2c_setup(int i2c_bus, int i2c_address);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg);
int si1182_init(int fd);
int read_proximity_data(int fd, int *proximity);
float calculate_bpm(int proximity);
int log_data(const char *timestamp, float bpm);
void signal_handler(int signal);

// I2C setup function
int i2c_setup(int i2c_bus, int i2c_address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address to I2C device");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return value;
}

// Si1182 initialization function
int si1182_init(int fd) {
    int part_id = i2c_read_reg(fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register\n");
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    // Configure MEAS_RATE0 for continuous measurement (example value)
    if (i2c_write_reg(fd, MEAS_RATE0_REG, 0x0A) < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE0 register\n");
        return -1;
    }

    // Reset the sensor
    if (i2c_write_reg(fd, COMMAND_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to COMMAND register (reset)\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Start continuous measurement
    if (i2c_write_reg(fd, COMMAND_REG, 0x03) < 0) {
        fprintf(stderr, "Error writing to COMMAND register (start)\n");
        return -1;
    }

    return 0;
}

// Read proximity data function
int read_proximity_data(int fd, int *proximity) {
    int data0 = i2c_read_reg(fd, PS_DATA0_REG);
    int data1 = i2c_read_reg(fd, PS_DATA1_REG);

    if (data0 < 0 || data1 < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    *proximity = (data1 << 8) | data0;
    return 0;
}

// Calculate BPM function (placeholder)
float calculate_bpm(int proximity) {
    // Simple threshold-based BPM calculation
    if (proximity > 500) {
        return 70.0; // Example BPM
    } else {
        return 60.0; // Example BPM
    }
}

// Log data to CSV function
int log_data(const char *timestamp, float bpm) {
    if (csv_file == NULL) {
        fprintf(stderr, "CSV file not opened\n");
        return -1;
    }

    fprintf(csv_file, "%s,%.2f\n", timestamp, bpm);
    fflush(csv_file);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // I2C setup
    i2c_fd = i2c_setup(I2C_BUS, SI1182_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize Si1182 sensor
    if (si1182_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,bpm\n");
    }

    // Main loop
    int proximity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    while (running) {
        // Read proximity data
        if (read_proximity_data(i2c_fd, &proximity) < 0) {
            fprintf(stderr, "Error reading proximity data, skipping sample\n");
            gpioDelay(100); // Wait 100ms before next attempt
            continue;
        }

        // Calculate BPM
        float bpm = calculate_bpm(proximity);

        // Get timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        // Log data
        if (log_data(timestamp, bpm) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait 100ms
        gpioDelay(100);
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

