    }
}

// Log data to CSV function
int log_data(const char *timestamp, float bpm) {
    if (csv_file == NULL) {
        fprintf(stderr, "CSV file not opened\n");
        return -1;
    }

    fprintf(csv_file, "%s,%.2f\n", timestamp, bpm);
    fflush(csv_file);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // I2C setup
    i2c_fd = i2c_setup(I2C_BUS, SI1182_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize Si1182 sensor
    if (si1182_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,bpm\n");
    }

    // Main loop
    int proximity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    while (running) {
        // Read proximity data
        if (read_proximity_data(i2c_fd, &proximity) < 0) {
            fprintf(stderr, "Error reading proximity data, skipping sample\n");
            gpioDelay(100); // Wait 100ms before next attempt
            continue;
        }

        // Calculate BPM
        float bpm = calculate_bpm(proximity);

        // Get timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        // Log data
        if (log_data(timestamp, bpm) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait 100ms
        gpioDelay(100);
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

