#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define CH101_ADDR 0x45
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define SAMPLE_INTERVAL 200 // milliseconds
#define DISTANCE_LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int trigger_measurement();
int read_distance();
int convert_to_mm(int raw_distance);
int log_distance(int distance_mm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    char trigger_data = 0x00; // Example trigger data
    int result = i2cWriteByteData(i2c_handle, 0x00, trigger_data); // Register address doesn't matter for this sensor
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the distance from the sensor
int read_distance() {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Failed to read distance: %d\n", result);
        return -1;
    }
    return (buffer[0] << 8) | buffer[1]; // Combine the two bytes into a 16-bit value
}

// Convert raw distance to millimeters
int convert_to_mm(int raw_distance) {
    // Assuming raw_distance is in mm directly
    return raw_distance;
}

// Log the distance to a file
int log_distance(int distance_mm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %d\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(DISTANCE_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Starting distance measurement...\n");

    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (adjust as needed)
        gpioDelay(TRIGGER_PULSE_DURATION); // Wait for trigger pulse duration

        // Read distance
        int raw_distance = read_distance();
        if (raw_distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to millimeters
        int distance_mm = convert_to_mm(raw_distance);

        // Log distance
        if (log_distance(distance_mm) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        // Print to stdout
        printf("Distance: %d mm\n", distance_mm);

        // Wait before next sample
        gpioDelay(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

