#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define POLLING_INTERVAL_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

int log_data(int sensor1_value, int sensor2_value) {
    FILE *fp = fopen("obstacle_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening obstacle_log.txt for writing!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_value, sensor2_value);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error already logged in read_sensor
        } else {
            if (log_data(sensor1_value, sensor2_value) == -1) {
                fprintf(stderr, "Error logging data!\n");
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    gpioTerminate();
    printf("Obstacle detection stopped.\n");
    return 0;
}

