int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient);
int log_data(FILE *fp, uint16_t proximity, uint16_t ambient);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    uint16_t proximity;
    uint16_t ambient;
} sensor_data_t;

