int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retry logic
int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(handle, PROXIMITY_REG);
        if (result >= 0) {
            *proximity = (uint16_t)result;
            result = i2cReadWordData(handle, AMBIENT_REG);
            if (result >= 0) {
                *ambient = (uint16_t)result;
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retries + 1, result);
            }
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(10); // Small delay before retrying
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to log data to a file
int log_data(FILE *fp, uint16_t proximity, uint16_t ambient) {
