#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define COMMAND_FRAME_LENGTH 4
#define RESPONSE_FRAME_LENGTH 15
#define DISTANCE_OFFSET 0
#define DISTANCE_SIZE 2
#define INTRUSION_THRESHOLD 1000 // mm
#define SAMPLE_COUNT 10
#define DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(uint8_t *command, int length);
int read_response(uint8_t *response, int length);
int validate_response(uint8_t *response);
float calculate_average_distance(uint8_t *responses, int num_responses);
void log_intrusion(float average_distance);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint8_t *data;
    int size;
} sensor_data_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(uint8_t *command, int length) {
    int result = i2cWriteDevice(i2c_handle, (char *)command, length);
    if (result != length) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read response from the sensor
int read_response(uint8_t *response, int length) {
    int result = i2cReadDevice(i2c_handle, (char *)response, length);
    if (result != length) {
        fprintf(stderr, "Error reading response: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate the response frame
int validate_response(uint8_t *response) {
    if (response[0] != 0x50) {
        fprintf(stderr, "Invalid response header: 0x%02X\n", response[0]);
        return -1;
    }
    return 0;
}

// Calculate the average distance from multiple readings
float calculate_average_distance(uint8_t *responses, int num_responses) {
    float sum = 0.0;
    for (int i = 0; i < num_responses; i++) {
        int distance = (responses[i][DISTANCE_OFFSET] << 8) | responses[i][DISTANCE_OFFSET + 1];
        sum += (float)distance;
    }
    return sum / num_responses;
}

// Log intrusion event to file
void log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", timestamp, average_distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

