// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the model ID from the VL53L0X
int read_model_id(int handle) {
    int model_id = read_register(handle, VL53L0X_REG_MODEL_ID);
    if (model_id < 0) {
        return -1;
    }
    return model_id;
}

// Function to start a single-shot ranging measurement
int start_ranging(int handle) {
    if (write_register(handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
        return -1;
    }
    return 0;
}

// Function to read the distance from the VL53L0X
int read_distance(int handle) {
    int distance = -1;
    int timeout = 100; // Timeout in milliseconds

    while (distance < 0 && timeout > 0) {
        // Wait for interrupt (polling)
        int interrupt_status = read_register(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
        if (interrupt_status < 0) {
            return -1;
        }

        if ((interrupt_status & 0x01) != 0) {
            // Interrupt occurred, read distance
            int range_status = read_register(handle, VL53L0X_REG_RESULT_RANGE_STATUS);
            if (range_status < 0) {
                return -1;
            }

            // Clear interrupt
            if (write_register(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
                return -1;
            }

            // Combine the two bytes to form the distance
            distance = (range_status & 0xFF) | ((range_status >> 8) & 0xFF) << 8;
        } else {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout--;
        }
    }

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Check if the VL53L0X is present
    int model_id = read_model_id(i2c_handle);
    if (model_id != 0xEE) {
        fprintf(stderr, "VL53L0X sensor not found. Model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Start ranging
        if (start_ranging(i2c_handle) < 0) {
            fprintf(stderr, "Error starting ranging\n");
        } else {
            // Wait for measurement to complete
            gpioDelay(100); // Wait 100ms

            // Read distance
            int distance = read_distance(i2c_handle);
            if (distance >= 0) {
                // Get current time
                time_t rawtime;
                struct tm *timeinfo;
                time(&rawtime);
                timeinfo = localtime(&rawtime);

                // Format timestamp
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Print distance reading
                printf("%s Distance: %d mm\n", timestamp, distance);
            } else {
                fprintf(stderr, "Error reading distance\n");
            }
        }

        // Wait 500ms
        gpioDelay(500);
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

