    if (status < 0) {
        fprintf(stderr, "Error reading LSB: %d\n", status);
        return -1;
    }
    lsb = status;

    // Read the MSB
    status = i2cReadByteData(i2c_handle, PROX_DATA_MSB);
    if (status < 0) {
        fprintf(stderr, "Error reading MSB: %d\n", status);
        return -1;
    }
    msb = status;

    // Combine the two bytes into a 16-bit value
    *proximity_value = (msb << 8) | lsb;

