// Define the I2C bus and address for the OPT3101 sensor
#define I2C_BUS 1
#define OPT3101_ADDR 0x44

// Define register addresses (replace with actual register addresses from the OPT3101 datasheet)
#define OPT3101_REG_DISTANCE 0x00
#define OPT3101_REG_AMBIENT 0x01
#define OPT3101_REG_ERROR 0x02

// Global variable to store the I2C handle
int i2c_handle;

// Signal handler for Ctrl+C (SIGINT)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from the OPT3101 sensor
int read_opt3101_data(int i2c_handle, int *distance, int *ambient_light, int *error_flag) {
    char buf[4]; // Buffer to hold the received data
    int result;

    // Read distance data
    result = i2cReadI2CBlockData(i2c_handle, OPT3101_REG_DISTANCE, buf, 4); // Read 4 bytes
    if (result != 4) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        *error_flag = 1; // Set error flag
        return -1; // Indicate error
    }
    *distance = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3]; // Combine bytes into a 32-bit integer

    // Read ambient light data
    result = i2cReadI2CBlockData(i2c_handle, OPT3101_REG_AMBIENT, buf, 4); // Read 4 bytes
    if (result != 4) {
        fprintf(stderr, "Error reading ambient light data: %d\n", result);
        *error_flag = 1; // Set error flag
        return -1; // Indicate error
    }
    *ambient_light = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3]; // Combine bytes into a 32-bit integer

    // Read error flag
    result = i2cReadI2CBlockData(i2c_handle, OPT3101_REG_ERROR, buf, 1); // Read 1 byte
    if (result != 1) {
        fprintf(stderr, "Error reading error flag: %d\n", result);
        *error_flag = 1; // Set error flag
        return -1; // Indicate error
    }
    *error_flag = buf[0];

    return 0; // Indicate success
}

int main() {
    int distance, ambient_light, error_flag;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from the OPT3101 sensor
        if (read_opt3101_data(i2c_handle, &distance, &ambient_light, &error_flag) == 0) {
            // Print the data to the console
            printf("Distance: %d mm, Ambient Light: %d, Error Flag: %d\n", distance, ambient_light, error_flag);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // Delay in microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper resource release.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

