#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_MS 200         // Timeout for echo pulse in milliseconds
#define MAX_DISTANCE_CM 400    // Maximum measurable distance in cm

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
void triggerSensor();
long long measurePulseWidth();
float calculateDistance(long long pulseWidth);
void logDistance(float distance);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the echo pulse width using gpioTick()
long long measurePulseWidth() {
    long long start_tick, end_tick, pulse_width;

    // Wait for echo to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_MS * 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_MS * 1000) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Error: Echo falling edge timeout\n");
        return -1; // Indicate timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate distance in centimeters
float calculateDistance(long long pulseWidth) {
    if (pulseWidth <= 0) {
        fprintf(stderr, "Error: Invalid pulse width: %lld us\n", pulseWidth);
        return -1.0; // Indicate invalid distance
    }

    if (pulseWidth > MAX_DISTANCE_CM * 0.0343) {
        fprintf(stderr, "Error: Pulse width exceeds maximum range: %lld us\n", pulseWidth);
        return -1.0; // Indicate out-of-range distance
    }

    return (pulseWidth * SPEED_OF_SOUND) / 2.0;
}

// Function to log the distance with a timestamp
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        triggerSensor();
        long long pulseWidth = measurePulseWidth();

        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);
            if (distance >= 0) {
                logDistance(distance);
            }
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

