// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define GPIO_LED 17
#define RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486 // meters per bin
#define THRESHOLD_DISTANCE 1.0 // meters
#define MAGIC_WORD_SIZE 8
#define DATA_FRAME_SIZE (MAGIC_WORD_SIZE + RANGE_BINS * 2)
#define LED_ON_TIME 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_radar_data(int fd, unsigned char *buffer, int buffer_size);
int validate_magic_word(const unsigned char *buffer, int buffer_size);
int parse_range_profile(const unsigned char *buffer, int buffer_size, float *range_profile);
int detect_intrusion(const float *range_profile, int num_bins, float threshold_distance);
int control_led(int gpio_pin, int on);
int log_intrusion(const char *timestamp, float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// UART initialization function
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read radar data from UART
int read_radar_data(int fd, unsigned char *buffer, int buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred, not an error
            return 0;
        }
        perror("Error reading from UART");
        return -1;
    }
    return (int)bytes_read;
}

// Function to validate the magic word
int validate_magic_word(const unsigned char *buffer, int buffer_size) {
    if (buffer_size != MAGIC_WORD_SIZE) {
        fprintf(stderr, "Error: Invalid magic word size: %d\n", buffer_size);
        return 0;
    }

    for (int i = 0; i < MAGIC_WORD_SIZE; i++) {
        if (buffer[i] != (unsigned char)((i % 2) ^ 1)) {
            fprintf(stderr, "Error: Invalid magic word: 0x%02X\n", buffer[i]);
            return 0;
        }
    }

    return 1;
}

// Function to parse the range profile
int parse_range_profile(const unsigned char *buffer, int buffer_size, float *range_profile) {
