// Define chip name
#define CHIP_NAME "gpiochip0"

// Define log file name
#define LOG_FILE "obstacle_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *buzzer_line;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor();
int control_buzzer(int state);
int log_event(const char *event);
void signal_handler(int sig);

// Function to read the sensor value
int read_sensor() {
    int value = -1;
    int ret;

    ret = gpiod_line_get_value(sensor_line, &value);
    if (ret < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-ret));
        return -1; // Indicate error
    }

    return value;
}

// Function to control the buzzer
int control_buzzer(int state) {
    int ret;

    ret = gpiod_line_set_value(buzzer_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(-ret));
        return -1; // Indicate error
    }

    return 0;
}

// Function to log events to a file
int log_event(const char *event) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int sensor_value;
    int buzzer_state = 0; // 0 = off, 1 = on

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line direction for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "obstacle_detector";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(sensor_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting sensor line: %s\n", strerror(-ret));
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request(buzzer_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer line: %s\n", strerror(-ret));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            // Error reading sensor, exit loop
            break;
        }

        if (sensor_value == 0 && buzzer_state == 0) {
            // Obstacle detected, activate buzzer
            if (control_buzzer(1) == 0) {
                log_event("Obstacle detected, buzzer activated");
            }
            buzzer_state = 1;
        } else if (sensor_value == 1 && buzzer_state == 1) {
            // Obstacle removed, deactivate buzzer
            if (control_buzzer(0) == 0) {
                log_event("Obstacle removed, buzzer deactivated");
            }
            buzzer_state = 0;
        }

        usleep(100000); // 100 ms
    }

    // Cleanup
    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return 0;
}

