#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_REG_HIGH 0x31
#define DISTANCE_REG_LOW 0x32
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL 100 // ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_distance(int *distance);
void log_data(int distance);
void trigger_alert(int distance);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int chirp_mode;
    int measurement_rate;
} sensor_config_t;

// Initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure alert pin is initially low

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read the distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG_HIGH, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Log the distance data with an ISO 8601 timestamp
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Trigger the alert if the distance is below the threshold
void trigger_alert(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1); // Set GPIO high
        gpioDelay(1000);          // Wait for 1 second
        gpioWrite(ALERT_GPIO, 0); // Set GPIO low
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_GPIO, 0); // Ensure alert pin is low on exit
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    int distance;
    int init_result = 0; // Initialize sensor (example)

    // Example: Initialize the sensor (replace with actual initialization sequence)
    init_result = i2cWriteByteData(i2c_handle, 0x00, 0x01); // Example: Set chirp mode
    if (init_result != 0) {
        fprintf(stderr, "Sensor initialization failed: %d\n", init_result);
        cleanup();
        return 1;
    }

    printf("Starting distance measurement...\n");

    while (!terminate) {
        if (read_distance(&distance)) {
            log_data(distance);
            trigger_alert(distance);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

