#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define DISTANCE_MIN 50 // mm
#define DISTANCE_MAX 500 // mm
#define BLINK_MIN_FREQ 10 // Hz
#define BLINK_MAX_FREQ 1 // Hz
#define SAMPLE_INTERVAL 100 // ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
int init_led();
void set_led_frequency(int frequency);
void log_data(int distance, int frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201
int read_distance(int *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buf[2]; // Buffer to store the distance data (2 bytes)
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retries left: %d\n", result, retries);
            gpioDelay(10); // 10 ms delay
            retries--;
            continue;
        }

        gpioDelay(10); // Small delay after write

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %d, retries left: %d\n", result, retries);
            gpioDelay(10); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Initialize LED GPIO
int init_led() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED GPIO mode.\n");
        return -1;
    }
    return 0;
}

// Set LED frequency (blink rate)
void set_led_frequency(int frequency) {
    if (frequency < BLINK_MIN_FREQ) frequency = BLINK_MIN_FREQ;
    if (frequency > BLINK_MAX_FREQ) frequency = BLINK_MAX_FREQ;

    int period_us = 1000000 / frequency; // Period in microseconds
    int on_time_us = period_us / 2;       // On time in microseconds
    int off_time_us = period_us - on_time_us; // Off time in microseconds

    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(on_time_us);   // Keep LED on for on_time_us
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(off_time_us);  // Keep LED off for off_time_us
}

// Log data to stdout
void log_data(int distance, int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %d mm, Blink Frequency: %d Hz\n", timestamp, distance, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LED
    if (init_led() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int distance;
    int frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            // Map distance to blink frequency
            frequency = (int)(((float)(DISTANCE_MAX - distance) / (DISTANCE_MAX - DISTANCE_MIN)) * (BLINK_MAX_FREQ - BLINK_MIN_FREQ) + BLINK_MIN_FREQ);

            // Set LED frequency
            set_led_frequency(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

