        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %d, retries left: %d\n", result, retries);
            gpioDelay(10); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Initialize LED GPIO
int init_led() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED GPIO mode.\n");
        return -1;
    }
    return 0;
}

// Set LED frequency (blink rate)
void set_led_frequency(int frequency) {
    if (frequency < BLINK_MIN_FREQ) frequency = BLINK_MIN_FREQ;
    if (frequency > BLINK_MAX_FREQ) frequency = BLINK_MAX_FREQ;

    int period_us = 1000000 / frequency; // Period in microseconds
    int on_time_us = period_us / 2;       // On time in microseconds
    int off_time_us = period_us - on_time_us; // Off time in microseconds

    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(on_time_us);   // Keep LED on for on_time_us
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(off_time_us);  // Keep LED off for off_time_us
}

// Log data to stdout
void log_data(int distance, int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %d mm, Blink Frequency: %d Hz\n", timestamp, distance, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LED
    if (init_led() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int distance;
    int frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            // Map distance to blink frequency
            frequency = (int)(((float)(DISTANCE_MAX - distance) / (DISTANCE_MAX - DISTANCE_MIN)) * (BLINK_MAX_FREQ - BLINK_MIN_FREQ) + BLINK_MIN_FREQ);

            // Set LED frequency
            set_led_frequency(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

