#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int distance_register;
} sensor_config_t;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
int log_data(time_t timestamp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(i2c_handle, DISTANCE_REG, 0) != 0) { // Trigger measurement
            fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
