    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_cm\n");
    }
    rewind(log_file);

    // Main loop
    int distance;
    time_t current_time;

    while (!terminate) {
        if (read_distance(&distance) == 0) {
            current_time = time(NULL);
            if (log_data(current_time, distance) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

