#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

#define DEBOUNCE_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

void log_proximity_event(int sensor_id, const char *event_type) {
    FILE *fp = fopen("proximity_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening proximity_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_1_state = 1; // Initialize to clear
    int sensor_2_state = 1; // Initialize to clear

    while (program_running) {
        int new_sensor_1_state = gpioRead(SENSOR_1_GPIO);
        int new_sensor_2_state = gpioRead(SENSOR_2_GPIO);

        if (new_sensor_1_state != sensor_1_state) {
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce
            new_sensor_1_state = gpioRead(SENSOR_1_GPIO);
            if (new_sensor_1_state != sensor_1_state) {
                if (new_sensor_1_state == 0) {
                    log_proximity_event(1, "DETECTED");
                } else {
                    sensor_1_state = new_sensor_1_state;
                }
            }
        }

        if (new_sensor_2_state != sensor_2_state) {
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce
            new_sensor_2_state = gpioRead(SENSOR_2_GPIO);
            if (new_sensor_2_state != sensor_2_state) {
                if (new_sensor_2_state == 0) {
                    log_proximity_event(2, "DETECTED");
                } else {
                    sensor_2_state = new_sensor_2_state;
                }
            }
        }

        gpioDelay(10000); // 10ms
    }

    gpioTerminate();
    return 0;
}

