char* get_iso8601_timestamp();

// Helper function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buffer[1];
    if (read(fd, buffer, 1) != 1) {
        fprintf(stderr, "Error reading register value: %s\n", strerror(errno));
        return -1;
    }
    return buffer[0];
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        fprintf(stderr, "Error writing register value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Trigger measurement function
int trigger_measurement(int fd) {
    if (i2c_write_register(fd, MEAS_TRIGGER_REG, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    return 0;
}

// Read distance function
int read_distance(int fd, int *distance_mm) {
    uint8_t status;
    int retries = 3;

    while (retries > 0) {
        status = i2c_read_register(fd, MEAS_STATUS_REG);
        if (status == 0x01) {
            break; // Data ready
        } else {
            usleep(10000); // 10ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    uint8_t high_byte, low_byte;
    if (i2c_read_register(fd, DIST_HIGH_REG) != 0) {
        fprintf(stderr, "Error reading DIST_HIGH register\n");
        return -1;
    }
    high_byte = i2c_read_register(fd, DIST_HIGH_REG);

    if (i2c_read_register(fd, DIST_LOW_REG) != 0) {
        fprintf(stderr, "Error reading DIST_LOW register\n");
        return -1;
    }
    low_byte = i2c_read_register(fd, DIST_LOW_REG);

    *distance_mm = (high_byte << 8) | low_byte;
    return 0;
}

// Log data function
int log_data(const char *timestamp, int distance_mm) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%d\n", timestamp, distance_mm);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }

    // Main loop
    while (!terminate) {
        int distance_mm;
        char *timestamp = get_iso8601_timestamp();

        if (trigger_measurement(i2c_fd) == 0) {
            if (read_distance(i2c_fd, &distance_mm) == 0) {
                if (log_data(timestamp, distance_mm) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Error reading distance\n");
            }
        } else {
            fprintf(stderr, "Error triggering measurement\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 500ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

