#define MLX75030_ADDR 0x4C

// Define the register address for distance data (replace with actual address)
#define DISTANCE_REG 0x00

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read distance from the sensor
int read_distance() {
    int distance = -1; // Initialize to an error value
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, DISTANCE_REG);
        if (result >= 0) {
            distance = result;
            break; // Exit the loop if read is successful
        } else {
            fprintf(stderr, "I2C read failed, retrying... (%d retries left)\n", retries);
            gpioDelay(10); // Wait 10 ms before retrying
            retries--;
        }
    }

    if (distance == -1) {
        fprintf(stderr, "I2C read failed after multiple retries. Sensor or bus issue?\n");
    }

    return distance;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance != -1) {
            // Get current timestamp
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

            // Print the distance with timestamp
            printf("%ld: Distance = %d mm\n", timestamp_ms, distance);
        } else {
            fprintf(stderr, "Failed to read distance. Skipping.\n");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

