#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x00C0
#define VL53L4CX_REG_SYSTEM_START 0x0000
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0096
#define VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0097

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l4cx_init();
int vl53l4cx_read_distance();
void signal_handler(int signal);
void log_data(time_t timestamp, int distance);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the VL53L4CX sensor
int vl53l4cx_init() {
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Failed to read sensor ID: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }
    if (status != 0xE1) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x7FFF, 0x00);
    if (status < 0) {
        fprintf(stderr, "Failed to write soft reset: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    // Start ranging
    status = i2cWriteByteData(i2c_handle, 0x0009, 0x01);
    if (status < 0) {
        fprintf(stderr, "Failed to write start ranging: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L4CX sensor
int vl53l4cx_read_distance() {
    int status;
    int distance;

    // Read range status
    status = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Failed to read range status: %d\n", status);
        return -1;
    }

    // Read distance
    distance = i2cReadWordData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Failed to read distance: %d\n", distance);
        return -1;
    }

    return distance;
}

// Function to log data with timestamp
void log_data(time_t timestamp, int distance) {
    struct tm *timeinfo;
    char timestamp_str[30];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s.%06ld, Distance: %d mm\n", timestamp_str, (long)timestamp, distance);
}

int main() {
    int distance;
    time_t current_time;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize VL53L4CX sensor
    if (vl53l4cx_init() != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read distance
        distance = vl53l4cx_read_distance();
        if (distance >= 0) {
            // Get current timestamp
            current_time = time(NULL);

            // Log data
            log_data(current_time, distance);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

