#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE -90.0       // degrees
#define MAX_ANGLE +90.0       // degrees
#define TIMEOUT_MS 50          // milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void log_data(float distance);
float measure_distance();
void set_servo_angle(float distance);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log data to file
void log_data(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(2);              // Wait 2 us
    gpioWrite(TRIGGER_PIN, 1); // Send trigger pulse
    gpioDelay(10);             // Wait 10 us
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_MS) {
        gpioDelay(1); // Check every 1 us
        timeout++;
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Error: Echo signal timeout (low).\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_MS) {
        gpioDelay(1); // Check every 1 us
        timeout++;
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Error: Echo signal timeout (high).\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 to get one-way distance

    return distance;
}

// Function to set servo angle based on distance
void set_servo_angle(float distance) {
    float angle;

    if (distance < MIN_DISTANCE) {
        angle = MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        angle = MAX_ANGLE;
    } else {
        angle = MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    // Convert angle to pulse width (500-2500 us)
    int pulse_width = (int)(500 + (angle * 2000.0 / 180.0));

    gpioServo(SERVO_PIN, pulse_width);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();        // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        return 1;
    }

    printf("Parking-assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance > 0) {
            log_data(distance);
            set_servo_angle(distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        gpioDelay(200); // Wait 200 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

