#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/msg.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define DISTANCE_THRESHOLD 100 // mm
#define BUZZER_GPIO 23
#define MSG_QUEUE_KEY 1234
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0096
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0097

// Global variables
int i2c_handle;
int msg_queue_id;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance();
void activate_buzzer();
void deactivate_buzzer();
void log_distance(int distance);
void signal_handler(int signal);
void cleanup();

// Structure for message queue
struct msgbuf {
    long mtype;         // Message type (must be > 0)
    int distance;       // Distance in millimeters
};

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize VL53L1X sensor
int init_vl53l1x() {
    char data[2];
    int result;

    // Check sensor model ID
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    result = i2cWriteI2CBlockData(i2c_handle, data[0], data, 1); // Write register address
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    result = i2cReadI2CBlockData(i2c_handle, data[0], data, 1); // Read model ID
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    if (data[0] != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", data[0]);
        return -1;
    }

    // Perform software reset
    data[0] = 0x0000;
    data[1] = 0x00;
    result = i2cWriteI2CBlockData(i2c_handle, data[0], data, 2);
    if (result < 0) {
