#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define BUZZER_ACTIVE_TIME 100 // ms

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;
volatile int buzzer_active = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 0; // Reset echo_received flag
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1; // Set echo_received flag
    }
}

// Function to calculate distance from pulse width
float calculate_distance(unsigned int pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Indicate timeout
    }

    // Handle pigpio's 32-bit tick wraparound
    if (start_tick > end_tick) {
        start_tick -= 4294967296; // Subtract 2^32 - 1
    }

    float distance = (float)(pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
    return distance;
}

// Function to control the buzzer based on distance
void control_buzzer(float distance) {
    if (distance < 30.0 && !buzzer_active) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
        buzzer_active = 1;
        printf("Buzzer ON\n");
    } else if (distance >= 30.0 && buzzer_active) {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
        buzzer_active = 0;
        printf("Buzzer OFF\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(100); // Wait 100 ms

        if (echo_received) {
            unsigned int pulse_width = end_tick - start_tick;
            float distance = calculate_distance(pulse_width);

            if (distance < 0) {
                printf("Sensor absent or timeout\n");
            } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Invalid reading: %.2f cm\n", distance);
            } else {
                printf("Distance: %.2f cm\n", distance);
                control_buzzer(distance);
            }
        } else {
            printf("No echo received\n");
        }
    }

    return 0;
}

