#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

// Configuration
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define LOG_FILE "gate_log.txt"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "gate_control"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int init_vl53l1x(int fd);
int read_distance(int fd);
int control_gate(int open);
int log_event(const char *event);
int mqtt_connect(const char *client_id, const char *host, int port, const char *client_id);
int mqtt_publish(const char *topic, const char *payload);
void signal_handler(int signal);
void cleanup();

// I2C initialization
int init_i2c(int bus, int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// VL53L1X initialization
int init_vl53l1x(int fd) {
    // Software reset
    char reset_cmd[] = {0x00, 0x00, 0x00, 0x00};
    if (write(fd, reset_cmd, sizeof(reset_cmd)) != sizeof(reset_cmd)) {
        perror("Failed to send reset command");
        return -1;
    }
    gpioDelay(10000); // Wait for reset

    // Start ranging
    char start_ranging_cmd[] = {0x00, 0x00, 0x00, 0x00};
    if (write(fd, start_ranging_cmd, sizeof(start_ranging_cmd)) != sizeof(start_ranging_cmd)) {
        perror("Failed to send start ranging command");
        return -1;
    }
    gpioDelay(10000); // Wait for ranging

    return 0;
}

// Read distance from VL53L1X
int read_distance(int fd) {
    char cmd[] = {0x00, 0x00, 0x00, 0x00};
    if (write(fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to send read distance command");
        return -1;
    }
    gpioDelay(10000); // Wait for data

    char buffer[2];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to read distance data");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

// Control the gate
int control_gate(int open) {
    if (open) {
        gpioServo(SERVO_PIN, 1500); // Open
        log_event("Gate opened");
    } else {
        gpioServo(SERVO_PIN, 1000); // Close
        log_event("Gate closed");
    }
    return 0;
}

// Log events to file
int log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
    return 0;
}

// MQTT connection
int mqtt_connect(const char *client_id, const char *host, int port, const char *client_id) {
    mosquitto_lib_init();
    mosq = mosquitto_new(client_id, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    int rc = mosquitto_connect(mosq, host, port, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// MQTT publish
int mqtt_publish(const char *topic, const char *payload) {
    int rc = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
