// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MIN_PULSE_WIDTH 100   // us
#define MAX_PULSE_WIDTH 30000 // us
#define TIMEOUT_MS 60

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(uint32_t pulse_width);
void log_data(float distance);
void log_error(const char *message);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for ECHO pin
void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t rising_tick = 0;
    static uint32_t falling_tick = 0;

    if (level == 1) {
        rising_tick = tick;
    } else if (level == 0) {
        falling_tick = tick;
    }
}

// Function to calculate distance from pulse width
float calculate_distance(uint32_t pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        log_error("Invalid pulse width: too short");
        return -1.0; // Indicate error
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        log_error("Invalid pulse width: too long");
        return -1.0; // Indicate error
    }

    return (float)pulse_width * SPEED_OF_SOUND / 2.0;
}

// Function to log data to stdout and file
void log_data(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (log_file != NULL) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    }
}

// Function to log errors to stdout and file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(stderr, "%s ERROR: %s\n", timestamp, message);

    if (log_file != NULL) {
        fprintf(log_file, "%s ERROR: %s\n", timestamp, message);
        fflush(log_file); // Ensure data is written to file immediately
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(200); // Wait 200 ms

        uint32_t pulse_width = 0;
        if (gpioRead(ECHO_PIN) == 1) {
            pulse_width = gpioTick() - rising_tick;
        } else if (gpioRead(ECHO_PIN) == 0) {
            pulse_width = gpioTick() - falling_tick;
        } else {
            log_error("Timeout waiting for ECHO pin to change");
            gpioDelay(200); // Wait 200 ms
            continue;
        }

        float distance = calculate_distance(pulse_width);

        if (distance >= 0) {
            log_data(distance);
        } else {
            log_error("Invalid distance reading");
        }

        if (gpioRead(ECHO_PIN) == 0) {
            // Timeout occurred
            log_error("Timeout waiting for ECHO pin to go high");
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

