#define INTERRUPT_PIN 24
#define DISTANCE_THRESHOLD_OPEN 50 // cm
#define DISTANCE_THRESHOLD_CLOSE 60 // cm
#define SERVO_OPEN_PULSE_WIDTH 2000 // us
#define SERVO_CLOSE_PULSE_WIDTH 1000 // us
#define SERVO_OPEN_DURATION 500 // ms
#define SERVO_CLOSE_DURATION 500 // ms
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int write_register(int handle, int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, int reg, int *value) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    char buf[1];
    if (i2cReadDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    *value = buf[0];
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    int model_id;

    // Check sensor ID
    if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", model_id);
        return -1;
    }

    // Add VL53L1X initialization sequence here (example)
    // This is a placeholder, refer to the VL53L1X datasheet for the correct sequence
    if (write_register(i2c_handle, 0x002d, 0x04) != 0) return -1; // Example register write
    if (write_register(i2c_handle, 0x002e, 0x01) != 0) return -1; // Example register write
    if (write_register(i2c_handle, 0x0000, 0x00) != 0) return -1; // Example register write

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    int distance;
    int ready;

    // Check if data is ready
    if (read_register(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, &ready) != 0) {
        fprintf(stderr, "Error reading data ready status\n");
        return -1;
    }

    if (!ready) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read the distance
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    return distance;
}

