    gpioPWM(SERVO_PIN, SERVO_CLOSE_PULSE_WIDTH);
    log_event("Gate closed", -1); // Distance unknown
    gpioDelay(SERVO_CLOSE_DURATION * 1000); // Convert ms to us
    gpioPWM(SERVO_PIN, 0); // Stop PWM
}

