#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define VL53L1X_ADDR 0x29
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define GPIO_TRIGGER 24
#define DISTANCE_THRESHOLD_FORWARD 100 // mm
#define DISTANCE_THRESHOLD_BACKWARD 300 // mm
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void trigger_sensor();
void signal_handler(int signal);

// VL53L1X Register Addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0024
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    // Soft reset
    if (vl53l1x_write_byte(i2c_handle, 0x0000, 0x00) != 0) return -1;
    gpioDelay(1); // Wait 1 ms

    // Start measurement
    if (vl53l1x_write_byte(i2c_handle, 0x0000, 0x01) != 0) return -1;

    // Configure for short-range mode (example configuration)
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x0A) != 0) return -1; // Set SNR
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN, 0x0A) != 0) return -1; // Set Count Rate

    // Enable system sequence
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x40) != 0) return -1; // Start ranging

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int *distance) {
    uint8_t range_status;

    // Poll range status until data is ready
    while (1) {
        if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) return -1;
        if (range_status & 0x01) break; // Data ready
        gpioDelay(10); // Small delay
    }

    // Read distance
    uint8_t distance_msb, distance_lsb;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_msb) != 0) return -1;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &distance_lsb) != 0) return -1;

    *distance = (distance_msb << 8) | distance_lsb;

    return 0;
}

// Function to control the motor forward
void motor_forward() {
    gpioWrite(GPIO_MOTOR_FORWARD, 1);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    printf("Motor: Forward\n");
}

// Function to control the motor backward
void motor_backward() {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 1);
    printf("Motor: Backward\n");
}

// Function to stop the motor
void motor_stop() {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    printf("Motor: Stopped\n");
}

// Function to trigger the sensor
void trigger_sensor() {
    gpioTrigger(GPIO_TRIGGER, 1, 1); // Rising edge
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

