#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0     // cm
#define TIMEOUT_US 30000        // 30 ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int gpio_request(int pin, const char *direction);
int gpio_unrequest(int pin);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
int gpio_line_request(int pin, const char *direction);
int gpio_line_release(int pin);
void trigger_pulse();
long long echo_start_time, echo_end_time;
double distance_cm;
void log_distance(double distance);
void signal_handler(int sig);

// GPIO request function
int gpio_request(int pin, const char *direction) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as %s: %s\n", pin, direction, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// GPIO unrequest function
int gpio_unrequest(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d value to %d: %s\n", pin, value, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// GPIO get value function
int gpio_get_value(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not get GPIO line %d value: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return ret;
}

// Trigger pulse function
void trigger_pulse() {
    if (gpio_set_value(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin low\n");
        program_running = 0; // Stop the program
        return;
    }
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 5 * 1000000; // 5 microseconds
    nanosleep(&ts, NULL);

    if (gpio_set_value(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin high\n");
        program_running = 0; // Stop the program
        return;
    }
    struct timespec ts_high;
    ts_high.tv_sec = 0;
    ts_high.tv_nsec = 10 * 1000000; // 10 microseconds
    nanosleep(&ts_high, NULL);

    if (gpio_set_value(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin low\n");
        program_running = 0; // Stop the program
        return;
    }
}

// Echo start time
long long echo_start_time = 0;

// Echo end time
long long echo_end_time = 0;

// Distance in centimeters
double distance_cm = 0.0;

// Log distance function
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO pins
    if (gpio_request(TRIGGER_PIN, "out") < 0) {
        fclose(log_file);
        return 1;
    }
    if (gpio_request(ECHO_PIN, "in") < 0) {
        gpio_unrequest(TRIGGER_PIN);
        fclose(log_file);
        return 1;
    }

    // Request echo line as input
    if (gpio_line_request(ECHO_PIN, "in") < 0) {
        gpio_unrequest(TRIGGER_PIN);
        fclose(log_file);
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for echo rising edge with timeout
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        echo_start_time = start.tv_sec * 1000000000LL + start.tv_nsec;
        while (gpio_get_value(ECHO_PIN) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            echo_end_time = end.tv_sec * 1000000000LL + end.tv_nsec;
            if ((echo_end_time - echo_start_time) > TIMEOUT_US) {
                fprintf(stderr, "Error: Echo rising edge timeout\n");
                program_running = 0; // Stop the program
                break;
            }
        }

        // Measure echo pulse width with timeout
        clock_gettime(CLOCK_MONOTONIC, &start);
        echo_start_time = start.tv_sec * 1000000000LL + start.tv_nsec;
        while (gpio_get_value(ECHO_PIN) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            echo_end_time = end.tv_sec * 1000000000LL + end.tv_nsec;
            if ((echo_end_time - echo_start_time) > TIMEOUT_US) {
                fprintf(stderr, "Error: Echo falling edge timeout\n");
                program_running = 0; // Stop the program
                break;
            }
        }

        // Calculate distance
        distance_cm = (echo_end_time - echo_start_time) * SPEED_OF_SOUND / 2000000.0 * 0.0343 / 2.0; // cm

        // Validate distance
        if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
            fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance_cm);
            log_distance(-1.0); // Log an error value
        } else {
            log_distance(distance_cm);
        }

        // Wait for 1 second
        struct timespec ts;
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpio_unrequest(TRIGGER_PIN);
    gpio_line_release(ECHO_PIN);
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

