    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 5 * 1000000; // 5 microseconds
    nanosleep(&ts, NULL);

    if (gpio_set_value(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin high\n");
        program_running = 0; // Stop the program
        return;
    }
    struct timespec ts_high;
    ts_high.tv_sec = 0;
    ts_high.tv_nsec = 10 * 1000000; // 10 microseconds
    nanosleep(&ts_high, NULL);

    if (gpio_set_value(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set trigger pin low\n");
        program_running = 0; // Stop the program
        return;
    }
}

// Echo start time
long long echo_start_time = 0;

// Echo end time
long long echo_end_time = 0;

// Distance in centimeters
double distance_cm = 0.0;

// Log distance function
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO pins
    if (gpio_request(TRIGGER_PIN, "out") < 0) {
        fclose(log_file);
        return 1;
    }
    if (gpio_request(ECHO_PIN, "in") < 0) {
        gpio_unrequest(TRIGGER_PIN);
        fclose(log_file);
        return 1;
    }

    // Request echo line as input
    if (gpio_line_request(ECHO_PIN, "in") < 0) {
        gpio_unrequest(TRIGGER_PIN);
        fclose(log_file);
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for echo rising edge with timeout
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        echo_start_time = start.tv_sec * 1000000000LL + start.tv_nsec;
        while (gpio_get_value(ECHO_PIN) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            echo_end_time = end.tv_sec * 1000000000LL + end.tv_nsec;
            if ((echo_end_time - echo_start_time) > TIMEOUT_US) {
                fprintf(stderr, "Error: Echo rising edge timeout\n");
                program_running = 0; // Stop the program
                break;
            }
        }

        // Measure echo pulse width with timeout
        clock_gettime(CLOCK_MONOTONIC, &start);
        echo_start_time = start.tv_sec * 1000000000LL + start.tv_nsec;
        while (gpio_get_value(ECHO_PIN) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            echo_end_time = end.tv_sec * 1000000000LL + end.tv_nsec;
            if ((echo_end_time - echo_start_time) > TIMEOUT_US) {
                fprintf(stderr, "Error: Echo falling edge timeout\n");
                program_running = 0; // Stop the program
                break;
            }
        }

        // Calculate distance
        distance_cm = (echo_end_time - echo_start_time) * SPEED_OF_SOUND / 2000000.0 * 0.0343 / 2.0; // cm

        // Validate distance
        if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
            fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance_cm);
            log_distance(-1.0); // Log an error value
        } else {
            log_distance(distance_cm);
        }

        // Wait for 1 second
        struct timespec ts;
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpio_unrequest(TRIGGER_PIN);
    gpio_line_release(ECHO_PIN);
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

