#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_PULSE_WIDTH 58.0   // Minimum pulse width in microseconds (1cm)
#define MAX_PULSE_WIDTH 25000.0 // Maximum pulse width in microseconds (4m)
#define MIN_DISTANCE 1.0       // Minimum distance in meters
#define MAX_DISTANCE 4.0       // Maximum distance in meters

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_width = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
void log_distance(float distance);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        echo_received = 1; // Indicate that an echo has been received
    } else if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;
        echo_received = 0; // Reset the flag after processing the pulse
    }
}

// Function to trigger the ultrasonic pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Function to calculate distance in meters
float calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate an error
    }

    // Handle tick-wraparound
    if (pulse_width < 0) {
        pulse_width += 4294967295; // Maximum value of an unsigned 32-bit integer
    }

    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt-driven ISR
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(1000); // Wait 1 second

        if (echo_received) {
            int pulse_width = pulse_width; // Use the variable after ISR is called
            float distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
                printf("Distance: %.2f meters\n", distance);
            } else {
                fprintf(stderr, "Invalid distance measurement: %.2f meters\n", distance);
            }
        } else {
            fprintf(stderr, "No echo received.\n");
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    fclose(log_file);
    gpioTerminate();

    return 0;
}

