// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0010
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0016
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0014

// GPIO pin for active-low trigger
#define TRIGGER_PIN 27

// I2C handle
int i2c_handle;

// Function prototypes
int init_vl53l1x();
int read_distance();
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, cleaning up...", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Configure GPIO27 as output
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1); // Enable sensor

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Check if the I2C device is valid
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        syslog(LOG_ERR, "Failed to read model ID: %d", model_id);
        i2cClose(i2c_handle);
        return -1;
    }
    if (model_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect model ID: 0x%02X", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure sensor for continuous ranging
    if (i2cWriteByteData(i2c_handle, 0x0018, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0018");
        i2cClose(i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0019, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0019");
        i2cClose(i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0020, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0020");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L1X sensor
int read_distance() {
    int distance = -1;
    int status = -1;

    // Read distance
    distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        syslog(LOG_ERR, "Failed to read distance");
        return -1;
    }

    // Read status
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        syslog(LOG_ERR, "Failed to read status");
        return -1;
    }

    return distance;
}

// Function to log data to the systemd journal
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s, Distance: %d mm, Status: %d", timestamp, distance, status);
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance >= 0) {
            log_data(distance, 0); // Status 0 for success
        } else {
            log_data(-1, -1); // Log error
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return 0;
}

