#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_MS 30
#define TRIGGER_PULSE_DURATION_US 10
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define MOVING_AVG_SIZE 5

// Global variables
volatile sig_atomic_t program_running = 1;
volatile int echo_received = 0;
volatile int pulse_width = 0;
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_valid = 0;

// Moving average filter buffer
float distance_buffer[MOVING_AVG_SIZE];
int buffer_index = 0;
float distance_average = 0.0;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(uint32_t pulse_width);
float apply_moving_average(float new_distance);
int map_distance_to_angle(float distance);
int map_angle_to_pulse_width(float angle);
int set_servo_angle(int pulse_width);
int log_data(float distance, float angle);
void echo_tick(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1;
    } else if (level == 0) {
        echo_end_tick = tick;
        if (echo_received) {
            pulse_width = echo_end_tick - echo_start_tick;
            echo_received = 0;
        }
    }
}

// Calculate distance from pulse width
float calculate_distance(uint32_t pulse_width) {
    if (pulse_width == 0) return -1.0; // Indicate no echo
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s
    return distance;
}

// Apply moving average filter
float apply_moving_average(float new_distance) {
    distance_buffer[buffer_index] = new_distance;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;

    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_buffer[i];
    }
    distance_average = sum / MOVING_AVG_SIZE;
    return distance_average;
}

// Map distance to servo angle (logarithmic mapping)
int map_distance_to_angle(float distance) {
    if (distance < 2.0) return 0;
    if (distance > 400.0) return 180;
    float angle = (log10(distance / 2.0) - log10(400.0 / 2.0)) * (SERVO_MAX_ANGLE / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));
    return (int)angle;
}

// Map servo angle to pulse width
int map_angle_to_pulse_width(float angle) {
    float pulse_width = (angle / SERVO_MAX_ANGLE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH;
    return (int)pulse_width;
}

// Set servo angle
int set_servo_angle(int pulse_width) {
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", pulse_width);
        return -1;
    }
    return 0;
}

// Log data to CSV file
int log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Echo tick function
void echo_tick(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
    } else if (level == 0) {
        echo_end_tick = tick;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Angle (degrees)\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (program_running) {
        // Trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_count = 0;
        while (!echo_received && timeout_count < TIMEOUT_MS) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout_count++;
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            distance_average = 0.0; // Reset moving average
            set_servo_angle(90); // Set servo to a default position
            log_data(-1.0, 90.0); // Log -1.0 and servo angle 90
            continue; // Skip to the next iteration
        }

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Apply moving average filter
        distance_average = apply_moving_average(distance);

        // Map distance to angle
        float angle = map_distance_to_angle(distance_average);

        // Map angle to pulse width
        int pulse_width = map_angle_to_pulse_width(angle);

        // Set servo angle
        if (set_servo_angle(pulse_width) != 0) {
            fprintf(stderr, "Error setting servo angle.\n");
        }

        // Log data
        if (log_data(distance_average, angle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    set_servo_angle(90); // Set servo to a default position
    fclose(log_file);
    gpioTerminate();

    return 0;
}

