#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define PROX_REG_HIGH 0x08
#define PROX_REG_LOW 0x09
#define GPIO_PIN 27
#define DEFAULT_THRESHOLD 1000
#define LOG_FILE "proximity.log"

// Global variables
static int i2c_handle;
static volatile int interrupt_flag = 0;
static int threshold = DEFAULT_THRESHOLD;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(int address);
int read_proximity(int handle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void log_proximity(int proximity, int status);
void signal_handler(int signal);

// Structure to pass data to the interrupt handler
typedef struct {
    int proximity;
} ProximityData;

// Function to initialize I2C
int init_i2c(int address) {
    int handle = i2cOpen(I2C_BUS, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read proximity value from the sensor
int read_proximity(int handle) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, PROX_REG_HIGH, buf, 2) != 2) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    return (buf[1] << 8) | buf[0];
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    ProximityData *data = (ProximityData *)user;
    data->proximity = read_proximity(i2c_handle);
    interrupt_flag = 1;
}

// Function to log proximity data to a file
void log_proximity(int proximity, int status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;
    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                int addr = strtol(optarg, NULL, 0);
                if (addr == 0x60 || addr == 0x61 || addr == 0x62 || addr == 0x63) {
                    threshold = atoi(optarg);
                } else {
                    fprintf(stderr, "Invalid I2C address: 0x%x\n", addr);
                    return 1;
                }
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(SI1102_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure GPIO for interrupt
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Threshold: %d\n", threshold);

    // Main loop
    while (1) {
        if (interrupt_flag) {
            int proximity = read_proximity(i2c_handle);
            if (proximity >= 0) {
                log_proximity(proximity, (proximity > threshold) ? 1 : 0);
            }
            interrupt_flag = 0;
        }
        gpioDelay(100); // Check every 100ms
    }

    return 0;
}

