#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0    // Hz
#define MAX_FREQUENCY 2000.0   // Hz
#define TIMEOUT 200000          // us (200ms)

// Global variables
volatile int running = 1;
volatile int previous_frequency = 0; // Store the previous frequency

// Function prototypes
void signal_handler(int signal);
float measure_distance();
float map_distance_to_frequency(float distance);
void set_frequency(int frequency);
void stop_pwm();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
    stop_pwm();
    gpioTerminate();
    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        gpioDelay(1); // Check every 1 us
        timeout--;
    }

    if (timeout <= 0) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        gpioDelay(1); // Check every 1 us
        timeout--;
    }

    if (timeout <= 0) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;

    if (diff < 0) {
        diff += 4294967295; // Handle tick rollover
    }

    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

// Function to map distance to frequency using a logarithmic scale
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return previous_frequency; // Keep the previous frequency if out of range
    }

    float frequency = MIN_FREQUENCY * exp((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
    return frequency;
}

// Function to set the PWM frequency and duty cycle
void set_frequency(int frequency) {
    if (frequency < 200 || frequency > 2000) {
        fprintf(stderr, "Error: Frequency out of range (200-2000 Hz)\n");
        return;
    }

    int range = 1000000 / frequency; // Calculate PWM range
    int duty_cycle = range / 2;       // 50% duty cycle

    gpioSetPWMfrequency(SPEAKER_PIN, frequency);
    gpioPWM(SPEAKER_PIN, duty_cycle);
}

// Function to stop PWM output
void stop_pwm() {
    gpioPWM(SPEAKER_PIN, 0); // Set duty cycle to 0 to stop the tone
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(SPEAKER_PIN, 1000000); // 1 MHz PWM range

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();
        if (distance > 0) {
            float frequency = map_distance_to_frequency(distance);
            set_frequency((int)frequency);
            previous_frequency = (int)frequency;
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(50); // Delay for 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_pwm();
    gpioTerminate();

    return 0;
}

