// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 29.1 // cm/us
#define MIN_DISTANCE 2.0    // cm
#define MAX_DISTANCE 400.0  // cm
#define TIMEOUT 50          // ms

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void trigger_pulse();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void print_distance(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width with timeout
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT * 1000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT * 1000) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT * 1000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT * 1000) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate distance from pulse width
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width / 2.0 / SPEED_OF_SOUND;
}

// Function to print the distance
void print_distance(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        printf("Invalid reading\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
        if (distance < 10.0) {
            printf("Too close!\n");
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            print_distance(distance);
        } else {
            fprintf(stderr, "Timeout occurred\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

