#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor and GPIO parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define CS_PIN 8
#define MAX_DISTANCE 5000 // mm
#define MIN_DISTANCE 200  // mm

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
int log_distance(int distance);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor configuration
typedef struct {
    int spi_channel;
    int spi_baud;
    int cs_pin;
    int max_distance;
    int min_distance;
} sensor_config_t;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the sensor
int initialize_sensor() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    // Initialize sensor (example configuration)
    char init_data[] = {0x01, 0x02, 0x00, 0x01};
    spiWrite(spi_handle, init_data, sizeof(init_data));

    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char tx_buf[2] = {0x00, 0x0C}; // Register address for low byte
    char rx_buf[2];
    int result;

    gpioWrite(CS_PIN, 0); // Activate CS
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    if (result != 2) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Combine high and low bytes
    *distance = (rx_buf[1] << 8) | rx_buf[0];

    return 0;
}

// Log distance to file
int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    int distance;
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %d\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

