#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // Standard I2C bus on Raspberry Pi
#define SI1175_ADDR 0x60      // Default I2C address of Si1175
#define ALS_VIS_DATA_REG 0x22 // Register address for visible ambient light data (low byte)
#define ALS_VIS_DATA_REG_HIGH 0x23 // Register address for visible ambient light data (high byte)
#define CSV_FILE "proximity_log.csv" // CSV file to log data to

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // File pointer for the CSV file
volatile sig_atomic_t terminate = 0; // Flag to signal termination

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_write(int fd, uint8_t reg, uint8_t value);
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len);
uint16_t read_als_visible(int fd);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, uint16_t als_visible);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Function to read the visible ambient light value
uint16_t read_als_visible(int fd) {
    uint8_t low_byte, high_byte;

    if (i2c_read(fd, ALS_VIS_DATA_REG, &low_byte, 1) < 0) {
        fprintf(stderr, "Error reading low byte of ALS data\n");
        return 0; // Return 0 on error
    }

    if (i2c_read(fd, ALS_VIS_DATA_REG_HIGH, &high_byte, 1) < 0) {
        fprintf(stderr, "Error reading high byte of ALS data\n");
        return 0; // Return 0 on error
    }

    return (uint16_t)((high_byte << 8) | low_byte);
}

// Function to get the current timestamp in ISO-8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log the data to a CSV file
int log_data(const char *timestamp, uint16_t als_visible) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%u\n", timestamp, als_visible) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = i2c_open(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Open the CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read the visible ambient light value
        uint16_t als_visible = read_als_visible(i2c_fd);

        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp\n");
            break; // Exit the loop if timestamp retrieval fails
        }

        // Log the data to the CSV file
        if (log_data(timestamp, als_visible) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        free(timestamp); // Free the allocated memory for the timestamp

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the I2C bus and the CSV file
    close(i2c_fd);
    fclose(log_file);

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

