#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET 0x30
#define SI1120_REG_ALS_LOW 0x22
#define SI1120_REG_ALS_HIGH 0x23
#define SI1120_REG_PS1_LOW 0x18
#define SI1120_REG_PS1_HIGH 0x19
#define SI1120_RESET_VALUE 0x01
#define SI1120_PART_ID_VALUE 0x41

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1120();
int read_si1120_data(int *als, int *ps1);
int log_data(int als, int ps1);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1120 sensor
int init_si1120() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, SI1120_RESET_VALUE);
        if (result >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error resetting Si1120 (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }

    gpioDelay(100); // Wait for reset to complete

    // Verify the part ID
    int part_id;
    retries = 3;
    while (retries > 0) {
        part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (part_id >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading Si1120 part ID (attempt %d): %d\n", 4 - retries, part_id);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read Si1120 part ID after multiple retries.\n");
        return -1;
    }

    if (part_id != SI1120_PART_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect Si1120 part ID: 0x%02x (expected 0x%02x)\n", part_id, SI1120_PART_ID_VALUE);
        return -1;
    }

    printf("Si1120 initialized successfully.\n");
    return 0;
}

// Read ALS and proximity data from the Si1120 sensor
int read_si1120_data(int *als, int *ps1) {
    int als_low, als_high, ps1_low, ps1_high;
    int retries = 3;

    while (retries > 0) {
        als_low = i2cReadByteData(i2c_handle, SI1120_REG_ALS_LOW);
        if (als_low >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading ALS low byte (attempt %d): %d\n", 4 - retries, als_low);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }

        ps1_low = i2cReadByteData(i2c_handle, SI1120_REG_PS1_LOW);
        if (ps1_low >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading PS1 low byte (attempt %d): %d\n", 4 - retries, ps1_low);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }

        als_high = i2cReadByteData(i2c_handle, SI1120_REG_ALS_HIGH);
        if (als_high >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading ALS high byte (attempt %d): %d\n", 4 - retries, als_high);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }

        ps1_high = i2cReadByteData(i2c_handle, SI1120_REG_PS1_HIGH);
        if (ps1_high >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading PS1 high byte (attempt %d): %d\n", 4 - retries, ps1_high);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read Si1120 data after multiple retries.\n");
        return -1;
    }

    *als = (als_low << 8) | als_high;
    *ps1 = (ps1_low << 8) | ps1_high;

    return 0;
}

// Log the data to a file
int log_data(int als, int ps1) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %d, PS1: %d\n", timestamp, als, ps1);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int als, ps1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1120 sensor
    if (init_si1120() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_si1120_data(&als, &ps1) == 0) {
            log_data(als, ps1);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

