#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x60
#define PS1_DATA0 0x16
#define PS1_DATA1 0x17
#define PS_FORCE 0x80
#define MEAS_RATE 0x06
#define HW_KEY 0x07
#define ALS_VIS_IR_ADC_COUNTER 0x21
#define ALS_VIS_ADC_GAIN 0x24
#define PS_ADC_COUNTER 0x22
#define PS_LED21 0x0C
#define PS_LED3 0x0F
#define PS_ADC_MISC 0x11
#define PS_ADC_GAIN 0x0D
#define COMMAND_REG 0x80

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_proximity();
void log_data(int proximity);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    // Reset the sensor
    status = i2cWriteByteData(i2c_handle, HW_KEY, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to HW_KEY: %d\n", status);
        return -1;
    }
    gpioDelay(10); // Delay after reset

    // Configure MEAS_RATE
    status = i2cWriteByteData(i2c_handle, MEAS_RATE, 0x02);
    if (status < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE: %d\n", status);
        return -1;
    }

    // Configure ALS_VIS_IR_ADC_COUNTER
    status = i2cWriteByteData(i2c_handle, ALS_VIS_IR_ADC_COUNTER, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to ALS_VIS_IR_ADC_COUNTER: %d\n", status);
        return -1;
    }

    // Configure ALS_VIS_ADC_GAIN
    status = i2cWriteByteData(i2c_handle, ALS_VIS_ADC_GAIN, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to ALS_VIS_ADC_GAIN: %d\n", status);
        return -1;
    }

    // Configure PS_ADC_COUNTER
    status = i2cWriteByteData(i2c_handle, PS_ADC_COUNTER, 0x49);
    if (status < 0) {
        fprintf(stderr, "Error writing to PS_ADC_COUNTER: %d\n", status);
        return -1;
    }

    // Configure PS_LED21
    status = i2cWriteByteData(i2c_handle, PS_LED21, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to PS_LED21: %d\n", status);
        return -1;
    }

    // Configure PS_LED3
    status = i2cWriteByteData(i2c_handle, PS_LED3, 0x0F);
    if (status < 0) {
        fprintf(stderr, "Error writing to PS_LED3: %d\n", status);
        return -1;
    }

    // Configure PS_ADC_MISC
    status = i2cWriteByteData(i2c_handle, PS_ADC_MISC, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to PS_ADC_MISC: %d\n", status);
        return -1;
    }

    // Configure PS_ADC_GAIN
    status = i2cWriteByteData(i2c_handle, PS_ADC_GAIN, 0x07);
    if (status < 0) {
        fprintf(stderr, "Error writing to PS_ADC_GAIN: %d\n", status);
        return -1;
    }

    // Force a measurement
    status = i2cWriteByteData(i2c_handle, COMMAND_REG, PS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error writing to COMMAND_REG: %d\n", status);
        return -1;
    }

    gpioDelay(10); // Delay after forcing measurement

    return 0;
}

// Function to read proximity data from the sensor
int read_proximity() {
    int low_byte, high_byte, proximity;

    low_byte = i2cReadByteData(i2c_handle, PS1_DATA0);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading PS1_DATA0: %d\n", low_byte);
        return -1;
    }

    high_byte = i2cReadByteData(i2c_handle, PS1_DATA1);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading PS1_DATA1: %d\n", high_byte);
        return -1;
    }

    proximity = (high_byte << 8) | low_byte;
    return proximity;
}

// Function to log data to a file
void log_data(int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int proximity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        proximity = read_proximity();
        if (proximity >= 0) {
            log_data(proximity);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, ERROR: Failed to read proximity data\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

