#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define BUZZER_DURATION 0.5 // seconds

// Global variables
static volatile int echo_start_time = 0;
static volatile int echo_end_time = 0;
static volatile int echo_received = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        running = 0;
        gpioTerminate();
        exit(0);
    }
}

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_time = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        echo_end_time = tick;
        echo_received = 0; // Reset the flag after falling edge
    }
}

