        fprintf(stderr, "Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(50); // Delay between measurements

        // Calculate pulse width
        int pulse_width = echo_end_time - echo_start_time;
        if (pulse_width < 0) {
            pulse_width = 0; // Handle potential overflow
        }

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Print distance
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);

            // Control buzzer
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error calculating distance\n");
        }

        gpioDelay(1000000); // Delay for 1 second
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

