#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout for echo pulse in microseconds
#define SERVO_MIN_PULSE_WIDTH 500 // Minimum pulse width for servo (500 us)
#define SERVO_MAX_PULSE_WIDTH 2500 // Maximum pulse width for servo (2500 us)
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define MIN_DISTANCE 200.0
#define MAX_DISTANCE 20.0
#define MIN_SERVO_ANGLE 0
#define MAX_SERVO_ANGLE 180
#define MIN_DISTANCE_CM 200.0
#define MAX_DISTANCE_CM 20.0
#define MIN_SERVO_ANGLE_CM 0
#define MAX_SERVO_ANGLE_CM 180

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int echo_received = 0;
volatile int echo_error = 0;
volatile int echo_timeout = 0;

// Function prototypes
float measure_distance();
void set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo start
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        echo_error = 1; // Indicate echo timeout
        return -1.0;     // Return -1.0 to indicate error
    }

    pulse_start = 0;
    pulse_end = 0;
    echo_received = 0;
    echo_timeout = 0;

    // Wait for echo end
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        echo_error = 1; // Indicate echo timeout
        return -1.0;     // Return -1.0 to indicate error
    }

    // Calculate pulse duration
    pulse_end = gpioTick();
    if (pulse_start == 0) {
        pulse_start = gpioTick();
    }

    int pulse_duration = pulse_end - pulse_start;

    // Calculate distance
    float distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // in cm

    // Validate distance
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        echo_error = 1; // Indicate invalid distance
        return -1.0;     // Return -1.0 to indicate error
    }

    return distance;
}

// Function to set servo angle
void set_servo_angle(int angle) {
    // Map angle (0-180) to pulse width (500-2500 us)
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)(angle) / 180.0 * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float distance = measure_distance();

        if (distance > 0) {
            // Calculate servo angle based on distance
            int servo_angle = (int)((MAX_DISTANCE_CM - distance) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) * 180.0);

            // Validate servo angle
            if (servo_angle < MIN_SERVO_ANGLE_CM || servo_angle > MAX_SERVO_ANGLE_CM) {
                echo_error = 1; // Indicate invalid distance
                distance = -1.0; // Return -1.0 to indicate error
            } else {
                set_servo_angle(servo_angle);
            }

            printf("Distance: %.2f cm, Servo Angle: %d\n", distance, servo_angle);
        } else {
            fprintf(stderr, "Error: Invalid distance or sensor error\n");
        }

        gpioDelay(100); // Delay 100 ms
    }

    return 0;
}

