#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define OPEN_PULSE_WIDTH 2000 // us
#define CLOSE_PULSE_WIDTH 1000 // us
#define DISTANCE_THRESHOLD_OPEN 200 // mm
#define DISTANCE_THRESHOLD_CLOSE 250 // mm
#define TIMING_BUDGET 0x00FA // 100ms
#define MODEL_ID_REG 0x010F
#define DISTANCE_REG 0x0089

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_sensor() {
    int model_id;

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Verify model ID
    model_id = i2cReadByteData(i2c_handle, MODEL_ID_REG);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    printf("VL53L1X sensor initialized successfully.\n");

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    int distance;

    distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }

    return distance;
}

// Open the gate by setting the servo pulse width
void open_gate() {
    gpioPWM(SERVO_PIN, OPEN_PULSE_WIDTH);
    log_event("Gate opened");
}

// Close the gate by setting the servo pulse width
void close_gate() {
    gpioPWM(SERVO_PIN, CLOSE_PULSE_WIDTH);
    log_event("Gate closed");
}

// Log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        printf("Distance: %d mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_OPEN) {
            open_gate();
        } else if (distance > DISTANCE_THRESHOLD_CLOSE) {
            close_gate();
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

