#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE 0.0          // degrees
#define MAX_ANGLE 180.0        // degrees
#define SERVO_MIN_PULSE_WIDTH 500 // us
#define SERVO_MAX_PULSE_WIDTH 2500 // us
#define TIMEOUT_US 50000         // 50 ms timeout

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int pulse_width = 0;
volatile int timeout_flag = 0;

// Function prototypes
float measure_distance();
int map_distance_to_angle(float distance);
void set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Stopping servo and exiting.\n");
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate();         // Terminate pigpio
        exit(0);
    }
}

// Function to measure distance using HC-SR04
float measure_distance() {
    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse width
    pulse_start = 0;
    pulse_end = 0;
    timeout_flag = 0;

    // Wait for the rising edge with timeout
    int start_seconds, start_micros;
    gpioTime(0, &start_seconds, &start_micros);
    while (gpioRead(ECHO_PIN) == 0) {
        if (pulse_start == 0) {
            pulse_start = gpioTick();
        }
        if (gpioTick() - pulse_start > TIMEOUT_US) {
            timeout_flag = 1;
            break;
        }
    }

    if (pulse_start == 0) return -1.0; // Timeout on rising edge

    // Wait for the falling edge with timeout
    gpioTime(0, &start_seconds, &start_micros);
    while (gpioRead(ECHO_PIN) == 1) {
        if (pulse_end == 0) {
            pulse_end = gpioTick();
        }
        if (gpioTick() - pulse_end > TIMEOUT_US) {
            timeout_flag = 1;
            break;
        }
    }

    if (pulse_end == 0) return -1.0; // Timeout on falling edge

    // Calculate the pulse width in microseconds
    pulse_width = pulse_end - pulse_start;

    // Check for timeout during falling edge
    if (pulse_end == 0) return -1.0; // Timeout on falling edge

    // Calculate the distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 to get one-way distance

    return distance;
}

// Function to map distance to servo angle
int map_distance_to_angle(float distance) {
    // Check for invalid distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range (%.2f cm)\n", distance);
        return -1; // Indicate an error
    }

    // Linear mapping
    float angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;

    // Ensure angle is within valid range
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    return (int)angle;
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    // Calculate pulse width based on angle
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Set the servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Measure distance
        float distance = measure_distance();

        // Check for timeout
        if (distance < 0) {
            if (timeout_flag) {
                fprintf(stderr, "Error: Timeout occurred during distance measurement\n");
            } else {
                fprintf(stderr, "Error: Distance measurement failed\n");
            }
        } else {
            // Map distance to angle
            int angle = map_distance_to_angle(distance);

            // Check for invalid angle
            if (angle == -1) {
                fprintf(stderr, "Error: Invalid angle returned\n");
            } else {
                // Set servo angle
                set_servo_angle(angle);

                // Print distance and angle
                printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
            }
        }

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

