#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define WHO_AM_I 0x75
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050(int i2c_handle) {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to stabilize

    // Set sample rate divider to 7 (125 Hz)
    if (i2cWriteByteData(i2c_handle, 0x19, 7) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Configure accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range to ±250 dps
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read raw data from the MPU-6050
int read_mpu6050_data(int i2c_handle, short *accel_x, short *accel_y, short *accel_z, short *gyro_x, short *gyro_y, short *gyro_z) {
    char buffer[14];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 14);

    if (bytes_read != 14) {
        fprintf(stderr, "Error: Could not read 14 bytes from MPU-6050\n");
        return -1;
    }

    *accel_x = (short)((buffer[0] << 8) | buffer[1]);
    *accel_y = (short)((buffer[2] << 8) | buffer[3]);
    *accel_z = (short)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (short)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (short)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (short)((buffer[12] << 8) | buffer[13]);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    short accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        if (read_mpu6050_data(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read MPU-6050 data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");

    return 0;
}

