#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// STS30-DIS I2C address
#define STS30_ADDR 0x4A

// I2C bus number
#define I2C_BUS 1

// Measurement command (high repeatability)
#define MEASURE_CMD 0x2C06

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sts30(int i2c_handle, float *temperature);
int log_temperature(FILE *log_file, float temperature);
int log_error(FILE *error_file, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error(error_file, "Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Read temperature from STS30-DIS sensor
int read_sts30(int i2c_handle, float *temperature) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buf[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error(error_file, "Failed to write measurement command");
        return -1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 12.1ms for high repeatability)

    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        log_error(error_file, "Failed to read temperature data");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return 0;
}

// Log temperature to file
int log_temperature(FILE *log_file, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Log error to file
int log_error(FILE *error_file, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_file, "%s, %s\n", timestamp, message);
    fflush(error_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("enclosure_temp_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen("error_log.txt", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fclose(log_file);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float temperature;
    while (!terminate) {
        if (read_sts30(i2c_handle, &temperature) == 0) {
            log_temperature(log_file, temperature);
        } else {
            log_error(error_file, "Failed to read temperature");
        }
        sleep(5);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    fclose(error_file);
    gpioTerminate();

    return 0;
}

