#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x36
#define MEASURE_CMD_LEN 2
#define DATA_FRAME_LEN 9
#define LOG_FILE "pressure_log.csv"
#define POLL_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd[MEASURE_CMD_LEN] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buffer[DATA_FRAME_LEN];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, MEASURE_CMD_LEN);
    if (result != MEASURE_CMD_LEN) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait for at least 1 ms

    // Read data frame
    result = i2cReadDevice(i2c_handle, (char *)buffer, DATA_FRAME_LEN);
    if (result != DATA_FRAME_LEN) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC for pressure
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t pressure_crc = buffer[2];
    uint8_t calculated_pressure_crc = crc8(pressure_data, 2);
    if (pressure_crc != calculated_pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temperature_data[2] = {buffer[3], buffer[4]};
    uint8_t temperature_crc = buffer[5];
    uint8_t calculated_temperature_crc = crc8(temperature_data, 2);
    if (temperature_crc != calculated_temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Extract raw values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    // Convert to physical units
    data->pressure = (float)raw_pressure / 240.0; // Pa
    data->temperature = (float)raw_temperature / 200.0; // °C

    return 0;
}

// Function to log data to file
int log_data(const char *timestamp, float pressure, float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20]; // ISO 8601 UTC timestamp
        time(&rawtime);
        timeinfo = gmtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data to file
            if (log_data(timestamp, sensor_data.pressure, sensor_data.temperature) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for the next poll interval
        sleep(POLL_INTERVAL_SEC);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

