#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD_HIGH_REPEATABILITY 0xFD
#define LOG_FILE "sht40_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT40
int read_sht40_data(int i2c_handle, uint8_t *data) {
    char buf[6];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    data[0] = buf[0];
    data[1] = buf[1];
    data[2] = buf[2];
    data[3] = buf[3];
    data[4] = buf[4];
    data[5] = buf[5];

    return 0;
}

// Function to validate CRC
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = crc8(data, len);
    return (crc != data[len]);
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Function to convert raw humidity to relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    uint8_t data[6];
    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            // Send measurement command
            char cmd[1] = {MEASURE_CMD_HIGH_REPEATABILITY};
            if (i2cWriteDevice(i2c_handle, cmd, 1) != 1) {
                fprintf(stderr, "Error writing to I2C device, retrying...\n");
                gpioDelay(100); // Wait before retrying
                retries++;
                continue;
            }

            gpioDelay(10); // Wait for measurement (at least 10ms)

            // Read data
            if (read_sht40_data(i2c_handle, data) == 0) {
                // Validate CRC
                if (!validate_crc(data, 2) || !validate_crc(data + 3, 2)) {
                    fprintf(stderr, "CRC validation failed, retrying...\n");
                    gpioDelay(100); // Wait before retrying
                    retries++;
                    continue;
                }

                // Convert data
                raw_temperature = (data[0] << 8) | data[1];
                raw_humidity = (data[3] << 8) | data[4];

                // Convert to Celsius and relative humidity
                temperature = convert_temperature(raw_temperature);
                humidity = convert_humidity(raw_humidity);

                // Log data
                log_data(temperature, humidity);

                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error reading data, retrying...\n");
                gpioDelay(100); // Wait before retrying
                retries++;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

