#define SDP31_ADDR 0x28
#define TRIGGER_COMMAND 0x21
#define MEASUREMENT_COMMAND 0x96
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_DELAY_MS 100
#define LOG_FILE "airflow.log"

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_handle = -1;
FILE *log_file = NULL;

// Structure for sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_trigger_command();
int read_sensor_data(uint8_t *data);
sensor_data_t convert_data(const uint8_t *raw_data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send trigger command
int send_trigger_command() {
    int result = i2cWriteByteData(i2c_handle, 0, TRIGGER_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error sending trigger command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data with retry logic
int read_sensor_data(uint8_t *data) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *raw_data) {
    sensor_data_t data;
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    data.pressure_pa = (float)raw_pressure / 60.0;
    data.temperature_c = (float)raw_temperature / 200.0;

    return data;
}

