    while (!terminate) {
        // Send trigger command
        if (send_trigger_command() != 0) {
            fprintf(stderr, "Failed to send trigger command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement (adjust as needed)
        gpioDelay(10); // Wait 10 ms

        // Read sensor data
        if (read_sensor_data(raw_data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        data = convert_data(raw_data);

        // Log data
        if (log_data(&data) != 0) {
            fprintf(stderr, "Failed to log data!\n");
        }

        // Wait before next sample
        gpioDelay(SAMPLE_DELAY_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

