int write_i2c(int handle, int reg, int val) {
    int result = i2cWriteByteData(handle, reg, val);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read from I2C
int read_i2c(int handle, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, 0, buf, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
        return -1;
    }
    return result;
}

