float read_temperature(int handle) {
    char buf[2];
    int raw_temp;
    int retries = 3;

    while (retries > 0) {
        if (write_i2c(handle, TEMP_CMD, 0) == 0) {
            gpioDelay(20); // Wait for measurement
            if (read_i2c(handle, buf, 2) == 2) {
                raw_temp = (buf[0] << 8) | buf[1];
                return (175.72 * raw_temp / 65536.0) - 46.85;
            } else {
