                gpioDelay(100); // Wait before retrying
                retries--;
            }
        } else {
            fprintf(stderr, "Failed to write temperature command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -999.0; // Indicate error
}

