#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// STS30-DIS I2C address
#define STS30_ADDR 0x4A

// STS30-DIS single-shot high-repeatability measurement command
#define MEASURE_CMD 0x2C06

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables for I2C handle and program state
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
float convert_temperature(uint16_t raw_temperature);
char* get_iso8601_timestamp();
int log_temperature(const char *timestamp, float temperature);
int log_error(const char *timestamp, const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, STS30_ADDR, 0); // Bus 1, address 0x4A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write a command to the STS30-DIS sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF; // MSB
    buf[1] = command & 0xFF;      // LSB

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the STS30-DIS sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw temperature data to degrees Celsius
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Get current timestamp in ISO-8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log temperature reading to file
int log_temperature(const char *timestamp, float temperature) {
    FILE *fp = fopen("enclosure_temp_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Log error message to file
int log_error(const char *timestamp, const char *message) {
    FILE *fp = fopen("error_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        return -1;
    }

    fprintf(fp, "%s, %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Send measurement command
        if (write_command(i2c_handle, MEASURE_CMD) != 0) {
            get_iso8601_timestamp();
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Failed to send measurement command.");
            log_error(get_iso8601_timestamp(), error_message);
            continue; // Skip to the next iteration
        }

        // Wait for conversion (at least 15 ms)
        gpioDelay(15000); // 15 ms

        // Read temperature data
        uint8_t data[3];
        if (read_data(i2c_handle, data, 3) != 0) {
            get_iso8601_timestamp();
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Failed to read temperature data.");
            log_error(get_iso8601_timestamp(), error_message);
            continue; // Skip to the next iteration
        }

        // Validate CRC
        uint8_t crc = 0xFF;
        for (int i = 0; i < 2; i++) {
            crc ^= data[i];
            for (int j = 0; j < 8; j++) {
                if ((crc & 0x80) != 0) {
                    crc = (crc << 1) ^ CRC_POLYNOMIAL;
                } else {
                    crc <<= 1;
                }
            }
        }

        if (crc != data[2]) {
            get_iso8601_timestamp();
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "CRC check failed.");
            log_error(get_iso8601_timestamp(), error_message);
            continue; // Skip to the next iteration
        }

        // Combine the two data bytes into a 16-bit value
        uint16_t raw_temperature = (data[0] << 8) | data[1];

        // Convert raw temperature to degrees Celsius
        float temperature = convert_temperature(raw_temperature);

        // Get current timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log temperature reading
        if (log_temperature(timestamp, temperature) != 0) {
            fprintf(stderr, "Failed to log temperature.\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

