#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY_CMD 0xFD
#define LOG_FILE "sht40_log.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT40
int read_sht40_data(uint8_t *data) {
    char buf[6];
    int result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from SHT40: %d\n", result);
        return -1;
    }

    // Validate CRC for temperature
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Validate CRC for humidity
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return -1;
    }

    memcpy(data, buf, 6);
    return 0;
}

// Function to convert raw data to temperature and humidity
void convert_data(uint8_t *data, float *temperature, float *humidity) {
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    *humidity = 100.0 * raw_humidity / 65535.0;
}

// Function to log data to file
