#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONT_MEAS_CMD 0x362F
#define PRESSURE_SCALE 240.0
#define TEMPERATURE_SCALE 200.0
#define TEMPERATURE_OFFSET -45.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int len);
int validate_crc(uint8_t data[], int len, uint8_t polynomial, uint8_t init);
sensor_data_t convert_data(uint8_t *raw_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Write a command to the SDP800 sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the SDP800 sensor
int read_data(int handle, uint8_t *data, int len) {
    int result = i2cReadDevice(handle, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len, uint8_t polynomial, uint8_t init) {
    uint8_t crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(uint8_t *raw_data) {
    sensor_data_t data;
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    data.pressure = (float)raw_pressure / PRESSURE_SCALE;
    data.temperature = ((float)raw_temperature / TEMPERATURE_SCALE) + TEMPERATURE_OFFSET;

    return data;
}

// Log data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (write_command(i2c_handle, CONT_MEAS_CMD) < 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint8_t raw_data[6];
    sensor_data_t sensor_data;

    while (!terminate) {
        // Wait for a short period
        gpioDelay(100000); // 100 ms

        // Read data from the sensor
        if (read_data(i2c_handle, raw_data, 6) < 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(100000); // Wait before retrying
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(raw_data, 2, CRC_POLYNOMIAL, CRC_INIT)) {
            fprintf(stderr, "Pressure CRC check failed\n");
            gpioDelay(100000); // Wait before retrying
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(raw_data + 3, 2, CRC_POLYNOMIAL, CRC_INIT)) {
            fprintf(stderr, "Temperature CRC check failed\n");
            gpioDelay(100000); // Wait before retrying
            continue;
        }

        // Convert raw data to pressure and temperature
        sensor_data = convert_data(raw_data);

        // Log the data
        if (log_data(sensor_data) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Print data to console
        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", sensor_data.pressure, sensor_data.temperature);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

