// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD 28.0
#define HUMID_THRESHOLD 30.0
#define HUMIDITY_THRESHOLD 40.0
#define BUFFER_SIZE 60
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} sensor_data_t;

sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void log_data(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        // Trigger temperature measurement
        if (i2cWriteByteData(i2c_handle, 0xE3) < 0) {
            fprintf(stderr, "Error writing temperature command: %d\n", i2c_handle);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }
        gpioDelay(10); // Wait for measurement

        // Read temperature data
        int raw_temperature = i2cReadWordData(i2c_handle, 0xE3);
        if (raw_temperature < 0) {
            fprintf(stderr, "Error reading temperature data: %d\n", raw_temperature);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Trigger humidity measurement
        if (i2cWriteByteData(i2c_handle, 0xE5) < 0) {
            fprintf(stderr, "Error writing humidity command: %d\n", i2c_handle);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }
        gpioDelay(10); // Wait for measurement

        // Read humidity data
        int raw_humidity = i2cReadWordData(i2c_handle, 0xE5);
        if (raw_humidity < 0) {
            fprintf(stderr, "Error reading humidity data: %d\n", raw_humidity);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert raw data to temperature and humidity
        *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
        *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to control the fan
void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        fan_on = 1;
        printf("Fan ON\n");
    } else if (temperature < (TEMP_THRESHOLD - 1.0) && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Function to log data to the circular buffer
void log_data(float temperature, float humidity) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&circular_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f C, Humidity: %.2f %%\n", time_str, circular_buffer[index].temperature, circular_buffer[index].humidity);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially OFF

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int read_status;

    while (!terminate) {
        read_status = read_sensor_data(&temperature, &humidity);

        if (read_status == 0) {
            control_fan(temperature);
            log_data(temperature, humidity);
            print_buffer();
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 2 seconds.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    cleanup();
    return 0;
}

