#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// Measurement command
#define MEASURE_CMD 0x21B1

// Data ready command
#define DATA_READY_CMD 0xE4B8

// Read measurement command
#define READ_MEASUREMENT_CMD 0xEC05

// Stop periodic measurement command
#define STOP_PERIODIC_CMD 0x3F86

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int verify_crc(uint8_t *data, int len);
int read_scd40_data(int handle, sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
int stop_periodic_measurement(int handle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to SCD40
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify CRC checksum
int verify_crc(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != data[len]) {
        fprintf(stderr, "CRC checksum failed\n");
        return -1;
    }
    return 0;
}

// Read SCD40 data
int read_scd40_data(int handle, sensor_data_t *data) {
    uint8_t raw_data[9];
    uint8_t read_cmd = READ_MEASUREMENT_CMD;

    if (send_command(handle, read_cmd) != 0) {
        fprintf(stderr, "Failed to send read measurement command\n");
        return -1;
    }

    gpioDelay(1000); // Wait for measurement (adjust as needed)

    if (read_data(handle, raw_data, 9) != 0) {
        fprintf(stderr, "Failed to read data\n");
        return -1;
    }

    data->co2 = (raw_data[0] << 8) | raw_data[1];
    data->temperature = (raw_data[3] << 8) | raw_data[4];
    data->humidity = (raw_data[6] << 8) | raw_data[7];
    data->crc = raw_data[8];

    return 0;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%u,%u,%u\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written immediately
}

// Stop periodic measurement
int stop_periodic_measurement(int handle) {
    uint16_t stop_cmd = STOP_PERIODIC_CMD;
    if (send_command(handle, stop_cmd) != 0) {
        fprintf(stderr, "Failed to send stop periodic measurement command\n");
        return -1;
    }
    gpioDelay(1000); // Wait for stop command to take effect
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_scd40_data(i2c_handle, &sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    stop_periodic_measurement(i2c_handle);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

