#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
    int valid;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_scd40();
int start_periodic_measurement();
int stop_periodic_measurement();
int read_measurement(uint8_t *data, int count);
int validate_crc(uint8_t data[], int len);
int read_scd40_data(uint8_t *data, int count);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
int get_from_buffer(circular_buffer_t *buffer, int index, sensor_data_t *data);
void print_buffer(circular_buffer_t *buffer);
void control_led(int co2);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize SCD40 sensor
int init_scd40() {
    uint8_t cmd[2] = {0x21, 0xB1}; // Start periodic measurement command
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to SCD40: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    return init_scd40();
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    uint8_t cmd[2] = {0x3F, 0x86}; // Stop periodic measurement command
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to SCD40: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read measurement data from SCD40
int read_scd40_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from SCD40: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Function to read measurement data from SCD40 with CRC validation
int read_measurement(uint8_t *data, int count) {
    if (count != 9) {
        fprintf(stderr, "Invalid data length: %d\n", count);
        return -1;
    }

    if (!validate_crc(data, 2)) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }

    if (!validate_crc(data + 3, 2)) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    if (!validate_crc(data + 6, 2)) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to get data from the circular buffer
int get_from_buffer(circular_buffer_t *buffer, int index, sensor_data_t *data) {
    if (index < 0 || index >= buffer->count) {
        return -1; // Invalid index
    }
    int actual_index = (buffer->head - buffer->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    *data = buffer->data[actual_index];
    return 0;
}

// Function to print the contents of the circular buffer
void print_buffer(circular_buffer_t *buffer) {
    printf("Circular Buffer Contents:\n");
    for (int i = 0; i < buffer->count; i++) {
        sensor_data_t data;
        if (get_from_buffer(buffer, i, &data) == 0) {
            printf("Index: %d, CO2: %u, Temperature: %.2f, Humidity: %.2f\n",
                   i, data.co2, data.temperature, data.humidity);
        } else {
            printf("Index: %d, Error getting data\n", i);
        }
    }
}

// Function to control the LED based on CO2 level
void control_led(int co2) {
    if (co2 > 1000) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint8_t data[9];
    sensor_data_t sensor_data;
    int get_data_ready;
    int retry_count = 0;

    while (!terminate) {
        // Check if data is ready
        do {
            get_data_ready = read_measurement(data, 9);
            if (get_data_ready != 0) {
