                break;
            }
        } while (retry_count < 10);

        if (get_data_ready == 0) {
            // Read data from sensor
            if (read_scd40_data(data, 9) != 0) {
                fprintf(stderr, "Error reading data from sensor, retrying...\n");
                gpioDelay(100); // Wait 100ms before retrying
                continue;
            }

            // Validate CRC
            if (!validate_crc(data, 2)) {
                fprintf(stderr, "CO2 CRC check failed, skipping reading.\n");
                gpioDelay(1000); // Wait 1 second before next attempt
                continue;
            }

            if (!validate_crc(data + 3, 2)) {
                fprintf(stderr, "Temperature CRC check failed, skipping reading.\n");
                gpioDelay(1000); // Wait 1 second before next attempt
                continue;
            }

            if (!validate_crc(data + 6, 2)) {
                fprintf(stderr, "Humidity CRC check failed, skipping reading.\n");
                gpioDelay(1000); // Wait 1 second before next attempt
                continue;
            }

            // Read data from sensor
            if (read_measurement(data, 9) != 0) {
                fprintf(stderr, "Error reading measurement data, retrying...\n");
                gpioDelay(100); // Wait 100ms before retrying
                continue;
            }

            // Populate sensor data
            sensor_data.co2 = (data[0] << 8) | data[1];
            sensor_data.temperature = -45 + 175 * ((float)((data[3] << 8) | data[4])) / 65535;
            sensor_data.humidity = 100 * ((float)((data[6] << 8) | data[7])) / 65535;
            sensor_data.valid = 1;

            // Add data to circular buffer
            add_to_buffer(&buffer, sensor_data);

            // Print buffer contents
            print_buffer(&buffer);

            // Control LED
            control_led(sensor_data.co2);

            // Wait 5 seconds
            gpioDelay(5000);
        } else {
            gpioDelay(100); // Wait 100ms before next attempt
        }
    }

    // Stop periodic measurement
    stop_periodic_measurement();

