#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define PWM_FREQUENCY 1000000 // 1 MHz
#define PWM_RANGE 1000       // 1000 counts
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Structure to hold temperature data
typedef struct {
    double temperature;
    time_t timestamp;
} TemperatureData;

// Function prototypes
double calculate_temperature(unsigned int th, unsigned int tl);
int log_temperature(double temperature);
int detect_sensor_error(double temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to calculate temperature from TH and TL
double calculate_temperature(unsigned int th, unsigned int tl) {
    if (tl == 0) {
        return -1000.0; // Indicate division by zero
    }
    return 4215.0 - (2143.0 * (double)th / (double)tl);
}

// Function to log temperature to file
int log_temperature(double temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(fp, "%s, %.2f\n", buf, temperature);
    fclose(fp);
    return 0;
}

// Function to detect sensor error
int detect_sensor_error(double temperature) {
    if (temperature < -40.0 || temperature > 150.0) {
        return 1; // Error
    }
    return 0; // No error
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    return 0;
}

// Cleanup function
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int consecutive_failures = 0;
    int sensor_absent_count = 0;

    while (!terminate) {
        unsigned int th = 0, tl = 0;
        unsigned int last_th = 0, last_tl = 0;
        int edge_count = 0;
        unsigned int pulse_width = 0;
        unsigned int start_time = gpioTick();
        unsigned int end_time;
        double temperature;
        int error;

        // Wait for a rising edge
        while (edge_count < 1000) {
            end_time = gpioTick();
            if (end_time - start_time > 1000000) {
                break; // Timeout after 1 second
            }

            if (gpioRead(GPIO_PIN) == 1) {
                th++;
            }
            start_time = end_time;
            gpioDelay(1); // Small delay to avoid busy-waiting
            edge_count++;
        }

        if (edge_count == 0) {
            sensor_absent_count++;
            if (sensor_absent_count >= 3) {
                log_temperature(-999.0); // Log SENSOR MALFUNCTION
                fprintf(stderr, "SENSOR MALFUNCTION detected\n");
            }
            continue; // Skip to the next iteration
        }

        // Wait for a falling edge
        edge_count = 0;
        while (edge_count < 1000) {
            end_time = gpioTick();
            if (end_time - start_time > 1000000) {
                break; // Timeout after 1 second
            }

            if (gpioRead(GPIO_PIN) == 0) {
                tl++;
            }
            start_time = end_time;
            gpioDelay(1); // Small delay to avoid busy-waiting
            edge_count++;
        }

        if (edge_count == 0) {
            sensor_absent_count = 0; // Reset sensor absent counter
            continue; // Skip to the next iteration
        }

        pulse_width = tl - th;

        temperature = calculate_temperature(th, tl);

        if (detect_sensor_error(temperature)) {
            error = 1;
        } else {
            error = 0;
        }

        if (log_temperature(temperature) != 0) {
            error = 1;
        }

        consecutive_failures = 0;
        if (error) {
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                log_temperature(-999.0); // Log SENSOR MALFUNCTION
                fprintf(stderr, "SENSOR MALFUNCTION detected\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for 5 seconds
    }

    cleanup();
    return 0;
}

