#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x24
#define DATA_LENGTH 6
#define RETRY_COUNT 3
#define RETRY_DELAY_SEC 1
#define LOG_FILE "environmental_data.txt"
#define LOG_INTERVAL_SEC 5
#define OFFSET_PERIOD_SEC 3600 // 1 hour
#define OFFSET_AMPLITUDE 2.0   // +/- 2 degrees Celsius
#define OFFSET_FREQUENCY 1.0   // 1 cycle per OFFSET_PERIOD_SEC
#define OFFSET_PHASE 0.0       // 0 degrees phase shift

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_sht35_data(uint8_t command, uint8_t *data, int data_length);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
float apply_offset(float temperature, float humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (as per Sensirion datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from SHT35
int read_sht35_data(uint8_t command, uint8_t *data, int data_length) {
    int result = i2cWriteByte(i2c_handle, command);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    gpioDelay(15); // Wait at least 15 ms

    result = i2cReadDevice(i2c_handle, (char *)data, data_length);
    if (result != data_length) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + (175.0 * (float)raw_temperature / 65535.0);
}

// Function to convert raw humidity to %RH
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to apply sinusoidal offset
float apply_offset(float temperature, float humidity) {
    float time_in_seconds = (float)time(NULL) / (float)CLOCKS_PER_SEC; // Get current time in seconds
    float phase = OFFSET_PHASE * M_PI / 180.0; // Convert degrees to radians

    // Calculate the offset values
    float temperature_offset = OFFSET_AMPLITUDE * sin(OFFSET_FREQUENCY * time_in_seconds + phase);
    float humidity_offset = OFFSET_AMPLITUDE * sin(OFFSET_FREQUENCY * time_in_seconds + (phase + M_PI / 2.0)); // Offset by 90 degrees

    return temperature + temperature_offset, humidity + humidity_offset;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
