// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x24
#define DATA_LENGTH 6
#define RETRY_COUNT 3
#define RETRY_DELAY_SEC 1
#define LOG_FILE "environmental_data.txt"
#define LOG_INTERVAL_SEC 5
#define OFFSET_PERIOD_SEC 3600 // 1 hour
#define OFFSET_AMPLITUDE 2.0   // +/- 2 degrees Celsius
#define OFFSET_FREQUENCY 1.0   // 1 cycle per OFFSET_PERIOD_SEC
#define OFFSET_PHASE 0.0       // 0 degrees phase shift

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_sht35_data(uint8_t command, uint8_t *data, int data_length);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
float apply_offset(float temperature, float humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (as per Sensirion datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from SHT35
int read_sht35_data(uint8_t command, uint8_t *data, int data_length) {
    int result = i2cWriteByte(i2c_handle, command);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    gpioDelay(15); // Wait at least 15 ms

    result = i2cReadDevice(i2c_handle, (char *)data, data_length);
    if (result != data_length) {
