float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to apply sinusoidal offset
float apply_offset(float temperature, float humidity) {
    float time_in_seconds = (float)time(NULL) / (float)CLOCKS_PER_SEC; // Get current time in seconds
    float phase = OFFSET_PHASE * M_PI / 180.0; // Convert degrees to radians

    // Calculate the offset values
    float temperature_offset = OFFSET_AMPLITUDE * sin(OFFSET_FREQUENCY * time_in_seconds + phase);
    float humidity_offset = OFFSET_AMPLITUDE * sin(OFFSET_FREQUENCY * time_in_seconds + (phase + M_PI / 2.0)); // Offset by 90 degrees

    return temperature + temperature_offset, humidity + humidity_offset;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

