#define MEASURE_CMD 0x2400
#define CSV_FILE "environment.csv"
#define SAMPLE_INTERVAL 5 // seconds

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

