int send_measurement_command();
int read_sensor_data(uint8_t *data);
SensorData convert_raw_data(const uint8_t *data);
int validate_crc(const uint8_t *data, size_t len);
int write_to_csv(const SensorData *data);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

