#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define CSV_FILE "environment.csv"
#define SAMPLE_INTERVAL 5 // seconds

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
SensorData convert_raw_data(const uint8_t *data);
int validate_crc(const uint8_t *data, size_t len);
int write_to_csv(const SensorData *data);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send measurement command
int send_measurement_command() {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature and humidity
SensorData convert_raw_data(const uint8_t *data) {
    SensorData sensor_data;
    int32_t raw_temperature = (data[0] << 8) | data[1];
    int32_t raw_humidity = (data[3] << 8) | data[4];

    sensor_data.temperature = -45 + 175 * raw_temperature / 65535.0;
    sensor_data.humidity = 100 * raw_humidity / 65535.0;

    return sensor_data;
}

// Function to validate CRC checksum
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Function to write data to CSV file
int write_to_csv(const SensorData *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "a");
        if (csv_file == NULL) {
            fprintf(stderr, "Failed to open CSV file\n");
            return -1;
        }
        fprintf(csv_file, "timestamp,temperature_c,humidity_pct\n");
    }

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(csv_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Send measurement command
    if (send_measurement_command() != 0) {
        cleanup();
        return 1;
    }

    // Wait for measurement to complete
    gpioDelay(15); // 15 ms

    // Read sensor data
    uint8_t data[6];
    if (read_sensor_data(data) != 0) {
        cleanup();
        return 1;
    }

    // Validate CRC
    if (!validate_crc(data, 2) || !validate_crc(data + 3, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        cleanup();
        return 1;
    }

    // Convert raw data
    SensorData sensor_data = convert_raw_data(data);

    // Write to CSV file
    if (write_to_csv(&sensor_data) != 0) {
        fprintf(stderr, "Failed to write to CSV file\n");
    }

    // Wait for the next sample
    sleep(SAMPLE_INTERVAL);

    // Cleanup and exit
    cleanup();
    return 0;
}

