#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_HUMIDITY 0xF5
#define MEASURE_TEMPERATURE 0xF3
#define PAIRED_MEASUREMENT 0xE0
#define RESET_COMMAND 0xFE
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define POLL_DELAY_MS 5000

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_setup(int bus, int addr);
int i2c_write(int fd, uint8_t command);
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len);
int si7021_read_humidity(int fd);
int si7021_read_temperature(int fd);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);
void reset_sensor(int fd);

// I2C setup function
int i2c_setup(int bus, int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t command) {
    uint8_t buf[2];
    buf[0] = command;
    buf[1] = 0x00; // Dummy byte for writing

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading from I2C");
        return -1;
    }
    return 0;
}

// Si7021 read humidity function
int si7021_read_humidity(int fd) {
    uint8_t data[3];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write(fd, MEASURE_HUMIDITY) == 0) {
            usleep(10000); // Wait for measurement (at least 15ms)
            if (i2c_read(fd, 0, data, 3) == 0) {
                uint16_t raw_humidity = (data[0] << 8) | data[1];
                return raw_humidity;
            } else {
                fprintf(stderr, "I2C read error (humidity), retrying...\n");
            }
        } else {
            fprintf(stderr, "I2C write error (humidity), retrying...\n");
        }
        retries--;
        usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
    }
    fprintf(stderr, "Failed to read humidity after multiple retries.\n");
    return 0; // Indicate failure
}

// Si7021 read temperature function
int si7021_read_temperature(int fd) {
    uint8_t data[3];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write(fd, MEASURE_TEMPERATURE) == 0) {
            usleep(10000); // Wait for measurement (at least 15ms)
            if (i2c_read(fd, 0, data, 3) == 0) {
                uint16_t raw_temperature = (data[0] << 8) | data[1];
                return raw_temperature;
            } else {
                fprintf(stderr, "I2C read error (temperature), retrying...\n");
            }
        } else {
            fprintf(stderr, "I2C write error (temperature), retrying...\n");
        }
        retries--;
        usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
    }
    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return 0; // Indicate failure
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 125.0 * raw_humidity / 65536.0 - 6.0;
}

// Log data to CSV file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
}

// Reset the sensor
void reset_sensor(int fd) {
    if (i2c_write(fd, RESET_COMMAND) != 0) {
        fprintf(stderr, "Error resetting sensor.\n");
    }
    usleep(100000); // Wait for reset to complete
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, SI7021_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        sensor_data_t sensor_data;

        // Read humidity
        int raw_humidity = si7021_read_humidity(i2c_fd);
        if (raw_humidity != 0) {
            fprintf(stderr, "Error reading humidity. Using default value.\n");
            sensor_data.humidity = 0.0; // Use a default value
        } else {
            sensor_data.humidity = convert_humidity(raw_humidity);
        }

        // Read temperature
        int raw_temperature = si7021_read_temperature(i2c_fd);
        if (raw_temperature != 0) {
            sensor_data.temperature = convert_temperature(raw_temperature);
        } else {
            fprintf(stderr, "Error reading temperature. Using default value.\n");
            sensor_data.temperature = 0.0; // Use a default value
        }

        // Log data
        if (log_data(log_file, sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for the next cycle
        usleep(POLL_DELAY_MS * 1000);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

