#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SAMPLE_INTERVAL_SEC 1
#define CRC8_POLYNOMIAL 0x31 // x8 + x7 + x5 + x4 + 1
#define CRC8_INIT 0x8C
#define CRC8_CHECKSUM 0x06

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int validate_crc(uint8_t data[], int len);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    fp = fopen("airflow.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open airflow.dat for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Write a command to the SDP810
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the SDP810
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != CRC8_CHECKSUM) {
        fprintf(stderr, "CRC check failed for data: ");
        for (int i = 0; i < len; i++) {
            fprintf(stderr, "%02X ", data[i]);
        }
        fprintf(stderr, "Expected 0x%02X, got 0x%02X\n", CRC8_CHECKSUM, crc);
        return -1;
    }
    return 0;
