#define MEASURE_CMD 0x362F
#define SAMPLE_INTERVAL_SEC 1
#define CRC8_POLYNOMIAL 0x31 // x8 + x7 + x5 + x4 + 1
#define CRC8_INIT 0x8C
#define CRC8_CHECKSUM 0x06

// Global variables
int i2c_handle;
