// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x3603
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"
#define SLEEP_SECONDS 5

// CRC Polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure_raw;
    uint8_t crc_pressure;
    int16_t temperature_raw;
    uint8_t crc_temperature;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(sensor_data_t *data);
float convert_pressure(int16_t raw_pressure);
int validate_crc(uint8_t data, uint8_t crc);
int log_pressure(float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Extract data from buffer
    data->pressure_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->crc_pressure = buffer[2];
    data->temperature_raw = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->crc_temperature = buffer[5];
    data->status = (uint16_t)((buffer[6] << 8) | buffer[7]);

    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / SCALE_FACTOR;
}

// Validate CRC
int validate_crc(uint8_t data, uint8_t crc) {
    uint8_t polynomial[] = {CRC_POLYNOMIAL};
    uint8_t crc_calculated = 0;
    uint8_t crc_check = 0;

    for (int i = 0; i < 8; i++) {
        crc_calculated = (crc_calculated ^ polynomial[i]) & 0x01;
        if (crc_calculated) {
            crc_calculated = (crc_calculated << 1) ^ 0x31;
        } else {
            crc_calculated = (crc_calculated << 1);
        }
        crc_check = (crc_check << 1) ^ polynomial[i];
        if (crc_check & 0x80) {
            crc_check = (crc_check ^ 0x31) >> 1;
        } else {
            crc_check = crc_check >> 1;
        }
    }

    return (crc_calculated == crc_check);
}

// Log pressure to file
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying in %d seconds...\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Wait for conversion (45 ms)
        gpioDelay(50000); // 50 ms

        // Read sensor data
        if (read_sensor_data(&sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying in %d seconds...\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Validate CRCs
        if (!validate_crc(sensor_data.pressure_raw, sensor_data.crc_pressure) ||
            !validate_crc(sensor_data.temperature_raw, sensor_data.crc_temperature)) {
            fprintf(stderr, "CRC validation failed, skipping logging\n");
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Convert pressure
        float pressure = convert_pressure(sensor_data.pressure_raw);

        // Log pressure
        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Error logging pressure\n");
        }

        // Sleep for specified interval
        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

