#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Sensor-specific constants
#define RAW_FLOW_MIN 1638
#define RAW_FLOW_MAX 14745
#define FLOW_MIN_SLPM 0.0
#define FLOW_MAX_SLPM 10.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, int *raw_flow);
float convert_to_flow_rate(int raw_flow);
void set_fan_speed(int gpio_pin, float duty_cycle);
void log_data(float flow_rate);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Configure FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, int *raw_flow) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return 1; // Indicate failure
    }

    // Combine the two bytes into a 16-bit word
    int16_t raw_word = (buffer[0] << 8) | buffer[1];

    // Mask off the status bits and shift right by 2
    *raw_flow = (raw_word >> 2) & 0x3FFF; // Mask status bits and shift

    return 0; // Indicate success
}

// Function to convert raw flow reading to flow rate
float convert_to_flow_rate(int raw_flow) {
    // Linear transfer function
    float flow_rate = (float)(raw_flow - RAW_FLOW_MIN) * (FLOW_MAX_SLPM - FLOW_MIN_SLPM) / (RAW_FLOW_MAX - RAW_FLOW_MIN) + FLOW_MIN_SLPM;
    return flow_rate;
}

// Function to set fan speed using PWM
void set_fan_speed(int gpio_pin, float duty_cycle) {
    // pigpio's gpioPWM takes a value between 0 and 255
    int pwm_value = (int)(duty_cycle * 255.0);
    gpioPWM(gpio_pin, pwm_value);
}

// Function to log data to file
void log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    set_fan_speed(FAN_GPIO, 0.0); // Turn off the fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    int raw_flow;
    float flow_rate;
    float duty_cycle;

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &raw_flow) == 0) {
            flow_rate = convert_to_flow_rate(raw_flow);
            duty_cycle = (float)flow_rate / FLOW_MAX_SLPM * 100.0;
            set_fan_speed(FAN_GPIO, duty_cycle);
            log_data(flow_rate);
            printf("Flow Rate: %.2f SLPM, Duty Cycle: %.2f%%\n", flow_rate, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

