#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_byte(int handle, uint8_t reg);
int i2c_write_byte(int handle, uint8_t reg, uint8_t value);
int read_pressure(int handle);
int read_temperature(int handle);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// I2C read byte function
int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// I2C write byte function
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Read pressure function
int read_pressure(int handle) {
    int xl = i2c_read_byte(handle, PRESS_OUT_XL);
    int l = i2c_read_byte(handle, PRESS_OUT_L);
    int h = i2c_read_byte(handle, PRESS_OUT_H);

    if (xl < 0 || l < 0 || h < 0) {
        return -1;
    }

    return (h << 16) | (l << 8) | xl;
}

// Read temperature function
int read_temperature(int handle) {
    int l = i2c_read_byte(handle, TEMP_OUT_L);
    int h = i2c_read_byte(handle, TEMP_OUT_H);

    if (l < 0 || h < 0) {
        return -1;
    }

    return (h << 8) | l;
}

// Convert pressure function
float convert_pressure(int32_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert temperature function
float convert_temperature(int16_t raw_temperature) {
    return 42.5 + (float)raw_temperature / 480.0;
}

// Log data function
void log_data(float pressure, float temperature) {
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime_r(&t, NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check WHO_AM_I register
    int who_am_i = i2c_read_byte(i2c_handle, WHO_AM_I);
    if (who_am_i != 0xB1) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0xB1\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure CTRL_REG1
    if (i2c_write_byte(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        fprintf(stderr, "Error configuring CTRL_REG1\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        int32_t raw_pressure = read_pressure(i2c_handle);
        int16_t raw_temperature = read_temperature(i2c_handle);

        if (raw_pressure >= 0 && raw_temperature >= 0) {
            // Convert to hPa and Celsius
            float pressure = convert_pressure(raw_pressure);
            float temperature = convert_temperature(raw_temperature);

            // Log the data
            log_data(pressure, temperature);

            // Print to console
            printf("Pressure: %.2f hPa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for 1 second
        gpioDelay(1000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

