#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
float read_temperature();
float calculate_average_temperature(CircularBuffer *cb);
void control_led(float average_temperature);
void signal_handler(int signal);
void initialize_circular_buffer(CircularBuffer *cb);

// Initialize circular buffer
void initialize_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0.0; // Initialize with 0.0
    }
}

// Function to read temperature from STLM75
float read_temperature() {
    int raw_temp;
    int retries = 3;

    while (retries > 0) {
        raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temp >= 0) {
            // Byte swap and extract temperature
            short swapped_temp = (raw_temp >> 8) | (raw_temp << 8);
            float temperature = (float)((short)((swapped_temp & 0x3FFF) << 7)) / 2.0;
            return temperature;
        } else {
            fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
            gpioDelay(100); // Wait before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -273.15; // Return absolute zero as error value
}

// Function to calculate the running average temperature
float calculate_average_temperature(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0; // Return 0 if the buffer is empty
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to control the LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer temperature_buffer;
    initialize_circular_buffer(&temperature_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        // Store temperature in circular buffer
        temperature_buffer.buffer[temperature_buffer.head] = temperature;
        temperature_buffer.head = (temperature_buffer.head + 1) % BUFFER_SIZE;
        if (temperature_buffer.count < BUFFER_SIZE) {
            temperature_buffer.count++;
        }

        // Calculate average temperature
        float average_temperature = calculate_average_temperature(&temperature_buffer);

        // Control LED
        control_led(average_temperature);

        // Print temperature and average temperature
        printf("Temperature: %.2f °C, Average Temperature: %.2f °C\n", temperature, average_temperature);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

