#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// SCD30 commands
#define CMD_START_CONT_MEAS 0x0010
#define CMD_SET_MEAS_INTERVAL 0x4600
#define CMD_GET_DATA_READY 0x0202
#define CMD_READ_MEASUREMENT 0x0300

// Measurement interval (seconds)
#define MEASUREMENT_INTERVAL 2

// CO2 thresholds for ventilation control
#define CO2_THRESHOLD_OFF 800
#define CO2_THRESHOLD_LOW 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to write a command to the SCD30
int write_command(int handle, unsigned short command) {
    unsigned char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing command 0x%04X\n", command);
        return -1;
    }
    return 0;
}

// Function to read data from the SCD30
int read_data(int handle, unsigned char *data, int len) {
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "Error reading data\n");
        return -1;
    }
    return 0;
}

// Function to initialize the SCD30 sensor
int initialize_sensor(int handle) {
    // Start continuous measurement
    if (write_command(handle, CMD_START_CONT_MEAS) != 0) {
        fprintf(stderr, "Error starting continuous measurement\n");
        return -1;
    }

    // Set measurement interval
    unsigned short interval = MEASUREMENT_INTERVAL * 1000; // Convert seconds to milliseconds
    unsigned char interval_data[2];
    interval_data[0] = interval >> 8;
    interval_data[1] = interval & 0xFF;
    if (write_command(handle, CMD_SET_MEAS_INTERVAL) != 0) {
        fprintf(stderr, "Error setting measurement interval\n");
        return -1;
    }

    return 0;
}

// Function to read data from the SCD30
int read_scd30_data(int handle, float *co2, float *temperature, float *humidity) {
    unsigned char data[18];
    unsigned char crc_data[18];

    // Read data ready status
    if (write_command(handle, CMD_GET_DATA_READY) != 0) {
        fprintf(stderr, "Error reading data ready status\n");
        return -1;
