    unsigned char data_ready;
    if (i2cReadDevice(handle, &data_ready, 1) != 1) {
        fprintf(stderr, "Error reading data ready status\n");
        return -1;
    }

    if (!(data_ready & 0x01)) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read measurement data
    if (read_data(handle, data, 18) != 0) {
        fprintf(stderr, "Error reading measurement data\n");
        return -1;
    }

    // CRC validation
    for (int i = 0; i < 18; i++) {
        crc_data[i] = data[i];
        unsigned char crc_calculated = crc8(crc_data, 1);
        if (crc_calculated != data[i + 1]) {
            fprintf(stderr, "CRC mismatch at byte %d\n", i);
            return -1;
        }
    }

    // Convert data to float values
    *co2 = (float)((unsigned int)data[0] << 8 | data[1]) / 65536.0;
    *temperature = (float)((unsigned int)data[3] << 8 | data[4]) / 65536.0;
    *humidity = (float)((unsigned int)data[6] << 8 | data[7]) / 65536.0;

    return 0;
}

