void control_ventilation(float co2) {
    if (co2 < CO2_THRESHOLD_OFF) {
        printf("Ventilation OFF\n");
    } else if (co2 >= CO2_THRESHOLD_LOW && co2 < CO2_THRESHOLD_OFF) {
        printf("Ventilation LOW\n");
    } else {
        printf("Ventilation HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

