#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SDP32 I2C address
#define SDP32_ADDR 0x21

// I2C bus
#define I2C_BUS 1

// Measurement command
#define MEASURE_CMD 0x36
#define MEASURE_CMD2 0x2F

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
    uint8_t crc_pressure;
    uint8_t crc_temperature;
    uint8_t crc_scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, sensor_data_t *data);
int verify_checksum(uint8_t data[], int len, uint8_t checksum);
float convert_pressure(int16_t raw_pressure, int16_t scale_factor);
void log_data(float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SDP32
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SDP32
int read_data(int handle, sensor_data_t *data) {
    char buf[9];
    int result = i2cReadDevice(handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->scale_factor = (int16_t)((buf[6] << 8) | buf[7]);
    data->crc_pressure = buf[2];
    data->crc_temperature = buf[5];
    data->crc_scale_factor = buf[8];

    return 0;
}

// Verify CRC checksum
int verify_checksum(uint8_t data[], int len, uint8_t checksum) {
    uint8_t polynomial = CRC8_POLYNOMIAL;
    uint8_t crc = 0xFF;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != checksum) {
        fprintf(stderr, "CRC checksum error!\n");
        return -1;
    }

    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, int16_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Log data to console
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Pressure: %.2f Pa\n", timestamp, pressure);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int interval = 1000; // Default interval in milliseconds
    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval. Using default value of 1000 ms.\n");
            interval = 1000;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASURE_CMD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(10); // Wait for the sensor to be ready

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    float pressure;

    // Main loop
    while (!terminate) {
        // Read data
        if (read_data(i2c_handle, &sensor_data) == 0) {
            // Verify checksums
            if (verify_checksum(sensor_data.pressure, 2, sensor_data.crc_pressure) != 0 ||
                verify_checksum(sensor_data.temperature, 2, sensor_data.crc_temperature) != 0 ||
                verify_checksum(sensor_data.scale_factor, 2, sensor_data.crc_scale_factor) != 0) {
                fprintf(stderr, "Checksum verification failed. Skipping data point.\n");
                gpioDelay(interval);
                continue;
            }

            // Convert pressure
            pressure = convert_pressure(sensor_data.pressure, sensor_data.scale_factor);

            // Log data
            log_data(pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d ms.\n", interval);
        }

        // Wait for the next interval
        gpioDelay(interval);
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

