#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMP_REG 0x00
#define HUM_REG 0x02
#define CONFIG_REG 0x01

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the HDC1000 sensor
int init_hdc1000() {
    // Configure the HDC1000 for combined temperature and humidity measurement
    uint8_t config_data[2] = {CONFIG_REG, 0x90}; // Enable temperature and humidity measurement, 14-bit resolution
    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Failed to write to configuration register");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data from the HDC1000
int read_hdc1000(float *temperature, float *humidity) {
    uint8_t read_data[4];
    int16_t raw_temperature, raw_humidity;

    // Write the temperature register address to the sensor
    if (write(i2c_fd, TEMP_REG, 1) != 1) {
        perror("Failed to write to temperature register");
        return -1;
    }

    // Wait for at least 20 ms for the conversion to complete
    usleep(20000); // 20 ms

    // Read 4 bytes of data (2 bytes temperature, 2 bytes humidity)
    if (read(i2c_fd, read_data, 4) != 4) {
        perror("Failed to read from temperature register");
        return -1;
    }

    // Combine the two bytes to form the raw temperature and humidity values
    raw_temperature = (read_data[0] << 8) | read_data[1];
    raw_humidity = (read_data[2] << 8) | read_data[3];

    // Convert the raw values to temperature and humidity
    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the HDC1000 sensor
    if (init_hdc1000() != 0) {
        fprintf(stderr, "HDC1000 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and log temperature and humidity data
    while (1) {
        // Read temperature and humidity data
        if (read_hdc1000(&temperature, &humidity) == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log the data to the console
            printf("%s Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // The program should never reach here due to the infinite loop,
    // but include close(i2c_fd) for completeness.
    close(i2c_fd);
    return 0;
}

