#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define TEMP_ERROR -999.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
double read_temperature();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from Si7051 sensor
double read_temperature() {
    int raw_temperature;
    double temperature;

    // Send temperature measurement command
    if (i2cWriteByteData(i2c_handle, 0, TEMP_MEASURE_CMD) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return TEMP_ERROR;
    }

    // Wait for measurement to complete (at least 20ms)
    gpioDelay(25000); // 25ms

    // Read temperature data (2 bytes)
    raw_temperature = i2cReadWordData(i2c_handle, 0);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return TEMP_ERROR;
    }

    // Convert raw temperature to Celsius
    temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    return temperature;
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();

        if (temperature != TEMP_ERROR) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

