#include <unistd.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x60

// Define the command to read pressure (Consult datasheet)
#define READ_PRESSURE_COMMAND 0x10 // Example command, adjust as needed

// Global variables for I2C handle and program state
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Function to read pressure from the sensor
int read_pressure(int i2c_handle, float *pressure) {
    char buf[2];
    int result;

    // Send the read pressure command
    result = i2cWriteByte(i2c_handle, READ_PRESSURE_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Read two bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert the two bytes to a 16-bit value
    uint16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert the raw pressure to Pascals (Consult datasheet for conversion)
    *pressure = (float)raw_pressure * 0.1; // Example conversion, adjust as needed

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float pressure;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    while (program_running) {
        // Read pressure from the sensor
        if (read_pressure(i2c_handle, &pressure) == 0) {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);
