// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x60

// Define the pressure registers
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB

// Define the scaling factor
#define SCALING_FACTOR 0.1

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

// Function to initialize the I2C bus
int i2c_init(int bus, int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to trigger a measurement
int trigger_measurement(int fd) {
    // Send the measurement command (0x00) to the sensor
    if (write(fd, "\0", 1) != 1) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the pressure value
int read_pressure(int fd, uint16_t *pressure) {
    uint8_t msb, lsb;

    // Read the MSB
    msb = read(fd, &msb, 1);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB: %s\n", strerror(errno));
        return -1;
    }

    // Read the LSB
    lsb = read(fd, &lsb, 1);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB: %s\n", strerror(errno));
        return -1;
    }

    // Combine the MSB and LSB to form the 16-bit pressure value
    *pressure = (msb << 8) | lsb;

    return 0;
}

// Function to convert the raw pressure value to kPa
float convert_to_kPa(uint16_t raw_pressure) {
    return (float)raw_pressure * SCALING_FACTOR;
}

// Function to log the pressure reading with a timestamp
void log_pressure(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure_kPa);
}

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = i2c_init(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop to read and log pressure values
    while (1) {
        uint16_t raw_pressure;
        float pressure_kPa;

        // Trigger a measurement
        if (trigger_measurement(i2c_fd) < 0) {
            fprintf(stderr, "Failed to trigger measurement. Continuing.\n");
            continue; // Continue to the next iteration
        }

        // Wait for a short period to allow the sensor to complete the measurement
        usleep(10000); // 10ms

        // Read the pressure value
        if (read_pressure(i2c_fd, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read pressure. Continuing.\n");
            continue; // Continue to the next iteration
        }

        // Convert the raw pressure value to kPa
        pressure_kPa = convert_to_kPa(raw_pressure);

        // Log the pressure reading
        log_pressure(pressure_kPa);

        // Wait for 1 second
        sleep(1);
    }

    // The program should never reach here due to the infinite loop,
    // but include the close statement for completeness.
    close(i2c_fd);
    return 0;
}

