#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define PRESSURE_SCALE 60.0
#define TEMPERATURE_SCALE 200.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int fd, uint8_t *data, int len) {
    if (write(fd, &CONTINUOUS_MEASUREMENT_COMMAND, 1) != 1) {
        perror("Failed to write command");
        return -1;
    }
    usleep(45000); // 45 ms

    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// Function to validate CRC
int validate_crc(uint8_t *data, int len) {
    for (int i = 0; i < len - 1; i++) {
        uint8_t crc = crc8(data + i, 1);
        if (crc != data[i + 1]) {
            fprintf(stderr, "CRC error at index %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Function to convert raw data to physical units
void convert_data(uint8_t *data, float *pressure, float *temperature) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    *pressure = (float)raw_pressure / PRESSURE_SCALE;
    *temperature = (float)raw_temperature / TEMPERATURE_SCALE;
}

// Function to log data to file
void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[9];
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, sensor_data, 9) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 9) == 0) {
                // Convert data
                convert_data(sensor_data, &pressure, &temperature);

                // Log data
                log_data(pressure, temperature);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(1); // Read every 1 second
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

