#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SAFE_PRESSURE_MIN 200.0
#define SAFE_PRESSURE_MAX 250.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_pressure(int *raw_pressure);
float convert_pressure(int raw_pressure);
void log_pressure(float pressure);
void check_pressure_range(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from the sensor
int read_pressure(int *raw_pressure) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure: %d\n", result);
        return -1;
    }

    *raw_pressure = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw pressure to kPa
float convert_pressure(int raw_pressure) {
    return (float)raw_pressure * 0.01;
}

// Log pressure to CSV file
void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen("pressure_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return;
        }
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk
}

// Check pressure range and log warning
void check_pressure_range(float pressure) {
    if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

        fprintf(stderr, "Warning: Pressure out of range: %.2f kPa\n", pressure);
        fprintf(log_file, "%s,Warning: Pressure out of range: %.2f kPa\n", timestamp, pressure);
        fflush(log_file);
    }
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    int raw_pressure;
    float pressure_kPa;

    // Main loop
    while (!terminate) {
        if (read_pressure(&raw_pressure) == 0) {
            pressure_kPa = convert_pressure(raw_pressure);
            log_pressure(pressure_kPa);
            check_pressure_range(pressure_kPa);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                break; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

