#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1MB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
SensorData process_sensor_data(const uint8_t *data);
int log_data(const SensorData *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from HIH6130
int read_sensor_data(uint8_t *data) {
    char trigger_cmd = 0x00;
    int result;

    result = i2cWriteByte(i2c_handle, trigger_cmd);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(40); // Wait for measurement (at least 35ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// Process raw sensor data into temperature and humidity
SensorData process_sensor_data(const uint8_t *data) {
    SensorData sensor_data;
    int raw_humidity, raw_temperature;

    // Extract raw humidity and temperature values
    raw_humidity = (data[0] << 8) | data[1];
    raw_temperature = (data[2] << 8) | data[3];

    // Convert raw values to temperature and humidity
    sensor_data.temperature = raw_temperature * 165.0 / 16383.0 - 40.0;
    sensor_data.humidity = raw_humidity * 100.0 / 16383.0;

    return sensor_data;
}

// Log sensor data to file
int log_data(const SensorData *data) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data->temperature, data->humidity);

    if (fseek(fp, 0, SEEK_END) == -1) {
        fprintf(stderr, "Error seeking to beginning of log file!\n");
        fclose(fp);
        return -1;
    }

    long file_size = ftell(fp);
    if (file_size > LOG_FILE_SIZE_LIMIT) {
        fclose(fp);
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file for truncation!\n");
            return -1;
        }
        fprintf(fp, "%s", "LOG_FILE TRUNCATED");
        fclose(fp);
    }

    if (fprintf(fp, "%s", "LOG_FILE TRUNCATED") != 0) {
        fprintf(stderr, "Error truncating log file!\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    uint8_t sensor_data[4];
    SensorData processed_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log data
            if (log_data(&processed_data) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

