#include <string.h>

// Define GPIO pin for SENT data
#define SENT_GPIO 4

// Define tick time (microseconds)
#define TICK_TIME 3

// Define timeout (microseconds)
#define TIMEOUT 1000

// Define SENT pulse width range (microseconds)
#define MIN_PULSE_WIDTH 36
#define MAX_PULSE_WIDTH 813

// Define MLX90824 SENT parameters
#define SYNC_PULSE_WIDTH 56 * TICK_TIME
#define STATUS_NIBBLE 4
#define DATA_NIBBLES 3
#define CHECKSUM_NIBBLE 1
#define SCALE 0.1  // Example scale factor (Pa per raw unit)
#define OFFSET 0.0 // Example offset (Pa)

// Global variables
static volatile int pulse_widths[STATUS_NIBBLE + DATA_NIBBLES + CHECKSUM_NIBBLE] = {0};
static volatile int pulse_count = 0;
static volatile int timeout_flag = 0;
static volatile int program_running = 1;

// Function prototypes
void signal_handler(int signal);
void pulse_callback(int gpio, int level, uint32_t tick);
int read_sent_data();
float calculate_pressure(int raw_value);
int validate_checksum(int raw_value);
int validate_pulse_widths();
void log_pressure(float pressure);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Callback function for pulse width measurement
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_widths[pulse_count] = tick - pulse_widths[pulse_count - 1];
        pulse_widths[pulse_count - 1] = tick;
        pulse_count++;
    } else if (level == PI_LOW) {
        pulse_count = 0;
    }
}

// Function to read SENT data from the sensor
int read_sent_data() {
    pulse_count = 0;
    timeout_flag = 0;

    // Wait for synchronization pulse
    int timeout_counter = 0;
    while (pulse_count < SYNC_PULSE_WIDTH && timeout_counter < TIMEOUT) {
        gpioDelay(TICK_TIME);
        timeout_counter++;
    }
    if (pulse_count < SYNC_PULSE_WIDTH) {
        fprintf(stderr, "Error: Timeout waiting for synchronization pulse\n");
        return -1; // Sensor-absent
    }

    // Read pulse widths
    for (int i = 0; i < STATUS_NIBBLE + DATA_NIBBLES + CHECKSUM_NIBBLE; i++) {
        pulse_count = 0;
        timeout_flag = 0;
        while (pulse_count < TIMEOUT && pulse_widths[i] == 0) {
            gpioDelay(TICK_TIME);
            timeout_counter++;
            if (timeout_counter > TIMEOUT) {
                fprintf(stderr, "Error: Timeout waiting for pulse %d\n", i);
                return -2; // Bus-error
            }
        }
        if (pulse_count >= TIMEOUT) {
            fprintf(stderr, "Error: Timeout waiting for pulse %d\n", i);
            return -2; // Bus-error
        }
        pulse_widths[i] = tick;
    }

    // Validate pulse widths
    if (!validate_pulse_widths()) {
        fprintf(stderr, "Error: Invalid pulse widths\n");
        return -3; // Bus-error
    }

    // Extract raw data
    int raw_value = 0;
    for (int i = 0; i < DATA_NIBBLES; i++) {
        raw_value = (raw_value << 1) | (pulse_widths[i + STATUS_NIBBLE] > MAX_PULSE_WIDTH / 2); // 1 if pulse width > MAX_PULSE_WIDTH / 2, 0 otherwise
    }

    // Calculate checksum
    int checksum = validate_checksum(raw_value);

    // Validate checksum
    if (checksum != (raw_value >> 4) & 0x0F) {
        fprintf(stderr, "Error: Invalid checksum\n");
        return -4; // Bus-error
    }

    return raw_value;
}

// Function to calculate pressure from raw value
float calculate_pressure(int raw_value) {
    return raw_value * SCALE + OFFSET;
}

// Function to validate checksum
int validate_checksum(int raw_value) {
    return (raw_value >> 4) & 0x0F;
}

// Function to validate pulse widths
int validate_pulse_widths() {
    for (int i = 0; i < STATUS_NIBBLE + DATA_NIBBLES + CHECKSUM_NIBBLE; i++) {
        if (pulse_widths[i] < MIN_PULSE_WIDTH || pulse_widths[i] > MAX_PULSE_WIDTH) {
            return 0; // Invalid pulse width
        }
    }
    return 1; // Valid pulse widths
}

// Function to log pressure data to file
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open pressure_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as input
    gpioSetMode(SENT_GPIO, PI_INPUT);

    // Set callback function for pulse width measurement
    gpioSetAlertFunc(SENT_GPIO, pulse_callback);

    // Set signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int raw_value = read_sent_data();
        if (raw_value != -1) {
            float pressure = calculate_pressure(raw_value);
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Error: Failed to read SENT data\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

