#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// High precision measurement command
#define MEASURE_CMD 0xFD

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables for graceful shutdown
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sht40(int i2c_handle, float *temperature, float *humidity);
int validate_crc(uint8_t data[], uint8_t crc);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd[1] = {MEASURE_CMD};
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 8.5 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC for temperature
    if (validate_crc(data, data[2]) != 0) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Validate CRC for humidity
    if (validate_crc(data + 3, data[5]) != 0) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45 + 175 * (raw_temperature / 65535.0);
    *humidity = -6 + 125 * (raw_humidity / 65535.0);

    return 0;
}

// Function to validate CRC checksum
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t polynomial[] = {CRC_POLYNOMIAL};
    uint8_t crc_calculated = 0xFF;

    for (int i = 0; i < 8; i++) {
        crc_calculated ^= data[i];
