#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define SAMPLE_INTERVAL_SEC 5
#define BUFFER_SIZE 100
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float value);
float get_latest_reading(CircularBuffer *cb);
void log_buffer(CircularBuffer *cb, const char *filename);
void signal_handler(int signal);

// Initialize the circular buffer
void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize the program
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read temperature from the TMP117 sensor
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Convert big-endian to little-endian
    uint16_t raw_temp = (buf[1] << 8) | buf[0];

    // Convert to Celsius
    float temperature = raw_temp * 0.0078125;

    return temperature;
}

// Add a reading to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the latest reading from the circular buffer
float get_latest_reading(CircularBuffer *cb) {
    if (cb->count == 0) {
        return -1000.0; // Indicate empty buffer
    }
    int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[index];
}

// Log the circular buffer to a file
void log_buffer(CircularBuffer *cb, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }

    size_t elements_written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (elements_written != cb->count) {
        fprintf(stderr, "Failed to write all elements to log file\n");
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize
    if (initialize()) {
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    init_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            add_to_buffer(&temp_buffer, temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        // Log the buffer every SAMPLE_INTERVAL_SEC seconds
        if (time(NULL) % SAMPLE_INTERVAL_SEC == 0) {
            log_buffer(&temp_buffer, LOG_FILE);
        }

        sleep(1); // Sleep for 1 second
    }

    // Cleanup
    log_buffer(&temp_buffer, LOG_FILE);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

