#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define MAX_REINIT_ATTEMPTS 3

int i2c_handle;
FILE *log_file;

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C connection
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the temperature from the TMP117
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate an error
    }

    // Convert raw temperature to Celsius
    float temperature = (float)raw_temp * TEMP_SCALE;
    return temperature;
}

// Function to log the temperature to a file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for error condition
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
        }

        time_sleep(1.0); // Wait for 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

