#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *raw_flow, int *raw_temp);
float convert_flow(int raw_flow);
float convert_temperature(int raw_temp);
int log_data(float flow_rate, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from I2C
int read_sensor_data(int *raw_flow, int *raw_temp) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    *raw_temp = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Convert raw flow data to SLPM
float convert_flow(int raw_flow) {
    return ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
}

// Convert raw temperature data to Celsius
float convert_temperature(int raw_temp) {
    return ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;
}

// Log data to file
int log_data(float flow_rate, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, flow_rate, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

