    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int first_read = 1;
    int stale_read_count = 0;

    // Main loop
    while (!terminate) {
        int raw_flow, raw_temp;

        if (first_read) {
            first_read = 0;
            stale_read_count = 0; // Reset stale read counter
            fprintf(log_file, "Power-up event. First read may be stale.\n");
            fflush(log_file);
        } else {
            stale_read_count = 0; // Reset stale read counter
        }

        if (read_sensor_data(&raw_flow, &raw_temp) == 0) {
            if (first_read || stale_read_count > 3) {
                // Discard the first two reads after power-up or if too many consecutive reads fail
                fprintf(log_file, "Discarding stale read.\n");
                fflush(log_file);
                continue; // Skip logging this iteration
            }

            float flow_rate = convert_flow(raw_flow);
            float temperature = convert_temperature(raw_temp);

            log_data(flow_rate, temperature);
            printf("Flow Rate: %.2f SLPM, Temperature: %.2f °C\n", flow_rate, temperature);
        } else {
