#include <signal.h>
#include <string.h>
#include <unistd.h>

#define DHT11_GPIO 4
#define DHT11_TIMEOUT 1000 // Timeout in milliseconds

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold DHT11 data
typedef struct {
    float temperature;
    float humidity;
    int checksum;
} DHT11Data;

// Function prototypes
int dht11_start_signal();
int dht11_read_response(int *data);
int dht11_decode_data(int *data, DHT11Data *dht11_data);
int dht11_checksum_check(const DHT11Data *dht11_data);
void log_error(const char *message);
void log_data(const DHT11Data *dht11_data);
void signal_handler(int signal);
char* iso8601_timestamp();

// Function to generate ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to send the start signal to the DHT11
int dht11_start_signal() {
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0); // Pull the line low
    gpioDelay(18); // Wait for 18 ms
    gpioWrite(DHT11_GPIO, 1); // Release the line
    gpioDelay(30); // Wait for 30 us
    return 0;
}

// Function to read the response from the DHT11
int dht11_read_response(int *data) {
    int i = 0;
    while (i < 40) {
        // Wait for the line to go low
        int timeout = 0;
        while (gpioRead(DHT11_GPIO) == 1 && timeout < DHT11_TIMEOUT) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout++;
        }
        if (timeout >= DHT11_TIMEOUT) {
            log_error("DHT11: Timeout waiting for start of response.");
            return -1; // Timeout
        }

        // Measure the high pulse duration
        int start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 0 && timeout < DHT11_TIMEOUT) {
            gpioDelay(1);
            timeout++;
        }
        if (timeout >= DHT11_TIMEOUT) {
            log_error("DHT11: Timeout waiting for end of start signal.");
            return -1; // Timeout
        }
        int end = gpioTick();

        // Calculate the high pulse duration in microseconds
        int high_pulse_duration = end - start;

        // Determine if it's a '0' or '1' based on the high pulse duration
        data[i / 8] <<= 1;
        if (high_pulse_duration > 50) {
            data[i / 8] |= 1;
        }

        i++;
    }
    return 0;
}

// Function to decode the data bits into temperature and humidity
int dht11_decode_data(int *data, DHT11Data *dht11_data) {
    // Checksum calculation
    dht11_data->checksum = 0;
    for (int i = 0; i < 4; i++) {
        dht11_data->checksum += data[i];
    }

    // Extract humidity and temperature
    dht11_data->humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    dht11_data->temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        dht11_data->temperature *= -1.0; // Handle negative temperatures
    }

    return 0;
}

// Function to check the checksum
int dht11_checksum_check(const DHT11Data *dht11_data) {
    int calculated_checksum = 0;
    for (int i = 0; i < 4; i++) {
        calculated_checksum += dht11_data->data[i];
    }

    if (calculated_checksum != dht11_data->checksum) {
        log_error("DHT11: Checksum mismatch.");
        return -1;
    }

    return 0;
}

// Function to log errors to a file
void log_error(const char *message) {
    char *timestamp = iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s ERROR: %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written to the file immediately
    } else {
        fprintf(stderr, "%s ERROR: %s\n", timestamp, message);
    }
    free(timestamp);
}

// Function to log data to a file
void log_data(const DHT11Data *dht11_data) {
    char *timestamp = iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s DATA: Temperature=%.1f\u00b0C, Humidity=%.1f%%, Checksum=%d\n",
                timestamp, dht11_data->temperature, dht11_data->humidity, dht11_data->checksum);
        fflush(log_file); // Ensure the message is written to the file immediately
    } else {
        fprintf(stderr, "%s DATA: Temperature=%.1f\u00b0C, Humidity=%.1f%%, Checksum=%d\n",
                timestamp, dht11_data->temperature, dht11_data->humidity, dht11_data->checksum);
    }
    free(timestamp);
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an input
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int data[5] = {0}; // Array to store the 40 data bits
    DHT11Data dht11_data;

    // Main loop
    while (running) {
        // Send the start signal
        if (dht11_start_signal() != 0) {
            log_error("DHT11: Failed to send start signal.");
            continue; // Try again
        }

        // Read the response
        if (dht11_read_response(data) != 0) {
            log_error("DHT11: Failed to read response.");
            continue; // Try again
        }

        // Decode the data
        if (dht11_decode_data(data, &dht11_data) != 0) {
            log_error("DHT11: Failed to decode data.");
            continue; // Try again
        }

        // Check the checksum
        if (dht11_checksum_check(&dht11_data) != 0) {
            log_error("DHT11: Checksum check failed.");
            continue; // Try again
        }

        // Log the data
        log_data(&dht11_data);

        // Wait for 2 seconds
        gpioDelay(2000); // Delay in milliseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

