#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define I2C_BUS 1
#define LOG_FILE "sht31d_data.log"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT31-D
int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int retries = 0;

    // Send measurement command
    while (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2 && retries < MAX_RETRIES) {
        gpioDelay(1000); // 1 ms delay
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(log_file, "%s,SHT31D,I2C Write Error,Command: 0x%02X%02X,Retries: %d\n", gmtime(NULL), MEASURE_CMD, MAX_RETRIES);
        fflush(log_file);
        return -1; // Indicate failure
    }

    gpioDelay(15000); // Wait 15 ms

    // Read 6 bytes of data
    retries = 0;
    while (i2cReadDevice(i2c_handle, (char *)data, 6) != 6 && retries < MAX_RETRIES) {
        gpioDelay(1000); // 1 ms delay
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(log_file, "%s,SHT31D,I2C Read Error,Retries: %d\n", gmtime(NULL), MAX_RETRIES);
        fflush(log_file);
        return -1; // Indicate failure
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(log_file, "%s,SHT31D,CRC Error,Temp CRC: 0x%02X, Hum CRC: 0x%02X\n", gmtime(NULL), crc8(data, 2), crc8(data + 3, 2));
        fflush(log_file);
        return -1; // Indicate failure
    }

    // Convert raw data to temperature and humidity
    int32_t temp_raw = (data[0] << 8) | data[1];
    int32_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0; // Indicate success
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(log_file, "%s,SHT31D,Read Failed\n", gmtime(NULL));
            fflush(log_file);
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

