    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a register to the ADPD105
int write_adpd105_register(int i2c_handle, uint8_t reg_addr, uint8_t data) {
    int result = i2cWriteI2CBlockData(i2c_handle, reg_addr, (char *)&data, 1);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data (Red, Green, Blue)
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[6];

    if (read_adpd105_register(i2c_handle, ADPD105_REG_RED, data, 6) < 0) {
        return -1;
    }

    *red = (uint16_t)((data[1] << 8) | data[0]);
    *green = (uint16_t)((data[3] << 8) | data[2]);
    *blue = (uint16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to calculate CCT using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float x = (float)red - (float)green;
    float y = (float)green - (float)blue;
    float z = (float)red + (float)green - (float)blue;
    float t = 4495.0 / (x + y + z);
    float c = 3600.0 * (t - 3485.0);
    float m = 0.000003 * c * c;
    float n = 0.000000143 * c * c * c;
    float cct = 4495.0 * (1.0 - m / 58.31 + n / 11677.31);
    return cct;
}

