#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t pressure_raw;
    uint16_t temperature_raw;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
void log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MLX90824
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->pressure_raw = (buf[1] << 8) | buf[0];
    data->temperature_raw = (buf[3] << 8) | buf[2];

    return 0;
}

// Convert raw pressure to kPa
float convert_pressure(uint16_t raw_pressure) {
    return (raw_pressure - 0) * (800.0 - 0.0) / (32768.0 - 0.0);
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return raw_temperature * 0.01 - 40.0;
}

// Log sensor data to file
void log_data(const sensor_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(data->timestamp, sizeof(data->timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&ts.tv_sec));
    fprintf(log_file, "%s,%u,%u,%.2f,%.2f\n", data->timestamp, data->pressure_raw, data->temperature_raw, convert_pressure(data->pressure_raw), convert_temperature(data->temperature_raw));
    fflush(log_file);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            fprintf(log_file, "%s,Error reading sensor data\n", buf);
            fflush(log_file);
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

