#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define AVG_SIZE 60
#define AVG_WINDOW_SIZE 10
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[AVG_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
float convert_to_celsius(unsigned int raw_temp);
float calculate_average(CircularBuffer *cb);
void control_fan(float average_temperature);
void signal_handler(int signal);
void initialize_circular_buffer(CircularBuffer *cb);

// Initialize circular buffer
void initialize_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < AVG_SIZE; i++) {
        cb->buffer[i] = 0.0; // Initialize with 0
    }
}

// Function to read temperature from LM75B
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1; // Indicate error
    }

    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    *temperature = convert_to_celsius(raw_temp);
    return 0; // Indicate success
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(unsigned int raw_temp) {
    // Extract the 9-bit temperature value
    int temp = (raw_temp >> 5) & 0x3FF; // Mask out the 9 bits

    // Sign extend if negative
    if (temp & 0x200) {
        temp |= 0xF800; // Sign extend to 12 bits
    }

    // Convert to Celsius
    return temp * 0.5;
}

// Function to calculate the running average of the temperature readings
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0; // Return 0 if the buffer is empty
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to control the cooling fan
void control_fan(float average_temperature) {
    static int fan_on = 0; // Track fan state

    if (average_temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Avg: %.2f > %.2f)\n", average_temperature, TEMP_THRESHOLD_HIGH);
    } else if (average_temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Avg: %.2f < %.2f)\n", average_temperature, TEMP_THRESHOLD_LOW);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float temperature;
    float average_temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    initialize_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(i2c_handle, &temperature) == 0) {
            // Add temperature to circular buffer
            temp_buffer.buffer[temp_buffer.head] = temperature;
            temp_buffer.head = (temp_buffer.head + 1) % AVG_SIZE;

            // Update circular buffer count
            if (temp_buffer.count < AVG_SIZE) {
                temp_buffer.count++;
            }

            // Calculate running average
            average_temperature = calculate_average(&temp_buffer);

            // Control fan
            control_fan(average_temperature);

            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    return 0;
}

