#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define PRESSURE_SCALE 60.0
#define TEMPERATURE_SCALE 200.0
#define PRESSURE_THRESHOLD 5.0
#define LOG_FILE "airflow.log"

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int validate_crc(uint8_t data[], int len, uint8_t crc);
sensor_data_t process_data(uint8_t *raw_data);
int log_data(sensor_data_t data);
void check_pressure_threshold(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error sending command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t polynomial[] = {CRC8_POLYNOMIAL};
    uint8_t crc_calculated = crc;

    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial[0];
            } else {
                crc_calculated = (crc_calculated << 1);
            }
        }
    }

    if (crc_calculated != crc) {
        fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc_calculated, crc);
        return -1;
    }
    return 0;
}

// Process raw data
sensor_data_t process_data(uint8_t *raw_data) {
    sensor_data_t data;
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    data.pressure = (float)raw_pressure / PRESSURE_SCALE;
    data.temperature = (float)raw_temperature / TEMPERATURE_SCALE;

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Check pressure threshold
void check_pressure_threshold(sensor_data_t data) {
    if (data.pressure > PRESSURE_THRESHOLD) {
        fprintf(stderr, "WARNING: Pressure exceeds threshold (%.2f Pa > %.2f Pa)\n", data.pressure, PRESSURE_THRESHOLD);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CMD_CONTINUOUS_MEASUREMENT) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t raw_data[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read data from sensor
        if (read_data(i2c_handle, raw_data, 9) == 0) {
            // Validate CRC
            if (validate_crc(raw_data, 8, raw_data[8]) == 0) {
                // Process data
                sensor_data = process_data(raw_data);

                // Log data
                log_data(sensor_data);

                // Check pressure threshold
                check_pressure_threshold(sensor_data);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Close I2C and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

