#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Constants
#define I2C_ADDR 0x4A
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define Hysteresis 1.0
#define TEMP_SCALE 0.0625
#define TEMP_REG 0x00
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void control_led(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from the STTS2004 sensor
float read_temperature() {
    int16_t raw_temp;
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, TEMP_REG);
        if (result >= 0) {
            raw_temp = (int16_t)result;
            // Combine MSB and LSB, right-shift by 4 bits
            raw_temp = ((raw_temp >> 8) | (raw_temp << 8)) >> 4;
            return (float)raw_temp * TEMP_SCALE;
        } else {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            retries--;
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -273.15; // Return absolute zero as error indicator
}

// Function to control the LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(LED_GPIO, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x4A, no flags
    if (i2c_handle < 0) {
