#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define SCALE_FACTOR_OFFSET 2
#define SCALE_FACTOR_SIZE 2
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int validate_crc(uint8_t *data, int len, uint8_t polynomial, uint8_t init_value);
sensor_data_t convert_data(uint8_t *raw_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t *data, int len, uint8_t polynomial, uint8_t init_value) {
    uint8_t crc = init_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Convert raw data to differential pressure and temperature
sensor_data_t convert_data(uint8_t *raw_data) {
    sensor_data_t data;
    int16_t differential_pressure_raw = (raw_data[0] << 8) | raw_data[1];
    int16_t temperature_raw = (raw_data[2] << 8) | raw_data[3];

    // Extract scale factor
    int16_t scale_factor = (raw_data[SCALE_FACTOR_OFFSET] << 8) | raw_data[SCALE_FACTOR_OFFSET + 1];

    // Convert to physical units
    data.differential_pressure = (float)differential_pressure_raw / scale_factor;
    data.temperature = (float)temperature_raw / 200.0;

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f Pa, %.2f °C\n", timestamp, data.differential_pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for at least 45 ms
    gpioDelay(50000); // 50 ms

    // Read data
    uint8_t raw_data[9];
    if (read_data(i2c_handle, raw_data, 9) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Validate CRC
    if (!validate_crc(raw_data, 2, CRC_POLYNOMIAL, CRC_INIT_VALUE) || !validate_crc(raw_data + 2, 2, CRC_POLYNOMIAL, CRC_INIT_VALUE)) {
        fprintf(stderr, "CRC validation failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Convert data
    sensor_data_t data = convert_data(raw_data);

    // Log data
    log_data(data);

    // Close resources
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

