#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_NO_HOLD 0xF3
#define MEASURE_HUMIDITY_NO_HOLD 0xF5
#define READ_TEMP_CMD 0xE0
#define RETRY_COUNT 3
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int handle, uint16_t *raw_temp, uint16_t *raw_humidity);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry
int read_sensor_data(int handle, uint16_t *raw_temp, uint16_t *raw_humidity) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        // Measure temperature
        if (i2cWriteByteData(handle, MEASURE_TEMP_NO_HOLD, 0) != 0) {
            fprintf(stderr, "Error writing temperature command\n");
            retries--;
            continue;
        }
        gpioDelay(20); // Wait 20ms

        uint16_t raw_temp_data;
        if (i2cReadWordData(handle, READ_TEMP_CMD) != 0) {
            fprintf(stderr, "Error reading temperature data\n");
            retries--;
            continue;
        }
        raw_temp_data = i2cReadWordData(handle, READ_TEMP_CMD);
        if (raw_temp_data < 0) {
            fprintf(stderr, "Error reading temperature data\n");
            retries--;
            continue;
        }
        *raw_temp = raw_temp_data;

        // Measure humidity
        if (i2cWriteByteData(handle, MEASURE_HUMIDITY_NO_HOLD, 0) != 0) {
            fprintf(stderr, "Error writing humidity command\n");
            retries--;
            continue;
        }
        gpioDelay(20); // Wait 20ms

        uint16_t raw_humidity_data;
        if (i2cReadWordData(handle, READ_TEMP_CMD) != 0) {
            fprintf(stderr, "Error reading humidity data\n");
            retries--;
            continue;
        }
        raw_humidity_data = i2cReadWordData(handle, READ_TEMP_CMD);
        if (raw_humidity_data < 0) {
            fprintf(stderr, "Error reading humidity data\n");
            retries--;
            continue;
        }
        *raw_humidity = raw_humidity_data;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 125.0 * raw_humidity / 65536.0 - 6.0;
}

// Log data to file and stdout
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen("environment.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fprintf(stdout, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_temp, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_temp, &raw_humidity) == 0) {
            // Convert data
            temperature = convert_temperature(raw_temp);
            humidity = convert_humidity(raw_humidity);

            // Validate data
            if (temperature < -40.0 || temperature > 85.0 || humidity < 0.0 || humidity > 100.0) {
                fprintf(stderr, "Invalid sensor data: temperature=%.2f, humidity=%.2f\n", temperature, humidity);
            } else {
                // Log data
                if (log_data(temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Sleep for 60 seconds
        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0);
    }

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

