#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// STS40 I2C address
#define STS40_ADDR 0x44

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Measurement command
#define MEASURE_CMD 0x2C
#define MEASURE_ARG 0xE0

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_open(int address);
int i2c_ioctl(int fd, int request, void *arg);
int i2c_write(int fd, uint8_t *data, int len);
int i2c_read(int fd, uint8_t *data, int len);
int sts40_read_measurement(int fd, float *temperature);
int sts40_validate_crc(uint8_t data[], int len);
float sts40_convert_to_celsius(uint16_t raw_temperature);
char* iso8601_timestamp(char* buf, size_t buf_size);
int log_temperature(const char *timestamp, float temperature);
void signal_handler(int signal);

// I2C open function
int i2c_open(int address) {
    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C ioctl function
int i2c_ioctl(int fd, int request, void *arg) {
    int result = ioctl(fd, request, arg);
    if (result < 0) {
        perror("Error in ioctl");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, uint8_t *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// STS40 read measurement function
int sts40_read_measurement(int fd, float *temperature) {
    uint8_t write_data[2] = {MEASURE_CMD, MEASURE_ARG};
    uint8_t read_data[3];
    int16_t raw_temperature;
    uint8_t crc_calculated, crc_received;

    // Send measurement command
    if (i2c_write(fd, write_data, 2) < 0) {
        fprintf(stderr, "Error sending measurement command\n");
        return -1;
    }

    // Wait for conversion (at least 10 ms)
    usleep(10000); // 10 ms

    // Read measurement data
    if (i2c_read(fd, read_data, 3) < 0) {
        fprintf(stderr, "Error reading measurement data\n");
        return -1;
    }

    // Extract CRC byte from read data
    crc_calculated = read_data[2];

    // Validate CRC
    if (sts40_validate_crc(read_data, 2) != 0) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw temperature to Celsius
    raw_temperature = (read_data[0] << 8) | read_data[1];
    *temperature = sts40_convert_to_celsius(raw_temperature);

    return 0;
}

// STS40 CRC validation function
int sts40_validate_crc(uint8_t data[], int len) {
    uint8_t crc_calculated = 0xFF;
    uint8_t crc_received = data[len];

    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    if (crc_calculated != crc_received) {
        return -1; // CRC mismatch
    }

    return 0; // CRC valid
}

// STS40 convert to Celsius function
float sts40_convert_to_celsius(uint16_t raw_temperature) {
    return -45 + 175 * raw_temperature / 65535.0;
}

// ISO 8601 timestamp function
char* iso8601_timestamp(char* buf, size_t buf_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = gmtime(&timer);

    strftime(buf, buf_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return buf;
}

// Log temperature function
int log_temperature(const char *timestamp, float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    float temperature;
    char timestamp[32];
    int retries = 3; // Number of retries for I2C operations

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Main loop
    while (1) {
        // Open I2C device
        i2c_fd = i2c_open(STS40_ADDR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to open I2C device, retrying in 5 seconds...\n");
            sleep(5);
            continue; // Retry opening I2C
        }

        // Read temperature with retries
        int read_success = 0;
        for (int i = 0; i < retries; i++) {
            if (sts40_read_measurement(i2c_fd, &temperature) == 0) {
                read_success = 1;
                break;
            } else {
                fprintf(stderr, "Failed to read temperature, retry %d/%d...\n", i + 1, retries);
                usleep(100000); // 100 ms delay
            }
        }

        if (!read_success) {
            fprintf(stderr, "Failed to read temperature after multiple retries\n");
            close(i2c_fd);
            i2c_fd = -1; // Reset i2c_fd for next loop iteration
            sleep(5);
            continue; // Retry opening I2C
        }

        // Get timestamp
        iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log temperature
        if (log_temperature(timestamp, temperature) != 0) {
            fprintf(stderr, "Failed to log temperature\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

