#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_MEASURE 0x3615
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to send the continuous measurement command
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(int handle, uint8_t *data, int len) {
    int result = i2cReadDevice(handle, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC
int validate_crc(const uint8_t *data, int len) {
    for (int i = 0; i < len; i++) {
        uint8_t crc = crc8(data + i, 1);
        if (crc != data[i + 1]) {
            fprintf(stderr, "CRC validation failed for data[%d]\n", i);
            return -1;
        }
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data, int len) {
    sensor_data_t sensor_data;
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor = (data[6] << 8) | data[7];

    // Convert to physical units
    sensor_data.pressure = (float)raw_pressure / 200.0; // Scale factor is 200 for SDP810-500Pa
    sensor_data.temperature = (float)raw_temperature / 200.0;

    return sensor_data;
}

// Function to log data to a file
int log_data(FILE *file, float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(file); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SDP810_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_command(i2c_handle, CMD_MEASURE) != 0) {
            fprintf(stderr, "Failed to send command, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Wait for measurement (at least 50ms)
        gpioDelay(50000); // 50ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Validate CRC
        if (validate_crc(data, 9) != 0) {
            fprintf(stderr, "CRC validation failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Convert data
        sensor_data = convert_data(data, 9);

        // Log data
        if (log_data(log_file, sensor_data.pressure, sensor_data.temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

