#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_MEASUREMENT_CMD 0x21B1
#define STOP_MEASUREMENT_CMD 0x3F86
#define READ_MEASUREMENT_CMD 0xE000
#define BUFFER_SIZE 100
#define LOG_FILE "/var/log/scd40_data/scd40_data_*.csv"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define SLEEP_DURATION_SEC 5
#define LOGGING_INTERVAL_SEC 60

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
static int i2c_handle;
static volatile sig_atomic_t running = 1;
static circular_buffer_t data_buffer;
static pthread_t logging_thread;
static int log_file_fd = -1; // File descriptor for the log file

// Function prototypes
int initialize_i2c();
int start_periodic_measurement();
int read_measurement(uint8_t *data, int count);
int validate_crc(uint8_t data[], int len, uint8_t polynomial, uint8_t initial_value);
void convert_data(uint8_t *data, int count, uint16_t *co2, float *temperature, float *humidity);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data, int index);
void *logging_thread_func(void *arg);
int write_to_csv(const char *filename, const sensor_data_t *data, int count);
void log_error(const char *message);
void signal_handler(int signal);
int create_log_directory();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char cmd[2] = {(START_MEASUREMENT_CMD >> 8) & 0xFF, START_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

// Read measurement data
int read_measurement(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        log_error("Failed to read measurement data");
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int len, uint8_t polynomial, uint8_t initial_value) {
    for (int i = 0; i < len; i++) {
        uint8_t crc = crc8(data + i, 1, polynomial, initial_value);
        if (crc != data[i]) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "CRC check failed for data[%d]: calculated 0x%02X, received 0x%02X", i, crc, data[i]);
            log_error(error_message);
            return -1;
        }
    }
    return 0;
}

// Convert raw data to CO2, temperature, and humidity
void convert_data(uint8_t *data, int count, uint16_t *co2, float *temperature, float *humidity) {
    *co2 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    *temperature = -45 + 175 * ((float)((uint16_t)data[2] | ((uint16_t)data[3] << 8))) / 65535.0;
    *humidity = 100 * ((float)((uint16_t)data[4] | ((uint16_t)data[5] << 8))) / 65535.0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Get data from the circular buffer
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data, int index) {
    pthread_mutex_lock(&buffer->mutex);
    if (index < 0 || index >= buffer->count) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Index out of bounds
    }
    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    *data = buffer->buffer[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging thread function
void *logging_thread_func(void *arg) {
    while (running) {
        sleep(LOGGING_INTERVAL_SEC);
        // Create the filename if it doesn't exist
        char filename[256];
        snprintf(filename, sizeof(filename), LOG_FILE);
        if (access(filename, F_OK) == -1) {
            if (mkdir(filename, 0777) != 0) {
                log_error("Failed to create log directory");
                break; // Exit thread if directory creation fails
            }
        }

        // Open the log file in append mode
        log_file_fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_file_fd == -1) {
            log_error("Failed to open log file");
            break; // Exit thread if file opening fails
        }

        // Write the data to the log file
        for (int i = 0; i < data_buffer.count; i++) {
            sensor_data_t data;
            if (get_from_buffer(&data_buffer, &data, i) == 0) {
                fprintf(log_file_fd, "%ld,%d,%.2f,%.2f\n", data.timestamp, data.co2, data.temperature, data.humidity);
            }
        }

        // Close the log file
        close(log_file_fd);
    }
    pthread_exit(NULL);
}

// Write data to CSV file
int write_to_csv(const char *filename, const sensor_data_t *data, int count) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        log_error("Failed to open CSV file for writing");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,co2,temperature,humidity\n");
    }

    // Write the data to the CSV file
    for (int i = 0; i < count; i++) {
        fprintf(fp, "%ld,%d,%.2f,%.2f\n", data[i].timestamp, data[i].co2, data[i].temperature, data[i].humidity);
    }

    fclose(fp);
    return 0;
}

// Log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    fprintf(fp, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, stopping...\n", signal);
}

// Create log directory if it doesn't exist
int create_log_directory() {
    struct stat st = {0};
    if (stat(LOG_FILE, &st) == -1) {
        if (mkdir(LOG_FILE, 0777) != 0) {
            log_error("Failed to create log directory");
            return -1;
        }
    }
    return 0;
}

int main() {
    // Initialize
    if (create_log_directory() != 0) return 1;
    if (initialize_i2c() != 0) return 1;

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    data_buffer.head = 0;
    data_buffer.tail = 0;
    data_buffer.count = 0;
    pthread_mutex_init(&data_buffer.mutex, NULL);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        uint8_t data[9];
        if (read_measurement(data, 9) == 0) {
            if (validate_crc(data, 9, 0x31, 0xFF) == 0) {
                uint16_t co2 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
                float temperature = -45 + 175 * ((float)((uint16_t)data[2] | ((uint16_t)data[3] << 8))) / 65535.0;
                float humidity = 100 * ((float)((uint16_t)data[4] | ((uint16_t)data[5] << 8))) / 65535.0;

                sensor_data_t data_point;
                data_point.timestamp = time(NULL);
                data_point.co2 = co2;
                data_point.temperature = temperature;
                data_point.humidity = humidity;

                add_to_buffer(&data_buffer, data_point);

        } else {
            log_error("Failed to read or validate CRC");
        }

        sleep(SLEEP_DURATION_SEC);
    }

    // Stop periodic measurement
    char stop_cmd[2] = {(STOP_MEASUREMENT_CMD >> 8) & 0xFF, STOP_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, stop_cmd, 2);
    if (result != 0) {
        log_error("Failed to stop periodic measurement");
    }

    // Join the logging thread
    pthread_join(logging_thread, NULL);

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

