// ICP-10110 I2C address
#define ICP10110_ADDR 0x63

// ICP-10110 register addresses
#define WHO_AM_I_REG 0x08
#define CALIB_REG 0x05
#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x02

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int16_t c0, c1, c2, c3;

// Function prototypes
int init_i2c();
int read_who_am_i();
int read_calibration_coefficients();
int read_pressure_temperature(int32_t *pressure, int32_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int32_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0); // Bus 1, address 0x63, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read WHO_AM_I register
int read_who_am_i() {
    int result = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", result);
        return -1;
    }
    return result;
}

// Read calibration coefficients
int read_calibration_coefficients() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, CALIB_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", result);
        return -1;
    }

    c0 = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Read pressure and temperature data
int read_pressure_temperature(int32_t *pressure, int32_t *temperature) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure and temperature data: %d\n", result);
        return -1;
    }

    *pressure = (int32_t)((buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3]);
    *temperature = (int32_t)((buf[3] << 24) | (buf[4] << 16) | (buf[5] << 8) | buf[6]);

    return 0;
}

