#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// ICP-10125 I2C address
#define ICP10125_ADDR 0x63

// ICP-10125 register addresses
#define ICP10125_REG_PRS_MSB 0x00
#define ICP10125_REG_TMP_MSB 0x03
#define ICP10125_REG_C0_MSB 0x66
#define ICP10125_REG_C1_MSB 0x67
#define ICP10125_REG_C2_MSB 0x68
#define ICP10125_REG_C3_MSB 0x69
#define ICP10125_REG_C4_MSB 0x6A
#define ICP10125_REG_C5_MSB 0x6B
#define ICP10125_REG_C6_MSB 0x6C
#define ICP10125_REG_C7_MSB 0x6D
#define ICP10125_REG_MEAS_CTRL 0x7E
#define ICP10125_REG_PRS_LSB 0x01
#define ICP10125_REG_TMP_LSB 0x05
#define ICP10125_REG_PRS_XLSB 0x07
#define ICP10125_REG_TMP_XLSB 0x09
#define ICP10125_REG_PRS_CRC 0x09
#define ICP10125_REG_TMP_CRC 0x0B

// GPIO pin for LED
#define LED_PIN 17

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int16_t c0, c1, c2, c3, c4, c5, c6, c7;

// Function prototypes
int init_i2c();
int read_calibration_coefficients();
int trigger_measurement();
int read_sensor_data(int32_t *pressure, int32_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int32_t raw_temperature);
void control_led(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ICP10125_ADDR, 0); // Bus 1, address 0x63, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration coefficients from OTP memory
int read_calibration_coefficients() {
    uint8_t buffer[8];
    int result = i2cReadI2CBlockData(i2c_handle, ICP10125_REG_C0_MSB, (char *)buffer, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", result);
        return -1;
    }

    c0 = (buffer[0] << 8) | buffer[1];
    c1 = (buffer[2] << 8) | buffer[3];
    c2 = (buffer[4] << 8) | buffer[5];
    c3 = (buffer[6] << 8) | buffer[7];
    c4 = (buffer[8] << 8) | buffer[9];
    c5 = (buffer[10] << 8) | buffer[11];
    c6 = (buffer[12] << 8) | buffer[13];
    c7 = (buffer[14] << 8) | buffer[15];

    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    uint8_t buffer[2];
    buffer[0] = (ICP10125_REG_MEAS_CTRL >> 8) & 0xFF; // MSB of command
    buffer[1] = ICP10125_REG_MEAS_CTRL & 0xFF;      // LSB of command

    int result = i2cWriteI2CBlockData(i2c_handle, 0x00, (char *)buffer, 2); // Dummy register address
    if (result != 2) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int32_t *pressure, int32_t *temperature) {
    uint8_t buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, ICP10125_REG_PRS_MSB, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *pressure = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    *temperature = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];

    // CRC check
    uint8_t crc_pressure = buffer[5] ^ 0x07;
    for (int i = 0; i < 4; i++) {
        crc_pressure ^= buffer[2 + i];
        for (int j = 0; j < 8; j++) {
            if (crc_pressure & 0x80) {
                crc_pressure = (crc_pressure << 1) ^ 0x31;
            } else {
                crc_pressure = (crc_pressure << 1);
            }
        }
    }
    if (crc_pressure != buffer[6]) {
        fprintf(stderr, "CRC check failed for pressure\n");
        return -1;
    }

    uint8_t crc_temperature = buffer[6] ^ 0x07;
    for (int i = 0; i < 4; i++) {
        crc_temperature ^= buffer[4 + i];
        for (int j = 0; j < 8; j++) {
            if (crc_temperature & 0x80) {
                crc_temperature = (crc_temperature << 1) ^ 0x31;
            } else {
                crc_temperature = (crc_temperature << 1);
            }
        }
    }
    if (crc_temperature != buffer[7]) {
        fprintf(stderr, "CRC check failed for temperature\n");
        return -1;
    }

    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int32_t raw_pressure) {
    float p = 0.0f;
    p = (float)raw_pressure / 4096.0f; // Scale factor from datasheet
    return p;
}

// Convert raw temperature to Celsius
float convert_temperature(int32_t raw_temperature) {
    float t = 0.0f;
    t = (float)raw_temperature / 4096.0f; // Scale factor from datasheet
    return t;
}

// Control the LED based on pressure
void control_led(float pressure) {
    if (pressure > 95000.0f) {
        // Normal condition: 1 Hz blinking
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(500);        // Wait 500 ms
        gpioWrite(LED_PIN, 0); // Turn LED off
        gpioDelay(500);        // Wait 500 ms
    } else {
        // Warning condition: 5 Hz blinking
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(100);        // Wait 100 ms
        gpioWrite(LED_PIN, 0); // Turn LED off
        gpioDelay(100);        // Wait 100 ms
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int32_t raw_pressure, raw_temperature;
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (adjust as needed)
        gpioDelay(20); // 20 ms delay

        // Read sensor data
        if (read_sensor_data(&raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Control LED
        control_led(pressure);

        // Print data (optional)
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

