        return -999.0; // Indicate invalid reading
    }

    if (raw_temp < OBJECT_TEMP_MIN || raw_temp > OBJECT_TEMP_MAX) {
        fprintf(stderr, "Invalid object temperature: %d\n", raw_temp);
        return -999.0; // Indicate invalid reading
    }

    return (float)raw_temp * 0.02 - 273.15;
}

