#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define SERVER_PORT 8080
#define MAX_SENSORS 4
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
int server_fd;
int sensor_addresses[MAX_SENSORS];
int num_sensors = 0;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_server();
int read_sht40(int i2c_handle, int sensor_address, float *temperature, float *humidity);
int handle_client(int client_socket);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the server
int init_server() {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error binding socket");
        close(server_fd);
        return -1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("Error listening on socket");
        close(server_fd);
        return -1;
    }

    return 0;
}

// Function to read data from SHT40 sensor
int read_sht40(int i2c_handle, int sensor_address, float *temperature, float *humidity) {
    char buf[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    unsigned short raw_temperature = (buf[0] << 8) | buf[1];
    unsigned short raw_humidity = (buf[3] << 8) | buf[4];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = -6.0 + 125.0 * (float)raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Function to handle client connection
int handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    // Read request from client
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        return -1;
    }
    buffer[bytes_received] = '\0';

    // Construct HTML response
    char response[2048];
    snprintf(response, sizeof(response), 
             "HTTP/1.1 200 OK\r\n" 
             "Content-Type: text/html\r\n" 
             "\r\n" 
             "<!DOCTYPE html><html><head><title>Temperature and Humidity</title></head><body>" 
             "<h1>Temperature and Humidity</h1><p>Temperature: %.2f &deg;C</p><p>Humidity: %.2f %%</p></body></html>",
             sensor_data_t{.temperature = 0.0, .humidity = 0.0});

    // Send response to client
    if (send(client_socket, response, strlen(response), 0) < 0) {
        perror("Error sending data");
        return -1;
    }

    close(client_socket);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize server
    if (init_server() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensors
        for (int i = 0; i < num_sensors; i++) {
            float temperature, humidity;
            int result = read_sht40(i2c_handle, sensor_addresses[i], &temperature, &humidity);
            if (result == 0) {
                // Update sensor data
                sensor_data_t sensor_data = {temperature, humidity};
                // Construct JSON payload
                char json_payload[256];
                snprintf(json_payload, sizeof(json_payload), "{\"sensors\":[{\"address\":0x%x, \"temperature\":%.2f, \"humidity\":%.2f}]}",
                         sensor_addresses[i], sensor_data.temperature, sensor_data.humidity);

                // Send data to server
                if (send(server_fd, json_payload, strlen(json_payload), 0) < 0) {
                    perror("Error sending data to server");
                }
            } else {
                fprintf(stderr, "Error reading sensor 0x%x, skipping\n", sensor_addresses[i]);
            }
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

