#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 Registers
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define TEMP_MSB 0x00
#define TEMP_LSB 0x01
#define HUMID_MSB 0x02
#define HUMID_LSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(int16_t *temperature, int16_t *humidity);
float convert_temperature(int16_t raw_temp);
float convert_humidity(int16_t raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a temperature and humidity measurement
int trigger_measurement() {
    int retries = 0;
    while (retries < 3) {
        if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x01) >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to MEASUREMENT_CONFIG (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(100000); // 100ms delay
            retries++;
        }
    }
    fprintf(stderr, "Failed to trigger measurement after 3 retries.\n");
    return -1; // Failure
}

// Read temperature and humidity data from the sensor
int read_sensor_data(int16_t *temperature, int16_t *humidity) {
    int retries = 0;
    while (retries < 3) {
        if (i2cWriteByteData(i2c_handle, CONFIG, 0x00) >= 0) {
            gpioDelay(1000); // Wait for measurement to complete (at least 1ms)
            if (i2cReadWordData(i2c_handle, TEMP_MSB) >= 0) {
                *temperature = i2cReadWordData(i2c_handle, TEMP_MSB);
                if (i2cReadWordData(i2c_handle, HUMID_MSB) >= 0) {
                    *humidity = i2cReadWordData(i2c_handle, HUMID_MSB);
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error reading HUMID_MSB (attempt %d): %d\n", retries + 1, i2c_handle);
                }
            } else {
                fprintf(stderr, "Error reading TEMP_MSB (attempt %d): %d\n", retries + 1, i2c_handle);
            }
        } else {
            fprintf(stderr, "Error writing to CONFIG (attempt %d): %d\n", retries + 1, i2c_handle);
        }
        gpioDelay(100000); // 100ms delay
        retries++;
    }
    fprintf(stderr, "Failed to read sensor data after 3 retries.\n");
    return -1; // Failure
}

// Convert raw temperature data to Celsius
float convert_temperature(int16_t raw_temp) {
    return ((float)raw_temp / 65536.0) * 165.0 - 40.0;
}

// Convert raw humidity data to percentage
float convert_humidity(int16_t raw_humidity) {
    return ((float)raw_humidity / 65536.0) * 100.0;
}

// Log temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    int16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Skipping this iteration.\n");
            gpioDelay(5000000); // Wait 5 seconds
            continue;
        }

        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_humidity) != 0) {
            fprintf(stderr, "Failed to read sensor data. Skipping this iteration.\n");
            gpioDelay(5000000); // Wait 5 seconds
            continue;
        }

        // Convert data
        temperature = convert_temperature(raw_temperature);
        humidity = convert_humidity(raw_humidity);

        // Log data
        log_data(temperature, humidity);

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

