#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x02
#define CRC_POLYNOMIAL 0x31
#define INITIAL_CRC_VALUE 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, int command);
int read_data(int handle, char *buffer, int count);
int verify_checksum(int16_t data, int16_t crc);
sensor_data_t read_sensor_data(int handle);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to the sensor
int send_command(int handle, int command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify CRC checksum
int verify_checksum(int16_t data, int16_t crc) {
    // CRC-8 calculation
    int polynomial = CRC_POLYNOMIAL;
    int initial_value = INITIAL_CRC_VALUE;
    int crc_calculated = 0;

    // Convert data to unsigned 8-bit values
    unsigned char data_bytes[2];
    data_bytes[0] = (unsigned char)(data >> 8);
    data_bytes[1] = (unsigned char)(data & 0xFF);

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    // Compare calculated CRC with received CRC
    return (crc_calculated == crc);
}

// Read sensor data
sensor_data_t read_sensor_data(int handle) {
    sensor_data_t data;
    char buffer[6];

    // Send continuous measurement command
    if (send_command(handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        data.pressure = 0; // Indicate error
        data.temperature = 0;
        return data;
    }

    // Wait for measurement to complete (at least 45 ms)
    gpioDelay(50000); // 50 ms

    // Read pressure and temperature data
    if (read_data(handle, buffer, 6) != 0) {
        data.pressure = 0; // Indicate error
        data.temperature = 0;
        return data;
    }

    // Extract pressure and temperature values
    data.pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    // Verify checksums
    if (!verify_checksum(data.pressure, buffer[2])) {
        fprintf(stderr, "Pressure checksum error\n");
        data.pressure = 0; // Indicate error
    }
    if (!verify_checksum(data.temperature, buffer[5])) {
        fprintf(stderr, "Temperature checksum error\n");
        data.temperature = 0; // Indicate error
    }

    return data;
}

// Log sensor data to the console
void log_data(sensor_data_t data) {
    printf("Pressure: %d Pa, Temperature: %d °C\n", data.pressure, data.temperature);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data(i2c_handle);

        if (sensor_data.pressure != 0 && sensor_data.temperature != 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(500000); // 500 ms
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

