    int polynomial = CRC_POLYNOMIAL;
    int initial_value = INITIAL_CRC_VALUE;
    int crc_calculated = 0;

    // Convert data to unsigned 8-bit values
    unsigned char data_bytes[2];
    data_bytes[0] = (unsigned char)(data >> 8);
    data_bytes[1] = (unsigned char)(data & 0xFF);

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
