#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TARGET_PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define SPI_SPEED 1000000 // 1 MHz
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// PID Constants
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
int spi_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Structure to hold PID state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function Prototypes
int spi_init(const char *device);
int spi_read_data(int fd, uint8_t *data);
double read_temperature();
double read_target_temperature(const char *filename);
double pid_control(double setpoint, double actual_temperature, PIDState *state);
int gpio_init(const char *chipname, int pin);
int gpio_set_value(int pin, int value);
int gpio_export(int pin, const char *chipname);
int gpio_unexport(int pin, const char *chipname);
double calculate_duty_cycle(double pid_output);
void log_data(double temperature, double target_temperature, double duty_cycle);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Set SPI max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read Data
int spi_read_data(int fd, uint8_t *data) {
    uint8_t tx_buf[2] = {0x01, 0x00}; // Example: Send a dummy byte to receive data
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)data,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read Temperature from MAX6675
double read_temperature() {
    uint8_t data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spi_read_data(spi_fd, data) == 0) {
            // Check for fault bit (bit 2)
            if (data[1] & 0x04) {
                fprintf(stderr, "MAX6675 Fault detected!\n");
                return -273.15; // Return absolute zero as error indicator
            }

            // Extract temperature data (bits 3-14)
            int16_t raw_temp = ((data[1] & 0x0F) << 8) | data[0];
            raw_temp >>= 4; // Right-shift to get rid of the irrelevant bits

            return (double)raw_temp * 0.25;
        } else {
            fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            retries++;
        }
    }

    fprintf(stderr, "MAX6675 read failed after %d retries.\n", MAX_RETRIES);
    return -273.15; // Return absolute zero as error indicator
}

// Read Target Temperature from File
double read_target_temperature(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening target profile file");
        return -273.15; // Return absolute zero as error indicator
    }

    char line[256];
    double target_temp = -273.15;
    double time_sec;

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%lf,%lf", &time_sec, &target_temp) == 2) {
            // Validate time and temperature
            if (time_sec >= 0 && time_sec <= 60 && target_temp > -273.0 && target_temp <= 500.0) {
                // Update global target temperature
                target_temp = target_temp;
            }
        }
    }

    fclose(fp);
    return target_temp;
}

// PID Control
double pid_control(double setpoint, double actual_temperature, PIDState *state) {
    double error = setpoint - actual_temperature;
    pid_state->integral += error;
    double derivative = error - pid_state->previous_error;
    double output = Kp * error + Ki * pid_state->integral + Kd * derivative;
    pid_state->previous_error = error;

    // Clamp output to 0-1 range
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// GPIO Initialization
int gpio_init(const char *chipname, int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "reflow", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(int pin, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO Export
int gpio_export(int pin, const char *chipname) {
    if (gpiod_chip_open_by_name(chipname) < 0) {
        perror("Error opening GPIO chip for export");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chipname, pin);
    if (!line) {
        perror("Error getting GPIO line for export");
        gpiod_chip_close(chipname);
        return -1;
    }

    if (gpiod_line_request_output(line, "reflow", 0) < 0) {
        perror("Error requesting GPIO line for export");
        gpiod_chip_close(chipname);
        return -1;
    }

    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line for export");
        gpiod_chip_close(chipname);
        return -1;
    }

    if (gpiod_chip_close(chipname) < 0) {
        perror("Error closing GPIO chip for export");
        return -1;
    }

    return 0;
}

// GPIO Unexport
int gpio_unexport(int pin, const char *chipname) {
    if (gpiod_chip_open_by_name(chipname) < 0) {
        perror("Error opening GPIO chip for unexport");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chipname, pin);
    if (!line) {
        perror("Error getting GPIO line for unexport");
        gpiod_chip_close(chipname);
        return -1;
    }

    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line for unexport");
        gpiod_chip_close(chipname);
        return -1;
    }

    if (gpiod_chip_close(chipname) < 0) {
        perror("Error closing GPIO chip for unexport");
        return -1;
    }

    return 0;
}

// Calculate Duty Cycle
double calculate_duty_cycle(double pid_output) {
    return pid_output * 100.0; // Scale PID output to 0-100%
}

// Log Data
void log_data(double temperature, double target_temperature, double duty_cycle) {
    if (log_file != NULL) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, target_temperature, duty_cycle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_line != NULL) {
        gpiod_line_set_value(gpio_line, 0); // Turn off the relay
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open Log File
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),TargetTemperature(C),DutyCycle\n");
    }

    // Main Loop
    double target_temperature = read_target_temperature(TARGET_PROFILE_FILE);
    if (target_temperature < -273.0) {
        fprintf(stderr, "Failed to read target temperature profile. Exiting.\n");
        cleanup();
        return 1;
    }

    while (program_running) {
        double temperature = read_temperature();
        if (temperature < -273.0) {
            fprintf(stderr, "Failed to read temperature. Skipping PID control.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        double pid_output = pid_control(target_temperature, temperature, &pid_state);

        // Calculate duty cycle
        double duty_cycle = calculate_duty_cycle(pid_output);

        // Set GPIO value (0 or 1)
        if (gpio_set_value(GPIO_PIN, (int)duty_cycle) < 0) {
            fprintf(stderr, "Failed to set GPIO value. Continuing.\n");
        }

        // Log data
        log_data(temperature, target_temperature, duty_cycle);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

