#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define I2C_BUS 1
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init();
int aht20_trigger_measurement();
int aht20_read_data(uint8_t *data);
float calculate_humidity(uint8_t *data);
void control_dehumidifier(float humidity);
void log_humidity(float humidity);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the AHT20 sensor
int aht20_init() {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error initializing AHT20: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait for initialization to complete
    return 0;
}

// Function to trigger a measurement on the AHT20 sensor
int aht20_trigger_measurement() {
    uint8_t trigger_cmd[3] = {0xAC, 0x33, 0x00};
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)trigger_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error triggering AHT20 measurement: %d\n", result);
        return -1;
    }
    gpioDelay(80); // Wait for measurement to complete
    return 0;
}

// Function to read data from the AHT20 sensor
int aht20_read_data(uint8_t *data) {
    int result;
    char buf[7];

    result = i2cReadDevice(i2c_handle, buf, 7);
    if (result != 7) {
        fprintf(stderr, "Error reading data from AHT20: %d\n", result);
        return -1;
    }

    data[0] = buf[0];
    data[1] = buf[1];
    data[2] = buf[2];
    data[3] = buf[3];
    data[4] = buf[4];
    data[5] = buf[5];
    data[6] = buf[6];

    return 0;
}

// Function to calculate humidity from the raw data
float calculate_humidity(uint8_t *data) {
    uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    float humidity = (float)raw_humidity * 100.0 / 0x100000;
    return humidity;
}

// Function to control the dehumidifier relay
void control_dehumidifier(float humidity) {
    static int dehumidifier_state = 0; // 0 = off, 1 = on

    if (humidity > HUMIDITY_THRESHOLD_HIGH && dehumidifier_state == 0) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        dehumidifier_state = 1;
        printf("Dehumidifier ON\n");
    } else if (humidity < HUMIDITY_THRESHOLD_LOW && dehumidifier_state == 1) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        dehumidifier_state = 0;
        printf("Dehumidifier OFF\n");
    }
}

// Function to log humidity data with a timestamp
void log_humidity(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Initialize to off

    // Initialize AHT20 sensor
    if (aht20_init() != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[7];
    float humidity;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (aht20_trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Read data
        if (aht20_read_data(data) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate humidity
        humidity = calculate_humidity(data);

        // Control dehumidifier
        control_dehumidifier(humidity);

        // Log humidity
        log_humidity(humidity);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

