#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define RETRY_COUNT 3
#define RETRY_DELAY_SEC 1

// Global variables
int i2c_fd = -1;
int socket_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_htu21d(int fd, float *humidity);
int post_data(const char *url, const char *data);
void signal_handler(int sig);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access or talk to slave 0x%02x: %s", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read humidity from HTU21D sensor
int read_htu21d(int fd, float *humidity) {
    unsigned char cmd[2] = {0xE5, 0x00}; // Trigger measurement command
    unsigned char data[3];
    int retries = 0;
    int bytes_written, bytes_read;

    while (retries < RETRY_COUNT) {
        bytes_written = write(fd, cmd, 2);
        if (bytes_written != 2) {
            syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        usleep(100000); // Wait for measurement (at least 50ms)

        bytes_read = read(fd, data, 3);
        if (bytes_read != 3) {
            syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // CRC check
        unsigned char crc = 0xFF;
        for (int i = 0; i < 2; i++) {
            crc = (crc << 8) ^ data[i];
        }

        if (crc != data[2]) {
            syslog(LOG_ERR, "CRC check failed");
            retries++;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // Convert data to humidity
        unsigned int raw_humidity = ((data[0] << 8) | data[1]) >> 8;
        *humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

        return 0; // Success
    }

    syslog(LOG_ERR, "Failed to read humidity after multiple retries.");
    return -1; // Failure
}

// Function to post data to HTTP endpoint
int post_data(const char *url, const char *data) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024] = {0};
    ssize_t bytes_sent;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // Default HTTP port
    if (inet_pton(AF_INET, url, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", url);
        close(sockfd);
        return -1;
    }

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Prepare the HTTP request
    snprintf(buffer, sizeof(buffer), "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", url, url, strlen(data), data);

    // Send the request
    bytes_sent = send(sockfd, buffer, strlen(buffer), 0);
    if (bytes_sent < 0) {
        syslog(LOG_ERR, "Failed to send request: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Receive the response (optional, but good practice)
    char response[1024] = {0};
    memset(response, 0, sizeof(response));
    bytes_sent = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_sent < 0) {
        syslog(LOG_ERR, "Failed to receive response: %s", strerror(errno));
    } else {
        response[bytes_sent] = '\0';
        syslog(LOG_INFO, "HTTP Response: %s", response);
    }

    // Close the connection
    close(sockfd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
    syslog(LOG_INFO, "Cleanup complete.");
}

int main() {
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);
