        fflush(log_file);
        printf("%s - Pressure: %.2f hPa - HIGH\n", timestamp, pressure);
    } else if (pressure < PRESSURE_THRESHOLD_LOW) {
        fprintf(log_file, "%s - Pressure: %.2f hPa - LOW\n", timestamp, pressure);
        fflush(log_file);
        printf("%s - Pressure: %.2f hPa - LOW\n", timestamp, pressure);
    }

