        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;

        // Read raw data with retry
        while (retry_count < 3) {
            if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read error, retrying... (%d/3)\n", retry_count + 1);
                gpioDelay(10000); // 10ms delay
                retry_count++;
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "Failed to read raw data after 3 retries, exiting.\n");
            break;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);

        // Log pressure
        log_pressure(pressure);

        gpioDelay(2000000); // 2 seconds
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

