#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define BACKOFF_MS 10
#define CSV_HEADER "Timestamp,Temperature(C),Humidity(%%),MotionDetected"

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *pir_line = NULL;

// Function prototypes
int init_i2c(const char *bus);
int init_gpio(int chip_num, int line_num);
int read_aht20(float *temperature, float *humidity);
int read_tmp117(float *temperature);
int read_pir_sensor(void);
int log_data(float temperature, float humidity, int motion);
void signal_handler(int sig);
void cleanup(void);

// I2C functions
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Error setting I2C slave address for TMP117");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Error setting I2C slave address for AHT20");
        close(fd);
        return -1;
    }

    return fd;
}

int read_tmp117(float *temperature) {
    unsigned char buf[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        buf[0] = 0x00; // Temperature register address
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Error writing to I2C device (TMP117)");
            retries++;
            usleep(BACKOFF_MS * 1000); // Exponential backoff
            continue;
        }

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Error reading from I2C device (TMP117)");
            retries++;
            usleep(BACKOFF_MS * 1000); // Exponential backoff
            continue;
        }

        // Convert raw data to temperature (LSB = 0.0078125 °C)
        int16_t raw_temp = (buf[0] << 8) | buf[1];
        *temperature = (float)raw_temp * 0.0078125;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature from TMP117 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// AHT20 functions
int read_aht20(float *temperature, float *humidity) {
    unsigned char init_cmd[] = {0xBE, 0x08, 0x00};
    unsigned char measure_cmd[] = {0xAC, 0x33, 0x00};
    unsigned char buf[7];
    int retries = 0;
    int bytes_read;

    // Initialize AHT20 sensor
    if (write(i2c_fd, init_cmd, sizeof(init_cmd)) != sizeof(init_cmd)) {
        perror("Error writing initialization command to AHT20");
        retries++;
        usleep(BACKOFF_MS * 1000); // Exponential backoff
        continue;
    }
    usleep(15000); // Wait for initialization (datasheet)

    // Measure temperature and humidity
    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, measure_cmd, sizeof(measure_cmd)) != sizeof(measure_cmd)) {
            perror("Error writing measurement command to AHT20");
            retries++;
            usleep(BACKOFF_MS * 1000); // Exponential backoff
            continue;
        }

        usleep(100000); // Wait for measurement (datasheet)

        if (read(i2c_fd, buf, 7) != 7) {
            perror("Error reading measurement data from AHT20");
            retries++;
            usleep(BACKOFF_MS * 1000); // Exponential backoff
            continue;
        }

        // Check busy bit (bit 7 of buf[0])
        if (buf[0] & 0x80) {
            fprintf(stderr, "AHT20 busy.\n");
            retries++;
            usleep(BACKOFF_MS * 1000); // Exponential backoff
            continue;
        }

        // Extract humidity and temperature data
        unsigned long humidity_raw = ((unsigned long)buf[1] << 12) | ((unsigned long)buf[2] << 4) | (buf[3] >> 4);
        unsigned long temperature_raw = ((unsigned long)buf[3] & 0x0F) << 16 | ((unsigned long)buf[4] << 8) | buf[5];

        // Convert raw data to humidity and temperature (datasheet formulas)
        *humidity = ((float)humidity_raw / 0x100000) * 100;
        *temperature = ((float)temperature_raw / 0x100000) * 200 - 50;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read data from AHT20 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// GPIO functions
int init_gpio(int chip_num, int line_num) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_num);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, line_num);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(line, "logger", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return line;
}

int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Logging functions
int log_data(float temperature, float humidity, int motion) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen("logger.log", "a");
    if (fp == NULL) {
        perror("Error opening logger.log");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);

    if (fclose(fp) != 0) {
        perror("Error closing logger.log");
        return -1;
    }

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main(void) {
    float temperature, humidity;
    int motion;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    pir_line = init_gpio(GPIO_CHIP, GPIO_LINE);
    if (pir_line < 0) {
        fprintf(stderr, "Failed to initialize GPIO. Continuing without PIR sensor.\n");
    }

    // Check sensor presence
    if (!pir_line) {
        printf("PIR sensor not found. Logging without motion detection.\n");
    }

    printf("Logger started. Logging to logger.log\n");

    while (program_running) {
        // Read sensor data
        if (read_tmp117(&temperature) == 0) {
            printf("TMP117 Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read TMP117 temperature.\n");
        }

        if (read_aht20(&temperature, &humidity) == 0) {
            printf("AHT20 Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read AHT20 temperature and humidity.\n");
        }

        // Read PIR sensor
        motion = read_pir_sensor();
        if (pir_line) {
            printf("PIR Sensor: %s\n", motion ? "Motion Detected" : "No Motion");
        } else {
            motion = 0; // Default to no motion if PIR sensor is not initialized
        }

        // Log data
        if (log_data(temperature, humidity, motion) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

