#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <syslog.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define ENA_PIN 22
#define IN1_PIN 23
#define IN2_PIN 24

// Define SPI parameters
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz

// Define motor control parameters
#define MOTOR_FORWARD_DURATION 5 // seconds

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *ena_line = NULL;
static struct gpiod_line *in1_line = NULL;
static struct gpiod_line *in2_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int bus, int device, int speed);
int read_rain_sensor(int gpio_pin);
int control_motor_forward(int ena_pin, int in1_pin, int in2_pin, int duration);
int stop_motor(int ena_pin, int in1_pin, int in2_pin);
int gpio_export(int gpio_pin);
int gpio_unexport(int gpio_pin);
int gpio_set_direction(int gpio_pin, const char *direction);
int gpio_write(int gpio_pin, int value);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(int bus, int device, int speed) {
    char spi_device_path[20];
    sprintf(spi_device_path, "/dev/spidev%d.%d", bus, device);

    spi_fd = open(spi_device_path, O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = speed; // Assign the speed to the variable
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed: %s", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Rain sensor reading function
int read_rain_sensor(int gpio_pin) {
    // This is a placeholder.  In a real implementation,
    // you would read the GPIO pin using gpiod_line_get_value().
    // For simulation purposes, we'll return a random value.
    int value = rand() % 2; // 0 or 1
    return value;
}

// Motor control function
int control_motor_forward(int ena_pin, int in1_pin, int in2_pin, int duration) {
    if (gpio_write(ena_pin, 1) < 0) {
        syslog(LOG_ERR, "Failed to enable motor: %s", strerror(errno));
        return -1;
    }
    if (gpio_write(in1_pin, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high: %s", strerror(errno));
        return -1;
    }
    if (gpio_write(in2_pin, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low: %s", strerror(errno));
        return -1;
