#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(char *line) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    // Read the first line which contains the CPU usage statistics
    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading /proc/stat");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load
float calculate_cpu_load(char *line) {
    char *token;
    char *rest = line;
    char *last_space = rest;
    int cpu_usage = 0;

    // Tokenize the line by space characters
    while ((token = strtok_r(rest, " \t", &rest)) != NULL) {
        if (strncmp(token, "cpu", 3) == 0) {
            // Convert the usage to an integer
            char *endptr;
            cpu_usage = strtol(token, &endptr, 10);

            // Check for errors during conversion
            if (*endptr != '\0' && *endptr != '\n') {
                fprintf(stderr, "Error: Invalid CPU usage value: %s\n", token);
                return -1.0f; // Indicate an error
            }
        }
    }

    // Calculate the CPU load as a percentage
    return (float)cpu_usage / 100.0f;
}

// Function to map CPU load to RGB color values
void map_cpu_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load < 0.0f) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else if (cpu_load < 50.0f) {
        *red = 0;
        *green = (int)(cpu_load * 2.0f);
        *blue = 0;
    } else {
        *red = 255;
        *green = 255;
        *blue = 0;
    }
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Invert for common anode
    gpioPWM(GREEN_PIN, 255 - green); // Invert for common anode
    gpioPWM(BLUE_PIN, 255 - blue);  // Invert for common anode
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char line[256];
    float cpu_load;
    int red, green, blue;

    // Main loop
    while (program_running) {
        // Read CPU statistics
        if (read_cpu_stats(line) == 0) {
            // Calculate CPU load
            cpu_load = calculate_cpu_load(line);

            if (cpu_load >= 0.0f) {
                // Map CPU load to RGB color
                map_cpu_to_color(cpu_load, &red, &green, &blue);

                // Set LED color
                set_led_color(red, green, blue);
            } else {
                fprintf(stderr, "Error calculating CPU load\n");
            }
        } else {
            fprintf(stderr, "Error reading CPU stats\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms
    }

    // Turn off the LED before exiting
    set_led_color(255, 255, 255); // Full on for common anode

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

