#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting
#define OSS 3

// GPIO pin for interrupt
#define INTERRUPT_PIN 2

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static FILE *log_file = NULL;
static int ac1, ac2, ac3, b1, b2, mb, mc, md, ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, int raw_temp);
double calculate_altitude(double pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    char write_buf[2];

    // Write temperature read command
    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }

    // Wait for measurement (4.5ms)
    gpioDelay(5000);

    // Read temperature data
    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, write_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    char write_buf[2];

    // Write pressure read command
    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x34 + (OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing pressure read command\n");
        return -1;
    }

    // Wait for measurement (based on OSS)
    switch (OSS) {
        case 0: gpioDelay(5000); break;
        case 1: gpioDelay(8000); break;
        case 2: gpioDelay(14000); break;
        case 3: gpioDelay(26000); break;
        default: fprintf(stderr, "Invalid OSS value\n"); return -1;
    }

    // Read pressure data
    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, write_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing pressure read command\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1, x2, b5;
    double temperature;

    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;
    temperature = ((b5 + 8) >> 4) / 10.0;

    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temp) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    long UT = raw_temp;
    long UP = raw_pressure;

    long x1_temp = (((long)UT - (long)ac6) * (long)ac5) >> 15;
    long x2_temp = ((long)mc << 11) / (x1_temp + md);
    long b5_temp = x1_temp + x2_temp;

    long b6_temp = b5_temp - 4000;
    x1 = (b2 * (b6_temp * b6_temp) >> 12) >> 11;
    x2 = (ac2 * b6_temp) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = (ac3 * b6_temp) >> 13;
    x2 = (b1 * ((b6_temp * b6_temp) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;

    b7 = ((unsigned long)UP - b3) * (50000 >> OSS);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return p;
}

// Function to calculate altitude in meters
double calculate_altitude(double pressure) {
    double altitude = 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
    return altitude;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int raw_temp, raw_pressure;
    double temperature, pressure, altitude;
    time_t timestamp;
    struct tm *timeinfo;
    char timestamp_str[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO2 as input with pull-up resistor
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    // Set interrupt handler for falling edge
    if (gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature,pressure,altitude\n");
    }
    rewind(log_file);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate temperature and pressure
                temperature = calculate_temperature(raw_temp);
                pressure = calculate_pressure(raw_pressure, raw_temp);
                altitude = calculate_altitude(pressure);

                // Get current timestamp
                time(&timestamp);
                timeinfo = localtime(&timestamp);
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log data to file
                fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp_str, temperature, pressure, altitude);
                fflush(log_file); // Ensure data is written to disk

                printf("%s - Temperature: %.2f C, Pressure: %.2f Pa, Altitude: %.2f m\n", timestamp_str, temperature, pressure, altitude);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        sleep(1);
    }

    return 0;
}

