#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CHIP_SELECT_PIN 8 // GPIO8
#define LOG_FILE "rtd_log.csv"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// Callendar-Van Dusen Equation Coefficients (PT100)
#define A 0.0039083
#define B -0.0000005775
#define R0 100.0

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(int fd, uint8_t reg, uint8_t *data, int len);
int max31865_read_config(int fd, uint16_t *config);
int max31865_read_rtd(int fd, uint16_t *rtd);
float calculate_temperature(uint16_t rtd);
int log_temperature(float temperature);
void signal_handler(int sig);
int gpio_init(void);
int gpio_set_cs_high(void);
int gpio_set_cs_low(void);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t tx_buf[1] = {reg};
    uint8_t rx_buf[len + 1];

    rx_buf[0] = 0x00; // Dummy byte for reading

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len + 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// MAX31865 Read Configuration
int max31865_read_config(int fd, uint16_t *config) {
    uint8_t data[2];

    if (spi_transfer(fd, MAX31865_CONFIG_REG, data, 2) != 0) {
        fprintf(stderr, "Error reading config register\n");
        return -1;
    }

    *config = (data[0] << 8) | data[1];
    return 0;
}

// MAX31865 Read RTD
int max31865_read_rtd(int fd, uint16_t *rtd) {
    uint8_t data[2];

    if (spi_transfer(fd, MAX31865_RTD_MSB_REG, data, 2) != 0) {
        fprintf(stderr, "Error reading RTD MSB register\n");
        return -1;
    }

    *rtd = (data[0] << 8) | data[1];
    return 0;
}

// Calculate Temperature using Callendar-Van Dusen Equation
float calculate_temperature(uint16_t rtd) {
    float rtd_resistance = (float)rtd * 400.0 / 32768.0; // Assuming 400 Ohm reference resistor
    float temperature = (A + B * rtd_resistance) * (R0 / rtd_resistance - 1);
    return temperature;
}

// Log Temperature to CSV File
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CHIP_SELECT_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "rtd-reader", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO Set CS High
int gpio_set_cs_high(void) {
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }
    return 0;
}

// GPIO Set CS Low
int gpio_set_cs_low(void) {
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }
    return 0;
}

// Cleanup Resources
void cleanup(void) {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete. Exiting.\n");
}

// Signal Handler
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main(void) {
    uint16_t config, rtd;
    float temperature;
    int retry;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }
    rewind(log_file);

    printf("RTD Reader started. Logging to %s every 5 seconds. Press Ctrl+C to exit.\n", LOG_FILE);

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            // Set CS high
            if (gpio_set_cs_high() != 0) {
                fprintf(stderr, "Error setting CS high. Retrying...\n");
                retry++;
                usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            // Read configuration
            if (max31865_read_config(spi_fd, &config) != 0) {
                fprintf(stderr, "Error reading config. Retrying...\n");
                retry++;
                usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            // Read RTD
            if (max31865_read_rtd(spi_fd, &rtd) != 0) {
                fprintf(stderr, "Error reading RTD. Retrying...\n");
                retry++;
                usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            // Calculate temperature
            temperature = calculate_temperature(rtd);

            // Log temperature
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature. Retrying...\n");
                retry++;
                usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            printf("Temperature: %.2f C\n", temperature);
            break; // Exit retry loop on success
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read temperature after %d retries. Logging error.\n", RETRY_COUNT);
            fprintf(log_file, "Error: Failed to read temperature after %d retries\n", RETRY_COUNT);
            fflush(log_file);
        }

        sleep(5); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

