#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

static volatile int running = 1;

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert to degrees Celsius
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(int temperature) {
    int duty_cycle = 0;

    if (temperature >= 40) {
        duty_cycle = (int)(((float)(temperature - 40) / (70 - 40)) * 255.0);
        if (duty_cycle > 255) {
            duty_cycle = 255;
        }
    } else if (temperature < 40) {
        duty_cycle = 0;
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(int temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %d°C, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
    set_fan_speed(0); // Stop the fan
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    int temperature, duty_cycle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode and PWM frequency
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate PWM duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set fan speed
        set_fan_speed(duty_cycle);

        // Log data
        log_data(temperature, duty_cycle);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_fan_speed(0);
    gpioTerminate();

    return 0;
}

