    var1 = dig_P9 * p * p / 2147483648.0;
    var2 = p * dig_P8 / 32768.0;
    p = p + (var1 + var2 + dig_P7) / 16.0;

    return p;
}

// Log data to file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("weather_data.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Detect BMP280 I2C address
int detect_bmp280_address() {
    int fd = init_i2c(BMP280_ADDR_1);
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize I2C at address 0x76, trying 0x77\n");
        bmp280_address = BMP280_ADDR_2;
        fd = init_i2c(BMP280_ADDR_2);
        if (fd < 0) {
            fprintf(stderr, "Failed to initialize I2C at address 0x77\n");
            return -1;
        }
    }

    uint8_t chip_id;
    if (read_register(fd, BMP280_CHIP_ID_REG, &chip_id) < 0) {
        fprintf(stderr, "Failed to read chip ID\n");
        close(fd);
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        close(fd);
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (detect_bmp280_address() < 0) {
        fprintf(stderr, "Failed to detect BMP280 address. Exiting.\n");
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    bmp280_calib_data calib;
    double temperature, pressure;

    while (!terminate) {
        if (read_calibration_data(i2c_fd, &calib) < 0) {
            fprintf(stderr, "Failed to read calibration data. Continuing.\n");
            sleep(5);
            continue;
        }

        if (read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw data. Continuing.\n");
            sleep(5);
            continue;
        }

        temperature = compensate_temperature(raw_temperature, calib);
        pressure = compensate_pressure(raw_pressure, calib);

        if (log_data(temperature, pressure) < 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);

        sleep(5);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

