#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_handle;
pthread_mutex_t buffer_mutex;
volatile sig_atomic_t terminate = 0;

// Structure for temperature readings
typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

// Circular buffer structure
typedef struct {
    TemperatureReading readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
void *sensor_thread(void *arg);
void signal_handler(int signal);
float read_temperature();
void add_reading(CircularBuffer *buffer, float temperature);
float calculate_average(CircularBuffer *buffer);
void control_led(float temperature);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Add reading to circular buffer
void add_reading(CircularBuffer *buffer, float temperature) {
    time_t now = time(NULL);
    buffer->readings[buffer->head].timestamp = now;
    buffer->readings[buffer->head].temperature = temperature;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate average of readings in circular buffer
float calculate_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->readings[i].temperature;
    }
    return sum / buffer->count;
}

// Read temperature from LM75 sensor
float read_temperature() {
    int raw_temp;
    int result;

    result = i2cReadWordData(i2c_handle, TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    raw_temp = result >> 5; // Extract temperature data
    return (float)raw_temp / 256.0;
}

// Control LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Sensor thread function
void *sensor_thread(void *arg) {
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            add_reading(&circular_buffer, temperature);
            control_led(temperature);
            printf("Temperature: %.2f°C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            gpioSetMode(LED_GPIO, PI_INPUT); // Reset GPIO
            gpioSetMode(LED_GPIO, PI_OUTPUT);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(1000000); // Wait 1 second
            i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C: %s\n", strerror(errno));
                gpioDelay(1000000); // Wait 1 second before retrying
                continue; // Retry reading
            }
        }
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Sleep for 1 second
    }
    pthread_exit(NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn LED off

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer circular_buffer;
    init_circular_buffer(&circular_buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Create sensor thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor thread\n");
        pthread_mutex_destroy(&buffer_mutex);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop (wait for signal)
    pthread_join(sensor_thread_id, NULL);
    pthread_mutex_destroy(&buffer_mutex);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

