void set_pwm_duty_cycle(int duty_cycle);
void signal_handler(int signal);
void log_message(const char *message);

// PID variables
float integral = 0;
float previous_error = 0;

// Function to load configuration from JSON file
int load_config(const char *filename, Config *config) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    config->target_temperature = json_real_value(json_object_get(root, "target_temperature"));
    config->Kp = json_real_value(json_object_get(root, "Kp"));
    config->Ki = json_real_value(json_object_get(root, "Ki"));
    config->Kd = json_real_value(json_object_get(root, "Kd"));
    config->spi_channel = json_integer_value(json_object_get(root, "spi_channel"));
    config->pwm_pin = json_integer_value(json_object_get(root, "pwm_pin"));
    config->spi_handle = json_integer_value(json_object_get(root, "spi_handle"));
    config->pwm_range = json_integer_value(json_object_get(root, "pwm_range"));
    config->pwm_frequency = json_integer_value(json_object_get(root, "pwm_frequency"));
    config->log_interval = json_integer_value(json_object_get(root, "log_interval"));

    json_decref(root);
    return 0;
}

// Function to read temperature from MAX31865
float read_temperature() {
    unsigned char data[5];
    int rtd_code;
    float rtd_resistance;
    float temperature;
    int fault;

    // Read RTD code (registers 0x01 and 0x02)
    data[0] = 0x01; // Read command for RTD MSB
    if (spiXfer(spi_handle, data, data, 1) != 0) {
        log_message("SPI read error for RTD MSB");
        return -273.15; // Return absolute zero on error
    }

    data[0] = 0x02; // Read command for RTD LSB
    if (spiXfer(spi_handle, data, data, 1) != 0) {
        log_message("SPI read error for RTD LSB");
        return -273.15; // Return absolute zero on error
    }

    rtd_code = (data[1] << 8) | data[2];

    // Read fault status (register 0x07)
    data[0] = 0x07; // Read command for fault status
    if (spiXfer(spi_handle, data, data, 1) != 0) {
        log_message("SPI read error for fault status");
        return -273.15; // Return absolute zero on error
    }

    fault = data[1];

    // Check for faults
    if (fault & 0x01) {
        log_message("RTD open circuit");
        return -273.15;
    }
    if (fault & 0x02) {
        log_message("RTD over-voltage");
        return -273.15;
    }
    if (fault & 0x04) {
        log_message("RTD under-voltage");
        return -273.15;
