    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    config->target_temperature = json_real_value(json_object_get(root, "target_temperature"));
    config->Kp = json_real_value(json_object_get(root, "Kp"));
    config->Ki = json_real_value(json_object_get(root, "Ki"));
