#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Global variables
static int i2c_fd = -1;
static FILE *breach_log = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int bmp180_read_calibration_data(int fd);
int bmp180_read_raw_temperature(int fd);
int bmp180_read_raw_pressure(int fd);
float bmp180_calculate_temperature(int32_t ut);
float bmp180_calculate_pressure(int32_t up, int32_t ut);
void log_breach(float temperature, float pressure);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }

    return 0;
}

// Read calibration data from BMP180
int bmp180_read_calibration_data(int fd) {
    ac1 = (i2c_read_reg(fd, BMP180_REG_CAL_AC1) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC1 + 1);
    ac2 = (i2c_read_reg(fd, BMP180_REG_CAL_AC2) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC2 + 1);
    ac3 = (i2c_read_reg(fd, BMP180_REG_CAL_AC3) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC3 + 1);
    ac4 = (i2c_read_reg(fd, BMP180_REG_CAL_AC4) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC4 + 1);
    ac5 = (i2c_read_reg(fd, BMP180_REG_CAL_AC5) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC5 + 1);
    ac6 = (i2c_read_reg(fd, BMP180_REG_CAL_AC6) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC6 + 1);
    b1 = (i2c_read_reg(fd, BMP180_REG_CAL_B1) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_B1 + 1);
    b2 = (i2c_read_reg(fd, BMP180_REG_CAL_B2) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_B2 + 1);
    mb = (i2c_read_reg(fd, BMP180_REG_CAL_MB) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_MB + 1);
    mc = (i2c_read_reg(fd, BMP180_REG_CAL_MC) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_MC + 1);
    md = (i2c_read_reg(fd, BMP180_REG_CAL_MD) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_MD + 1);

    return 0;
}

// Read raw temperature data from BMP180
int bmp180_read_raw_temperature(int fd) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x2E) != 0) {
        return -1;
    }
    usleep(5000); // Wait 4.5ms
    return i2c_read_reg(fd, BMP180_REG_MSB);
}

// Read raw pressure data from BMP180
int bmp180_read_raw_pressure(int fd) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        return -1;
    }
    usleep(2 + (3 << BMP180_OSS)) ; // Wait for conversion

    int msb = i2c_read_reg(fd, BMP180_REG_MSB);
    int lsb = i2c_read_reg(fd, BMP180_REG_LSB);
    int xlsb = i2c_read_reg(fd, BMP180_REG_XLSB);

    if (msb < 0 || lsb < 0 || xlsb < 0) {
        return -1;
    }

    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
}

// Calculate temperature in degrees Celsius
float bmp180_calculate_temperature(int32_t ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Calculate pressure in hPa
float bmp180_calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;

    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    float pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure / 100.0f; // Convert to hPa
}

// Log breach to file
void log_breach(float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(breach_log, "%s - Temperature: %.2f\u00b0C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(breach_log); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (bmp180_read_calibration_data(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Open breach log file
    breach_log = fopen("breach_log.txt", "a");
    if (breach_log == NULL) {
        perror("Failed to open breach log file");
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 sensor... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read raw temperature and pressure
        int32_t ut = bmp180_read_raw_temperature(i2c_fd);
        int32_t up = bmp180_read_raw_pressure(i2c_fd);

        if (ut < 0 || up < 0) {
            fprintf(stderr, "Failed to read raw data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate temperature and pressure
        float temperature = bmp180_calculate_temperature(ut);
        float pressure = bmp180_calculate_pressure(up, ut);

        // Log breach if necessary
        if (temperature > 30.0 || pressure < 950.0) {
            log_breach(temperature, pressure);
        }

