#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define OSS 0

// GPIO pin for fan control
#define FAN_PIN 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int fan_state = 0; // 0 = off, 1 = on
int program_running = 1;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temperature, bmp180_calibration_data_t calibration_data);
float calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration_data);
void add_to_circular_buffer(float temperature, float pressure);
void control_fan(float temperature);
void timer_callback();
void signal_handler(int signal);
void print_buffer();

// Function to read a 16-bit value from the BMP180
int16_t read_int16(int i2c_handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%X\n", reg);
        return 0; // Return 0 on error
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_uint16(int i2c_handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%X\n", reg);
        return 0; // Return 0 on error
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)&calibration_data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }
    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temperature) {
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature conversion command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return -1;
    }

    switch (OSS) {
        case 0: gpioDelay(5000); break; // 4.5ms
        case 1: gpioDelay(8000); break; // 7.5ms
        case 2: gpioDelay(14000); break; // 13.5ms
        case 3: gpioDelay(26000); break; // 25.5ms
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((uint16_t)buf[0] << 16 | (uint16_t)buf[1] << 8 | (uint16_t)buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate true temperature in degrees Celsius
float calculate_temperature(int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long x1 = (((long)raw_temperature - (long)calibration_data.ac6) * (long)calibration_data.ac5) >> 15;
    long x2 = ((long)calibration_data.mc << 11) / (x1 + calibration_data.md);
    long b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate true pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long x1 = (((long)raw_temperature - (long)calibration_data.ac6) * (long)calibration_data.ac5) >> 15;
    long x2 = ((long)calibration_data.mc << 11) / (x1 + calibration_data.md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)calibration_data.b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)calibration_data.ac2 * b6) >> 11;
    long b3 = (((((long)calibration_data.ac1) * 4 + x3) << OSS) + 2) >> 2;

    unsigned long x1_pressure = ((unsigned long)calibration_data.ac3 * b6) >> 13;
    unsigned long x2_pressure = ((unsigned long)calibration_data.b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long x3_pressure = ((x1_pressure + x2_pressure + 2) >> 2);
    unsigned long b4 = ((unsigned long)calibration_data.ac4 * (x3_pressure + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);

    long pressure;
    if (b7 < 0x80000000)
    {
        pressure = (b7 * 2) / b4;
    }
    else
    {
        pressure = (b7 / b4) * 2;
    }

    x1_pressure = (pressure >> 8) * (pressure >> 8);
    x1_pressure = (x1_pressure * 3038) >> 16;
    x2_pressure = (-7357 * pressure) >> 16;
    pressure = pressure + ((x1_pressure + x2_pressure + 3791) >> 4);

    return pressure;
}

// Function to add a new reading to the circular buffer
void add_to_circular_buffer(float temperature, float pressure) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > 30.0f) {
        if (!fan_state) {
            gpioWrite(FAN_PIN, 1); // Turn fan on
            fan_state = 1;
            printf("Fan turned ON\n");
        }
    } else {
        if (fan_state) {
            gpioWrite(FAN_PIN, 0); // Turn fan off
            fan_state = 0;
            printf("Fan turned OFF\n");
        }
    }
}

// Timer callback function
void timer_callback() {
    int raw_temperature, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0 &&
        read_raw_pressure(&raw_pressure) == 0) {

        temperature = calculate_temperature(raw_temperature, calibration_data);
        pressure = calculate_pressure(raw_pressure, raw_temperature, calibration_data);

        printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);

        add_to_circular_buffer(temperature, pressure);
        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data in timer callback\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&circular_buffer[index].timestamp));
        printf("Timestamp: %s, Temperature: %.2f °C, Pressure: %.2f Pa\n", timestamp_str, circular_buffer[index].temperature, circular_buffer[index].pressure);
    }
    printf("--- End of Buffer ---\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin for fan control as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL); // Timer 0, every 500ms

    // Main loop
    while (program_running) {
        print_buffer();
        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

