    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

