    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - 3); // OSS = 3
    return 0;
}

// Function to calculate pressure using the Bosch compensation formula
double calculate_pressure(int raw_temp, int raw_pressure) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    x1 = ((long)raw_temp - ac6) * ac5 / pow(2, 15);
    x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    b5 = x1 + x2;
    b6 = b5 - 4000;
