        last_interrupt_time = current_time;
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    logging_enabled = 0; // Stop logging on exit
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set interrupt handler for falling edge detection
    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Pressure logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int raw_temp, raw_pressure;
            double pressure;

            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                pressure = calculate_pressure(raw_temp, raw_pressure);
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure\n");
                }
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }

            gpioDelay(2000000); // Wait 2 seconds
        }
    }

    return 0;
}

