#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED (BCM numbering)
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM range
#define PWM_RANGE 255

// Global variable to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_millidegrees;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_millidegrees) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp_millidegrees;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, PWM_RANGE - red);   // Invert duty cycle for common anode
    gpioPWM(GREEN_PIN, PWM_RANGE - green); // Invert duty cycle for common anode
    gpioPWM(BLUE_PIN, PWM_RANGE - blue);  // Invert duty cycle for common anode
}

// Function to map temperature to RGB color
void map_temp_to_color(int temp_millidegrees, int *red, int *green, int *blue) {
    if (temp_millidegrees < 40000) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temp_millidegrees >= 40000 && temp_millidegrees <= 59999) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main() {
    int temp_millidegrees;
    int red, green, blue;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range for each pin
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temp_millidegrees = read_cpu_temp();
        if (temp_millidegrees == -1) {
            // Handle temperature read error (skip this cycle)
            sleep(0.5);
            continue;
        }

        // Map temperature to RGB color
        map_temp_to_color(temp_millidegrees, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Print temperature and RGB values
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp_millidegrees, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup: Turn off LED and terminate pigpio
    set_led_color(255, 255, 255); // Turn off common anode LED
    gpioTerminate();

    return 0;
}

