#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <curl/curl.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY 5 // seconds
#define MAX_DATA_LENGTH 64

// Global variables
static volatile int running = 1;
static int terminate_flag = 0;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int checksum;
} DHT22Data;

// Function prototypes
int init_gpio();
DHT22Data read_dht22();
int validate_checksum(const unsigned char *data, int data_len);
int post_data(const DHT22Data *data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    return 0;
}

// Read DHT22 sensor data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    unsigned char raw_data[5] = {0};
    int i, j;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for start signal\n");
            data.temperature = -999.0; // Indicate error
            data.humidity = -999.0;
            data.checksum = -1;
            return data;
        }
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for data signal\n");
            data.temperature = -999.0; // Indicate error
            data.humidity = -999.0;
            data.checksum = -1;
            return data;
        }
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for data signal end\n");
            data.temperature = -999.0; // Indicate error
            data.humidity = -999.0;
            data.checksum = -1;
            return data;
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        unsigned long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for bit start\n");
                data.temperature = -999.0; // Indicate error
                data.humidity = -999.0;
                data.checksum = -1;
                return data;
            }
        }

        start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for bit end\n");
                data.temperature = -999.0; // Indicate error
                data.humidity = -999.0;
                data.checksum = -1;
                return data;
            }
        }

        unsigned long end = gpioTick();
        unsigned long duration = end - start;

        if (duration > 40) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Convert data to temperature and humidity
    data.humidity = (float)(((raw_data[0] << 8) | raw_data[1])) / 10.0;
    data.temperature = (float)(((raw_data[2] << 8) | raw_data[3])) / 10.0;
    if (raw_data[2] & 0x80) {
        data.temperature *= -1.0;
    }
    data.checksum = (int)(((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF));

    return data;
}

// Validate checksum
int validate_checksum(const unsigned char *data, int data_len) {
    unsigned char checksum = 0;
    for (int i = 0; i < data_len - 1; i++) {
        checksum += data[i];
    }
    checksum = 0xFF - checksum;
    if (checksum != data[data_len - 1]) {
        return 0; // Checksum mismatch
    }
    return 1; // Checksum valid
}

// Post data to server
int post_data(const DHT22Data *data) {
    CURL *curl;
    CURLcode res;
    char json_data[MAX_DATA_LENGTH];
    struct curl_slist *headers = NULL;

    // Format JSON payload
    snprintf(json_data, sizeof(json_data), "{\"temperature\": %.2f, \"humidity\": %.2f, \"checksum\": %d}", data->temperature, data->humidity, data->checksum);

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        // Set URL
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);

        // Set POST data
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        // Set content type header
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Perform request
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        // Clean up
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        res = CURLE_FAILED_INIT;
    }

    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (running) {
        DHT22Data data = read_dht22();

        if (data.temperature != -999.0 && data.humidity != -999.0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", data.temperature, data.humidity);
            if (validate_checksum(data.raw_data, 5)) {
                if (post_data(&data) != 0) {
                    fprintf(stderr, "Failed to post data\n");
                }
            } else {
                fprintf(stderr, "Checksum validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }

        sleep(RETRY_DELAY);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

