#define DHT22_GPIO 4
#define DEFAULT_URL "http://your-server.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds

// Structure to hold DHT22 data
typedef struct {
    float humidity;
    float temperature;
} DHT22Data;

// Structure to hold DHT22 sensor data
typedef struct {
    int gpio;
    int initialized;
} DHT22Sensor;

// Global variables
DHT22Sensor sensors[2]; // Assuming a maximum of 2 sensors
char *server_urls[2] = {"http://your-server.com/api/humidity", "http://your-server.com/api/humidity2"};
int num_sensors = 0;
int running = 1;

// Function prototypes
int initialize_gpio();
DHT22Data read_dht22(int gpio);
int validate_checksum(const unsigned char *data, int len);
int post_humidity_data(float humidity, const char *url);
void signal_handler(int signal);
void cleanup();

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // You can process the response here if needed
    return real_size;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to read data from the DHT22 sensor
DHT22Data read_dht22(int gpio) {
    DHT22Data data = {0.0, 0.0};
    unsigned char data_buffer[5] = {0, 0, 0, 0, 0};
    int i, j;
    int retries = 0;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 20-40 us

    gpioSetMode(gpio, PI_INPUT);

    // Read data
    for (i = 0; i < 40; i++) {
        unsigned int start = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - start > 200) { // Timeout after 200 us
                syslog(LOG_ERR, "DHT22: Timeout waiting for data line to go high (bit %d)", i);
                return data; // Return default values on timeout
            }
        }

        start = gpioTick();
        while (gpioRead(gpio) == 1) {
            if (gpioTick() - start > 200) { // Timeout after 200 us
                syslog(LOG_ERR, "DHT22: Timeout waiting for data line to go low (bit %d)", i);
                return data; // Return default values on timeout
            }
        }

        start = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - start > 200) { // Timeout after 200 us
                syslog(LOG_ERR, "DHT22: Timeout waiting for data line to go high (bit %d)", i);
                return data; // Return default values on timeout
            }
        }

        unsigned int pulse_length = gpioTick() - start;
        data_buffer[i / 8] <<= 1;
        if (pulse_length > 40) {
            data_buffer[i / 8] |= 1;
        }
    }

    // Validate checksum
    if (validate_checksum(data_buffer, 4) != 0) {
        syslog(LOG_ERR, "DHT22: Checksum validation failed");
        return data; // Return default values on checksum failure
    }

    // Extract humidity and temperature
    data.humidity = (float)(((data_buffer[0] << 8) | data_buffer[1])) / 10.0;
    data.temperature = (float)(((data_buffer[2] << 8) | data_buffer[3])) / 10.0;
    if (data_buffer[2] & 0x80) {
        data.temperature *= -1;
    }

    return data;
}

// Function to validate the checksum of the DHT22 data
int validate_checksum(const unsigned char *data, int len) {
    unsigned char checksum = 0;
    for (int i = 0; i < len - 1; i++) {
        checksum += data[i];
    }
    checksum = 0xFF - checksum + 1;
    if (checksum != data[len - 1]) {
        return -1;
    }
    return 0;
}

// Function to post humidity data to the server
int post_humidity_data(float humidity, const char *url) {
    CURL *curl;
    CURLcode res;
    char json_data[100];
    int retries = 0;

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

    while (retries < MAX_RETRIES) {
        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            syslog(LOG_INFO, "Humidity data posted successfully to %s", url);
            break; // Exit retry loop on success
        } else {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s, retrying... (url: %s)", curl_easy_strerror(res), url);
            retries++;
            sleep(BACKOFF_DELAY * (1 << retries)); // Exponential backoff
        }
    }

    if (res != CURLE_OK) {
        syslog(LOG_ERR, "Failed to post humidity data after %d retries (url: %s)", MAX_RETRIES, url);
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i].initialized) {
            gpioTerminate();
        }
    }
    syslog(LOG_INFO, "Cleanup complete, exiting.");
    closelog();
}

int main(int argc, char *argv[]) {
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 monitor...");

    // Parse command-line arguments
    if (argc > 1) {
        for (int i = 1; i < argc; i++) {
            if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
                server_urls[0] = argv[i + 1];
                i++;
            } else if (i + 1 < argc) {
                server_urls[num_sensors] = argv[i + 1];
                num_sensors++;
            }
        }
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting.");
        return 1;
    }

    // Initialize sensors
    sensors[0].gpio = DHT22_GPIO;
    sensors[0].initialized = 0;

    sensors[1].gpio = DHT22_GPIO;
    sensors[1].initialized = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (gpioInitialise() < 0) {
            syslog(LOG_ERR, "Failed to initialize pigpio for sensor %d, exiting.", i + 1);
            cleanup();
            return 1;
        }
        sensors[i].initialized = 1;
        syslog(LOG_INFO, "Sensor %d initialized.", i + 1);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        for (int i = 0; i < num_sensors; i++) {
            if (sensors[i].initialized) {
                DHT22Data data = read_dht22(sensors[i].gpio);
                if (data.humidity != 0.0) {
                    syslog(LOG_INFO, "Sensor %d: Humidity = %.2f%%", i + 1, data.humidity);
                    if (post_humidity_data(data.humidity, server_urls[i]) != 0) {
                        syslog(LOG_ERR, "Failed to post humidity data for sensor %d.", i + 1);
                    }
                } else {
                    syslog(LOG_ERR, "Failed to read data from sensor %d.", i + 1);
                }
            }
        }
        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

