#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"

// Global variable to track program state for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_cpu_temp();
int write_fan_speed(int state);
int log_fan_change(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("Received signal %d, shutting down...\n", signal);
        write_fan_speed(0); // Stop the fan
        log_fan_change(0); // Log the shutdown
        exit(0);
    }
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;
    int retries = 3;

    while (retries > 0) {
        fp = fopen(TEMP_FILE, "r");
        if (fp == NULL) {
            perror("Error opening temperature file");
            retries--;
            sleep(1); // Wait before retrying
            continue;
        }

        if (fscanf(fp, "%d", &temp) != 1) {
            fprintf(stderr, "Error reading temperature from file\n");
            fclose(fp);
            retries--;
            sleep(1);
            continue;
        }

        fclose(fp);
        return temp;
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1; // Indicate error
}

// Function to write fan speed to file
int write_fan_speed(int state) {
    FILE *fp;
    int retries = 3;

    while (retries > 0) {
        fp = fopen(FAN_STATE_FILE, "w");
        if (fp == NULL) {
            perror("Error opening fan state file");
            retries--;
            sleep(1);
            continue;
        }

        if (fprintf(fp, "%d", state) < 0) {
            perror("Error writing to fan state file");
            fclose(fp);
            retries--;
            sleep(1);
            continue;
        }

        fclose(fp);
        return 0; // Success
    }

    fprintf(stderr, "Failed to write fan speed after multiple retries.\n");
    return -1; // Indicate error
}

// Function to log fan change to file
int log_fan_change(int state) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Fan speed set to %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, state);

    fclose(fp);
    return 0;
}

int main() {
    int temp, fan_speed;

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in 5 seconds.\n");
        } else {
            fan_speed = 0;
            if (temp < 45000) {
                fan_speed = 0;
            } else if (temp < 55000) {
                fan_speed = 1;
            } else if (temp < 65000) {
                fan_speed = 2;
            } else {
                fan_speed = 3;
            }

            if (write_fan_speed(fan_speed) == 0) {
                if (fan_speed != (write_fan_speed(0) == 0)) {
                    log_fan_change(fan_speed);
                }
            } else {
                fprintf(stderr, "Failed to write fan speed.\n");
            }
        }

        sleep(5);
    }

    return 0;
}

