#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define TARGET_TEMPERATURE 50.0
#define DEFAULT_Kp 1.0
#define DEFAULT_Ki 0.1
#define DEFAULT_Kd 0.01
#define DEFAULT_SPI_SPEED 500000 // 500 kHz
#define DEFAULT_PWM_FREQUENCY 1000 // 1 kHz
#define DEFAULT_LOG_INTERVAL 1 // 1 second

// GPIO Pin Assignments
#define HEATER_PIN 18
#define SPI_CLK_PIN 11
#define SPI_CS_PIN 8 // CE0
#define SPI_DO_PIN 9

// PID Gains
double Kp = DEFAULT_Kp;
double Ki = DEFAULT_Ki;
double Kd = DEFAULT_Kd;

// Global Variables
volatile sig_atomic_t terminate = 0;
int spi_fd;
FILE *log_file;

// PID Variables
double integral = 0.0;
double previous_error = 0.0;

// Function Prototypes
double read_temperature();
double calculate_pid(double current_temperature);
void set_heater_pwm(double pwm_value);
void log_data(double temperature, double pwm_value, double pid_output);
void signal_handler(int signal);
int spi_init();
void spi_close();
int initialize_gpio();
void cleanup();

// Function to read temperature from MAX31855 via SPI
double read_temperature() {
    uint8_t tx_buf[4] = {0, 0, 0, 0}; // Dummy data for reading
    uint8_t rx_buf[4];
    struct spi_ioc_transfer transfer[1];

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 4;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = DEFAULT_SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transaction failed");
        return -273.15; // Return absolute zero on error
    }

    // Parse the received data
    int16_t raw_temp = ((rx_buf[0] << 8) | rx_buf[1]) >> 2;
    if (raw_temp & 0x2000) {
        fprintf(stderr, "Thermocouple fault detected!\n");
        return -273.15; // Indicate an error
    }

    // Extract temperature (bits 31:18) and convert to Celsius
    double temperature = (double)(raw_temp >> 2) * 0.25;
    return temperature;
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = TARGET_TEMPERATURE - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double pwm_value) {
    if (pwm_value < 0.0) pwm_value = 0.0;
    if (pwm_value > 100.0) pwm_value = 100.0;
    gpioPWM(HEATER_PIN, (int)(pwm_value * 255.0 / 100.0)); // pigpio PWM range is 0-255
}

// Function to log data to file
void log_data(double temperature, double pwm_value, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, PWM: %.2f, PID: %.2f\n", timestamp, temperature, pwm_value, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// SPI Initialization
int spi_init() {
    char spi_device[20];
    sprintf(spi_device, "/dev/spidev0.%d", 0); // SPI device file

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = DEFAULT_SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Close
void spi_close() {
    close(spi_fd);
}

// GPIO Initialization
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_PIN, DEFAULT_PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, 255); // Set PWM range to 0-255

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_pwm(0.0); // Turn off heater
    spi_close(); // Close SPI device
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:p:k:i:d:s:l:")) != -1) {
        switch (opt) {
            case 't':
                TARGET_TEMPERATURE = atof(optarg);
                break;
            case 'p':
                Kp = atof(optarg);
                break;
            case 'k':
                Ki = atof(optarg);
                break;
            case 'd':
                Kd = atof(optarg);
                break;
            case 's':
                DEFAULT_SPI_SPEED = atof(optarg);
                break;
            case 'l':
                DEFAULT_LOG_INTERVAL = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t target_temp] [-p Kp] [-k Ki] [-d Kd] [-s spi_speed] [-l log_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize logging
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        spi_close();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();
        if (temperature > -273.0) { // Basic sanity check
            double pid_output = calculate_pid(temperature);
            double pwm_value = pid_output;
            set_heater_pwm(pwm_value);
            log_data(temperature, pwm_value, pid_output);

            // Failsafe checks
            if (temperature > 100.0) {
                fprintf(stderr, "Temperature exceeds failsafe limit: %.2f C\n", temperature);
                set_heater_pwm(0.0);
                log_data(temperature, pwm_value, pid_output);
            } else if (temperature < 0.0) {
                fprintf(stderr, "Temperature below failsafe limit: %.2f C\n", temperature);
                set_heater_pwm(0.0);
                log_data(temperature, pwm_value, pid_output);
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
            log_data(-273.15, pwm_value, pid_output); // Log error temperature
            set_heater_pwm(0.0); // Turn off heater on error
        }

        sleep(DEFAULT_LOG_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

