#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, shutting down...\n", sig);
    gpioPWM(GPIO_PIN, 0); // Turn off the fan
    gpioTerminate();       // Release pigpio resources
    exit(0);
}

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    return (float)temp_milli_celsius / 1000.0;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < 40.0) {
        duty_cycle = 0;
    } else if (temperature > 70.0) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((temperature - 40.0) / (70.0 - 40.0)) * 100.0);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle value: %d\n", duty_cycle);
        return -1; // Indicate error
    }

    int result = gpioPWM(GPIO_PIN, duty_cycle);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %d\n", result);
        return -1; // Indicate error
    }

    return 0;
}

// Function to log data to CSV file
int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1; // Indicate error
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    fclose(fp);
    return 0;
}

int main() {
    float temperature;
    int duty_cycle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Optionally, exit the program if temperature reading consistently fails
            // break; // Exit the loop if temperature reading fails
            continue; // Skip to the next iteration
        }

        // Calculate PWM duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle, exiting.\n");
            break; // Exit the loop if PWM setting fails
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, but continuing.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Turn off the fan and terminate pigpio
    gpioPWM(GPIO_PIN, 0);
    gpioTerminate();

    printf("Fan control stopped.\n");

    return 0;
}

