#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASUREMENT_CMD 0x3608
#define FLOW_RATE_MULTIPLIER 0.01
#define LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
    int retries;
} sensor_t;

// Function prototypes
int init_i2c(sensor_t *sensor);
int read_sensor_data(int handle, int *raw_data);
float convert_to_flow_rate(int raw_data);
int log_data(float flow_rate1, float flow_rate2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (pure function)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C for a sensor
int init_i2c(sensor_t *sensor) {
    sensor->handle = i2cOpen(I2C_BUS, sensor->address, 0);
    if (sensor->handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", sensor->address, sensor->handle);
        return -1;
    }
    return 0;
}

// Function to read data from a sensor with retries
int read_sensor_data(int handle, int *raw_data) {
    char cmd[2] = {(MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF};
    char buffer[3];
    int retries = 0;

    while (retries < SENSOR1_ADDR_MAX_RETRIES) {
        if (i2cWriteDevice(handle, cmd, 2) != 2) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, i2cWriteDevice(handle, cmd, 2));
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        if (i2cReadDevice(handle, buffer, 3) != 3) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, i2cReadDevice(handle, buffer, 3));
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        // CRC validation
        unsigned char crc = crc8(buffer, 2);
        if (crc != buffer[2]) {
            fprintf(stderr, "CRC validation failed (attempt %d)\n", retries + 1);
            return -1; // Indicate CRC failure
        }

        *raw_data = (buffer[0] << 8) | buffer[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", SENSOR1_ADDR_MAX_RETRIES);
    return -1; // Indicate failure after retries
}

// Function to convert raw data to flow rate
float convert_to_flow_rate(int raw_data) {
    return raw_data * FLOW_RATE_MULTIPLIER;
}

// Function to log data to a file
int log_data(float flow_rate1, float flow_rate2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow_rate1, flow_rate2) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Initialize sensors
    sensor_t sensor1 = { .handle = -1, .address = SENSOR1_ADDR, .retries = SENSOR1_ADDR_MAX_RETRIES };
    sensor_t sensor2 = { .handle = -1, .address = SENSOR2_ADDR, .retries = SENSOR2_ADDR_MAX_RETRIES };

    if (init_i2c(&sensor1) != 0 || init_i2c(&sensor2) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_data1, raw_data2;
        float flow_rate1, flow_rate2;

        // Read data from sensor 1
        if (read_sensor_data(sensor1.handle, &raw_data1) == 0) {
            flow_rate1 = convert_to_flow_rate(raw_data1);
        } else {
            flow_rate1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_sensor_data(sensor2.handle, &raw_data2) == 0) {
            flow_rate2 = convert_to_flow_rate(raw_data2);
        } else {
            flow_rate2 = -1.0; // Indicate error
        }

        // Log data
        if (log_data(flow_rate1, flow_rate2) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

