#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-Effect Latch sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
volatile int pulse_count = 0;
volatile int current_state = 0; // 0: A < B, 1: A = B, 2: A > B, 3: Unknown
volatile int last_state = 0;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void handle_gpio_interrupt(int gpio, int level, uint32_t tick, void *user_data);
void log_state(int state);
void cleanup();
void signal_handler(int signal);

// Structure to hold the state machine state and pulse count
typedef struct {
    int state;
    int pulse_count;
} EncoderState;

EncoderState encoder_state = {0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file for writing
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop to monitor the rotary encoder
    while (1) {
        // Read the current state of the GPIO pins
        int current_state_value = gpioRead(SENSOR_A_PIN) ^ gpioRead(SENSOR_B_PIN);

        // Update the current state based on the previous state and the current state value
        if (current_state_value != 0 && current_state_value != last_state) {
            current_state = (current_state_value == 1) ? 1 : 2; // A < B -> 1, A > B -> 2
            last_state = current_state;
        }

        // Increment the pulse count based on the current state
        if (current_state == 1) {
            pulse_count++;
        } else if (current_state == 2) {
            pulse_count--;
        }

        // Log the state change and angular position
        log_state(current_state);

        // Delay to avoid excessive CPU usage
        gpioDelay(1000); // 1 ms delay
    }

    return 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO17 (Sensor A) as an input with pull-up resistor
    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);

    // Configure GPIO18 (Sensor B) as an input with pull-up resistor
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    // Set up interrupt handlers for both GPIO pins
    if (gpioSetISRFuncEx(SENSOR_A_PIN, RISING_EDGE, 0, handle_gpio_interrupt, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Sensor A\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(SENSOR_B_PIN, RISING_EDGE, 0, handle_gpio_interrupt, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Sensor B\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt handler function
void handle_gpio_interrupt(int gpio, int level, uint32_t tick, void *user_data) {
    // This function is called when either Sensor A or Sensor B changes state
    // We need to determine which sensor changed and update the pulse count accordingly
    // and update the current state.

    // Determine which sensor changed
    if (gpio == SENSOR_A_PIN) {
        if (level == 1) {
            // Sensor A went high (rising edge)
            if (gpioRead(SENSOR_B_PIN) == 0) {
                // Sensor A is high and Sensor B is low
                if (current_state == 0) {
                    pulse_count++;
                    current_state = 1;
                } else if (current_state == 1) {
                    // Sensor A is high and Sensor B is high
                    current_state = 2;
                }
            } else {
                // Sensor A is high and Sensor B is high
                current_state = 2;
            }
        } else if (level == 0) {
            // Sensor A went low (falling edge)
            if (gpioRead(SENSOR_B_PIN) == 1) {
                // Sensor A is low and Sensor B is high
                if (current_state == 1) {
                    pulse_count--;
                    current_state = 0;
                } else if (current_state == 2) {
                    // Sensor A is low and Sensor B is low
                    current_state = 3;
                }
            } else {
                // Sensor A is low and Sensor B is low
                current_state = 3;
            }
        }
    } else if (gpio == SENSOR_B_PIN) {
        if (level == 1) {
            // Sensor B went high (rising edge)
            if (gpioRead(SENSOR_A_PIN) == 0) {
                // Sensor B is high and Sensor A is low
                if (current_state == 0) {
                    pulse_count++;
                    current_state = 1;
                } else if (current_state == 1) {
                    // Sensor B is high and Sensor A is high
                    current_state = 2;
                }
            } else {
                // Sensor B is high and Sensor A is high
                current_state = 2;
            }
        } else if (level == 0) {
            // Sensor B went low (falling edge)
            if (gpioRead(SENSOR_A_PIN) == 1) {
                // Sensor B is low and Sensor A is high
                if (current_state == 1) {
                    pulse_count--;
                    current_state = 0;
                } else if (current_state == 2) {
                    // Sensor B is low and Sensor A is low
                    current_state = 3;
                }
            } else {
                // Sensor B is low and Sensor A is low
                current_state = 3;
            }
        }
    }
}

// Function to log the state change and angular position to a file
void log_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Calculate the normalized angular position
    float normalized_angle = (float)pulse_count / 360.0;

    // Log the data to the file
    fprintf(log_file, "%s, State: %d, Angle: %.2f\n", timestamp, state, normalized_angle);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up and exiting...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up...\n", signal);
    cleanup();
    exit(0);
}

