// Structure to pass data to the ISR
typedef struct {
    int gpio;
    int *pulse_count;
} isr_data_t;

// ISR function
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    isr_data_t *data = (isr_data_t *)user;
    if (level == PI_HIGH) {
        pthread_mutex_lock(&mutex);
        (*data->pulse_count)++;
        pthread_mutex_unlock(&mutex);
    }
}

// Calculate RPM
double calculate_rpm(int pulses) {
    return (double)pulses * 60.0; // Revolutions per minute
}

