    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register ISR
    isr_data_t isr_data;
    isr_data.gpio = GPIO_PIN;
    isr_data.pulse_count = &pulse_count;

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter_isr, &isr_data) != 0) {
        fprintf(stderr, "Error setting ISR function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

