    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Calculate RPM
        double rpm = calculate_rpm(pulse_count);

        // Log RPM
        log_rpm(rpm);

        // Reset pulse count
        pulse_count = 0;

        // Wait for 1 second
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

