        return -1;
    }
    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,IR\n");
    }
    return 0;
}

// Function to read data from ADPD144RI
int read_adpd144ri_data(int *red, int *ir) {
    char buf[FIFO_DATA_LEN];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, buf, FIFO_DATA_LEN);

    if (bytes_read != FIFO_DATA_LEN) {
        fprintf(stderr, "Error reading FIFO data: %d\n", bytes_read);
        return -1;
    }

    // Combine the bytes to form 16-bit values
    *red = (int16_t)((buf[1] << 8) | buf[0]);
    *ir = (int16_t)((buf[3] << 8) | buf[2]);

    return 0;
}

