    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int red, ir, led_state = 0; // Initial LED state

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_adpd144ri_data(&red, &ir) == 0) {
            // Process data
            int threshold_exceeded = process_data(red, ir);

            // Control LED
            led_state = !led_state; // Toggle LED state
            control_led(led_state);

            // Log data
            log_data(red, ir);

            // Print data to console (optional)
            printf("Red: %d, IR: %d, LED: %s\n", red, ir, led_state ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    return 0;
}

