#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 17
#define GAIN_CONTROL_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *audio_line;
static struct gpiod_line *gain_line;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_gpio(void);
int set_gpio_direction(int pin, const char *direction);
int set_gpio_value(int pin, int value);
int read_audio_level(void);
int log_audio_event(int level);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return -1;
    }

    audio_line = gpiod_chip_get_line(chip, AUDIO_INPUT_PIN);
    if (!audio_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", AUDIO_INPUT_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_CONTROL_PIN);
    if (!gain_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GAIN_CONTROL_PIN);
        gpiod_line_release(audio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(audio_line, "audio", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", AUDIO_INPUT_PIN, strerror(-ret));
        gpiod_line_release(gain_line);
        gpiod_line_release(audio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(gain_line, "gain", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GAIN_CONTROL_PIN, strerror(-ret));
        gpiod_line_release(audio_line);
        gpiod_line_release(gain_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Set GPIO direction (input or output)
int set_gpio_direction(int pin, const char *direction) {
    int ret;

    ret = gpiod_line_set_direction(audio_line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d direction to %s: %s\n", pin, direction, strerror(-ret));
        return -1;
    }

    ret = gpiod_line_set_direction(gain_line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d direction to %s: %s\n", pin, direction, strerror(-ret));
