#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDRESS 0x36
#define FLOW_LOG_FILE "flow_log.csv"
#define READ_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow rate from the sensor
float read_flow_rate() {
    uint8_t buffer[3];
    int bytes_read;
    int16_t raw_flow;
    uint8_t crc;

    // Read 3 bytes from the sensor
    bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1.0; // Indicate an error
    }

    // Extract raw flow value and CRC
    raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    crc = buffer[2];

    // CRC validation
    uint8_t crc_calculated = crc8(buffer, 2);
    if (crc != crc_calculated) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", crc_calculated, crc);
        return -1.0; // Indicate an error
    }

    // Convert raw flow value to flow rate in uL/min
    float flow_rate = (float)raw_flow / 1000.0;

    return flow_rate;
}

// Function to log flow rate to a file
void log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current timestamp
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open the log file in append mode
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    // Write the timestamp and flow rate to the log file
    fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate);

    // Flush the buffer to ensure data is written to the file
    fflush(log_file);

    // Close the log file
    fclose(log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    char init_command[2] = {0x36, 0x08};
    if (i2cWriteDevice(i2c_handle, init_command, 2) != 2) {
        fprintf(stderr, "Error initializing sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float flow_rate = read_flow_rate();

        if (flow_rate >= 0.0) {
            log_flow_rate(flow_rate);
        } else {
            fprintf(stderr, "Error reading flow rate\n");
        }

        gpioDelay(READ_INTERVAL_MS); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

