#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define SENSOR_REG 0x00
#define TVOC_REG 1
#define ECO2_REG 5
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float calculate_iaq(uint16_t tvoc, uint16_t eco2);
int log_data(float iaq, uint16_t tvoc, uint16_t eco2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C device
int read_sensor_data(sensor_data_t *data) {
    char buf[7];
    int result = i2cReadI2CBlockData(i2c_handle, SENSOR_REG, buf, 7);

    if (result != 7) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->tvoc = (buf[1] << 8) | buf[0];
    data->eco2 = (buf[5] << 8) | buf[4];

    return 0;
}

// Calculate IAQ index
float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0 - (tvoc / 10.0) - ((eco2 - 400.0) / 50.0);
    if (iaq < 0.0) {
        iaq = 0.0;
    } else if (iaq > 100.0) {
        iaq = 100.0;
    }
    return iaq;
}

// Log data to a CSV file
int log_data(float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate IAQ
            float iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);

            // Log data
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);

            printf("IAQ: %.2f, TVOC: %u, eCO2: %u\n", iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

