#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TAMPER_THRESHOLD_SEC 5
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

/* Function to initialize the GPIO line */
int initialize_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    int ret;

    /* Request the GPIO line as input */
    ret = gpiod_line_request(line, "ttp223_tamper", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

/* Function to read the sensor value */
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

/* Function to check for tamper event */
int check_tamper(struct gpiod_line *line, struct timespec *start_time) {
    int value = read_sensor(line);
    if (value < 0) {
        return -1; // Indicate error
    }

    if (value == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, start_time) == -1) {
            fprintf(stderr, "Error getting start time: %s\n", strerror(errno));
            return -1;
        }
        return 0; // Sensor touched
    } else {
        if (clock_gettime(CLOCK_MONOTONIC, start_time) == -1) {
            fprintf(stderr, "Error getting start time: %s\n", strerror(errno));
            return -1;
        }
        return 1; // Sensor released
    }
}

/* Function to handle tamper event */
void handle_tamper(struct gpiod_line *line) {
    struct timespec tamper_start_time;
    if (clock_gettime(CLOCK_MONOTONIC, &tamper_start_time) == -1) {
        fprintf(stderr, "Error getting start time: %s\n", strerror(errno));
        return;
    }

    int tamper_detected = 0;
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    while (!terminate && !tamper_detected) {
        if (check_tamper(line, &tamper_start_time) == 0) {
            tamper_detected = 1;
        } else {
            break; // Exit loop on error or termination signal
        }
        usleep(POLL_INTERVAL_MS * 1000); // Sleep for 100ms
    }

    if (!tamper_detected) {
        printf("Tamper event detected!\n");
    }
}

/* Function to cleanup GPIO resources */
void cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip) {
    if (gpiod_line_release(line) < 0) {
        fprintf(stderr, "Error releasing GPIO line: %s\n", strerror(-gpiod_line_release(line)));
    }
    if (gpiod_chip_close(chip) < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(-gpiod_chip_close(chip)));
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec tamper_start_time, current_time;
    int ret;

    /* Install signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Initialize GPIO line */
    if (initialize_gpio(chip, line) < 0) {
        cleanup_gpio(line, chip);
        return EXIT_FAILURE;
    }

    printf("Tamper detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (check_tamper(line, &tamper_start_time) == 0) {
            handle_tamper(line);
        } else {
            fprintf(stderr, "Error during tamper check. Exiting.\n");
            break;
        }
    }

    /* Cleanup GPIO resources */
    cleanup_gpio(line, chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

