#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 2 // bytes
#define BUFFER_SIZE 1024 // 1 second of audio

// Define GPIO pin for L/R select
#define L_R_SELECT_PIN 17

// Global variables for ALSA and pigpio
snd_pcm_t *pcm_handle;
int running = 1;

// Function prototypes
int init_i2s();
int capture_audio(snd_pcm_t *pcm_handle, int16_t *buffer, int buffer_size);
int write_to_file(const int16_t *buffer, int buffer_size);
void cleanup();
void signal_handler(int signum);

// Structure to hold ALSA configuration
typedef struct {
    snd_pcm_t *pcm_handle;
    snd_pcm_hw_params_t *hw_params;
} alsa_config_t;

alsa_config_t alsa_config;

// Function to initialize I2S
int init_i2s() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(L_R_SELECT_PIN, PI_OUTPUT);
    gpioWrite(L_R_SELECT_PIN, 0); // Initially select left channel

    if (alsa_config.pcm_handle = snd_pcm_open(alsa_config.pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0) < 0) {
        fprintf(stderr, "Cannot open audio device: %s\n", snd_strerror(alsa_config.pcm_handle));
        gpioTerminate();
        return -1;
    }

    if (alsa_config.hw_params = snd_pcm_hw_params_alloca(alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot allocate hardware parameter structure\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    if (snd_pcm_hw_params(alsa_config.hw_params, snd_pcm_hw_params_any, alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot initialize hardware parameter structure\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    if (snd_pcm_hw_params_set_access(alsa_config.hw_params, SND_PCM_ACCESS_RW_INTERLEAVED, alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot set access type\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    if (snd_pcm_hw_params_set_format(alsa_config.hw_params, SND_PCM_FORMAT_S16_LE, alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot set sample format\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    unsigned int val = 0x00000001; // 1 channel
    if (snd_pcm_hw_params_set_channels(alsa_config.hw_params, &val, alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot set channel count\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if (snd_pcm_hw_params_set_rate_near(alsa_config.hw_params, alsa_config.pcm_handle, &rate, 0) < 0) {
        fprintf(stderr, "Cannot set sample rate\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    if (snd_pcm_hw_params(alsa_config.hw_params, snd_pcm_hw_params_set_access, alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot set access type\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    if (snd_pcm_hw_params(alsa_config.hw_params, snd_pcm_hw_params_set_format, alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot set sample format\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    if (snd_pcm_hw_params(alsa_config.hw_params, snd_pcm_hw_params_set_channels, alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot set channel count\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    if (snd_pcm_hw_params(alsa_config.hw_params, snd_pcm_hw_params_set_rate, alsa_config.hw_params) < 0) {
        fprintf(stderr, "Cannot set sample rate\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    if (snd_pcm_hw_params(alsa_config.hw_params, alsa_config.hw_params, alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot set parameters\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    if (snd_pcm_prepare(alsa_config.pcm_handle) < 0) {
        fprintf(stderr, "Cannot prepare audio interface\n");
        snd_pcm_close(alsa_config.pcm_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to capture audio data
int capture_audio(snd_pcm_t *pcm_handle, int16_t *buffer, int buffer_size) {
    int16_t sample;
    int frames = buffer_size / SAMPLE_SIZE;
    int err;

    for (int i = 0; i < frames && running; ++i) {
        err = snd_pcm_readi(pcm_handle, &sample, 1);
        if (err == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "error from read: %s\n", snd_strerror(err));
            return -1;
        } else if (err != 1) {
            fprintf(stderr, "short read, read %d frames\n", err);
        } else {
            buffer[i] = sample;
        }
    }

    return 0;
}

// Function to write audio data to file
int write_to_file(const int16_t *buffer, int buffer_size) {
    FILE *fp = fopen("audio_capture.pcm", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, sizeof(int16_t), buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file, wrote %zu bytes, expected %d\n", bytes_written, buffer_size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up...\n");
    if (alsa_config.pcm_handle) {
        snd_pcm_drain(alsa_config.pcm_handle);
        snd_pcm_close(alsa_config.pcm_handle);
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(L_R_SELECT_PIN, 0); // Deactivate L/R select
        gpioTerminate();
    }
    printf("Cleanup complete.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting...\n");
        running = 0;
    }
}

int main() {
    int16_t audio_buffer[BUFFER_SIZE];
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2S
    if (init_i2s() != 0) {
        fprintf(stderr, "I2S initialization failed\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Capture audio data
        if (capture_audio(alsa_config.pcm_handle, audio_buffer, BUFFER_SIZE) == 0) {
            // Write data to file
            if (write_to_file(audio_buffer, BUFFER_SIZE) != 0) {
                fprintf(stderr, "Error writing to file\n");
            }
        } else {
            fprintf(stderr, "Error capturing audio\n");
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Clean up resources
    cleanup();

    return 0;
}

