            fprintf(stderr, "error from read: %s\n", snd_strerror(err));
            return -1;
        } else if (err != 1) {
            fprintf(stderr, "short read, read %d frames\n", err);
        } else {
            buffer[i] = sample;
        }
    }

    return 0;
}

// Function to write audio data to file
int write_to_file(const int16_t *buffer, int buffer_size) {
    FILE *fp = fopen("audio_capture.pcm", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, sizeof(int16_t), buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file, wrote %zu bytes, expected %d\n", bytes_written, buffer_size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up...\n");
    if (alsa_config.pcm_handle) {
        snd_pcm_drain(alsa_config.pcm_handle);
        snd_pcm_close(alsa_config.pcm_handle);
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(L_R_SELECT_PIN, 0); // Deactivate L/R select
        gpioTerminate();
    }
    printf("Cleanup complete.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting...\n");
        running = 0;
    }
}

int main() {
    int16_t audio_buffer[BUFFER_SIZE];
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2S
    if (init_i2s() != 0) {
        fprintf(stderr, "I2S initialization failed\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Capture audio data
        if (capture_audio(alsa_config.pcm_handle, audio_buffer, BUFFER_SIZE) == 0) {
            // Write data to file
            if (write_to_file(audio_buffer, BUFFER_SIZE) != 0) {
                fprintf(stderr, "Error writing to file\n");
            }
        } else {
            fprintf(stderr, "Error capturing audio\n");
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Clean up resources
    cleanup();

    return 0;
}

