#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency and range
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000

// Define flame detection parameters
#define FLAME_DETECTED 0
#define FLAME_NOT_DETECTED 1
#define DEBOUNCE_MS 50

// Global variables
static volatile int running = 1;
static time_t flame_start_time = 0;
static int flame_detected = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, PWM_RANGE);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return value;
}

// Function to control the cooling fan
void control_fan(int flame_detected) {
    if (flame_detected) {
        // Flame detected
        if (flame_start_time == 0) {
            flame_start_time = time(NULL);
            log_event("Flame detected");
        }
        // Calculate duty cycle based on flame duration (exponential curve)
        double duty_cycle = 80.0 * exp(-0.1 * (time(NULL) - flame_start_time));
        if (duty_cycle > 80.0) duty_cycle = 80.0; // Cap at 80%
        if (duty_cycle < 0.0) duty_cycle = 0.0; // Cap at 0%

        int duty_cycle_int = (int)duty_cycle * 100; // Scale to PWM range
        gpioPWM(FAN_PIN, duty_cycle_int);
        log_event("Fan ON");
    } else {
        // No flame detected
        gpioPWM(FAN_PIN, 0); // Turn fan off
        log_event("Fan OFF");
    }
}

// Function to log events to a file
void log_event(const char *event) {
    FILE *fp = fopen("flame_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("System shutdown");
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    gpioPWM(FAN_PIN, 0); // Turn fan off
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("System started");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == FLAME_DETECTED) {
            flame_detected = 1;
        } else if (sensor_value == FLAME_NOT_DETECTED) {
            flame_detected = 0;
        } else {
            // Error reading sensor, retry after a short delay
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        gpioDelay(DEBOUNCE_MS * 1000); // Debounce delay (in microseconds)

        control_fan(flame_detected);
    }

    return 0;
}

