#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI and GPIO pins
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define GPIO_TRIGGER 23
#define GPIO_READY 24

// Define data structure for frame configuration
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t chirp_count;
    uint32_t sample_count;
    uint32_t frame_period;
} frame_config_t;

// Define data structure for heatmap data
typedef struct {
    uint8_t data[32768]; // Assuming 32x32 range-Doppler heatmap (32768 bytes)
} heatmap_data_t;

// Global variables
int spi_handle;
FILE *log_file;
frame_config_t config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_config(frame_config_t *config);
int spi_transfer(heatmap_data_t *data);
int log_data(heatmap_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_TRIGGER, PI_OUTPUT);
    gpioSetMode(GPIO_READY, PI_INPUT);
    gpioWrite(GPIO_TRIGGER, 0); // Ensure trigger is low initially

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0.0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    log_file = fopen("radar_log.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header to log file
    uint32_t magic_number = 0x52444144;
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    fwrite(&magic_number, sizeof(uint32_t), 1, log_file);
    fwrite(&now, sizeof(time_t), 1, log_file);
    fwrite(&config, sizeof(frame_config_t), 1, log_file);

    return 0;
}

// Read configuration from file (example)
int read_config(frame_config_t *config) {
    // In a real application, this function would read the configuration
    // from a file or a database.
    config->start_frequency = 77; // GHz
    config->end_frequency = 79;   // GHz
    config->chirp_count = 64;
    config->sample_count = 256;
    config->frame_period = 100; // ms
    return 0;
}

// SPI transfer function
int spi_transfer(heatmap_data_t *data) {
    int result = spiXfer(spi_handle, (char *)data, (char *)data, 32768); // Full duplex transfer
    if (result != 32768) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(heatmap_data_t *data) {
    size_t bytes_written = fwrite(data->data, sizeof(uint8_t), 32768, log_file);
    if (bytes_written != 32768) {
        fprintf(stderr, "Failed to write data to log file\n");
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    read_config(&config);

    heatmap_data_t heatmap_data;
    int frame_number = 0;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Trigger data acquisition
        gpioWrite(GPIO_TRIGGER, 1);
        gpioDelay(1); // Small delay
        gpioWrite(GPIO_TRIGGER, 0);

        // Wait for data ready interrupt
        int timeout = 1000; // Timeout after 1 second
        while (gpioRead(GPIO_READY) == 0 && timeout > 0) {
            gpioDelay(1); // Check every 1 ms
            timeout--;
        }

        if (timeout == 0) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            break; // Exit loop if timeout occurs
        }

        // Read heatmap data
        if (spi_transfer(&heatmap_data) != 0) {
            break; // Exit loop if SPI transfer fails
        }

        // Log data
        if (log_data(&heatmap_data) != 0) {
            break; // Exit loop if logging fails
        }

        frame_number++;

        // Print frame number for debugging
        printf("Frame %d\n", frame_number);

        gpioDelay(100); // Delay between frames
    }

    cleanup();
    printf("Data acquisition stopped.\n");
    return 0;
}

