#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 20
#define POLL_INTERVAL_MS 100
#define LOG_FILE "flame_log.txt"

static volatile int keep_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    free(timestamp); // Free the allocated memory
    fclose(fp);
    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_chip *chip, struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to handle state transitions
void handle_state_transition(int state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for log entry.\n");
        return;
    }

    if (state == 0) { // Flame detected (LOW signal)
        if (log_message("Flame detected") != 0) {
            fprintf(stderr, "Failed to log flame detected event.\n");
        }
    } else { // No flame (HIGH signal)
        if (log_message("Flame cleared") != 0) {
            fprintf(stderr, "Failed to log flame cleared event.\n");
        }
    }

    free(timestamp);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int prev_state = -1; // Initialize to an invalid state

    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for input
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Failed to request GPIO line for input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int current_state = read_flame_sensor(chip, line);
        if (current_state < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (current_state != prev_state) {
            handle_state_transition(current_state);
            prev_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000); // Sleep for 100 milliseconds
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    printf("Flame sensor monitoring stopped.\n");

    return 0;
}

