#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define OPT3001_ADDR 0x44
#define OPT3001_REG_RESULT 0x00
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_REG_STATUS 0x02
#define I2C_BUS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t exponent;
    uint16_t mantissa;
    float lux;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
sensor_data_t read_sensor_data();
float calculate_lux(uint16_t exponent, uint16_t mantissa);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    // Continuous conversion mode, 100ms conversion time, automatic full-scale range
    uint16_t config_value = 0x1080; // 0b0001000000000000
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cWriteWordData(i2c_handle, OPT3001_REG_CONFIG, config_value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to config register (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to configure sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int retries = 0;
    uint8_t buffer[2];

    while (retries < MAX_RETRIES) {
        int result = i2cReadI2CBlockData(i2c_handle, OPT3001_REG_RESULT, (char *)buffer, 2);
        if (result == 2) {
            // Success
            data.exponent = (buffer[0] << 8) | buffer[1];
            data.mantissa = (buffer[1] << 8) | buffer[0];
            data.lux = calculate_lux(data.exponent, data.mantissa);
            return data;
        } else {
            fprintf(stderr, "Error reading sensor data (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    data.exponent = 0; // Indicate error
    data.mantissa = 0; // Indicate error
    data.lux = -1.0; // Indicate error
    return data;
}

// Calculate lux value
float calculate_lux(uint16_t exponent, uint16_t mantissa) {
    return 0.01 * 2.0 ** exponent * mantissa;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (data.exponent == 0 && data.mantissa == 0) {
        fprintf(log_file, "%s,ERROR: Sensor read failed\n", timestamp);
        fflush(log_file);
        return -1; // Indicate error
    }

    fprintf(log_file, "%s,Exponent: %d, Mantissa: %d, Lux: %.2f\n", timestamp, data.exponent, data.mantissa, data.lux);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        if (data.exponent != 0) { // Check for valid sensor reading
            log_data(data);
        } else {
            fprintf(stderr, "Error: Invalid sensor reading, skipping log.\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

