#include <time.h>
#include <pigpio.h>
#include <string.h>

#define FLAME_SENSOR_PIN 17
#define POLLING_INTERVAL 1 // seconds

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int gpio_status;
    int flame_detected;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char *flame_status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read the flame sensor value
        flame_detected = gpioRead(FLAME_SENSOR_PIN);

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Determine the correct message based on the sensor value
        if (flame_detected == 0) {
            flame_status = "Flame Detected: YES";
        } else {
            flame_status = "Flame Detected: NO";
        }

        // Log the data to the console
        printf("%s %s\n", timestamp, flame_status);

        // Wait for the next polling interval
        gpioDelay(POLLING_INTERVAL * 1000000); // Convert seconds to microseconds
    }

    // Clean up resources before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");

    return 0;
}

