#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define CHIP_NAME "gpiochip0"
#define CHIP_LINE_FORMAT "gpio%d"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_CHANNELS] = {NULL};
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

int main() {
    int i, ret;
    struct timespec sleep_time = {100, 0}; // 100 milliseconds

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Request and open each line
    for (i = 0; i < NUM_CHANNELS; i++) {
        char line_str[64];
        snprintf(line_str, sizeof(line_str), CHIP_LINE_FORMAT, i);
        lines[i] = gpiod_chip_get_line(chip, line_str);
        if (!lines[i]) {
            fprintf(stderr, "Error opening line %s\n", line_str);
            gpiod_chip_close(chip);
            return 1;
        }

        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %s: %d\n", line_str, ret);
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (keep_running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading line %s: %d\n", CHIP_LINE_FORMAT, value);
                continue; // Continue to the next channel
            }
            printf("Channel %d: %d\n", i, value);
        }
