#define CH6 7
#define CH7 8
#define CH8 9

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Configure GPIO pins as inputs with pull-down resistors
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(CH1 + i, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", CH1 + i);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(CH1 + i, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", CH1 + i);
            gpioTerminate();
            return 1;
        }
    }
    return 0; // Indicate success
}

// Function to read sensor data
int read_sensor_data(int *data) {
    for (int i = 0; i < 8; i++) {
        data[i] = gpioRead(CH1 + i);
    }
    return 0;
}

