    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    int sensor_data[8];

    // Main loop to read and log sensor data
    while (!terminate) {
        read_sensor_data(sensor_data);
        log_sensor_data(sensor_data);
        gpioDelay(100000); // 100 ms delay
    }

    // Terminate pigpio before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
    return 0;
}

