#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

// Define the GPIO pins connected to the touch sensor channels
const int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

// Structure to hold the state of each channel
struct ChannelState {
    int gpio_pin;
    int state;
};

struct ChannelState channel_states[NUM_CHANNELS];

// Function prototypes
int setup_gpio();
int read_channel(int gpio_pin);
void log_data();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Exiting gracefully.\n");
        program_running = 0;
    }
}

// Setup GPIO pins as inputs with pull-down resistors
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        channel_states[i].gpio_pin = gpio_pins[i];
        channel_states[i].state = gpioRead(channel_states[i].gpio_pin); // Initialize state to default (HIGH)
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(channel_states[i].gpio_pin, PI_INPUT);
        gpioSetPullUpDown(channel_states[i].gpio_pin, PI_PUD_DOWN); // Enable pull-down resistor
    }

    return 0; // Indicate success
}

// Read the state of a single channel
int read_channel(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Log the data to the console in CSV format
void log_data() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("%s,%d,%d\n", timestamp, channel_states[i].gpio_pin, channel_states[i].state);
    }
    printf("\n");
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        return 1; // Exit if GPIO setup fails
    }

    printf("Touch sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        log_data();
        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 50ms
    }

    // Clean up GPIO resources before exiting
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(channel_states[i].gpio_pin, PI_INPUT); // Reset to input
        gpioSetPullUpDown(channel_states[i].gpio_pin, PI_PUD_OFF); // Disable pull-down
    }

    gpioTerminate();
    printf("GPIO resources released. Exiting.\n");
    return 0;
}

