#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4 // BCM GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int tilt_state;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 4 as an input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Startup banner
    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the tilt sensor state
        tilt_state = gpioRead(TILT_SENSOR_GPIO);

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log the tilt state with timestamp
        if (tilt_state == 0) {
            printf("%s Tilted\n", timestamp);
        } else {
            printf("%s Not Tilted\n", timestamp);
        }

        // Flush stdout to ensure immediate output
        fflush(stdout);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

