#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define HW_KEY 0x17
#define CHLIST 0x18
#define ALS_FORCE 0x06
#define ALS_VIS_DATA0 0x22
#define ALS_VIS_DATA1 0x23
#define UV_INDEX_DATA0 0x2C
#define UV_INDEX_DATA1 0x2D

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int si1145_read_data(float *uv_index, int *als_visible);
void log_data(float uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, 0x00); // Assuming PART_ID is at register 0x00
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }
    printf("Si1145 PART ID: 0x%02X\n", part_id);

    // Write to HW_KEY register
    if (i2cWriteByteData(i2c_handle, HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing to HW_KEY register\n");
        return -1;
    }

    // Configure CHLIST register
    if (i2cWriteByteData(i2c_handle, CHLIST, 0x01) < 0) {
        fprintf(stderr, "Error writing to CHLIST register\n");
        return -1;
    }

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, ALS_FORCE, 0x01) < 0) {
        fprintf(stderr, "Error writing to ALS_FORCE register\n");
        return -1;
    }

    return 0;
}

// Read UV index and visible ALS data from the sensor
int si1145_read_data(float *uv_index, int *als_visible) {
    int uv_index_raw, als_vis_raw;

    // Read UV index data
    uv_index_raw = i2cReadByteData(i2c_handle, UV_INDEX_DATA0);
    if (uv_index_raw < 0) {
        fprintf(stderr, "Error reading UV_INDEX_DATA0\n");
        return -1;
    }
    uv_index_raw |= (i2cReadByteData(i2c_handle, UV_INDEX_DATA1) << 8);
    if (uv_index_raw < 0) {
        fprintf(stderr, "Error reading UV_INDEX_DATA1\n");
        return -1;
    }

    // Read visible ALS data
    als_vis_raw = i2cReadByteData(i2c_handle, ALS_VIS_DATA0);
    if (als_vis_raw < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0\n");
        return -1;
