#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define FLOW_SCALE_FACTOR 0.036
#define ALARM_GPIO 17
#define ALARM_THRESHOLD 0.5
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, float *flow_rate);
float calculate_average_flow(float flow1, float flow2);
void control_alarm(float average_flow);
void log_data(float flow1, float flow2, float average_flow);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the sensor
int initialize_sensor(int i2c_handle) {
    char buf[2];
    buf[0] = 0x36; // I2C command register
    buf[1] = 0x08; // Start measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to send start measurement command to sensor at address 0x%02X\n", i2c_handle);
        return -1;
    }

    gpioDelay(100); // Wait for 100 ms
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, float *flow_rate) {
    char buf[9];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 9);

    if (bytes_read != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from sensor at address 0x%02X, read %d bytes\n", i2c_handle, bytes_read);
        return -1;
    }

    // Validate CRC for flow rate
    uint8_t flow_data[3] = {buf[0], buf[1], buf[2]};
    uint8_t flow_crc = buf[2];
    uint8_t calculated_crc = crc8(flow_data, 2);

    if (flow_crc != calculated_crc) {
        fprintf(stderr, "Error: CRC check failed for flow rate from sensor at address 0x%02X\n", i2c_handle);
        return -1;
    }

    // Convert raw data to flow rate
    int16_t raw_flow = (buf[0] << 8) | buf[1];
    *flow_rate = (float)raw_flow * FLOW_SCALE_FACTOR;

    return 0;
}

// Function to calculate the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Function to control the alarm
void control_alarm(float average_flow) {
    if (average_flow < ALARM_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    } else {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO low
    }
}

// Function to log data to a file
void log_data(float flow1, float flow2, float average_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min, Average: %.2f ml/min\n",
            timestamp, flow1, flow2, average_flow);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 1 at address 0x%02X\n", SENSOR1_ADDR);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 2 at address 0x%02X\n", SENSOR2_ADDR);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for alarm
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2, average_flow;

    // Main loop
    while (!terminate) {
        // Initialize sensors
        if (initialize_sensor(i2c_handle1) != 0) {
            fprintf(stderr, "Error: Failed to initialize sensor 1\n");
        }
        if (initialize_sensor(i2c_handle2) != 0) {
            fprintf(stderr, "Error: Failed to initialize sensor 2\n");
        }

        // Read data from sensors
        if (read_sensor_data(i2c_handle1, &flow1) == 0) {
            // Validate flow rate
            if (flow1 >= 0.0 && flow1 <= 100.0) {
                average_flow = calculate_average_flow(flow1, flow2);
                log_data(flow1, flow2, average_flow);
                control_alarm(average_flow);
            } else {
                fprintf(stderr, "Warning: Invalid flow rate from sensor 1: %.2f ml/min\n", flow1);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read data from sensor 1\n");
        }

        if (read_sensor_data(i2c_handle2, &flow2) == 0) {
            // Validate flow rate
            if (flow2 >= 0.0 && flow2 <= 100.0) {
                average_flow = calculate_average_flow(flow1, flow2);
                log_data(flow1, flow2, average_flow);
                control_alarm(average_flow);
            } else {
                fprintf(stderr, "Warning: Invalid flow rate from sensor 2: %.2f ml/min\n", flow2);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read data from sensor 2\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();

    return 0;
}

