#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and sensor reading
typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

// Circular buffer
SensorData sensorBuffer[BUFFER_SIZE];
int bufferIndex = 0;

// Function prototypes
int initializeGPIO();
int configureGPIO(int pin, int mode, int pullUpDown);
int readSensor(int pin);
void addToBuffer(time_t timestamp, int reading);
void printBuffer();
void signalHandler(int signal);

// Global variable to track program termination
volatile sig_atomic_t programRunning = 1;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Initialize pigpio
    if (initializeGPIO() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Configure GPIO pin as input with pull-up resistor
    if (configureGPIO(GPIO_PIN, PI_INPUT, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to configure GPIO. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (programRunning) {
        // Read sensor value
        int sensorValue = readSensor(GPIO_PIN);

        // Add data to circular buffer
        if (sensorValue == 0) {
