#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_REG_L 0x2A
#define ACCEL_X_REG_H 0x2B
#define ACCEL_Y_REG_L 0x2C
#define ACCEL_Y_REG_H 0x2D
#define ACCEL_Z_REG_L 0x2E
#define ACCEL_Z_REG_H 0x2F
#define ACCEL_SCALE 0.0009765625 // g/LSB
#define SAMPLE_INTERVAL_MS 500
#define MAX_I2C_RETRIES 3

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int log_data(float x_g, float y_g, float z_g);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to initialize the D7S sensor
int initialize_sensor() {
    int retries = 0;
    while (retries < MAX_I2C_RETRIES) {
        if (i2cWriteByteData(i2c_handle, MODE_CONTROL_REG, 0x10) == 0) {
            // Success
            return 0;
        } else {
            fprintf(stderr, "Failed to write to MODE_CONTROL_REG (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(10); // Wait before retrying
            retries++;
        }
    }
    fprintf(stderr, "Failed to initialize sensor after %d retries\n", MAX_I2C_RETRIES);
    return -1;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int retries = 0;
    while (retries < MAX_I2C_RETRIES) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_X_REG_L, buf, 6) == 6) {
            // Success
            *x = (int16_t)((buf[1] << 8) | buf[0]);
            *y = (int16_t)((buf[3] << 8) | buf[2]);
            *z = (int16_t)((buf[5] << 8) | buf[4]);
            return 0;
        } else {
            fprintf(stderr, "Failed to read sensor data (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(10); // Wait before retrying
            retries++;
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_I2C_RETRIES);
    return -1;
}

// Function to convert raw data to g
float convert_to_g(int16_t raw_value) {
    return raw_value * ACCEL_SCALE;
}

// Function to log data to CSV file
int log_data(float x_g, float y_g, float z_g) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (csv_file == NULL) {
        csv_file = fopen("fan_health.csv", "a");
        if (csv_file == NULL) {
            fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
            return -1;
        }
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
    fflush(csv_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to g
            x_g = convert_to_g(raw_x);
            y_g = convert_to_g(raw_y);
            z_g = convert_to_g(raw_z);

            // Log data
            if (log_data(x_g, y_g, z_g) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

