// Define GPIO pins
#define SENSOR_1_OUT 23
#define SENSOR_2_OUT 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(SENSOR_1_OUT, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_OUT);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR_2_OUT, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_OUT);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read sensor values
int read_sensors(int *sensor1, int *sensor2) {
    *sensor1 = gpioRead(SENSOR_1_OUT);
    *sensor2 = gpioRead(SENSOR_2_OUT);
    return 0;
}

// Function to control the LED
void control_led(int led_state) {
    gpioWrite(LED_PIN, led_state);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    int sensor1_value, sensor2_value;

    // Main loop
    while (program_running) {
        // Read sensor values
        if (read_sensors(&sensor1_value, &sensor2_value) != 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop on error
        }

        // Control the LED based on sensor values
        if (sensor1_value == 0 || sensor2_value == 0) {
            control_led(1); // Turn LED ON if obstacle detected
        } else {
            control_led(0); // Turn LED OFF if no obstacle detected
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    fprintf(stderr, "pigpio terminated successfully.\n");
    return 0;
}

