#include <string.h>
#include <unistd.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_SEC 2

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
    time_t stall_start_time;
} SensorData;

// Global variables
FILE *log_file = NULL;
SensorData current_stall_data = {0, 0, 0};
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int check_stall(SensorData *data);
int log_stall();
void signal_handler(int signal);
void cleanup();

int main() {
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (check_stall(&current_stall_data)) {
            if (log_stall() != 0) {
                fprintf(stderr, "Error logging stall event.\n");
            }
        }

        gpioDelay(100); // Check every 100ms
    }

    cleanup();
    printf("Conveyor belt monitoring stopped.\n");
    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    return 0;
}

