#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x0E
#define CONTINUOUS_MODE_REG 0x09
#define X_REG_L 0x03
#define X_REG_H 0x04
#define Y_REG_L 0x05
#define Y_REG_H 0x06
#define Z_REG_L 0x07
#define Z_REG_H 0x08
#define RANGE_50MT_REG 0x06
#define RANGE_50MT_VALUE 0x00
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VALUE 0x8D

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_mT(int16_t raw_value, float *mT);
void log_data(int16_t x, int16_t y, int16_t z, float x_mT, float y_mT, float z_mT);
void signal_handler(int signal);
int check_device_id();
int write_register(int handle, uint8_t reg, uint8_t value);
int read_register(int handle, uint8_t reg);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    // Configure continuous conversion mode
    if (write_register(i2c_handle, CONTINUOUS_MODE_REG, RANGE_50MT_VALUE) != 0) {
        fprintf(stderr, "Error configuring continuous conversion mode.\n");
        return -1;
    }

    // Verify device ID
    int device_id = check_device_id();
    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X (expected 0x%02X).\n", device_id, DEVICE_ID_VALUE);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, X_REG_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw data to mT
void convert_to_mT(int16_t raw_value, float *mT) {
    // Scale factor for 50 mT range: 1 LSB = 0.1 mT
    *mT = (float)raw_value * 0.1;
}

// Function to log data to CSV file
void log_data(int16_t x, int16_t y, int16_t z, float x_mT, float y_mT, float z_mT) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.1f,%.1f,%.1f\n", timestamp, x, y, z, x_mT, y_mT, z_mT);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to check the device ID
int check_device_id() {
    char buffer[1];
    if (read_register(i2c_handle, DEVICE_ID_REG) != 0) {
        fprintf(stderr, "Error reading device ID.\n");
        return -1;
    }
    buffer[0] = read_register(i2c_handle, DEVICE_ID_REG);
    return buffer[0];
}

// Function to write to a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read from a register
int read_register(int handle, uint8_t reg) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteI2CBlockData(handle, reg, buf, 0) != 0) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadI2CBlockData(handle, reg, buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return buf[0];
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z,X_mT,Y_mT,Z_mT\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    float x_mT, y_mT, z_mT;
    while (!terminate) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            convert_to_mT(x, &x_mT);
            convert_to_mT(y, &y_mT);
            convert_to_mT(z, &z_mT);
            log_data(x, y, z, x_mT, y_mT, z_mT);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

