#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

int read_sensor() {
    int level = gpioRead(GPIO_PIN);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return level;
}

int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value == 1) {
            printf("Water detected!\n");
            if (log_event("Water detected") != 0) {
                fprintf(stderr, "Error logging event\n");
            }
        } else if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, attempting re-initialization...\n");
            gpioTerminate();
            if (initialize_gpio() != 0) {
                fprintf(stderr, "Failed to re-initialize GPIO. Exiting.\n");
                program_running = 0; // Exit the loop if re-initialization fails
            }
            sleep(60); // Wait 60 seconds before next attempt
            continue; // Skip the rest of the loop and try again
        }

        sleep(POLL_INTERVAL_SEC);
    }

    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");
    return 0;
}

