    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value == 1) {
            printf("Water detected!\n");
            if (log_event("Water detected") != 0) {
                fprintf(stderr, "Error logging event\n");
            }
        } else if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, attempting re-initialization...\n");
            gpioTerminate();
            if (initialize_gpio() != 0) {
                fprintf(stderr, "Failed to re-initialize GPIO. Exiting.\n");
                program_running = 0; // Exit the loop if re-initialization fails
            }
            sleep(60); // Wait 60 seconds before next attempt
            continue; // Skip the rest of the loop and try again
        }

        sleep(POLL_INTERVAL_SEC);
    }

    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");
    return 0;
}

