// Global variables
volatile int pulse_count = 0;
volatile int running = 1;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

// Function prototypes
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void *timer_thread(void *arg);
void signal_handler(int signal);
int initialize_gpio();
void cleanup();

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Timer thread function
void *timer_thread(void *arg) {
    (void)arg; // unused

    while (running) {
        // Disable interrupts temporarily
        gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt handler

        // Calculate RPM
        double rpm = (double)pulse_count * 60.0;
        pulse_count = 0; // Reset pulse count

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

