        }

        // Print RPM to stdout
        printf("%s %.2f\n", buf, rpm);

        // Re-enable interrupts
        gpioSetAlertFuncEx(GPIO_PIN, interrupt_handler, NULL); // Re-enable interrupt handler

        // Sleep for 1 second
        sleep(SAMPLE_INTERVAL_SEC);
    }

    return NULL;
}

