    running = 0;

    // Disable interrupts
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt handler

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

