#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the quadrature state machine states
typedef enum {
    Q_STATE_IDLE,
    Q_STATE_A,
    Q_STATE_B,
    Q_STATE_CW,
    Q_STATE_CCW
} quadrature_state_t;

// Global variables
static volatile quadrature_state_t current_state = Q_STATE_IDLE;
static volatile int previous_state = Q_STATE_IDLE;
static volatile int rotation_count = 0;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t rotation_cond = PTHREAD_COND_INITIALIZER;
static FILE *log_file = NULL;

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
quadrature_state_t determine_direction(quadrature_state_t current_state, quadrature_state_t previous_state);
void log_rotation(quadrature_state_t direction);
void signal_handler(int signal);

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    pthread_mutex_lock(&state_mutex);
    current_state = determine_direction(current_state, previous_state);
    previous_state = current_state;
    pthread_mutex_unlock(&state_mutex);

    if (current_state == Q_STATE_CW) {
        rotation_count++;
    } else if (current_state == Q_STATE_CCW) {
        rotation_count--;
    }
    pthread_cond_signal(&rotation_cond);
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    pthread_mutex_lock(&state_mutex);
    current_state = determine_direction(current_state, previous_state);
    previous_state = current_state;
    pthread_mutex_unlock(&state_mutex);

    if (current_state == Q_STATE_CW) {
        rotation_count++;
    } else if (current_state == Q_STATE_CCW) {
        rotation_count--;
    }
    pthread_cond_signal(&rotation_cond);
}

// Function to determine the direction based on the quadrature pattern
quadrature_state_t determine_direction(quadrature_state_t current_state, quadrature_state_t previous_state) {
    if (current_state == Q_STATE_A && previous_state == Q_STATE_IDLE) {
        return Q_STATE_CW;
    } else if (current_state == Q_STATE_B && previous_state == Q_STATE_IDLE) {
        return Q_STATE_CCW;
    } else if (current_state == Q_STATE_C && previous_state == Q_STATE_CW) {
        return Q_STATE_CW;
    } else if (current_state == Q_STATE_D && previous_state == Q_STATE_CCW) {
        return Q_STATE_CCW;
    } else {
        return Q_STATE_IDLE;
    }
}

// Function to log the rotation event to a file
void log_rotation(quadrature_state_t direction) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    sprintf(timestamp + strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    pthread_mutex_lock(&state_mutex);
    pthread_cond_wait(&rotation_cond, &state_mutex);
    pthread_mutex_unlock(&state_mutex);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Rotation: %s\n", timestamp, (direction == Q_STATE_CW) ? "CW" : "CCW");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the sensors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);

    // Set pull-up resistors on the sensor pins
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Set up interrupt service routines for the sensors
    if (gpioSetAlertFunc(SENSOR_A_GPIO, sensor_a_isr) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFunc(SENSOR_B_GPIO, sensor_b_isr) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor B\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    pthread_mutex_lock(&state_mutex);
    pthread_cond_wait(&rotation_cond, &state_mutex);
    pthread_mutex_unlock(&state_mutex);

    while (1) {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

