#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define line names
#define TOUCH_SENSOR_LINE "touch_sensor"
#define LED_LINE "led"

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_touch_sensor(void);
int control_led(int state);
void log_message(int priority, const char *message);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    // Request touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_LINE);
    if (!touch_line) {
        log_message(LOG_ERR, "Failed to get touch sensor line");
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(touch_line, "touch_sensor", 0);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to request touch sensor line");
        cleanup();
        return -1;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        log_message(LOG_ERR, "Failed to get LED line");
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to request LED line");
        cleanup();
        return -1;
    }

    log_message(LOG_INFO, "GPIO initialization complete");
    return 0;
}

// Function to read the touch sensor
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read touch sensor value");
        return -1;
    }
    return value;
}

// Function to control the LED
int control_led(int state) {
    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to set LED value");
        return -1;
    }
    return 0;
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        terminate = 1;
    }
}

// Cleanup function to release resources
void cleanup(void) {
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    log_message(LOG_INFO, "GPIO resources released");
}

int main(void) {
    int touch_detected = 0;
    struct timespec delay;
    delay.tv_sec = 0;
