#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define TOUCH_SENSOR_GPIO 17
#define LED_GPIO 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_chip;
    int led_level;
    int touch_value;
    struct timespec last_touch_time;
    struct timespec current_time;
    double time_diff;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initialize LED to LOW

    // Open GPIO chip
    gpio_chip = 0; // Default chip number
    if (gpioSetChip(gpio_chip) != 0) {
        fprintf(stderr, "Failed to set GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize last touch time
    clock_gettime(CLOCK_MONOTONIC, &last_touch_time);

    fprintf(stderr, "Touch sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read touch sensor value
        touch_value = gpioRead(TOUCH_SENSOR_GPIO);

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Calculate time difference
        time_diff = (current_time.tv_sec - last_touch_time.tv_sec) + (current_time.tv_nsec - last_touch_time.tv_nsec) / 1000000000.0;

        // Debounce: Ignore touch events within 50ms of the last one
        if (time_diff > 0.05) {
            // Toggle LED state
            led_level = (gpioRead(LED_GPIO) == 0) ? 1 : 0;
            gpioWrite(LED_GPIO, led_level);

            // Update last touch time
            last_touch_time = current_time;
        }

        // Small delay to avoid busy-waiting
        usleep(1000); // 1ms
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

