#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure for touch event
typedef struct {
    int sensor_pin;
    long timestamp;
    int state;
} TouchEvent;

// Circular buffer structure
typedef struct {
    TouchEvent buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow;
} CircularBuffer;

// Global variables
CircularBuffer log_buffer;
int running = 1;

// Function prototypes
int init_gpio();
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, long timestamp, int state);
void signal_handler(int signal);
void print_log();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    cb->overflow = 0;
}

// Function to initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        return 1;
    }

    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        return 1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to log touch event
void log_event(int sensor_pin, long timestamp, int state) {
    TouchEvent event;
    event.sensor_pin = sensor_pin;
    event.timestamp = timestamp;
    event.state = state;

    CircularBuffer *cb = &log_buffer;

    if (cb->count == BUFFER_SIZE) {
        cb->overflow = 1;
    } else {
        cb->overflow = 0;
    }

    if (cb->head == cb->tail) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->head = (cb->head + 1) % BUFFER_SIZE;
    }

    cb->buffer[cb->head] = event;

    if (cb->overflow) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    }
    cb->count++;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Turn off LEDs
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    print_log();
    exit(0);
}

// Function to print the log buffer
void print_log() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < log_buffer.count; i++) {
        int index = (log_buffer.tail + i) % BUFFER_SIZE;
        TouchEvent event = log_buffer.buffer[index];
        struct tm *timeinfo = localtime(&event.timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("Sensor: %d, Timestamp: %s, State: %d\n", event.sensor_pin, timestamp_str, event.state);
    }
    printf("--- Log Buffer Overflow: %d\n", log_buffer.overflow);
}

int main() {
    // Initialize circular buffer
    init_circular_buffer(&log_buffer);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor and LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Control LEDs
        control_led(LED_1_PIN, sensor1_value);
        control_led(LED_2_PIN, sensor2_value);

        // Log events
        if (sensor1_value == 1) {
            log_event(SENSOR_1_PIN, time(NULL), 1);
        } else {
            log_event(SENSOR_1_PIN, time(NULL), 0);
        }

        if (sensor2_value == 1) {
            log_event(SENSOR_2_PIN, time(NULL), 1);
        } else {
            log_event(SENSOR_2_PIN, time(NULL), 0);
        }

        // Delay for debounce
        gpioDelay(50); // 50 milliseconds
    }

    return 0;
}

