#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int rain_detected;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *log_file;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as input with pull-up resistor
    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    printf("Raindrop sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the rain sensor
        rain_detected = gpioRead(RAIN_SENSOR_GPIO);

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the event
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        } else {
            if (rain_detected == 0) {
                fprintf(log_file, "%s Rain Detected\n", timestamp);
            } else {
                fprintf(log_file, "%s No Rain\n", timestamp);
            }
            fclose(log_file);
        }

        // Wait 500 milliseconds
        gpioDelay(500000); // pigpio uses microseconds
    }

    // Cleanup
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

