#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define CONFIG_REG 0x30
#define PART_ID_REG 0x00
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *heart_rate, int *spo2);
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Si1182 sensor
int initialize_sensor() {
    // Check if the sensor is present
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Error: Incorrect PART_ID (0x%02x). Expected 0x82.\n", part_id);
        return -1;
    }

    // Configure the sensor for continuous measurement
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONFIG register.\n");
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Reads heart rate and SpO2 data from the sensor
int read_sensor_data(int *heart_rate, int *spo2) {
    int heart_rate_val, spo2_val;

    heart_rate_val = i2cReadWordData(i2c_handle, HEART_RATE_REG);
    if (heart_rate_val < 0) {
        fprintf(stderr, "Error reading heart rate data.\n");
        return -1;
    }
    *heart_rate = heart_rate_val;

    spo2_val = i2cReadWordData(i2c_handle, SPO2_REG);
    if (spo2_val < 0) {
        fprintf(stderr, "Error reading SpO2 data.\n");
        return -1;
    }
    *spo2 = spo2_val;

    return 0;
}

// Logs the heart rate and SpO2 data to a file
int log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);

    return 0;
}

int main() {
    int heart_rate, spo2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&heart_rate, &spo2) == 0) {
            // Log the data
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

