#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define alarm duration (seconds)
#define ALARM_DURATION 5

// Define debounce time (milliseconds)
#define DEBOUNCE_TIME 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type, int sensor_id);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set sensor pins as inputs with pull-down resistors
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Set alarm pin as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    return 0; // Indicate success
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d\n", pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1);
    printf("Alarm activated!\n");
}

// Function to deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
    printf("Alarm deactivated!\n");
}

// Function to log events to file
void log_event(const char *event_type, int sensor_id) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - Sensor %d\n", buf, event_type, sensor_id);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    int sensor1_state = 0;
    int sensor2_state = 0;
    time_t sensor1_tilt_start = 0;
    time_t sensor2_tilt_start = 0;
    time_t sensor1_tilt_end = 0;
    time_t sensor2_tilt_end = 0;

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            cleanup();
            return 1;
        }

        // Check sensor 1
        if (sensor1_value == 1) {
            if (sensor1_state == 0) {
                sensor1_tilt_start = time(NULL);
                sensor1_state = 1;
                log_event("tilt-start", 1);
            } else {
                if (difftime(time(NULL), sensor1_tilt_start) >= 2) {
                    activate_alarm();
                    sensor1_tilt_end = time(NULL);
                    sensor1_state = 0;
                    log_event("threshold-exceeded", 1);
                }
            }
        } else {
            if (sensor1_state == 1) {
                sensor1_tilt_end = time(NULL);
                sensor1_state = 0;
                log_event("tilt-end", 1);
            }
        }

        // Check sensor 2
        if (sensor2_value == 1) {
            if (sensor2_state == 0) {
                sensor2_tilt_start = time(NULL);
                sensor2_state = 1;
                log_event("tilt-start", 2);
            } else {
                if (difftime(time(NULL), sensor2_tilt_start) >= 2) {
                    activate_alarm();
                    sensor2_tilt_end = time(NULL);
                    sensor2_state = 0;
                    log_event("threshold-exceeded", 2);
                }
            }
        } else {
            if (sensor2_state == 1) {
                sensor2_tilt_end = time(NULL);
                sensor2_state = 0;
                log_event("tilt-end", 2);
            }
        }

        gpioDelay(100); // Delay for 100 ms
    }

    cleanup();
    return 0;
}

