#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_LSB_REG 0x28
#define ACCEL_Y_LSB_REG 0x2A
#define ACCEL_Z_LSB_REG 0x2C
#define LED_GPIO 17
#define VIBRATION_THRESHOLD 500
#define LED_ON_DURATION 1000 // milliseconds
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_acceleration_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_vibration_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(float vibration_magnitude);
void control_led(float vibration_magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Omron D7S-A0011 sensor
int initialize_sensor() {
    int result;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00); // Clear power-down bit
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error initializing sensor (attempt %d): %d\n", i + 1, result);
            gpioDelay(10); // Small delay before retrying
        }
    }
    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Reads acceleration data from the sensor
int read_acceleration_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, ACCEL_X_LSB_REG, buffer, 6);
        if (result == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading acceleration data (attempt %d): %d\n", i + 1, result);
            gpioDelay(10); // Small delay before retrying
        }
    }
    fprintf(stderr, "Failed to read acceleration data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Calculates the Euclidean vibration magnitude
float calculate_vibration_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Logs a timestamped event to the log file
void log_event(float vibration_magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, vibration_magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Controls the LED based on the vibration magnitude
void control_led(float vibration_magnitude) {
    if (vibration_magnitude > VIBRATION_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        gpioDelay(LED_ON_DURATION * 1000); // Delay for 1 second
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    int16_t x, y, z;
    float vibration_magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration_data(&x, &y, &z) == 0) {
            // Calculate vibration magnitude
            vibration_magnitude = calculate_vibration_magnitude(x, y, z);

            // Log event if threshold is exceeded
            if (vibration_magnitude > VIBRATION_THRESHOLD) {
                log_event(vibration_magnitude);
                control_led(vibration_magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    return 0;
}

