#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Function prototypes
int read_sensor(int pin);
int control_led(int pin, int value);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nCaught signal %d, cleaning up...\n", sig);
        if (chip != NULL) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpiod_line_get_value(chip, pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value from pin %d\n", pin);
        return -1; // Indicate error
    }
    return (value == 0) ? 1 : 0; // Active-low: 0 means object detected
}

// Function to control the LED
int control_led(int pin, int value) {
    int ret = gpiod_line_set_value(chip, pin, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value on pin %d\n", pin);
        return -1; // Indicate error
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Get line handles for sensor pins
    int sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    int sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    int sensor3_line = gpiod_chip_get_line(chip, SENSOR3_PIN);
    int sensor4_line = gpiod_chip_get_line(chip, SENSOR4_PIN);

    if (!sensor1_line || !sensor2_line || !sensor3_line || !sensor4_line) {
        fprintf(stderr, "Error getting line for sensor pins\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input
    if (gpiod_line_request_input(sensor1_line, "obstacle_sensor", 0) < 0 ||
        gpiod_line_request_input(sensor2_line, "obstacle_sensor", 0) < 0 ||
        gpiod_line_request_input(sensor3_line, "obstacle_sensor", 0) < 0 ||
        gpiod_line_request_input(sensor4_line, "obstacle_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for input\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(LED_PIN, "obstacle_led", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_detected = read_sensor(SENSOR1_PIN);
        int sensor2_detected = read_sensor(SENSOR2_PIN);
        int sensor3_detected = read_sensor(SENSOR3_PIN);
        int sensor4_detected = read_sensor(SENSOR4_PIN);

        if (sensor1_detected < 0 || sensor2_detected < 0 || sensor3_detected < 0 || sensor4_detected < 0) {
            fprintf(stderr, "Error reading sensor, exiting\n");
            break;
        }

        int object_detected = (sensor1_detected || sensor2_detected || sensor3_detected || sensor4_detected);

        if (control_led(LED_PIN, object_detected) < 0) {
            fprintf(stderr, "Error controlling LED, exiting\n");
            break;
        }

        usleep(50000); // 50 ms delay
    }

    // Cleanup
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_line_release(sensor3_line);
    gpiod_line_release(sensor4_line);
    gpiod_line_release(LED_PIN);
    gpiod_chip_close(chip);

    return 0;
}

