// Define the syslog identifier
#define SYSLOG_IDENTIFIER "flame_monitor"

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile sig_atomic_t program_running = 1;
int gpio_lines[5];
int log_fd = -1;
int sensor_ids[5] = {1, 2, 3, 4, 5};

