#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define NUM_CHANNELS 8

// Define GPIO pins for each channel
const int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Function prototypes
int read_channel(struct gpiod_chip *chip, int pin);
void log_event(int channel, int pin, int state);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

// Function to read the state of a single channel
int read_channel(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = NULL;
    int value = -1; // Initialize to an invalid value

    // Open the GPIO line
    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }

    // Read the value from the line
    value = gpiod_line_get_value(line);

    // Close the line
    gpiod_line_release(line);

    return value;
}

// Function to log an event with an ISO-8601 timestamp
void log_event(int channel, int pin, int state) {
    time_t rawtime;
    struct tm *info;
    char buffer[80];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 80, "%Y-%m-%dT%H:%M:%SZ", info);

    if (state == 1) {
        printf("%s Channel %d (GPIO %d): Touch Detected\n", buffer, channel, pin);
    } else {
        printf("%s Channel %d (GPIO %d): Touch Released\n", buffer, channel, pin);
    }
}

int main() {
    int i;

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Main loop to read and log sensor data
    while (1) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int value = read_channel(chip, gpio_pins[i]);
            if (value != -1) {
                log_event(i, gpio_pins[i], value);
            }
        }
        usleep(50000); // 50 milliseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper resource release.
    gpiod_chip_close(chip);
    return 0;
}

