#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_REG 0x04
#define PWM_GPIO 18
#define PWM_FREQ 1000 // Hz
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int configure_sensor();
int read_als();
float convert_to_lux(int raw);
int set_led_brightness(float lux);
int log_data(float lux, int brightness);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    int raw_als;
    float lux;
    int brightness;
} sensor_data_t;

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Configure LED GPIO as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure the VEML7700 sensor
int configure_sensor() {
    uint16_t config_value = 0x0000; // ALS gain 1/8, integration time 100ms
    uint8_t low_byte = (config_value >> 8) & 0xFF;
    uint8_t high_byte = config_value & 0xFF;

    char buf[3];
    buf[0] = 0x00; // Config register address
    buf[1] = low_byte;
    buf[2] = high_byte;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read ambient light data from the VEML7700 sensor
int read_als() {
    char buf[1];
    buf[0] = ALS_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write register address for ALS read: %s\n", strerror(errno));
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %s\n", strerror(errno));
        return -1;
    }

    return (data[0] << 8) | data[1]; // Combine high and low bytes
}

// Function to convert raw ALS data to lux
float convert_to_lux(int raw) {
    return raw * 0.0576;
}

// Function to set the LED brightness using hardware PWM
int set_led_brightness(float lux) {
    int brightness;

    if (lux < 100) {
        brightness = 100;
    } else if (lux < 500) {
        brightness = 75;
    } else if (lux < 1000) {
        brightness = 50;
    } else {
        brightness = 25;
    }

    gpioPWM(PWM_GPIO, brightness);
    return brightness;
}

// Function to log data to a file
