    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, lux, brightness);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int raw_als = read_als();
        if (raw_als < 0) {
            fprintf(stderr, "Failed to read ALS data. Retrying in 1 second.\n");
            log_data(-1, -1); // Log error
            gpioDelay(1000); // Wait 1 second
            continue;
