#include <string.h>

// Define GPIO pins for touch sensors and LED
const int touch_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int led_pin = 17;
const int num_touch_pins = sizeof(touch_pins) / sizeof(touch_pins[0]);

// Debounce time in milliseconds
const int debounce_time = 50;

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensors();
void log_touch_event(int channel);
void control_led(int state);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Configure touch sensor pins as inputs with pull-down resistors
    for (int i = 0; i < num_touch_pins; i++) {
        gpioSetMode(touch_pins[i], PI_INPUT);
        gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN);
    }

    // Configure LED pin as output
    gpioSetMode(led_pin, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read touch sensor values
int read_touch_sensors() {
    int touch_status = 0;
    for (int i = 0; i < num_touch_pins; i++) {
        touch_status |= (gpioRead(touch_pins[i]) << i);
    }
    return touch_status;
}

// Function to log touch events to a file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(led_pin, state);
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Function to perform cleanup before exiting
void cleanup() {
    // Turn off the LED
    control_led(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Security Keypad Simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int current_touch_status = read_touch_sensors();

        // Check each channel for a touch
        for (int i = 0; i < num_touch_pins; i++) {
            if ((current_touch_status >> i) & 1) {
                // Debounce check
                if ((current_touch_status >> i) & 1) { // Check if still touched after debounce time
                    log_touch_event(i + 1);
                    control_led(1); // Turn on LED
                    gpioDelay(debounce_time * 1000); // Debounce delay
                    control_led(0); // Turn off LED
                }
            }
        }
        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    return 0;
}

