    uint16_t config_word_big_endian = ((CONFIG_WORD >> 8) & 0xFF) | ((CONFIG_WORD << 8) & 0xFF00);
    uint8_t data[2];
    data[0] = (config_word_big_endian >> 8) & 0xFF;
    data[1] = config_word_big_endian & 0xFF;

    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, data[0] | (data[1] << 8));
    if (result < 0) {
