    if (result_raw < 0) {
        fprintf(stderr, "Error reading result: %d\n", result_raw);
        return -1;
    }
    *result = (uint16_t)result_raw;
    return 0;
}

// Calculate lux value
float calculate_lux(uint16_t raw_result) {
    int exponent = raw_result >> 12;
    int mantissa = raw_result & 0x0FFF;

