#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 4
#define ALERT_GPIO 17
#define ALERT_DURATION_MS 1000
#define POLL_INTERVAL_MS 500

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int flame_detected;
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_message[100];

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("fire_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read flame sensor
        flame_detected = gpioRead(FLAME_SENSOR_GPIO);

        if (flame_detected == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading flame sensor!\n");
            fprintf(log_file, "Error reading flame sensor!\n");
        } else {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Format log message
            snprintf(log_message, sizeof(log_message), "%s - Flame detected: %d\n", timestamp, flame_detected);

            // Log to file
            fprintf(log_file, "%s", log_message);
            fflush(log_file); // Ensure immediate write

            // Trigger alert
            gpioWrite(ALERT_GPIO, 1);
            gpioDelay(ALERT_DURATION_MS);
            gpioWrite(ALERT_GPIO, 0);

            printf("%s", log_message);
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioWrite(ALERT_GPIO, 0); // Ensure alert GPIO is LOW
    gpioTerminate();

    return 0;
}

