#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define DEBOUNCE_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    keep_running = 0;
}

// Function to initialize the GPIO line
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(*chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(*line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(*chip);
        *line = NULL;
        return -1;
    }

    return 0;
}

// Function to read the GPIO line value
int read_gpio_line(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to log the touch event to a file
int log_touch_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to release GPIO resources
void cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip, FILE *log_file) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio(line, chip, NULL);
        return 1;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int value = read_gpio_line(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line, exiting.\n");
            break;
        }

        if (value == 1) {
            log_touch_event("Touch Detected");
        } else {
            log_touch_event("Touch Released");
        }

        usleep(DEBOUNCE_MS * 1000); // Debounce
    }

    // Cleanup and exit
    cleanup_gpio(line, chip, log_file);
    fprintf(stderr, "Touch sensor monitoring stopped.\n");
    return 0;
}

