#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDRESS 0x08
#define FLOW_COMMAND 0x36
#define FLOW_READ_COMMAND 0x08
#define FLOW_READ_LENGTH 3
#define FLOW_READ_DELAY_MS 2
#define FLOW_READ_RETRY_COUNT 3
#define FLOW_READ_RETRY_DELAY_MS 10
#define FLOW_RATE_SCALE 90.0
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int length);
int validate_crc(uint8_t data[], int length, uint8_t polynomial);
float convert_to_ml_min(int16_t raw_flow);
char* get_status_string(float flow_rate);
int log_data(float flow_rate, int status);
void signal_handler(int signal);

// CRC-8 validation function
int validate_crc(uint8_t data[], int length, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, uint8_t *data, int length) {
    int result = i2cReadDevice(handle, (char *)data, length);
    if (result != length) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw flow value to ml/min
float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE;
}

// Function to get the status string
char* get_status_string(float flow_rate) {
    static char status_string[50]; // Static to preserve across calls
    if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
        strcpy(status_string, "INVALID");
    } else if (flow_rate < 0.0) {
        strcpy(status_string, "ERROR");
    } else {
        strcpy(status_string, "OK");
    }
    return status_string;
}

// Function to log data to a file
int log_data(float flow_rate, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[FLOW_READ_LENGTH];
        int retry = 0;
        int read_result;

        // Send flow rate measurement command
        if (send_command(i2c_handle, FLOW_READ_COMMAND) != 0) {
            fprintf(stderr, "Failed to send flow rate measurement command. Retrying...\n");
            log_data(-1.0, -1); // Log the error
            gpioDelay(FLOW_READ_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue; // Skip to the next iteration
        }

        gpioDelay(FLOW_READ_DELAY_MS * 1000); // Delay for at least 2ms

        // Read sensor data with retry
        while (retry < FLOW_READ_RETRY_COUNT) {
            read_result = read_sensor_data(i2c_handle, data, FLOW_READ_LENGTH);
            if (read_result == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retry + 1, FLOW_READ_RETRY_COUNT);
                log_data(-1.0, -1); // Log the error
                gpioDelay(FLOW_READ_RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry++;
            }
        }

        if (retry == FLOW_READ_RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
            log_data(-1.0, -1); // Log the error
            gpioDelay(FLOW_READ_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue; // Skip to the next iteration
        }

        // Validate CRC
        if (!validate_crc(data, FLOW_READ_LENGTH, 0x31)) {
            fprintf(stderr, "CRC validation failed.\n");
            log_data(-1.0, -1); // Log the error
            gpioDelay(FLOW_READ_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue; // Skip to the next iteration
        }

        // Convert raw flow value to ml/min
        int16_t raw_flow = (data[0] << 8) | data[1];
        float flow_rate = convert_to_ml_min(raw_flow);

        // Get status string
        char *status_string = get_status_string(flow_rate);

        // Log data
        if (log_data(flow_rate, 0) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Print to console for debugging
        printf("Flow Rate: %.2f ml/min, Status: %s\n", flow_rate, status_string);

        gpioDelay(1000000); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

