#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define GPIO_NUMBER 4
#define GPIO_DIRECTION_IN 0
#define GPIO_EDGE_FALLING 0
#define GPIO_LEVEL_LOW 0

static volatile int keep_running = 1;

// Structure to hold chip and line information
struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

// Signal handler for clean exit
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to get the current timestamp
char* get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an event to a file
int log_event(const char *timestamp)
{
    FILE *fp = fopen("flame_events.txt", "a");
    if (fp == NULL) {
        perror("Error opening flame_events.txt");
        return -1;
    }

    fprintf(fp, "%s: Flame detected!\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to handle the falling edge event
void handle_falling_edge(void)
{
    char *timestamp = get_timestamp();
    printf("%s: Flame detected!\n", timestamp);

    if (log_event(timestamp) != 0) {
        fprintf(stderr, "Error logging event.\n");
    }
}

int main()
{
    struct timespec sleep_time = {0, 100000000}; // 100 milliseconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO as an input
    if (gpiod_line_request_input(line, GPIO_EDGE_FALLING, 0) != 0) {
        perror("Error requesting GPIO as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    printf("Monitoring flame sensor... Press Ctrl+C to exit.\n");
    while (keep_running) {
        if (gpiod_line_is_active(line) == 0) {
            handle_falling_edge();
        }
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

