#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIOCHIP "/dev/gpiochip4"
#define TOUCH_PIN 23
#define LED_PIN 24

static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *led_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nSignal received, exiting gracefully...\n");
}

// Function to initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return -1;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch line %d\n", TOUCH_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d\n", LED_PIN);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting touch line as input\n");
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to log touch events with ISO-8601 timestamp
int log_touch_event(int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, led_state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to toggle the LED state
int toggle_led() {
    int current_state = gpiod_line_get_value(led_line);
    int new_state = !current_state;
    if (gpiod_line_set_value(led_line, new_state) < 0) {
        fprintf(stderr, "Error setting LED value\n");
        return -1;
    }
    return new_state;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    fprintf(stdout, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int led_state = gpiod_line_get_value(led_line);
        int new_led_state = toggle_led();
        if (new_led_state < 0) {
            break; // Exit loop on error
        }

        log_touch_event(new_led_state);

        // Wait for touch event with timeout
        int ret = gpiod_line_event_wait(touch_line, 1, 1000); // 1 second timeout
        if (ret < 0) {
            fprintf(stderr, "Error waiting for touch event: %s\n", strerror(errno));
            break; // Exit loop on error
        } else if (ret == 0) {
            // Timeout occurred, no touch event
            continue; // Skip to the next iteration
        }

        // Touch event occurred
        usleep(50000); // Debounce delay (50ms)
    }

    // Cleanup and exit
    fprintf(stdout, "Cleaning up and exiting...\n");
    cleanup_gpio();
    return 0;
}

