#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define GPIO chip name
#define GPIO_CHIP_NAME "gpiochip0"

// Define log file path
#define LOG_FILE "alert_log.txt"

// Define flame detection threshold (adjust as needed)
#define FLAME_DETECTED 0 // Active-low: LOW indicates flame

// Define buzzer activation duration (in seconds)
#define BUZZER_DURATION 2

// Define polling interval (in milliseconds)
#define POLL_INTERVAL 500

// Global variables
static volatile int keep_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;

// Function prototypes
int log_event(const char *message);
int read_flame_sensor(struct gpiod_line *line);
int activate_buzzer(struct gpiod_line *line, int duration_ms);
void signal_handler(int sig);
int setup_gpio(void);
int cleanup_gpio(void);
int setup_logging(void);
int cleanup_logging(void);

// Function to log events with timestamps
int log_event(const char *message) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
        return -1; // Failure
    }
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the buzzer for a specified duration
int activate_buzzer(struct gpiod_line *line, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer HIGH: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting buzzer LOW: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return 0; // Success
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        keep_running = 0;
    }
}

// Function to set up GPIO pins
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        gpiod_line_release(buzzer_line);
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer") < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to clean up GPIO pins
int cleanup_gpio(void) {
