#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_MS 200

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log the touch event with timestamp
int log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Touch detected\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

// Function to toggle the LED
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_level);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 0; // 0 = released, 1 = touched
    unsigned long last_touch_time = 0;

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_touch_state = gpioRead(TOUCH_PIN);

        if (current_touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            unsigned long current_time = gpioTick();

            // Debounce check
            if (current_time - last_touch_time > DEBOUNCE_MS * 1000) {
                log_touch_event();
                toggle_led();
                last_touch_state = 1;
                last_touch_time = current_time;
            }
        } else if (current_touch_state == 0 && last_touch_state == 1) {
            last_touch_state = 0;
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

