        return -1;
    }

    result = gpioSetPullUpDown(pin, PI_PUD_UP);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d pull-up: %d\n", pin, result);
        return -1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log a state change to a file
void log_state_change(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen("magnet_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s - Sensor %d: %d\n", timestamp, sensor_id, state);
    fclose(fp);
}

