#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define LED_CURRENT_VALUE 0x3F
#define AVERAGING_REG 0x04
#define AVERAGING_VALUE 0x0A
#define ENABLE_REG 0x01
#define ENABLE_VALUE 0x01
#define HEART_RATE_REG 0x2A
#define BPM_MULTIPLIER 0.5
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for moving average filter
typedef struct {
    int buffer[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
int initialize_i2c();
int initialize_sensor();
int configure_sensor();
int read_heart_rate();
double apply_moving_average(int raw_bpm);
int validate_bpm(double bpm);
int log_data(double bpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the Si1182-A-GM sensor
int initialize_sensor() {
    int part_id, hw_rev;

    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV register: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X\n", hw_rev);
        return -1;
    }

    return 0;
}

// Configure the Si1182-A-GM sensor
int configure_sensor() {
    int status;

    // Configure LED current
    status = i2cWriteByteData(i2c_handle, LED_CURRENT_REG, LED_CURRENT_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing to LED_CURRENT register: %d\n", status);
        return -1;
    }

    // Configure averaging
    status = i2cWriteByteData(i2c_handle, AVERAGING_REG, AVERAGING_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing to AVERAGING register: %d\n", status);
        return -1;
