    for (int i = 0; i < NUM_CHANNELS; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!counter_lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", counter_pins[i], strerror(errno));
            goto cleanup;
        }

        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        ret = gpiod_line_request(counter_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    return 0;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (touch_lines[i]) {
            gpiod_line_release(touch_lines[i]);
        }
        if (counter_lines[i]) {
            gpiod_line_release(counter_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return -1;
}

// Function to read touch sensor values
int read_touch_sensors(void) {
    int ret;
    struct gpiod_line_request_config config;
    struct timespec delay = {0, 10000000}; // 10ms

    for (int i = 0; i < NUM_CHANNELS; i++) {
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        ret = gpiod_line_request(touch_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input for reading: %s\n", touch_pins[i], strerror(errno));
            continue; // Skip to the next channel
        }

        int value = gpiod_line_get_value(touch_lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", touch_pins[i], strerror(errno));
            continue; // Skip to the next channel
        }

        // Debouncing and edge detection
        if (value != touch_lines[i]->direction) {
            touch_lines[i]->direction = value;
        }
    }
    nanosleep(&delay, NULL);
    return 0;
}

// Function to update the counter display
void update_counter_display(int counter_value) {
    int bit_index = counter_value % NUM_CHANNELS;
    int pin_index = 17 + bit_index;

    int value = (counter_value > 127) ? 1 : 0; // Convert 8-bit to 8-bit binary
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = pin_index + i;
        int line = counter_lines[i];
        int ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Error setting line %d: %s\n", pin, strerror(errno));
        }
    }
}

// Function to log touch events
void log_touch_event(int channel, int counter_value) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
    fclose(fp);

    printf("Touch on channel %d | Counter: %d\n", channel, counter_value);
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    int ret;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (touch_lines[i]) {
            gpiod_line_release(touch_lines[i]);
        }
        if (counter_lines[i]) {
            gpiod_line_release(counter_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Stabilization delay
    sleep(2);

    // Main loop
    while (running) {
        if (read_touch_sensors() < 0) {
            fprintf(stderr, "Error reading touch sensors, exiting.\n");
            cleanup_gpio();
            return 1;
        }

        int new_counter_value = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(touch_lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading line %d, skipping.\n", touch_pins[i]);
                continue; // Skip to the next channel
            }

            if (value == 1) {
                new_counter_value += 1;
                if (new_counter_value >= 256) {
                    new_counter_value = 0;
                }
            }
        }

        update_counter_display(new_counter_value);
        log_touch_event(new_counter_value, new_counter_value);

        nanosleep(&delay, NULL);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

