    sensor1_line = gpiod_line_request_input(chip, SENSOR1_PIN, "sensor1");
    if (!sensor1_line) {
        fprintf(stderr, "Error requesting sensor1 line: %s\n", strerror(errno));
        goto cleanup;
    }

