    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        sensor1 = read_sensor(sensor1_line);
        sensor2 = read_sensor(sensor2_line);
        sensor3 = read_sensor(sensor3_line);
        sensor4 = read_sensor(sensor4_line);

        // Get the current timestamp
        current_time = time(NULL);

        // Log the data
        if (sensor1 == -1 || sensor2 == -1 || sensor3 == -1 || sensor4 == -1) {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        } else {
            if (log_data(current_time, sensor1, sensor2, sensor3, sensor4) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        // Wait for 100 milliseconds
        usleep(100000); // 100 ms
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

