#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LOG_FILE "/var/log/tilt_events.log"

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_line *line;
    int number;
    int chip;
} gpio_line_t;

// Global variables
static struct gpiod_chip *chip = NULL;
static gpio_line_t lines[2];
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int request_gpio_line(struct gpiod_chip *chip, int number, int consumer);
int configure_gpio_line(struct gpiod_line *line, int active_low, int pull_up);
int read_gpio_line(struct gpiod_line *line);
int log_event(int sensor_number);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize GPIO chip
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return -1;
    }

    return 0;
}

// Request a GPIO line
int request_gpio_line(struct gpiod_chip *chip, int number, int consumer) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = consumer;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_chip_request_line(chip, number, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", number, strerror(-ret));
        return -1;
    }
    return 0;
}

// Configure GPIO line
int configure_gpio_line(struct gpiod_line *line, int active_low, int pull_up) {
    int ret = gpiod_line_set_active_low(line, active_low);
    if (ret < 0) {
        fprintf(stderr, "Error setting active low for GPIO line %d: %s\n", line->number, strerror(-ret));
        return -1;
    }

    ret = gpiod_line_set_pull_up(line, pull_up ? 1 : 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting pull-up for GPIO line %d: %s\n", line->number, strerror(-ret));
        return -1;
    }

    return 0;
}

// Read GPIO line value
int read_gpio_line(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", line->number, strerror(-value));
        return -1;
    }
    return value;
}

// Log event to file
int log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
    fflush(log_file); // Ensure immediate write to disk

    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Release GPIO lines
    for (int i = 0; i < 2; i++) {
        if (lines[i].line) {
            gpiod_line_release(lines[i].line);
        }
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request and configure GPIO lines
    lines[0].number = 17;
    lines[0].chip = CHIP_NAME;
    if (request_gpio_line(chip, lines[0].number, 0) < 0) {
        cleanup();
        return 1;
    }
    if (configure_gpio_line(lines[0].line, 0, 1) < 0) {
        cleanup();
        return 1;
    }

    lines[1].number = 18;
    lines[1].chip = CHIP_NAME;
    if (request_gpio_line(chip, lines[1].number, 0) < 0) {
        cleanup();
        return 1;
    }
    if (configure_gpio_line(lines[1].line, 0, 1) < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 2; i++) {
            int value = read_gpio_line(lines[i].line);
            if (value < 0) {
                fprintf(stderr, "Error reading line %d, skipping...\n", lines[i].number);
                continue; // Skip to the next sensor
            }

            if (value == 0) { // Active low
                log_event(i + 1);
                // Debounce
                struct timespec delay = {0, 50000000}; // 50ms
                nanosleep(&delay, NULL);
            }
        }
        usleep(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

