    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
    fflush(log_file); // Ensure immediate write to disk

    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Release GPIO lines
    for (int i = 0; i < 2; i++) {
        if (lines[i].line) {
            gpiod_line_release(lines[i].line);
        }
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request and configure GPIO lines
    lines[0].number = 17;
    lines[0].chip = CHIP_NAME;
    if (request_gpio_line(chip, lines[0].number, 0) < 0) {
        cleanup();
        return 1;
    }
    if (configure_gpio_line(lines[0].line, 0, 1) < 0) {
        cleanup();
        return 1;
    }

    lines[1].number = 18;
    lines[1].chip = CHIP_NAME;
    if (request_gpio_line(chip, lines[1].number, 0) < 0) {
        cleanup();
        return 1;
    }
    if (configure_gpio_line(lines[1].line, 0, 1) < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 2; i++) {
            int value = read_gpio_line(lines[i].line);
            if (value < 0) {
                fprintf(stderr, "Error reading line %d, skipping...\n", lines[i].number);
                continue; // Skip to the next sensor
            }

            if (value == 0) { // Active low
                log_event(i + 1);
                // Debounce
                struct timespec delay = {0, 50000000}; // 50ms
                nanosleep(&delay, NULL);
            }
        }
        usleep(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

