#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling period (microseconds)
#define SAMPLE_PERIOD 125

// Define LED on time (milliseconds)
#define LED_ON_TIME 100

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping program...\n", signal);
}

// Function to read the microphone input
int read_microphone() {
    return gpioRead(MIC_PIN);
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Function to log the timestamp
void log_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    sprintf(timestamp + strlen(timestamp), ".%09ld", ts.tv_nsec);
    printf("%s\n", timestamp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    gpioSetMode(MIC_PIN, PI_INPUT);

    // Set GPIO17 as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read microphone input
        int mic_value = read_microphone();

        // Check for peak detection (HIGH signal)
        if (mic_value == 1) {
            // Log timestamp
            log_timestamp();

            // Turn LED on
            control_led(1);

            // Wait for LED on time
            gpioDelay(LED_ON_TIME * 1000); // Convert milliseconds to microseconds

            // Turn LED off
            control_led(0);
        }

        // Delay for the sampling period
        gpioDelay(SAMPLE_PERIOD);
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

