#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define LEFT_PIN 17
#define CENTER_PIN 27
#define RIGHT_PIN 22

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variable to store the GPIO line handle
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *center_line = NULL;
static struct gpiod_line *right_line = NULL;

// Function prototypes
int initialize_gpio(int pin);
int read_sensor(int pin);
void cleanup_gpio();
void signal_handler(int signum);

// Structure to hold sensor data
typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

// Function to initialize a GPIO pin
int initialize_gpio(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "sensor-reader";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return line;
}

// Function to read the state of a sensor
int read_sensor(int pin) {
    struct gpiod_line *line = (pin == LEFT_PIN) ? left_line :
                                (pin == CENTER_PIN) ? center_line :
                                (pin == RIGHT_PIN) ? right_line : NULL;

    if (!line) {
        fprintf(stderr, "Error: Invalid GPIO pin for reading.\n");
        return -1; // Indicate an error
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO line");
        return -1; // Indicate an error
    }

    return value;
}

// Function to clean up GPIO resources
