#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SI1175_ADDR 0x49

// Define the register addresses for ALS visible data
#define ALS_VIS_DATA_LSB 0x24
#define ALS_VIS_DATA_MSB 0x25

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int i2c_init(int bus, int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a register from the Si1175
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    uint8_t buf[1];
    if (read(fd, buf, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return buf[0];
}

// Function to read the ALS visible data registers
int read_als_data(int fd, uint16_t *lsb, uint16_t *msb) {
    *lsb = read_register(fd, ALS_VIS_DATA_LSB);
    if (*lsb < 0) return -1;
    *msb = read_register(fd, ALS_VIS_DATA_MSB);
    if (*msb < 0) return -1;
    return 0;
}

// Function to log the sensor data
void log_data(uint16_t lsb, uint16_t msb) {
    printf("LSB: %u, MSB: %u\n", lsb, msb);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = i2c_init(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    printf("Si1175 sensor reading started. Press Ctrl+C to exit.\n");

    // Main loop to read and log the sensor data
    while (1) {
        uint16_t lsb, msb;

        if (read_als_data(i2c_fd, &lsb, &msb) == 0) {
            log_data(lsb, msb);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        usleep(100000); // 100 ms delay
    }

    return 0;
}

