    left_line = gpiod_chip_get_line(chip, GPIOLEFT);
    if (!left_line) {
        perror("Error getting left line");
        gpiod_chip_close(chip);
        return 1;
    }

    middle_line = gpiod_chip_get_line(chip, GIMIDDLE);
    if (!middle_line) {
        perror("Error getting middle line");
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return 1;
    }

    right_line = gpiod_chip_get_line(chip, GORIGHT);
    if (!right_line) {
        perror("Error getting right line");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines as input
    if (gpiod_line_request_input(left_line, "sensor") < 0) {
        perror("Error requesting left line as input");
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(middle_line, "sensor") < 0) {
        perror("Error requesting middle line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(right_line, "sensor") < 0) {
        perror("Error requesting right line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor values
        left_val = gpiod_line_get_value(left_line);
        middle_val = gpiod_line_get_value(middle_line);
        right_val = gpiod_line_get_value(right_line);

        // Log sensor values
        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);

        // Sleep for 100 milliseconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }
    }

    return 0;
}

