#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8

// GPIO pins for the TTP226 channels
int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read the state of a single GPIO pin
int read_gpio(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the state of all channels
void log_channel_states(int channel_states) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("[%s] ", buf);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (channel_states & (1 << i)) {
            printf("CH%d=1 ", i + 1);
        } else {
            printf("CH%d=0 ", i + 1);
        }
    }
    printf("\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO pins as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(gpio_pins[i], PI_INPUT);
    }

    // Main loop to read and log channel states
    while (!terminate) {
        int channel_states = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = read_gpio(gpio_pins[i]);
            if (value < 0) {
                // Error reading GPIO, exit the loop
                break;
            }
            channel_states |= (value << i);
        }

        log_channel_states(channel_states);
        gpioDelay(200); // Delay for 200 milliseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

