#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

// TCS34725 I2C address
#define TCS34725_ADDR 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// GPIO pin for LED
#define LED_PIN 17

// Red threshold for LED control
#define RED_THRESHOLD 200

// I2C file descriptor
int i2c_fd;

// Function prototypes
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void signal_handler(int signal);

// Signal handler for clean exit
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd >= 0) {
        // Power down the sensor (optional, but good practice)
        uint8_t data[2];
        data[0] = TCS34725_ENABLE;
        data[1] = 0x00; // Power down
        if (write(i2c_fd, data, 2) != 2) {
            perror("Failed to power down sensor");
        }
    }
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioSetMode(LED_PIN, PI_INPUT); // Release GPIO
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

// Initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    uint8_t data[2];

    // Enable power and RGBC
    data[0] = TCS34725_ENABLE;
    data[1] = 0x03; // PON | AEN
    if (write(fd, data, 2) != 2) {
        perror("Failed to enable sensor");
        return -1;
    }

    // Set integration time (ATIME)
    data[0] = TCS34725_ATIME;
    data[1] = 0x00; // 154ms integration time
    if (write(fd, data, 2) != 2) {
        perror("Failed to set integration time");
        return -1;
    }

    // Set gain (CONTROL)
    data[0] = TCS34725_CONTROL;
    data[1] = 0x00; // 1x gain
    if (write(fd, data, 2) != 2) {
        perror("Failed to set gain");
        return -1;
    }

    // Verify sensor ID
    uint8_t id;
    if (read(fd, &id, 1) != 1) {
        perror("Failed to read sensor ID");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    printf("TCS34725 sensor initialized successfully.\n");
    return 0;
}

// Read color data from the TCS34725 sensor
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];

    // Read all 8 bytes in one go
    if (read(fd, data, 8) != 8) {
        perror("Failed to read color data");
        return -1;
    }

    // Extract clear, red, green, and blue values
    *clear = (data[1] << 8) | data[0];
    *red = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue = (data[7] << 8) | data[6];

    return 0;
}

int main() {
    // Register signal handler for clean exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    uint16_t clear, red, green, blue;

    // Main loop
    while (1) {
        // Read color data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Apply calibration (gain and offset)
            red = red * 1.5; // Example calibration
            green = green * 1.5; // Example calibration
            blue = blue * 1.5; // Example calibration

            // Display calibrated values
            printf("Clear: %5d, Red: %5d, Green: %5d, Blue: %5d\n", clear, red, green, blue);

            // Control LED based on red value
            gpioWrite(LED_PIN, (red > RED_THRESHOLD) ? 1 : 0);
        } else {
            fprintf(stderr, "Failed to read color data, attempting re-initialization...\n");
            // Attempt to re-initialize the sensor
            if (tcs34725_init(i2c_fd) != 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                // Handle the error appropriately, e.g., exit or attempt a different sensor
            }
        }

        // Wait 200ms
        gpioDelay(200000); // 200ms
    }

    return 0;
}

