    if (handle < 0) {
        fprintf(stderr, "I2C initialisation failed for address 0x%02x: %d\n", i2c_address, handle);
        return -1;
    }
    return handle;
}

// Function to read data from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char cmd[1] = {0x21}; // One-Time High-Resolution Mode 2
    char data[2];

    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "I2C write failed for sensor 0x%02x\n", i2c_handle);
        return -1;
