// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize VEML7700 sensor
int init_veml7700() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, CONFIG_REG, CONFIG_VALUE) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to config register, retrying...\n");
            gpioDelay(100); // 100 ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize VEML7700 after multiple retries.\n");
    return -1; // Failure
}

// Read ALS data from VEML7700
int read_veml7700(int *raw_value) {
    int retries = 3;
    while (retries > 0) {
        if (i2cReadWordData(i2c_handle, ALS_DATA_REG) >= 0) {
            *raw_value = i2cReadWordData(i2c_handle, ALS_DATA_REG);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading ALS data, retrying...\n");
            gpioDelay(100); // 100 ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
    return -1; // Failure
}

// Convert raw ALS data to lux
float convert_to_lux(int raw_value) {
    return raw_value * 0.0036 * (1.0 / 8.0) * (100.0 / 100.0); // Simplified conversion
}

// Apply gamma correction to lux value
int gamma_correct(float lux) {
    float brightness_float = lux / MAX_LUX;
    float brightness_gamma = 255.0 * pow(brightness_float, 1.0 / 2.2);
    return (int)brightness_gamma;
}

// Set LED brightness using bit-banging
int set_led_brightness(int brightness) {
    if (brightness < THRESHOLD_BRIGHTNESS) {
        gpioWrite(GPIO_PIN, 0); // Turn off LED
        return threshold_control(brightness);
    } else {
        // Bit-banging implementation
        int num_bytes = 3; // Number of bytes for 24-bit color (8 bits per color * 3 colors)
        int num_bits = 24; // Number of bits for 24-bit color
        int bit_index = 0;
        int byte_index = 0;
        int bit_mask = 1 << bit_index;
        int byte_mask = 1 << byte_index;

        while (bit_index < num_bits) {
            int pulse_width = (int)(brightness * (BITRATE / 255.0));
            if (pulse_width > 0) {
                gpioWrite(GPIO_PIN, 1);
                gpioDelay(pulse_width);
                gpioWrite(GPIO_PIN, 0);
                gpioDelay(1000 / BITRATE); // Ensure pulse width is accurate
            } else {
                gpioWrite(GPIO_PIN, 0);
                gpioDelay(1000 / BITRATE);
            }
            bit_index++;
            if (bit_index >= 8) {
                bit_index = 0;
                byte_index++;
            }
        }
        return 0;
    }
}

// Threshold-based LED control
int threshold_control(int brightness) {
    gpioWrite(GPIO_PIN, 1); // Turn on LED
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_lux;
    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_veml7700(&raw_lux) == 0) {
            // Convert to lux
            lux = convert_to_lux(raw_lux);

            // Apply gamma correction
            brightness = gamma_correct(lux);

            // Set LED brightness
            if (set_led_brightness(brightness) != 0) {
                fprintf(stderr, "Failed to set LED brightness\n");
            }

            // Print lux and brightness values
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read ALS data, using default brightness\n");
            // Use default brightness if reading fails
            brightness = THRESHOLD_BRIGHTNESS;
            if (threshold_control(brightness) != 0) {
                fprintf(stderr, "Failed to control LED brightness using threshold\n");
            }
        }

        // Delay
        gpioDelay(200); // 200 ms delay
    }

    // Cleanup
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

