#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define LUX_THRESHOLD 1000
#define BLINK_RATE_MIN 0.5
#define BLINK_RATE_MAX 5.0

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_read(int fd, uint8_t addr, uint16_t *data);
float raw_to_lux(uint16_t raw);
float calculate_average_lux(CircularBuffer *cb);
float calculate_blink_rate(float avg_lux);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
void signal_handler(int sig);

// I2C read function
int i2c_read(int fd, uint8_t addr, uint16_t *data) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Raw to lux conversion
float raw_to_lux(uint16_t raw) {
    return raw / 1.2;
}

// Circular buffer functions
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

float circular_buffer_get_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Blink rate calculation
float calculate_blink_rate(float avg_lux) {
    float rate = 0.5 + (avg_lux / LUX_THRESHOLD) * 4.5;
    if (rate < BLINK_RATE_MIN) {
        rate = BLINK_RATE_MIN;
    } else if (rate > BLINK_RATE_MAX) {
        rate = BLINK_RATE_MAX;
    }
    return rate;
}

// GPIO functions
int gpio_export(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open export file");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open unexport file");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open gpio direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) == -1) {
        perror("Failed to set gpio direction");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_write(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open gpio value file");
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) == -1) {
        perror("Failed to write GPIO value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize GPIO
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to output\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer lux_buffer;
    circular_buffer_init(&lux_buffer);

    // Main loop
    while (program_running) {
        uint16_t raw_value;
        if (i2c_read(i2c_fd, BH1750_ADDR, &raw_value) == 0) {
            float lux = raw_to_lux(raw_value);
            circular_buffer_add(&lux_buffer, lux);
            float avg_lux = circular_buffer_get_average(&lux_buffer);

            printf("Raw: %u, Lux: %.2f, Avg Lux: %.2f\n", raw_value, lux, avg_lux);

            // Blink rate calculation
            float blink_rate = calculate_blink_rate(avg_lux);

            // Blink the LED
            if (gpio_write(GPIO_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %d high\n", GPIO_PIN);
            }
            usleep(blink_rate * 1000000); // microseconds
            if (gpio_write(GPIO_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %d low\n", GPIO_PIN);
            }
            usleep(blink_rate * 1000000); // microseconds
        } else {
            fprintf(stderr, "Failed to read from I2C device, retrying...\n");
        }

        sleep(1);
    }

    // Cleanup
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

