        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) == -1) {
        perror("Failed to write GPIO value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize GPIO
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to output\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer lux_buffer;
    circular_buffer_init(&lux_buffer);

    // Main loop
    while (program_running) {
        uint16_t raw_value;
        if (i2c_read(i2c_fd, BH1750_ADDR, &raw_value) == 0) {
            float lux = raw_to_lux(raw_value);
            circular_buffer_add(&lux_buffer, lux);
            float avg_lux = circular_buffer_get_average(&lux_buffer);

            printf("Raw: %u, Lux: %.2f, Avg Lux: %.2f\n", raw_value, lux, avg_lux);

            // Blink rate calculation
            float blink_rate = calculate_blink_rate(avg_lux);

            // Blink the LED
            if (gpio_write(GPIO_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %d high\n", GPIO_PIN);
            }
            usleep(blink_rate * 1000000); // microseconds
            if (gpio_write(GPIO_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %d low\n", GPIO_PIN);
            }
            usleep(blink_rate * 1000000); // microseconds
        } else {
            fprintf(stderr, "Failed to read from I2C device, retrying...\n");
        }

        sleep(1);
    }

    // Cleanup
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

