#include <errno.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for digit '5'
const unsigned char segments[10] = {
    0b00111111, // A
    0b00000110, // B
    0b01011011, // C
    0b01001111, // D
    0b01100110, // E
    0b01101101, // F
    0b01111101, // G
    0b01111111  // DP
};

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(struct gpiod_chip *chip, struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line);
void shift_out(unsigned char data);
void display_digit_5();
void cleanup(struct gpiod_chip *chip, struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        program_running = 0;
    }
}

// Function to initialize GPIO lines
int initialize_gpio(struct gpiod_chip *chip, struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line) {
    int ret;

    // Request data line as output
    ret = gpiod_line_request_output(data_line, "data", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting data line: %s\n", strerror(-ret));
        return -1;
    }

    // Request clock line as output
    ret = gpiod_line_request_output(clock_line, "clock", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting clock line: %s\n", strerror(-ret));
        gpiod_line_release(data_line);
        return -1;
    }

    // Request latch line as output
    ret = gpiod_line_request_output(latch_line, "latch", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting latch line: %s\n", strerror(-ret));
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        return -1;
    }

    return 0;
}

// Function to shift out data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin
        gpiod_line_set_value(data_line, 1 << i, 1);

        // Pulse clock pin
        ret = gpiod_line_set_value(clock_line, 1, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting clock line: %s\n", strerror(-ret));
            return;
        }
        usleep(1); // 1 us delay

        ret = gpiod_line_set_value(clock_line, 0, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting clock line: %s\n", strerror(-ret));
            return;
        }
        usleep(1); // 1 us delay

        // Set latch pin
        ret = gpiod_line_set_value(latch_line, 1, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting latch line: %s\n", strerror(-ret));
            return;
        }
        usleep(1); // 1 us delay

        ret = gpiod_line_set_value(latch_line, 0, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting latch line: %s\n", strerror(-ret));
            return;
        }
        usleep(1); // 1 us delay
    }
}

// Function to display the digit '5'
void display_digit_5() {
    shift_out(segments[4]);
}

// Function to cleanup GPIO lines
void cleanup(struct gpiod_chip *chip, struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line) {
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *clock_line, *latch_line;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(chip, &data_line, &clock_line, &latch_line) < 0) {
        cleanup(chip, &data_line, &clock_line, &latch_line);
        return 1;
    }

    // Main loop
    while (program_running) {
        display_digit_5();
        usleep(500000); // 500 ms on

        shift_out(0x00); // Clear display
        usleep(500000); // 500 ms off
    }

    // Cleanup and exit
    cleanup(chip, &data_line, &clock_line, &latch_line);
    return 0;
}

