#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C pressed, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;  // 1 second
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Request LED line as output initially low
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return 1;
    }

    int led_request_status = gpiod_line_request_output(led_line, 0, 0); // Initial value 0
    if (led_request_status < 0) {
        perror("gpiod_line_request_output (LED)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line as input with internal pull-up and falling-edge event detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (BUTTON)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    int button_request_status = gpiod_line_request_input(button_line, 0, GPIOD_LINE_REQUEST_FLAG_EVENT);
    if (button_request_status < 0) {
        perror("gpiod_line_request_input (BUTTON)");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Toggle LED state
        int led_value = (led_line->value == 0) ? 1 : 0;
        int led_request_status = gpiod_line_set_value(led_line, led_value);
        if (led_request_status < 0) {
            perror("gpiod_line_set_value (LED)");
            break; // Exit loop on error
        }

        // Wait for button event with timeout
        int button_event = gpiod_line_event_wait(button_line, 1, sleep_time);
        if (button_event < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                perror("gpiod_line_event_wait");
                break; // Exit loop on error
            }
        } else if (button_event > 0) {
            // Button event occurred
            printf("Button pressed! Turning off LED and exiting.\n");
            gpiod_line_set_value(led_line, 0); // Turn off LED
            break; // Exit loop
        } else {
            // Timeout occurred, no button event
            // Do nothing, just sleep
        }
    }

    // Cleanup
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

