#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int result;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", result);
        return 1;
    }

    // Set GPIO5 as an output
    result = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %d\n", LED_PIN, result);
        gpioTerminate();
        return 1;
    }

    printf("LED blinking started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Turn LED on
        result = gpioWrite(LED_PIN, 1);
        if (result != 0) {
            fprintf(stderr, "Failed to set GPIO%d HIGH: %d\n", LED_PIN, result);
            break; // Exit loop on error
        }

        // Print 'LED ON'
        printf("LED ON\n");

        // Wait 750 ms
        time_sleep(0.75);

        // Turn LED off
        result = gpioWrite(LED_PIN, 0);
        if (result != 0) {
            fprintf(stderr, "Failed to set GPIO%d LOW: %d\n", LED_PIN, result);
            break; // Exit loop on error
        }

        // Print 'LED OFF'
        printf("LED OFF\n");

        // Wait 750 ms
        time_sleep(0.75);
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

