#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for RGB LED
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define chip and line structures
struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void set_pwm_duty_cycle(int pin, int duty_cycle);
void generate_random_rgb(int *red, int *green, int *blue);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCtrl+C pressed. Cleaning up and exiting.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip.\n");
        return -1;
    }

    // Get line structures for each GPIO pin
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d, %d, or %d.\n", RED_PIN, GREEN_PIN, BLUE_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(red_line, "random_rgb", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request output for GPIO %d: %d\n", RED_PIN, ret);
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(green_line, "random_rgb", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request output for GPIO %d: %d\n", GREEN_PIN, ret);
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(blue_line, "random_rgb", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request output for GPIO %d: %d\n", BLUE_PIN, ret);
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int pin, int duty_cycle) {
    struct timespec high_time, low_time;
    long high_ns, low_ns;

    // Calculate high and low times based on 100 Hz frequency and duty cycle
    high_ns = (long)(1000000000.0 / 100.0); // 10 ms period
    low_ns = (long)(1000000000.0 / 100.0 * (100.0 - duty_cycle.0)); // Calculate low time

    high_time.tv_sec = 0;
    high_time.tv_nsec = high_ns;
    low_time.tv_sec = 0;
    low_time.tv_nsec = low_ns;

    // Set the GPIO pin high
    if (gpiod_line_set_value(pin, 1) < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d high.\n", pin);
        return;
    }

    // Wait for the high time
    nanosleep(&high_time, NULL);

    // Set the GPIO pin low
    if (gpiod_line_set_value(pin, 0) < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d low.\n", pin);
        return;
    }

    // Wait for the low time
    nanosleep(&low_time, NULL);
}

// Function to generate random RGB values
void generate_random_rgb(int *red, int *green, int *blue) {
    *red = rand() % 101;
    *green = rand() % 101;
    *blue = rand() % 101;
}

int main(void) {
    int red, green, blue;
    struct timespec sleep_time;
    int ret;

    // Seed the random number generator with the current time
    srand(time(NULL));

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO lines
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Generate random RGB values
        generate_random_rgb(&red, &green, &blue);

        // Set PWM duty cycles for each color
        set_pwm_duty_cycle(RED_PIN, red);
        set_pwm_duty_cycle(GREEN_PIN, green);
        set_pwm_duty_cycle(BLUE_PIN, blue);

        // Sleep for 100 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 ms
        ret = nanosleep(&sleep_time, NULL);
        if (ret < 0) {
            fprintf(stderr, "Error: nanosleep failed: %d\n", ret);
        }
    }

    return 0;
}

