#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for impact indication
#define IMPACT_GPIO 17

// Default impact threshold (G)
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double impact_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_lsm303();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_impact_data(int16_t x, int16_t y, int16_t z);
void impact_callback(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    int opt;
    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303DLHC
    if (init_lsm303() != 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(IMPACT_GPIO, PI_OUTPUT);
    gpioWrite(IMPACT_GPIO, 0); // Ensure it starts LOW

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt on GPIO17 (falling edge)
    gpioSetAlertFuncEx(IMPACT_GPIO, impact_callback, NULL);

    // Main loop
    accelerometer_data_t accel_data;
    while (program_running) {
        // Read accelerometer data
        if (read_accelerometer_data(&accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Calculate magnitude
            double magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

            // Log data if impact detected
            if (magnitude > impact_threshold) {
                log_impact_data(accel_data.x, accel_data.y, accel_data.z);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Sleep for 100 ms (10 Hz polling rate)
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up
    gpioSetAlertFuncEx(IMPACT_GPIO, NULL, NULL); // Disable interrupt
    i2cClose(i2c_handle);
    gpioWrite(IMPACT_GPIO, 0); // Ensure GPIO is LOW before exiting
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize LSM303DLHC
int init_lsm303() {
    // Enable all axes and set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return 1;
    }

    // Set full-scale range to +/- 2G and sensitivity to 16384 LSB/G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return 1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return 1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude of acceleration vector
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 16384.0; // Convert to G
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact data to file
int log_impact_data(int16_t x, int16_t y, int16_t z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", s, x, y, z);
    fclose(fp);
    return 0;
}

// Callback function for GPIO interrupt
void impact_callback(int gpio, int level, uint32_t tick, void *user) {
    // This function is called when the impact is detected (GPIO goes LOW)
    // The actual impact detection is done in the main loop.
    // This function is used to trigger the GPIO pulse.
    gpioWrite(IMPACT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(50000);          // Wait for 50 ms
    gpioWrite(IMPACT_GPIO, 0); // Set GPIO LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

