        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }
    *als = (uint16_t)result;
    return 0;
}

// Function to read RGB data
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    int result_red = i2cReadWordData(i2c_handle, RED_LSB_REG);
    int result_green = i2cReadWordData(i2c_handle, GREEN_LSB_REG);
    int result_blue = i2cReadWordData(i2c_handle, BLUE_LSB_REG);

