float calculate_magnitude(float x, float y, float z);
int log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0); // Bus 1, address 0x1F, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the sensor by reading WHO_AM_I register
int verify_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X (expected 0xC7)\n", who_am_i);
        return -1;
    }
    printf("Sensor verified: WHO_AM_I = 0x%02X\n", who_am_i);
    return 0;
}

// Configure the sensor
int configure_sensor() {
    // Standby mode (CTRL_REG1 bit 0 = 0)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby mode)\n");
        return -1;
    }

    // ±2g mode (XYZ_DATA_CFG = 0x00)
    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG\n");
        return -1;
    }

    // Active mode (CTRL_REG1 bit 0 = 1, ODR = 200 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active mode)\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buf, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine MSB and LSB, shift right by 2 bits
    raw_x = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    raw_y = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    raw_z = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    // Convert to g-force units
    *x = (float)raw_x / SENSITIVITY * 9.81;
    *y = (float)raw_y / SENSITIVITY * 9.81;
    *z = (float)raw_z / SENSITIVITY * 9.81;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log impact data to a file
int log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify the sensor
    if (verify_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Log the impact
                log_impact(x, y, z, magnitude);
                printf("Impact detected: x=%.3f, y=%.3f, z=%.3f, magnitude=%.3f\n", x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Close the log file
    fclose(log_file);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

