#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define SAMPLE_RATE 100 // Hz
#define CALIBRATION_SAMPLES 100
#define LOG_PERIOD_MS 50
#define ALERT_THRESHOLD 50.0 // dps

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure for gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure for gyroscope calibration offsets
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} gyro_offsets_t;

// Function prototypes
int i2c_open(int bus, int addr);
int i2c_write(int fd, uint8_t reg, uint8_t value);
int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len);
int gyro_init(int fd);
int gyro_read(int fd, gyro_data_t *data);
gyro_offsets_t gyro_calibrate(int fd, int num_samples);
void log_data(FILE *fp, gyro_data_t data, gyro_offsets_t offsets);
void check_alert(gyro_data_t data, gyro_offsets_t offsets);
void signal_handler(int sig);

// I2C open function
int i2c_open(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Gyroscope initialization function
int gyro_init(int fd) {
    // Verify sensor presence
    uint8_t who_am_i;
    if (i2c_read(fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (100 Hz ODR, all axes enabled)
    if (i2c_write(fd, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4 (250 dps full-scale, continuous update)
    if (i2c_write(fd, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Gyroscope read function
int gyro_read(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    if (i2c_read(fd, OUT_X_L, buf, 6) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    // Convert to degrees per second
    data->x = (float)raw_x * 0.00875;
    data->y = (float)raw_y * 0.00875;
    data->z = (float)raw_z * 0.00875;

    return 0;
}

// Gyroscope calibration function
gyro_offsets_t gyro_calibrate(int fd, int num_samples) {
    gyro_offsets_t offsets;
    int16_t raw_x, raw_y, raw_z;
    float x_sum = 0, y_sum = 0, z_sum = 0;
    gyro_data_t data;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < num_samples; i++) {
        if (gyro_read(fd, &data) < 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return (gyro_offsets_t){0, 0, 0}; // Return default offsets
        }
        x_sum += data.x;
        y_sum += data.y;
        z_sum += data.z;
        usleep(10000); // 10 ms delay
    }

    offsets.x_offset = x_sum / num_samples;
    offsets.y_offset = y_sum / num_samples;
    offsets.z_offset = z_sum / num_samples;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", offsets.x_offset, offsets.y_offset, offsets.z_offset);
    return offsets;
}

// Data logging function
void log_data(FILE *fp, gyro_data_t data, gyro_offsets_t offsets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x - offsets.x_offset, data.y - offsets.y_offset, data.z - offsets.z_offset);
    fflush(fp); // Ensure data is written to file immediately
}

// Alert checking function
void check_alert(gyro_data_t data, gyro_offsets_t offsets) {
    if (fabs(data.x) > ALERT_THRESHOLD || fabs(data.y) > ALERT_THRESHOLD || fabs(data.z) > ALERT_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = gmtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        fprintf(stderr, "ALERT: %s, X=%.2f, Y=%.2f, Z=%.2f\n", timestamp, data.x, data.y, data.z);
        fprintf(log_file, "ALERT: %s, X=%.2f, Y=%.2f, Z=%.2f\n", timestamp, data.x, data.y, data.z);
        fflush(log_file);
    }
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS, GYRO_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize gyroscope
    if (gyro_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Calibrate gyroscope
    gyro_offsets_t offsets = gyro_calibrate(i2c_fd, CALIBRATION_SAMPLES);

    // Main loop
    gyro_data_t data;
    struct timespec req = {0, LOG_PERIOD_MS * 1000000L};
    struct timespec got;
    long long elapsed;

    while (!terminate) {
        // Read gyroscope data
        if (gyro_read(i2c_fd, &data) < 0) {
            fprintf(stderr, "Error reading gyro data\n");
            break;
        }

        // Apply calibration offsets
        data.x -= offsets.x_offset;
        data.y -= offsets.y_offset;
        data.z -= offsets.z_offset;

        // Log data
        log_data(log_file, data, offsets);

        // Check for alerts
        check_alert(data, offsets);

        // Sleep for the specified period
        if (nanosleep(&req, &got) != 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
            break;
        }

        // Reset sleep time
        req.tv_nsec = LOG_PERIOD_MS * 1000000L;
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

