#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_DEVID 0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Full-resolution, ±2g range
#define ADXL345_RANGE 0x08

// GPIO pin for LED
#define LED_PIN 17

// Acceleration threshold (g)
#define ACCEL_THRESHOLD 2.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_acceleration();
void log_data(accelerometer_data_t data);
void control_led(float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the ADXL345 accelerometer
int initialize_adxl345() {
    // Check DEVID register
    char devid;
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DEVID, &devid, 1) != 1) {
        fprintf(stderr, "Error reading DEVID register\n");
        return -1;
    }

    if (devid != 0xE5) {
        fprintf(stderr, "Error: Incorrect DEVID value: 0x%02X\n", devid);
        return -1;
    }

    // Set range to ±2g
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, ADXL345_RANGE) != 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Reads acceleration data from the ADXL345
accelerometer_data_t read_acceleration() {
    accelerometer_data_t data;
    char raw_data[6];
    int16_t x, y, z;

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g units (assuming full resolution and ±2g range)
    data.x = (float)x / 256.0;
    data.y = (float)y / 256.0;
    data.z = (float)z / 256.0;

    return data;
}

// Logs the acceleration data to a file
void log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Controls the LED based on the acceleration magnitude
void control_led(float magnitude) {
    if (magnitude > ACCEL_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        accelerometer_data_t data = read_acceleration();

        // Log data
        log_data(data);

        // Control LED
        control_led(sqrt(data.x * data.x + data.y * data.y + data.z * data.z));

        // Sleep for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    return 0;
}

