float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle_accel = init_i2c(1, ACCEL_ADDR);
    i2c_handle_mag = init_i2c(1, MAG_ADDR);

    if (i2c_handle_accel < 0 || i2c_handle_mag < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize accelerometer
    if (write_register(i2c_handle_accel, CTRL_REG1_A, 0x27) < 0) {
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (write_register(i2c_handle_mag, MR_REG_M, 0x00) < 0) {
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Check if the log file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_accel_data(i2c_handle_accel, &accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            continue; // Retry reading accelerometer data
        }
        if (read_mag_data(i2c_handle_mag, &mag_x, &mag_y, &mag_z) < 0) {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            continue; // Retry reading magnetometer data
        }

        // Calculate heading
        heading = calculate_heading(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Log data
        log_data(heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

