// VL6180X initialization function
int vl6180x_init() {
    int status;

    // Check device ID
    status = i2cReadByteData(i2c_handle, VL6180X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", status);
        return -1;
    }
    if (status != 0xB4) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", status);
        return -1;
    }

    // Reset the device
    status = i2cWriteByteData(i2c_handle, 0x016, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error resetting device: %d\n", status);
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure GPIO
    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error configuring GPIO: %d\n", status);
        return -1;
    }

    // Start continuous ranging
    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting continuous ranging: %d\n", status);
        return -1;
    }

    return 0;
}

