int read_distance() {
    int status;
    int distance = -1; // Default to -1 to indicate error

    // Read range status
    status = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", status);
        return -1;
    }

    // Check for errors
    if (status & 0x01) {
        fprintf(stderr, "Overrange error\n");
    } else if (status & 0x02) {
        fprintf(stderr, "Signal failure\n");
    } else if (status & 0x04) {
        fprintf(stderr, "Timeout error\n");
    } else if (status & 0x08) {
        fprintf(stderr, "Device busy\n");
    } else if (status & 0x10) {
        fprintf(stderr, "Communication error\n");
    } else if (status & 0x20) {
        fprintf(stderr, "Sensor not present\n");
    } else {
        // Read range value
        status = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_VAL);
        if (status < 0) {
            fprintf(stderr, "Error reading range value: %d\n", status);
            return -1;
        }

        distance = status; // Distance in mm
    }

    return distance;
}

