    i2c_handle = i2cOpen(1, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL6180X sensor
    init_result = vl6180x_init();
    if (init_result != 0) {
        fprintf(stderr, "VL6180X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(100); // Sample every 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

