#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define SAMPLE_INTERVAL_US 10000 // 10 ms
#define SAMPLE_RATE_HZ 100
#define CONTROL_REG 0x00
#define DATA_REG 0x01
#define SAMPLE_SIZE 2 // Bytes per sample (16-bit signed)
#define LOG_FILE "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
    int address_str;
} sensor_t;

// Function prototypes
int initialize_i2c(sensor_t *sensor1, sensor_t *sensor2);
int read_sensor_data(sensor_t *sensor);
int calculate_tdoa(int sensor1_sample, int sensor2_sample);
int log_data(int sensor1_sample, int sensor2_sample, int tdoa);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes I2C communication for both sensors
int initialize_i2c(sensor_t *sensor1, sensor_t *sensor2) {
    // Open I2C device for sensor 1
    sensor1->handle = i2cOpen(I2C_BUS, sensor1->address, 0);
    if (sensor1->handle < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", sensor1->handle);
        return -1;
    }
    sensor1->address_str = sensor1->address;
    sensor1->address_str[2] = '\0'; // Ensure null termination

    // Open I2C device for sensor 2
    sensor2->handle = i2cOpen(I2C_BUS, sensor2->address, 0);
    if (sensor2->handle < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", sensor2->handle);
        i2cClose(sensor1->handle);
        return -1;
    }
    sensor2->address_str = sensor2->address;
    sensor2->address_str[2] = '\0'; // Ensure null termination

    // Configure sensor 1
    if (i2cWriteByteData(sensor1->handle, CONTROL_REG, 0x80) < 0) {
        fprintf(stderr, "Error configuring sensor 1\n");
        i2cClose(sensor1->handle);
        i2cClose(sensor2->handle);
        return -1;
    }

    // Configure sensor 2
    if (i2cWriteByteData(sensor2->handle, CONTROL_REG, 0x80) < 0) {
        fprintf(stderr, "Error configuring sensor 2\n");
        i2cClose(sensor1->handle);
        i2cClose(sensor2->handle);
        return -1;
    }

    return 0;
}

// Reads audio data from a single sensor
int read_sensor_data(sensor_t *sensor) {
    char buf[SAMPLE_SIZE];
    int bytes_read = i2cReadI2CBlockData(sensor->handle, DATA_REG, buf, SAMPLE_SIZE);

    if (bytes_read != SAMPLE_SIZE) {
        fprintf(stderr, "Error reading from sensor %s: %d\n", sensor->address_str, bytes_read);
        return -1; // Indicate error
    }

    // Convert the buffer to a signed 16-bit integer
    int16_t sample = (int16_t)((buf[1] << 8) | buf[0]);

    return sample;
}

// Calculates the TDOA between the two sensor readings
int calculate_tdoa(int sensor1_sample, int sensor2_sample) {
    return sensor1_sample - sensor2_sample;
}

// Logs the sensor data and TDOA to a CSV file
int log_data(int sensor1_sample, int sensor2_sample, int tdoa) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Convert nanoseconds to microseconds
    long long sec = ts.tv_sec;
    long long nsec = ts.tv_nsec;
    long long tdoa_us = (sec * 1000000LL) + nsec + tdoa;

    // Log the data to the CSV file
    if (fprintf(log_file, "%lld,%lld,%d,%d,%d\n", sec, nsec, sensor1_sample, sensor2_sample, tdoa_us) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Define sensor structures
    sensor_t sensor1 = {0};
    sensor1.address = SENSOR1_ADDR;
    sensor1.address_str[0] = '\0'; // Initialize address string

    sensor_t sensor2 = {0};
    sensor2.address = SENSOR2_ADDR;
    sensor2.address_str[0] = '\0'; // Initialize address string

    // Initialize I2C communication
    if (initialize_i2c(&sensor1, &sensor2) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(sensor1.handle);
        i2cClose(sensor2.handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read data from sensor 1
        int sensor1_sample = read_sensor_data(&sensor1);
        if (sensor1_sample == -1) {
            fprintf(stderr, "Error reading sensor 1, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        // Read data from sensor 2
        int sensor2_sample = read_sensor_data(&sensor2);
        if (sensor2_sample == -1) {
            fprintf(stderr, "Error reading sensor 2, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        // Calculate TDOA
        int tdoa = calculate_tdoa(sensor1_sample, sensor2_sample);

        // Log the data
        if (log_data(sensor1_sample, sensor2_sample, tdoa) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for the sampling interval
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Close I2C devices and terminate pigpio
    i2cClose(sensor1.handle);
    i2cClose(sensor2.handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

