#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8

// Scaling factors
#define GYRO_SCALE 0.02 // dps/LSB
#define ACCEL_SCALE 0.00025 // g/LSB

// Global variables
int spi_fd;
int cs_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int spi_read_register(uint8_t address, uint16_t *data);
int spi_write_register(uint16_t data);
void read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// SPI Initialization function
int spi_init() {
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_fd);
        return -1;
    }

    cs_fd = gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate chip select initially

    return 0;
}

// SPI Read Register function
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: address (MSB=1) + dummy byte
    tx_buf[0] = address | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Activate chip select
    int result = spiXfer(spi_fd, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deactivate chip select

    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Combine the received bytes into a 16-bit value
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// SPI Write Register function
int spi_write_register(uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: data (MSB=0) + dummy byte
    tx_buf[0] = data & 0x7F; // Clear MSB for write
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Activate chip select
    int result = spiXfer(spi_fd, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deactivate chip select

    if (result != 3) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Read IMU Data function
void read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_register(XGYRO_OUT, &raw_gyro_x) != 0) {
        fprintf(stderr, "Error reading gyro X\n");
        *gyro_x = 0.0;
    } else {
        *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    }

    if (spi_read_register(YGYRO_OUT, &raw_gyro_y) != 0) {
        fprintf(stderr, "Error reading gyro Y\n");
        *gyro_y = 0.0;
    } else {
        *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    }

    if (spi_read_register(ZGYRO_OUT, &raw_gyro_z) != 0) {
        fprintf(stderr, "Error reading gyro Z\n");
        *gyro_z = 0.0;
    } else {
        *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    }

    if (spi_read_register(XACCL_OUT, &raw_accel_x) != 0) {
        fprintf(stderr, "Error reading accel X\n");
        *accel_x = 0.0;
    } else {
        *accel_x = (float)raw_accel_x * ACCEL_SCALE;
    }

    if (spi_read_register(YACCL_OUT, &raw_accel_y) != 0) {
        fprintf(stderr, "Error reading accel Y\n");
        *accel_y = 0.0;
    } else {
        *accel_y = (float)raw_accel_y * ACCEL_SCALE;
    }

    if (spi_read_register(ZACCL_OUT, &raw_accel_z) != 0) {
        fprintf(stderr, "Error reading accel Z\n");
        *accel_z = 0.0;
    } else {
        *accel_z = (float)raw_accel_z * ACCEL_SCALE;
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Main loop
    while (!terminate) {
        read_imu_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z);

        // Print the data
        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accel X: %.2f g, Accel Y: %.2f g, Accel Z: %.2f g\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

