#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B

// Accelerometer and gyroscope data registers
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// I2C file descriptor
int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    close(i2c_fd);
    exit(0);
}

// Function to write a byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
            perror("Failed to acquire bus access and/or talk to slave.");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000);
            continue;
        }

        if (write(fd, &value, 1) != 1) {
            perror("Failed to write data");
            retries--;
            usleep(10000);
            continue;
        }

        return 0; // Success
    }
    fprintf(stderr, "Failed to write to I2C device after multiple retries.\n");
    return -1; // Failure
}

// Function to read a byte from an I2C register
int read_register(int fd, uint8_t reg, uint8_t *value) {
    int retries = 3;
    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
            perror("Failed to acquire bus access and/or talk to slave.");
            retries--;
            usleep(10000);
            continue;
        }

        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000);
            continue;
        }

        if (read(fd, value, 1) != 1) {
            perror("Failed to read data");
            retries--;
            usleep(10000);
            continue;
        }

        return 0; // Success
    }
    fprintf(stderr, "Failed to read from I2C device after multiple retries.\n");
    return -1; // Failure
}

// Function to initialize the MPU-6886
int initialize_mpu6886(int fd) {
    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (read_register(fd, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != 0x86) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x86.\n", who_am_i);
        return -1;
    }

    // Wake up the sensor
    if (write_register(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register.\n");
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    if (write_register(fd, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG register.\n");
        return -1;
    }

    // Configure gyroscope range (+/- 250 dps)
    if (write_register(fd, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register.\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];

    if (read(fd, buffer, 14) != 14) {
        perror("Failed to read sensor data");
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Combine high and low bytes for gyroscope data
    *gyro_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *gyro_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.");
        close(i2c_fd);
        return 1;
    }

    // Initialize the MPU-6886
    if (initialize_mpu6886(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6886 initialized successfully.\n");

    // Main loop
    while (1) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        // Read sensor data
        if (read_sensor_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print the raw sensor data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(50000); // 50ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    return 0;
}

