    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.");
        close(i2c_fd);
        return 1;
    }

    // Initialize the MPU-6886
    if (initialize_mpu6886(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6886 initialized successfully.\n");

    // Main loop
    while (1) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        // Read sensor data
        if (read_sensor_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print the raw sensor data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(50000); // 50ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    return 0;
}

