#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 Registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Scaling factors
#define ACCEL_SCALE 16384.0f // +/- 2g
#define GYRO_SCALE 131.0f   // +/- 250 dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_icm20602();
int read_icm20602_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z);
int log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initializes the ICM-20602 IMU
int init_icm20602() {
    // Wake up the device
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up ICM-20602\n");
        return -1;
    }

    // Configure accelerometer range to +-2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range to +-250 dps
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Reads accelerometer and gyroscope data from the ICM-20602
int read_icm20602_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 12) < 0) {
        fprintf(stderr, "Error: Could not read accelerometer/gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    raw_accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Combine high and low bytes for gyroscope data
    raw_gyro_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    raw_gyro_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    raw_gyro_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    // Convert raw data to g and dps
    *accel_x = (float)raw_accel_x / ACCEL_SCALE;
    *accel_y = (float)raw_accel_y / ACCEL_SCALE;
    *accel_z = (float)raw_accel_z / ACCEL_SCALE;
    *gyro_x = (float)raw_gyro_x / GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y / GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z / GYRO_SCALE;

    return 0;
}

// Logs the IMU data to a CSV file
int log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the ICM-20602
    if (init_icm20602() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read IMU data
        if (read_icm20602_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Log the data
            log_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read IMU data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close the log file
    fclose(log_file);

    return 0;
}

