#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define OUT_X_MSB 0x01
#define OUT_Y_MSB 0x03
#define OUT_Z_MSB 0x05
#define LED_GPIO 17
#define THRESHOLD 2.0f
#define IMPACT_DURATION 500 // milliseconds
#define POLL_INTERVAL 100 // milliseconds

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_sensor();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Turn LED off initially
    return 0;
}

// Initialize the sensor
int init_sensor() {
    // Verify sensor identity
    int who_am_i = i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%X\n", who_am_i);
        return -1;
    }
    printf("Sensor identity verified: WHO_AM_I = 0x%X\n", who_am_i);

    // Configure the sensor (default settings)
    // CTRL_REG1: Normal mode, 100 Hz data rate, enable all axes
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, 0x01) < 0) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    // CTRL_REG2: +-2g range
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG2, 0x00) < 0) {
        perror("Error writing to CTRL_REG2");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_MSB, buffer, 6) < 0) {
        perror("Error reading acceleration data");
        return -1;
    }

    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to g-force units (+/- 2g range, 1g = 1024 counts)
    *x = (float)raw_x / 2048.0f;
    *y = (float)raw_y / 2048.0f;
    *z = (float)raw_z / 2048.0f;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log impact event
void log_impact(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Impact detected - X=%.2f g, Y=%.2f g, Z=%.2f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (init_sensor() < 0) {
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    float x, y, z, magnitude;

    printf("Monitoring acceleration... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > THRESHOLD) {
                gpioWrite(LED_GPIO, 1); // Turn LED on
                log_impact(x, y, z);
                gpioDelay(IMPACT_DURATION); // Keep LED on for 500 ms
                gpioWrite(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(POLL_INTERVAL); // Poll every 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();
    close(i2c_fd);

    return 0;
}

