#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // Standard I2C bus on Raspberry Pi
#define TMAG5273_ADDR 0x35    // Default I2C address of TMAG5273
#define X_REG 0x10            // X-axis data register
#define Y_REG 0x11            // Y-axis data register
#define Z_REG 0x12            // Z-axis data register
#define SAMPLE_RATE_SEC 1      // Sampling rate in seconds
#define CSV_FILE "magnetic_field_log.csv"

// Global variables
static int i2c_fd = -1; // I2C file descriptor
static FILE *log_file = NULL; // CSV log file pointer
static volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len);
int16_t read_magnetic_field(int fd, uint8_t reg);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
int open_i2c_device(const char *bus, int addr);
int close_i2c_device(int fd);
int open_csv_file(const char *filename);
int close_csv_file(FILE *fp);

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// I2C read multiple registers function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read magnetic field data from the sensor
int16_t read_magnetic_field(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (i2c_read_regs(fd, reg, buf, 2) != 0) {
        fprintf(stderr, "Error reading magnetic field data from register 0x%02x\n", reg);
        return 0; // Return 0 on error
    }
    return (int16_t)((buf[1] << 8) | buf[0]); // Combine the two bytes
}

// Function to log data to CSV file
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to open the CSV file
int open_csv_file(const char *filename) {
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    return 0;
}

// Function to close the CSV file
int close_csv_file(FILE *fp) {
    if (fp != NULL) {
        fclose(fp);
        return 0;
    } else {
        return -1;
    }
}

