#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Scaling factors
#define ACCEL_SCALE 0.061 // mg/LSB for +-2g range
#define GYRO_SCALE 8.75  // mdps/LSB for +-250 dps range

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f

// Fall detection window (in seconds)
#define FALL_WINDOW 1.0

// Global variables
static int i2c_handle;
static volatile int running = 1;

// Function prototypes
int init_lsm6dsr();
int read_accel_data(float *x, float *y, float *z);
int read_gyro_data(float *x, float *y, float *z);
int log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z);
int detect_freefall(float accel_x, float accel_y, float accel_z);
int detect_impact(float accel_x, float accel_y, float accel_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function to initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Configure accelerometer: +-2g, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 0x80: 104 Hz, +-2g
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 0x80: 104 Hz, +-250 dps
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accel_data(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to g
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x * ACCEL_SCALE / 1000.0f; // Convert to g
    *y = (float)raw_y * ACCEL_SCALE / 1000.0f;
    *z = (float)raw_z * ACCEL_SCALE / 1000.0f;

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes, convert to dps
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x * GYRO_SCALE / 1000.0f; // Convert to dps
    *y = (float)raw_y * GYRO_SCALE / 1000.0f;
    *z = (float)raw_z * GYRO_SCALE / 1000.0f;

    return 0;
}

// Function to log data to a file
int log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z) {
    FILE *fp = fopen("motion_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    fclose(fp);

    return 0;
}

// Function to detect freefall
int detect_freefall(float accel_x, float accel_y, float accel_z) {
    float magnitude = sqrtf(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);
    return (magnitude < FREEFALL_THRESHOLD);
}

// Function to detect impact
int detect_impact(float accel_x, float accel_y, float accel_z) {
    float magnitude = sqrtf(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);
    return (magnitude > IMPACT_THRESHOLD);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_accel_data(&sensor_data.accel_x, &sensor_data.accel_y, &sensor_data.accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
        } else if (read_gyro_data(&sensor_data.gyro_x, &sensor_data.gyro_y, &sensor_data.gyro_z) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
        } else {
            // Log data
            if (log_data(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.gyro_x, sensor_data.gyro_y, sensor_data.gyro_z) < 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Detect freefall/impact
            if (detect_freefall(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z)) {
                printf("Freefall detected!\n");
            } else if (detect_impact(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z)) {
                printf("Impact detected!\n");
            }
        }

        // Delay for approximately 10 Hz (100 ms)
        gpioDelay(100000); // 100 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

