// GY-50 L3G4200D I2C address
#define GYRO_ADDRESS 0x69

// CTRL_REG1 register address
#define CTRL_REG1 0x20

// CTRL_REG4 register address
#define CTRL_REG4 0x23

// WHO_AM_I register address
#define WHO_AM_I 0x0F

// Data register addresses
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Sensitivity (mdps/LSB)
#define SENSITIVITY 8.75

// Full-scale range (dps)
#define FULL_SCALE 250.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *dps_x, float *dps_y, float *dps_z);
void log_data(float dps_x, float dps_y, float dps_z);
void signal_handler(int signal);

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function to initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int result;

    // Configure CTRL_REG1 for normal mode and all axes enabled
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 for +-250 dps full-scale range
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

