void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *dps_x, float *dps_y, float *dps_z) {
    *dps_x = (float)raw_x / 114.285;
    *dps_y = (float)raw_y / 114.285;
    *dps_z = (float)raw_z / 114.285;
}

// Function to log data to a file
void log_data(float dps_x, float dps_y, float dps_z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "%ld,%.6f,%.6f,%.6f\n", timestamp_ns, dps_x, dps_y, dps_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I register returned 0x%X, expected 0xD3\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    float dps_x, dps_y, dps_z;

    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            convert_to_dps(raw_x, raw_y, raw_z, &dps_x, &dps_y, &dps_z);
            log_data(dps_x, dps_y, dps_z);
        } else {
            fprintf(stderr, "Failed to read or process gyro data. Retrying...\n");
        }
        gpioDelay(10000); // Sample every 10 ms
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

