#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x53
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILE "vibration_log.csv"
#define ACCEL_REG_START 0x28
#define ACCEL_REG_COUNT 6
#define ACCEL_REG_SIZE 2
#define ACCEL_REG_BYTES 12
#define ACCEL_REG_BYTES_SIGNED 6

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_acceleration_data(int fd, acceleration_data_t *data);
int log_data(FILE *fp, const acceleration_data_t *data);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read acceleration data from the sensor
int read_acceleration_data(int fd, acceleration_data_t *data) {
    uint8_t buffer[ACCEL_REG_BYTES];
    int i;

    // Read all acceleration registers in one go
    if (read(fd, buffer, ACCEL_REG_BYTES) != ACCEL_REG_BYTES) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    // Combine LSB and MSB for each axis
    for (i = 0; i < ACCEL_REG_BYTES_SIGNED; i++) {
        data->x = (int16_t)((buffer[i * 2] << 8) | buffer[i * 2 + 1]);
        data->y = (int16_t)((buffer[(i + 1) * 2] << 8) | buffer[(i + 1) * 2 + 1]);
        data->z = (int16_t)((buffer[(i + 2) * 2] << 8) | buffer[(i + 2) * 2 + 1]);
    }

    return 0;
}

// Log data to CSV file
int log_data(FILE *fp, const acceleration_data_t *data) {
    time_t rawtime;
    struct tm *info;
    char timestamp[30];

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, data->x, data->y, data->z) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    acceleration_data_t acceleration_data;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_SLAVE_ADDR);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration_data(i2c_fd, &acceleration_data) == 0) {
            // Log data to CSV file
            if (log_data(csv_file, &acceleration_data) != 0) {
                fprintf(stderr, "Error logging data, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, skipping sample...\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

