#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define LOG_FILE "conveyor_log.txt"

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read sensor states
int read_sensor_states(int sensor1_gpio, int sensor2_gpio) {
    int sensor1_state = gpioRead(sensor1_gpio);
    int sensor2_state = gpioRead(sensor2_gpio);

    if (sensor1_state < 0 || sensor2_state < 0) {
        fprintf(stderr, "Error reading sensor states.\n");
        return -1; // Indicate error
    }

    return (sensor1_state << 4) | sensor2_state; // Combine sensor states into a single 8-bit value
}

// Function to log data to file
void log_data(FILE *log_file, int sensor_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(log_file, "%ld.%03ld,%d\n", ts.tv_sec, milliseconds, sensor_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to halt the conveyor (simulated)
void halt_conveyor() {
    printf("Conveyor halted!\n");
}

int main() {
    FILE *log_file;
    int sensor_state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-ups
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    fprintf(stdout, "Conveyor belt safety system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sensor_state = read_sensor_states(SENSOR1_GPIO, SENSOR2_GPIO);

        if (sensor_state == -1) {
            fprintf(stderr, "Error reading sensors, exiting.\n");
            break;
        }

        log_data(log_file, sensor_state);

        if (sensor_state == 0b1100) { // Both sensors triggered
            halt_conveyor();
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Conveyor belt safety system stopped.\n");
    return 0;
}

