#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define DATA_REG_START 0x01
#define DATA_REG_COUNT 6
#define DATA_REG_SIZE 2
#define DATA_RATE 100 // Hz
#define SAMPLE_INTERVAL 10 // ms
#define TILT_THRESHOLD 45.0 // degrees
#define FALL_LOG_FILE "fall_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int count);
int sensor_init(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_fall_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int count) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for block read");
        return -1;
    }
    if (read(fd, data, count) != count) {
        perror("Error reading block from I2C device");
        return -1;
    }
    return 0;
}

// Sensor initialization function
int sensor_init(int fd) {
    uint8_t who_am_i;

    // Verify WHO_AM_I register
    if (i2c_read_reg(fd, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x2A) {
        fprintf(stderr, "WHO_AM_I value: 0x%02X (expected 0x2A)\n", who_am_i);
        return -1;
    }

    printf("MMA8452Q WHO_AM_I: 0x%02X\n", who_am_i);

    // Set CTRL_REG1
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data function
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[12];

    if (i2c_read_block(fd, DATA_REG_START, data, DATA_REG_COUNT) < 0) {
