#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// I2C file descriptor
int i2c_fd = -1;

// Log file pointer
FILE *log_file = NULL;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the I2C bus
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a byte to a specific register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from a specific register
int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two registers
int16_t read_16bit(int fd, uint8_t low_reg, uint8_t high_reg) {
    uint8_t low, high;
    if (read_register(fd, low_reg, &low) < 0) return -1;
    if (read_register(fd, high_reg, &high) < 0) return -1;
    return (int16_t)((high << 8) | low);
}

// Function to initialize the LIS3MDL sensor
int init_lis3mdl(int fd) {
    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (read_register(fd, WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != 0x3D) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x3D\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (ODR = 80 Hz, High Performance)
    if (write_register(fd, CTRL_REG1, 0x70) < 0) return -1;

    // Configure CTRL_REG4 (Z-axis high-performance)
    if (write_register(fd, CTRL_REG4, 0x0C) < 0) return -1;

    // Configure CTRL_REG3 (X and Y high-performance)
    if (write_register(fd, CTRL_REG3, 0x00) < 0) return -1;

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data(int fd) {
    magnetometer_data_t data;
    data.x = read_16bit(fd, OUT_X_L, OUT_X_H);
    data.y = read_16bit(fd, OUT_Y_L, OUT_Y_H);
    data.z = read_16bit(fd, OUT_Z_L, OUT_Z_H);
    return data;
}

// Function to apply calibration offsets and scale
magnetometer_data_t apply_calibration(magnetometer_data_t data, int16_t x_offset, int16_t y_offset, int16_t z_offset) {
    data.x -= x_offset;
    data.y -= y_offset;
    data.z -= z_offset;
    return data;
}

// Function to convert raw data to milliGauss
magnetometer_data_t convert_to_mG(magnetometer_data_t data, float scale_factor) {
    magnetometer_data_t mG_data;
    mG_data.x = (int16_t)(data.x * scale_factor);
    mG_data.y = (int16_t)(data.y * scale_factor);
    mG_data.z = (int16_t)(data.z * scale_factor);
    return mG_data;
}

// Function to log data to a file
int log_data(magnetometer_data_t data, FILE *fp) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Function to check for metal detection
void check_metal_detection(magnetometer_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > 800.0) {
        printf("Metal Detected! Magnitude: %.2f mG\n", magnitude);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(LIS3MDL_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize LIS3MDL sensor
    if (init_lis3mdl(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data(i2c_fd);

        // Apply calibration
        magnetometer_data_t calibrated_data = apply_calibration(raw_data, 0, 0, 0);

        // Convert to milliGauss
        magnetometer_data_t mG_data = convert_to_mG(calibrated_data, 0.146); // Sensitivity of 0.146 mG/LSB

        // Log data
        if (log_data(mG_data, log_file) < 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        // Check for metal detection
        check_metal_detection(mG_data);

        // Sleep for 100 ms (10 Hz sampling rate)
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C connection and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

