            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        // Check for metal detection
        check_metal_detection(mG_data);

        // Sleep for 100 ms (10 Hz sampling rate)
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C connection and log file
    close(i2c_fd);
    fclose(log_file);

