int adxl354b_read_acceleration(int spi_handle, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Function to read a single byte from the ADXL354B register
int adxl354b_read_register(int spi_handle, uint8_t reg_addr) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    return rx_buf[1];
}

// Function to write a single byte to the ADXL354B register
int adxl354b_write_register(int spi_handle, uint8_t reg_addr, uint8_t value) {
    char tx_buf[2];
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = value;

    if (spiWrite(spi_handle, tx_buf, 2) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// Function to reset the ADXL354B
int adxl354b_reset(int spi_handle) {
