int adxl354b_set_measurement_mode(int spi_handle) {
    if (adxl354b_write_register(spi_handle, ADXL354B_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }
    gpioDelay(10000); // Wait for STABLE bit to set (adjust as needed)
    if (adxl354b_write_register(spi_handle, ADXL354B_POWER_CTL, 0x10) != 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL354B
int adxl354b_read_acceleration(int spi_handle, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    int x_l, x_h, y_l, y_h, z_l, z_h;

    x_l = adxl354b_read_register(spi_handle, ADXL354B_XDATA_L);
    x_h = adxl354b_read_register(spi_handle, ADXL354B_XDATA_H);
