    y_h = adxl354b_read_register(spi_handle, ADXL354B_YDATA_H);
    z_l = adxl354b_read_register(spi_handle, ADXL354B_ZDATA_L);
    z_h = adxl354b_read_register(spi_handle, ADXL354B_ZDATA_H);

    if (x_l == -1 || x_h == -1 || y_l == -1 || y_h == -1 || z_l == -1 || z_h == -1) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((x_h << 8) | x_l);
    raw_y = (int16_t)((y_h << 8) | y_l);
    raw_z = (int16_t)((z_h << 8) | z_l);

