// ADIS16362 Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // degrees/sec/LSB
#define ACCL_SCALE 0.0025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int spi_handle, uint8_t address, int16_t *data);
void log_data(FILE *fp, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z);
void signal_handler(int signal);

// Function to read a single register from the ADIS16362
int spi_read_register(int spi_handle, uint8_t address, int16_t *data) {
    char tx_buf[3];
    char rx_buf[3];
    int result;

    // Construct the transmit buffer: address (MSB set) + dummy byte
    tx_buf[0] = address | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    // Transfer the data
    result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Extract the received data (16-bit)
    *data = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    return 0; // Indicate success
}

// Function to log the IMU data to a file
void log_data(FILE *fp, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(fp, "%ld,%d,%d,%d,%d,%d,%d\n", timestamp_ns, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int result;
    int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read IMU data
        if (spi_read_register(spi_handle, X_GYRO, &gyro_x) != 0 ||
            spi_read_register(spi_handle, Y_GYRO, &gyro_y) != 0 ||
            spi_read_register(spi_handle, Z_GYRO, &gyro_z) != 0 ||
            spi_read_register(spi_handle, X_ACCL, &accel_x) != 0 ||
            spi_read_register(spi_handle, Y_ACCL, &accel_y) != 0 ||
            spi_read_register(spi_handle, Z_ACCL, &accel_z) != 0) {
            fprintf(stderr, "Failed to read IMU data\n");
        } else {
            // Log the data
            log_data(log_file, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        }

        // Delay for approximately 10 ms (100 Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

