            spi_read_register(spi_handle, Y_ACCL, &accel_y) != 0 ||
            spi_read_register(spi_handle, Z_ACCL, &accel_z) != 0) {
            fprintf(stderr, "Failed to read IMU data\n");
        } else {
            // Log the data
            log_data(log_file, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        }

        // Delay for approximately 10 ms (100 Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

