#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// ADIS16266 Register Addresses
#define MSC_CTRL   0x24
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    3

// Chip Select GPIO Pin
#define CS_PIN 8

// Global Variables
int spi_handle;
int cs_gpio;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_spi();
int initialize_gpio();
int initialize_adis16266();
int read_adis16266_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_degrees_per_second(int16_t raw_data, float scale_factor, float *degrees_per_second);
void log_data(int16_t x_raw, int16_t y_raw, int16_t z_raw, float x_deg_per_sec, float y_deg_per_sec, float z_deg_per_sec);
void signal_handler(int signal);

// Signal Handler Function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize SPI Interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO for Chip Select
int initialize_gpio() {
    cs_gpio = gpioSetMode(CS_PIN, PI_OUTPUT);
    if (cs_gpio < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %d\n", CS_PIN, cs_gpio);
        return -1;
    }
    gpioWrite(CS_PIN, 1); // Deactivate CS initially
    return 0;
}

// Initialize ADIS16266
int initialize_adis16266() {
    // Enable data ready mode
    char tx_buf[2];
    tx_buf[0] = MSC_CTRL | 0x80; // Write command
    tx_buf[1] = 0x0004; // Enable data ready mode

    gpioWrite(CS_PIN, 0); // Activate CS
    int result = spiWrite(spi_handle, tx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    if (result < 0) {
        fprintf(stderr, "Error writing to MSC_CTRL register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read Data from ADIS16266
int read_adis16266_data(int16_t *x, int16_t *y, int16_t *z) {
    char tx_buf[3];
    char rx_buf[6];

    // Read X Gyro
    tx_buf[0] = X_GYRO_OUT | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Activate CS
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    if (result < 0) {
        fprintf(stderr, "Error reading X Gyro data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    // Read Y Gyro
    tx_buf[0] = Y_GYRO_OUT | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Activate CS
    result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    if (result < 0) {
        fprintf(stderr, "Error reading Y Gyro data: %d\n", result);
        return -1;
    }

    *y = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    // Read Z Gyro
    tx_buf[0] = Z_GYRO_OUT | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Activate CS
    result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    if (result < 0) {
        fprintf(stderr, "Error reading Z Gyro data: %d\n", result);
        return -1;
    }

    *z = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    return 0;
}

// Convert Raw Data to Degrees per Second
void convert_to_degrees_per_second(int16_t raw_data, float scale_factor, float *degrees_per_second) {
    *degrees_per_second = (float)raw_data * scale_factor;
}

// Log Data to Console
void log_data(int16_t x_raw, int16_t y_raw, int16_t z_raw, float x_deg_per_sec, float y_deg_per_sec, float z_deg_per_sec) {
    printf("X: %6d, Y: %6d, Z: %6d, X: %.2f, Y: %.2f, Z: %.2f\n",
           x_raw, y_raw, z_raw, x_deg_per_sec, y_deg_per_sec, z_deg_per_sec);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADIS16266
    if (initialize_adis16266() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x_raw, y_raw, z_raw;
    float x_deg_per_sec, y_deg_per_sec, z_deg_per_sec;

    // Main loop
    while (!terminate) {
        if (read_adis16266_data(&x_raw, &y_raw, &z_raw) == 0) {
            convert_to_degrees_per_second(x_raw, 0.02, &x_deg_per_sec);
            convert_to_degrees_per_second(y_raw, 0.02, &y_deg_per_sec);
            convert_to_degrees_per_second(z_raw, 0.02, &z_deg_per_sec);
            log_data(x_raw, y_raw, z_raw, x_deg_per_sec, y_deg_per_sec, z_deg_per_sec);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

