#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Sensitivity values
#define GYRO_SENSITIVITY 8.75f // dps/LSB
#define ACCEL_SENSITIVITY 0.061f // g/LSB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%X (expected 0x6B)\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x42) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    char buffer[12];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);

    if (bytes_read != 12) {
        fprintf(stderr, "Error reading sensor data: %d bytes read\n", bytes_read);
        return -1;
    }

    // Convert raw data to physical units
    *gyro_x = (float)((int16_t)((buffer[1] << 8) | buffer[0])) * GYRO_SENSITIVITY;
    *gyro_y = (float)((int16_t)((buffer[3] << 8) | buffer[2])) * GYRO_SENSITIVITY;
    *gyro_z = (float)((int16_t)((buffer[5] << 8) | buffer[4])) * GYRO_SENSITIVITY;
    *accel_x = (float)((int16_t)((buffer[7] << 8) | buffer[6])) * ACCEL_SENSITIVITY;
    *accel_y = (float)((int16_t)((buffer[9] << 8) | buffer[8])) * ACCEL_SENSITIVITY;
    *accel_z = (float)((int16_t)((buffer[11] << 8) | buffer[10])) * ACCEL_SENSITIVITY;

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
