#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700(int handle) {
    // Check WHO_AM_I register
    int who_am_i = i2c_read_byte(handle, WHO_AM_I);
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0xC7\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (hybrid mode, 100 Hz ODR)
    if (i2c_write_byte(handle, CTRL_REG1, 0x15) < 0) return -1; // Active mode, 100 Hz

    // Configure CTRL_REG2 (±2g range)
    if (i2c_write_byte(handle, CTRL_REG2, 0x00) < 0) return -1; // ±2g

    // Configure M_CTRL_REG1 (continuous conversion mode)
    if (i2c_write_byte(handle, M_CTRL_REG1, 0x1F) < 0) return -1; // Continuous conversion

    // Configure M_CTRL_REG2 (continuous conversion mode)
    if (i2c_write_byte(handle, M_CTRL_REG2, 0x00) < 0) return -1; // Continuous conversion

