        fprintf(stderr, "Error reading data block\n");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 6) | (buffer[1] >> 2));
    *accel_y = (int16_t)((buffer[2] << 6) | (buffer[3] >> 2));
    *accel_z = (int16_t)((buffer[4] << 6) | (buffer[5] >> 2));

    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

