#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt_angle(int16_t x, int16_t y);
void log_tilt_event(float angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Reads accelerometer data from the ADXL345
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char raw_data[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    *y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    *z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    return 0;
}

// Calculates the tilt angle in degrees
float calculate_tilt_angle(int16_t x, int16_t y) {
    float angle = atan2(y, x);
    return angle * 180.0 / M_PI;
}

// Logs a tilt event to the log file
void log_tilt_event(float angle) {
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", s, angle);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("ADXL345 Tilt Monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            // Calculate tilt angle
            float angle = calculate_tilt_angle(y, x);

            // Log tilt event if threshold is exceeded
            if (fabs(angle) > TILT_THRESHOLD) {
                log_tilt_event(angle);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

