    printf("ADXL345 Tilt Monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            // Calculate tilt angle
            float angle = calculate_tilt_angle(y, x);

            // Log tilt event if threshold is exceeded
            if (fabs(angle) > TILT_THRESHOLD) {
                log_tilt_event(angle);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

