#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Global variables
static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(int pin, const char *chip_name, const char *line_name);
int set_gpio_value(int pin, int value);
int get_gpio_value(int pin);
int generate_random_code(char *code);
int validate_code(const char *code);
int unlock_door(int pin);
int log_access(const char *code);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal %d, exiting gracefully...\n", signum);
    }
}

// Initialize GPIO pin
int initialize_gpio(int pin, const char *chip_name, const char *line_name) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chip_name, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, line_name, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Set GPIO pin value
int set_gpio_value(int pin, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(GPIO_CHIP, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", pin, strerror(errno));
        return -1;
    }

    return 0;
}

// Get GPIO pin value
int get_gpio_value(int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(GPIO_CHIP, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO line %d value: %s\n", pin, strerror(errno));
        return -1;
    }

    return value;
}

// Generate random 6-digit code
int generate_random_code(char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Code buffer is NULL\n");
        return -1;
    }

    for (int i = 0; i < 6; i++) {
        code[i] = '0' + (rand() % 10);
    }
    return 0;
}

// Validate code
int validate_code(const char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Code buffer is NULL\n");
        return -1;
    }

    if (strlen(code) != 6) {
        fprintf(stderr, "Error: Invalid code length. Must be exactly 6 digits.\n");
        return -1;
    }

    char *endptr;
    long num = strtol(code, &endptr, 10);

    if (*endptr != '\0' || num < 100000 || num > 999999) {
        fprintf(stderr, "Error: Invalid code. Must be between 100000 and 999999.\n");
        return -1;
    }

    return 0;
}

// Unlock door
int unlock_door(int pin) {
    if (set_gpio_value(pin, 0) < 0) {
        fprintf(stderr, "Error de-energizing door lock.\n");
        return -1;
    }
    return 0;
}

// Log access
int log_access(const char *code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is NULL\n");
        return -1;
    }

    fprintf(log_file, "%s,%s\n", timestamp, code);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize GPIO pins
    if (initialize_gpio(DOOR_A_PIN, GPIO_CHIP, "door_a") < 0) {
        fprintf(stderr, "Error initializing GPIO %d\n", DOOR_A_PIN);
        return 1;
    }
    if (initialize_gpio(DOOR_B_PIN, GPIO_CHIP, "door_b") < 0) {
        fprintf(stderr, "Error initializing GPIO %d\n", DOOR_B_PIN);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char code[6];
    int code_valid = 0;

    printf("Enter the security code: ");
    while (program_running) {
        if (fgets(code, sizeof(code), stdin) != NULL) {
            // Remove trailing newline character
            code[strcspn(code, "\n")] = 0;

            if (validate_code(code) == 0) {
                code_valid = 1;
                printf("Code entered correctly: %s\n", code);
                if (unlock_door(DOOR_A_PIN) == 0) {
                    printf("Door A unlocked for 5 seconds.\n");
                    log_access(code);
                    generate_random_code(code);
                    printf("New code: %s\n", code);
                } else {
                    fprintf(stderr, "Error unlocking door A.\n");
                }
            } else {
                printf("Invalid code. Please enter a 6-digit code between 100000 and 999999.\n");
            }
        } else {
            // Clear the input buffer if an error occurs
            while (fgets(code, sizeof(code), stdin) != NULL);
            if (feof(stdin)) {
                printf("End of file reached. Exiting.\n");
                program_running = 0;
            } else {
                // Clear the buffer if there was an error reading from stdin
                rewind(stdin);
                // Attempt to read again
            }
        }
    }

    // Cleanup
    set_gpio_value(DOOR_A_PIN, 1); // Lock Door A
    set_gpio_value(DOOR_B_PIN, 1); // Lock Door B
    gpiod_chip_close(GPIO_CHIP);
    fclose(log_file);

    printf("Program finished.\n");
    return 0;
}

