#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define HIGH_RES_MODE 0x10
#define LOG_FILE "light_log.txt"

static volatile int keep_running = 1;

void int_handler(int dummy) {
    keep_running = 0;
}

// Function to write a byte to the I2C device
int i2c_write(int fd, uint8_t addr, uint8_t data) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error: ioctl(I2C_SLAVE) failed");
        return -1;
    }
    if (write(fd, &data, 1) != 1) {
        perror("Error: write failed");
        return -1;
    }
    return 0;
}

// Function to read a byte from the I2C device
int i2c_read(int fd, uint8_t addr, uint8_t *data) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error: ioctl(I2C_SLAVE) failed");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Error: read failed");
        return -1;
    }
    return 0;
}

// Function to initialize the BH1750 sensor
int init_bh1750(int fd) {
    if (i2c_write(fd, BH1750_ADDR, HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error: Failed to set high-resolution mode.\n");
        return -1;
    }
    return 0;
}

// Function to read the illuminance value from the BH1750 sensor
float read_illuminance(int fd) {
    uint8_t buffer[2];
    if (i2c_read(fd, BH1750_ADDR, buffer) < 0) {
        fprintf(stderr, "Error: Failed to read illuminance data.\n");
        return -1.0;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    return (raw_value * 5) / 6.0;
}

// Function to log the illuminance value to a file
int log_illuminance(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error: Failed to open log file.");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main() {
    int fd;
    float lux;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, int_handler);

    // Open the I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    // Initialize the BH1750 sensor
    if (init_bh1750(fd) < 0) {
        fprintf(stderr, "Error: Failed to initialize BH1750 sensor.\n");
        close(fd);
        return 1;
    }

    printf("BH1750 sensor initialized. Reading illuminance every 5 seconds...\n");

    while (keep_running) {
        // Read the illuminance value
        lux = read_illuminance(fd);

        if (lux >= 0) {
            // Log the illuminance value
            if (log_illuminance(lux) < 0) {
                fprintf(stderr, "Error: Failed to log illuminance value.\n");
            }
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error: Failed to read illuminance value.\n");
        }

        sleep(5);
    }

    printf("Exiting...\n");

    // Close the I2C bus
    close(fd);

    return 0;
}

