#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PWM_FREQ 440
#define PWM_DUTY 500000 // 50% duty cycle (0-1000000)
#define TCP_PORT 12345
#define MOTION_DETECTED_PREFIX "MOTION_DETECTED:"
#define SECRET_KEY "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define I2C_BUS 1
#define NUM_ELECTRODES 12

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_data(unsigned short *touch_data);
float map_touch_to_frequency(unsigned short touch_data);
void generate_tone(float frequency);
void handle_client(int client_socket);
void log_frequency(float frequency);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure Electrode Configuration (ECR) register
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Enable all 12 electrodes
        fprintf(stderr, "Error: ECR configuration failed\n");
        return -1;
    }

    // Configure Touch and Release Thresholds (0x41 - 0x52, 0x53 - 0x5A)
    for (int i = 0x41; i <= 0x5A; i++) {
        if (i2cWriteByteData(i2c_handle, i, 0x0F) < 0) { // Touch threshold
            fprintf(stderr, "Error: Touch threshold configuration failed\n");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, i + 12, 0x0A) < 0) { // Release threshold
            fprintf(stderr, "Error: Release threshold configuration failed\n");
            return -1;
        }
    }

    // Configure Filter Control Register (FCR) (0x5B)
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Enable filter
        fprintf(stderr, "Error: Filter configuration failed\n");
        return -1;
    }

    // Configure Electrode Filter Configuration (EFC) (0x5C)
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) { // Enable filter
        fprintf(stderr, "Error: EFC configuration failed\n");
        return -1;
    }

    // Configure Global Sensing Enable (0x5D)
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x24) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Global sensing enable failed\n");
        return -1;
    }

    return 0;
}

// Read touch data from MPR121
int read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }

    *touch_data = ((unsigned short)buf[1] << 8) | (unsigned short)buf[0];
    return 0;
}

// Map touch data to frequency using a logarithmic scale
float map_touch_to_frequency(unsigned short touch_data) {
    float max_touch = 0.0f;
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (touch_data & (1 << i)) {
            max_touch = fmax(max_touch, (float)i); // Assuming electrode number is proportional to touch strength
        }
    }

    float frequency = PWM_FREQ * (1.0f - log10(max_touch + 1.0f) / log10(12.0f)) + 220.0f;
    return frequency;
}

// Generate a tone using hardware PWM
void generate_tone(float frequency) {
    int duty_cycle = (int)(PWM_DUTY * frequency / 880.0f);
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        printf("Received: %s\n", buffer);

        if (strncmp(buffer, MOTION_DETECTED_PREFIX, strlen(MOTION_DETECTED_PREFIX)) == 0) {
            if (strstr(buffer, SECRET_KEY) != NULL) {
                printf("Secret key found, playing theremin...\n");
                unsigned short touch_data;
                if (read_touch_data(&touch_data) == 0) {
                    float frequency = map_touch_to_frequency(touch_data);
                    generate_tone(frequency);
                    log_frequency(frequency);
                } else {
                    fprintf(stderr, "Error reading touch data during theremin\n");
                }
            } else {
                fprintf(stderr, "Incorrect secret key\n");
            }
        } else {
            fprintf(stderr, "Invalid message format\n");
        }
    }

    if (bytes_received == 0) {
        printf("Client disconnected\n");
    } else if (bytes_received < 0) {
        perror("recv failed");
    }
    close(client_socket);
}

// Log frequency to file
void log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure PWM
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, 1000000); // Set range to 1000000 for percentage

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", TCP_PORT);

    // Main loop
    while (!terminate) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        int client_socket;
        unsigned short touch_data;
        float frequency;

        // Accept connection
        if ((client_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len)) < 0) {
            perror("accept failed");
            continue; // Continue listening for other connections
        }

        handle_client(client_socket);

        // Play theremin every 5 seconds
        time_t now = time(NULL);
        if (now % 5 == 0) {
            if (read_touch_data(&touch_data) == 0) {
                frequency = map_touch_to_frequency(touch_data);
                generate_tone(frequency);
                log_frequency(frequency);
            } else {
                fprintf(stderr, "Error reading touch data during theremin\n");
            }
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    close(server_fd);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

