#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define OUT_X_H_M 0x09
#define OUT_Y_L_M 0x0A
#define OUT_Y_H_M 0x0B
#define OUT_Z_L_M 0x0C
#define OUT_Z_H_M 0x0D

// GPIO pin for LED
#define LED_PIN 17

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg, uint8_t *value);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int initialize_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t z);
int set_led_brightness(int brightness);
void signal_handler(int sig);
void cleanup();

// I2C read register function
int i2c_read_register(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }

    return 0;
}

// I2C block read function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

// Initialize magnetometer
int initialize_magnetometer(int fd) {
    if (i2c_write_register(fd, CTRL_REG1_M, 0x18) != 0) {
        fprintf(stderr, "Error initializing magnetometer.\n");
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (i2c_read_block(fd, OUT_X_L_M, data, 6) != 0) {
        fprintf(stderr, "Error reading magnetometer data.\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Calculate Z-axis magnitude
double calculate_magnitude(int16_t z) {
