// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_X_MSB 0x03
#define DATA_X_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define DATA_Y_MSB 0x07
#define DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Hard-iron offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int initialize_hmc5883l();
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z);
void apply_hard_iron_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x_offset, float *y_offset, float *z_offset, float *corrected_x, float *corrected_y, float *corrected_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Configuration Register A: 8-sample averaging, 15 Hz output rate, Gain = 1.3 Gauss
    uint8_t config_a_value = 0x70; // 0b01110000
    if (i2cWriteByteData(i2c_handle, CONFIG_A, config_a_value) != 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }

    // Configuration Register B: Gain = 1.3 Gauss
    uint8_t config_b_value = 0x20; // 0b00010100
    if (i2cWriteByteData(i2c_handle, CONFIG_B, config_b_value) != 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }

    // Mode Register: Continuous measurement mode
    uint8_t mode_value = 0x00;
    if (i2cWriteByteData(i2c_handle, MODE, mode_value) != 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Function to read raw data from the HMC5883L
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading data from HMC5883L\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to apply hard-iron offsets
void apply_hard_iron_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x_offset, float *y_offset, float *z_offset, float *corrected_x, float *corrected_y, float *corrected_z) {
    *corrected_x = (float)raw_x - *x_offset;
    *corrected_y = (float)raw_y - *y_offset;
    *corrected_z = (float)raw_z - *z_offset;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() != 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float corrected_x, corrected_y, corrected_z;
    int sample_count = 0;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_hmc5883l(&raw_x, &raw_y, &raw_z) == 0) {
            // Apply hard-iron offsets
            apply_hard_iron_offsets(raw_x, raw_y, raw_z, &x_offset, &y_offset, &z_offset, &corrected_x, &corrected_y, &corrected_z);

            // Update running average of hard-iron offsets
            x_offset += corrected_x;
            y_offset += corrected_y;
            z_offset += corrected_z;
            sample_count++;

            // Print corrected values every 500ms
            if (sample_count >= 100) {
                printf("X: %.2f, Y: %.2f, Z: %.2f\n", corrected_x, corrected_y, corrected_z);
                sample_count = 0;
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(500); // Delay for 500ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

