// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define INT1_CFG 0x30
#define OUT_X_L_A 0x28

// GPIO pin for INT1 interrupt
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer
accelerometer_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_lsm303d();
int read_acceleration(accelerometer_data_t *data);
void add_to_buffer(accelerometer_data_t data);
void print_buffer();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0); // Open I2C bus 1, device address 0x1D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the LSM303D
int init_lsm303d() {
    // Verify WHO_AM_I register
    int who_am_i = i2c_smbus_read_byte_data(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1_A for 50 Hz ODR and enable all axes
    if (i2c_smbus_write_byte_data(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // Configure CTRL_REG4_A for +-2g full-scale
    if (i2c_smbus_write_byte_data(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
