#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define GPIO chip
#define GPIO_CHIP "gpiochip0"

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int request_gpio_line(int gpio_pin, const char *consumer_label);
int set_gpio_value(int gpio_line, int value);
int unexport_gpio_line(int gpio_line);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully.\n", signum);
        program_running = 0;
        unexport_gpio_line(SOLENOID_1_PIN);
        unexport_gpio_line(SOLENOID_2_PIN);
        exit(0);
    }
}

// Function to request a GPIO line
int request_gpio_line(int gpio_pin, const char *consumer_label) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_pin);
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request(line, consumer_label, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %d\n", gpio_pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(int gpio_line, int value) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_line);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d value: %d\n", gpio_line, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to unexport a GPIO line
int unexport_gpio_line(int gpio_line) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_line);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_unexport(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not unexport GPIO line %d: %d\n", gpio_line, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    if (request_gpio_line(SOLENOID_1_PIN, "solenoid1") < 0) {
        fprintf(stderr, "Failed to initialize solenoid 1 GPIO line.\n");
        return 1;
    }
    if (request_gpio_line(SOLENOID_2_PIN, "solenoid2") < 0) {
        fprintf(stderr, "Failed to initialize solenoid 2 GPIO line.\n");
        unexport_gpio_line(SOLENOID_1_PIN);
        return 1;
    }

    // Set initial state (both solenoids off)
    if (set_gpio_value(SOLENOID_1_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set solenoid 1 to LOW.\n");
        unexport_gpio_line(SOLENOID_1_PIN);
        unexport_gpio_line(SOLENOID_2_PIN);
        return 1;
    }
    if (set_gpio_value(SOLENOID_2_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set solenoid 2 to LOW.\n");
        unexport_gpio_line(SOLENOID_1_PIN);
        unexport_gpio_line(SOLENOID_2_PIN);
        return 1;
    }

    printf("Actuator simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Energize solenoid 1
        if (set_gpio_value(SOLENOID_1_PIN, 1) < 0) {
            fprintf(stderr, "Failed to energize solenoid 1.\n");
            break;
        }
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 500000000}, NULL); // 500 ms

        // De-energize solenoid 1 and energize solenoid 2
        if (set_gpio_value(SOLENOID_1_PIN, 0) < 0) {
            fprintf(stderr, "Failed to de-energize solenoid 1.\n");
            break;
        }
        if (set_gpio_value(SOLENOID_2_PIN, 1) < 0) {
            fprintf(stderr, "Failed to energize solenoid 2.\n");
            break;
        }
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 500000000}, NULL); // 500 ms

        // De-energize solenoid 2
        if (set_gpio_value(SOLENOID_2_PIN, 0) < 0) {
            fprintf(stderr, "Failed to de-energize solenoid 2.\n");
            break;
        }
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 500000000}, NULL); // 500 ms
    }

    // Clean up GPIO lines before exiting
    unexport_gpio_line(SOLENOID_1_PIN);
    unexport_gpio_line(SOLENOID_2_PIN);

    printf("Actuator simulation stopped.\n");

    return 0;
}

