// Define GPIO pins for door locks
#define DOOR1_LOCK_PIN 17
#define DOOR2_LOCK_PIN 27

// Define UART ports
#define PRIMARY_UART "/dev/serial0"
#define SECONDARY_UART "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout duration (seconds)
#define TIMEOUT_DURATION 5

// Define unlock duration (seconds)
#define UNLOCK_DURATION 2

// Global variables
volatile sig_atomic_t program_running = 1;
int primary_uart_fd = -1;
int secondary_uart_fd = -1;

// Function prototypes
int initialize_gpio();
int initialize_uart(const char *port);
int read_serial_port(int fd, char *buffer, int max_length);
int validate_code(const char *code);
void unlock_doors();
void relock_doors();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DOOR1_LOCK_PIN, PI_OUTPUT);
    gpioSetMode(DOOR2_LOCK_PIN, PI_OUTPUT);

    gpioWrite(DOOR1_LOCK_PIN, 0);
    gpioWrite(DOOR2_LOCK_PIN, 0);

    return 0;
}

