#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define relay strike duration (seconds)
#define STRIKE_DURATION 1

// Define failsafe timeout (seconds)
#define FAILSAFE_TIMEOUT 10

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int request_gpio_line(struct gpiod_chip *chip, int pin, const char *consumer, struct gpiod_line **line);
int set_gpio_value(struct gpiod_line *line, int value);
int read_gpio_value(struct gpiod_line *line);
void motion_detected_callback(void *user_data);
void relay_on(void);
void relay_off(void);
void failsafe_timeout_handler(void);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO
int initialize_gpio(void) {
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting door strike system");

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    pir_line = request_gpio_line(chip, PIR_PIN, "door_strike", &relay_line);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to request PIR line");
        cleanup();
        return -1;
    }

    relay_line = request_gpio_line(chip, RELAY_PIN, "door_strike", NULL);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to request relay line");
        cleanup();
        return -1;
    }

    syslog(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Function to request a GPIO line
int request_gpio_line(struct gpiod_chip *chip, int pin, const char *consumer, struct gpiod_line **line) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = consumer;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT; // For PIR sensor
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT; // For relay

    int ret = gpiod_chip_add_line(chip, pin, &config, line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to add line %d: %d", pin, ret);
        return -1;
    }

    return 0;
}

// Function to set GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set GPIO value: %d", ret);
        return -1;
    }
    return 0;
}

// Function to read GPIO value
int read_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read GPIO value: %d", value);
        return -1;
    }
    return value;
}

// Callback function for motion detection
void motion_detected_callback(void *user_data) {
    (void)user_data; // Suppress unused parameter warning
    syslog(LOG_INFO, "Motion detected!");
    relay_on();
}

// Function to energize the relay
void relay_on(void) {
    if (set_gpio_value(relay_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to energize relay");
        return;
    }
    syslog(LOG_INFO, "Relay energized");
}

// Function to de-energize the relay
void relay_off(void) {
    if (set_gpio_value(relay_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to de-energize relay");
        return;
    }
    syslog(LOG_INFO, "Relay de-energized");
}

// Failsafe timeout handler
void failsafe_timeout_handler(void) {
    syslog(LOG_WARNING, "Failsafe timeout triggered! De-energizing relay.");
    relay_off();
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up GPIO resources...");
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Request PIR line as input
    if (request_gpio_line(chip, PIR_PIN, "door_strike", &pir_line) < 0) {
        cleanup();
        return 1;
    }

    // Request relay line as output
    if (request_gpio_line(chip, RELAY_PIN, "door_strike", &relay_line) < 0) {
        cleanup();
        return 1;
    }

    // Set up motion detection callback
    struct gpiod_line_event event;
    memset(&event, 0, sizeof(event));
    event.consumer = "door_strike";
    event.callback = motion_detected_callback;

    if (gpiod_line_request_event(pir_line, &event) < 0) {
        syslog(LOG_ERR, "Failed to request event on PIR line");
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Door strike system started");

    // Main loop
    while (!terminate) {
        int pir_value = read_gpio_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR value, exiting");
            break;
        }

        if (pir_value == 1) {
            relay_on();
        } else {
            relay_off();
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

