#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the relay activation duration (in seconds)
#define RELAY_DURATION 300

// Define the pause duration (in seconds)
#define PAUSE_DURATION 60

// Define the timer interval (in seconds)
#define TIMER_INTERVAL 60

// Define the state machine states
typedef enum {
    STATE_RELAY1,
    STATE_RELAY2,
    STATE_RELAY3,
    STATE_RELAY4,
    STATE_PAUSE
} state_t;

// Global variables
static volatile state_t current_state = STATE_RELAY1;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
void relay_on(int gpio_pin);
void relay_off(int gpio_pin);
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to turn a relay ON (active-LOW)
