#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <math.h>

// MPU6050 Registers
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

// I2C Device Path
#define I2C_DEVICE "/dev/i2c-1"

// Circular Buffer Size
#define BUFFER_SIZE 100

// Structure to hold acceleration data
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Circular Buffer Structure
typedef struct {
    AccelData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

// Global Variables
int i2c_fd = -1;
CircularBuffer buffer;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_mpu6050(int fd);
AccelData read_acceleration(int fd);
void buffer_init(CircularBuffer *buffer);
void buffer_add(CircularBuffer *buffer, AccelData data);
AccelData buffer_get_latest(CircularBuffer *buffer);
void signal_handler(int signal);
int create_circular_buffer(CircularBuffer *buffer);
void uninitialize_circular_buffer(CircularBuffer *buffer);

// I2C Read Function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// I2C Write Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// MPU6050 Initialization Function
int init_mpu6050(int fd) {
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake MPU6050\n");
        return -1;
    }
    if (i2c_write_reg(fd, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return -1;
    }
    return 0;
}

// Read Acceleration Data Function
AccelData read_acceleration(int fd) {
    uint8_t buffer[6];
    AccelData data;

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read acceleration data");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    int16_t raw_x = (buffer[0] << 8) | buffer[1];
    int16_t raw_y = (buffer[2] << 8) | buffer[3];
    int16_t raw_z = (buffer[4] << 8) | buffer[5];

    data.x = (float)raw_x / 16384.0;
    data.y = (float)raw_y / 16384.0;
    data.z = (float)raw_z / 16384.0;

    return data;
}

// Circular Buffer Initialization Function
void buffer_init(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

// Circular Buffer Add Function
void buffer_add(CircularBuffer *buffer, AccelData data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Circular Buffer Get Latest Function
AccelData buffer_get_latest(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return AccelData(0.0, 0.0, 0.0);
    }
    int index = (buffer->tail + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[index];
}

// Signal Handler Function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Circular Buffer Creation Function
int create_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    return 0;
}

// Circular Buffer Destruction Function
void uninitialize_circular_buffer(CircularBuffer *buffer) {
    // No need to free memory, just set to empty state
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Create circular buffer
    create_circular_buffer(&buffer);

    // Create sysfs interface
    char buffer_path[256];
    snprintf(buffer_path, sizeof(buffer_path), "/sys/kernel/mpu6050_accel/latest");
    FILE *fp = fopen(buffer_path, "w");
    if (fp == NULL) {
        perror("Failed to create sysfs interface");
        close(i2c_fd);
        return 1;
    }
    fclose(fp);

    // Main loop
    struct sigaction sa;
    struct itimerspec timer_spec;
    struct timespec now;
    AccelData accel_data;
    int i2c_address = 0x68; // Default I2C address

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        perror("sigaction");
        close(i2c_fd);
        return 1;
    }

    // Set up timer using POSIX timer
    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = 10000000; // 10ms
    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = 10000000; // 10ms

    if (timer_settime(0, 0, &timer_spec, NULL) == -1) {
        perror("timer_settime");
        close(i2c_fd);
        return 1;
    }

    while (program_running) {
        // Read acceleration data
        accel_data = read_acceleration(i2c_fd);

        // Add data to circular buffer
        buffer_add(&buffer, accel_data);

        // Write data to sysfs interface
        fp = fopen(buffer_path, "w");
        if (fp != NULL) {
            fprintf(fp, "%f,%f,%f\n", accel_data.x, accel_data.y, accel_data.z);
            fclose(fp);
        } else {
            perror("Failed to write to sysfs interface");
        }

        // Sleep for 10ms
        nanosleep(&timer_spec, NULL);
    }

    // Clean up
    close(i2c_fd);
    uninitialize_circular_buffer(&buffer);
    fp = fopen(buffer_path, "w");
    if (fp != NULL) {
        fclose(fp);
    }

    return 0;
}

