#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to store the GPIO line handle
struct gpiod_line *relay1_line = NULL;
struct gpiod_line *relay2_line = NULL;
struct gpiod_line *relay3_line = NULL;
struct gpiod_line *relay4_line = NULL;

// Function prototypes
int initialize_gpio(int pin);
int set_relay_state(int pin, int state);
int toggle_relay(int pin);
int get_interval(int *interval);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, cleaning up...\n", signum);

        // Turn off all relays
        set_relay_state(RELAY1_PIN, 0);
        set_relay_state(RELAY2_PIN, 0);
        set_relay_state(RELAY3_PIN, 0);
        set_relay_state(RELAY4_PIN, 0);

        // Release GPIO lines
        if (relay1_line) {
            gpiod_line_release(relay1_line);
        }
        if (relay2_line) {
            gpiod_line_release(relay2_line);
        }
        if (relay3_line) {
            gpiod_line_release(relay3_line);
        }
        if (relay4_line) {
            gpiod_line_release(relay4_line);

        }

        exit(0);
    }
}

// Function to initialize a GPIO pin as output
int initialize_gpio(int pin) {
