#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define alarm duration (seconds)
#define ALARM_DURATION 3

// Define debounce time (seconds)
#define DEBOUNCE_TIME 1

// Global variables
static volatile int alarm_active = 0;
static volatile unsigned long last_activation_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void deactivate_relay();
void log_alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    deactivate_relay();
    gpioTerminate();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0; // Indicate success
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the relay
void activate_relay() {
    if (!alarm_active) {
        gpioWrite(RELAY_PIN, 1); // Activate relay
        alarm_active = 1;
        last_activation_time = gpioTick();
        printf("Alarm activated!\n");
    }
}

// Function to deactivate the relay
void deactivate_relay() {
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    alarm_active = 0;
    printf("Alarm deactivated!\n");
}

// Function to log the alarm event
void log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: Alarm triggered\n", timestamp);
    fclose(fp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Sound-activated alarm system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            // Check for debouncing
            unsigned long current_time = gpioTick();
            if (current_time - last_activation_time > (DEBOUNCE_TIME * 1000000)) { // Convert seconds to microseconds
                activate_relay();
                log_alarm();
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

