#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Gyroscope sensitivity (LSB/deg/s) for +-250 dps range
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define THRESHOLD 50.0

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t gyro_buffer;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int initialize_mpu6050(int fd);
int read_gyro_data(int fd, float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z);
float calculate_magnitude(float x, float y, float z);
void check_threshold(float magnitude);
void signal_handler(int sig);

// I2C read function
int i2c_read_register(int fd, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;

    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buffer, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return buffer[0];
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;

    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int initialize_mpu6050(int fd) {
    // Wake up the MPU-6050
    if (i2c_write_register(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2c_read_register(fd, WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
        return -1;
    }

    printf("MPU-6050 initialized successfully\n");
    return 0;
}

// Read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    // Read raw gyroscope data
    int x_h = i2c_read_register(fd, GYRO_XOUT_H);
    int x_l = i2c_read_register(fd, GYRO_XOUT_H + 1);
    int y_h = i2c_read_register(fd, GYRO_YOUT_H);
    int y_l = i2c_read_register(fd, GYRO_YOUT_H + 1);
    int z_h = i2c_read_register(fd, GYRO_ZOUT_H);
    int z_l = i2c_read_register(fd, GYRO_ZOUT_H + 1);

    if (x_h == -1 || x_l == -1 || y_h == -1 || y_l == -1 || z_h == -1 || z_l == -1) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    // Combine high and low bytes
    raw_x = (int16_t)((x_h << 8) | x_l);
    raw_y = (int16_t)((y_h << 8) | y_l);
    raw_z = (int16_t)((z_h << 8) | z_l);

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate angular velocity magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Check if threshold is exceeded
void check_threshold(float magnitude) {
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f\n", magnitude);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("Exiting gracefully...\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (initialize_mpu6050(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    float x, y, z;
    float magnitude;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, x, y, z);

            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check threshold
            check_threshold(magnitude);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        // Delay
        usleep(10000); // 10ms
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

