#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define READ_COMMAND_LENGTH 9
#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define TIMEOUT_MS 1000
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"

// Global variables for signal handling
static volatile int running = 1;
static int uart_handle = -1;
static FILE *co2_log_fp = NULL;
static FILE *error_log_fp = NULL;

// Structure to hold sensor data
typedef struct {
    int ppm;
    int error_flag;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_uart(const char *device, int baud_rate);
int send_command(int uart_handle, const unsigned char *command, int command_length);
int read_sensor_data(int uart_handle, unsigned char *buffer, int buffer_length);
int validate_checksum(const unsigned char *data, int data_length);
int extract_ppm(const unsigned char *data, int data_length);
int log_data(const SensorData *data);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Open UART port
int open_uart(const char *device, int baud_rate) {
    int handle = serOpen(device, baud_rate, 0); // 0 for default flags
    if (handle < 0) {
        log_error("Failed to open UART port");
        return -1;
    }
    return handle;
}

// Send command to the sensor
int send_command(int uart_handle, const unsigned char *command, int command_length) {
    int bytes_written = serWrite(uart_handle, command, command_length);
    if (bytes_written != command_length) {
        log_error("Failed to send command");
        return -1;
    }
    gpioDelay(100); // Wait 100ms
    return 0;
}

// Read data from the sensor
int read_sensor_data(int uart_handle, unsigned char *buffer, int buffer_length) {
    int bytes_read = serDataAvailable(uart_handle);
    if (bytes_read < 0) {
        log_error("Error reading from UART");
        return -1;
    }

    if (bytes_read > buffer_length) {
        log_error("Buffer too small for data received");
        return -1;
    }

    for (int i = 0; i < bytes_read; ++i) {
        buffer[i] = serReadByte(uart_handle);
        if (buffer[i] < 0) {
            log_error("Error reading byte from UART");
            return -1;
        }
    }

    return bytes_read;
}

// Validate checksum
int validate_checksum(const unsigned char *data, int data_length) {
    unsigned char checksum = data[8];
    unsigned char sum = 0;
    for (int i = 0; i < data_length - 1; ++i) {
        sum += data[i];
    }
    sum = ~sum + 1; // Convert to unsigned

    if (checksum != (sum ^ 0xFF)) {
        log_error("Checksum validation failed");
        return -1;
    }

    return 0;
}

// Extract CO2 concentration from sensor data
int extract_ppm(const unsigned char *data, int data_length) {
    if (data_length != 9) {
        log_error("Invalid data length");
        return -1;
    }

    unsigned int raw_ppm = (data[2] << 8) | data[3];
    return (int)raw_ppm;
}

// Log data to JSON file
int log_data(const SensorData *data) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long tv_sec = tv.tv_sec;
    long tv_usec = tv.tv_usec;

    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv_sec, tv_usec);

    if (co2_log_fp == NULL) {
        co2_log_fp = fopen(CO2_LOG_FILE, "a");
        if (co2_log_fp == NULL) {
            log_error("Failed to open CO2 log file");
            return -1;
        }
    }

    fprintf(co2_log_fp, "{\"timestamp\": \"%s\", \"ppm\": %d, \"error_flag\": %d}\n",
            timestamp, data->ppm, data->error_flag);
    fflush(co2_log_fp);

    printf("{\"timestamp\": \"%s\", \"ppm\": %d, \"error_flag\": %d}\n",
           timestamp, data->ppm, data->error_flag);

    return 0;
}

// Log errors to error log file
void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long tv_sec = tv.tv_sec;
    long tv_usec = tv.tv_usec;

    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv_sec, tv_usec);

    if (error_log_fp == NULL) {
        error_log_fp = fopen(ERROR_LOG_FILE, "a");
        if (error_log_fp == NULL) {
            perror("Failed to open error log file");
            return;
        }
    }

    fprintf(error_log_fp, "%s: %s\n", timestamp, message);
    fflush(error_log_fp);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (co2_log_fp != NULL) {
        fclose(co2_log_fp);
    }
    if (error_log_fp != NULL) {
        fclose(error_log_fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open UART port
    uart_handle = open_uart(UART_DEVICE, BAUD_RATE);
    if (uart_handle < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        unsigned char buffer[9];
        int bytes_read = read_sensor_data(uart_handle, buffer, sizeof(buffer));

        if (bytes_read > 0) {
            if (validate_checksum(buffer, bytes_read) == 0) {
                int ppm = extract_ppm(buffer, bytes_read);
                if (ppm >= 0) {
                    SensorData data = {ppm, 0};
                    log_data(&data);
                } else {
                    data = {0, 1};
                    log_data(&data);
                }
            } else {
                data = {0, 1};
                log_data(&data);
            }
        } else if (bytes_read < 0) {
            data = {0, 1};
            log_data(&data);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

