    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t heading_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_hmc5883l();
magnetometer_data_t read_magnetometer_data();
float calculate_heading(magnetometer_data_t data);
void update_gpio(float heading);
void update_circular_buffer(magnetometer_data_t data);
void signal_handler(int signal);

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Configure register 0x00 (CONFIG_A)
    if (i2cWriteByteData(i2c_handle, CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }

    // Configure register 0x01 (CONFIG_B)
    if (i2cWriteByteData(i2c_handle, CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }

    // Configure register 0x02 (MODE)
    if (i2cWriteByteData(i2c_handle, MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    char buffer[6];
    magnetometer_data_t data;

    if (i2cReadI2CBlockData(i2c_handle, DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0.0; // Return default values in case of error
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine MSB and LSB for each axis
    int16_t x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t z = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t y = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to float (assuming microteslas)
    data.x = (float)x;
    data.y = (float)y;
    data.z = (float)z;

    return data;
}

// Function to calculate heading in degrees
float calculate_heading(magnetometer_data_t data) {
    float heading = atan2(data.y, data.x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to update GPIO based on heading deviation
void update_gpio(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);
    if (deviation > 10.0) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

// Function to update the circular buffer
void update_circular_buffer(magnetometer_data_t data) {
    heading_buffer.data[heading_buffer.head] = data;
    heading_buffer.head = (heading_buffer.head + 1) % BUFFER_SIZE;
    if (heading_buffer.count < BUFFER_SIZE) {
        heading_buffer.count++;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize circular buffer
    heading_buffer.head = 0;
    heading_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data();

        // Calculate heading
        float heading = calculate_heading(data);

        // Update GPIO
        update_gpio(heading);

        // Update circular buffer
        update_circular_buffer(data);

        // Print heading (for debugging)
        printf("Heading: %.2f degrees\n", heading);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

