#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address for BH1750 sensor
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds for relay control
#define LUX_THRESHOLD_RED 50
#define LUX_THRESHOLD_GREEN 50
#define LUX_THRESHOLD_BLUE 150
#define LUX_THRESHOLD_ALL 300

// Define log file name
#define LOG_FILE "lighting_log.txt"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_gpio(int pin);
int set_gpio_value(int pin, int value);
int read_bh1750(int fd, float *lux);
int control_relay(int pin, int state);
int log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int sig);

// Function to initialize I2C communication
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize a GPIO pin as output
int init_gpio(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_number(0); // Open GPIO chip 0
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "lighting_system", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return line;
}

// Function to set the value of a GPIO pin (0 or 1)
int set_gpio_value(int pin, int value) {
    if (pin != RED_RELAY_PIN && pin != GREEN_RELAY_PIN && pin != BLUE_RELAY_PIN) {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", pin);
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid GPIO value: %d\n", value);
        return -1;
    }

    if (red_line == NULL) red_line = gpiod_chip_get_line(gpio_chip, RED_RELAY_PIN);
    if (green_line == NULL) green_line = gpiod_chip_get_line(gpio_chip, GREEN_RELAY_PIN);
    if (blue_line == NULL) blue_line = gpiod_chip_get_line(gpio_chip, BLUE_RELAY_PIN);

    if (red_line) gpiod_line_set_value(red_line, value);
    if (green_line) gpiod_line_set_value(green_line, value);
    if (blue_line) gpiod_line_set_value(blue_line, value);

    return 0;
}

// Function to read ambient light from BH1750 sensor
int read_bh1750(int fd, float *lux) {
    unsigned char buf[2];
    int retries = 3;

    while (retries > 0) {
        if (read(fd, buf, 2) == 2) {
            unsigned int raw_value = (buf[0] << 8) | buf[1];
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(100000); // Wait 100ms before retrying
        }
    }

    return -1; // Failure after multiple retries
}

// Function to control the state of a relay (0 or 1)
int control_relay(int pin, int state) {
    if (pin != RED_RELAY_PIN && pin != GREEN_RELAY_PIN && pin != BLUE_RELAY_PIN) {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", pin);
        return -1;
    }

    if (set_gpio_value(pin, state) != 0) {
        fprintf(stderr, "Error setting GPIO value for pin %d\n", pin);
        return -1;
    }

    return 0;
}

// Function to log data to a file
int log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%d,%d,%d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_number(0);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(i2c_fd);
        return 1;
    }

    red_line = init_gpio(RED_RELAY_PIN);
    green_line = init_gpio(GREEN_RELAY_PIN);
    blue_line = init_gpio(BLUE_RELAY_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    float lux;
    int red_state = 0, green_state = 0, blue_state = 0;

    // Main loop
    while (!terminate) {
        // Read ambient light
        if (read_bh1750(i2c_fd, &lux) == 0) {
            // Control relays based on lux value
            if (lux < LUX_THRESHOLD_RED) {
                red_state = 1;
                green_state = 0;
                blue_state = 0;
            } else if (lux >= LUX_THRESHOLD_RED && lux < LUX_THRESHOLD_GREEN) {
                red_state = 0;
                green_state = 1;
                blue_state = 0;
            } else if (lux >= LUX_THRESHOLD_GREEN && lux < LUX_THRESHOLD_BLUE) {
                red_state = 0;
                green_state = 0;
                blue_state = 1;
            } else {
                red_state = 0;
                green_state = 0;
                blue_state = 1;
            }

            // Set relay states
            if (control_relay(RED_RELAY_PIN, red_state) != 0) {
                fprintf(stderr, "Error controlling RED relay\n");
            }
            if (control_relay(GREEN_RELAY_PIN, green_state) != 0) {
                fprintf(stderr, "Error controlling GREEN relay\n");
            }
            if (control_relay(BLUE_RELAY_PIN, blue_state) != 0) {
                fprintf(stderr, "Error controlling BLUE relay\n");
            }

            // Log data
            if (log_data(lux, red_state, green_state, blue_state) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    if (i2c_fd > 0) close(i2c_fd);
    if (log_file) fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

