#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// Ultrasonic sensor simulation
#define DISTANCE_A 10
#define DISTANCE_B 20

// PWM frequency
#define PWM_FREQUENCY 1000

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to set motor direction and speed
void set_motor_direction(int motor, int distance) {
    int in1, in3, in2, in4;

    if (distance < 50) {
        // Forward
        in1 = 1; // Motor A
        in3 = 1; // Motor B
        in2 = 0; // Motor A
        in4 = 0; // Motor B
    } else {
        // Backward
        in1 = 0; // Motor A
        in3 = 0; // Motor B
        in2 = 0; // Motor A
        in4 = 0; // Motor B
    }

    // Set GPIO pins
    gpioWrite(motor, in1);
    gpioPWM(motor, in2);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_IN2, 255);
    gpioSetPWMrange(MOTOR_B_IN4, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Simulate ultrasonic sensor readings
        int distance_a = DISTANCE_A;
        int distance_b = DISTANCE_B;

        // Set motor directions based on simulated distances
        set_motor_direction(1, distance_a); // Motor A
        set_motor_direction(2, distance_b); // Motor B

        // Delay for 100 ms
