#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define LOG_FILE "solar_tracker.log"
#define NUM_SENSORS 3
#define NUM_READINGS 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define PWM_RANGE 2000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure for sensor data
typedef struct {
    float pitch;
    float roll;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_mpu6050(int fd, sensor_data_t *data);
float calculate_average_pitch(sensor_data_t data[], int num_sensors);
float calculate_average_roll(sensor_data_t data[], int num_sensors);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int servo_angle);
void signal_handler(int signal);
int export_pwm(int pin);
int unexport_pwm(int pin);
int set_pwm_period(int pin, int period_ns);
int set_pwm_duty_cycle(int pin, int duty_cycle_ns);
int set_servo_angle(int pin, int angle);

// Exponential backoff retry function
int retry_i2c_read(int fd, int retries, int delay_ms) {
    int result = -1;
    for (int i = 0; i < retries; ++i) {
        result = read_mpu6050(fd, &sensor_data_t{0.0, 0.0}); // Dummy data for retry
        if (result == 0) {
            break; // Success, exit retry loop
        }
        fprintf(stderr, "I2C read failed, retrying in %d ms...\n", delay_ms);
        usleep(delay_ms * 1000); // Convert ms to microseconds
        delay_ms *= 2; // Exponential backoff
    }
    return result;
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize PWM
    if (export_pwm(SERVO_PIN) != 0) {
        fprintf(stderr, "PWM export failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (set_pwm_period(SERVO_PIN, PWM_FREQUENCY * 1000000) != 0) {
        fprintf(stderr, "PWM period setting failed\n");
        unexport_pwm(SERVO_PIN);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (set_pwm_duty_cycle(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "PWM duty cycle setting failed\n");
        unexport_pwm(SERVO_PIN);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        unexport_pwm(SERVO_PIN);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data[NUM_SENSORS];
    float avg_pitch, avg_roll;

    // Main loop
    while (program_running) {
        // Read sensor data
        for (int i = 0; i < NUM_SENSORS; ++i) {
            if (retry_i2c_read(i2c_fd, MAX_RETRIES, RETRY_DELAY_MS) == 0) {
                // Process sensor data (crude conversion to pitch/roll)
                // This is a placeholder; replace with actual MPU6050 reading and conversion
                // For example, using accelerometer data to calculate pitch and roll
                // Refer to MPU6050 datasheet for the correct registers and formulas
                // This is a simplified example and may not be accurate for real-world use
                sensor_data[i].pitch = atan2f((float)(i % 2 == 0 ? 1 : -1), sqrtf((float)(i % 2 == 0 ? 2 : 1)));
                sensor_data[i].roll = atan2f((float)(i % 2 == 0 ? 2 : 1), sqrtf((float)(i % 2 == 0 ? 1 : -1)));
            } else {
                fprintf(stderr, "Failed to read sensor data from sensor %d\n", i);
                sensor_data[i].pitch = 0.0;
                sensor_data[i].roll = 0.0;
            }
        }

        // Calculate average pitch and roll
        avg_pitch = calculate_average_pitch(sensor_data, NUM_SENSORS);
        avg_roll = calculate_average_roll(sensor_data, NUM_SENSORS);

        // Set servo angle
        int servo_angle = (int)(avg_pitch * 100); // Map pitch to servo angle (0-180)
        if (servo_angle < 0) servo_angle = 0;
        if (servo_angle > 180) servo_angle = 180;
        if (set_servo_angle(SERVO_PIN, servo_angle) != 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        // Log data
        if (log_data(avg_pitch, avg_roll, servo_angle) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay
        usleep(100000); // 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_servo_angle(SERVO_PIN, 90); // Set servo to a safe position
    unexport_pwm(SERVO_PIN);
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: 0x%02x\n", addr);
        close(fd);
        return -1;
    }

    return fd;
}

// Read MPU6050 data (dummy implementation)
int read_mpu6050(int fd, sensor_data_t *data) {
    // This is a placeholder; replace with actual MPU6050 reading and conversion
    // Refer to MPU6050 datasheet for the correct registers and formulas
    // For example, reading accelerometer and gyroscope data, then calculating pitch and roll
    // This is a simplified example and may not be accurate for real-world use
    data->pitch = (float)(rand() % 360); // Simulate pitch
    data->roll = (float)(rand() % 360); // Simulate roll
    return 0;
}

// Calculate average pitch
float calculate_average_pitch(sensor_data_t data[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;
    for (int i = 0; i < num_sensors; ++i) {
        if (data[i].pitch != 0.0) { // Consider only valid readings
            sum += data[i].pitch;
            valid_count++;
        }
    }
    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return 0.0; // Return 0 if no valid readings
    }
}

// Calculate average roll
float calculate_average_roll(sensor_data_t data[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;
    for (int i = 0; i < num_sensors; ++i) {
        if (data[i].roll != 0.0) { // Consider only valid readings
            sum += data[i].roll;
            valid_count++;
        }
    }
    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return 0.0; // Return 0 if no valid readings
    }
}

// Set servo angle using pigpio
int set_servo_angle(int pin, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return -1;
    }

    int pulse_width = SERVO_MIN_PULSE_WIDTH + (angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180.0);
    if (set_servo_angle(pin, pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width\n");
        return -1;
    }
    return 0;
}

// Set servo angle using pigpio
int set_servo_angle(int pin, int pulse_width) {
    gpioServo(pin, pulse_width);
    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int servo_angle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_angle);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received: %d.  Shutting down...\n", signal);
    program_running = 0;
}

// Exponential backoff retry function
int retry_i2c_read(int fd, int retries, int delay_ms) {
    int result = -1;
    for (int i = 0; i < retries; ++i) {
        result = read_mpu6050(fd, &sensor_data_t{0.0, 0.0}); // Dummy data for retry
        if (result == 0) {
            break; // Success, exit retry loop
        }
        fprintf(stderr, "I2C read failed, retrying in %d ms...\n", delay_ms);
        usleep(delay_ms * 1000); // Convert ms to microseconds
        delay_ms *= 2; // Exponential backoff
    }
    return result;
}

