// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define sunrise/sunset transition duration (seconds)
#define TRANSITION_DURATION 1800

// Global variables
static volatile int running = 1;
static time_t last_schedule_change = 0;

// Function prototypes
int read_schedule(const char *filename, int *schedule[], int *num_entries);
int check_schedule(time_t current_time, int *schedule[], int num_entries);
void fade_brightness(int gpio_pin, int on_off);
void signal_handler(int signal);

// Function to read the schedule from a file
int read_schedule(const char *filename, int *schedule[], int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open schedule file %s\n", filename);
        return -1;
    }

    char line[256];
    *num_entries = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%d:%d:%d,%d", &schedule[*num_entries].hour, &schedule[*num_entries].minute, &schedule[*num_entries].second, &schedule[*num_entries].relay) == 4) {
            if (schedule[*num_entries].hour < 0 || schedule[*num_entries].hour > 23 ||
                schedule[*num_entries].minute < 0 || schedule[*num_entries].minute > 59 ||
                schedule[*num_entries].second < 0 || schedule[*num_entries].second > 59) {
                fprintf(stderr, "Error: Invalid schedule entry: %s\n", line);
                fclose(fp);
                return -1;
            }
            (*num_entries)++;
        } else {
            fprintf(stderr, "Error: Invalid schedule format: %s\n", line);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

// Function to check if the current time matches an entry in the schedule
int check_schedule(time_t current_time, int *schedule[], int num_entries) {
    time_t current_hour = current_time / 3600;
    time_t current_minute = (current_time % 3600) / 60;
    time_t current_second = current_time % 60;

    for (int i = 0; i < num_entries; i++) {
        int hour = schedule[i].hour;
        int minute = schedule[i].minute;
        int second = schedule[i].second;
        int relay = schedule[i].relay;

        if (hour == current_hour && minute == current_minute && second == current_second && relay == 1) {
            return 1; // Match found
        }
    }
    return 0; // No match found
}

// Function to fade the brightness of a lamp using PWM
void fade_brightness(int gpio_pin, int on_off) {
    int duty_cycle = (on_off ? 100 : 0) + (int)(((float)(PWM_FREQUENCY * 100) / TRANSITION_DURATION) * (time(NULL) - last_schedule_change));

    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(gpio_pin, duty_cycle);
    last_schedule_change = time(NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Set PWM range (0-100)
    gpioSetPWMrange(RELAY1_PIN, 100);
    gpioSetPWMrange(RELAY2_PIN, 100);
    gpioSetPWMrange(RELAY3_PIN, 100);
    gpioSetPWMrange(RELAY4_PIN, 100);

    // Set PWM dutycycle to 0 initially
    gpioPWM(RELAY1_PIN, 0);
    gpioPWM(RELAY2_PIN, 0);
    gpioPWM(RELAY3_PIN, 0);
    gpioPWM(RELAY4_PIN, 0);

    // Read the schedule from the file
    int schedule[10]; // Assuming a maximum of 10 entries
    int num_entries;
    if (read_schedule("lighting_schedule.txt", schedule, &num_entries) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        time_t current_time = time(NULL);

        if (check_schedule(current_time, schedule, num_entries)) {
            printf("Match found: %d:%d:%d, Relay %d\n", schedule[num_entries - 1].hour, schedule[num_entries - 1].minute, schedule[num_entries - 1].second, schedule[num_entries - 1].relay);
            fade_brightness(schedule[num_entries - 1].relay, 1); // Turn on the lamp
        } else {
            fade_brightness(schedule[num_entries - 1].relay, 0); // Turn off the lamp
        }

        gpioDelay(1000); // Check every second
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

