        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }
    start_tick = gpioTick();

    // Wait for echo to end (falling edge)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }
    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set buzzer frequency using PWM
void set_buzzer_frequency(float frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    int range = 1000000 / frequency; // PWM range
    gpioSetPWMrange(BUZZER_PIN, range);
    gpioPWM(BUZZER_PIN, range / 2); // 50% duty cycle
}

// Function to cleanup GPIO and terminate pigpio
void cleanup() {
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measure_distance();
        if (distance > 0) {
            float frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(60); // Delay for 60 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

