// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the color of the RGB LED
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Common anode, so invert the PWM value
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, so invert the PWM value
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, so invert the PWM value
}

// Function to simulate proximity value using a sine wave
float generate_proximity() {
    static float proximity = 0.0;
    static float time = 0.0;
    time += 0.01; // Simulate time passing
    proximity = sin(time * 2 * M_PI) + 0.5; // Sine wave between 0.5 and 1.5
    if (proximity < 0.5) proximity = 0.5;
    if (proximity > 1.5) proximity = 1.5;
    return proximity;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Main loop
    while (program_running) {
        // Generate proximity value
        float proximity = generate_proximity();

        // Set LED color based on proximity
        set_led_color((int)proximity, 255 - (int)proximity, 255 - (int)proximity);

        // Print proximity value
        printf("Proximity: %.2f, LED Color: R=%d, G=%d, B=%d\n", proximity, (int)proximity, 255 - (int)proximity, 255 - (int)proximity);

        // Delay for a short period
        gpioDelay(10000); // 10 ms
    }

    // Turn off the LED before exiting
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

