#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor
#define GYRO_SCALE_FACTOR 131.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *device);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t len, uint8_t *data);
int16_t combine_bytes(uint8_t high, uint8_t low);
float convert_to_degrees_per_second(int16_t raw_value);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read registers function
int i2c_read_regs(int fd, uint8_t reg, uint8_t len, uint8_t *data) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Combine high and low bytes into a 16-bit signed integer
int16_t combine_bytes(uint8_t high, uint8_t low) {
    return (int16_t)((high << 8) | low);
}

// Convert raw gyroscope data to degrees per second
float convert_to_degrees_per_second(int16_t raw_value) {
    return (float)raw_value / GYRO_SCALE_FACTOR;
}

// Log data to file
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        return 1;
    }

    // Wake up the MPU-6050
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    uint8_t gyro_data[6];
    int16_t raw_x, raw_y, raw_z;
    float x, y, z;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (i2c_read_regs(i2c_fd, GYRO_XOUT_H, 6, gyro_data) < 0) {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Combine high and low bytes
        raw_x = combine_bytes(gyro_data[0], gyro_data[1]);
        raw_y = combine_bytes(gyro_data[2], gyro_data[3]);
        raw_z = combine_bytes(gyro_data[4], gyro_data[5]);

        // Convert to degrees per second
        x = convert_to_degrees_per_second(raw_x);
        y = convert_to_degrees_per_second(raw_y);
        z = convert_to_degrees_per_second(raw_z);

        // Log data
        log_data(log_file, x, y, z);

        // Wait 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

