#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody data (frequency, duration)
const int melody[] = {
    262, 200,   // C4, 200ms
    294, 200,   // D4, 200ms
    330, 200,   // E4, 200ms
    349, 200,   // F4, 200ms
    392, 200,   // G4, 200ms
    440, 200,   // A4, 200ms
    494, 200,   // B4, 200ms
    523, 200,   // C5, 200ms
    0,  0       // Rest, 0ms
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int playing = 0;
volatile int button_pressed = 0;

// Function prototypes
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Interrupt handler function
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)tick; (void)user_data; // Unused parameters
    if (level == 0) { // Button pressed (active-low)
        button_pressed = 1;
    }
}

// Function to play the melody
void play_melody() {
    (void)playing; // Unused parameter
    playing = 1;
    printf("Playing melody...\n");
    for (int i = 0; i < melody_length; i++) {
        gpioHardwarePWM(BUZZER_PIN, melody[i] * 100); // Convert frequency to duty cycle (0-1000000)
        gpioDelay(melody[i] * 1000); // Delay in microseconds
    }
}

// Function to stop the melody
void stop_melody() {
    (void)playing; // Unused parameter
    playing = 0;
    printf("Stopping melody...\n");
    gpioHardwarePWM(BUZZER_PIN, 0); // Stop PWM
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set BUTTON_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    // Enable pull-up resistor on button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM range and frequency (adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 1000000); // 1MHz range
    gpioSetPWMfrequency(BUZZER_PIN, 440);   // 440Hz base frequency

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical doorbell started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            button_pressed = 0; // Reset the flag
            if (!playing) {
                play_melody();
            }
        }
        gpioDelay(10000); // Check every 10ms
    }

    return 0;
}

