        gpioTerminate();
        return 1;
    }

    // Enable pull-up resistor on button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM range and frequency (adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 1000000); // 1MHz range
    gpioSetPWMfrequency(BUZZER_PIN, 440);   // 440Hz base frequency

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical doorbell started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            button_pressed = 0; // Reset the flag
            if (!playing) {
                play_melody();
            }
        }
        gpioDelay(10000); // Check every 10ms
    }

    return 0;
}

