#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <poll.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3

volatile sig_atomic_t program_running = 1;

// Structure to hold the last N events
typedef struct {
    int events[WINDOW_SIZE];
    int index;
} EventBuffer;

EventBuffer event_buffer = {{0}, 0};

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the GPIO line
int initialize_gpio(int chip_name, int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chip_name, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request_input(line, "vibration_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the GPIO line value
int read_gpio_value(int chip_name, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip_name, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d value: %s\n", pin, strerror(errno));
        return -1;
    }

    return value;
}

// Function to log the event to a file
int log_event(const char *timestamp, int value) {
    FILE *fp = fopen("vibration_events.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening vibration_events.log: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s,%d\n", timestamp, value);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to vibration_events.log: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        fprintf(stderr, "Error acquiring lock on vibration_events.log: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fsync(fileno(fp)) == -1) {
        fprintf(stderr, "Error syncing vibration_events.log: %s\n", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        fprintf(stderr, "Error releasing lock on vibration_events.log: %s\n", strerror(errno));
    }

    fclose(fp);
    return 0;
}

// Function to check for earthquake alert
void check_earthquake_alert() {
    if (event_buffer.index < WINDOW_SIZE) {
        if (event_buffer.events[event_buffer.index] == 1) {
            event_buffer.events[event_buffer.index] = 0; // Remove from buffer
            int count = 0;
            for (int i = 0; i < WINDOW_SIZE; i++) {
                if (event_buffer.events[i] == 1) {
                    count++;
                }
            }
            if (count >= EARTHQUAKE_THRESHOLD) {
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char buf[80];
                strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
                printf("EARTHQUAKE ALERT: %s\n", buf);
            }
        }
    } else {
        event_buffer.index = 0; // Reset buffer if full
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = 1000; // Default timeout

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default (1000ms).\n");
            timeout_ms = 1000;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(GPIO_CHIP, GPIO_PIN) < 0) {
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening vibration_events.log: %s\n", strerror(errno));
        gpiod_line_release(GPIO_CHIP, GPIO_PIN);
        gpiod_chip_close(GPIO_CHIP);
        return 1;
    }

    // Main loop
    struct pollfd pfd;
    pfd.fd = fileno(log_file);
    pfd.events = POLLOUT; // Monitor for write availability

    while (program_running) {
        // Read GPIO value
        int value = read_gpio_value(GPIO_CHIP, GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value, exiting.\n");
            break;
        }

        // Get timestamp
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

        // Log the event
        if (log_event(timestamp, value) < 0) {
            fprintf(stderr, "Error logging event, exiting.\n");
            break;
        }

        // Add event to buffer
        event_buffer.events[event_buffer.index] = value;
        event_buffer.index = (event_buffer.index + 1) % WINDOW_SIZE;

        // Check for earthquake alert
        check_earthquake_alert();

        // Poll for timeout
        int ret = poll(&pfd, 1, timeout_ms);
        if (ret < 0) {
            fprintf(stderr, "Error polling: %s\n", strerror(errno));
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout occurred.\n");
            break;
        }

        // Consume the write event
        char buffer[1];
        lseek(fileno(log_file), 0, SEEK_SET); // Rewind the file pointer
        read(fileno(log_file), buffer, 1);       // Consume the write event
    }

    // Cleanup
    gpiod_line_release(GPIO_CHIP, GPIO_PIN);
    gpiod_chip_close(GPIO_CHIP);
    fclose(log_file);

    return 0;
}

