#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Data rate setting
#define DATA_RATE 15 // Hz

// Compass direction enum
enum compass_direction {
    N,
    NE,
    E,
    SE,
    S,
    SW,
    W,
    NW
};

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int i2c_open(const char *device);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len);
int configure_magnetometer(int fd);
magnetometer_data_t read_magnetometer_data(int fd);
void calibrate_magnetometer_data(magnetometer_data_t data, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z);
float calculate_heading(int16_t calibrated_x, int16_t calibrated_y);
enum compass_direction get_compass_direction(float heading);
void log_data(FILE *fp, int16_t calibrated_x, int16_t calibrated_y, int16_t calibrated_z, float heading, enum compass_direction direction);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LSM303_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read multiple registers function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure magnetometer function
int configure_magnetometer(int fd) {
    // Set continuous-conversion mode
    if (i2c_write_reg(fd, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error setting continuous-conversion mode\n");
        return -1;
    }

    // Set data rate to 15 Hz
    if (i2c_write_reg(fd, CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Error setting data rate\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data function
magnetometer_data_t read_magnetometer_data(int fd) {
    magnetometer_data_t data;
    uint8_t buf[6];

    if (i2c_read_regs(fd, OUT_X_H_M, buf, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buf[0] << 8) | buf[1]);
    data.y = (int16_t)((buf[3] << 8) | buf[4]);
    data.z = (int16_t)((buf[6] << 8) | buf[5]);

    return data;
}

// Calibrate magnetometer data function
void calibrate_magnetometer_data(magnetometer_data_t data, int16_t *calibrated_x, int16_t *calibrated_y, int16_t *calibrated_z) {
    *calibrated_x = data.x - X_OFFSET;
    *calibrated_y = data.y - Y_OFFSET;
    *calibrated_z = data.z - Z_OFFSET;
}

// Calculate compass heading function
float calculate_heading(int16_t calibrated_x, int16_t calibrated_y) {
    float heading = atan2f(calibrated_y, calibrated_x);
    heading = fmod(heading, 2 * M_PI);
    if (heading < 0) {
        heading += 2 * M_PI;
    }
    return heading;
}

// Get compass direction function
enum compass_direction get_compass_direction(float heading) {
    float heading_rad = heading * (M_PI / 180.0);
    if (heading_rad < M_PI / 6.0) {
        return N;
    } else if (heading_rad < M_PI / 3.0) {
        return NE;
    } else if (heading_rad < M_PI) {
        return E;
    } else if (heading_rad < 4 * M_PI / 3.0) {
        return SE;
    } else if (heading_rad < 5 * M_PI / 6.0) {
        return S;
    } else if (heading_rad < 2 * M_PI) {
        return SW;
    } else if (heading_rad < 3 * M_PI / 2.0) {
        return W;
    } else {
        return NW;
    }
}

// Log data to CSV function
void log_data(FILE *fp, int16_t calibrated_x, int16_t calibrated_y, int16_t calibrated_z, float heading, enum compass_direction direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d,%.2f,%d\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading, direction);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        return 1;
    }

    // Configure magnetometer
    if (configure_magnetometer(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data(i2c_fd);
        int16_t calibrated_x, calibrated_y, calibrated_z;
        calibrate_magnetometer_data(raw_data, &calibrated_x, &calibrated_y, &calibrated_z);

        // Calculate heading
        float heading = calculate_heading(calibrated_x, calibrated_y);

        // Get compass direction
        enum compass_direction direction = get_compass_direction(heading);

        // Log data
        log_data(log_file, calibrated_x, calibrated_y, calibrated_z, heading, direction);

        // Print to console
        printf("Calibrated X: %d, Calibrated Y: %d, Calibrated Z: %d, Heading: %.2f, Direction: %d\n",
               calibrated_x, calibrated_y, calibrated_z, heading, direction);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

