#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define log file path
#define LOG_FILE "relay_log.json"

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile int last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void touch_callback(int gpio, int level, uint32_t tick);
int log_relay_state(const char *timestamp, const char *state);
char* get_iso8601_timestamp();
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

// Callback function for touch sensor events
void touch_callback(int gpio, int level, uint32_t tick) {
    int current_time = gpioTick();

    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
        last_touch_time = current_time;

        if (level == 1) { // Touch detected (HIGH)
            relay_state = !relay_state; // Toggle relay state
            gpioWrite(RELAY_PIN, relay_state);

            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (log_relay_state(timestamp, relay_state) != 0) {
                    fprintf(stderr, "Failed to log relay state\n");
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }
        }
    }
}

// Function to log relay state to JSON file
int log_relay_state(const char *timestamp, const char *state) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to handle program cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Turn relay OFF
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d\n", signal);
    cleanup();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up interrupt on touch sensor pin
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        sleep(1); // Keep the program running
    }

    return 0;
}

