#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

// Configuration
#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO23 23
#define GPIO24 24
#define GPIO25 25
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5 // seconds
#define GAP_DURATION 1 // seconds
#define LOG_FILE "irrigation_log.txt"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x48 // Replace with your soil moisture sensor's I2C address

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay17 = NULL;
static struct gpiod_line *relay23 = NULL;
static struct gpiod_line *relay24 = NULL;
static struct gpiod_line *relay25 = NULL;
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int read_soil_moisture(void);
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_event(int relay_number, int moisture_level);
void send_data_to_server(int moisture_level);
void cleanup(void);
void signal_handler(int sig);

// Function to initialize GPIO lines
int init_gpio(void) {
    int ret;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return -1;
    }

    // Request GPIO lines as outputs
    config.consumer = "irrigation_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    relay17 = gpiod_chip_get_line(chip, GPIO17);
    if (!relay17) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO17);
        goto cleanup_chip;
    }

    relay23 = gpiod_chip_get_line(chip, GPIO23);
    if (!relay23) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO23);
        goto cleanup_relay17;
    }

    relay24 = gpiod_chip_get_line(chip, GPIO24);
    if (!relay24) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO24);
        goto cleanup_relay23;
    }

    relay25 = gpiod_chip_get_line(chip, GPIO25);
    if (!relay25) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO25);
        goto cleanup_relay24;
    }

    ret = gpiod_line_request(relay17, &config);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO17, strerror(-ret));
        goto cleanup_relay25;
    }

    ret = gpiod_line_request(relay23, &config);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO23, strerror(-ret));
        goto cleanup_relay17;
    }

    ret = gpiod_line_request(relay24, &config);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO24, strerror(-ret));
        goto cleanup_relay23;
    }

    ret = gpiod_line_request(relay25, &config);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO25, strerror(-ret));
        goto cleanup_relay24;
    }

    // Set initial state to inactive (HIGH)
    ret = gpiod_line_set_value(relay17, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO17, strerror(-ret));
        goto cleanup_relay25;
    }

    ret = gpiod_line_set_value(relay23, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO23, strerror(-ret));
        goto cleanup_relay17;
    }

    ret = gpiod_line_set_value(relay24, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO24, strerror(-ret));
        goto cleanup_relay23;
    }

    ret = gpiod_line_set_value(relay25, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO25, strerror(-ret));
        goto cleanup_relay24;
    }

    return 0;

cleanup_relay25:
    gpiod_line_release(relay25);
cleanup_relay24:
    gpiod_line_release(relay24);
cleanup_relay23:
    gpiod_line_release(relay23);
cleanup_relay17:
    gpiod_line_release(relay17);
cleanup_relay25:
    gpiod_line_release(relay25);
cleanup_relay24:
    gpiod_line_release(relay24);
cleanup_relay23:
    gpiod_line_release(relay23);
cleanup_relay17:
    gpiod_line_release(relay17);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Function to initialize I2C
int init_i2c(void) {
    int ret;

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read soil moisture from I2C
int read_soil_moisture(void) {
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C not initialized\n");
        return -1;
    }

    // Read two bytes from the I2C device
    uint8_t buf[2];
    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
