#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 20
#define MOISTURE_THRESHOLD_HIGH 50

// Define servo pulse widths (microseconds)
#define VALVE_CLOSED 500
#define VALVE_OPEN 1500
#define NOZZLE_POSITIONS {0, 45, 90, 135, 180}

// Define watering cycle parameters
#define WATERING_DURATION 5 // seconds
#define NOZZLE_STEP_DURATION 2 // seconds
#define NOZZLE_STEP_DELAY 5 // seconds

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t valve_closed = 0;
volatile sig_atomic_t valve_open = 0;
volatile sig_atomic_t valve_error = 0;

// Function prototypes
int initialize_gpio();
int set_valve_position(int position);
int set_nozzle_position(int position);
int read_moisture();
void water_plant(int moisture_level);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(NOZZLE_GPIO, PI_OUTPUT);

    // Set initial valve position (closed)
    if (set_valve_position(VALVE_CLOSED) != 0) {
        fprintf(stderr, "Failed to set initial valve position\n");
        return 1;
    }

    // Set initial nozzle position (0 degrees)
    if (set_nozzle_position(0) != 0) {
        fprintf(stderr, "Failed to set initial nozzle position\n");
        return 1;
    }

    return 0;
}

// Set valve position
int set_valve_position(int position) {
    int pulse_width = VALVE_CLOSED + (position * (VALVE_OPEN - VALVE_CLOSED) / 180.0);
    int retries = 3;
    int delay_ms = 100;

    while (retries > 0) {
        if (gpioServo(VALVE_GPIO, pulse_width) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to set valve position, retrying...\n");
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    if (!valve_closed && !valve_open) {
        fprintf(stderr, "Critical error: Valve failed to open after multiple retries!\n");
        valve_error = 1; // Log the error
    } else if (position == VALVE_CLOSED) {
        fprintf(stderr, "Valve closed successfully.\n");
        valve_closed = 1;
    } else {
        fprintf(stderr, "Valve open successfully.\n");
        valve_open = 1;
    }

    return 1; // Failure
}

// Set nozzle position
int set_nozzle_position(int position) {
    int pulse_width = NOZZLE_POSITIONS[position];
    int retries = 3;
    int delay_ms = 100;

    while (retries > 0) {
        if (gpioServo(NOZZLE_GPIO, pulse_width) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to set nozzle position, retrying...\n");
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    if (!valve_open) {
        fprintf(stderr, "Nozzle position failed to set after multiple retries!\n");
        valve_error = 1; // Log the error
    } else {
        fprintf(stderr, "Nozzle set to %d degrees.\n", position);
    }

    return 1; // Failure
}

// Read simulated moisture level
int read_moisture() {
    static int moisture_level = MOISTURE_THRESHOLD_LOW;
    moisture_level = (moisture_level + 5) % 5; // Cycle through values
    return moisture_level;
}

// Water the plant
void water_plant(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD_LOW) {
        printf("Moisture level low (%d), watering...\n", moisture_level);
        if (!valve_closed) {
            if (set_valve_position(VALVE_OPEN) != 0) {
                fprintf(stderr, "Failed to open valve, watering cycle aborted.\n");
                valve_error = 1;
            }
        }
        for (int i = 0; i < 5; i++) {
            if (set_nozzle_position(i) != 0) {
                fprintf(stderr, "Failed to set nozzle position %d, watering cycle aborted.\n", i);
                valve_error = 1;
                break;
            }
            gpioDelay(WATERING_DURATION * 1000); // Wait for watering duration
        }
        if (set_valve_position(VALVE_CLOSED) != 0) {
            fprintf(stderr, "Failed to close valve, watering cycle aborted.\n");
            valve_error = 1;
        }
    } else {
        printf("Moisture level high (%d), skipping watering.\n", moisture_level);
    }
}

// Cleanup GPIO pins
void cleanup_gpio() {
    printf("Cleaning up GPIO pins...\n");
    gpioServo(VALVE_GPIO, 0); // Stop valve servo
    gpioServo(NOZZLE_GPIO, 0); // Stop nozzle servo
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int moisture_level = read_moisture();
        printf("Moisture level: %d\n", moisture_level);
        water_plant(moisture_level);
        gpioDelay(NOZZLE_STEP_DELAY * 1000); // Wait before next cycle
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

