#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor
#define GYRO_SCALE_FACTOR 131.0f

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len);
int16_t read_gyro_data(int fd, uint8_t reg);
float convert_to_degrees_per_second(int16_t raw_data);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signum);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Read gyroscope data
int16_t read_gyro_data(int fd, uint8_t reg) {
    uint8_t data[2];
    if (i2c_read_regs(fd, reg, data, 2) != 0) {
        fprintf(stderr, "Error reading gyro data from register 0x%02X\n", reg);
        return 0; // Return 0 on error
    }
    return (int16_t)((data[0] << 8) | data[1]);
}

// Convert raw data to degrees per second
float convert_to_degrees_per_second(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE_FACTOR;
}

// Log data to file
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the sensor
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read gyroscope data
        int16_t raw_x = read_gyro_data(i2c_fd, GYRO_XOUT_H);
        int16_t raw_y = read_gyro_data(i2c_fd, GYRO_YOUT_H);
        int16_t raw_z = read_gyro_data(i2c_fd, GYRO_ZOUT_H);

        // Convert to degrees per second
        float x = convert_to_degrees_per_second(raw_x);
        float y = convert_to_degrees_per_second(raw_y);
        float z = convert_to_degrees_per_second(raw_z);

        // Log data
        log_data(log_file, x, y, z);

        // Sleep for 100ms (10 Hz sampling rate)
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

