#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for stepper motor control
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

// Define GPIO pins for push-button inputs
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define the number of steps for a quarter turn
#define QUARTER_TURN_STEPS 512

// Define the delay between steps (in microseconds)
#define STEP_DELAY 3000

// Global variable to track the current step
static volatile int current_step = 0;

// Function prototypes
void set_step(int step);
void rotate_quarter_turn_clockwise();
void rotate_quarter_turn_counter_clockwise();
void lock_door();
void unlock_door();
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int in1;
    int in2;
    int in3;
    int in4;
    int lock_button;
    int unlock_button;
} gpio_config_t;

// Global configuration
gpio_config_t gpio_config = {
    IN1, IN2, IN3, IN4, LOCK_BUTTON, UNLOCK_BUTTON
};

// Function to set the step of the stepper motor
void set_step(int step) {
    gpioWrite(gpio_config.in1, (step & 1) ? 1 : 0);
    gpioWrite(gpio_config.in2, (step & 2) ? 1 : 0);
    gpioWrite(gpio_config.in3, (step & 4) ? 1 : 0);
    gpioWrite(gpio_config.in4, (step & 8) ? 1 : 0);
}

// Function to rotate the stepper motor clockwise for a quarter turn
void rotate_quarter_turn_clockwise() {
    for (int i = 0; i < QUARTER_TURN_STEPS; i++) {
        set_step(i);
        gpioDelay(STEP_DELAY);
    }
    printf("Locked door (clockwise)\n");
}

// Function to rotate the stepper motor counter-clockwise for a quarter turn
void rotate_quarter_turn_counter_clockwise() {
    for (int i = 0; i < QUARTER_TURN_STEPS; i++) {
        set_step(QUARTER_TURN_STEPS - i - 1);
        gpioDelay(STEP_DELAY);
    }
    printf("Unlocked door (counter-clockwise)\n");
}

// Function to lock the door
void lock_door() {
    if (gpioRead(gpio_config.lock_button) == 0) { // Active low
        printf("Lock button pressed. Locking door.\n");
        rotate_quarter_turn_clockwise();
    }
}

// Function to unlock the door
void unlock_door() {
    if (gpioRead(gpio_config.unlock_button) == 0) { // Active low
        printf("Unlock button pressed. Unlocking door.\n");
        rotate_quarter_turn_counter_clockwise();
    }
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    if (gpio == gpio_config.lock_button && level == 0) {
        lock_door();
    } else if (gpio == gpio_config.unlock_button && level == 0) {
        unlock_door();
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Stopping motor and exiting.\n");
    // De-energize all coils
    gpioWrite(gpio_config.in1, 0);
    gpioWrite(gpio_config.in2, 0);
    gpioWrite(gpio_config.in3, 0);
    gpioWrite(gpio_config.in4, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motor control pins
    gpioSetMode(gpio_config.in1, PI_OUTPUT);
    gpioSetMode(gpio_config.in2, PI_OUTPUT);
    gpioSetMode(gpio_config.in3, PI_OUTPUT);
    gpioSetMode(gpio_config.in4, PI_OUTPUT);

    // Set GPIO modes for button pins
    gpioSetMode(gpio_config.lock_button, PI_INPUT);
    gpioSetPullUpDown(gpio_config.lock_button, PI_PUD_UP); // Enable pull-up resistor
    gpioSetMode(gpio_config.unlock_button, PI_INPUT);
    gpioSetPullUpDown(gpio_config.unlock_button, PI_PUD_UP); // Enable pull-up resistor

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up callback functions for button presses
    gpioSetAlertFunc(gpio_config.lock_button, button_callback);
    gpioSetAlertFunc(gpio_config.unlock_button, button_callback);

    printf("Stepper motor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    return 0;
}

