#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000        // 50 ms timeout
#define GUARD_TIME_US 60000      // 60 ms guard time

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init();
int trigger_pulse();
long measure_pulse_width();
float calculate_distance(long pulse_width);
int log_distance(float distance);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize GPIO pins
int gpio_init() {
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %s\n", strerror(errno));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line as output: %s\n", strerror(-ret));
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(echo_line, "echo", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line as input: %s\n", strerror(-ret));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Generate a 10 microsecond high pulse on the trigger line
int trigger_pulse() {
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "trigger_pulse";

    ret = gpiod_line_request_output(trigger_line, "trigger_pulse", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line as output for pulse: %s\n", strerror(-ret));
        return -1;
    }

    usleep(10); // 10 microseconds

    ret = gpiod_line_request_output(trigger_line, "trigger_pulse", 0);
    if (ret < 0) {
        fprintf(stderr, "Error releasing trigger line after pulse: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Measure the echo pulse width using a busy-wait loop
long measure_pulse_width() {
    struct timespec start, end;
    long pulse_width = 0;
    int ret;

    ret = clock_gettime(CLOCK_MONOTONIC, &start);
    if (ret < 0) {
        fprintf(stderr, "Error getting start time: %s\n", strerror(-ret));
        return -1;
    }

    while (1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            fprintf(stderr, "Error getting echo line value: %s\n", strerror(-ret));
            return -1;
        }

        if (ret) {
            ret = clock_gettime(CLOCK_MONOTONIC, &end);
            if (ret < 0) {
                fprintf(stderr, "Error getting end time: %s\n", strerror(-ret));
                return -1;
            }

            pulse_width = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
            return pulse_width;
        }

        ret = clock_gettime(CLOCK_MONOTONIC, &end);
        if (ret < 0) {
            fprintf(stderr, "Error getting end time: %s\n", strerror(-ret));
            return -1;
        }
    }
}

// Calculate distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Log distance to file
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int ret;
    long pulse_width;
    float distance_cm;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger pulse
        if (trigger_pulse() < 0) {
            fprintf(stderr, "Error sending trigger pulse.\n");
            log_distance(-1.0);
        } else {
            // Measure pulse width
            pulse_width = measure_pulse_width();
            if (pulse_width < 0) {
                fprintf(stderr, "Error measuring pulse width.\n");
                log_distance(-1.0);
            } else {
                // Calculate distance
                distance_cm = calculate_distance(pulse_width);

                // Log distance
                if (log_distance(distance_cm) < 0) {
                    fprintf(stderr, "Error logging distance.\n");
                }
            }
        }

        // Wait for guard time
        usleep(GUARD_TIME_US);
    }

    // Clean up
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

