#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm
#define POLL_INTERVAL 100 // ms

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0096
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_relay(int state);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Set ranging mode (example: short distance)
    if (i2cWriteByteData(i2c_handle, 0x001E, 0x04) < 0) { // Example: Short distance mode
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance() {
    int distance = -1;
    int status;

    // Read range status
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read range status\n");
        return -1;
    }

    // Read distance (MSB and LSB)
    int msb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    int lsb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);

    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error: Failed to read distance data\n");
        return -1;
    }

    distance = (msb << 8) | lsb;

    return distance;
}

// Control the relay (HIGH to open the door, LOW to close it)
void control_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) < 0) {
        fprintf(stderr, "Error: Failed to write to GPIO\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            if (distance <= DISTANCE_THRESHOLD) {
                control_relay(1); // Open the door
            } else {
                control_relay(0); // Close the door
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(POLL_INTERVAL); // Wait before next poll
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is LOW on exit
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

