#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0f

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buffer[6];

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    // Combine high and low bytes, and convert to degrees/second
    *x = (int16_t)((buffer[0] << 8) | buffer[1]) * GYRO_SENSITIVITY;
    *y = (int16_t)((buffer[2] << 8) | buffer[3]) * GYRO_SENSITIVITY;
    *z = (int16_t)((buffer[4] << 8) | buffer[5]) * GYRO_SENSITIVITY;

    return 0;
}

