    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2c_write_reg(i2c_fd, GYRO_CONFIG, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }

