#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the log file name
#define LOG_FILE "smart_lighting.log"

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to initialize a GPIO pin as output
int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to set GPIO %d as output", pin);
        log_event(error_message);
        return -1;
    }
    return 0;
}

// Function to set the PWM duty cycle for a relay
int set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to set PWM duty cycle for GPIO %d to %d", pin, duty_cycle);
        log_event(error_message);
        return -1;
    }
    return 0;
}

// Function to simulate the sunrise effect
void sunrise_effect(int *duty_cycles) {
    for (int i = 0; i <= 255 && program_running; i++) {
        for (int j = 0; j < 4; j++) {
            if (set_pwm_duty_cycle(RELAY1_PIN, duty_cycles[j]) != 0 ||
                set_pwm_duty_cycle(RELAY2_PIN, duty_cycles[j]) != 0 ||
                set_pwm_duty_cycle(RELAY3_PIN, duty_cycles[j]) != 0 ||
                set_pwm_duty_cycle(RELAY4_PIN, duty_cycles[j]) != 0) {
                program_running = 0; // Stop if there's an error
                break;
            }
        }
        gpioDelay(1000); // Wait for 1 second
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(RELAY1_PIN) != 0 ||
        initialize_gpio(RELAY2_PIN) != 0 ||
        initialize_gpio(RELAY3_PIN) != 0 ||
        initialize_gpio(RELAY4_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize duty cycles to 0
    int duty_cycles[4] = {0, 0, 0, 0};

    // Start the sunrise effect
    sunrise_effect(duty_cycles);

    // Clean up and terminate the pigpio library
    gpioTerminate();
    log_event("Program terminated gracefully");

    return 0;
}

