int mpu9250_read_gyro_data(int fd, int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    uint8_t tx_buf[7] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx_buf[7];

    if (spi_transfer(fd, tx_buf, rx_buf, 7) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x_rate = (int16_t)((rx_buf[2] << 8) | rx_buf[1]);
    *y_rate = (int16_t)((rx_buf[4] << 8) | rx_buf[3]);
