#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 3900000 // 3.9 MHz
#define CE0_PIN 8
#define LED_PIN 17
#define BUFFER_SIZE 64
#define THRESHOLD 200.0 // degrees per second

// MPU-6050 Register Addresses
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *ce_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Data Structures
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular Buffer
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Function Prototypes
int spi_init(const char *device, int mode, int speed);
int spi_read_register(int fd, uint8_t reg);
int spi_write_register(int fd, uint8_t reg, uint8_t value);
int read_gyro_data(int fd, float *x, float *y, float *z);
void buffer_init(circular_buffer_t *buffer);
void buffer_add(circular_buffer_t *buffer, float x, float y, float z);
void buffer_print(circular_buffer_t *buffer);
void led_control(int on);
void signal_handler(int sig);
int gpio_request(int pin, char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);

// SPI Initialization
int spi_init(const char *device, int mode, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int ret = ioctl(fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read Register
int spi_read_register(int fd, uint8_t reg) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for read
    tx_buf[1] = 0x00;       // Dummy byte

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error reading SPI register");
        return -1;
    }

    return rx_buf[1];
}

// SPI Write Register
int spi_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx_buf[2];
    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = value;

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)NULL,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error writing SPI register");
        return -1;
    }

    return 0;
}

// Read Gyro Data
