#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LED_ON_TIME_MS 500
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000 // 10ms

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
int control_gpio(int gpio, int value);
void signal_handler(int sig);
int setup_gpio(void);

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = RETRY_COUNT;
    int result;
    struct timespec delay = {0, RETRY_DELAY_US};

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (address) failed");
            goto retry;
        }

        if (read(fd, data, len) == len) {
            return 0; // Success
        } else {
            perror("I2C read failed");
            goto retry;
        }
        nanosleep(&delay, NULL);
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
retry:
    retries--;
}

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = RETRY_COUNT;
    int result;
    struct timespec delay = {0, RETRY_DELAY_US};

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (address) failed");
            goto retry;
        }

        if (write(fd, &value, 1) != 1) {
            perror("I2C write (data) failed");
            goto retry;
        }
        nanosleep(&delay, NULL);
        return 0; // Success
    }

    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
retry:
    retries--;
    return -1; // Failure
}

// Read sensor data function
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t data[4];

    if (i2c_read_bytes(fd, AMBIENT_LIGHT_REG, data, 4) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }

    *ambient_light = (data[1] << 8) | data[0];
    *proximity = (data[3] << 8) | data[2];

    return 0;
}

// Log data function
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Control GPIO function
int control_gpio(int gpio, int value) {
    if (gpio != GPIO_PIN) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio);
        return -1;
    }

    if (gpio_line_set_value(gpio_line, value) < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }

    struct timespec delay = {0, LED_ON_TIME_MS * 1000000L};
    nanosleep(&delay, NULL);

    if (gpio_line_set_value(gpio_line, 0) < 0) {
        perror("Failed to reset GPIO value");
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }

    exit(0);
}

// Setup GPIO function
int setup_gpio(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_line, "biometric", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_set_value(gpio_line, 0);
    if (ret < 0) {
        perror("Failed to set initial GPIO value");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int main() {
    uint16_t ambient_light, proximity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int ret;

    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Setup GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed.\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            if (log_data(log_file, ambient_light, proximity) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }

            if (proximity > 100) {
                if (control_gpio(GPIO_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to control GPIO.\n");
                }
            } else {
                if (control_gpio(GPIO_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to control GPIO.\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(100000); // 100ms
    }

    // Cleanup (should not reach here if signal handler works)
    close(i2c_fd);
    fclose(log_file);
    gpiod_chip_close(gpio_chip);
    gpiod_line_release(gpio_line);

    return 0;
}

