#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXRS290 Register Addresses
#define ADXRS290_REG_X_RATE 0x02
#define ADXRS290_REG_Y_RATE 0x04

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Sensitivity (LSB/deg/s)
#define SENSITIVITY 200.0

// Global Variables
int spi_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_spi();
int read_register(uint8_t address, uint8_t dummy, uint8_t *data);
int write_register(uint8_t address, uint8_t data);
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
void log_data(int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);

// Structure for gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read a register
int read_register(uint8_t address, uint8_t dummy, uint8_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address | 0x80; // Set read bit
    tx_buf[1] = dummy;
    tx_buf[2] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    *data = rx_buf[2];
    return 0;
}

// Function to write a register
int write_register(uint8_t address, uint8_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address & 0x7F; // Clear read bit
    tx_buf[1] = data;
    tx_buf[2] = 0x00; // Dummy byte for writing

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_rate_data, y_rate_data;

    if (read_register(ADXRS290_REG_X_RATE, 0x00, &x_rate_data) != 0) {
        fprintf(stderr, "Error reading X rate\n");
        return -1;
    }

    if (read_register(ADXRS290_REG_Y_RATE, 0x00, &y_rate_data) != 0) {
        fprintf(stderr, "Error reading Y rate\n");
        return -1;
    }

    *x_rate = (int16_t)x_rate_data;
    *y_rate = (int16_t)y_rate_data;

    return 0;
}

// Function to log data to file
void log_data(int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(data_file, "%.6f,%d,%d\n", timestamp, x_rate, y_rate);
    fflush(data_file); // Ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen("gyro_data.csv", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,X_rate,Y_rate\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t x_rate, y_rate;
    while (!terminate) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            log_data(x_rate, y_rate);
        } else {
            fprintf(stderr, "Failed to read gyro data. Reinitializing SPI...\n");
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Failed to reinitialize SPI. Exiting.\n");
                break;
            }
        }
        gpioDelay(10); // 10 ms delay (100 Hz sampling rate)
    }

    // Cleanup
    fclose(data_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

