    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Check if both sensors are HIGH simultaneously
        if (sensor_states.sensor1_state == 1 && sensor_states.sensor2_state == 1) {
            uint32_t current_tick = gpioTick();
            if (current_tick - sensor_states.last_tick >= (SEISMIC_DURATION * 1000)) {
                trigger_alert();
                log_event();
                sensor_states.last_tick = current_tick;
            }
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    fclose(log_file);
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();

    return 0;
}

