    gpioWrite(ALERT_GPIO, 1); // Set ALERT_GPIO HIGH
    gpioDelay(ALERT_DURATION * 1000000); // Wait for ALERT_DURATION seconds
    gpioWrite(ALERT_GPIO, 0); // Set ALERT_GPIO LOW
}

// Function to log the event
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

