#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADXRS290 register addresses
#define RATE_XL 0x02
#define RATE_XH 0x03

// Define GPIO pin for LED
#define LED_PIN 17

// Define angular velocity threshold
#define ANGULAR_VELOCITY_THRESHOLD 20.0

// Define circular buffer size
#define CIRCULAR_BUFFER_SIZE 100

// Structure to hold timestamped angular velocity data
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} gyro_data_t;

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
gyro_data_t circular_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int spi_read_register(uint8_t address, uint16_t *data);
float convert_to_deg_per_second(uint16_t raw_data);
void add_to_circular_buffer(float angular_velocity);
void *monitor_gyro_data(void *arg);
void signal_handler(int signal);

// Function to read a single register via SPI
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Set MSB of address to 1 for read operation
    tx_buf[0] = address | 0x80; // Read bit set
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2]; // Combine bytes
    return 0;
}

// Function to convert raw data to degrees per second
float convert_to_deg_per_second(uint16_t raw_data) {
    return (float)raw_data / 200.0f; // 200 LSB/deg/s
}

// Function to add data to the circular buffer
void add_to_circular_buffer(float angular_velocity) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    circular_buffer[buffer_index].timestamp = ts;
    circular_buffer[buffer_index].angular_velocity = angular_velocity;

    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
}

// Thread function to monitor gyroscope data
void *monitor_gyro_data(void *arg) {
    uint16_t raw_data;
    float angular_velocity;
    struct timespec ts;

    while (!terminate) {
        if (spi_read_register(RATE_XL, &raw_data) == 0) {
            angular_velocity = convert_to_deg_per_second(raw_data);
            add_to_circular_buffer(angular_velocity);
            printf("Angular Velocity: %.2f deg/s\n", angular_velocity);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        // Check for threshold violation
        if (fabs(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD) {
            gpioWrite(LED_PIN, 1); // Turn on LED
        } else {
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        gpioDelay(1000); // Delay for 1 ms
    }

    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create thread for monitoring gyroscope data
    pthread_t gyro_thread;
    if (pthread_create(&gyro_thread, NULL, monitor_gyro_data, NULL) != 0) {
        fprintf(stderr, "Error: Could not create gyroscope monitoring thread\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop (do nothing, thread handles gyroscope monitoring)
    while (!terminate) {
        sleep(1); // Sleep to avoid busy-waiting
    }

    // Cleanup
    pthread_join(gyro_thread, NULL);
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

