#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to fade a lamp from full brightness to off
int fade_lamp(int gpio, int duration) {
    int i, steps, step_delay;
    int pwm_value;

    // Validate duration
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Invalid fade duration. Must be between 1 and 3600 seconds.\n");
        return -1; // Indicate an error
    }

    // Calculate the number of steps and delay
    steps = duration * 1000; // Total fade time in milliseconds
    step_delay = (steps / PWM_RANGE); // Delay between steps in milliseconds

    // Fade from 100% to 0%
    for (i = 0; i <= PWM_RANGE; i++) {
        pwm_value = i;
        gpioPWM(gpio, pwm_value);
        gpioDelay(step_delay);
    }

    return 0; // Indicate success
}

int main(int argc, char *argv[]) {
    int fade_duration;

