int set_relay_state(int relay_pin, int state) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!line) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(line, relay_pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(line);
        return -1;
    }

    ret = gpiod_line_request_output(line, "traffic_light", state);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(line);
        return -1;
    }

    gpiod_line_set_value(line, state);
    gpiod_line_release(line);

    return 0;
}

