#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define RELAY_GPIO 17
#define MPR121_I2C_ADDR 0x5A
#define MPR121_TOUCH_STATUS_REG 0x00
#define MPR121_RELEASE_STATUS_REG 0x01
#define MPR121_ELECTRODE_CONFIG_REG 0x5D
#define MPR121_TOUCH_THRESHOLD_REG 0x41
#define MPR121_RELEASE_THRESHOLD_REG 0x42
#define MPR121_DEBOUNCE_REG 0x5B
#define MPR121_CHARGE_TIME_REG 0x5C
#define MPR121_STOP_MODE_REG 0x5E
#define MPR121_RESET_REG 0x80

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_mpr121();
int read_touch_status();
int debounce_touch();
void toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message("Received signal, cleaning up...");
        terminate = 1;
    }
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF
    return 0;
}

// Initialize MPR121 sensor
int initialize_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, MPR121_RESET_REG, 0x63) < 0) {
        log_message("Failed to reset MPR121");
        return -1;
    }
    gpioDelay(100000); // Wait 100ms

    // Configure MPR121 for electrode 0 only
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG_REG, 0x01) < 0) {
        log_message("Failed to configure MPR121 for electrode 0");
        return -1;
    }

    // Set touch and release thresholds
    if (i2cWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD_REG, 0x0A) < 0) {
        log_message("Failed to set touch threshold");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD_REG, 0x08) < 0) {
        log_message("Failed to set release threshold");
        return -1;
    }

    // Set debounce
    if (i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE_REG, 0x21) < 0) {
        log_message("Failed to set debounce");
        return -1;
    }

    // Set charge time
    if (i2cWriteByteData(i2c_handle, MPR121_CHARGE_TIME_REG, 0x0D) < 0) {
        log_message("Failed to set charge time");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG_REG, 0x01) < 0) {
        log_message("Failed to enable electrode 0");
        return -1;
    }

    // Start in stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_STOP_MODE_REG, 0x00) < 0) {
        log_message("Failed to set stop mode");
        return -1;
    }

    // Run in run mode
    if (i2cWriteByteData(i2c_handle, MPR121_STOP_MODE_REG, 0x0D) < 0) {
        log_message("Failed to set run mode");
        return -1;
    }

    return 0;
}

// Read touch status from MPR121
int read_touch_status() {
    int touch_status_lsb = i2cReadByteData(i2c_handle, MPR121_TOUCH_STATUS_REG);
    int touch_status_msb = i2cReadByteData(i2c_handle, MPR121_RELEASE_STATUS_REG);

    if (touch_status_lsb < 0 || touch_status_msb < 0) {
        log_message("Failed to read touch status");
        return 0; // Return 0 on error
    }

    return (touch_status_msb << 8) | touch_status_lsb;
}

// Debounce touch event
int debounce_touch() {
    gpioDelay(100000); // 100ms delay
    int current_touch_status = read_touch_status();
    if (current_touch_status == 0) { // Check if still touched after debounce
        return 1;
    }
    return 0;
}

// Toggle relay state
void toggle_relay() {
    int current_relay_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_relay_state);
    log_message("Relay toggled");
}

// Log messages to file with timestamp
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(1, MPR121_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_message("System started");

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status();
        if (debounce_touch()) {
            toggle_relay();
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();
    fclose(log_file);
    log_message("System stopped");

    return 0;
}

