// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration (milliseconds)
#define DISPENSE_DURATION 1000

// Define dispense interval (seconds)
#define DISPENSE_INTERVAL 5

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int configure_gpio_output(int pin);
int dispense_solenoid(int solenoid_pin, int duration_ms);
int log_dispense_event(int solenoid_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Deactivating solenoids and exiting.\n");
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);
        gpioTerminate();
        program_running = 0;
        exit(0);
    }
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to configure a GPIO pin as an output
int configure_gpio_output(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to dispense solenoid 1 for a given duration
int dispense_solenoid(int solenoid_pin, int duration_ms) {
    if (gpioWrite(solenoid_pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on pin %d\n", solenoid_pin);
        return 1; // Indicate failure
    }
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    if (gpioWrite(solenoid_pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on pin %d\n", solenoid_pin);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to log a dispense event to a file
int log_dispense_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open dispense_log.txt for writing\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Solenoid %d activated for %d ms\n", s, solenoid_pin, duration_ms);
    fclose(fp);
    return 0; // Indicate success
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Configure GPIO pins as outputs
    if (configure_gpio_output(SOLENOID_1_PIN) != 0) {
        gpioTerminate();
        return 1;
    }
    if (configure_gpio_output(SOLENOID_2_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Dispense solenoid 1
        if (dispense_solenoid(SOLENOID_1_PIN, DISPENSE_DURATION / 2) != 0) {
            fprintf(stderr, "Failed to dispense solenoid 1\n");
        }

        // Dispense solenoid 2
        if (dispense_solenoid(SOLENOID_2_PIN, DISPENSE_DURATION / 2) != 0) {
            fprintf(stderr, "Failed to dispense solenoid 2\n");
        }

        // Wait for the next dispense interval
        gpioDelay(DISPENSE_INTERVAL * 1000000); // Delay in microseconds
    }

    // Deactivate solenoids and terminate pigpio (handled by signal handler)
    return 0;
}

