void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void set_motor_speed(int motor_a_speed, int motor_b_speed);
void pid_control(float tilt_error, float *motor_a_speed, float *motor_b_speed);

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, stopping motors and cleaning up...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor control pins as outputs
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    // Set enable pins high
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_FORWARD, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_A_BACKWARD, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_FORWARD, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_BACKWARD, PWM_FREQUENCY);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // Stop motors
    set_motor_speed(0, 0);

    // Disable enable pins
    gpioWrite(ENA, 0);
    gpioWrite(ENB, 0);

    // Terminate pigpio
    gpioTerminate();
}

// Function to log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %d, %d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to set motor speeds
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_a_speed < -255) motor_a_speed = -255;
    if (motor_b_speed > 255) motor_b_speed = 255;
    if (motor_b_speed < -255) motor_b_speed = -255;

    gpioPWM(MOTOR_A_FORWARD, motor_a_speed);
    gpioPWM(MOTOR_A_BACKWARD, -motor_a_speed);
    gpioPWM(MOTOR_B_FORWARD, motor_b_speed);
    gpioPWM(MOTOR_B_BACKWARD, -motor_b_speed);
}

// Function to implement PID control
void pid_control(float tilt_error, float *motor_a_speed, float *motor_b_speed) {
    static float integral = 0.0;
    static float previous_error = 0.0;

    float derivative = tilt_error - previous_error;

    integral += tilt_error;

    float output = (Kp * tilt_error) + (Ki * integral) + (Kd * derivative);

    *motor_a_speed = (int)(output * 255.0);
    *motor_b_speed = (int)(output * 255.0);

    previous_error = tilt_error;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Main loop
    while (running) {
        float tilt_error = (float)(rand() % 201 - 100); // Random tilt error between -10 and 10
        float distance = (float)(rand() % 400 - 200) + 2.0; // Random distance between 2 and 400

        if (distance < OBSTACLE_THRESHOLD) {
            set_motor_speed(-128, -128); // Reverse both motors at 50% speed
            log_data(tilt_error, distance, -128, -128);
            gpioDelay(500000); // Wait 0.5 seconds
            set_motor_speed(0, 0); // Stop motors
        } else {
            pid_control(tilt_error, &motor_a_speed, &motor_b_speed);
            set_motor_speed(motor_a_speed, motor_b_speed);
            log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        }

        gpioDelay(50000); // Control loop frequency of 20 Hz
    }

    // Cleanup and exit
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

