#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initializes the pigpio library and sets up GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO4 as input for the touch sensor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for the relay
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Enable pull-down resistor on GPIO4 (optional, depends on sensor)
    // gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    return 0; // Indicate success
}

// Reads the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Controls the relay state
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", RELAY_PIN);
        return 1; // Indicate failure
    }
    relay_state = state; // Update global state
    return 0; // Indicate success
}

// Cleans up GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Turn off relay on exit
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // If touch is detected and debounced
        if (touch_detected == 1) {
            // Toggle relay state
            int new_relay_state = !relay_state;
            if (control_relay(new_relay_state) == 0) {
                printf("Touch detected, relay toggled to %d\n", new_relay_state);
            } else {
                fprintf(stderr, "Failed to toggle relay\n");
            }

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

