    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, *hw_params_temp, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "cannot set sample format (%s)\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, *hw_params_temp, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "cannot set channel count (%s)\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, *hw_params_temp, &sample_rate, 0)) < 0) {
        fprintf(stderr, "cannot set sample rate (%s)\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, *hw_params_temp, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "cannot set period size (%s)\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, *hw_params_temp)) < 0) {
        fprintf(stderr, "cannot set parameters (%s)\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_prepare(*pcm_handle)) < 0) {
        fprintf(stderr, "cannot prepare audio interface for use (%s)\n", snd_strerror(err));
        return -1;
    }

    *pcm_handle = *pcm_handle; // Assign to global variable
    *hw_params = *hw_params_temp; // Assign to global variable

    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    running = 0;

    // Stop PWM
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    // Close ALSA device
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }

    // Free ALSA hardware parameters
    if (hw_params) {
        snd_pcm_hw_params_free(hw_params);
    }

    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    cleanup();
    exit(0);
}

// Function to read audio data from ALSA
int read_audio_data(short *buffer, int buffer_size) {
    int err;
    int frames_read = 0;

    while (frames_read < buffer_size && running) {
        err = snd_pcm_readi(pcm_handle, buffer + frames_read, buffer_size - frames_read);
        if (err == -EPIPE) {
            fprintf(stderr, "Error: Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err == -ESTRPIPE) {
            fprintf(stderr, "Error: Playback suspended\n");
            snd_pcm_resume(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading audio: %s\n", snd_strerror(err));
            return -1;
        } else {
            frames_read += err;
        }
    }

    if (!running) return 0; // Exit loop if signal received

    if (frames_read < 0) {
        fprintf(stderr, "Error: Short read, only %d frames read\n", frames_read);
        return -1;
    }

    return frames_read;
}

// Function to calculate RMS amplitude
float calculate_rms(const short *buffer, int buffer_size) {
    double sum_sq = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / buffer_size);
}

// Function to map amplitude to color
void map_amplitude_to_color(float amplitude, int *red, int *green, int *blue) {
    // Non-linear mapping: cool colors for low amplitude, warm colors for high amplitude
    float normalized_amplitude = (amplitude - MIN_AMPLITUDE) / (MAX_AMPLITUDE - MIN_AMPLITUDE);
    normalized_amplitude = fmax(0.0, fmin(1.0, normalized_amplitude)); // Clamp to 0-1

    // Use a logarithmic scale for color mapping
    float log_amplitude = log10(1.0 + normalized_amplitude); // Avoid log(0)

    // Map log_amplitude to RGB values
    *red = (int)(log_amplitude * 255.0); // Scale to 0-255
    *green = (int)(log_amplitude * 255.0); // Scale to 0-255
    *blue = (int)(log_amplitude * 255.0); // Scale to 0-255
}

// Function to set LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to simulate audio input
void simulate_audio() {
    short buffer[PERIOD_SIZE];
    float amplitude = 0.0;
    int red, green, blue;

    while (running) {
        // Generate a sine wave for simulation
        for (int i = 0; i < PERIOD_SIZE; i++) {
            amplitude += 127.0; // Amplitude of sine wave
            if (amplitude > 255.0) amplitude = 255.0;
            if (amplitude < -127.0) amplitude = -127.0;
            buffer[i] = (short)(amplitude * 127.0); // Scale to 16-bit range
        }

        // Calculate RMS amplitude
        float rms_amplitude = calculate_rms(buffer, PERIOD_SIZE);

        // Map RMS amplitude to color
        map_amplitude_to_color(rms_amplitude, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }
}

int main(int argc, char *argv[]) {
    int opt;
    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0) {
                    fprintf(stderr, "Error: Sensitivity must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity]\n", argv[0]);
                return 1;
        }
    }

    // Initialize ALSA
    if (init_alsa(&pcm_handle, &hw_params) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    short audio_buffer[PERIOD_SIZE];
    int frames_read;
    float rms_amplitude;
    int red, green, blue;

    printf("Mood light started. Press Ctrl+C to exit.\n");

    if (alsa_available) {
        while (running) {
            frames_read = read_audio_data(audio_buffer, PERIOD_SIZE);
            if (frames_read > 0) {
                rms_amplitude = calculate_rms(audio_buffer, PERIOD_SIZE);
                map_amplitude_to_color(rms_amplitude, &red, &green, &blue);
                set_led_color(red, green, blue);
            } else {
                fprintf(stderr, "Error reading audio data\n");
            }
        }
    } else {
        simulate_audio();
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

