#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define the number of phases
#define NUM_PHASES 4

// Define the duration of each phase in seconds
#define PHASE_DURATION 3600 // 1 hour

// Define the duration of daytime in seconds
#define DAYTIME_DURATION 21600 // 6 hours

// Define the duration of nighttime in seconds
#define NIGHTTIME_DURATION 518400 // 14.4 hours

// Global variable to track the current phase index
volatile int current_phase = 0;

// Global variable to track the current time
time_t current_time;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void set_relay_state(int relay_pin, int state);
void simulate_brightness_increase(int relay_pin);
void simulate_brightness_decrease(int relay_pin);
void simulate_daytime(void);
void simulate_nighttime(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the GPIO chip
int initialize_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the lines for the relay pins
    relay1_line = gpiod_line_get(chip, RELAY1_PIN);
    relay2_line = gpiod_line_get(chip, RELAY2_PIN);
    relay3_line = gpiod_line_get(chip, RELAY3_PIN);
    relay4_line = gpiod_line_get(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the lines for output
    if (gpiod_line_request_output(relay1_line, "sunset_simulator", 0) < 0 ||
        gpiod_line_request_output(relay2_line, "sunset_simulator", 0) < 0 ||
        gpiod_line_request_output(relay3_line, "sunset_simulator", 0) < 0 ||
        gpiod_line_request_output(relay4_line, "sunset_simulator", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Close the chip
    gpiod_chip_close(chip);

    return 0;
}

// Function to cleanup the GPIO chip
void cleanup_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip for cleanup");
        return;
    }

    // Release the lines
    gpiod_line_release(relay1_line);
    gpiod_line_release(relay2_line);
    gpiod_line_release(relay3_line);
    gpiod_line_release(relay4_line);

    // Close the chip
    gpiod_chip_close(chip);
}

// Function to set the state of a relay
void set_relay_state(int relay_pin, int state) {
    struct gpiod_line *line;
    line = gpiod_line_get(gpiod_chip_open_by_name(GPIO_CHIP), relay_pin);
    if (!line) {
        perror("Error getting GPIO line");
        return;
    }
    gpiod_line_set_value(line, state);
}

// Function to simulate brightness increase
void simulate_brightness_increase(int relay_pin) {
    int duty_cycle = 0;
    int i;

    for (i = 0; i <= 255; i++) {
        set_relay_state(relay_pin, 1);
        duty_cycle += 1;
        if (duty_cycle > 255) break;
        sleep(1);
    }
}

// Function to simulate brightness decrease
void simulate_brightness_decrease(int relay_pin) {
    int duty_cycle = 255;
    int i;

    for (i = 255; i >= 0; i--) {
        set_relay_state(relay_pin, 1);
        duty_cycle -= 1;
        if (duty_cycle < 0) break;
        sleep(1);
    }
}

// Function to simulate daytime
void simulate_daytime(void) {
    printf("Daytime\n");
    for (int i = 0; i < DAYTIME_DURATION; i++) {
        simulate_brightness_decrease(RELAY1_PIN);
        simulate_brightness_decrease(RELAY2_PIN);
        simulate_brightness_decrease(RELAY3_PIN);
        simulate_brightness_decrease(RELAY4_PIN);
        sleep(1);
    }
}

// Function to simulate nighttime
void simulate_nighttime(void) {
    printf("Nighttime\n");
    for (int i = 0; i < NIGHTTIME_DURATION; i++) {
        set_relay_state(RELAY1_PIN, 0);
        set_relay_state(RELAY2_PIN, 0);
        set_relay_state(RELAY3_PIN, 0);
        set_relay_state(RELAY4_PIN, 0);
        sleep(1);
    }
}

int main(void) {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO chip
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Main loop
    while (1) {
        // Get the current time
        current_time = time(NULL);

        // Determine the current phase
        int phase_index = (current_time % (NUM_PHASES * PHASE_DURATION + DAYTIME_DURATION + NIGHTTIME_DURATION)) % NUM_PHASES;

        // Print the phase
        printf("Phase: %d\n", phase_index);

        // Simulate the current phase
        switch (phase_index) {
            case 0: // Sunrise
                printf("Sunrise\n");
                for (int i = 0; i < PHASE_DURATION; i++) {
                    simulate_brightness_increase(RELAY1_PIN);
                    simulate_brightness_increase(RELAY2_PIN);
                    simulate_brightness_increase(RELAY3_PIN);
                    simulate_brightness_increase(RELAY4_PIN);
                    sleep(1);
                }
                break;
            case 1: // Daytime
                printf("Daytime\n");
                simulate_daytime();
                break;
            case 2: // Sunset
                printf("Sunset\n");
                for (int i = 0; i < PHASE_DURATION; i++) {
                    simulate_brightness_decrease(RELAY1_PIN);
                    simulate_brightness_decrease(RELAY2_PIN);
                    simulate_brightness_decrease(RELAY3_PIN);
                    simulate_brightness_decrease(RELAY4_PIN);
                    sleep(1);
                }
                break;
            case 3: // Nighttime
                printf("Nighttime\n");
                simulate_nighttime();
                break;
            default:
                printf("Invalid phase\n");
                break;
        }
    }

    return 0;
}

