#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_S 5
#define LOG_FILE "motion_log.txt"

static volatile int running = 1;
static volatile unsigned long last_trigger_time = 0;

// Function to generate ISO 8601 timestamp
char* generate_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y%m%d_%H%M%S", timeinfo);
    return timestamp;
}

// Function to log motion detection event
void log_motion(const char* timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s: Motion detected\n", timestamp);
    fclose(fp);
}

// Function to capture video
int capture_video() {
    char* timestamp = generate_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to generate timestamp for video filename.\n");
        return -1;
    }

    char filename[50];
    snprintf(filename, sizeof(filename), "/home/pi/videos/%s.h264", timestamp);

    char command[100];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_S);

    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid command");
        free(timestamp);
        return -1;
    }

    printf("Video captured: %s\n", filename);
    free(timestamp);
    return 0;
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_time = gpioTick();

    if (level == 0) { // Obstacle detected (LOW signal)
        if (current_time - last_trigger_time > DEBOUNCE_MS * 1000) { // Debounce
            char* timestamp = generate_timestamp();
            if (timestamp != NULL) {
                printf("Motion detected at %s\n", timestamp);
                log_motion(timestamp);
                if (capture_video() != 0) {
                    fprintf(stderr, "Failed to capture video.\n");
                }
                free(timestamp);
            }
            last_trigger_time = current_time;
        }
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up resistor (optional, depending on sensor wiring)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set alert function for motion detection
    gpioSetAlertFuncEx(GPIO_PIN, motion_detected_callback, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Clean up
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

