#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x19
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0f

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpu6050(int i2c_handle);
int read_gyro_data(int i2c_handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    terminate = 1;
}

// Initializes the MPU-6050 sensor
int initialize_mpu6050(int i2c_handle) {
    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set sample rate divider to 125 Hz
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Set gyroscope full-scale range to ±250°/s
    if (i2cWriteByteData(i2c_handle, GYRO_XOUT_H, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set full-scale range\n");
        return -1;
    }

    return 0;
}

// Reads gyroscope data from the MPU-6050
int read_gyro_data(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read all six bytes at once
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyro data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Logs the gyroscope data to a CSV file
void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    fprintf(fp, "%ld,%f,%f,%f\n", timestamp_ms, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    float x, y, z;
    int reinit_attempts = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (initialize_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Attempting re-initialization...\n");
            reinit_attempts = 0; // Reset re-initialization attempts
            while (reinit_attempts < 3) {
                if (initialize_mpu6050(i2c_handle) == 0) {
                    printf("MPU-6050 re-initialized successfully.\n");
                    break; // Exit re-initialization loop
                } else {
                    fprintf(stderr, "Error: MPU-6050 re-initialization failed. Attempt %d/3\n", reinit_attempts + 1);
                    reinit_attempts++;
                    gpioDelay(100); // Wait before retrying
                }
            }
            if (reinit_attempts == 3) {
                fprintf(stderr, "Error: Failed to re-initialize MPU-6050 after multiple attempts. Continuing with potentially faulty sensor.\n");
            }
        }

        gpioDelay(10); // Sample at approximately 100 Hz
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

