int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize relays to HIGH (inactive)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to read moisture sensor data
int read_moisture_sensor(int zone) {
    static int moisture_level = 0;
    static time_t last_seed_time = 0;
    time_t current_time = time(NULL);

    // Seed the random number generator every 60 seconds
    if (difftime(current_time, last_seed_time) >= 60) {
        srand(time(NULL));
        last_seed_time = current_time;
    }

    // Generate a random moisture level between 0 and 100
    moisture_level = rand() % 101;

    return moisture_level;
}

