#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32

// GPIO pin for alarm
#define ALARM_PIN 27

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// Alarm duration (seconds)
#define ALARM_DURATION 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
void log_freefall_event(int16_t x, int16_t y, int16_t z);
void alarm_handler();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        accelerometer_data_t data;

        // Read accelerometer data
        if (read_accelerometer_data(&data.x, &data.y, &data.z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            continue; // Continue to the next iteration
        }

        // Convert to g-force
        float x_g = convert_to_g(data.x);
        float y_g = convert_to_g(data.y);
        float z_g = convert_to_g(data.z);

        // Check for freefall
        if (fabs(x_g) < FREEFALL_THRESHOLD && fabs(y_g) < FREEFALL_THRESHOLD && fabs(z_g) < FREEFALL_THRESHOLD) {
            // Check if freefall duration is reached
            if (time(NULL) - last_freefall_time >= FREEFALL_DURATION) {
                // Log freefall event
                log_freefall_event(data.x, data.y, data.z);
                // Trigger alarm
                alarm_handler();
                // Update last freefall time
                last_freefall_time = time(NULL);
            }
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup
    fclose(log_file);
    gpioWrite(ALARM_PIN, 0); // Set GPIO low
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize ADXL345
int adxl345_init() {
    // Open I2C device
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADXL345 for ±2g range and full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) != 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read 6 bytes starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine bytes to form 16-bit values
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw value to g-force
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 256.0;
}

// Log freefall event to file
void log_freefall_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Handle alarm event
void alarm_handler() {
    gpioWrite(ALARM_PIN, 1); // Set GPIO high
    gpioDelay(ALARM_DURATION * 1000000); // Wait for alarm duration (in microseconds)
    gpioWrite(ALARM_PIN, 0); // Set GPIO low
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

