#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 4000.0   // cm
#define TIMEOUT 100000         // us (100 ms)
#define MAX_PULSE_WIDTH 23200  // us (4 meters)

// Global variables
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int echo_received = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
void cleanup();

// Interrupt handler for ECHO pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) // Rising edge
    {
        pthread_mutex_lock(&mutex);
        start_tick = tick;
        echo_received = 1; // Indicate that a rising edge has been received
        pthread_mutex_unlock(&mutex);
    }
    else if (level == 0) // Falling edge
    {
        pthread_mutex_lock(&mutex);
        end_tick = tick;
        pthread_mutex_unlock(&mutex);
    }
}

// Function to trigger the ultrasonic pulse
void trigger_pulse()
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width)
{
    if (pulse_width <= 0)
    {
        return -1.0; // Indicate an invalid pulse width
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log the distance to a file
void log_distance(double distance)
{
    if (distance < 0)
    {
        fprintf(stderr, "Error: Invalid distance measurement.\n");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    pthread_mutex_lock(&mutex);
    if (log_file != NULL)
    {
        fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    pthread_mutex_unlock(&mutex);
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup()
{
    printf("Cleaning up resources...\n");
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set up interrupt handler for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running)
    {
        trigger_pulse();
        gpioDelay(200); // Wait 200 ms

        pthread_mutex_lock(&mutex);
        if (log_file != NULL)
        {
            uint32_t pulse_width = end_tick - start_tick;
            if (pulse_width > 0 && pulse_width <= MAX_PULSE_WIDTH)
            {
                double distance = calculate_distance(pulse_width);
                if (distance >= 0)
                {
                    log_distance(distance);
                }
            }
        }
        pthread_mutex_unlock(&mutex);

        if (!echo_received)
        {
            // Timeout occurred
            fprintf(stderr, "Timeout: No echo received within %d us\n", TIMEOUT);
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

