#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define GPIO_BUZZER 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define NUM_SENSORS 2

// Global variables
int i2c_handles[NUM_SENSORS];
int freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
int impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int configure_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int detect_freefall(float magnitude, float threshold);
int detect_impact(float magnitude, float threshold);
void activate_buzzer(int gpio_pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Configure the LIS3DH accelerometer
int configure_lis3dh(int i2c_handle) {
    // Set data rate to 100 Hz and full scale to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from the LIS3DH
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g units (sensitivity is 16384 LSB/g)
    *x = (float)x_raw / 16384.0;
    *y = (float)y_raw / 16384.0;
    *z = (float)z_raw / 16384.0;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Detect freefall
int detect_freefall(float magnitude, float threshold) {
    return (magnitude < threshold) ? 1 : 0;
}

// Detect impact
int detect_impact(float magnitude, float threshold) {
    return (magnitude > threshold) ? 1 : 0;
}

// Activate the buzzer for 1 second
void activate_buzzer(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Turn buzzer on
    gpioDelay(1000000);     // Wait for 1 second
    gpioWrite(gpio_pin, 0); // Turn buzzer off
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "f:i:")) != -1) {
        switch (opt) {
            case 'f':
                freefall_threshold = atof(optarg);
                break;
            case 'i':
                impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-f freefall_threshold] [-i impact_threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for the buzzer
    gpioSetMode(GPIO_BUZZER, PI_OUTPUT);

    // Initialize I2C for each sensor
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = init_i2c(I2C_BUS, LIS3DH_ADDR);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Failed to initialize I2C for sensor %d\n", i);
            // Attempt to close any previously initialized handles
            for (int j = 0; j < i; j++) {
                i2cClose(i2c_handles[j]);
            }
            gpioTerminate();
            return 1;
        }
        if (configure_lis3dh(i2c_handles[i]) < 0) {
            fprintf(stderr, "Failed to configure LIS3DH sensor %d\n", i);
            // Attempt to close any previously initialized handles
            for (int j = 0; j <= i; j++) {
                i2cClose(i2c_handles[j]);
            }
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            float x, y, z, magnitude;

            if (read_acceleration(i2c_handles[i], &x, &y, &z) == 0) {
                magnitude = calculate_magnitude(x, y, z);

                if (detect_freefall(magnitude, freefall_threshold)) {
                    printf("Sensor %d: Freefall detected! Magnitude: %.3f g\n", i, magnitude);
                }

                if (detect_impact(magnitude, impact_threshold)) {
                    printf("Sensor %d: Impact detected! Magnitude: %.3f g\n", i, magnitude);
                    activate_buzzer(GPIO_BUZZER);
                }
            } else {
                fprintf(stderr, "Error reading from sensor %d\n", i);
            }
        }
        gpioDelay(10); // Delay for 10ms (adjust as needed)
    }

    // Close I2C connections and terminate pigpio
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2cClose(i2c_handles[i]);
    }
    gpioTerminate();

    return 0;
}

