#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Stepper motor steps per revolution
#define STEPS_PER_REV 2048

// Conversion factor (steps per mm)
#define STEPS_PER_MM 10

// Square side length (mm)
#define SQUARE_SIDE 50

// Step delay (microseconds)
#define STEP_DELAY 1000

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void set_gpio_output(int pin);
void set_gpio_mode(int pin, int mode);
void step_motor(int motor, int steps);
void move_motor(int motor, int direction, int steps);
void draw_square();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Stopping motors and cleaning up...\n");
        program_running = 0;
    }
}

// Function to set a GPIO pin as output
void set_gpio_output(int pin) {
    int result = gpioSetMode(pin, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %d\n", pin, result);
    }
}

