#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Default I2C address and threshold
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int configure_sensor(int handle);
int read_acceleration(int handle, float *x, float *y, float *z);
void log_event(float x, float y, float z);
void shutdown_system(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Configure the LIS3DH sensor
int configure_sensor(int handle) {
    // CTRL_REG1: 0x57 (ODR = 100 Hz, FS = ±2g, High Resolution)
    if (i2cWriteByteData(handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: 0x88 (FS = ±2g, High Resolution)
    if (i2cWriteByteData(handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the LIS3DH
int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, OUT_X_L | 0x80, buffer, 6) < 0) { // Read multiple bytes with auto-increment
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to g
    *x = (float)raw_x * 0.0009765625;
    *y = (float)raw_y * 0.0009765625;
    *z = (float)raw_z * 0.0009765625;

    return 0;
}

// Log high acceleration event to file
void log_event(float x, float y, float z) {
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - High acceleration detected: X=%.4f g, Y=%.4f g, Z=%.4f g\n", s, x, y, z);
    fclose(fp);
}

// Shutdown the system
void shutdown_system(float x, float y, float z) {
    printf("High acceleration detected! Shutting down...\n");
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex, octal, or decimal
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Error: Threshold must be greater than 0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c(i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    float x, y, z;
    while (!terminate) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Check for high acceleration
            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                log_event(x, y, z);
                shutdown_system(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay (10 Hz)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

