// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIOLINE 0

// Define circular buffer size
#define BUFFER_SIZE 5

// Define alert duration (seconds)
#define ALERT_DURATION 2

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *left_line, *center_line, *right_line, *alert_line;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int read_sensor(int gpio);
void add_to_buffer(CircularBuffer *cb, int value);
int get_from_buffer(CircularBuffer *cb, int index);
void control_alert(int alert_state);
void line_following_logic(int center_value);
void signal_handler(int sig);
int initialize_gpio(void);
void cleanup_gpio(void);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get a value from the circular buffer at a specific index
int get_from_buffer(CircularBuffer *cb, int index) {
    if (index < 0 || index >= cb->count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return -1; // Indicate error
    }
    int index_in_buffer = (cb->head - cb->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[index_in_buffer];
}

// Control the alert pin (LED or buzzer)
void control_alert(int alert_state) {
    if (alert_state) {
        if (gpiod_line_set_value(alert_line, 1) < 0) {
            fprintf(stderr, "Error setting alert pin HIGH\n");
        }
    } else {
        if (gpiod_line_set_value(alert_line, 0) < 0) {
            fprintf(stderr, "Error setting alert pin LOW\n");
        }
    }
}

