#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD 5.0 // mT
#define SAMPLE_INTERVAL 100 // ms
#define MAX_POLL_ATTEMPTS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor(float *field_mT);
void control_relay(int state);
void log_event(const char *event_type, float field_mT, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float field_mT;
    int relay_state;
} sensor_data_t;

int main() {
    float field_mT;
    int relay_state = 0; // 0 = off, 1 = on

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor(&field_mT) == 0) {
            // Control relay based on field strength
            if (field_mT > FIELD_THRESHOLD * 100) {
                relay_state = 1; // Turn on relay
            } else {
                relay_state = 0; // Turn off relay
            }

            // Log the event
            log_event("field_reading", field_mT, relay_state);
        } else {
            log_event("sensor_read_error", 0.0, relay_state); // Log error
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize the pigpio library and I2C connection
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output for relay control
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read magnetic field data from the Si7210 sensor
int read_sensor(float *field_mT) {
    int field_raw;
    int poll_count = 0;
    int field_data[2];

    // Start a conversion by writing 0x01 to register 0xC1
    if (i2cWriteByteData(i2c_handle, 0xC1, 0x01) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return 1;
    }

    // Wait for the conversion to complete with timeout
    while (poll_count < MAX_POLL_ATTEMPTS) {
        if (i2cReadByteData(i2c_handle, 0xC1) == 0x00) {
            break; // Conversion complete
        } else {
            poll_count++;
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }

    if (poll_count >= MAX_POLL_ATTEMPTS) {
        fprintf(stderr, "Timeout waiting for conversion\n");
        return 1;
    }

    // Read the field strength data (2 bytes from register 0xC0)
    if (i2cReadI2CBlockData(i2c_handle, 0xC0, (char *)field_data, 2) != 2) {
        fprintf(stderr, "Failed to read field strength data\n");
        return 1;
    }

    // Combine the two bytes into a signed 16-bit value
    field_raw = (field_data[1] << 8) | field_data[0];

    // Convert to milliTesla units of 0.01 mT
    *field_mT = (float)field_raw * 25 / 1000.0;

    return 0;
}

// Control the relay (GPIO 17) based on the field strength
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log events to the magnetic_events.txt file
void log_event(const char *event_type, float field_mT, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s %s, Field: %.2f mT, Relay: %s\n",
            timestamp, event_type, field_mT, (relay_state == 1) ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

