#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024

// Global variables for signal handling
int server_fd = -1;
int client_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int setup_gpio();
int setup_socket();
void handle_client(int client_fd);
void log_event(const char *message);
void cleanup();
void signal_handler(int signum);

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Function to initialize GPIO using pigpio
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    log_event("GPIO initialized successfully.");
    return 0;
}

// Function to set up the TCP socket
int setup_socket() {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket failed");
        log_event("Socket creation failed");
        return -1;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Socket bind failed");
        close(fd);
        return -1;
    }

    if (listen(fd, 3) < 0) {
        perror("listen failed");
        log_event("Socket listen failed");
        close(fd);
        return -1;
    }

    log_event("Socket setup successfully.");
    return fd;
}

// Function to handle client commands
void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        log_event("Receive failed");
        close(client_fd);
        return;
    }

