#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define FLOW_THRESHOLD 5.0 // ml/min
#define RELAY_GPIO 18
#define RELAY_ON 1
#define RELAY_OFF 0
#define LOG_FILE "flow_log.txt"

// Global variables
static volatile int running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int open_i2c_handle(int bus, int addr);
int write_i2c(int handle, uint16_t command);
int read_i2c(int handle, char *buffer, int count);
int validate_crc(uint8_t data[], int len, uint8_t polynomial);
float convert_to_ml_min(int16_t raw_value);
void control_relay(int gpio, int state);
void log_flow_rates(float flow1, float flow2);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C handle
int open_i2c_handle(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to write to an I2C device
int write_i2c(int handle, uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read from an I2C device
int read_i2c(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC
int validate_crc(uint8_t data[], int len, uint8_t polynomial) {
    uint8_t crc = crc8(data, len, polynomial);
    if (crc != data[len]) {
        fprintf(stderr, "CRC validation failed for data: %02X %02X %02X\n", data[0], data[1], data[2]);
        return -1;
    }
    return 0;
}

// Function to convert raw data to ml/min
float convert_to_ml_min(int16_t raw_value) {
    return (float)raw_value / 1500.0;
}

// Function to control the relay
void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to log flow rates
void log_flow_rates(float flow1, float flow2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(log_file, "%s.%09ld,%.2f,%.2f\n", timestamp, ts.tv_nsec, flow1, flow2);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = open_i2c_handle(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = open_i2c_handle(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 18 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, RELAY_OFF); // Initialize relay to OFF

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        char buffer[3];
        int16_t raw_flow1, raw_flow2;
        float flow1, flow2;

        // Sensor 1
        if (write_i2c(i2c_handle1, 0x36) != 0) {
            fprintf(stderr, "Failed to write to sensor 1\n");
            continue; // Skip to the next cycle
        }
        if (read_i2c(i2c_handle1, buffer, 3) != 0) {
            fprintf(stderr, "Failed to read from sensor 1\n");
            continue; // Skip to the next cycle
        }
        if (validate_crc(buffer, 3, 0x31) != 0) {
            fprintf(stderr, "CRC validation failed for sensor 1\n");
            continue; // Skip to the next cycle
        }
        raw_flow1 = (int16_t)((buffer[0] << 8) | buffer[1]);
        flow1 = convert_to_ml_min(raw_flow1);

        // Sensor 2
        if (write_i2c(i2c_handle2, 0x36) != 0) {
            fprintf(stderr, "Failed to write to sensor 2\n");
            continue; // Skip to the next cycle
        }
        if (read_i2c(i2c_handle2, buffer, 3) != 0) {
            fprintf(stderr, "Failed to read from sensor 2\n");
            continue; // Skip to the next cycle
        }
        if (validate_crc(buffer, 3, 0x31) != 0) {
            fprintf(stderr, "CRC validation failed for sensor 2\n");
            continue; // Skip to the next cycle
        }
        raw_flow2 = (int16_t)((buffer[0] << 8) | buffer[1]);
        flow2 = convert_to_ml_min(raw_flow2);

        // Control relay
        if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
            control_relay(RELAY_GPIO, RELAY_ON);
        } else {
            control_relay(RELAY_GPIO, RELAY_OFF);
        }

        // Log flow rates
        log_flow_rates(flow1, flow2);

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioWrite(RELAY_GPIO, RELAY_OFF); // Ensure relay is OFF on exit
    gpioTerminate();

    return 0;
}

