#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdbool.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define ENA_PIN 22
#define IN1_PIN 23
#define IN2_PIN 24

// Define constants
#define RAIN_DETECTED 0  // Rain sensor output is LOW when rain is detected
#define DRY 1             // Rain sensor output is HIGH when dry
#define MOTOR_CLOSE_TIME 5 // Motor run time in seconds
#define DRY_READINGS 3    // Number of consecutive dry readings to suppress re-trigger

// Global variables
static volatile bool running = true;
static volatile int dry_readings = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int close_window();
int stop_motor();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        stop_motor();
        gpioTerminate();
        closelog();
        running = false;
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set RAIN_SENSOR_PIN mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ENA_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set ENA_PIN mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(IN1_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set IN1_PIN mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(IN2_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set IN2_PIN mode");
        gpioTerminate();
        return -1;
    }

    // Set pull-up resistor on the rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

