#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define BUTTON_UNLOCK_PIN 21
#define BUTTON_LOCK_PIN 22

// Define pulse widths
#define UNLOCK_PULSE_WIDTH 1000
#define LOCK_PULSE_WIDTH 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, stopping servo and terminating pigpio...\n");
}

// Function to set the servo pulse width
int set_servo_pulse(int pulse_width) {
    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to lock the door
int lock_door() {
    if (set_servo_pulse(LOCK_PULSE_WIDTH) != 0) {
        return -1;
    }
    printf("Door locked.\n");
    return 0;
}

// Function to unlock the door
int unlock_door() {
    if (set_servo_pulse(UNLOCK_PULSE_WIDTH) != 0) {
        return -1;
    }
    printf("Door unlocked.\n");
    return 0;
}

// Function to check button state with debouncing
int check_button(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
    return state;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_UNLOCK_PIN, PI_INPUT);
    gpioSetMode(BUTTON_LOCK_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_UNLOCK_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_LOCK_PIN, PI_PUD_UP);

    // Set initial servo position (center)
    set_servo_pulse(1500); // Example center position

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check unlock button
        if (check_button(BUTTON_UNLOCK_PIN)) {
            if (unlock_door() == 0) {
                gpioDelay(500 * 1000); // Delay to prevent multiple unlocks
            }
        }

        // Check lock button
        if (check_button(BUTTON_LOCK_PIN)) {
            if (lock_door() == 0) {
                gpioDelay(500 * 1000); // Delay to prevent multiple locks
            }
        }

        gpioDelay(10 * 1000); // Small delay to reduce CPU usage
    }

    // Stop servo and terminate pigpio
    set_servo_pulse(0); // Stop servo
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

