#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 4
#define FLOODLIGHT_GPIO 17
#define LOG_FILE "security_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    int motion_detected;
    int floodlight_duration;
    int pigpio_init_result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Configure GPIO pins
    if (gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MOTION_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOODLIGHT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FLOODLIGHT_GPIO);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read motion sensor
        motion_detected = gpioRead(MOTION_SENSOR_GPIO);

        if (motion_detected == 1) {
            // Motion detected
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Activate floodlight
            if (gpioWrite(FLOODLIGHT_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to write to GPIO %d\n", FLOODLIGHT_GPIO);
                program_running = 0; // Stop the program
                break;
            }

            // Log activation
            fprintf(log_file, "%s Motion Detected\n", timestamp);
            fflush(log_file);

            // Measure duration
            floodlight_duration = 60; // Fixed duration of 60 seconds

            // Deactivate floodlight
            if (gpioWrite(FLOODLIGHT_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to write to GPIO %d\n", FLOODLIGHT_GPIO);
                program_running = 0; // Stop the program
                break;
            }

            // Log deactivation
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            fprintf(log_file, "%s Floodlight deactivated for %d seconds\n", timestamp, floodlight_duration);
            fflush(log_file);

        } else {
            // No motion detected
            //printf("No motion detected\n");
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FLOODLIGHT_GPIO, 0); // Ensure floodlight is off
    gpioTerminate();

    printf("Smart Security Light System stopped.\n");
    return 0;
}

