#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>
#include <errno.h>
#include <pthread.h>

// Constants
#define GPIO_CHIP "gpiochip0"
#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY) // Period in microseconds
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define LOG_FILE "security.log"

// Global variables
static volatile int running = 1;
static int server_fd, new_socket;
static struct gpiod_chip *chip;
static struct gpiod_line *servo_line, *pir_line;
static FILE *log_file;

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
int init_socket(void);
void *servo_pwm_thread(void *arg);
int parse_command(char *command, int *angle, int *pir_state);
int set_servo_angle(int angle);
int read_pir_sensor(void);
int log_event(const char *message);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO
int init_gpio(void) {
    int ret;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Error opening GPIO chip: %s", GPIO_CHIP);
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        syslog(LOG_ERR, "Error getting servo line: %s", GPIO_CHIP);
        gpiod_chip_close(chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Error getting PIR line: %s", GPIO_CHIP);
        gpiod_chip_close(chip);
        return -1;
    }

    config.consumer = "servo_pwm";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(servo_line, &config, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Error requesting servo line: %s", GPIO_CHIP);
        gpiod_chip_close(chip);
        return -1;
    }

    config.consumer = "servo_pwm";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(pir_line, &config, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Error requesting PIR line: %s", GPIO_CHIP);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Initialize socket
int init_socket(void) {
    int opt = 1;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        syslog(LOG_ERR, "Setsockopt failed: %s", strerror(errno));
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        syslog(LOG_ERR, "Bind failed: %s", strerror(errno));
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
