#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define I2C_BUS 1
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_bh1750();
void control_relay(float lux);
void log_data(float lux);
void signal_handler(int signal);

// Function to read lux value from BH1750 sensor
float read_bh1750() {
    int raw_value;
    int retries = 0;
    while (retries < RETRY_COUNT) {
        // Send the "One-Time High-Resolution Mode" command
        if (i2cWriteByteData(i2c_handle, 0x00, 0x20) < 0) {
            fprintf(stderr, "Error: Failed to write to I2C device. Retry: %d\n", retries + 1);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(120); // Wait for conversion (at least 120ms)

        // Read two bytes from the sensor
        char buffer[2];
        if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
            fprintf(stderr, "Error: Failed to read from I2C device. Retry: %d\n", retries + 1);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Combine the bytes into a 16-bit integer
        raw_value = (buffer[0] << 8) | buffer[1];

        // Convert raw value to lux
        float lux = (float)raw_value / 1.2;
        return lux;
    }

    fprintf(stderr, "Error: Failed to read BH1750 after %d retries.\n", RETRY_COUNT);
    return -1.0; // Indicate an error
}

// Function to control the relay based on lux value
void control_relay(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Activate relay (turn on grow light)
    } else {
        gpioWrite(RELAY_GPIO, 0); // Deactivate relay (turn off grow light)
    }
}

// Function to log data to a file
void log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO23 as output for relay control
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_bh1750();
        if (lux >= 0) {
            control_relay(lux);
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error: Failed to read lux value\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

