    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO23 as output for relay control
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_bh1750();
        if (lux >= 0) {
            control_relay(lux);
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error: Failed to read lux value\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

