#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define DOUT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 25

// Define HX711 parameters
#define NUM_READINGS 5
#define TARE_READINGS 10
#define WEIGHT_THRESHOLD 1000.0 // grams
#define SOLENOID_DURATION 200 // ms
#define POLL_INTERVAL 500 // ms

// Define HX711 commands
#define HX711_CMD_READ 0x01
#define HX711_CMD_TARE 0x00

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *dout_line, *sck_line, *solenoid_line;
static volatile sig_atomic_t running = 1;
static float tare_offset = 0.0;

// Function prototypes
int init_gpio(void);
int read_hx711(int *raw_value);
float convert_to_weight(int raw_value, float scale);
float tare(void);
float average_readings(int *readings, int num_readings);
void control_solenoid(int state);
void signal_handler(int sig);
void cleanup(void);
void log_message(int priority, const char *message);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        running = 0;
        log_message(LOG_INFO, "Received signal, shutting down...");
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    if (!dout_line) {
        log_message(LOG_ERR, "Failed to get DOUT line");
        goto cleanup;
    }

    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    if (!sck_line) {
        log_message(LOG_ERR, "Failed to get SCK line");
        goto cleanup;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        log_message(LOG_ERR, "Failed to get solenoid line");
        goto cleanup;
    }

    ret = gpiod_line_request_output(solenoid_line, "solenoid", 0);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to request solenoid line as output");
        goto cleanup;
    }

    ret = gpiod_line_request_input(dout_line, "dout");
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to request DOUT line as input");
        goto cleanup;
    }

    ret = gpiod_line_request_input(sck_line, "sck");
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to request SCK line as input");
        goto cleanup;
    }

    log_message(LOG_INFO, "GPIO initialization complete");
    return 0;

cleanup:
    cleanup();
    return -1;
}

// Read data from HX711
int read_hx711(int *raw_value) {
    int i;
    int data = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Wait for DOUT to go LOW
    while (gpiod_line_get_value(dout_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) - start_time.tv_sec > 1) {
            log_message(LOG_ERR, "Timeout waiting for DOUT to go LOW");
            return -1; // Timeout
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpiod_line_set_value(sck_line, 1);
        usleep(1); // Small delay
        data = data << 1;
        if (gpiod_line_get_value(dout_line)) {
            data++;
        }
        gpiod_line_set_value(sck_line, 0);
        usleep(1); // Small delay
    }

    // Send one extra clock pulse for channel A, gain 128
    gpiod_line_set_value(sck_line, 1);
    usleep(1); // Small delay
    gpiod_line_set_value(sck_line, 0);
    usleep(1); // Small delay

    // Convert to signed 32-bit integer
    *raw_value = data ^ 0x800000; // Convert to signed

    return 0;
}

// Convert raw reading to weight in grams
float convert_to_weight(int raw_value, float scale) {
    return (float)(raw_value - tare_offset) / scale;
}

// Tare the load cell
float tare(void) {
    float sum = 0.0;
    int raw_value;

    log_message(LOG_INFO, "Starting tare procedure...");
    for (int i = 0; i < TARE_READINGS; i++) {
        if (read_hx711(&raw_value) == 0) {
            sum += raw_value;
        } else {
            log_message(LOG_ERR, "Error reading HX711 during tare");
            return -1.0; // Indicate tare failure
        }
        usleep(10000); // 10ms delay
    }

    tare_offset = sum / TARE_READINGS;
    log_message(LOG_INFO, "Tare offset: %f", tare_offset);
    return 0.0; // Indicate tare success
}

// Average multiple readings
float average_readings(int *readings, int num_readings) {
    float sum = 0.0;
    for (int i = 0; i < num_readings; i++) {
        sum += readings[i];
    }
    return sum / num_readings;
}

// Control the solenoid lock
void control_solenoid(int state) {
    if (gpiod_line_set_value(solenoid_line, state) < 0) {
        log_message(LOG_ERR, "Failed to set solenoid state");
    }
}

// Cleanup resources
void cleanup(void) {
    log_message(LOG_INFO, "Cleaning up resources...");
    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 0); // Ensure solenoid is off
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
    }
    if (sck_line) {
        gpiod_line_release(sck_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main(int argc, char *argv[]) {
    int i;
    int raw_value;
    float weight;
    float avg_weight;
    float tare_result;

    // Parse command-line arguments
    int threshold = WEIGHT_THRESHOLD;
    float scale = 1.0;
    int duration = SOLENOID_DURATION;

    if (argc > 1) {
        threshold = atoi(argv[1]);
    }
    if (argc > 2) {
        scale = atof(argv[2]);
    }
    if (argc > 3) {
        duration = atoi(argv[3]);
    }

    // Initialize syslog
    openlog("load_cell_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        return 1;
    }

    log_message(LOG_INFO, "Load cell monitor started");

    // Main loop
    while (running) {
        // Tare the load cell
        tare_result = tare();
        if (tare_result != 0.0) {
            log_message(LOG_ERR, "Tare failed, using previous offset");
        }

        // Read multiple readings and average
        int readings[NUM_READINGS];
        for (i = 0; i < NUM_READINGS; i++) {
            if (read_hx711(&raw_value) == 0) {
                readings[i] = raw_value;
            } else {
                log_message(LOG_ERR, "Error reading HX711");
                readings[i] = -1; // Indicate error
            }
        }

        avg_weight = average_readings(readings, NUM_READINGS);

        // Convert to weight and check threshold
        weight = convert_to_weight(avg_weight, scale);

        if (weight > threshold) {
            log_message(LOG_INFO, "Weight above threshold, activating solenoid");
            control_solenoid(1); // Activate solenoid
            usleep(duration * 1000); // Wait for specified duration
            control_solenoid(0); // Deactivate solenoid
            log_message(LOG_INFO, "Solenoid deactivated");
        }

        // Print weight to console (optional)
        printf("Weight: %.2f grams\n", weight);

        // Wait before next measurement
        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

