#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define KEEPALIVE 60

static volatile int running = 1;
static struct mosquitto *mosq = NULL;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen == 0) {
        syslog(LOG_ERR, "Empty message received: %s", message->topic);
        return;
    }

    if (strcmp(message->payload, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1); // Relay ON
        syslog(LOG_INFO, "Received ON, setting GPIO %d HIGH", GPIO_PIN);
    } else if (strcmp(message->payload, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0); // Relay OFF
        syslog(LOG_INFO, "Received OFF, setting GPIO %d LOW", GPIO_PIN);
    } else {
        syslog(LOG_ERR, "Invalid message received: %s", message->payload);
    }
}

int main() {
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    mosquitto_lib_init();
    mosq = mosquitto_new("relay_controller_1", true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Connected to MQTT broker %s:%d", MQTT_BROKER, MQTT_PORT);

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to topic %s: %s", MQTT_TOPIC, mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Subscribed to topic %s", MQTT_TOPIC);

    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // -1 for blocking, 1 for max 1 message processed
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            sleep(5);
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
            mosquitto_lib_cleanup();
            closelog();
            mosquitto_lib_init();
            mosq = mosquitto_new("relay_controller_1", true, NULL);
            if (!mosq) {
                syslog(LOG_ERR, "Failed to create mosquitto instance");
                closelog();
                return 1;
            }
            rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
                closelog();
                return 1;
            }
            rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "Failed to subscribe to topic %s: %s", MQTT_TOPIC, mosquitto_strerror(rc));
                closelog();
                return 1;
            }
            syslog(LOG_INFO, "Reconnecting to MQTT broker %s:%d", MQTT_BROKER, MQTT_PORT);
        }
    }

    syslog(LOG_INFO, "Disconnecting from MQTT broker");

    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    closelog();

    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();

    return 0;
}

