#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target Speed (RPM)
#define TARGET_SPEED 50.0

// Encoder Ticks per Revolution
#define ENCODER_TICKS 64

// Encoder Stall Detection Time (seconds)
#define STALL_TIMEOUT 2

// Global Variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile int encoder_a_stall_count = 0;
volatile int encoder_b_stall_count = 0;
volatile int encoder_a_stall_start_time = 0;
volatile int encoder_b_stall_start_time = 0;
pthread_mutex_t encoder_a_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder_b_mutex = PTHREAD_MUTEX_INITIALIZER;

// PI Controller Gains
#define KP 0.5
#define KI 0.05

// PWM Frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// PWM Range
#define PWM_RANGE 255

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Structure to hold motor and encoder data
typedef struct {
    int in1;
    int in2;
    int pwm;
    int dir;
    int a_ticks;
    int b_ticks;
    int stall_count;
    int stall_start_time;
    pthread_mutex_t mutex;
} MotorEncoder;

MotorEncoder motor_a, motor_b;

// Function Prototypes
void motor_a_forward(int speed);
void motor_a_backward(int speed);
void motor_a_stop();
void motor_b_forward(int speed);
void motor_b_backward(int speed);
void motor_b_stop();
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double calculate_error(double setpoint, double actual);
double calculate_proportional(double error);
double calculate_integral(double error, double *integral);
void set_motor_speed(double speed);
void *encoder_thread(void *arg);
void signal_handler(int signal);

// Function to set motor direction and speed
void set_motor_speed(double speed) {
    if (speed > 0) {
        if (speed < 255) {
            gpioPWM(motor_a_pwm, (int)(speed * PWM_RANGE));
            gpioWrite(motor_a_dir, 1); // Forward
        } else {
            gpioPWM(motor_a_pwm, 255);
            gpioWrite(motor_a_dir, 1);
        }
    } else if (speed < 0) {
        if (speed > -255) {
            gpioPWM(motor_a_pwm, (int)((-speed) * PWM_RANGE));
            gpioWrite(motor_a_dir, 0); // Backward
        } else {
            gpioPWM(motor_a_pwm, 0);
            gpioWrite(motor_a_dir, 0);
        }
    } else {
        motor_a_stop();
    }
}

// Motor A functions
void motor_a_forward(int speed) {
    set_motor_speed(speed);
}

void motor_a_backward(int speed) {
    set_motor_speed(-speed);
}

void motor_a_stop() {
    gpioWrite(motor_a_dir, 0);
    gpioPWM(motor_a_pwm, 0);
}

// Motor B functions
void motor_b_forward(int speed) {
    set_motor_speed(speed);
}

void motor_b_backward(int speed) {
    set_motor_speed(-speed);
}

void motor_b_stop() {
    gpioWrite(motor_b_dir, 0);
    gpioPWM(motor_b_pwm, 0);
}

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    pthread_mutex_lock(&encoder_a_mutex);
    if (current_tick - last_tick > 1000) { // Debounce
        if (level == 1) {
            encoder_a_ticks++;
        } else if (level == 0) {
            encoder_a_ticks--;
        }
        last_tick = current_tick;
    }
    pthread_mutex_unlock(&encoder_a_mutex);
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    pthread_mutex_lock(&encoder_b_mutex);
    if (current_tick - last_tick > 1000) { // Debounce
        if (level == 1) {
            encoder_b_ticks++;
        } else if (level == 0) {
            encoder_b_ticks--;
        }
        last_tick = current_tick;
    }
    pthread_mutex_unlock(&encoder_b_mutex);
}

// Calculate RPM from encoder ticks
double calculate_rpm(int ticks) {
    double rpm = ((double)ticks / ENCODER_TICKS) * 60.0;
    return rpm;
}

// Calculate error for PI controller
double calculate_error(double setpoint, double actual) {
    return setpoint - actual;
}

// Calculate proportional term
double calculate_proportional(double error) {
    return KP * error;
}

// Calculate integral term
double calculate_integral(double error, double *integral) {
    *integral += KI * error;
    return *integral;
}

// Set motor speed based on PI controller output
void set_motor_speed(double speed) {
    pthread_mutex_lock(&motor_a_mutex);
    pthread_mutex_lock(&motor_b_mutex);
    double error_a = calculate_error(TARGET_SPEED, calculate_rpm(encoder_a_ticks));
    double error_b = calculate_error(TARGET_SPEED, calculate_rpm(encoder_b_ticks));

    double proportional_a = calculate_proportional(error_a);
    double integral_a = calculate_integral(error_a, &integral_a);
    double output_a = proportional_a + integral_a;

    double proportional_b = calculate_proportional(error_b);
    double integral_b = calculate_integral(error_b, &integral_b);
    double output_b = proportional_b + integral_b;

    pthread_mutex_unlock(&motor_a_mutex);
    pthread_mutex_unlock(&motor_b_mutex);

    if (output_a > 255) output_a = 255;
    if (output_a < 0) output_a = 0;
    if (output_b > 255) output_b = 255;
    if (output_b < 0) output_b = 0;

    set_motor_speed(output_a);
    set_motor_speed(output_b);
}

// Encoder stall detection thread
void *encoder_thread(void *arg) {
    while (program_running) {
        time_t now = time(NULL);
        if (encoder_a_stall_count > STALL_TIMEOUT) {
            fprintf(stderr, "WARNING: Encoder A stall detected!\n");
            encoder_a_stall_count = 0;
        }
        if (encoder_b_stall_count > STALL_TIMEOUT) {
            fprintf(stderr, "WARNING: Encoder B stall detected!\n");
            encoder_b_stall_count = 0;
        }
        sleep(1);
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motors...\n", signal);
    motor_a_stop();
    motor_b_stop();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Initialize motor and encoder data
    motor_a.in1 = MOTOR_A_IN1;
    motor_a.in2 = MOTOR_A_IN2;
    motor_a.pwm = MOTOR_A_PWM;
    motor_a.dir = MOTOR_A_DIR;
    motor_a.a_ticks = 0;
    motor_a.b_ticks = 0;
    motor_a.stall_count = 0;
    motor_a.stall_start_time = 0;
    pthread_mutex_init(&motor_a_mutex, NULL);

    motor_b.in1 = MOTOR_B_IN3;
    motor_b.in2 = MOTOR_B_IN4;
    motor_b.pwm = MOTOR_B_PWM;
    motor_b.dir = MOTOR_B_DIR;
    motor_b.a_ticks = 0;
    motor_b.b_ticks = 0;
    motor_b.stall_count = 0;
    motor_b.stall_start_time = 0;
    pthread_mutex_init(&motor_b_mutex, NULL);

    // Set up interrupt handlers
    gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL);
    gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL);
    gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL);
    gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create encoder stall detection thread
    pthread_t encoder_thread_id;
    if (pthread_create(&encoder_thread_id, NULL, encoder_thread, NULL) != 0) {
        perror("Failed to create encoder thread");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        set_motor_speed(calculate_rpm(encoder_a_ticks) / TARGET_SPEED);
        set_motor_speed(calculate_rpm(encoder_b_ticks) / TARGET_SPEED);
        gpioDelay(100); // 100 ms period
    }

    // Clean up
    pthread_join(encoder_thread_id, NULL);
    pthread_mutex_destroy(&motor_a_mutex);
    pthread_mutex_destroy(&motor_b_mutex);
    gpioTerminate();

    return 0;
}

