#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_DAWN 200
#define LUX_THRESHOLD_DUSK 50
#define Hysteresis 10
#define I2C_BUS 1
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_bh1750(int i2c_handle, float *lux);
void control_relay(int gpio_pin, int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    char config_cmd = 0x21; // One-Time High-Resolution Mode 2
    char buffer[2];
    int result;

    // Send configuration command
    result = i2cWriteByte(i2c_handle, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        *lux = -1.0; // Indicate error
        return 1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        *lux = -1.0; // Indicate error
        return 1;
    }

    // Convert raw data to lux
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    control_relay(RELAY_GPIO, 0); // Turn off relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_bh1750(i2c_handle, &lux) == 0) {
            // Control relay based on lux value and hysteresis
            if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
                control_relay(RELAY_GPIO, 1);
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
                control_relay(RELAY_GPIO, 0);
                relay_state = 0;
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
            control_relay(RELAY_GPIO, 0); // Turn off relay on error
            log_data(-1.0, relay_state); // Log error
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

