#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 50
#define MAIN_LOOP_DELAY_MS 10

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int relay_state = 0; // 0 = OFF, 1 = ON
    int last_touch_state = 0;
    int current_touch_state;
    struct timespec debounce_delay = {0, DEBOUNCE_DELAY_MS * 1000000L}; // 50ms
    struct timespec touch_release_delay = {0, 100 * 1000000L}; // 100ms

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIOs
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        current_touch_state = gpioRead(TOUCH_SENSOR_GPIO);

        if (current_touch_state == 1) {
            // Touch detected
            if (last_touch_state == 0) {
                // Rising edge
                printf("Touch detected (rising edge)\n");
                if (gpioWrite(RELAY_GPIO, !relay_state) != 0) {
                    fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_GPIO);
                }
                relay_state = !relay_state;
                printf("Relay state: %s\n", relay_state ? "ON" : "OFF");
                last_touch_state = 1;
            } else {
                // Falling edge (debounce)
                printf("Touch confirmed (falling edge)\n");
                if (gpioWrite(RELAY_GPIO, !relay_state) != 0) {
                    fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_GPIO);
                }
                relay_state = !relay_state;
                printf("Relay state: %s\n", relay_state ? "ON" : "OFF");
                last_touch_state = 1;
            }

            // Wait for touch release
            while (gpioRead(TOUCH_SENSOR_GPIO) == 1) {
                gpioDelay(100); // Small delay to prevent busy-waiting
            }

            // Touch release detected
            if (gpioRead(TOUCH_SENSOR_GPIO) == 0) {
                printf("Touch released\n");
                gpioDelay(touch_release_delay);
            }
        } else {
            // No touch detected
            gpioDelay(MAIN_LOOP_DELAY_MS);
        }
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
    gpioTerminate();
    printf("Relay control program terminated.\n");
    return 0;
}

