#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define SOLENOID_OPEN 1
#define SOLENOID_CLOSED 0
#define DEBOUNCE_TIME 1 // seconds

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
int solenoid_state = SOLENOID_OPEN; // Initial solenoid state

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
float calculate_lpm(int pulses);
void control_solenoid(float lpm);
void log_data(float lpm, int solenoid_state);
void signal_handler(int signal);

// Interrupt service routine (ISR)
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate LPM
float calculate_lpm(int pulses) {
    return (pulses / PULSES_PER_LITER) * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(float lpm) {
    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == SOLENOID_OPEN) {
        gpioWrite(SOLENOID_GPIO, SOLENOID_CLOSED);
        solenoid_state = SOLENOID_CLOSED;
        log_data(calculate_lpm(pulse_count), solenoid_state);
        printf("Solenoid closed due to high LPM: %.2f LPM\n", lpm);
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == SOLENOID_CLOSED) {
        gpioWrite(SOLENOID_GPIO, SOLENOID_OPEN);
        solenoid_state = SOLENOID_OPEN;
        log_data(calculate_lpm(pulse_count), solenoid_state);
        printf("Solenoid opened due to low LPM: %.2f LPM\n", lpm);
    }
}

// Function to log data to a file
void log_data(float lpm, int solenoid_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state == SOLENOID_OPEN ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Could not open log file!\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Reopen the solenoid valve to a safe state
    if (solenoid_state == SOLENOID_CLOSED) {
        gpioWrite(SOLENOID_GPIO, SOLENOID_OPEN);
        solenoid_state = SOLENOID_OPEN;
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Set solenoid to open initially
    gpioWrite(SOLENOID_GPIO, SOLENOID_OPEN);

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Disable interrupts temporarily
        gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable ISR temporarily
        pulse_count = 0; // Reset pulse count
        gpioDelay(DEBOUNCE_TIME * 1000000); // Debounce for 1 second

        // Re-enable interrupts
        if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
            fprintf(stderr, "Failed to re-enable ISR function\n");
            break; // Exit loop if re-enabling ISR fails
        }

        // Calculate LPM
        float lpm = calculate_lpm(pulse_count);

        // Control the solenoid valve
        control_solenoid(lpm);

        // Log the data
        log_data(lpm, solenoid_state);

        // Sleep for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup (in case the loop exits due to an error)
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable ISR
