#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Default values
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVO_PIN 18
#define DEFAULT_HX711_DATA_PIN 23
#define DEFAULT_HX711_CLOCK_PIN 24
#define DEFAULT_TIMEOUT_MS 1000
#define DEFAULT_LOG_FILE "dispensing_log.json"

// Global variables (minimize usage)
static int server_port = DEFAULT_SERVER_PORT;
static char *server_ip = DEFAULT_SERVER_IP;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static int servo_pin = DEFAULT_SERVO_PIN;
static int hx711_data_pin = DEFAULT_HX711_DATA_PIN;
static int hx711_clock_pin = DEFAULT_HX711_CLOCK_PIN;
static int timeout_ms = DEFAULT_TIMEOUT_MS;
static char *log_file = DEFAULT_LOG_FILE;
static int socket_desc = -1;
static FILE *log_file_ptr = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config();
int init_gpio();
int init_socket();
void handle_client(int client_socket);
int read_hx711();
double calibrate_hx711();
void set_servo_angle(int angle);
void log_event(double target_weight, double actual_weight);
void signal_handler(int signum);
void cleanup();

// HX711 read function with timeout
int read_hx711() {
    int data = 0;
    int attempts = 0;
    int timeout = timeout_ms * 1000; // Convert ms to microseconds

    while (attempts < timeout) {
        // Wait for DATA pin to go low
        while (gpioRead(hx711_data_pin) == 1) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            attempts++;
            if (attempts > timeout) {
                fprintf(stderr, "Error: HX711 timeout (DATA pin high)\n");
                return -1; // Indicate timeout error
            }
        }

        // Read 24 bits of data
        for (int i = 0; i < 24; i++) {
            gpioWrite(hx711_clock_pin, 1);
            gpioDelay(1); // Clock pulse width
            data = data << 1;
            if (gpioRead(hx711_data_pin)) {
                data++;
            }
            gpioWrite(hx711_clock_pin, 0);
            gpioDelay(1); // Clock pulse width
        }

        // Pulse the clock pin 1 more time to set the gain to 128
        gpioWrite(hx711_clock_pin, 1);
        gpioDelay(1);
        gpioWrite(hx711_clock_pin, 0);
        gpioDelay(1);

        // Convert to signed 2's complement
        if (data & 0x800000) {
            data |= ~0xffffff;
        }

        return data;
    }

    fprintf(stderr, "Error: HX711 timeout (max attempts reached)\n");
    return -1; // Indicate timeout error
}

// Calibration function
double calibrate_hx711() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in grams): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight\n");
        return -1.0;
    }

    printf("Reading raw value...\n");
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: HX711 read failed during calibration\n");
        return -1.0;
    }

    double ratio = (double)raw_value / known_weight;
    calibration_factor = 1.0 / ratio; // Invert the ratio for calibration
    printf("Calibration factor: %lf\n", calibration_factor);
    return calibration_factor;
}

// Servo control function
void set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle: %d\n", angle);
        return;
    }

    int pulse_width = 1000 + (int)((float)angle / 180.0 * 1000.0);
    gpioServo(servo_pin, pulse_width);
}

// Logging function
void log_event(double target_weight, double actual_weight) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file_ptr, "{\"date\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": null}\n",
            timestamp, target_weight, actual_weight);
    fflush(log_file_ptr); // Ensure data is written to disk immediately
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (socket_desc != -1) {
        close(socket_desc);
    }
    if (log_file_ptr != NULL) {
        fclose(log_file_ptr);
    }
    gpioTerminate();
}

// Read configuration from file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open config file %s, using defaults.\n", CONFIG_FILE);
        return 1; // Indicate failure to open config file
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "server_ip") == 0) {
                server_ip = strdup(value); // Allocate memory for the string
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            } else if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "servo_pin") == 0) {
                servo_pin = atoi(value);
            } else if (strcmp(key, "hx711_data_pin") == 0) {
                hx711_data_pin = atoi(value);
            } else if (strcmp(key, "hx711_clock_pin") == 0) {
                hx711_clock_pin = atoi(value);
            } else if (strcmp(key, "timeout_ms") == 0) {
                timeout_ms = atoi(value);
            } else if (strcmp(key, "log_file") == 0) {
                log_file = strdup(value); // Allocate memory for the string
            }
        }
    }

    fclose(fp);
    return 0; // Indicate success
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration
    if (read_config() != 0) {
        fprintf(stderr, "Warning: Could not read config file, using defaults.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (gpioSetMode(servo_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set servo pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(hx711_data_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set HX711 data pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(hx711_clock_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set HX711 clock pin mode\n");
        cleanup();
        return 1;
    }

    // Initialize socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Set up server address
    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_addr.s_addr = inet_addr(server_ip);
    server.sin_port = htons(server_port);

    // Bind socket to address
    if (bind(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(socket_desc, 3) < 0) {
        perror("Listen failed");
        cleanup();
        return 1;
    }

    printf("Server listening on %s:%d...\n", server_ip, server_port);

    // Main loop
    while (!terminate) {
        // Accept connection
        int client_socket = accept(socket_desc, NULL, NULL);
        if (client_socket < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted\n");

        // Handle client
        handle_client(client_socket);

        // Close client socket
        close(client_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;
    double target_weight, actual_weight;
    int raw_value;
    double ratio;
    int angle;

    // Receive weight from client
    printf("Received connection, waiting for weight...\n");
    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("Recv failed");
        close(client_socket);
        return;
    }
    buffer[valread] = '\0';
    target_weight = atof(buffer);

    // Open servo
    set_servo_angle(0); // Open servo
    gpioDelay(1000); // Wait 1 second

    // Read HX711
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: HX711 read failed\n");
        close(client_socket);
        return;
    }

    // Calculate actual weight
    ratio = raw_value / calibration_factor;
    actual_weight = ratio;

    // Map weight to servo angle
    angle = (int)((float)actual_weight / 1000.0 * 180.0); // Assuming max weight is 1000g
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    // Set servo angle
    set_servo_angle(angle);

    // Wait 1 second
