int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration
    if (read_config() != 0) {
        fprintf(stderr, "Warning: Could not read config file, using defaults.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (gpioSetMode(servo_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set servo pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(hx711_data_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set HX711 data pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(hx711_clock_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set HX711 clock pin mode\n");
        cleanup();
        return 1;
    }

    // Initialize socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Set up server address
    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_addr.s_addr = inet_addr(server_ip);
    server.sin_port = htons(server_port);

    // Bind socket to address
    if (bind(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(socket_desc, 3) < 0) {
        perror("Listen failed");
        cleanup();
        return 1;
    }

    printf("Server listening on %s:%d...\n", server_ip, server_port);

    // Main loop
    while (!terminate) {
        // Accept connection
        int client_socket = accept(socket_desc, NULL, NULL);
        if (client_socket < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted\n");

        // Handle client
        handle_client(client_socket);

        // Close client socket
        close(client_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;
    double target_weight, actual_weight;
    int raw_value;
    double ratio;
    int angle;

    // Receive weight from client
    printf("Received connection, waiting for weight...\n");
    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("Recv failed");
        close(client_socket);
        return;
    }
    buffer[valread] = '\0';
    target_weight = atof(buffer);

    // Open servo
    set_servo_angle(0); // Open servo
    gpioDelay(1000); // Wait 1 second

    // Read HX711
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: HX711 read failed\n");
        close(client_socket);
        return;
    }

    // Calculate actual weight
    ratio = raw_value / calibration_factor;
    actual_weight = ratio;

    // Map weight to servo angle
    angle = (int)((float)actual_weight / 1000.0 * 180.0); // Assuming max weight is 1000g
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    // Set servo angle
    set_servo_angle(angle);

    // Wait 1 second
    gpioDelay(1000);

    // Read HX711 again
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: HX711 read failed during actual weight reading\n");
        close(client_socket);
        return;
    }

    // Calculate actual weight
    ratio = raw_value / calibration_factor;
    actual_weight = ratio;

    // Send actual weight to client
    char response[256];
    snprintf(response, sizeof(response), "Actual weight: %.2f\n", actual_weight);
    send(client_socket, response, strlen(response), 0);

    // Log event
    log_event(target_weight, actual_weight);

    printf("Dispensing complete\n");
    close(client_socket);
}

