#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEFAULT_DEBOUNCE_TIME 50

// Global variable to track relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce_touch();
int toggle_relay();
int set_relay_state(int state);
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal, cleaning up...\n");
        set_relay_state(0); // Turn relay OFF
        gpioTerminate(); // Release pigpio resources
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN to input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Read the touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounce the touch sensor
int debounce_touch() {
    int stable_count = 0;
    int current_state = read_touch_sensor();
    if (current_state == 1) {
        for (int i = 0; i < 5; i++) {
            if (read_touch_sensor() == 1) {
                stable_count++;
            }
            gpioDelay(DEFAULT_DEBOUNCE_TIME / 5); // Divide debounce time for 5 readings
            if (stable_count >= 5) {
                return 1; // Valid touch detected
            }
        }
    }
    return 0; // No stable touch detected
}

// Toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    return 0;
}

// Set the relay state
int set_relay_state(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to RELAY_PIN\n");
        return 1;
    }
    return 0;
}

// Log the relay state to the console
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line argument for debounce time
    if (argc > 1) {
        int debounce_time = atoi(argv[1]);
        if (debounce_time > 0) {
            DEFAULT_DEBOUNCE_TIME = debounce_time;
        } else {
            fprintf(stderr, "Invalid debounce time. Using default value: %d ms\n", DEFAULT_DEBOUNCE_TIME);
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch-controlled relay switch started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (debounce_touch()) {
            toggle_relay();
            set_relay_state(relay_state);
            log_relay_state(relay_state);
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

