#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <termios.h>
#include <unistd.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD (1000000 / PWM_FREQUENCY) // microseconds
#define MIN_PULSE_WIDTH 500 // us
#define MAX_PULSE_WIDTH 2500 // us
#define DEFAULT_ANGLE 90

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

int main() {
    int angle = DEFAULT_ANGLE;
    int pulse_width;
    int gpio_init_result;

    // Register signal handler for SIGINT (Ctrl-C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    gpio_init_result = gpioInitialise();
    if (gpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", gpio_init_result);
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Save terminal settings
    struct termios orig_termios;
    if (tcgetattr(STDIN_FILENO, &orig_termios) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    // Set non-canonical mode
    struct termios new_termios;
    tcgetattr(STDIN_FILENO, &orig_termios);
    new_termios = orig_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new_termios);

    printf("Servo control started. Press '+' to increase, '-' to decrease, 'q' to quit.\n");

    while (program_running) {
        char input;
        int angle_change;

        printf("Angle: %d\n", angle);

        // Read input from the terminal
        input = getchar();

        if (input == '+') {
            angle_change = 10;
        } else if (input == '-') {
            angle_change = -10;
        } else if (input == 'q') {
            break;
        } else if (input == '\n') {
            // Handle newline character (Enter key)
            break;
        } else {
            // Ignore other characters
            continue;
        }

        // Validate angle change
        if (angle_change >= -90 && angle_change <= 90) {
            angle += angle_change;
        } else {
            fprintf(stderr, "Angle change out of range (-90 to 90). Using default.\n");
            angle_change = 0;
        }

        // Validate angle
        if (angle < 0) {
            angle = 0;
        } else if (angle > 180) {
            angle = 180;
        }

        // Calculate pulse width
        pulse_width = (int)(((float)angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);

        // Set servo position
        gpioServo(SERVO_PIN, pulse_width);

        // Print the current angle
        printf("Angle: %d\n", angle);
    }

    // Stop PWM pulses
    gpioServo(SERVO_PIN, 0);

    // Restore terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);

    // Terminate pigpio
    gpioTerminate();

    printf("Servo control stopped.\n");
    return 0;
}

