#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_MS 2
#define LOG_INTERVAL_SEC 5

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;
static struct timespec last_interrupt_time;

// Function prototypes
int gpio_init(void);
int gpio_request_input(struct gpiod_line *line, int flags);
int gpio_set_pull_up(struct gpiod_line *line, int pull_up);
int gpio_get_value(struct gpiod_line *line);
int gpio_event_wait(struct gpiod_line *line, struct timespec *timeout);
int count_pulse(void);
double calculate_rpm(int pulse_count);
int log_rpm(double rpm);
void signal_handler(int sig);

// GPIO initialization function
int gpio_init(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// GPIO request input function
int gpio_request_input(struct gpiod_line *line, int flags) {
    int ret = gpiod_line_request_input(line, flags);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input with flags 0x%08X: %s\n", line->line_number, flags, strerror(errno));
        return ret;
    }
    return 0;
}

// GPIO set pull-up function
int gpio_set_pull_up(struct gpiod_line *line, int pull_up) {
    int ret = gpiod_line_set_pull_up(line, pull_up);
    if (ret < 0) {
        fprintf(stderr, "Error setting pull-up on GPIO line %d: %s\n", line->line_number, strerror(errno));
        return ret;
    }
    return 0;
}

// GPIO get value function
int gpio_get_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting value from GPIO line %d: %s\n", line->line_number, strerror(errno));
        return -1;
    }
    return value;
}

// GPIO event wait function with debouncing
int gpio_event_wait(struct gpiod_line *line, struct timespec *timeout) {
    int ret = gpiod_line_event_wait(line, timeout);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for event on GPIO line %d: %s\n", line->line_number, strerror(errno));
        return -1;
    }
    return ret;
}

// Pulse counting function
int count_pulse(void) {
    struct timespec current_time;
