#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ACTIVE_HIGH 1
#define RELAY_INACTIVE_LOW 0
#define RELAY_ON_TIME 5 // seconds
#define TOUCH_TIMEOUT 10 // seconds

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN to input\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN to output\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading TOUCH_SENSOR_PIN\n");
        return -1;
    }
    return value;
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to RELAY_PIN\n");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up and exiting...\n");
    control_relay(RELAY_INACTIVE_LOW); // Ensure relay is OFF
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_detected = read_touch_sensor();
        if (touch_detected == 1) {
            // Toggle relay state
            int relay_state = (control_relay(RELAY_ACTIVE_HIGH) == 0) ? RELAY_ACTIVE_HIGH : RELAY_INACTIVE_LOW;
            printf("Relay toggled to %d\n", relay_state);

            // Debounce and touch timeout
            int last_touch_state = touch_detected;
            time_t start_time = time(NULL);

            while (read_touch_sensor() == 1 && !terminate) {
                gpioDelay(50); // Poll every 50ms
                last_touch_state = read_touch_sensor();
                if (last_touch_state == PI_BAD_GPIO) {
                    fprintf(stderr, "Error reading touch sensor during timeout check\n");
                    break;
                }
            }

            if (last_touch_state == 1) {
                time_t current_time = time(NULL);
                if (difftime(current_time, start_time) > TOUCH_TIMEOUT) {
                    printf("Touch sensor stuck HIGH for %ld seconds. Forcing relay OFF.\n", (long int)TOUCH_TIMEOUT);
                    control_relay(RELAY_INACTIVE_LOW);
                    break; // Exit the loop after timeout
                }
            }
        } else if (touch_detected == 0) {
            // Reset relay state if touch is released
            control_relay(RELAY_INACTIVE_LOW);
        }

        gpioDelay(50); // Delay for 50ms
    }

    cleanup();
    return 0;
}

