#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define VALVE_GPIO 18
#define ENABLE_GPIO 23
#define FLOW_SENSOR_GPIO 24
#define PWM_FREQUENCY 1000 // Hz
#define PULSES_PER_LITER 450
#define TARGET_FLOW_RATE "-t"
#define LOG_FILE "flow_log.csv"

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulse_count);
int control_valve(float flow_rate, float target_flow_rate);
void log_data(float flow_rate, int valve_position);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Calculate flow rate in L/min
float calculate_flow_rate(int pulse_count) {
    return (float)pulse_count / PULSES_PER_LITER / 60.0;
}

// Proportional controller to adjust valve position
int control_valve(float flow_rate, float target_flow_rate) {
    float error = target_flow_rate - flow_rate;
    int valve_position = (int)(error * 1.0); // Kp = 1.0

    // Clamp valve position to [0, 255]
    if (valve_position < 0) {
        valve_position = 0;
    } else if (valve_position > 255) {
        valve_position = 255;
    }

    return valve_position;
}

// Log data to file
void log_data(float flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main(int argc, char *argv[]) {
    float target_flow_rate = 0.0;

    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L/min>\n", argv[0]);
        return 1;
    }

    char *endptr;
    target_flow_rate = strtof(argv[1], &endptr);
    if (*endptr != '\0') {
        fprintf(stderr, "Invalid target flow rate: %s\n", argv[1]);
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(ENABLE_GPIO, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp_ms,flow_rate,L/min,valve_position\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Disable valve temporarily
        gpioWrite(ENABLE_GPIO, 0);
        gpioPWM(VALVE_GPIO, 0); // Stop PWM
        gpioDelay(1000); // Wait 1 ms

        // Read pulse count
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count

        // Enable valve and set PWM
        gpioWrite(ENABLE_GPIO, 1);
        gpioPWM(VALVE_GPIO, control_valve(calculate_flow_rate(current_pulse_count), target_flow_rate));

        // Log data
        log_data(calculate_flow_rate(current_pulse_count), gpioGetPWMdutycycle(VALVE_GPIO));

        // Wait 100 ms
        gpioDelay(100);
    }

    // Cleanup
    gpioWrite(ENABLE_GPIO, 0);
    gpioPWM(VALVE_GPIO, 0); // Stop PWM
    fclose(log_file);
    gpioTerminate();

    return 0;
}

