#include <pigpio.h>

// Define GPIO pins
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define BUTTON_GPIO 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define RFID tag ID
const unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};
#define TAG_LENGTH 10

// Define lock disengage and engage times
#define DISENGAGE_TIME 5 // seconds
#define ENGAGE_TIME 2    // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpioInitialise();
int spiOpen(int channel, int speed, int mode);
int spiXfer(int handle, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int gpioWrite(int gpio, int level);
int gpioRead(int gpio);
int buttonPress();
int rfidRead();
int authenticate();
int logEvent(const char *event);
void signalHandler(int signal);

// Function to initialize GPIO
int gpioInitialise() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open SPI channel
int spiOpen(int channel, int speed, int mode) {
    int handle = spiOpen(channel, speed, mode);
    if (handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        return -1;
    }
    return handle;
}

// Function to transfer data via SPI
int spiXfer(int handle, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    int result = spiXfer(handle, tx_buf, rx_buf, len);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }
    return 0;
}

// Function to write to a GPIO pin
int gpioWrite(int gpio, int level) {
    gpioWrite(gpio, level);
    return 0;
}

// Function to read from a GPIO pin
int gpioRead(int gpio) {
    return gpioRead(gpio);
}

// Function to check for button press
int buttonPress() {
    int level = gpioRead(BUTTON_GPIO);
    if (level == 0) { // Active low
        gpioDelay(50); // Debounce
        return 1;
    }
    return 0;
}

// Function to read RFID tag
int rfidRead() {
    unsigned char rx_buffer[TAG_LENGTH];
    if (spiXfer(spi_handle, NULL, rx_buffer, TAG_LENGTH) != TAG_LENGTH) {
        logEvent("RFID read failure");
        return -1;
    }

    // Basic check if the tag is valid
    if (memcmp(rx_buffer, valid_tag, TAG_LENGTH) != 0) {
        logEvent("Invalid RFID tag");
        return -1;
    }

    return 0;
}

// Function to authenticate user
int authenticate() {
    if (rfidRead() == 0) {
        logEvent("RFID authentication successful");
        gpioDelay(ENGAGE_TIME * 1000); // Engage locks for ENGAGE_TIME seconds
        gpioWrite(LOCK1_GPIO, 1);
        gpioWrite(LOCK2_GPIO, 1);
        return 1;
    } else {
        logEvent("RFID authentication failed");
        return 0;
    }
}

// Function to log events
int logEvent(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }
}

// Signal handler for clean shutdown
void signalHandler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Enable internal pull-up resistor

    printf("Two-factor authentication system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (authenticate()) {
            gpioWrite(LOCK1_GPIO, 0);
            gpioWrite(LOCK2_GPIO, 0);
            gpioDelay(DISENGAGE_TIME * 1000); // Disengage locks for DISENGAGE_TIME seconds
            gpioWrite(LOCK1_GPIO, 1);
            gpioWrite(LOCK2_GPIO, 1);
            gpioDelay(ENGAGE_TIME * 1000); // Re-engage locks for ENGAGE_TIME seconds
        } else {
            gpioDelay(1000); // Delay between authentication attempts
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LOCK1_GPIO, 1);
    gpioWrite(LOCK2_GPIO, 1);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

