#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>
#include <unistd.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR1_A 5
#define MOTOR1_B 6

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define MOTOR2_A 26
#define MOTOR2_B 19

// Encoder Counts
#define ENCODER_COUNTS 1

// PID Parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPMs
#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100

// Encoder Decoding Interval (ms)
#define ENCODER_DECODE_INTERVAL 1

// Log File
#define LOG_FILE "motor_log.csv"

// Global Variables
static volatile int encoder_counts[ENCODER_COUNTS] = 0;
static volatile int encoder_index = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold motor data
typedef struct {
    int ena_pin;
    int in1_pin;
    int in2_pin;
    int enb_pin;
    int in3_pin;
    int in4_pin;
    int a_pin;
    int b_pin;
    double target_rpm;
    double current_rpm;
    double pid_output;
    double integral;
    double previous_error;
} Motor;

// Function Prototypes
void *encoder_thread(void *arg);
double calculate_rpm(int encoder_count);
double pid_control(Motor *motor, double target_rpm, double current_rpm, double dt);
void set_motor_speed(Motor *motor, double pid_output);
void log_data(Motor *motor1, Motor *motor2);
void signal_handler(int sig);
int gpio_request(int pin, const char *request);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
int gpio_get_line(int pin);
int gpio_request_line(int pin, const char *request);
int gpio_set_line_value(int pin, int value);
int gpio_get_line_value(int pin);
void cleanup();

// Motor Structures
Motor motor1, motor2;

// Function to request a GPIO line
int gpio_request(int pin, const char *request) {
    struct gpiod_line *line = gpiod_chip_get_line(motor1.chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }
    if (gpiod_line_request(line, request, 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to set the direction of a GPIO line
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_line *line = gpiod_chip_get_line(motor1.chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }
    if (gpiod_line_set_direction(line, direction) < 0) {
        fprintf(stderr, "Error: Could not set direction for line %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to set the value of a GPIO line
int gpio_set_value(int pin, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(motor1.chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set value for line %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to get the value of a GPIO line
int gpio_get_value(int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(motor1.chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }
    return gpiod_line_get_value(line);
}

// Function to request a GPIO line for output
int gpio_request_line(int pin, const char *request) {
    struct gpiod_line *line = gpiod_chip_get_line(motor1.chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }
    if (gpiod_line_request_line(line, request, 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to set the value of a GPIO line for output
int gpio_set_line_value(int pin, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(motor1.chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set value for line %d\n", pin);
        return -1;
    }
    return 0;
}

// Encoder Thread Function
void *encoder_thread(void *arg) {
    while (running) {
        for (int i = 0; i < ENCODER_COUNTS; i++) {
            int a_value = gpio_get_value(motor1.a_pin);
            int b_value = gpio_get_value(motor1.b_pin);

            if (a_value < 0 || b_value < 0) {
                fprintf(stderr, "Error reading encoder values\n");
                break;
            }

            if (a_value == 0 && b_value == 1) {
                encoder_counts[i]++;
            } else if (a_value == 1 && b_value == 0) {
                encoder_counts[i]--;
            } else {
                encoder_counts[i] = 0; // Reset if no clear direction
            }
        }

        pthread_mutex_lock(&encoder_mutex);
        for (int i = 0; i < ENCODER_COUNTS; i++) {
            encoder_counts[i] = 0; // Reset counts for the next interval
        }
        encoder_index = (encoder_index + 1) % ENCODER_COUNTS;
        pthread_mutex_unlock(&encoder_mutex);

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = ENCODER_DECODE_INTERVAL * 1000000; // Convert ms to ns
        nanosleep(&sleep_time, NULL);
    }
    return NULL;
}

// Calculate RPM from encoder counts
double calculate_rpm(int encoder_count) {
    return (double)encoder_count / 600.0 * TARGET_RPM1; // Assuming 600 pulses per revolution
}

// PID Control Function
double pid_control(Motor *motor, double target_rpm, double current_rpm, double dt) {
    double error = target_rpm - current_rpm;
    double integral = integral + error * dt;
    double derivative = (error - previous_error) / dt;

    double output = KP * error + KI * integral + KD * derivative;

    previous_error = error;

    return output;
}

// Set Motor Speed Function
void set_motor_speed(Motor *motor, double pid_output) {
    // Software PWM implementation
    double duty_cycle = pid_output; // Use PID output as duty cycle
    double period = 1.0 / PWM_FREQUENCY; // Period in seconds
    double on_time = duty_cycle * period;
    double off_time = (1.0 - duty_cycle) * period;

    // Calculate on/off times in microseconds
    long on_time_us = (long)(on_time * 1000000);
    long off_time_us = (long)(off_time * 1000000);

    // Toggle ENA pin
    if (gpio_set_value(motor1.ena_pin, 1) < 0) {
        fprintf(stderr, "Error setting ENA high\n");
    }
    if (gpio_set_value(motor1.in1_pin, 1) < 0) {
        fprintf(stderr, "Error setting IN1 high\n");
    }
    if (gpio_set_value(motor1.in2_pin, 0) < 0) {
        fprintf(stderr, "Error setting IN2 low\n");
    }
    nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = on_time_us}, NULL);
    if (gpio_set_value(motor1.in1_pin, 0) < 0) {
        fprintf(stderr, "Error setting IN1 low\n");
    }
    if (gpio_set_value(motor1.in2_pin, 1) < 0) {
        fprintf(stderr, "Error setting IN2 high\n");
    }
    nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = off_time_us}, NULL);

    // Toggle ENB pin
    if (gpio_set_value(motor2.enb_pin, 1) < 0) {
        fprintf(stderr, "Error setting ENB high\n");
    }
    if (gpio_set_value(motor2.in3_pin, 1) < 0) {
        fprintf(stderr, "Error setting IN3 high\n");
    }
    if (gpio_set_value(motor2.in4_pin, 0) < 0) {
        fprintf(stderr, "Error setting IN4 low\n");
    }
    nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = on_time_us}, NULL);
    if (gpio_set_value(motor2.in3_pin, 0) < 0) {
        fprintf(stderr, "Error setting IN3 low\n");
    }
    if (gpio_set_value(motor2.in4_pin, 1) < 0) {
        fprintf(stderr, "Error setting IN4 high\n");
    }
    nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = off_time_us}, NULL);
}

// Log Data Function
void log_data(Motor *motor1, Motor *motor2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Motor1 RPM: %.2f, Motor2 RPM: %.2f, P: %.2f, I: %.2f, D: %.2f, Output: %.2f\n",
            timestamp, motor1.current_rpm, motor2.current_rpm, motor1.pid_output, motor1.integral, motor1.previous_error, motor1.pid_output);
    fflush(log_file);
}

// Signal Handler Function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

int main() {
    // Initialize GPIO pins
    if (gpio_request(MOTOR1_ENA, "out") < 0 ||
        gpio_request(MOTOR1_IN1, "out") < 0 ||
        gpio_request(MOTOR1_IN2, "out") < 0 ||
        gpio_request(MOTOR1_A, "in") < 0 ||
        gpio_request(MOTOR1_B, "in") < 0) {
        fprintf(stderr, "Error: Could not request GPIO pins for Motor 1\n");
        return 1;
    }

    if (gpio_request(MOTOR2_ENB, "out") < 0 ||
        gpio_request(MOTOR2_IN3, "out") < 0 ||
        gpio_request(MOTOR2_IN4, "out") < 0 ||
        gpio_request(MOTOR2_A, "in") < 0 ||
        gpio_request(MOTOR2_B, "in") < 0) {
        fprintf(stderr, "Error: Could not request GPIO pins for Motor 2\n");
        return 1;
    }

    // Initialize GPIO lines
