    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode Filter (EF) registers (example values)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // EF_CONFIG
        fprintf(stderr, "Error: EF_CONFIG write failed\n");
        return -1;
    }

    // Configure Release Thresholds (RTLx) for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30) < 0) { // RTLx
            fprintf(stderr, "Error: RTL%d write failed\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10) < 0) { // RTHx
            fprintf(stderr, "Error: RTH%d write failed\n", i);
            return -1;
        }
    }

    // Configure Touch Thresholds (TTHx) for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0A) < 0) { // TTHx
            fprintf(stderr, "Error: TTH%d write failed\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x05) < 0) { // TRLx
            fprintf(stderr, "Error: TRL%d write failed\n", i);
            return -1;
        }
    }

    // Enable all electrodes in run mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0F) < 0) { // ELE_CFG
        fprintf(stderr, "Error: ELE_CFG write failed\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(unsigned short *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = ((unsigned short)buf[1] << 8) | (unsigned short)buf[0];
    return 0;
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to relay GPIO\n");
        return -1;
    }
    return 0;
}

// Function to log the relay state to a file
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    unsigned short touch_status;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            if (touch_status > 0) {
                control_relay(1); // Activate relay
            } else {
                control_relay(0); // Deactivate relay
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(POLL_INTERVAL_MS); // Wait before next poll
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

