int initialize_gpio(struct gpiod_chip *chip, int gpio_pin);
int request_output_line(struct gpiod_line *line, int direction);
int set_gpio_value(struct gpiod_line *line, int value);
int unexport_gpio(struct gpiod_line *line);
int log_event(const char *event);
void cleanup_gpio(struct gpiod_line *valve1_line, struct gpiod_line *valve2_line);
void signal_handler(int signum);

// Function to initialize a GPIO pin
int initialize_gpio(struct gpiod_chip *chip, int gpio_pin) {
    struct gpiod_line *line = NULL;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_request_output(line, "watering", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request output line for GPIO %d: %s\n", gpio_pin, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    return line;
}

// Function to request an output line
int request_output_line(struct gpiod_line *line, int direction) {
    int ret = gpiod_line_request_output(line, "watering", direction);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request output line for GPIO %d: %s\n", line->line_number, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to set the GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO value for GPIO %d: %s\n", line->line_number, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO line
int unexport_gpio(struct gpiod_line *line) {
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release GPIO line for GPIO %d: %s\n", line->line_number, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to log an event with an ISO 8601 timestamp
int log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(struct gpiod_line *valve1_line, struct gpiod_line *valve2_line) {
    if (valve1_line) {
        unexport_gpio(valve1_line);
    }
    if (valve2_line) {
        unexport_gpio(valve2_line);
    }
}

