        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Request output lines
    if (request_output_line(valve1_line, 1) < 0) {
        cleanup_gpio(valve1_line, valve2_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }
    if (request_output_line(valve2_line, 1) < 0) {
        cleanup_gpio(valve1_line, valve2_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Activate Valve 1
        if (set_gpio_value(valve1_line, 1) < 0) {
            cleanup_gpio(valve1_line, valve2_line);
            gpiod_chip_close(chip);
            fclose(log_file);
            return 1;
        }
        log_event("Valve 1 activated");
        usleep(500000); // 500 ms

        // Pause
