#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define MPR121_I2C_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_TIME 0x20
#define ELE_EN 0x20
#define RUN_MODE 0x10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void toggle_relay(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode.\n");
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, TOUCH_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, RELEASE_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Set filter time and electrode current
    if (i2cWriteByteData(i2c_handle, 0x5C, FILTER_TIME) < 0) {
        fprintf(stderr, "Error: Failed to set filter time.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, ELE_EN) < 0) {
        fprintf(stderr, "Error: Failed to set electrode enable.\n");
        return -1;
    }

    // Enter run mode
    if (i2cWriteByteData(i2c_handle, 0x2B, RUN_MODE) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode.\n");
        return -1;
    }
    gpioDelay(100); // 100ms delay for stabilization

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(int i2c_handle) {
    int touch_status_low = i2cReadByteData(i2c_handle, 0x00);
    int touch_status_high = i2cReadByteData(i2c_handle, 0x01);

    if (touch_status_low < 0 || touch_status_high < 0) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// Function to toggle the relay
void toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_state);
    printf("Relay toggled to state: %d\n", !current_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output and initialize to off
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (touch_status > 0) {
            toggle_relay(RELAY_GPIO);
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

