    if (i2cWriteByteData(i2c_handle, 0x5D, ELE_EN) < 0) {
        fprintf(stderr, "Error: Failed to set electrode enable.\n");
        return -1;
    }

    // Enter run mode
    if (i2cWriteByteData(i2c_handle, 0x2B, RUN_MODE) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode.\n");
        return -1;
    }
    gpioDelay(100); // 100ms delay for stabilization

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(int i2c_handle) {
    int touch_status_low = i2cReadByteData(i2c_handle, 0x00);
    int touch_status_high = i2cReadByteData(i2c_handle, 0x01);

    if (touch_status_low < 0 || touch_status_high < 0) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// Function to toggle the relay
void toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_state);
    printf("Relay toggled to state: %d\n", !current_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output and initialize to off
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (touch_status > 0) {
            toggle_relay(RELAY_GPIO);
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

