#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_S 2
#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static time_t last_unlock_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void unlock_door();
void log_event(const char *event_type);
void rate_limit();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to unlock the door
void unlock_door() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for 500ms
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    log_event("Door unlocked");
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, event_type);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to implement rate limiting
void rate_limit() {
    time_t now = time(NULL);
    if (difftime(now, last_unlock_time) >= RATE_LIMIT_DURATION_S) {
        unlock_door();
        last_unlock_time = now;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
            if (read_pir_sensor() == 1) {
                unlock_door();
                rate_limit();
            }
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

