#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Global variable to signal program termination
volatile sig_atomic_t shutdown = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down gracefully...\n");
        shutdown = 1;
    }
}

// Function to generate a random PWM duty cycle (0-255)
int generate_random_pwm(int gpio) {
    return rand() % 256;
}

// Function to generate a random duration (50-200 ms)
int generate_random_duration() {
    return rand() % 151; // 200 - 50 + 1
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
    }
}

// Function to play a single step in the haptic feedback pattern
void play_step(int motor1_duty_cycle, int motor2_duty_cycle, int duration_ms) {
    set_pwm_duty_cycle(MOTOR1_GPIO, motor1_duty_cycle);
    set_pwm_duty_cycle(MOTOR2_GPIO, motor2_duty_cycle);
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
}

// Function to generate a haptic feedback pattern
void generate_pattern(int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        int motor1_duty_cycle = generate_random_pwm(MOTOR1_GPIO);
        int motor2_duty_cycle = generate_random_pwm(MOTOR2_GPIO);
        int duration_ms = generate_random_duration();
        play_step(motor1_duty_cycle, motor2_duty_cycle, duration_ms);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Seed the random number generator with the current time
    srand(time(NULL));

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Haptic feedback generator started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!shutdown) {
        generate_pattern(5 + (rand() % 11)); // 5 to 15 steps
        gpioDelay(100000); // 100ms delay between patterns
    }

    // Stop the motors and terminate the pigpio library before exiting
    set_pwm_duty_cycle(MOTOR1_GPIO, 0);
    set_pwm_duty_cycle(MOTOR2_GPIO, 0);
    gpioTerminate();

    printf("Haptic feedback generator stopped.\n");

    return 0;
}

