#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define NUM_CALIBRATION_READINGS 100
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define SOLENOID_LOCK_DURATION 5 // seconds
#define SOLENOID_RELEASE_DELAY 2 // seconds
#define HX711_TIMEOUT 0.5 // seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double scale_factor = 1.0;
static double offset = 0.0;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
int load_calibration_data();
int save_calibration_data();
double calibrate_sensor();
void control_solenoid(int lock);
void log_data(int raw_value, double weight);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int i;
    int data = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for the HX711 to be ready
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
        if (timeout_counter > HX711_TIMEOUT * 1000) { // Timeout after HX711_TIMEOUT seconds
            fprintf(stderr, "Error: HX711 timeout waiting for data pin to go low.\n");
            return 0; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    // Apply the 25th clock pulse for gain selection (default gain = 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Sign extend if negative
    if (data & 0x800000) {
        data |= (int)0xFF000000;
    }

    return data;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to load calibration data from file
int load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s. Using default calibration.\n", CALIBRATION_FILE);
        return -1; // Indicate failure
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%lf %lf", &scale_factor, &offset) == 2) {
            fclose(fp);
            printf("Calibration data loaded: scale_factor = %lf, offset = %lf\n", scale_factor, offset);
            return 0; // Indicate success
        } else {
            fprintf(stderr, "Error: Invalid calibration data in %s. Using default calibration.\n", CALIBRATION_FILE);
            fclose(fp);
            return -1; // Indicate failure
        }
    } else {
        fprintf(stderr, "Error: Calibration file %s is empty. Using default calibration.\n", CALIBRATION_FILE);
        fclose(fp);
        return -1; // Indicate failure
    }
}

// Function to save calibration data to file
int save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing.\n", CALIBRATION_FILE);
        return -1; // Indicate failure
    }

    fprintf(fp, "%lf %lf", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale_factor = %lf, offset = %lf\n", scale_factor, offset);
    return 0; // Indicate success
}

// Function to calibrate the sensor
double calibrate_sensor() {
    double sum = 0.0;
    int i;

    printf("Calibrating sensor. Please ensure no weight is applied.\n");
    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw_value = read_hx711();
        if (raw_value == 0) { // Handle timeout
            fprintf(stderr, "Error: Calibration read timed out.\n");
            return -1.0; // Indicate failure
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    double average_raw_value = sum / NUM_CALIBRATION_READINGS;
    scale_factor = 1.0 / average_raw_value; // Assuming raw value is proportional to weight
    offset = 0.0; // Assuming no offset with zero load
    printf("Calibration complete. scale_factor = %lf, offset = %lf\n", scale_factor, offset);
    return 0.0; // Indicate success
}

// Function to control the solenoid lock
void control_solenoid(int lock) {
    gpioWrite(SOLENOID_PIN, lock);
    printf("Solenoid set to %d\n", lock);
}

// Function to log data to file
void log_data(int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Raw: %d, Weight: %.2lf kg\n", timestamp, raw_value, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(SOLENOID_PIN, 0); // Unlock solenoid
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    int raw_value;
    double weight;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load calibration data
    if (load_calibration_data() != 0) {
        fprintf(stderr, "Error: Failed to load calibration data. Using default values.\n");
    }

    // Calibrate the sensor
    if (calibrate_sensor() != 0) {
        fprintf(stderr, "Error: Sensor calibration failed.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        raw_value = read_hx711();
        if (raw_value != 0) { // Check for timeout
            weight = convert_to_weight(raw_value);
            log_data(raw_value, weight);

            if (weight > 10.0) {
                control_solenoid(1); // Lock
                gpioDelay(SOLENOID_LOCK_DURATION * 1000); // Keep locked for SOLENOID_LOCK_DURATION seconds
                control_solenoid(0); // Unlock
                gpioDelay(SOLENOID_RELEASE_DELAY * 1000); // Wait before next check
            }
        } else {
            fprintf(stderr, "Error: HX711 read timed out. Skipping this iteration.\n");
        }

        gpioDelay(500); // Read every 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0); // Unlock solenoid
    gpioTerminate(); // Terminate pigpio
    fclose(log_file);

    return 0;
}

