int read_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < NUM_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
    }
    return (low_count >= (NUM_READINGS / 2)); // Treat rain as detected if at least half are low
}

