    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("Window control system started.");

    while (running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected && last_rain_state == 1) {
            // Rain detected and was dry before, debounce
            log_event("Rain detected after debounce.");
            close_window();
        }

        last_rain_state = rain_detected;
        gpioDelay(60000000); // 60 seconds
    }

    // Cleanup (should not reach here if signal handler works)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

