    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
        program_running = 0;
        gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low (data ready)
    int timeout_counter = 0;
    while (gpioRead(HX711_DT) == 1 && timeout_counter < HX711_TIMEOUT) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= HX711_TIMEOUT) {
        fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse SCK 25th time to set the gain to 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Two's complement conversion if negative
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

