#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to initialize GPIO lines
int initialize_gpio(int chip_name, int sensor_pin, int relay_pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *relay_line;
    int ret;

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    sensor_line = gpiod_chip_get_line(chip, sensor_pin);
    if (!sensor_line) {
        perror("Error getting sensor GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, relay_pin);
    if (!relay_line) {
        perror("Error getting relay GPIO line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(sensor_line, NULL, 0); // Request sensor line as input
    if (ret < 0) {
        perror("Error requesting sensor line");
        gpiod_line_release(relay_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(relay_line, NULL, 0); // Request relay line as output
    if (ret < 0) {
        perror("Error requesting relay line");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor(int chip, int sensor_pin) {
    struct gpiod_line *line = NULL;
    int ret;
    int value;

    line = gpiod_chip_get_line(chip, sensor_pin);
    if (!line) {
        perror("Error getting sensor line");
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("Error reading sensor value");
        gpiod_line_release(line);
        return -1;
    }

    value = ret;

    gpiod_line_release(line);
    return value;
}

// Function to toggle the relay state
int toggle_relay(int chip, int relay_pin, int current_state) {
    struct gpiod_line *line = NULL;
    int ret;
    int new_state = (current_state == 0) ? 1 : 0;

    line = gpiod_chip_get_line(chip, relay_pin);
    if (!line) {
        perror("Error getting relay line");
        return -1;
    }

    ret = gpiod_line_set_value(line, new_state);
    if (ret < 0) {
        perror("Error setting relay value");
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return new_state;
}

// Function to log the relay event
int log_relay_event(const char *log_file, int relay_state) {
    FILE *fp;
    time_t rawtime;
    struct tm *info;
    char timestamp[32];

    fp = fopen(log_file, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);

    fprintf(fp, "%s Relay: %s\n", timestamp, relay_state ? "ON" : "OFF");

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    int sensor_value, relay_state = 0; // Initial relay state
    int prev_sensor_value = -1; // Initialize to an invalid value

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(CHIP_NAME, SENSOR_PIN, RELAY_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        sensor_value = read_sensor(chip, SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        if (sensor_value == 0 && prev_sensor_value != 0) {
            // Obstacle detected (sensor active-low)
            relay_state = toggle_relay(chip, RELAY_PIN, relay_state);
            if (relay_state < 0) {
                fprintf(stderr, "Error toggling relay. Retrying...\n");
                sleep(1); // Wait before retrying
                continue;
            }

            if (log_relay_event(LOG_FILE, relay_state) < 0) {
                fprintf(stderr, "Error logging relay event. Retrying...\n");
                sleep(1); // Wait before retrying
                continue;
            }

            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            prev_sensor_value = sensor_value; // Update previous sensor value
        }

        prev_sensor_value = sensor_value; // Update previous sensor value
        usleep(100000); // 100ms delay
    }

    // Cleanup GPIO
    gpiod_line_release(gpiod_chip_get_line(chip, SENSOR_PIN));
    gpiod_line_release(gpiod_chip_get_line(chip, RELAY_PIN));
    gpiod_chip_close(chip);

    printf("Relay control program stopped.\n");

    return 0;
}

