#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO chip and line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18

// Define valve activation duration (seconds)
#define VALVE_DURATION 60

// Define GPIO line direction
#define GPIO_DIRECTION "out"

// Define GPIO line value
#define GPIO_VALUE 1

// Define GPIO line active-low setting
#define GPIO_ACTIVE_LOW 0

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read watering duration from configuration file
int read_watering_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "duration=%d", duration) != 1) {
        fprintf(stderr, "Error parsing line from file %s: %s\n", filename, line);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to initialize GPIO line
int initialize_gpio(int chip, int line, const char *direction, int active_low, int value) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip);
    if (!chip) {
        fprintf(stderr, "Error opening chip %s: %s\n", chip->name, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, line);
    if (!line) {
        fprintf(stderr, "Error getting line %d from chip %s: %s\n", line, chip->name, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request(line, direction, active_low, value);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d: %s\n", line, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO line value
int set_gpio_value(int chip, int line, int value) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening chip %s: %s\n", chip->name, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting line %d from chip %s: %s\n", line, chip->name, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting line %d value: %s\n", line, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to release GPIO line
int release_gpio(int chip, int line) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening chip %s: %s\n", chip->name, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting line %d from chip %s: %s\n", line, chip->name, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing line %d: %s\n", line, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int main() {
    int duration;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read watering duration from configuration file
    if (read_watering_duration("watering.conf", &duration) != 0) {
        fprintf(stderr, "Error reading watering duration. Exiting.\n");
        return 1;
    }

    // Check if duration is valid
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid watering duration. Must be between 1 and 3600 seconds. Exiting.\n");
        return 1;
    }

    // Initialize GPIO line
    if (initialize_gpio(GPIO_CHIP, GPIO_LINE, GPIO_DIRECTION, GPIO_ACTIVE_LOW, GPIO_VALUE) != 0) {
        fprintf(stderr, "Error initializing GPIO line. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Activate valve
        if (set_gpio_value(GPIO_CHIP, GPIO_LINE, GPIO_VALUE) != 0) {
            fprintf(stderr, "Error setting GPIO value. Exiting.\n");
            break;
        }
        fprintf(stdout, "Valve activated for %d seconds\n", duration);

        // Wait for watering duration
        struct timespec sleep_time;
        sleep_time.tv_sec = duration;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);

        // Deactivate valve
        if (set_gpio_value(GPIO_CHIP, GPIO_LINE, 0) != 0) {
            fprintf(stderr, "Error setting GPIO value. Exiting.\n");
            break;
        }
        fprintf(stdout, "Valve deactivated\n");
    }

    // Release GPIO line
    if (release_gpio(GPIO_CHIP, GPIO_LINE) != 0) {
        fprintf(stderr, "Error releasing GPIO line. Exiting.\n");
    }

    return 0;
}

