int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensors();
void control_motors(int left_sensor, int middle_sensor, int right_sensor);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_motor_speed, int right_motor_speed);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Stop motors
    gpioPWM(LEFT_PWM, 0);
    gpioPWM(RIGHT_PWM, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(LEFT_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_PWM, PI_OUTPUT);
    gpioSetMode(LEFT_DIR, PI_OUTPUT);
    gpioSetMode(RIGHT_DIR, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_PWM, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(LEFT_PWM, 255);
    gpioSetPWMrange(RIGHT_PWM, 255);

    return 0;
}

// Read sensor values
int read_sensors() {
    int left_sensor = gpioRead(LEFT_SENSOR);
    int middle_sensor = gpioRead(MIDDLE_SENSOR);
    int right_sensor = gpioRead(RIGHT_SENSOR);

    // Active-low sensors: 0 means obstacle detected
    return (left_sensor << 2) | (middle_sensor << 1) | right_sensor;
}

// Control motor speeds based on sensor readings
void control_motors(int left_sensor, int middle_sensor, int right_sensor) {
    int left_motor_speed = BASE_SPEED;
    int right_motor_speed = BASE_SPEED;

    if (left_sensor == 0) {
        // Obstacle on left, turn right
        left_motor_speed = BASE_SPEED / 2;
        right_motor_speed = BASE_SPEED * 1.5; // Increase right motor speed
    } else if (right_sensor == 0) {
        // Obstacle on right, turn left
        right_motor_speed = BASE_SPEED / 2;
        left_motor_speed = BASE_SPEED * 1.5; // Increase left motor speed
    } else if (middle_sensor == 0) {
        // Obstacle in the middle, move straight
        left_motor_speed = BASE_SPEED;
        right_motor_speed = BASE_SPEED;
    } else {
        // No obstacle, stop
        left_motor_speed = 0;
        right_motor_speed = 0;
    }

    // Set motor directions (forward)
    gpioWrite(LEFT_DIR, 1);
    gpioWrite(RIGHT_DIR, 1);

    // Set motor speeds
    gpioPWM(LEFT_PWM, left_motor_speed);
    gpioPWM(RIGHT_PWM, right_motor_speed);
}

// Log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_motor_speed, int right_motor_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_motor_speed, right_motor_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int sensors = read_sensors();
        control_motors(sensors);
        log_data(sensors, sensors, sensors, gpioGetPWMdutycycle(LEFT_PWM), gpioGetPWMdutycycle(RIGHT_PWM));
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(LEFT_PWM, 0);
    gpioPWM(RIGHT_PWM, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

