#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define LUX_THRESHOLD 150.0
#define RELAY_GPIO 23
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library and I2C connection
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially turn off the relay

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Reads the lux value from the BH1750 sensor
float read_lux() {
    char buf[2];
    int result;

    // Send the measurement command (0x10 for continuous high-resolution mode)
    buf[0] = 0x10;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        log_data(-1.0, -1); // Log error
        return -1.0; // Indicate error
    }

    // Delay for measurement (at least 180ms)
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // pigpioDelay takes microseconds

    // Read the two bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read error: %d\n", result);
        log_data(-1.0, -1); // Log error
        return -1.0; // Indicate error
    }

    // Convert the two bytes to a lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2; // BH1750 datasheet conversion

    return lux;
}

// Controls the relay (turns it on or off)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Logs the lux value and relay state to the log file
void log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Turn off the relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Grow lamp control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            int relay_state = (lux < LUX_THRESHOLD) ? 1 : 0;
            control_relay(relay_state);
            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(500 * 1000); // Check every 500ms
    }

    cleanup();
    return 0;
}

