#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define servo positions
#define LOCK_POSITION 1000
#define UNLOCK_POSITION 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to set the servo pulse width
int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d). Must be between %d and %d.\n", pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1; // Indicate an error
    }
    gpioServo(SERVO_PIN, pulse_width);
    return 0; // Indicate success
}

// Function to lock the door
int lock_door() {
    printf("Locking door...\n");
    if (set_servo_pulse_width(LOCK_POSITION) != 0) {
        return -1; // Indicate an error
    }
    return 0;
}

// Function to unlock the door
int unlock_door() {
    printf("Unlocking door...\n");
    if (set_servo_pulse_width(UNLOCK_POSITION) != 0) {
        return -1; // Indicate an error
    }
    return 0;
}

// Function to handle button presses
int handle_button_press(int button_pin) {
    int button_state = gpioRead(button_pin);
    if (button_state == 0) { // Active-low
        printf("Button pressed!\n");
        if (set_servo_pulse_width(LOCK_POSITION) != 0) {
            return -1; // Indicate an error
        } else {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            if (set_servo_pulse_width(UNLOCK_POSITION) != 0) {
                return -1; // Indicate an error
            } else {
                return 0; // Indicate success
            }
        }
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors for the buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (handle_button_press(LOCK_BUTTON_PIN) != 0) {
            fprintf(stderr, "Error handling button press.\n");
        }
        if (handle_button_press(UNLOCK_BUTTON_PIN) != 0) {
            fprintf(stderr, "Error handling button press.\n");
        }
        gpioDelay(10000); // Check buttons every 10ms
    }

    // Clean up and exit
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    printf("Program terminated.\n");
    return 0;
}

