#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO lines for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define GPIO lines for the driver circuits
#define DRIVER1_GPIO 22
#define DRIVER2_GPIO 23

// Define GPIO lines for the flyback diodes
#define FLYBACK1_GPIO 24
#define FLYBACK2_GPIO 25

// Define the duration of the pulse in milliseconds
#define PULSE_DURATION_MS 200

// Define the delay between pulses in milliseconds
#define DELAY_MS 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nCaught signal %d, stopping motors and cleaning up...\n", sig);
        program_running = 0;
    }
}

// Function to request a GPIO line for output
int request_gpio_output(gpiod_line_t *line, const char *consumer) {
    int ret = gpiod_line_request_output(line, consumer, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %d\n", line->line, ret);
        return -1;
    }
    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(gpiod_line_t *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d to value %d: %d\n", line->line, value, ret);
        return -1;
    }
    return 0;
}

// Function to release a GPIO line
int release_gpio(gpiod_line_t *line) {
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %d\n", line->line, ret);
        return -1;
    }
    return 0;
}

// Function to pulse a motor
int pulse_motor(gpiod_line_t *motor_line, gpiod_line_t *driver_line, gpiod_line_t *flyback_line, int duration_ms) {
    int ret;

    // Set driver line HIGH
    ret = set_gpio_value(driver_line, 1);
    if (ret < 0) return -1;

    // Set flyback diode line HIGH
    ret = set_gpio_value(flyback_line, 1);
    if (ret < 0) {
        release_gpio(driver_line);
        return -1;
    }

    // Delay for the pulse duration
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = duration_ms * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&ts, NULL);

    // Set driver line LOW
    ret = set_gpio_value(driver_line, 0);
    if (ret < 0) return -1;

    // Set flyback diode line LOW
    ret = set_gpio_value(flyback_line, 0);
    if (ret < 0) {
        release_gpio(driver_line);
        return -1;
    }

    return 0;
}

int main() {
    gpiod_line_t motor1_line, motor2_line, driver1_line, driver2_line, flyback1_line, flyback2_line;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = DELAY_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", chip->name);
        return 1;
    }

    // Get the GPIO lines
    motor1_line = gpiod_chip_get_line(chip, MOTOR1_GPIO);
    motor2_line = gpiod_chip_get_line(chip, MOTOR2_GPIO);
    driver1_line = gpiod_chip_get_line(chip, DRIVER1_GPIO);
    driver2_line = gpiod_chip_get_line(chip, DRIVER2_GPIO);
    flyback1_line = gpiod_chip_get_line(chip, FLYBACK1_GPIO);
    flyback2_line = gpiod_chip_get_line(chip, FLYBACK2_GPIO);

    if (!motor1_line || !motor2_line || !driver1_line || !driver2_line || !flyback1_line || !flyback2_line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    if (request_gpio_output(&motor1_line, "motor1") < 0 ||
        request_gpio_output(&motor2_line, "motor2") < 0 ||
