// Define GPIO lines for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define GPIO lines for the driver circuits
#define DRIVER1_GPIO 22
#define DRIVER2_GPIO 23

// Define GPIO lines for the flyback diodes
#define FLYBACK1_GPIO 24
#define FLYBACK2_GPIO 25

// Define the duration of the pulse in milliseconds
#define PULSE_DURATION_MS 200

// Define the delay between pulses in milliseconds
#define DELAY_MS 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nCaught signal %d, stopping motors and cleaning up...\n", sig);
        program_running = 0;
    }
}

// Function to request a GPIO line for output
int request_gpio_output(gpiod_line_t *line, const char *consumer) {
    int ret = gpiod_line_request_output(line, consumer, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %d\n", line->line, ret);
        return -1;
    }
    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(gpiod_line_t *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d to value %d: %d\n", line->line, value, ret);
        return -1;
    }
    return 0;
}

// Function to release a GPIO line
int release_gpio(gpiod_line_t *line) {
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %d\n", line->line, ret);
        return -1;
    }
    return 0;
}

// Function to pulse a motor
int pulse_motor(gpiod_line_t *motor_line, gpiod_line_t *driver_line, gpiod_line_t *flyback_line, int duration_ms) {
    int ret;

    // Set driver line HIGH
    ret = set_gpio_value(driver_line, 1);
    if (ret < 0) return -1;

    // Set flyback diode line HIGH
    ret = set_gpio_value(flyback_line, 1);
    if (ret < 0) {
        release_gpio(driver_line);
        return -1;
    }

    // Delay for the pulse duration
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = duration_ms * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&ts, NULL);

    // Set driver line LOW
    ret = set_gpio_value(driver_line, 0);
    if (ret < 0) return -1;

    // Set flyback diode line LOW
    ret = set_gpio_value(flyback_line, 0);
    if (ret < 0) {
        release_gpio(driver_line);
        return -1;
    }

    return 0;
}

