    if (request_gpio_output(&motor1_line, "motor1") < 0 ||
        request_gpio_output(&motor2_line, "motor2") < 0 ||
        request_gpio_output(&driver1_line, "driver1") < 0 ||
        request_gpio_output(&driver2_line, "driver2") < 0 ||
        request_gpio_output(&flyback1_line, "flyback1") < 0 ||
        request_gpio_output(&flyback2_line, "flyback2") < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Pulse motor 1
        if (pulse_motor(&motor1_line, &driver1_line, &flyback1_line, PULSE_DURATION_MS) < 0) {
            break;
        }

        // Pulse motor 2
        if (pulse_motor(&motor2_line, &driver2_line, &flyback2_line, PULSE_DURATION_MS) < 0) {
            break;
