#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>
#include <zmq.h>
#include <errno.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://localhost:5555"

// Define alarm duration (seconds)
#define ALARM_DURATION 1

// Define sound sensor polling interval (milliseconds)
#define POLLING_INTERVAL 10

// Global variables
static volatile int running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *sound_sensor_line = NULL;
static struct gpiod_line *alarm_led_line = NULL;
static struct gpiod_line *gpio_chip_line = NULL; // Dummy line for GPIO chip
static void *context = NULL;
static void *subscriber = NULL;
static pthread_t sound_sensor_thread;
static pthread_t alarm_node_thread;

// Function prototypes
int gpio_init(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int gpio_set_direction(int pin, const char *direction);
int gpio_get_line(struct gpiod_chip *chip, const char *consumer, struct gpiod_line **line);
int gpio_get_chip(struct gpiod_chip **chip);
void *sound_sensor_thread_func(void *arg);
void *alarm_node_thread_func(void *arg);
int publish_alert(const char *message);
int subscribe_alert(void *arg);
void signal_handler(int sig);
void cleanup(void);

// GPIO initialization function
int gpio_init(int pin, const char *direction) {
    struct gpiod_line *line = NULL;
    int ret;

    if (gpio_get_line(gpio_chip, "consumer", &line) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO line for pin %d", pin);
        return -1;
    }

    ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set direction for GPIO pin %d: %s", pin, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// GPIO read function
int gpio_read(int pin) {
    int value = gpiod_line_get_value(gpio_chip_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read GPIO pin %d: %s", pin, strerror(-value));
        return -1;
    }
    return value;
}

// GPIO write function
int gpio_write(int pin, int value) {
    int ret = gpiod_line_set_value(gpio_chip_line, value);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to write value %d to GPIO pin %d: %s", value, pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    int ret = gpiod_line_set_direction(gpio_chip_line, direction);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set direction for GPIO pin %d: %s", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// GPIO get line function
int gpio_get_line(struct gpiod_chip *chip, const char *consumer, struct gpiod_line **line) {
    int ret;
    ret = gpiod_chip_get_line(chip, consumer, line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to get GPIO line for consumer %s: %s", consumer, strerror(-ret));
        return -1;
    }
    return 0;
}

// GPIO get chip function
int gpio_get_chip(struct gpiod_chip **chip) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (*chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Sound sensor thread function
void *sound_sensor_thread_func(void *arg) {
    (void)arg; // Suppress unused parameter warning
    int sound_detected;
    char message[256];
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    while (running) {
        sound_detected = gpio_read(SOUND_SENSOR_PIN);
        if (sound_detected < 0) {
            syslog(LOG_ERR, "Error reading sound sensor, exiting thread.");
            break;
        }

        if (sound_detected == 0) { // Logic low indicates sound detected
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            snprintf(message, sizeof(message), "%s: Sound detected!", timestamp);
            publish_alert(message);
        }
        usleep(POLLING_INTERVAL * 1000); // Sleep for polling interval
    }
    cleanup();
    pthread_exit(NULL);
}

// Alarm node thread function
void *alarm_node_thread_func(void *arg) {
    (void)arg; // Suppress unused parameter warning
    char *message = NULL;
    int ret;

    while (running) {
        ret = zmq_recv(subscriber, &message, sizeof(message) - 1, 0);
        if (ret > 0) {
            message[ret] = '\0'; // Null-terminate the received message
            syslog(LOG_INFO, "Received alert: %s", message);
            if (gpio_write(ALARM_LED_PIN, 1) == 0) {
                sleep(ALARM_DURATION);
                gpio_write(ALARM_LED_PIN, 0);
            } else {
                syslog(LOG_ERR, "Failed to activate alarm LED.");
            }
            zmq_free(message);
        } else if (ret == 0) {
            syslog(LOG_INFO, "No message received.");
        } else {
            syslog(LOG_ERR, "Error receiving message: %s", zmq_strerror(ret));
        }
        usleep(100000); // Sleep for 100ms
    }
    cleanup();
    pthread_exit(NULL);
}

// Publish alert function
int publish_alert(const char *message) {
    zmq_msg_t message;
    int ret;

    zmq_msg_init_size(&message, strlen(message));
    memcpy(zmq_msg_data(&message), message, strlen(message));

    ret = zmq_msg_send(&message, context, ZMQ_SNDMORE);
    if (ret == -1) {
        syslog(LOG_ERR, "Failed to send message: %s", zmq_strerror(ret));
        zmq_msg_close(&message);
        return -1;
    }

    ret = zmq_msg_send(&message, context, 0);
    if (ret == -1) {
        syslog(LOG_ERR, "Failed to send message: %s", zmq_strerror(ret));
        zmq_msg_close(&message);
        return -1;
    }

    zmq_msg_close(&message);
    return 0;
}

// Subscribe alert function
int subscribe_alert(void *arg) {
    (void)arg; // Suppress unused parameter warning
    int ret;
    char *buffer = NULL;
    int buffer_size = 0;

    while (running) {
        ret = zmq_recv(subscriber, &buffer, 0, ZMQ_DONTWAIT);
        if (ret > 0) {
            syslog(LOG_INFO, "Received message: %s", buffer);
            buffer_size = ret;
        } else if (ret == 0) {
            // No message received, sleep for a short interval
            usleep(10000); // 10ms
        } else {
            syslog(LOG_ERR, "Error receiving message: %s", zmq_strerror(ret));
            break;
        }
    }

    zmq_free(buffer);
    cleanup();
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Cleanup function
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");

    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (gpio_chip_line) {
        gpiod_line_release(gpio_chip_line);
    }
    if (context) {
        zmq_close(context);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    closelog();
}

int main(int argc, char *argv[]) {
    int mode = 0;
    int ret;

    openlog("sound_alarm", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_get_chip(&gpio_chip) < 0) {
        syslog(LOG_ERR, "GPIO initialization failed.");
        return 1;
    }

    if (gpio_init(SOUND_SENSOR_PIN, "in") < 0) {
        syslog(LOG_ERR, "Failed to initialize sound sensor pin.");
        cleanup();
        return 1;
    }

    if (gpio_init(ALARM_LED_PIN, "out") < 0) {
        syslog(LOG_ERR, "Failed to initialize alarm LED pin.");
        cleanup();
        return 1;
    }

    // Initialize ZeroMQ
    context = zmq_ctx_new();
    if (!context) {
        syslog(LOG_ERR, "Failed to create ZeroMQ context: %s", zmq_strerror(errno));
        cleanup();
        return 1;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        syslog(LOG_ERR, "Failed to create ZeroMQ socket: %s", zmq_strerror(errno));
        cleanup();
        return 1;
    }

    ret = zmq_connect(subscriber, ZMQ_ENDPOINT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to connect ZeroMQ socket: %s", zmq_strerror(ret));
        cleanup();
        return 1;
    }

    // Create threads
    if (pthread_create(&sound_sensor_thread, NULL, sound_sensor_thread_func, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create sound sensor thread.");
        cleanup();
        return 1;
    }

    if (pthread_create(&alarm_node_thread, NULL, alarm_node_thread_func, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create alarm node thread.");
        cleanup();
        return 1;
    }

    // Wait for threads to finish
    pthread_join(sound_sensor_thread, NULL);
    pthread_join(alarm_node_thread, NULL);

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

