#define MIN_PULSE_LENGTH 500 // microseconds
#define MAX_PULSE_LENGTH 2500 // microseconds

// NEC Timing Constants (in microseconds)
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 562
#define NEC_ZERO_SPACE 1690
#define NEC_ONE_SPACE 562

