static volatile int pulse_count = 0;
static volatile unsigned int pulse_times[MAX_PULSES];
static volatile int pulse_index = 0;
static volatile int nec_address = 0;
static volatile int nec_command = 0;
static volatile int nec_checksum = 0;
static volatile int nec_extended = 0;
static volatile int ir_data_ready = 0;
static struct mosquitto *mqtt_client = NULL;
static int pigpio_initialized = 0;

// Function Prototypes
void ir_callback(int gpio, int level, uint32_t tick, void *user);
int decode_nec(unsigned int *pulse_times, int pulse_count);
void validate_checksum(unsigned int address, unsigned int command);
void publish_mqtt(unsigned int address, unsigned int command);
void signal_handler(int signal);
int init_mqtt();
void cleanup();

// NEC Decoding Function
int decode_nec(unsigned int *pulse_times, int pulse_count) {
    if (pulse_count < 68) {
        syslog(LOG_ERR, "Pulse count too short: %d", pulse_count);
        return -1; // Not enough pulses
    }

    // Check for NEC header
    if (pulse_times[0] < NEC_HEADER_MARK - 500 || pulse_times[0] > NEC_HEADER_MARK + 500 ||
        pulse_times[1] < NEC_HEADER_SPACE - 500 || pulse_times[1] > NEC_HEADER_SPACE + 500) {
        syslog(LOG_ERR, "Invalid NEC header: %u %u", pulse_times[0], pulse_times[1]);
        return -1; // Invalid header
    }

    // Decode address (8 bits)
    for (int i = 2; i < 10; i++) {
        if (pulse_times[2 * i] < NEC_BIT_MARK - 500 || pulse_times[2 * i] > NEC_BIT_MARK + 500) {
            syslog(LOG_ERR, "Invalid bit mark: %u", pulse_times[2 * i]);
            return -1;
        }
        if (pulse_times[2 * i + 1] > NEC_ZERO_SPACE - 500) {
            nec_address |= (1 << (i - 2));
        }
    }

    // Decode command (8 bits)
    for (int i = 10; i < 18; i++) {
        if (pulse_times[2 * i] < NEC_BIT_MARK - 500 || pulse_times[2 * i] > NEC_BIT_MARK + 500) {
            syslog(LOG_ERR, "Invalid bit mark: %u", pulse_times[2 * i]);
            return -1;
        }
        if (pulse_times[2 * i + 1] > NEC_ONE_SPACE - 500) {
            nec_command |= (1 << (i - 10));
        }
    }

    // Decode inverted address (8 bits)
    for (int i = 18; i < 26; i++) {
        if (pulse_times[2 * i] < NEC_BIT_MARK - 500 || pulse_times[2 * i] > NEC_BIT_MARK + 500) {
            syslog(LOG_ERR, "Invalid bit mark: %u", pulse_times[2 * i]);
            return -1;
        }
        if (pulse_times[2 * i + 1] > NEC_ZERO_SPACE - 500) {
            nec_address |= (1 << (i - 18));
        }
    }

    // Decode inverted command (8 bits)
    for (int i = 26; i < 34; i++) {
        if (pulse_times[2 * i] < NEC_BIT_MARK - 500 || pulse_times[2 * i] > NEC_BIT_MARK + 500) {
            syslog(LOG_ERR, "Invalid bit mark: %u", pulse_times[2 * i]);
            return -1;
        }
        if (pulse_times[2 * i + 1] > NEC_ONE_SPACE - 500) {
            nec_command |= (1 << (i - 26));
        }
    }

    // Decode checksum (8 bits)
    for (int i = 34; i < 42; i++) {
        if (pulse_times[2 * i] < NEC_BIT_MARK - 500 || pulse_times[2 * i] > NEC_BIT_MARK + 500) {
            syslog(LOG_ERR, "Invalid bit mark: %u", pulse_times[2 * i]);
            return -1;
        }
        if (pulse_times[2 * i + 1] > NEC_ZERO_SPACE - 500) {
            nec_checksum |= (1 << (i - 34));
        }
    }

    // Validate checksum
    validate_checksum(nec_address, nec_command);

    return 0; // Success
}

// Checksum Validation Function
void validate_checksum(unsigned int address, unsigned int command) {
    unsigned int inv_address = ~address;
    unsigned int inv_command = ~command;

    unsigned int inv_checksum = 0;
    for (int i = 0; i < 8; i++) {
        inv_checksum |= ((inv_address >> i) & 1) << (7 - i);
    }

    unsigned int calculated_checksum = 0;
    for (int i = 0; i < 8; i++) {
        calculated_checksum |= ((address >> i) & 1) << (7 - i);
    }

    if (calculated_checksum != inv_checksum) {
        syslog(LOG_ERR, "Checksum mismatch: calculated=%u, received=%u", calculated_checksum, inv_checksum);
    }
}

// MQTT Publishing Function
void publish_mqtt(unsigned int address, unsigned int command) {
    char payload[50];
    snprintf(payload, sizeof(payload), "{\"address\":%u,\"command\":%u}", address, command);

    int ret = mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
    }
}

// Signal Handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    cleanup();
    exit(0);
}

// MQTT Initialization Function
int init_mqtt() {
    mosquitto_lib_init();
