    }

    if (mosquitto_connect(mqtt_client, MQTT_BROKER, MQTT_PORT, 60)) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mqtt_client);
        return -1;
    }

    mosquitto_loop_start(mqtt_client);
    return 0;
}

// Cleanup Function
void cleanup() {
    ir_data_ready = 0; // Disable callback
    if (mqtt_client) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_loop_stop(mqtt_client, false);
        mosquitto_destroy(mqtt_client);
    }
    mosquitto_lib_cleanup();
    if (pigpio_initialized) {
        gpioTerminate();
    }
    closelog();
}

