#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <fcntl.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SLEEP_SECONDS 1

// Sensor addresses
const int sensor_addresses[] = {0x23, 0x24, 0x25, 0x26};
const int num_sensors = sizeof(sensor_addresses) / sizeof(sensor_addresses[0]);

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fds[4]; // Array to hold file descriptors for each sensor
int udp_socket;

// Function prototypes
int open_i2c_device(const char *bus, int address);
int set_i2c_slave(int fd, int address);
int write_i2c(int fd, unsigned char data);
int read_i2c(int fd, unsigned char *data, int count);
float read_bh1750(int fd);
void format_data(float *data, char *buffer, size_t buffer_size);
int send_udp_multicast(const char *data, const char *address, int port);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal received (%d). Terminating...\n", signum);
}

// Function to open an I2C device
int open_i2c_device(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to set the I2C slave address
int set_i2c_slave(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to write to an I2C device
int write_i2c(int fd, unsigned char data) {
    unsigned char buf[2];
    buf[0] = 0x00; // Dummy byte for writing
    buf[1] = data;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read from an I2C device
int read_i2c(int fd, unsigned char *data, int count) {
    if (write(fd, data, count) != count) {
        perror("Error writing to I2C device for read");
        return -1;
    }
    if (read(fd, data, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

