#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LOG_FILE "airflow_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_setup(const char *bus, int address);
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data);
float convert_to_slpm(uint16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// I2C setup function
int i2c_setup(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }

    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing data");
        return -1;
    }

    return 0;
}

// Convert raw flow to SLPM
float convert_to_slpm(uint16_t raw_flow) {
    return (raw_flow - 3277) * FLOW_SCALE_FACTOR;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        perror("Log file is not open");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Setup signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    printf("Airflow sensor data logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        uint8_t data[2];
        uint16_t raw_flow;
        float flow_rate;

        // Read flow data
        if (i2c_read_bytes(i2c_fd, 0x00, data, 2) == 0) {
            raw_flow = (data[0] << 8) | data[1];
            flow_rate = convert_to_slpm(raw_flow);

            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        } else {
            fprintf(stderr, "Error reading flow data. Retrying...\n");
        }

        sleep(1); // Sample once per second
    }

    // Cleanup (should not reach here if signal handler works)
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

