#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define WHO_AM_I 0x24
#define ENABLE 0x80
#define CFG6 0xAF
#define SP_EN 0x73
#define F1 0x60
#define F2 0x61
#define F3 0x62
#define F4 0x63
#define F5 0x64
#define F6 0x65
#define F7 0x66
#define F8 0x67
#define Clear 0x68
#define NIR 0x69

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t f1;
    uint16_t f2;
    uint16_t f3;
    uint16_t f4;
    uint16_t f5;
    uint16_t f6;
    uint16_t f7;
    uint16_t f8;
    uint16_t clear;
    uint16_t nir;
} sensor_data_t;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
int i2c_read_word(int fd, uint8_t reg);
int as7341_init(int fd);
int as7341_read_spectral_data(int fd, sensor_data_t *data);
float calculate_lux(sensor_data_t data);
int log_data(sensor_data_t data, float lux);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return value;
}

// I2C write word function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;       // LSB
    if (write(fd, buf, 3) != 3) {
        perror("I2C write (word) failed");
        return -1;
    }
    return 0;
}

// I2C read word function
int i2c_read_word(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// AS7341 initialization function
int as7341_init(int fd) {
    int who_am_i;

    // Verify WHO_AM_I register
    who_am_i = i2c_read_word(fd, WHO_AM_I);
    if (who_am_i != 0x19) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%X, expected 0x19\n", who_am_i);
        return -1;
    }

    // Enable sensor
    if (i2c_write_byte(fd, ENABLE, 0x01) != 0) {
        return -1;
    }

    // Configure SMUX for spectral readings
    if (i2c_write_byte(fd, CFG6, 0x03) != 0) {
        return -1;
    }

    // Enable spectral measurement
    if (i2c_write_byte(fd, SP_EN, 0x01) != 0) {
        return -1;
    }

    return 0;
}

// AS7341 read spectral data function
int as7341_read_spectral_data(int fd, sensor_data_t *data) {
    data->f1 = i2c_read_word(fd, F1);
    data->f2 = i2c_read_word(fd, F2);
    data->f3 = i2c_read_word(fd, F3);
    data->f4 = i2c_read_word(fd, F4);
    data->f5 = i2c_read_word(fd, F5);
    data->f6 = i2c_read_word(fd, F6);
    data->f7 = i2c_read_word(fd, F7);
    data->f8 = i2c_read_word(fd, F8);
    data->clear = i2c_read_word(fd, Clear);
    data->nir = i2c_read_word(fd, NIR);

    return 0;
}

// Calculate lux approximation (simplified)
float calculate_lux(sensor_data_t data) {
    // This is a placeholder.  A real implementation would use calibration data
    // and a more sophisticated algorithm.
    float lux = 0.0f;
    // Example: Sum the F1-F8 values and divide by a scaling factor
    float sum = data.f1 + data.f2 + data.f3 + data.f4 + data.f5 + data.f6 + data.f7 + data.f8;
    lux = sum / 100.0f; // Example scaling factor
    return lux;
}

// Log data to CSV file
int log_data(sensor_data_t data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

