#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define NUM_BYTES_TO_READ 6
#define G_PER_LSB 0.000244f
#define MAX_RETRIES 3
#define BACKOFF_DELAY_NS 10000000 // 10 ms

// Sensor Registers
#define REG_X_L 0x28
#define REG_X_H 0x29
#define REG_Y_L 0x2A
#define REG_Y_H 0x2B
#define REG_Z_L 0x2C
#define REG_Z_H 0x2D

// Global variables
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char *filename = DEFAULT_FILENAME;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x_g;
    float y_g;
    float z_g;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *bus, int address);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, sensor_data_t *data);
float convert_to_g(int16_t raw);
int log_data(FILE *fp, sensor_data_t data);
int log_error(const char *message);
void signal_handler(int sig);
void cleanup();

// I2C setup function
int i2c_setup(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        log_error("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        log_error("Failed to write register address for read");
        return -1;
    }

    if (read(fd, data, len) != len) {
        log_error("Failed to read data from I2C");
        return -1;
    }

    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        log_error("Failed to write byte to I2C");
        return -1;
    }

    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buffer[NUM_BYTES_TO_READ];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_bytes(fd, REG_X_L, buffer, NUM_BYTES_TO_READ) != 0) {
        log_error("Failed to read sensor data");
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    data->x_g = convert_to_g(raw_x);
    data->y_g = convert_to_g(raw_y);
    data->z_g = convert_to_g(raw_z);

    return 0;
}

// Convert raw data to g
float convert_to_g(int16_t raw) {
    return raw * G_PER_LSB;
}

// Log data to CSV file
int log_data(FILE *fp, sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x_g, data.y_g, data.z_g);
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Log error messages to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);
    perror(message); // Also print to stderr
    return -1;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    int opt;
    // Default values
    i2c_address = DEFAULT_I2C_ADDRESS;
    interval = DEFAULT_INTERVAL;
    filename = DEFAULT_FILENAME;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = atoi(optarg);
                if (interval <= 0) {
                    fprintf(stderr, "Invalid interval. Using default value (1 second).\n");
                    interval = DEFAULT_INTERVAL;
                }
                break;
            case 'f':
                filename = strdup(optarg); // Duplicate the string to avoid issues with static storage
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        perror("Failed to open error log file");
        return EXIT_FAILURE;
    }

    // Open data log file
    data_file = fopen(filename, "w");
    if (data_file == NULL) {
        log_error("Failed to open data log file");
        fclose(error_file);
        return EXIT_FAILURE;
    }

    // Write CSV header
    fprintf(data_file, "timestamp,x_g,y_g,z_g\n");

    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, i2c_address);
    if (i2c_fd < 0) {
        log_error("I2C initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            log_data(data_file, sensor_data);
        } else {
            log_error("Failed to read sensor data");
        }

        usleep(interval * 1000000); // Sleep for the specified interval
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

