#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1
#define SLEEP_SECONDS 1

int i2c_fd = -1;
int udp_socket = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (udp_socket != -1) {
            close(udp_socket);
        }
        exit(0);
    }
}

// Function to initialize the BH1750 sensor
int init_bh1750() {
    unsigned char buf[2];
    int retries = 3;

    // Power on the sensor
    buf[0] = 0x01;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to power on BH1750 (attempt %d/%d)\n", 3 - retries, retries);
        return -1;
    }
    usleep(100000); // Wait for power-up (100ms)

    // Set continuous high-resolution mode
    buf[0] = 0x10;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to set BH1750 mode (attempt %d/%d)\n", 3 - retries, retries);
        return -1;
    }
    usleep(100000); // Wait for mode change (100ms)

    return 0;
}

// Function to read the raw sensor value
int read_sensor_value(unsigned short *raw_value) {
    unsigned char buf[2];
    int retries = 3;

    // Read 2 bytes from the sensor
    buf[0] = 0x00; // Dummy byte to trigger read
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to trigger read (attempt %d/%d)\n", 3 - retries, retries);
        return -1;
    }

    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read sensor value (attempt %d/%d)\n", 3 - retries, retries);
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send the lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    char buffer[32];
    int ttl = TTL;

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Set TTL for multicast
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Convert lux value to string
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    // Send the data
    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending data");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    return 0;
}

int main() {
    unsigned short raw_value;
    float lux_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_bh1750() != 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor value
        if (read_sensor_value(&raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Send over UDP multicast
            if (send_udp_multicast(lux_value) != 0) {
                fprintf(stderr, "Failed to send UDP multicast.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor value.\n");
        }

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    // Cleanup (should not reach here in normal execution due to the signal handler)
    close(i2c_fd);
    close(udp_socket);
    return 0;
}

