#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_SIZE 4
#define TLV_TYPE_SIZE 2
#define TLV_LENGTH_SIZE 4
#define MAX_FRAME_SIZE 4096 // Adjust as needed
#define MAX_OBJECTS 100

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    int object_index;
    float range_m;
    float velocity_mps;
} RadarObject;

// Function prototypes
int initialize_uart();
int read_uart_data(char *buffer, int max_len);
int synchronize_tlv(char *buffer, int len);
int extract_tlv(char *buffer, int len, RadarObject *objects, int max_objects);
void validate_tlv(char *buffer, int len);
void write_data_to_csv(FILE *fp, RadarObject *objects, int num_objects);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    fprintf(stderr, "UART initialized on %s at %d baud\n", UART_DEVICE, BAUD_RATE);
    return 0;
}

// Read data from UART
int read_uart_data(char *buffer, int max_len) {
    int bytes_read = serRead(uart_handle, buffer, max_len);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    } else if (bytes_read == 0) {
        // Timeout or no data available
        return 0;
    }
    return bytes_read;
}

// Synchronize on TLV magic word
int synchronize_tlv(char *buffer, int len) {
    if (len < MAGIC_WORD_SIZE) return 0; // Not enough data to check magic word

    unsigned char magic_word[MAGIC_WORD_SIZE];
    memcpy(magic_word, buffer, MAGIC_WORD_SIZE);

    // Check if the magic word is correct (little-endian)
    if (magic_word[0] != 0x04 || magic_word[1] != 0x02 ||
        magic_word[2] != 0x06 || magic_word[3] != 0x03 ||
        magic_word[3] != 0x05 || magic_word[2] != 0x08 ||
        magic_word[1] != 0x07 || magic_word[0] != 0x07) {
        fprintf(stderr, "Error: Invalid magic word: 0x%02X 0x%02X 0x%02X 0x%02X\n",
                magic_word[0], magic_word[1], magic_word[2], magic_word[3]);
        return -1;
    }

    fprintf(stderr, "Synchronized on TLV magic word: 0x%02X 0x%02X 0x%02X 0x%02X\n",
            magic_word[0], magic_word[1], magic_word[2], magic_word[3]);

    return len - MAGIC_WORD_SIZE;
}

// Extract TLV data and validate
int extract_tlv(char *buffer, int len, RadarObject *objects, int max_objects) {
    int offset = 0;
    int object_count = 0;
    int i;

    while (offset < len - TLV_LENGTH_SIZE && object_count < max_objects) {
        unsigned char tlv_type[TLV_TYPE_SIZE];
        memcpy(tlv_type, buffer + offset, TLV_TYPE_SIZE);

        // Extract TLV type (2 bytes) and length (4 bytes)
        int tlv_type_int = (tlv_type[0] << 8) | tlv_type[1];
        int tlv_length_int = (buffer[offset + TLV_LENGTH_SIZE] << 24) |
                             (buffer[offset + TLV_LENGTH_SIZE + 1] << 16) |
                             (buffer[offset + TLV_LENGTH_SIZE + 2] << 8)    |
                             buffer[offset + TLV_LENGTH_SIZE + 3];

        // Extract TLV payload
        char *payload = buffer + offset + TLV_LENGTH_SIZE;
        int payload_len = tlv_length_int;

        // Validate TLV length
        if (payload_len > len - offset - TLV_LENGTH_SIZE) {
            fprintf(stderr, "Error: TLV length exceeds buffer size\n");
            return -1;
        }

        // Process TLV type (example: assuming type 1 is object data)
        if (tlv_type[0] == 1) {
            // Extract object data (assuming range and velocity are floats)
            float range = *(float *)(payload + 4);
            float velocity = *(float *)(payload + 8);

            // Create RadarObject
            objects[object_count].object_index = object_count;
            objects[object_count].range_m = (int)range;
            objects[object_count].velocity_mps = (int)velocity;

            object_count++;
        } else {
            fprintf(stderr, "Warning: Unknown TLV type: 0x%02X\n", tlv_type[0]);
        }

        offset += TLV_LENGTH_SIZE + payload_len;
    }

    return object_count;
}

// Validate TLV payload (example: check if range is within reasonable bounds)
void validate_tlv(char *buffer, int len) {
    // Implement your TLV validation logic here
    // For example, check if range is within a certain range
    // and velocity is within a certain range.
    // This is a placeholder and should be replaced with actual validation.
    // For now, we just print a message.
    fprintf(stderr, "TLV payload validated\n");
}

// Write data to CSV file
void write_data_to_csv(FILE *fp, RadarObject *objects, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s", timestamp);
    for (int i = 0; i < num_objects; i++) {
        fprintf(fp, ",%d,%.2f,%.2f\n", i + 1, objects[i].range_m, objects[i].velocity_mps);
    }
    fprintf(fp, "\n");
    fflush(fp);
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
        fprintf(stderr, "UART closed\n");
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        fprintf(stderr, "CSV file closed\n");
    }
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for writing
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    char buffer[MAX_FRAME_SIZE];
    RadarObject objects[MAX_OBJECTS];
    int num_objects;

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        int bytes_read = read_uart_data(buffer, MAX_FRAME_SIZE);
        if (bytes_read > 0) {
            int offset = 0;
            int tlv_length = 0;

            // Synchronize on TLV magic word
            while (offset < bytes_read - MAGIC_WORD_SIZE && tlv_length < MAX_FRAME_SIZE - offset) {
                int sync_result = synchronize_tlv(buffer, bytes_read - offset);
                if (sync_result > 0) {
                    tlv_length += sync_result;
                    offset += sync_result;
                } else {
                    break; // Malformed frame or no more data
                }
            }

            if (offset < bytes_read) {
                fprintf(stderr, "Warning: Incomplete frame received (%d bytes)\n", bytes_read);
            } else {
                // Extract TLV data
                num_objects = extract_tlv(buffer + offset, bytes_read - offset, objects, MAX_OBJECTS);

                // Validate TLV data
                validate_tlv(buffer + offset, bytes_read - offset);

                // Write data to CSV file
                write_data_to_csv(csv_file, objects, num_objects);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading UART data, retrying...\n");
            gpioDelay(100); // Wait before retrying
        }
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

