#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC 0
#define MAX_LINE_LENGTH 256

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int open_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return -1;
    }
    return fd;
}

int configure_uart(int fd, struct termios *options) {
    if (tcgetattr(fd, options) != 0) {
        perror("tcgetattr");
        return -1;
    }

    options->c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 8N1, no parity
    options->c_iflag = IGNPAR; // Ignore parity errors
    options->c_oflag = 0;
    options->c_lflag = 0; // Non-canonical mode

    // Set inter-byte timeout (IBT) to 0.5 seconds (500000 microseconds)
    struct termios ibt_options;
    if (tcgetattr(fd, &ibt_options) != 0) {
        perror("tcgetattr (ibt)");
        return -1;
    }
    ibt_options.c_cc[VMIN] = 0;  // Minimum number of characters to read
    ibt_options.c_cc[VTIME] = 500000; // Timeout in deciseconds (0.5 seconds)
    if (tcsetattr(fd, TCSANOW, &ibt_options) != 0) {
        perror("tcsetattr (ibt)");
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, options) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // No data available
        }
        perror("read");
        return -1; // Error
    } else {
        buffer[bytes_read] = '\0';
        return (int)bytes_read;
    }
}

int parse_line(const char *line, size_t line_len, float *range) {
    if (line_len < 10) {
        fprintf(stderr, "Invalid line length: %zu\n", line_len);
        return -1;
    }

    char *token = strtok(line, ",");
    if (token == NULL) {
        fprintf(stderr, "Invalid line format: %s\n", line);
        return -1;
    }

    char *timestamp = strtok(NULL, ",");
    if (timestamp == NULL) {
        fprintf(stderr, "Invalid line format: %s\n", line);
        return -1;
    }

    char *endptr;
    long timestamp_seconds = strtol(timestamp, &endptr, 10);
    if (*endptr != '\0' || timestamp_seconds < 0 || timestamp_seconds > 2147483647) {
        fprintf(stderr, "Invalid timestamp: %s\n", timestamp);
        return -1;
    }

    *range = strtof(token, &endptr);
    if (*endptr != '\0' || *range < 0.0 || *range > 100.0) {
        fprintf(stderr, "Invalid range value: %s\n", token);
        return -1;
    }

    return 0;
}

int main() {
    int uart_fd = -1;
    struct termios options;
    char line_buffer[MAX_LINE_LENGTH];
    float range;
    time_t timestamp;
    struct tm *timeinfo;
    char timestamp_str[20];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    if (configure_uart(uart_fd, &options) == -1) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART configured. Reading data from %s...\n", UART_DEVICE);

    while (program_running) {
        fd_set readfds;
        struct timeval timeout;

        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = TIMEOUT_USEC;

        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("select");
            break;
        } else if (select_result == 0) {
            // Timeout occurred
            continue;
        } else {
            // Data is available
            char *read_buffer = malloc(256);
            if (read_buffer == NULL) {
                perror("malloc");
                break;
            }

            int bytes_read = read_uart_data(uart_fd, read_buffer, 256);
            if (bytes_read > 0) {
                // Attempt to read the complete line
                int bytes_to_read = (int)strlen(line_buffer);
                int bytes_read_from_uart = read_uart_data(uart_fd, line_buffer + bytes_to_read, sizeof(line_buffer) - bytes_to_read);

                if (bytes_read_from_uart > 0) {
                    line_buffer[bytes_to_read + bytes_read_from_uart] = '\0';

                    if (parse_line(line_buffer, strlen(line_buffer), &range) == 0) {
                        // Get current timestamp
                        time(&timestamp);
                        timeinfo = localtime(&timestamp);
                        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

                        printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
                    }
                }
            }
            free(read_buffer);
        }
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

