#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define the serial port
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the sensor values
int read_sensors(int *left, int *middle, int *right) {
    *left = gpioRead(LEFT_SENSOR_PIN);
    *middle = gpioRead(MIDDLE_SENSOR_PIN);
    *right = gpioRead(RIGHT_SENSOR_PIN);
    return 0; // Indicate success
}

// Function to log sensor data with timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to check for emergency stop condition
void check_emergency_stop(int left, int middle, int right) {
    if (left == 0 && middle == 0 && right == 0) {
        char emergency_message[] = "EMERGENCY STOP!\n";
        int bytes_written = serialWrite(SERIAL_PORT, emergency_message, strlen(emergency_message));

        if (bytes_written < 0) {
            fprintf(stderr, "Error writing to serial port: %d\n", bytes_written);
        }
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the serial port
    int serial_fd = serialOpen(SERIAL_PORT, BAUD_RATE, 0); // 0 for no flow control
    if (serial_fd < 0) {
        fprintf(stderr, "Error opening serial port: %d\n", serial_fd);
        gpioTerminate(); // Clean up pigpio before exiting
        return 1; // Exit if serial port cannot be opened
    }

    int left_sensor_value, middle_sensor_value, right_sensor_value;

    // Main loop
    while (program_running) {
        // Read sensor values
        if (read_sensors(&left_sensor_value, &middle_sensor_value, &right_sensor_value) == 0) {
            // Log sensor data
            log_sensor_data(left_sensor_value, middle_sensor_value, right_sensor_value);

            // Check for emergency stop condition
            check_emergency_stop(left_sensor_value, middle_sensor_value, right_sensor_value);
        } else {
            fprintf(stderr, "Error reading sensors\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close the serial port
    serialClose(serial_fd);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

